void testBS014ProgramBareFormsPrepass() {
  std::printf("[selftest] --- BS-014 `program dir`/`program list`/bare `program drop` pre-pass ---\n");
  namespace fs = std::filesystem;
  std::string workdir = (fs::temp_directory_path() / "piet_native_selftest_bs014").u8string();
  std::error_code ec;
  fs::remove_all(workdir, ec);
  fs::create_directories(workdir, ec);

  // `program dir` / bare `program drop NAME` ARE handled at dispatch time
  // (dispatcher.cpp's own pre-pass) — with BS-014 fixed, the rest of the
  // do-file must run normally after them instead of being silently eaten.
  // BUG-923: the drop of an absent program is r(111) (Stata), so it is
  // captured here; the arm is about the capture pass not eating the file.
  for (const std::string& bareLine :
       {std::string("capture program drop nosuchprogram014"), std::string("program dir")}) {
    piet::SessionState session(workdir);
    std::string src = bareLine + "\nsysuse fatalities, clear\ngen bs014mark = 1\n";
    (void)piet::doexec::executeDoSource(src, session, piet::dispatch);
    check(session.hasData() && session.datastore()->has("bs014mark"),
          "BS-014: `" + bareLine + "` no longer swallows the rest of the do-file as a bogus "
          "program body (sysuse+gen after it still ran)");
  }

  // `program list` has NO dispatcher handler (an honest gap) — with BS-014
  // fixed, it reaches dispatch and is honestly rejected right there, instead
  // of the capture-pass silently eating the rest of the file with NO error
  // at all and no later line ever getting a chance to run.
  {
    piet::SessionState session(workdir);
    std::string src = std::string("program list") + "\nsysuse fatalities, clear\ngen bs014mark2 = 1\n";
    auto result = piet::doexec::executeDoSource(src, session, piet::dispatch);
    check(result.stoppedAtReason.has_value(),
          "BS-014: `program list` reaches dispatch and honestly halts there "
          "(not a silent no-op over the whole rest of the file)");
    check(session.programs.find("list") == session.programs.end(),
          "BS-014: `program list` was NOT captured as a bogus program named `list`");
  }

  fs::remove_all(workdir, ec);
}

void testBS015CaptureMultilineBlock() {
  std::printf("[selftest] --- BS-015 `capture { ... }` multi-line block ---\n");
  namespace fs = std::filesystem;
  std::string workdir = (fs::temp_directory_path() / "piet_native_selftest_bs015").u8string();
  std::error_code ec;
  fs::remove_all(workdir, ec);
  fs::create_directories(workdir, ec);

  // Success case: every line in the block runs, in order, and _rc == 0.
  {
    piet::SessionState session(workdir);
    std::string src =
        "capture {\n"
        "    sysuse fatalities, clear\n"
        "    gen bs015a = 1\n"
        "    gen bs015b = 2\n"
        "}\n";
    auto result = piet::doexec::executeDoSource(src, session, piet::dispatch);
    check(session.hasData() && session.datastore()->has("bs015a") && session.datastore()->has("bs015b"),
          "BS-015: every line inside `capture { ... }` actually ran (today: runs uncaptured, "
          "which happens to still work for an all-success body, but see the failure case below)");
    check(session.eval.locals.get("_rc", "") == "0",
          "BS-015: `capture { ... }` (fully successful body) sets _rc=0");
    check(!result.stoppedAtReason.has_value(),
          "BS-015: a successful `capture { ... }` block does not halt the enclosing do-file");
  }

  // Failure case: a bad line inside the block is swallowed (does NOT halt
  // the do-file), _rc == 111, lines after the failure inside the SAME block
  // do not run, and a line AFTER the closing brace still runs.
  // Mechanism (BUG-546 routes capture-block errors through eval::coarseRc):
  // the 111 comes from errors.cpp's "variable" + "not found" substring rule
  // matching the engine message `column not found: nosuchvariable_bs015`
  // ONLY because this identifier contains the word "variable". The engine's
  // generic `column not found: X` still maps to rc 1 (pinned by BS-100 and
  // the C1/N3 guard below) -- a REFUSAL-rc gap, not fixed here.
  {
    piet::SessionState session(workdir);
    std::string src =
        "capture {\n"
        "    sysuse fatalities, clear\n"
        "    regress nosuchvariable_bs015 spirits\n"
        "    gen bs015_never_reached = 1\n"
        "}\n"
        "gen bs015_after_block = 1\n";
    auto result = piet::doexec::executeDoSource(src, session, piet::dispatch);
    check(session.eval.locals.get("_rc", "") == "111",
          "BS-015: an error inside `capture { ... }` sets _rc=111 (variable not found; oracle "
          "w2_openbugs fe_unknown / bug483_484_control_oracle C1)");
    check(session.hasData(), "BS-015: lines BEFORE the failing line inside the block still ran");
    check(session.hasData() && !session.datastore()->has("bs015_never_reached"),
          "BS-015: lines AFTER the failing line inside the SAME block did not run");
    check(session.hasData() && session.datastore()->has("bs015_after_block"),
          "BS-015: the do-file CONTINUES past the capture block after it swallows the error "
          "(today, this error incorrectly runs uncaptured and halts the whole do-file instead)");
    check(!result.stoppedAtReason.has_value(),
          "BS-015: the enclosing do-file did not halt because of the captured error");
  }

  fs::remove_all(workdir, ec);
}

void testBUG116NestedCaptureBlock() {
  std::printf("[selftest] --- BUG-116 nested `capture` inside `capture { ... }` ---\n");
  namespace fs = std::filesystem;
  std::string workdir = (fs::temp_directory_path() / "piet_native_selftest_bug116").u8string();
  std::error_code ec;
  fs::remove_all(workdir, ec);
  fs::create_directories(workdir, ec);

  // A NESTED `capture` failing inside an outer `capture { ... }` block must
  // NOT be treated as an error escaping to the outer scope: the dispatcher
  // already tagged that error captured:true (BS-127, display-only), so the
  // outer block's own scan (runCaptureBlock) must key off the SAME halt
  // authority runBody/doexec use (stoppedAtLine), not a bare "any
  // type==error block" scan — the pre-fix bug. Correct behavior: the outer
  // block keeps running past the nested capture's line, and outer _rc stays
  // "0" (nothing actually escaped to this scope). BUG-1434: a bare capture
  // block prints none of its ordinary output (StataBE 19.5), so the marker is
  // a `noisily display`, which StataBE does print inside one.
  piet::SessionState session(workdir);
  std::string src =
      "capture {\n"
      "    sysuse fatalities, clear\n"
      "    capture noisily regress nosuchvariable_bug116 spirits\n"
      "    noisily display \"bug116_after_nested_marker\"\n"
      "}\n"
      "display \"bug116_after_block_marker\"\n";
  auto result = piet::doexec::executeDoSource(src, session, piet::dispatch);

  check(session.eval.locals.get("_rc", "") == "0",
        "BUG-116: outer `capture { ... }` block's _rc stays \"0\" — an already-captured NESTED "
        "capture's error must not pollute the outer scope's _rc, got _rc=" +
            session.eval.locals.get("_rc", "<unset>"));

  bool sawAfterNested = false;
  bool sawAfterBlock = false;
  for (const auto& b : result.blocks) {
    if (!b.is_object() || b.value("type", std::string()) != "display") continue;
    const std::string text = b.value("text", std::string());
    if (text == "bug116_after_nested_marker") sawAfterNested = true;
    if (text == "bug116_after_block_marker") sawAfterBlock = true;
  }
  check(sawAfterNested,
        "BUG-116: the line AFTER the nested capture, inside the SAME outer capture block, still "
        "ran and its output reached the transcript (pre-fix: the outer block wrongly halted "
        "right at the nested capture's already-caught error)");
  check(sawAfterBlock,
        "BUG-116: the do-file continues normally past the whole outer capture block");
  check(!result.stoppedAtReason.has_value(),
        "BUG-116: the do-file never halted — the nested capture's error was genuinely caught, "
        "twice over");

  fs::remove_all(workdir, ec);
}

void testBUG116NestedCaptureSingleLine() {
  std::printf("[selftest] --- BUG-116 class sweep: nested single-line `capture capture ...` ---\n");
  namespace fs = std::filesystem;
  std::string workdir =
      (fs::temp_directory_path() / "piet_native_selftest_bug116_singleline").u8string();
  std::error_code ec;
  fs::remove_all(workdir, ec);
  fs::create_directories(workdir, ec);
  piet::SessionState session(workdir);

  (void)piet::dispatch("sysuse fatalities, clear", session);

  // Oracle (StataBE 19.5, live-verified this session): `capture capture
  // noisily regress mpg nosuchvar` leaves _rc==0 — the wrapped statement is
  // itself a `capture`, which always completes without an error escaping
  // it (that is capture's entire point), regardless of what _rc the INNER
  // capture set as a side effect. dispatcher.cpp's Pre-0 `capture` arm had
  // the same un-guarded "any error block" scan as BUG-116's runCaptureBlock
  // — fixed by the same !captured guard.
  (void)piet::dispatch("capture capture noisily regress fatal nosuchvar_bug116", session);
  check(session.eval.locals.get("_rc", "") == "0",
        "BUG-116 class: `capture capture noisily <failing cmd>` (single-line double capture) "
        "leaves outer _rc==0 (oracle: StataBE 19.5), got _rc=" +
            session.eval.locals.get("_rc", "<unset>"));

  // Same oracle-confirmed result holds when the OUTER capture is itself
  // noisily-rooted (noisily only affects display, not rc capture).
  (void)piet::dispatch("capture noisily capture noisily regress fatal nosuchvar_bug116", session);
  check(session.eval.locals.get("_rc", "") == "0",
        "BUG-116 class: `capture noisily capture noisily <failing cmd>` also leaves outer "
        "_rc==0 (oracle: StataBE 19.5), got _rc=" +
            session.eval.locals.get("_rc", "<unset>"));

  fs::remove_all(workdir, ec);
}

// P9 arc①/② — `parallel, workers(N) { ... }` block form.
//
// The VERIFY probe (tests/eval/verify_ledger/probes/piet-plevel) is the real
// gate for this feature: it forks actual workers and byte-compares stdout, the
// log, and every artifact. It is NOT part of the standard battery, so these
// legs are what a routine `--selftest` run has to notice a regression with.
// They stay in-process on purpose (workers(1) takes the serial leg), so they
// are fast and cannot be flaky about process scheduling.
// P9 automode · the recognizer's approval predicate.
//
// The predicate is the only thing standing between "run these in parallel" and
// wrong output, so its REFUSALS are as load-bearing as its approvals and are
// tested here in both directions. These legs never spawn a worker — they ask
// planRegion directly, which is where every decision is actually made.
void testP9AutoRecognizer() {
  std::printf("[selftest] --- P9 automode recognizer (approval predicate) ---\n");
  namespace fs = std::filesystem;
  std::string workdir = (fs::temp_directory_path() / "piet_native_selftest_p9auto").u8string();
  std::error_code ec;
  fs::remove_all(workdir, ec);
  fs::create_directories(workdir, ec);

  // Default OFF is a User ruling, not a preference: assert it holds with no env.
  check(!piet::parallel::autoModeEnabled(),
        "P9 automode: OFF unless PIET_PARALLEL_AUTO is set");

  auto plan = [&](const std::vector<std::string>& stmts,
                  const std::vector<std::string>& after) {
    piet::SessionState session(workdir);
    return piet::parallel::planRegion(stmts, after, session);
  };

  // Approves: three self-seeding, effect-free-outside tasks with nothing after.
  {
    auto p = plan({"clear", "clear", "clear"}, {});
    check(p.approved, std::string("P9 automode: a run of self-seeding statements is approved") +
                          (p.approved ? "" : " — got: " + p.refusalReason));
  }
  // Refuses: below the minimum region size (a 2-task region cannot pay for itself).
  {
    auto p = plan({"clear", "clear"}, {});
    check(!p.approved, "P9 automode: a run shorter than kAutoMinRegion is refused");
  }
  // Session-globals are decided BY NAME, not by the fact of writing one. With
  // nothing downstream reading `g`, the region is safe and is approved — the
  // blanket refusal this replaced rejected every real program.
  {
    auto p = plan({"clear", "global g 1", "clear"}, {});
    check(p.approved,
          std::string("P9 automode: a session-global nobody reads afterwards is approved") +
              (p.approved ? "" : " — got: " + p.refusalReason));
  }
  // ...and refused, by name, the moment something after the region reads it.
  {
    auto p = plan({"clear", "global g 1", "clear"}, {"display \"$g\""});
    check(!p.approved && p.refusalReason.find("g") != std::string::npos,
          "P9 automode: a session-global READ after the region refuses it, by name");
  }
  // A write whose target name is minted at run time cannot be reasoned about at
  // all, so it refuses regardless of what follows.
  {
    auto p = plan({"clear", "global `nm' 1", "clear"}, {});
    check(!p.approved && p.refusalReason.find("macro") != std::string::npos,
          "P9 automode: a macro-named session-global write refuses");
  }
  // Refuses: a top-level `capture` (writes _rc and changes which lines run).
  {
    auto p = plan({"clear", "capture summarize x", "clear"}, {});
    check(!p.approved && p.refusalReason.find("capture") != std::string::npos,
          "P9 automode: a top-level `capture` is refused by name");
  }
  // Refuses: an unknown command — the whole safety axiom in one case.
  {
    auto p = plan({"clear", "no_such_command_at_all", "clear"}, {});
    check(!p.approved && p.refusalReason.find("effect table") != std::string::npos,
          "P9 automode: an unclassified command refuses the region");
  }
  // Refuses: the region leaves a dataset that a later statement reads.
  {
    auto p = plan({"clear", "clear", "clear"}, {"summarize x"});
    check(!p.approved, "P9 automode: a successor that reads the region's dataset refuses it");
  }
  // The failure index is what lets the scan resume after a bad statement instead
  // of writing off everything behind it — measured on the acceptance corpus,
  // that difference is the whole batch being reachable or not.
  {
    auto p = plan({"capture summarize x", "clear", "clear", "clear"}, {});
    check(!p.approved && p.failedAt == 0,
          "P9 automode: the refusal names WHICH statement failed (failedAt)");
  }
  // User ruling 2026-09-02 (supersedes #14-b's floor of one and #25): the auto
  // worker count is DERIVED from the budgets and the work — cores (performance
  // cores when auto), memory (budget / a dataset-scaled per-worker cost), tasks
  // (the block's own count) and disk (half the free scratch space / a
  // dataset-scaled per-task scratch peak). The smallest term binds; nothing is
  // a constant floor. Pinned through the pure derivation so no live machine
  // state enters.
  {
    using piet::parallel::DerivationInputs;
    auto mk = [] {
      DerivationInputs in;
      in.perfCores = 4;
      in.memoryBudgetMb = 4096;
      in.residentBytes = 0;
      in.taskCount = 8;
      in.scratchFreeBytes = int64_t(100) << 30;  // 100 GiB: disk never binds here
      return in;
    };
    auto d = piet::parallel::deriveDefaultWorkers(mk());
    check(d.n == 4 && d.coresTerm == 4 && d.memTerm == 5,
          "P9 N (09-02): auto/4 perf cores/4096 MB/8 tasks/plenty of disk -> 4 (cores bind; memory 5)");
    check(d.reason.find("cores 4") != std::string::npos && d.reason.find("-> 4") != std::string::npos,
          "P9 N (09-02): the banner names every term and the result");
    { auto in = mk(); in.taskCount = 2; check(piet::parallel::deriveDefaultWorkers(in).n == 2,
          "P9 N (09-02): a 2-task block gets 2 workers (the work binds)"); }
    { auto in = mk(); in.taskCount = 1; check(piet::parallel::deriveDefaultWorkers(in).n == 1,
          "P9 N (09-02): a 1-task block gets 1 worker"); }
    { auto in = mk(); in.taskCount = 0; check(piet::parallel::deriveDefaultWorkers(in).n == 4,
          "P9 N (09-02): unknown task count is no constraint"); }
    { auto in = mk(); in.computeCores = 2; check(piet::parallel::deriveDefaultWorkers(in).n == 2,
          "P9 N (09-02): an explicit compute_cores=2 replaces the perf-core width"); }
    { auto in = mk(); in.perfCores = 8; in.memoryBudgetMb = 8192;
      check(piet::parallel::deriveDefaultWorkers(in).n == 4,
          "P9 N (09-02): the measured ceiling (kMemoryCapWorkers) still caps a generous machine at 4"); }
    { auto in = mk(); in.memoryBudgetMb = 1000;
      auto dd = piet::parallel::deriveDefaultWorkers(in);
      check(dd.n == 1 && dd.perWorkerMb == 700,
          "P9 N (09-02): resident unknown -> the 700 MB constant; 1000 MB budget -> 1 worker"); }
    { auto in = mk(); in.residentBytes = int64_t(164) << 20;
      auto dd = piet::parallel::deriveDefaultWorkers(in);
      check(dd.perWorkerMb == 200 + 2 * 164 && dd.memTerm == 7 && dd.n == 4,
          "P9 N (09-02): per-worker cost scales with the resident data (200 + 2 x 164 = 528 MB)"); }
    { auto in = mk(); in.residentBytes = int64_t(164) << 20; in.scratchFreeBytes = int64_t(1) << 30;
      auto dd = piet::parallel::deriveDefaultWorkers(in);
      check(dd.perTaskScratchMb == 4 * 164 && dd.n == 1,
          "P9 N (09-02): 1 GiB free scratch / (4 x 164 MB per task, half headroom) -> 1 worker (disk binds)"); }
    { auto in = mk(); in.residentBytes = int64_t(164) << 20; in.scratchFreeBytes = int64_t(4) << 30;
      check(piet::parallel::deriveDefaultWorkers(in).n == 3,
          "P9 N (09-02): 4 GiB free -> 2048 / 656 = 3 workers (disk binds below cores)"); }
    { auto in = mk(); in.scratchFreeBytes = -1; check(piet::parallel::deriveDefaultWorkers(in).n == 4,
          "P9 N (09-02): unknown free space is no constraint"); }
    { auto in = mk(); in.residentBytes = 1 << 20; in.scratchFreeBytes = int64_t(1) << 30;
      auto dd = piet::parallel::deriveDefaultWorkers(in);
      check(dd.perTaskScratchMb == 64 && dd.n == 4,
          "P9 N (09-02): a tiny dataset still budgets the 64 MB per-task floor"); }
    check(piet::parallel::perfCoreCount() >= 1, "P9 N (09-02): perfCoreCount() is never 0");
    check(piet::parallel::scratchFreeBytes("") > 0,
          "P9 N (09-02): scratchFreeBytes() reads the scratch volume (>0 on a live machine)");
  }

  // ONESHOT-P9N4 C: the N² guard's divisor. resolveWorkers reads the live
  // settings file, so these legs pin the arithmetic through the ONE input a
  // selftest can hold fixed — the requested N — and assert the invariant that
  // holds for every machine rather than a number that only holds on this one.
  // (compute_cores is the User's setting, not ours to write from a test.)
  {
    const piet::parallel::WorkerBudget b1 = piet::parallel::resolveWorkers(1);
    const piet::parallel::WorkerBudget b4 = piet::parallel::resolveWorkers(4);
    check(b1.engineThreads >= 1 && b4.engineThreads >= 1,
          "P9 threads: every worker gets at least one engine thread (never 0)");
    check(b4.n == 4 || b4.pressure >= 4,
          "P9 threads: an explicit workers(4) is honoured unless the kernel is critical");
    // The whole point of the guard: N workers must not each take the full width.
    check(b4.engineThreads <= b1.engineThreads,
          "P9 threads: four workers each get no more engine threads than one worker does");
    check(b4.n * b4.engineThreads <= b1.engineThreads * b1.n + b4.n,
          "P9 threads: total engine threads stay within the core budget (+rounding floor)");
    // 2026-09-02: the memory budget divides the same way, with a 64 MB floor.
    check(b1.engineMemoryMb >= 64 && b4.engineMemoryMb >= 64,
          "P9 memory: every worker gets at least the 64 MB floor");
    check(b4.engineMemoryMb <= b1.engineMemoryMb,
          "P9 memory: four workers each get no more memory than one worker does");
    check(b4.n * b4.engineMemoryMb <= b1.engineMemoryMb + 64 * b4.n,
          "P9 memory: the workers' shares stay within the memory budget (+floor)");
  }

  // Coverage is a progress metric, not a correctness one — but an empty table
  // would make every region refuse and every test above pass vacuously.
  check(piet::parallel::classifiedCommandCount() > 50,
        "P9 automode: the effect table is populated (" +
            std::to_string(piet::parallel::classifiedCommandCount()) + " commands)");
}

// BUG-344: `summarize` never set r(sum) / r(sum_w).
//
// The r() mapping (captureRFromBlock, macros.cpp) had read both keys since it
// was written — the defect was upstream of it, in the two PRODUCERS: the engine
// published `sum` only under `detail` and `sum_w` only under [aw=], and PIET's
// no-cobra fallback summed the column to get the mean and then dropped the sum
// on the floor. So this test drives the whole user-visible path (`summarize`
// then `display r(sum)`) rather than the mapping in isolation: a mapping-only
// leg would have been GREEN for the entire time the bug was live.
//
// Stata posts r(sum) and r(sum_w) for EVERY summarize form — plain, detail, and
// meanonly — because they are properties of the sample, not of the display.
void testBug344SummarizeSum() {
  std::printf("[selftest] --- BUG-344 `summarize` sets r(sum) / r(sum_w) ---\n");
  namespace fs = std::filesystem;
  std::string workdir = (fs::temp_directory_path() / "piet_native_selftest_bug344").u8string();
  std::error_code ec;
  fs::remove_all(workdir, ec);
  fs::create_directories(workdir, ec);

  auto displayed = [](const auto& blocks) {
    std::string last;
    for (const auto& b : blocks)
      if (b.is_object() && b.value("type", std::string()) == "display")
        last = b.value("text", std::string());
    return last;
  };

  // x = 1..10 -> sum 55, sum_w 10 (Σw with w≡1 IS the observation count).
  for (const std::string& form : {std::string("summarize x"), std::string("summarize x, meanonly"),
                                  std::string("summarize x, detail")}) {
    piet::SessionState session(workdir);
    std::string src = "clear\nset obs 10\ngen double x = _n\n" + form +
                      "\ndisplay r(sum)\ndisplay r(sum_w)\n";
    auto r = piet::doexec::executeDoSource(src, session, piet::dispatch);
    int errs = 0;
    std::string sumTxt, sumwTxt;
    for (const auto& b : r.blocks) {
      if (!b.is_object()) continue;
      if (b.value("type", std::string()) == "error") ++errs;
      if (b.value("type", std::string()) == "display") {
        if (sumTxt.empty()) sumTxt = b.value("text", std::string());
        else if (sumwTxt.empty()) sumwTxt = b.value("text", std::string());
      }
    }
    (void)displayed;
    check(errs == 0, "BUG-344 [" + form + "]: no error (r(sum) was `not set` before the fix)");
    check(sumTxt == "55", "BUG-344 [" + form + "]: r(sum) = 55 over x=1..10, got `" + sumTxt + "`");
    check(sumwTxt == "10",
          "BUG-344 [" + form + "]: r(sum_w) = 10 (=N unweighted), got `" + sumwTxt + "`");
  }

  // BUG-476 (User-ruled 2026-09-09): unlike r(sum)/r(sum_w) above, r(sd) is
  // NOT value-identical across forms — `meanonly` skips Stata's whole
  // variance/percentile pass, so r(sd) is left MISSING. Measured StataBE
  // 19.5 (tests/eval/golden/aer_b4/pins_oracle_r.log, batch R):
  // `B4VAL|mean|+1.81541bacf914cX+00c|sd_is_missing|+1.0000000000000X+3ff`
  // — mean published, sd is Stata's `.` (= 2^1023 = kStataMissingSentinel
  // in %21x). Checked at the C++ level (session.eval.rValues), not through
  // `display`'s text formatting, so this pins the VALUE the fix publishes
  // rather than a display-layer rendering detail.
  {
    piet::SessionState session(workdir);
    std::string src = "clear\nset obs 10\ngen double x = _n\nsummarize x, meanonly\n";
    auto r = piet::doexec::executeDoSource(src, session, piet::dispatch);
    check(!r.stoppedAtReason.has_value(), "BUG-476: `summarize x, meanonly` runs cleanly");
    const double* mean = session.eval.rValues.find("mean");
    const double* sd = session.eval.rValues.find("sd");
    check(mean != nullptr && std::fabs(*mean - 5.5) < 1e-9,
          "BUG-476: r(mean) = 5.5 over x=1..10 under meanonly (still published) -- got " +
              (mean != nullptr ? std::to_string(*mean) : std::string("MISSING")));
    check(sd != nullptr && *sd >= piet::eval::kStataMissingSentinel,
          "BUG-476: r(sd) reads back as Stata MISSING after meanonly -- this build used to "
          "publish the true sd (3.0276503540974917) -- got " +
              (sd != nullptr ? std::to_string(*sd) : std::string("(key absent -- would honest-"
                                                                  "reject on a `display r(sd)` "
                                                                  "read, not silently miss)")));
    const double* var = session.eval.rValues.find("Var");
    const double* median = session.eval.rValues.find("median");
    check(var != nullptr && *var >= piet::eval::kStataMissingSentinel,
          "BUG-476: r(Var) (derived from sd) is ALSO missing under meanonly, not just r(sd)");
    // BUG-1013: summarize never posts r(median) -- Stata has no such result
    // (help summarize lists r(p50), `detail` only), so a read is `.` after every
    // form (w2as_summary_stats_family.log:407 sx_sum_plain_u, :509 sx_sum_d_u). The
    // PIET-only p50 alias this pin used to accept is gone; absent and missing both
    // read as `.`.
    check(median == nullptr || *median >= piet::eval::kStataMissingSentinel,
          "BUG-476/BUG-1013: r(median) is never a value after meanonly (Stata posts no "
          "r(median); w2as_summary_stats_family.log:407)");
  }
  // control: a FULL summarize on the same column DOES publish a real r(sd)
  // (BUG-476.do's own control leg) -- so the assertion above cannot be
  // blamed on the column or the fixture.
  {
    piet::SessionState session(workdir);
    std::string src = "clear\nset obs 10\ngen double x = _n\nsummarize x\n";
    (void)piet::doexec::executeDoSource(src, session, piet::dispatch);
    const double* sd = session.eval.rValues.find("sd");
    check(sd != nullptr && *sd < piet::eval::kStataMissingSentinel && *sd > 0,
          "BUG-476 control: a full `summarize x` (no meanonly) DOES publish a finite r(sd) -- "
          "got " + (sd != nullptr ? std::to_string(*sd) : std::string("MISSING")));
  }
}

// BUG-341: `display var[1]` after a resident mutation answered `matrix var not
// found` — a variable read falling into the matrix namespace. Pre-existing since
// subscript support arrived (before it, B.6.2 echoed `ynum[1]` literally), and the
// acceptance corpus never uses the form, which is why eight waves missed it.
//
// Every expectation below is a StataBE measurement taken 2026-08-14, not a guess:
// in-range → the row's value, out-of-range and index 0 → missing, string variable
// → the string. The undefined-matrix leg guards the arm ABOVE it staying reachable.
// BUG-343: the `file` family (text mode). The registry had 162 rows and none of
// them was `file`, so a do-file that wrote its own log stopped dead. These legs
// drive the whole round trip through the user-visible path, because the three
// things that can silently go wrong here are all end-to-end: the bytes actually
// on disk, `r(eof)` actually reaching a read loop, and the refusals actually
// naming what they refuse.
void testBug343FileFamily() {
  std::printf("[selftest] --- BUG-343 `file open|write|read|close` (text mode) ---\n");
  namespace fs = std::filesystem;
  std::string workdir = (fs::temp_directory_path() / "piet_native_selftest_bug343").u8string();
  std::error_code ec;
  fs::remove_all(workdir, ec);
  fs::create_directories(workdir, ec);
  const std::string out = (fs::path(workdir) / "out.txt").u8string();

  auto displays = [](const auto& blocks) {
    std::vector<std::string> v;
    for (const auto& b : blocks)
      if (b.is_object() && b.value("type", std::string()) == "display")
        v.push_back(b.value("text", std::string()));
    return v;
  };
  auto errorText = [](const auto& blocks) {
    for (const auto& b : blocks)
      if (b.is_object() && b.value("type", std::string()) == "error")
        return b.value("message", std::string());
    return std::string();
  };

  {
    piet::SessionState session(workdir);
    session.eval.cwd = workdir;
    std::string src = "file open fh using \"" + out + "\", write replace\n"
                      "file write fh \"hello\" _n \"a,b\" _n\n"
                      "file close fh\n";
    auto r = piet::doexec::executeDoSource(src, session, piet::dispatch);
    check(errorText(r.blocks).empty(), "BUG-343: open/write/close raises no error");
    std::ifstream f(out, std::ios::binary);
    std::string got((std::istreambuf_iterator<char>(f)), std::istreambuf_iterator<char>());
    check(got == "hello\na,b\n",
          "BUG-343: the bytes on disk are exactly what was written (`_n` is a newline, "
          "quoted items keep their spaces) — got " + std::to_string(got.size()) + "B");
  }
  {
    piet::SessionState session(workdir);
    session.eval.cwd = workdir;
    std::string src = "file open rh using \"" + out + "\", read\n"
                      "file read rh l1\ndisplay \"`l1'\"\n"
                      "file read rh l2\ndisplay \"`l2'\"\n"
                      "file read rh l3\ndisplay r(eof)\n"
                      "file close rh\n";
    auto r = piet::doexec::executeDoSource(src, session, piet::dispatch);
    auto d = displays(r.blocks);
    check(d.size() == 3 && d[0] == "hello" && d[1] == "a,b",
          "BUG-343: `file read` returns one LINE per call into the named local");
    check(d.size() == 3 && d[2] == "1",
          "BUG-343: r(eof) is 1 once the reads run past the end — the value a read loop tests");
  }
  {  // BUG-1526: `binary` mode reads the file's bytes (BUG-343 refused it by name).
    piet::SessionState session(workdir);
    session.eval.cwd = workdir;
    auto r = piet::doexec::executeDoSource("file open bh using \"" + out + "\", binary\n"
                                           "file read bh %5s w %1bu nl\n"
                                           "display \"`w'|\" nl\n"
                                           "file close bh\n",
                                           session, piet::dispatch);
    auto d = displays(r.blocks);
    check(errorText(r.blocks).empty() && d.size() == 1 && d[0] == "hello|10",
          "BUG-1526: a binary read gives the file's bytes (%5s `hello`, %1bu 10 for the newline)");
  }
  {
    piet::SessionState session(workdir);
    session.eval.cwd = workdir;
    auto r = piet::doexec::executeDoSource("file close nosuch\n", session, piet::dispatch);
    // EM2: Stata's wording and code, "file handle NAME not found" r(111)
    // (w2af_macro_text_file.log:2130-2136 mt_fwrite_closed).
    check(errorText(r.blocks).find("not found") != std::string::npos,
          "BUG-343: closing a handle that was never opened is an honest error");
  }
  {  // No-clobber: a plain `write` over an existing file must refuse without `replace`,
     // in Stata's words: `file X already exists` r(602), the file as typed
     // (StataBE 19.5; this arm used to pin PIET's own "(specify `replace`)").
    piet::SessionState session(workdir);
    session.eval.cwd = workdir;
    auto r = piet::doexec::executeDoSource(
        "file open ch using \"" + out + "\", write\n", session, piet::dispatch);
    std::string reason;
    for (const auto& b : r.blocks)
      if (b.is_object() && b.value("type", std::string()) == "error")
        reason = b.value("reason", std::string());
    check(errorText(r.blocks) == "file " + out + " already exists" && reason == "r(602)",
          "BUG-343: opening an existing file for write without `replace` refuses and says so "
          "(got `" + errorText(r.blocks) + "` " + reason + ")");
  }
}

// AER-SCOPE1 bundle D (ENV): the nineteen preamble verbs.
//
// Sibling of testBug343FileFamily above, and for the same reason: these verbs
// act on the FILESYSTEM and on SESSION STATE, so neither the eval goldens nor
// the per-command floor gate can see whether they did anything. The floors.json
// rows say so explicitly (state no_fixture, "a budget would be measuring
// nothing"). That makes THIS function the only place the work itself is
// checked, and the checks below are written against the effect rather than
// against the message wherever an effect exists: `shell rm` is verified by
// asking the filesystem whether the file is gone, not by reading the note.
//
// The note texts ARE asserted verbatim, in one table, because for the accepted
// verbs the note is the entire observable behaviour -- a `net install` that
// went quiet and returned 0 is indistinguishable from one that installed. Each
// message prints what came back beside what was expected, so a display-layer
// drift reads as a drift at a glance instead of as a mystery.
void testAerEnvBundle() {
  std::printf("[selftest] --- AER-SCOPE1 bundle D (ENV): shell / net / ado / adopath / sysdir / "
              "findfile / error / frames / tset / sleep ---\n");
  namespace fs = std::filesystem;
  std::string workdir = (fs::temp_directory_path() / "piet_native_selftest_aerenv").u8string();
  std::error_code ec;
  fs::remove_all(workdir, ec);
  fs::create_directories(workdir, ec);

  auto displays = [](const auto& blocks) {
    std::vector<std::string> v;
    for (const auto& b : blocks)
      if (b.is_object() && b.value("type", std::string()) == "display")
        v.push_back(b.value("text", std::string()));
    return v;
  };
  auto errField = [](const auto& blocks, const char* field) {
    for (const auto& b : blocks)
      if (b.is_object() && b.value("type", std::string()) == "error")
        return b.value(field, std::string());
    return std::string();
  };
  auto writeFile = [](const std::string& p, const std::string& body) {
    std::ofstream f(p, std::ios::binary);
    f << body;
  };
  auto readFile = [](const std::string& p) {
    std::ifstream f(p, std::ios::binary);
    return std::string((std::istreambuf_iterator<char>(f)), std::istreambuf_iterator<char>());
  };
  // Absolute paths throughout: the shell arg parser's quote handling is not
  // what is under test here, and the temp dir has no spaces to need it.
  auto at = [&](const std::string& rel) { return (fs::path(workdir) / rel).u8string(); };

  // --- shell: the translation is judged by the DISK, not by its own note. ---
  {
    piet::SessionState session(workdir);
    session.eval.cwd = workdir;
    const std::string victim = at("victim.txt");
    writeFile(victim, "gone soon\n");
    auto r = piet::doexec::executeDoSource("shell rm -f " + victim + "\n", session, piet::dispatch);
    check(!fs::exists(victim), "ENV/shell: `shell rm` actually unlinks the file -- the note is the "
                               "report, not the work");
    bool saidSo = false;
    for (const auto& line : displays(r.blocks))
      if (line.find("translated ->") != std::string::npos) saidSo = true;
    check(saidSo, "ENV/shell: the translation is VISIBLE (`translated -> <verb> <paths>`); a silent "
                  "accept would leave the user believing a real shell ran");
  }
  {
    piet::SessionState session(workdir);
    session.eval.cwd = workdir;
    const std::string deep = at("a/b/c");
    (void)piet::doexec::executeDoSource("shell mkdir -p " + deep + "\n", session, piet::dispatch);
    check(fs::is_directory(deep),
          "ENV/shell: `mkdir -p` creates the WHOLE chain, not just the leaf's parent");
  }
  {
    piet::SessionState session(workdir);
    session.eval.cwd = workdir;
    const std::string payload = "one,two\nthree\n";
    const std::string a = at("cp_src.txt"), b = at("cp_mid.txt"), c = at("cp_dst.txt");
    writeFile(a, payload);
    (void)piet::doexec::executeDoSource(
        "shell cp " + a + " " + b + "\nshell mv " + b + " " + c + "\n", session, piet::dispatch);
    check(fs::exists(a) && readFile(a) == payload,
          "ENV/shell: `cp` COPIED -- the source is still there with its bytes");
    check(!fs::exists(b), "ENV/shell: `mv` moved rather than copied -- the intermediate is gone");
    check(fs::exists(c) && readFile(c) == payload,
          "ENV/shell: cp-then-mv leaves the bytes unchanged at the destination");
  }
  {  // A glob is the shape the corpus actually writes (`shell rm -f tmp/*.txt`).
    piet::SessionState session(workdir);
    session.eval.cwd = workdir;
    const std::string g1 = at("g_1.txt"), g2 = at("g_2.txt"), keep = at("g_keep.dat");
    writeFile(g1, "1");
    writeFile(g2, "2");
    writeFile(keep, "k");
    (void)piet::doexec::executeDoSource("shell rm -f " + at("g_*.txt") + "\n", session,
                                        piet::dispatch);
    check(!fs::exists(g1) && !fs::exists(g2),
          "ENV/shell: a glob removes BOTH matches (a first-match-only expansion is the silent "
          "half-done class)");
    check(fs::exists(keep), "ENV/shell: and nothing that did not match the glob");
  }
  // The two refusals, each naming its own cause AND landing on r(199).
  //
  // The rc leg is not decoration. eval::coarseRc (errors.cpp) answers 199 for
  // exactly two shapes: code == "unsupported_command", or a `reason` spelled
  // "r(NNN)". A refusal block built as a bare engine_error with reason
  // "refused:<cause>" matches NEITHER, so it falls through to the generic 1 --
  // and a do-file branching on `if _rc == 199` then takes the wrong branch off
  // an error that refused perfectly well. The code check and the _rc check are
  // therefore both here: the first says which shape was built, the second says
  // what the user actually sees.
  {
    piet::SessionState session(workdir);
    session.eval.cwd = workdir;
    auto r = piet::doexec::executeDoSource("shell chmod 777 " + workdir + "\n", session,
                                           piet::dispatch);
    check(errField(r.blocks, "code") == "unsupported_command",
          "ENV/shell: an off-allowlist verb is an honest unsupported_command, got code `" +
              errField(r.blocks, "code") + "`");
    check(errField(r.blocks, "reason") == "refused:shell_allowlist",
          "ENV/shell: ...and names the allowlist as the cause, got reason `" +
              errField(r.blocks, "reason") + "`");
  }
  {
    piet::SessionState session(workdir);
    session.eval.cwd = workdir;
    auto r = piet::doexec::executeDoSource("shell rm -f " + at("nothing.txt") + " | cat\n", session,
                                           piet::dispatch);
    check(errField(r.blocks, "reason") == "refused:shell_operator",
          "ENV/shell: a shell metacharacter refuses as an OPERATOR, distinct from the allowlist "
          "refusal -- PIET has no shell to interpret it, got reason `" +
              errField(r.blocks, "reason") + "`");
  }
  {
    const std::vector<std::pair<std::string, std::string>> kRefusals = {
        {"shell chmod 777 " + workdir, "off-allowlist shell verb"},
        {"shell rm -f " + at("nothing.txt") + " | cat", "shell metacharacter"},
        {"winexec notepad.exe", "winexec"},
        // twoway__histogram_gen left this list when gfx-histogram-kdensity-family
        // served it (w2aq_histogram_family hk_thg_*); selftest_w2aq_histogram pins it.
    };
    for (const auto& [src, what] : kRefusals) {
      piet::SessionState session(workdir);
      session.eval.cwd = workdir;
      (void)piet::doexec::executeDoSource("capture " + src + "\n", session, piet::dispatch);
      check(session.eval.locals.get("_rc", "") == "199",
            "ENV/refusal: " + what + " leaves _rc 199, the code Stata gives an unrecognized "
            "capability -- got _rc=" + session.eval.locals.get("_rc", "<unset>"));
    }
  }
  {  // `!cmd` must reach the same code, not a second and looser one.
    piet::SessionState session(workdir);
    session.eval.cwd = workdir;
    const std::string bang = at("bang.txt");
    writeFile(bang, "b");
    (void)piet::doexec::executeDoSource("!rm -f " + bang + "\n", session, piet::dispatch);
    check(!fs::exists(bang),
          "ENV/shell: `!cmd` is rewritten to `shell cmd` before tokenizing -- same file verb, same "
          "effect");
    auto r = piet::doexec::executeDoSource("!chmod 777 " + workdir + "\n", session, piet::dispatch);
    check(errField(r.blocks, "reason") == "refused:shell_allowlist",
          "ENV/shell: `!` inherits the SAME allowlist -- a bang that refused less than `shell` "
          "would be a hole with a shorter spelling, got reason `" +
              errField(r.blocks, "reason") + "`");
  }

  // --- error: the argument IS the return code, and 0 is not an error. ---
  {
    piet::SessionState session(workdir);
    (void)piet::doexec::executeDoSource("capture error 199\n", session, piet::dispatch);
    check(session.eval.locals.get("_rc", "") == "199",
          "ENV/error: `capture error 199` leaves _rc 199 (not the generic captured 1), got _rc=" +
              session.eval.locals.get("_rc", "<unset>"));
  }
  {
    piet::SessionState session(workdir);
    auto r = piet::doexec::executeDoSource("error 0\n", session, piet::dispatch);
    // Every dispatched line emits its own echo block, so "no block at all" is
    // not the observable -- "no ERROR block" is. Asserting emptiness measured
    // the echo, not `error 0`.
    size_t errBlocks = 0;
    for (const auto& b : r.blocks) {
      if (b.is_object() && b.value("type", std::string()) == "error") ++errBlocks;
    }
    check(errBlocks == 0, "ENV/error: `error 0` raises NO error -- r(0) is Stata's success code, "
                          "so raising it would invent a failure, got " +
                              std::to_string(errBlocks) + " error block(s)");
    check(!r.stoppedAtReason.has_value(),
          "ENV/error: `error 0` does not stop the do-file, stop=" +
              r.stoppedAtReason.value_or("<none>"));
  }

  // --- the accept-notes, verbatim. For these verbs the note IS the behaviour.
  {
    // adopath and sysdir RECORD the resolved path but ECHO the argument as it
    // was written (handlers_aer_env.cpp says why: a resolved echo would bake
    // the capture machine's cwd into every golden that pins the note). These
    // two probes pass an ABSOLUTE path anyway, so as-written and as-resolved
    // are the same string and the expectation stays exact whichever way a
    // later edit takes the handler -- this test is not the place that decides
    // it. The read-back leg below is what actually pins the recorded form.
    const std::string apDir = at("99_ado");
    const std::string sdDir = at("plus_ado");
    const std::vector<std::pair<std::string, std::string>> kNotes = {
        {"net install reghdfe", "(net install reghdfe: PIET is offline -- skipped)"},
        // The corpus's real spelling carries options. The note is built off the
        // varlist, so the option tail must not reach it -- a `(net install
        // reghdfe,: ...)` would be invisible to the bare probe above.
        {"net install reghdfe, from(\"https://example.invalid/src/\") replace",
         "(net install reghdfe: PIET is offline -- skipped)"},
        {"ado uninstall moremata", "(ado uninstall moremata: PIET has no ado directory -- skipped)"},
        {"adopath + " + apDir,
         "(adopath + " + apDir + ": recorded for findfile and ado autoload)"},
        {"sysdir set PLUS " + sdDir,
         "(sysdir set PLUS " + sdDir + ": recorded for findfile)"},
        {"pause on", "(pause on: PIET is non-interactive -- no effect)"},
        {"gr_edit .plotregion1.style.editstyle margin(medium) editcopy",
         "(gr_edit: graph-editor recording, appearance only -- ignored)"},
    };
    for (const auto& [src, note] : kNotes) {
      piet::SessionState session(workdir);
      session.eval.cwd = workdir;
      auto r = piet::doexec::executeDoSource(src + "\n", session, piet::dispatch);
      auto d = displays(r.blocks);
      bool exact = false;
      for (const auto& line : d)
        if (line == note) exact = true;
      check(exact, "ENV/note: `" + src + "` prints its accept-note verbatim -- expected `" + note +
                       "`, got " + (d.empty() ? std::string("no display at all") :
                                                std::string("`") + d.front() + "`"));
    }
  }

  // --- adopath -> findfile: the recorded path is what findfile is FOR. ---
  const std::string adodir = at("ado");
  fs::create_directories(adodir, ec);
  const std::string adofile = (fs::path(adodir) / "piet_env_probe.ado").u8string();
  writeFile(adofile, "* probe\n");
  {
    piet::SessionState session(workdir);
    session.eval.cwd = workdir;
    (void)piet::doexec::executeDoSource(
        "adopath + " + adodir + "\nfindfile piet_env_probe.ado\nlocal fn `r(fn)'\n", session,
        piet::dispatch);
    check(session.eval.locals.get("fn", "") == adofile,
          "ENV/findfile: searches the RECORDED adopath and publishes r(fn) as the absolute path, "
          "got `" + session.eval.locals.get("fn", "<unset>") + "`");
  }
  {
    // [P] findfile (p.pdf pp.246-247): each path directory is searched, then its
    // letter subdirectory, unless nodescend -- where an installed ado lives
    // (w2t_boottest_family.log:131 A6 `.../ado/plus/b/boottest.ado`). bin/main
    // tested `dir/name` only: r(601).
    const std::string letterDir = (fs::path(adodir) / "p").u8string();
    fs::create_directories(letterDir, ec);
    const std::string letterFile = (fs::path(letterDir) / "piet_env_letter.ado").u8string();
    writeFile(letterFile, "* probe\n");
    piet::SessionState session(workdir);
    session.eval.cwd = workdir;
    (void)piet::doexec::executeDoSource(
        "findfile piet_env_letter.ado, path(\"" + adodir + "\")\nlocal fn `r(fn)'\n"
        "capture findfile piet_env_letter.ado, path(\"" + adodir + "\") nodescend\n"
        "local rc2 = _rc\n",
        session, piet::dispatch);
    check(session.eval.locals.get("fn", "") == letterFile &&
              session.eval.locals.get("rc2", "") == "601",
          "ENV/findfile: descends into the letter subdirectory (r(fn) `" + letterFile +
              "`), and nodescend does not (r(601)); got `" +
              session.eval.locals.get("fn", "<unset>") + "` rc2 " +
              session.eval.locals.get("rc2", "<unset>"));
  }
  {
    piet::SessionState session(workdir);
    session.eval.cwd = workdir;
    auto r = piet::doexec::executeDoSource("findfile piet_env_no_such.ado\n", session,
                                           piet::dispatch);
    check(errField(r.blocks, "reason") == "r(601)",
          "ENV/findfile: a miss is r(601) -- an empty r(fn) with rc 0 would be the silent-wrong "
          "answer, got reason `" + errField(r.blocks, "reason") + "`");
  }
  {  // A `set` nobody can read back is a write-only setting.
    //
    // The set and the read-back are TWO executeDoSource calls on one session,
    // not one two-line source: the `sysdir set` accept-note itself contains
    // both "PLUS" and the directory, so a single-call scan is satisfied by the
    // note alone and stays GREEN even if bare `sysdir` prints nothing at all.
    // Only the second call's blocks are scanned, so the listing has to answer.
    piet::SessionState session(workdir);
    session.eval.cwd = workdir;
    (void)piet::doexec::executeDoSource("sysdir set PLUS " + adodir + "\n", session,
                                        piet::dispatch);
    auto r = piet::doexec::executeDoSource("sysdir\n", session, piet::dispatch);
    bool reflected = false;
    for (const auto& line : displays(r.blocks))
      if (line.find("PLUS") != std::string::npos && line.find(adodir) != std::string::npos)
        reflected = true;
    check(reflected, "ENV/sysdir: bare `sysdir` reports the directory `sysdir set` recorded");
  }

  // --- frames reset: the roster, not just the current frame. ---
  {
    piet::SessionState session(workdir);
    (void)piet::doexec::executeDoSource("sysuse fatalities, clear\n"
                                        "frame put state beertax, into(envf1)\n"
                                        "frame put state year, into(envf2)\n",
                                        session, piet::dispatch);
    check(session.frames.size() >= 2,
          "ENV/frames: two frames exist before the reset (preamble sanity), have " +
              std::to_string(session.frames.size()));
    (void)piet::doexec::executeDoSource("frames reset\n", session, piet::dispatch);
    // Counted rather than `frames.empty()`: runFramesReset skips the name
    // "default" by design (that frame IS the session), so an empty-map
    // assertion would be testing whether the roster happens to carry a
    // "default" row instead of testing the drop.
    size_t survivors = 0;
    std::string surviving;
    for (const auto& [name, path] : session.frames) {
      (void)path;
      if (name == "default") continue;
      ++survivors;
      surviving += (surviving.empty() ? "" : " ") + name;
    }
    check(survivors == 0, "ENV/frames: `frames reset` drops EVERY non-default frame, left " +
                              std::to_string(survivors) + " (" + surviving + ")");
  }

  // --- sleep: milliseconds. Both bounds matter -- a seconds reading would
  // still pass a >= 5ms floor while turning `sleep 200` into three minutes.
  {
    piet::SessionState session(workdir);
    auto t0 = std::chrono::steady_clock::now();
    (void)piet::dispatch("sleep 5", session);
    auto ms = std::chrono::duration_cast<std::chrono::milliseconds>(
                  std::chrono::steady_clock::now() - t0)
                  .count();
    check(ms >= 5, "ENV/sleep: `sleep 5` actually waits -- waited " + std::to_string(ms) + "ms");
    check(ms < 2000, "ENV/sleep: ...in MILLISECONDS, not seconds -- waited " +
                         std::to_string(ms) + "ms");
  }

  // --- tset: the pre-Stata-7 spelling, both arities. ---
  {
    piet::SessionState session(workdir);
    (void)piet::doexec::executeDoSource(
        "sysuse fatalities, clear\negen long envpid = group(state)\ntset envpid year\n", session,
        piet::dispatch);
    check(session.panelvar.value_or("<unset>") == "envpid" &&
              session.timevar.value_or("<unset>") == "year",
          "ENV/tset: `tset panelvar timevar` is xtset -- it seeds BOTH, got panelvar=" +
              session.panelvar.value_or("<unset>") + " timevar=" +
              session.timevar.value_or("<unset>"));
  }
  {
    piet::SessionState session(workdir);
    (void)piet::doexec::executeDoSource(
        "sysuse fatalities, clear\nkeep if state == \"al\"\ntset year\n", session, piet::dispatch);
    check(!session.panelvar.has_value() && session.timevar.value_or("<unset>") == "year",
          "ENV/tset: `tset timevar` is tsset -- time only, no panel invented, got panelvar=" +
              session.panelvar.value_or("<unset>") + " timevar=" +
              session.timevar.value_or("<unset>"));
  }

  fs::remove_all(workdir, ec);
}

// AER-SCOPE1 bundle A: the abbreviations the corpus types (forval / forv /
// forvalue / tw / sc / gr / sca de / eret / levels / loc / gl / prog def), plus
// the two commands that exist only under an old name -- `ivreg` and `winsor`.
//
// Sibling of testAerEnvBundle above, and here for the same reason: the
// floors.json rows for `ivreg` and `winsor` are `no_fixture` (the timing corpus
// is absent from this tree), so this function and pangram S25 carry the bundle
// until a --counters batch captures it.
//
// The property under test differs between the two halves, and writing both
// halves the same way is how a bundle like this gets a green gate over a broken
// route. For an ABBREVIATION the question is never "does it run" -- it is "does
// it reach the same handler", so each leg below runs the short spelling AND the
// long one and compares the two results. A truncation wired to a second,
// nearly-right code path passes a run-it-once probe and fails here.
//
// For `ivreg` and `winsor` there is no long spelling to compare against, so
// what those legs pin is the arithmetic. `winsor`'s leg is the sharpest in the
// function on purpose: the cheapest wrong way to land Cox's winsor is to alias
// it onto winsor2, which is a SILENT wrong answer (both commands succeed, both
// write a plausible column, and only the tails differ). At N=100 with p(.01)
// the two disagree by construction -- winsor takes the (h+1)-th ORDER STATISTIC
// and winsor2 interpolates the percentile -- so both are run over the same
// column and both tails are asserted. The winsor2 numbers below are measured,
// not derived: `winsor2 x, cuts(1 99)` over x = 1..100 answers min 1.5 / max
// 99.5 on this binary. If the alias were ever made, the first pair fails; if
// winsor2 itself drifts, the second pair fails.
void testAerAbbrevBundle() {
  std::printf("[selftest] --- AER-SCOPE1 bundle A: forval/forv/forvalue / loc / gl / sca de / "
              "prog def / eret / levels / tw+sc / gr / ivreg / winsor ---\n");
  namespace fs = std::filesystem;
  std::string workdir = (fs::temp_directory_path() / "piet_native_selftest_aerabbrev").u8string();
  std::error_code ec;
  fs::remove_all(workdir, ec);
  fs::create_directories(workdir, ec);

  auto displays = [](const auto& blocks) {
    std::vector<std::string> v;
    for (const auto& b : blocks)
      if (b.is_object() && b.value("type", std::string()) == "display")
        v.push_back(b.value("text", std::string()));
    return v;
  };
  // Guarded rather than returning a bare json: `value()` on a null throws, so
  // an absent block would abort the run instead of failing one check (the trap
  // the BUG-129 graph legs earlier in this file record).
  auto firstOfType = [](const auto& blocks, const std::string& type) -> nlohmann::json {
    for (const auto& b : blocks)
      if (b.is_object() && b.value("type", std::string()) == type) return b;
    return nlohmann::json::object();
  };
  auto anyTextContaining = [](const auto& blocks, const std::string& needle) -> std::string {
    for (const auto& b : blocks) {
      if (!b.is_object()) continue;
      const std::string t = b.value("text", std::string());
      if (!t.empty() && t.find(needle) != std::string::npos) return t;
    }
    return std::string();
  };

  // --- forvalues: the three measured truncations, against the long spelling. ---
  {
    const std::vector<std::pair<std::string, std::string>> kLoopSpellings = {
        {"forvalues", "the unabbreviated spelling, carried as this leg's control"},
        {"forval", "the corpus's most common truncation"},
        {"forv", "the shortest spelling measured in the corpus"},
        {"forvalue", "the one that reads like a typo and is not"},
    };
    for (const auto& kw : kLoopSpellings) {
      piet::SessionState session(workdir);
      const std::string src = "local k = 0\n" + kw.first + " i = 1/4 {\n"
                              "    local k = `k' + 1\n"
                              "}\n";
      auto r = piet::doexec::executeDoSource(src, session, piet::dispatch);
      check(session.eval.locals.get("k", "<unset>") == "4",
            "ABBREV/" + kw.first + ": opens a brace block and runs it FOUR times (" + kw.second +
                "), got k=" + session.eval.locals.get("k", "<unset>"));
      // A truncation that is recognized as a command but not as a loop KEYWORD
      // swallows the `{` line and stops there, which leaves k unset for the
      // reason above and would be indistinguishable from a miscount without
      // this second reading.
      check(!r.stoppedAtReason.has_value(),
            "ABBREV/" + kw.first + ": ...without stopping the do-file, stop=" +
                r.stoppedAtReason.value_or("<none>"));
    }
  }
  {  // Under a prefix: the prefix engine and the brace-block keyword table are
     // two different lookups, and only a prefixed SHORT header crosses them.
    piet::SessionState session(workdir);
    auto r = piet::doexec::executeDoSource("local k = 0\nquietly forval i = 1/4 {\n"
                                           "    local k = `k' + 1\n}\n",
                                           session, piet::dispatch);
    check(session.eval.locals.get("k", "<unset>") == "4",
          "ABBREV/quietly forval: a truncated loop header still opens its block under a prefix, "
          "got k=" + session.eval.locals.get("k", "<unset>"));
    check(!r.stoppedAtReason.has_value(),
          "ABBREV/quietly forval: ...and the do-file does not stop, stop=" +
              r.stoppedAtReason.value_or("<none>"));
  }

  // --- loc / gl: a macro that is defined but does not EXPAND is half-landed. ---
  {
    piet::SessionState session(workdir);
    auto r = piet::doexec::executeDoSource("loc todrop = 3\ngl AER \"codeSTATA\"\n"
                                           "display \"`todrop' $AER\"\n",
                                           session, piet::dispatch);
    auto d = displays(r.blocks);
    check(d.size() == 1 && d[0] == "3 codeSTATA",
          "ABBREV/loc+gl: both short spellings define a macro that EXPANDS -- expected `3 "
          "codeSTATA`, got " + (d.empty() ? std::string("no display at all")
                                          : std::string("`") + d[0] + "`"));
  }

  // --- sca de: `scalar define` with BOTH words truncated. ---
  {
    // Two executeDoSource calls, not one two-line source. anyTextContaining
    // scans EVERY block's `text`, echo blocks included, and the echo of `sca de
    // p = .05` reads ".  sca de p = .05" -- which contains "p =". That echo is
    // not emitted today (dispatcher.cpp's tryCaptureDefinition arm returns a
    // FRESH array on success, so a macro/scalar definition drops the entry echo
    // pushed ahead of it), but that is a property of that arm and not of this
    // assertion. Running the definition in its own call means the check reads
    // `scalar list`'s output and nothing else, whichever way the arm goes.
    piet::SessionState session(workdir);
    (void)piet::doexec::executeDoSource("sca de p = .05\n", session, piet::dispatch);
    auto r = piet::doexec::executeDoSource("scalar list\n", session, piet::dispatch);
    const std::string listed = anyTextContaining(r.blocks, "p =");
    double got = -999.0;
    const auto eq = listed.find("p =");
    if (eq != std::string::npos) {
      try {
        got = std::stod(listed.substr(eq + 3));
      } catch (...) {
      }
    }
    check(std::fabs(got - 0.05) < 1e-12,
          "ABBREV/sca de: `sca de p = .05` defines the scalar `scalar list` then reports -- "
          "expected 0.05, got " +
              (listed.empty() ? std::string("no line naming p") : std::string("`") + listed + "`"));
  }

  // --- capt prog drop / prog def / end: a definition that never runs is worth
  // nothing, so the leg CALLS it. The drop comes first because a replication
  // do-file is expected to be re-runnable inside one session, which is exactly
  // why the corpus writes the pair.
  {
    piet::SessionState session(workdir);
    auto r = piet::doexec::executeDoSource("capt prog drop mht_rw\n"
                                           "prog def mht_rw\n"
                                           "    display \"ABBREV_PROG_RAN\"\n"
                                           "end\n"
                                           "mht_rw\n",
                                           session, piet::dispatch);
    auto d = displays(r.blocks);
    bool ran = false;
    for (const auto& line : d)
      if (line == "ABBREV_PROG_RAN") ran = true;
    check(ran, "ABBREV/prog def: `prog def NAME` ... `end` defines a program that RUNS when called");
    // `capt prog drop` of a program that was never defined must be swallowed by
    // the capture rather than stopping the file -- that first line is the one
    // the corpus always writes and the one that would kill every replication.
    check(!r.stoppedAtReason.has_value(),
          "ABBREV/capt prog drop: dropping a program that does not exist is captured, not fatal, "
          "stop=" + r.stoppedAtReason.value_or("<none>"));
  }

  // --- eret list == ereturn list, output for output. ---
  {
    auto listing = [&](const std::string& verb) -> std::string {
      piet::SessionState session(workdir);
      auto r = piet::doexec::executeDoSource("sysuse fatalities, clear\n"
                                             "regress income beertax\n" + verb + "\n",
                                             session, piet::dispatch);
      for (const auto& b : r.blocks) {
        if (!b.is_object()) continue;
        const std::string t = b.value("text", std::string());
        if (t.find("e(N)") != std::string::npos) return t;
      }
      return std::string();
    };
    const std::string longForm = listing("ereturn list");
    const std::string shortForm = listing("eret list");
    check(!longForm.empty(), "ABBREV/eret: the control (`ereturn list`) prints an e(N) line at all");
    check(shortForm == longForm,
          "ABBREV/eret: `eret list` prints the SAME listing as `ereturn list` -- a short spelling "
          "routed to a second printer is the silent half of this class");
  }

  // --- levels == levelsof, into the same local. ---
  {
    auto levelsInto = [&](const std::string& verb) {
      piet::SessionState session(workdir);
      (void)piet::doexec::executeDoSource("sysuse fatalities, clear\n" + verb +
                                              " year, local(yr)\n",
                                          session, piet::dispatch);
      return session.eval.locals.get("yr", "<unset>");
    };
    const std::string longForm = levelsInto("levelsof");
    const std::string shortForm = levelsInto("levels");
    check(longForm.find("1982") != std::string::npos,
          "ABBREV/levels: the control (`levelsof year, local(yr)`) fills the local, got `" +
              longForm + "`");
    check(shortForm == longForm,
          "ABBREV/levels: `levels` fills the same local with the same levels -- got `" + shortForm +
              "` against `" + longForm + "`");
  }

  // --- tw + sc: inside a twoway layer, `sc` is scatter. TWO layers, because a
  // one-layer probe passes even when the layer list collapses to its head.
  {
    piet::SessionState session(workdir);
    auto r = piet::doexec::executeDoSource("sysuse fatalities, clear\n"
                                           "tw (sc income beertax) (sc income spirits)\n",
                                           session, piet::dispatch);
    auto g = firstOfType(r.blocks, "graph");
    check(g.value("kind", std::string()) == "twoway",
          "ABBREV/tw: `tw (...) (...)` builds a twoway graph block, got kind `" +
              g.value("kind", std::string()) + "`");
    auto layers = g.value("layers", nlohmann::json::array());
    check(layers.size() == 2, "ABBREV/tw: both layers survive, got " +
                                  std::to_string(layers.size()));
    if (layers.size() == 2) {
      check(layers[0].value("kind", std::string()) == "scatter" &&
                layers[1].value("kind", std::string()) == "scatter",
            "ABBREV/sc: `sc` inside a twoway layer IS scatter, got `" +
                layers[0].value("kind", std::string()) + "` and `" +
                layers[1].value("kind", std::string()) + "`");
    }
  }

  // --- gr export: the short spelling of the verb that writes the file. The
  // FILE is the assertion, not the note -- `gr export` that printed a save line
  // over an empty directory is the exact shape a report-only check misses.
  {
    piet::SessionState session(workdir);
    session.eval.cwd = workdir;
    const std::string figure = (fs::path(workdir) / "abbrev_fig.svg").u8string();
    (void)piet::doexec::executeDoSource("sysuse fatalities, clear\n"
                                        "tw (sc income beertax)\n"
                                        "gr export \"" + figure + "\", replace\n",
                                        session, piet::dispatch);
    check(fs::exists(figure) && fs::file_size(figure, ec) > 0,
          "ABBREV/gr: `gr export` actually wrote the file, not just a note about it");
  }

  // --- ivreg == ivregress 2sls, coefficient for coefficient. ---
  {
    auto coefs = [&](const std::string& cmd) {
      piet::SessionState session(workdir);
      auto r = piet::doexec::executeDoSource("sysuse fatalities, clear\n" + cmd + "\n", session,
                                             piet::dispatch);
      std::map<std::string, double> out;
      for (const auto& b : r.blocks) {
        if (!b.is_object() || b.value("type", std::string()) != "estimation") continue;
        for (const auto& row : b.value("coeftable", nlohmann::json::array()))
          if (row.is_object()) out[row.value("name", std::string())] = row.value("b", 0.0);
      }
      return out;
    };
    const auto modern = coefs("ivregress 2sls income (beertax = spirits)");
    const auto legacy = coefs("ivreg income (beertax = spirits)");
    check(!modern.empty(), "IVREG: the control (`ivregress 2sls`) estimated at all");
    check(legacy.size() == modern.size(),
          "IVREG: `ivreg y x (d = z)` returns the same coefficient table SHAPE as `ivregress 2sls "
          "y x (d = z)` -- got " + std::to_string(legacy.size()) + " rows against " +
              std::to_string(modern.size()));
    for (const auto& row : modern) {
      const auto it = legacy.find(row.first);
      if (it == legacy.end()) {
        check(false, "IVREG: `ivreg` is missing the row `" + row.first + "` the modern spelling "
                     "returns");
        continue;
      }
      // RELATIVE, not absolute: |b| is ~2.4e4 here, so an absolute 1e-12 sits
      // below the double's own ULP at that magnitude and would be pinning
      // bit-identity while claiming a tolerance. Same handler and same data
      // should in fact give bit-identity; this states the weaker claim it can
      // honestly certify, and it is still ~4 orders tighter than any real
      // numeric drift between two estimators.
      const double tol = 1e-12 * std::max(1.0, std::fabs(row.second));
      check(std::fabs(row.second - it->second) <= tol,
            "IVREG: `ivreg` and `ivregress 2sls` agree on b[" + row.first + "] to 1e-12 relative -- "
            "got " + std::to_string(it->second) + " against " + std::to_string(row.second));
    }
  }

  // --- winsor is Cox's, and it is NOT winsor2. ---
  {
    auto tails = [&](const std::string& cmd, const std::string& col) {
      piet::SessionState session(workdir);
      auto r = piet::doexec::executeDoSource("clear\nset obs 100\ngen double x = _n\n" + cmd +
                                                 "\nsummarize " + col + "\n",
                                             session, piet::dispatch);
      auto s = firstOfType(r.blocks, "summarize").value("stats", nlohmann::json::object());
      auto one = s.is_object() ? s.value(col, nlohmann::json::object())
                               : nlohmann::json::object();
      return std::make_pair(one.value("min", -999.0), one.value("max", -999.0));
    };
    // h = floor(100 * .01) = 1, so the single lowest value is replaced by the
    // 2nd order statistic and the single highest by the 99th. Those ARE 2 and
    // 99 in 1..100 -- exact, because winsor copies an existing observation
    // rather than computing a new number.
    const auto cox = tails("winsor x, gen(xw) p(.01)", "xw");
    check(cox.first == 2.0,
          "WINSOR: Cox's winsor clamps the low tail to the ORDER STATISTIC 2, not to an "
          "interpolated 1.5 -- got " + std::to_string(cox.first));
    check(cox.second == 99.0,
          "WINSOR: ...and the high tail to the order statistic 99, not to 99.5 -- got " +
              std::to_string(cox.second));
    // The other half of the discriminator. Without it, an alias of BOTH
    // commands onto one implementation could still pass the pair above.
    const auto lian = tails("winsor2 x, cuts(1 99)", "x_w");
    check(lian.first == 1.5 && lian.second == 99.5,
          "WINSOR: winsor2 still INTERPOLATES over the same column (1.5 / 99.5, measured) -- if "
          "this moved to 2 / 99 the two commands have been collapsed onto one, got " +
              std::to_string(lian.first) + " / " + std::to_string(lian.second));
  }

  // --- the honest-rejection half. The campaign's wiring checklist owes one per
  // bundle (item 13) and this bundle had none: every leg above asserts that a
  // command RUNS, which is the half a handler that accepts anything also passes.
  // Each line names a DIFFERENT gate in runWinsorCox, and each asserts the same
  // two things. The second is the load-bearing one: a refusal that still wrote
  // the column is the silent shape this whole bundle exists to keep out, and an
  // error block alone cannot tell the two apart (the block is emitted either
  // way). The setup runs in its OWN executeDoSource call because `gen double x`
  // emits a data_mutation of its own, which would satisfy the scan below no
  // matter what winsor did.
  {
    const std::vector<std::pair<std::string, std::string>> kRefusals = {
        {"winsor x, gen(xw)", "neither p() nor h(): winsor.ado has no default tail"},
        {"winsor x, gen(xw) p(.1) h(3)", "p() and h() name two different tails at once"},
        {"winsor x, gen(xw) p(.6)", "p() outside 0 < p < 0.5 crosses the two tails"},
        {"winsor x, gen(xw) p(.1) highonly lowonly", "both -only flags together clamp nothing"},
        {"winsor x, p(.1)", "no gen(): there is no replace mode, so the name is required"},
        {"winsor x, gen(xw) p(.1) cuts(1 99)", "cuts() is winsor2's option, not winsor's"},
    };
    for (const auto& rf : kRefusals) {
      piet::SessionState session(workdir);
      (void)piet::doexec::executeDoSource("clear\nset obs 100\ngen double x = _n\n", session,
                                          piet::dispatch);
      auto r = piet::doexec::executeDoSource(rf.first + "\n", session, piet::dispatch);
      check(!firstOfType(r.blocks, "error").empty(),
            "WINSOR REFUSE: `" + rf.first + "` is refused -- " + rf.second);
      bool wrote = false;
      for (const auto& b : r.blocks)
        if (b.is_object() && b.value("type", std::string()) == "data_mutation") wrote = true;
      check(!wrote, "WINSOR REFUSE: ...and `" + rf.first +
                        "` wrote NOTHING -- no data_mutation block came back with the refusal");
    }
  }

  fs::remove_all(workdir, ec);
}

// Sibling of testAerAbbrevBundle above, and here for the same reason: all four
// floors.json rows of AER bundle B are `no_fixture` (two because there is no
// dataset quantity to floor, two because the timing corpus is absent from this
// tree), so this function, pangram S26 and internal capture
// probe_results.do carry the bundle until a --counters batch captures it.
//
// THE HEADLINE PROPERTY IS ONE LINE OF BEHAVIOUR AND IT IS INVISIBLE TO EVERY
// OTHER GATE. At the TOP LEVEL `return scalar`/`return local` now set r()
// IMMEDIATELY. Before this bundle every form staged, and a staged store still
// prints a perfectly healthy `return list` while `display r(q)` reads nothing --
// so each of the first two legs reads the value TWICE, once through the listing
// and once through an expression, and it is the SECOND reading that fails on a
// half-landed store. A run-it-once probe passes either way.
//
// The in-program half is the mirror, and it is asserted NEGATIVELY on purpose:
// inside a program `return scalar` must STILL stage (Stata's behaviour, and the
// half the top-level change must not have broken). The in-body read is wrapped
// in `capture noisily` and the check is "the value is not visible YET" rather
// than "the display prints missing", because an engine that refuses an unset
// r() reference and one that prints a dot both satisfy the property under test;
// only printing 7 is the regression. The leg cannot pass vacuously -- the
// after-the-call reading pins 7 positively, so a program that never ran fails.
//
// svmat and mkmat are asserted as a ROUND TRIP rather than one at a time. Each
// alone can only be checked against numbers this function itself wrote, which a
// handler that ignored its input would also produce; composed, the columns have
// to come back.
//
// Deliberately NOT asserted anywhere below: the number of blocks. Every
// dispatched line also emits an echo block, so a block count measures the echo
// (an earlier bundle in this campaign learned that). Every check here reads
// block CONTENT.
void testAerResultsBundle() {
  std::printf("[selftest] --- AER-SCOPE1 bundle B: return list/scalar/local/clear / svmat / "
              "mkmat / matlist ---\n");
  namespace fs = std::filesystem;
  std::string workdir = (fs::temp_directory_path() / "piet_native_selftest_aerresults").u8string();
  std::error_code ec;
  fs::remove_all(workdir, ec);
  fs::create_directories(workdir, ec);

  auto displays = [](const auto& blocks) {
    std::vector<std::string> v;
    for (const auto& b : blocks)
      if (b.is_object() && b.value("type", std::string()) == "display")
        v.push_back(b.value("text", std::string()));
    return v;
  };
  // Guarded rather than returning a bare json: `value()` on a null throws, so
  // an absent block would abort the run instead of failing one check (the trap
  // the BUG-129 graph legs earlier in this file record).
  auto firstOfType = [](const auto& blocks, const std::string& type) -> nlohmann::json {
    for (const auto& b : blocks)
      if (b.is_object() && b.value("type", std::string()) == type) return b;
    return nlohmann::json::object();
  };
  // The printed output with the COMMAND ECHO removed. Filtered on the text's
  // own leading '.' rather than on the block type, because this bundle's
  // printers reuse runEreturnList's "echo"-typed block (handlers.h says so in
  // as many words) -- a type filter would throw away the output itself. The
  // ereturn-shaped listings open with a newline, so they survive the filter.
  auto renderText = [](const auto& blocks) {
    std::string out;
    for (const auto& b : blocks) {
      if (!b.is_object()) continue;
      const std::string t = b.value("text", std::string());
      if (t.empty() || t[0] == '.') continue;
      out += t;
      out += "\n";
    }
    return out;
  };
  // The one LINE carrying `needle`, so a check on r(q)'s value cannot be
  // satisfied by a different row of the same listing.
  auto lineWith = [](const std::string& text, const std::string& needle) {
    const size_t at = text.find(needle);
    if (at == std::string::npos) return std::string();
    size_t b = text.rfind('\n', at);
    b = (b == std::string::npos) ? size_t(0) : b + 1;
    const size_t e = text.find('\n', at);
    return text.substr(b, (e == std::string::npos ? text.size() : e) - b);
  };
  auto numberAfter = [](const std::string& line, const std::string& sep) -> double {
    const size_t at = line.find(sep);
    if (at == std::string::npos) return std::nan("");
    try {
      return std::stod(line.substr(at + sep.size()));
    } catch (...) {
      return std::nan("");
    }
  };
  // `display "TAG=" expr` prints "TAG=<value>" with no separating space (the
  // shape BUG-167's leg above pins). Parsed as a NUMBER rather than compared as
  // a string so a formatting choice ("5" against "5.0000") cannot fail a check
  // about arithmetic.
  auto displayValue = [&](const auto& blocks, const std::string& prefix) -> double {
    for (const auto& s : displays(blocks)) {
      if (s.rfind(prefix, 0) != 0) continue;
      try {
        return std::stod(s.substr(prefix.size()));
      } catch (...) {
        return std::nan("");
      }
    }
    return std::nan("");
  };
  auto sawDisplayExactly = [&](const auto& blocks, const std::string& want) {
    for (const auto& s : displays(blocks))
      if (s == want) return true;
    return false;
  };
  auto varCount = [](piet::SessionState& session) {
    const nlohmann::ordered_json blocks = piet::dispatch("describe", session);
    for (const auto& b : blocks)
      if (b.is_object() && b.value("type", std::string()) == "describe" && b.contains("variables"))
        return static_cast<int>(b["variables"].size());
    return -1;
  };
  auto exec = [](const std::string& src, piet::SessionState& session) {
    return piet::doexec::executeDoSource(src, session, piet::dispatch);
  };
  auto sawCode = [](const auto& blocks, const std::string& code) {
    for (const auto& b : blocks)
      if (b.is_object() && b.value("type", std::string()) == "error" &&
          b.value("code", std::string()) == code)
        return true;
    return false;
  };

  // --- TOP-LEVEL `return scalar` / `return local` are REFUSED (BUG-423). ---
  //
  // This leg used to assert the opposite: that a top-level `return scalar` set
  // r() immediately. That came from an unmeasured comment in program.cpp, and
  // bundle B's own wave pin measured StataBE 19.5 answering **r(151)**, "non
  // r-class program may not set r()". The 2026-09-06 ruling is to match Stata
  // (accepting what Stata refuses is the one direction that silently produces a
  // do-file which cannot run there), so the leg now pins the refusal -- and,
  // just as importantly, pins that r() is NOT quietly set behind it.
  {
    piet::SessionState session(workdir);
    // Separate executeDoSource calls, not one source: every scan here reads
    // every block, and the ECHO of `display r(q)` contains the literal "r(q)",
    // so a one-call read could pass on the echo of the line under test.
    const auto refused = exec("return scalar q = 5\n", session);
    // The sentence lives in the error block's `message`, not in rendered text —
    // renderText reads `text`, which an error block does not carry.
    const auto msgOf = [](const auto& blocks) {
      for (const auto& b : blocks)
        if (b.is_object() && b.value("type", std::string()) == "error")
          return b.value("message", std::string());
      return std::string();
    };
    const std::string rtext = msgOf(refused.blocks);
    check(rtext.find("non r-class program may not set r()") != std::string::npos,
          "RESULTS/return scalar: a TOP-LEVEL `return scalar q = 5` is REFUSED with Stata's own "
          "sentence (r(151)) -- got `" + rtext + "`");
    const std::string listing = renderText(exec("return list\n", session).blocks);
    check(lineWith(listing, "r(q)").empty(),
          "RESULTS/return scalar: ...and r(q) is NOT set behind the refusal -- an error that still "
          "wrote the value would be the worst of both. Got `" + listing + "`");
  }
  {
    piet::SessionState session(workdir);
    const auto msgOf = [](const auto& blocks) {
      for (const auto& b : blocks)
        if (b.is_object() && b.value("type", std::string()) == "error")
          return b.value("message", std::string());
      return std::string();
    };
    const std::string rtext = msgOf(exec("return local w abc\n", session).blocks);
    check(rtext.find("non r-class program may not set r()") != std::string::npos,
          "RESULTS/return local: the macro twin is refused the same way -- the two stores went "
          "immediate together and they are refused together. Got `" + rtext + "`");
    const std::string listing = renderText(exec("return list\n", session).blocks);
    check(lineWith(listing, "r(w)").empty(),
          "RESULTS/return local: ...and r(w) is unset behind it. Got `" + listing + "`");
  }

  // --- inside a program the SAME statements must still stage. ---
  {
    piet::SessionState session(workdir);
    auto r = exec("program define aer_b_stage, rclass\n"
                  "    return scalar z = 7\n"
                  "    capture noisily display \"AER_INPROG=\" r(z)\n"
                  "end\n"
                  "aer_b_stage\n"
                  "display \"AER_AFTER=\" r(z)\n",
                  session);
    check(!r.stoppedAtReason.has_value(),
          "RESULTS/in-program: the rclass program runs to its end, stop=" +
              r.stoppedAtReason.value_or("<none>"));
    check(!sawDisplayExactly(r.blocks, "AER_INPROG=7"),
          "RESULTS/in-program: `return scalar z = 7` INSIDE a program still STAGES -- the value "
          "must NOT be readable before the program returns. This is Stata in both places, and it "
          "is the half the top-level change must not have taken with it");
    check(sawDisplayExactly(r.blocks, "AER_AFTER=7"),
          "RESULTS/in-program: ...and it IS readable once the program returns -- without this "
          "positive reading the negative check above passes on a program that never ran at all");
  }

  // --- return clear empties BOTH stores. ---
  {
    piet::SessionState session(workdir);
    (void)exec("return scalar q = 5\n", session);
    (void)exec("return local w abc\n", session);
    (void)exec("return clear\n", session);
    const std::string listing = renderText(exec("return list\n", session).blocks);
    check(listing.find("r(q)") == std::string::npos,
          "RESULTS/return clear: the SCALAR store is empty afterwards -- got `" + listing + "`");
    check(listing.find("r(w)") == std::string::npos,
          "RESULTS/return clear: ...and the MACRO store with it. Two stores, and a clear that "
          "reached only one is the half-landing shape again -- got `" + listing + "`");
  }

  // --- svmat with NO dataset: this is how Stata builds a dataset FROM a
  // matrix, so a no-data refusal here is the defect rather than the guard.
  {
    piet::SessionState session(workdir);
    auto mat = exec("matrix A = (1,2\\3,4\\5,6)\n", session);
    // Read FIRST, and it is not defensive padding. MEASURED on the shipped
    // binary: `matrix A = (1,2\3,4\5,6)` with nothing in memory answers
    // no_data_loaded and STOPS the do-file, because the dispatcher's
    // kNoDataCommands set carries `svmat` and `matlist` but not `matrix`. Every
    // check under this one would then read as "svmat did nothing" while the real
    // cause is one line upstream, so the cause is asserted where it happens.
    check(!sawCode(mat.blocks, "no_data_loaded"),
          "RESULTS/svmat no-data: the `matrix A = ...` that FEEDS svmat is itself reachable with "
          "nothing in memory -- svmat sitting in the no-data allowlist buys nothing while the only "
          "way to build its input does not");
    auto r = exec("svmat A\n"
                  "display \"AER_N=\" _N\n"
                  "display \"AER_A13=\" A1[3]\n"
                  "display \"AER_A22=\" A2[2]\n",
                  session);
    check(std::fabs(displayValue(r.blocks, "AER_N=") - 3.0) < 1e-12,
          "RESULTS/svmat no-data: `svmat A` over a 3x2 matrix with no dataset sets _N to 3");
    check(std::fabs(displayValue(r.blocks, "AER_A13=") - 5.0) < 1e-12,
          "RESULTS/svmat no-data: ...and A1[3] is the matrix's own (3,1) cell, 5");
    check(std::fabs(displayValue(r.blocks, "AER_A22=") - 4.0) < 1e-12,
          "RESULTS/svmat no-data: ...and A2[2] is 4 -- the SECOND column, so a route that wrote "
          "column 1 twice moves this rather than passing quietly");
  }

  // --- names(col) reads the matrix's COLUMN names. ---
  {
    piet::SessionState session(workdir);
    auto r = exec("sysuse fatalities, clear\n"
                  "matrix B = (1,2\\3,4)\n"
                  "matrix colnames B = alpha beta\n"
                  "svmat B, names(col)\n"
                  "display \"AER_ALPHA=\" alpha[2]\n"
                  "display \"AER_BETA=\" beta[1]\n",
                  session);
    check(std::fabs(displayValue(r.blocks, "AER_ALPHA=") - 3.0) < 1e-12,
          "RESULTS/svmat names(col): the variables are named from the matrix COLUMN names, so "
          "alpha[2] reads 3. A silently-ignored option makes B1/B2 instead and this reads nothing "
          "-- which is why the check is on the NAMED column, not on the values");
    check(std::fabs(displayValue(r.blocks, "AER_BETA=") - 2.0) < 1e-12,
          "RESULTS/svmat names(col): ...and beta[1] reads 2, the second column's first cell");
  }

  // --- a name collision refuses, and refuses having created NOTHING. ---
  {
    piet::SessionState session(workdir);
    (void)exec("clear\nset obs 3\ngen double A1 = 99\nmatrix A = (1,2\\3,4\\5,6)\n", session);
    const int before = varCount(session);
    // svmat in its OWN call: the setup's `gen` emits a data_mutation of its own
    // and the counts below would then be reading the setup.
    auto r = exec("svmat A\n", session);
    check(!firstOfType(r.blocks, "error").empty(),
          "RESULTS/svmat collision: `svmat A` is REFUSED when the target name A1 is already taken");
    const int after = varCount(session);
    check(before > 0 && after == before,
          "RESULTS/svmat collision: ...and it created NOTHING. A refusal that had already made A2 "
          "before reaching A1 is the silent half of this class and an error block alone cannot "
          "tell the two apart -- got " + std::to_string(before) + " variables before, " +
              std::to_string(after) + " after");
    check(std::fabs(displayValue(exec("display \"AER_KEPT=\" A1[1]\n", session).blocks,
                                 "AER_KEPT=") -
                    99.0) < 1e-12,
          "RESULTS/svmat collision: ...and the EXISTING A1 still holds 99, not the matrix's 1");
  }

  // --- mkmat is svmat's inverse, and the pair is asserted as a ROUND TRIP. ---
  {
    piet::SessionState session(workdir);
    (void)exec("clear\nset obs 3\ngen double xx = _n\ngen double yy = _n * 2\n"
               "mkmat xx yy, matrix(RT)\n",
               session);
    auto r = exec("svmat RT\n"
                  "display \"AER_RT11=\" RT1[1]\n"
                  "display \"AER_RT13=\" RT1[3]\n"
                  "display \"AER_RT23=\" RT2[3]\n",
                  session);
    check(std::fabs(displayValue(r.blocks, "AER_RT11=") - 1.0) < 1e-12,
          "RESULTS/mkmat round trip: xx -> matrix -> RT1 returns xx[1] == 1");
    check(std::fabs(displayValue(r.blocks, "AER_RT13=") - 3.0) < 1e-12,
          "RESULTS/mkmat round trip: ...and xx[3] == 3, so the column arrived whole rather than "
          "as its first cell repeated");
    check(std::fabs(displayValue(r.blocks, "AER_RT23=") - 6.0) < 1e-12,
          "RESULTS/mkmat round trip: ...and yy[3] == 6 came back as the SECOND column -- the "
          "reading a transposed or single-column matrix fails and two separate one-command "
          "checks would not");
  }

  // --- nomissing drops LISTWISE, which is a different answer from truncating. ---
  {
    piet::SessionState session(workdir);
    auto r = exec("clear\nset obs 3\ngen double xx = _n\ngen double yy = _n * 2\n"
                  "replace yy = . in 2\n"
                  "mkmat xx yy, matrix(NM) nomissing\n"
                  "display \"AER_NMROWS=\" rowsof(NM)\n"
                  "display \"AER_NM21=\" NM[2,1]\n",
                  session);
    check(std::fabs(displayValue(r.blocks, "AER_NMROWS=") - 2.0) < 1e-12,
          "RESULTS/mkmat nomissing: the observation whose yy is missing is dropped -- 3 in, 2 out");
    check(std::fabs(displayValue(r.blocks, "AER_NM21=") - 3.0) < 1e-12,
          "RESULTS/mkmat nomissing: ...and it is the MIDDLE observation that went, so matrix row "
          "2 carries observation 3 (xx == 3). A handler that dropped the LAST row instead would "
          "answer 2 rows here too and read 2 for this cell");
  }

  // --- a string variable has no cell in a matrix, and the refusal says which. ---
  {
    piet::SessionState session(workdir);
    (void)exec("clear\nset obs 3\ngen double xx = _n\ngen str6 sname = \"ab\"\n", session);
    auto r = exec("mkmat xx sname, matrix(SM)\n", session);
    auto err = firstOfType(r.blocks, "error");
    check(!err.empty(),
          "RESULTS/mkmat string: a string variable in the varlist is REFUSED -- accepting it "
          "would write a column of missing and call it data");
    const std::string smsg = err.value("message", std::string());
    check(smsg.find("sname") != std::string::npos,
          "RESULTS/mkmat string: ...and the message NAMES the variable, which is the difference "
          "between a fixable do-file and a re-run with prints in it -- got `" + smsg + "`");
    // The NAME alone cannot certify this leg. `mkmat: variable sname not found`
    // carries "sname" too, and that is what this leg reads if the setup's
    // `gen str6` ever stops making a column -- a refusal for the wrong reason,
    // certifying a string path that was never walked. The wording is the
    // discriminator, and it is load-bearing twice over: the handler states
    // r(109) through `reason` because coarseRc has no message rule for this
    // phrase, so a rewrite that dropped the phrase would also have to keep the
    // explicit rc.
    check(smsg.find("string variable") != std::string::npos,
          "RESULTS/mkmat string: ...and it is refused AS A STRING rather than as a missing "
          "variable -- `variable sname not found` names sname too and would satisfy the check "
          "above while proving the string path was never reached. Got `" + smsg + "`");
  }

  // --- matlist renders; `matrix list` already prints numbers. ---
  {
    piet::SessionState session(workdir);
    (void)exec("sysuse fatalities, clear\n"
               "matrix C = (1,2\\3,4)\n"
               "matrix rownames C = rowa rowb\n"
               "matrix colnames C = cola colb\n",
               session);
    const std::string plain = renderText(exec("matlist C\n", session).blocks);
    for (const char* stub : {"rowa", "rowb", "cola", "colb"}) {
      check(plain.find(stub) != std::string::npos,
            std::string("RESULTS/matlist: the rendering carries the stub `") + stub +
                "` -- BOTH row names and BOTH column names, because a printer that emitted only "
                "the numbers is what `matrix list` already does. Got `" + plain + "`");
    }
    const std::string fmt = renderText(exec("matlist C, format(%9.3f)\n", session).blocks);
    check(fmt != plain,
          "RESULTS/matlist format(): format(%9.3f) CHANGES the rendering. The command echo is "
          "filtered out of both strings, so this compares OUTPUT and not command text -- an "
          "option parsed and then dropped leaves these two identical");
    check(fmt.find("1.000") != std::string::npos,
          "RESULTS/matlist format(): ...to three decimals -- got `" + fmt + "`");
  }

  // --- the honest-rejection half, one line per command of the bundle. The
  // campaign's wiring checklist owes one per bundle, and an unknown option is
  // the sharpest one available here: a command missing from its option
  // vocabulary ACCEPTS the token and then ignores it, which is a silent wrong
  // answer wearing a green gate. The code is asserted as well as the block,
  // because eval::coarseRc answers r(198) for `unsupported_option` and turns a
  // refusal carrying the default engine_error code into rc 1 instead.
  {
    const std::vector<std::pair<std::string, std::string>> kBogus = {
        {"return list, floob", "`return list` takes `all` and nothing else"},
        {"svmat A, floob", "svmat takes a type and names(), and floob is neither"},
        {"mkmat xx yy, matrix(BM) floob", "floob is not one of mkmat's own options"},
        {"matlist C, floob", "matlist takes format() and its siblings"},
    };
    for (const auto& bg : kBogus) {
      piet::SessionState session(workdir);
      (void)exec("clear\nset obs 3\ngen double xx = _n\ngen double yy = _n * 2\n"
                 "matrix A = (1,2\\3,4\\5,6)\nmatrix C = (1,2\\3,4)\n",
                 session);
      auto r = exec(bg.first + "\n", session);
      auto err = firstOfType(r.blocks, "error");
      check(!err.empty(), "RESULTS REFUSE: `" + bg.first + "` is refused -- " + bg.second);
      check(err.value("code", std::string()) == "unsupported_option",
            "RESULTS REFUSE: ...under the `unsupported_option` code, the one eval::coarseRc maps "
            "to r(198) -- got `" + err.value("code", std::string()) + "`");
    }
  }

  fs::remove_all(workdir, ec);
}

// Sibling of testAerResultsBundle above, and here for the same reason: all ten
// floors.json rows of AER bundle C are `no_fixture` (the floor VALUE has to be
// captured on the post-merge binary), so this function, pangram S27, three
// freeze_extra.do stanzas and internal script probe_gtools.do carry the
// bundle until a --counters batch captures it.
//
// THE SHARPEST ASSERTION AVAILABLE FOR THIS BUNDLE IS EQUIVALENCE, so it leads.
// Every row here is an ALIAS: `gcollapse` is not a new answer, it is `collapse`
// under the name a gtools user already types. That makes the property testable
// in a way an ordinary feature is not -- run the alias and the native command
// in two FRESH sessions over the same data and the blocks that come back must
// be IDENTICAL. A per-command "does it work" check passes on a shim that
// dropped an option, reordered a by(), or forwarded to a neighbouring handler.
// The identity does not.
//
// WHAT THE COMPARISON IGNORES, AND WHY EXACTLY TWO THINGS. (1) The command
// ECHO, filtered on the text's own leading '.' -- the same rule renderText uses
// in testAerResultsBundle above, and for the same reason: some printers reuse
// the "echo" block TYPE for real output, so a type filter would throw away the
// thing under test. (2) The alias SPELLING itself, rewritten to the native
// spelling before the compare, because a block that records which command
// produced it would otherwise differ on the one byte an alias is entitled to
// differ on. Everything else must match byte for byte.
//
// EVERY EQUIVALENCE LEG ALSO ASSERTS ITS SIGNATURE IS NON-EMPTY. Two commands
// that both did nothing at all compare equal, and an equality check that can be
// satisfied by silence is the empty-golden shape -- it certifies the handler
// that stopped working. `gisid` is silent on success, so its equivalence is
// taken on the REFUSING form (a duplicated key), where there is output to
// compare; its success form is asserted separately as "no error block".
//
// Deliberately NOT asserted anywhere below: the number of blocks. Every
// dispatched line also emits an echo, so a block count measures the echo (an
// earlier bundle in this campaign learned that). Every check here reads block
// CONTENT.
//
// THE OPTION LEGS ARE THE ONES THAT CATCH THE DEFECT THIS CAMPAIGN SHIPPED. A
// gtools option is one of three kinds and each has its own correct outcome, so
// each has its own leg. `fast` describes only SPEED and is DROPPED -- asserted
// as "the result is identical with and without it", because an option that was
// accepted as an unknown prefix and then ignored also returns rc 0, which is
// how `ivreg, ro` once ran WITHOUT robust standard errors and reported no
// problem. `nq()` is a RENAME of `nquantiles()` -- asserted by VALUE against
// summarize's own p25, because an option dropped on the floor falls back on the
// engine default and still returns rc 0. `merge` would change the ANSWER and is
// REFUSED -- asserted on the code AND on the rc, because eval::coarseRc answers
// 199 only for code == "unsupported_command" or a reason spelled "r(NNN)", so a
// refusal built with the default engine_error code arrives as rc 1 and a
// do-file branching on 199 silently takes the other branch.
void testAerGtoolsBundle() {
  std::printf("[selftest] --- AER-SCOPE1 bundle C: gtools/ftools aliases == their native "
              "commands; dropped/renamed/refused options ---\n");
  namespace fs = std::filesystem;
  std::string workdir = (fs::temp_directory_path() / "piet_native_selftest_aergtools").u8string();
  std::error_code ec;
  fs::remove_all(workdir, ec);
  fs::create_directories(workdir, ec);

  auto exec = [](const std::string& src, piet::SessionState& session) {
    return piet::doexec::executeDoSource(src, session, piet::dispatch);
  };
  // Returns a NULL json when there is no error block rather than a bare
  // `value()` on nothing, which throws and would abort the whole run instead of
  // failing one check (the BUG-129 trap the graph legs earlier in this file
  // record). ordered_json rather than json because eval::coarseRc takes that.
  auto firstError = [](const nlohmann::ordered_json& blocks) -> nlohmann::ordered_json {
    for (const auto& b : blocks)
      if (b.is_object() && b.value("type", std::string()) == "error") return b;
    return nlohmann::ordered_json();
  };
  auto displays = [](const auto& blocks) {
    std::vector<std::string> v;
    for (const auto& b : blocks)
      if (b.is_object() && b.value("type", std::string()) == "display")
        v.push_back(b.value("text", std::string()));
    return v;
  };
  auto displayValue = [&](const auto& blocks, const std::string& prefix) -> double {
    for (const auto& s : displays(blocks)) {
      if (s.rfind(prefix, 0) != 0) continue;
      try {
        return std::stod(s.substr(prefix.size()));
      } catch (...) {
        return std::nan("");
      }
    }
    return std::nan("");
  };
  // The comparable part of a block list: see this function's header for the
  // two exclusions and why there are exactly two.
  auto signature = [](const nlohmann::ordered_json& blocks, const std::string& alias,
                      const std::string& native) {
    std::string out;
    for (const auto& b : blocks) {
      if (!b.is_object()) continue;
      const std::string t = b.value("text", std::string());
      if (!t.empty() && t[0] == '.') continue;
      out += b.dump();
      out += "\n";
    }
    if (!alias.empty()) {
      size_t at = 0;
      while ((at = out.find(alias, at)) != std::string::npos) {
        out.replace(at, alias.size(), native);
        at += native.size();
      }
    }
    return out;
  };
  const std::string kLoad = "sysuse fatalities, clear\n";
  // The setup runs in its OWN call in every leg below, so the signatures being
  // compared hold the TARGET line's blocks and not `sysuse`'s.
  auto runFresh = [&](const std::string& setup, const std::string& line) {
    piet::SessionState session(workdir);
    if (!setup.empty()) (void)exec(setup, session);
    return exec(line, session);
  };

  // --- four of the five equivalence legs. alias == native, block for block.
  // The fifth is `gisid`, and it is separate below rather than in this table
  // because it is SILENT on success: a table-driven identity over two empty
  // block lists would pass on two handlers that had both stopped working.
  {
    // {alias name, native name, alias line, native line}. A vector of vectors
    // rather than std::array because <array> is not among this file's includes
    // and this lane may not add one.
    //
    // The native NAME is written out rather than derived by stripping the
    // leading g/f, and that is not verbosity: it happens to work for these four
    // and it is wrong for the rest of the bundle -- `gquantiles`'s native
    // command is `xtile`, `gstats`'s is two commands, and a derived name would
    // have silently rewritten the wrong token in the signature the moment
    // either was added to this table.
    const std::vector<std::vector<std::string>> kPairs = {
        {"gcollapse", "collapse", "gcollapse (mean) fatal beertax, by(state)\n",
         "collapse (mean) fatal beertax, by(state)\n"},
        {"gegen", "egen", "gegen gm = mean(fatal), by(state)\n",
         "egen gm = mean(fatal), by(state)\n"},
        {"gduplicates", "duplicates", "gduplicates report state\n", "duplicates report state\n"},
        {"glevelsof", "levelsof", "glevelsof state, local(lv)\n", "levelsof state, local(lv)\n"},
    };
    for (const auto& p : kPairs) {
      const std::string alias = p[0];
      const std::string native = p[1];
      const auto aRun = runFresh(kLoad, p[2]);
      const auto bRun = runFresh(kLoad, p[3]);
      const std::string aSig = signature(aRun.blocks, alias, native);
      const std::string bSig = signature(bRun.blocks, std::string(), std::string());
      // Non-empty is NOT enough on its own: an error block is output too, so
      // two identical FAILURES satisfy both the emptiness guard and the
      // identity below. That is the same unfalsifiable shape the emptiness
      // guard exists to close, arriving from the other side -- so the four
      // legs in this table (all of which are supposed to SUCCEED) assert the
      // absence of an error on both sides first. `gisid` is exactly the leg
      // that cannot make this assertion, which is why it is not in this table.
      //
      // errText, not `firstError(...).value("message", ...)` inline: check()'s
      // message argument is built EAGERLY, on the passing path too, and
      // nlohmann's value() on a NULL json throws type_error.306 rather than
      // returning the default -- which would abort the run on every GREEN pass.
      auto errText = [](const nlohmann::ordered_json& e) {
        return e.is_object() ? e.value("message", std::string()) : std::string("<none>");
      };
      check(firstError(aRun.blocks).is_null(),
            "GTOOLS EQUIV: `" + alias + "` SUCCEEDS on this data -- the identity below is "
            "satisfied by two identical failures, so the failure case is ruled out here. Got `" +
                errText(firstError(aRun.blocks)) + "`");
      check(firstError(bRun.blocks).is_null(),
            "GTOOLS EQUIV: ...and so does the native `" + native +
                "`, so the pair being compared is two commands that both reached an answer. Got `" +
                errText(firstError(bRun.blocks)) + "`");
      check(!aSig.empty(), "GTOOLS EQUIV: `" + alias +
                               "` returns SOMETHING to compare -- an equality check between two "
                               "empty block lists certifies a handler that did nothing");
      check(aSig == bSig,
            "GTOOLS EQUIV: `" + alias + "` returns exactly what `" + native +
                "` returns on the same data. Alias name and command echo aside, every block must "
                "match -- a shim that dropped an option or reordered by() differs HERE while "
                "still answering rc 0. Got alias `" + aSig + "` vs native `" + bSig + "`");
    }
  }

  // --- gisid: silent on success, so equivalence is taken where there IS
  // output. `state` alone repeats across years; `state year` does not.
  {
    auto okAlias = runFresh(kLoad, "gisid state year\n");
    auto okNative = runFresh(kLoad, "isid state year\n");
    check(firstError(okAlias.blocks).is_null(),
          "GTOOLS EQUIV/gisid: `gisid state year` SUCCEEDS -- state-year is the key of this "
          "dataset");
    check(firstError(okNative.blocks).is_null(),
          "GTOOLS EQUIV/gisid: ...and so does the native `isid state year`, so the pair below "
          "compares two commands that are both reaching a real check");
    const std::string aSig = signature(runFresh(kLoad, "gisid state\n").blocks, "gisid", "isid");
    const std::string bSig =
        signature(runFresh(kLoad, "isid state\n").blocks, std::string(), std::string());
    check(!aSig.empty(),
          "GTOOLS EQUIV/gisid: the DUPLICATED-key form produces output -- this is the form the "
          "equivalence is taken on precisely because the success form produces none");
    check(aSig == bSig, "GTOOLS EQUIV/gisid: `gisid state` refuses exactly as `isid state` does. "
                        "Got alias `" + aSig + "` vs native `" + bSig + "`");
  }

  // --- the by-PREFIX form, which the by() option form does not cover: a shim
  // that stripped the prefix along with the name passes every leg above.
  // Synthetic rather than `sysuse`, because two named by-groups with known
  // means make a wrong grouping visible as a wrong NUMBER, not as an error.
  {
    const std::string kSetup = "clear\nset obs 12\ngen double yy = _n\ngen double region = 1\n"
                               "replace region = 2 in 7/12\n";
    const std::string aSig =
        signature(runFresh(kSetup, "bysort region: gegen m = mean(yy)\n").blocks, "gegen", "egen");
    const std::string bSig = signature(runFresh(kSetup, "bysort region: egen m = mean(yy)\n").blocks,
                                       std::string(), std::string());
    check(!aSig.empty(), "GTOOLS EQUIV/bysort: the prefixed form returns something to compare");
    check(aSig == bSig, "GTOOLS EQUIV/bysort: `bysort region: gegen` == `bysort region: egen`. Got "
                        "alias `" + aSig + "` vs native `" + bSig + "`");
    // ...and the grouping is the RIGHT one. Identity above proves the two
    // spellings agree; it cannot prove they are both correct, and two
    // handlers that both ignored the prefix would also agree.
    piet::SessionState session(workdir);
    (void)exec(kSetup, session);
    auto r = exec("bysort region: gegen m = mean(yy)\n"
                  "display \"AER_G1=\" m[1]\n"
                  "display \"AER_G2=\" m[12]\n",
                  session);
    check(std::fabs(displayValue(r.blocks, "AER_G1=") - 3.5) < 1e-12,
          "GTOOLS EQUIV/bysort: the first by-group's mean is 3.5 (rows 1-6 carry 1..6), so the "
          "prefix actually GROUPED -- a prefix consumed and ignored answers 6.5 here");
    check(std::fabs(displayValue(r.blocks, "AER_G2=") - 9.5) < 1e-12,
          "GTOOLS EQUIV/bysort: ...and the second group's is 9.5, so the two groups are distinct "
          "rather than one group repeated");
  }

  // --- a DROPPED option changes nothing. `fast` is speed-only. ---
  {
    const std::string withFast =
        signature(runFresh(kLoad, "gcollapse (mean) fatal beertax, by(state) fast\n").blocks,
                  std::string(), std::string());
    const std::string without =
        signature(runFresh(kLoad, "gcollapse (mean) fatal beertax, by(state)\n").blocks,
                  std::string(), std::string());
    check(!withFast.empty(),
          "GTOOLS DROP/fast: `gcollapse ..., fast` is ACCEPTED and produces a result -- a refusal "
          "here would be the opposite defect from the one this leg is looking for");
    check(withFast == without,
          "GTOOLS DROP/fast: ...and the result is identical to the same line WITHOUT `fast`. That "
          "option describes speed and nothing else, so dropping it is correct and changing the "
          "answer with it is not. Got `" + withFast + "` vs `" + without + "`");
  }

  // --- a REFUSED option refuses, under the code that maps to r(199), and
  // leaves the dataset alone.
  {
    piet::SessionState session(workdir);
    (void)exec(kLoad, session);
    const double before = displayValue(exec("display \"AER_N=\" _N\n", session).blocks, "AER_N=");
    auto r = exec("gcollapse (mean) fatal, by(state) merge\n", session);
    auto err = firstError(r.blocks);
    check(!err.is_null(),
          "GTOOLS REFUSE/merge: `gcollapse ..., merge` is REFUSED. It writes the aggregate back "
          "onto the source rows instead of replacing them, which is a different ANSWER -- an "
          "option in that class must never be dropped quietly");
    // The code is read into a local BEFORE the check: check()'s message is
    // built eagerly, and nlohmann's value() on the NULL json firstError()
    // returns when there is no error block throws type_error.306 -- which
    // would abort the whole run in place of failing this one check. That is
    // the BUG-129 trap firstError() itself was written to avoid, and an
    // inline value() in the message re-opens it on the failing path.
    const std::string code = err.is_object() ? err.value("code", std::string()) : std::string();
    check(code == "unsupported_command",
          "GTOOLS REFUSE/merge: ...under the `unsupported_command` code, got `" + code + "`");
    const std::string reason = err.is_null() ? std::string() : err.value("reason", std::string());
    check(reason.rfind("refused:", 0) == 0,
          "GTOOLS REFUSE/merge: ...with a reason beginning `refused:`, which is what separates an "
          "answer-changing option from an unimplemented one in this bundle's vocabulary. Got `" +
              reason + "`");
    check(!err.is_null() && piet::eval::coarseRc(err) == "199",
          "GTOOLS REFUSE/merge: ...and it maps to r(199). Asserted separately from the code "
          "because coarseRc answers 199 only for `unsupported_command` or a reason spelled "
          "`r(NNN)`; a refusal built with the default engine_error code arrives as rc 1 and every "
          "do-file branching on 199 takes the wrong branch. Got r(" +
              (err.is_null() ? std::string("<none>") : piet::eval::coarseRc(err)) + ")");
    const double after = displayValue(exec("display \"AER_N=\" _N\n", session).blocks, "AER_N=");
    check(before > 0 && std::fabs(after - before) < 1e-12,
          "GTOOLS REFUSE/merge: ...and it collapsed NOTHING. A refusal that had already aggregated "
          "before it reached the option is the silent half of this class and the error block alone "
          "cannot tell the two apart -- got " + std::to_string(before) + " obs before, " +
              std::to_string(after) + " after");
  }

  // --- gquantiles _pctile fills r(), and the VALUE is the assertion. ---
  {
    piet::SessionState session(workdir);
    (void)exec(kLoad, session);
    // The _pctile form must fill r() and write NO column, so the width is read
    // on both sides of it. A shim that routed _pctile onto the xtile form
    // satisfies every value check below and is caught only here.
    auto varCount = [&](piet::SessionState& s) {
      const nlohmann::ordered_json blocks = piet::dispatch("describe", s);
      for (const auto& b : blocks)
        if (b.is_object() && b.value("type", std::string()) == "describe" &&
            b.contains("variables"))
          return static_cast<int>(b["variables"].size());
      return -1;
    };
    const int widthBefore = varCount(session);
    // r(r1) is READ BEFORE `summarize, detail` runs: summarize refills r() and
    // would overwrite the store this leg is about, so the ordering here is
    // load-bearing rather than stylistic.
    auto r = exec("gquantiles fatal, _pctile nq(4)\n"
                  "display \"AER_R1=\" r(r1)\n"
                  "summarize fatal, detail\n"
                  "display \"AER_P25=\" r(p25)\n",
                  session);
    const double r1 = displayValue(r.blocks, "AER_R1=");
    const double p25 = displayValue(r.blocks, "AER_P25=");
    check(!std::isnan(r1),
          "GTOOLS/_pctile: `gquantiles fatal, _pctile nq(4)` FILLS r(r1) -- an r() store left "
          "empty reads as nothing here while the command still returns rc 0");
    check(!std::isnan(p25) && std::fabs(r1 - p25) < 1e-9,
          "GTOOLS/_pctile: ...and r(r1) IS the 25th percentile `summarize, detail` reports. This "
          "is where `nq(4)` is proved to be a RENAME of `nquantiles(4)` rather than a dropped "
          "token: a dropped option falls back on this handler's own kPctileDefaultNq of 2 and "
          "returns rc 0 while r(r1) becomes the MEDIAN. (BUG-370 runs the other way from the way "
          "it is usually misremembered -- Stata's xtile default is 2 and the ENGINE's is 4, which "
          "is why the shim emits nquantiles() explicitly instead of forwarding as typed.) Got r1=" +
              std::to_string(r1) +
              " p25=" + std::to_string(p25));
    const int widthAfter = varCount(session);
    check(widthBefore > 0 && widthAfter == widthBefore,
          "GTOOLS/_pctile: ...and it wrote NO column. The `_pctile` form fills r() and nothing "
          "else, so a shim that forwarded it to the xtile form leaves one variable more here "
          "while every value check above still passes -- got " + std::to_string(widthBefore) +
              " variables before, " + std::to_string(widthAfter) + " after");
  }

  // --- gstats is a MULTIPLEX, so each arm is checked against ITS OWN native
  // target: winsor against winsor2, by value on both tails.
  {
    const std::string kTails = "summarize fatal_w\n"
                               "display \"AER_MIN=\" r(min)\n"
                               "display \"AER_MAX=\" r(max)\n";
    piet::SessionState sa(workdir);
    (void)exec(kLoad, sa);
    auto a = exec("gstats winsor fatal, cuts(5 95)\n" + kTails, sa);
    piet::SessionState sb(workdir);
    (void)exec(kLoad, sb);
    auto b = exec("winsor2 fatal, cuts(5 95)\n" + kTails, sb);
    const double aMin = displayValue(a.blocks, "AER_MIN=");
    const double aMax = displayValue(a.blocks, "AER_MAX=");
    const double bMin = displayValue(b.blocks, "AER_MIN=");
    const double bMax = displayValue(b.blocks, "AER_MAX=");
    check(!std::isnan(aMin) && !std::isnan(aMax),
          "GTOOLS/gstats winsor: `gstats winsor fatal, cuts(5 95)` writes fatal_w -- the column "
          "has to exist before either tail can be compared");
    check(std::fabs(aMin - bMin) < 1e-9,
          "GTOOLS/gstats winsor: the LOWER tail equals `winsor2 fatal, cuts(5 95)`'s. Both tails "
          "are read because a cuts() that arrived half-parsed clamps one end and leaves the other "
          "alone. Got " + std::to_string(aMin) + " vs " + std::to_string(bMin));
    check(std::fabs(aMax - bMax) < 1e-9,
          "GTOOLS/gstats winsor: ...and the UPPER tail equals it too. Got " + std::to_string(aMax) +
              " vs " + std::to_string(bMax));
  }

  // --- the other gstats arm, and a subcommand this multiplex does not have. ---
  {
    piet::SessionState session(workdir);
    (void)exec(kLoad, session);
    auto sum = exec("gstats sum fatal\ndisplay \"AER_SUMN=\" r(N)\n", session);
    check(firstError(sum.blocks).is_null(),
          "GTOOLS/gstats sum: `gstats sum fatal` reaches summarize rather than the multiplex's "
          "reject arm -- the SUBCOMMAND has to travel with the name");
    check(std::fabs(displayValue(sum.blocks, "AER_SUMN=") - 336.0) < 1e-12,
          "GTOOLS/gstats sum: ...and it fills r(N) with this dataset's 336 observations, so the "
          "arm actually SUMMARIZED rather than merely being accepted");
    auto tab = exec("gstats tab state\n", session);
    auto err = firstError(tab.blocks);
    check(!err.is_null(),
          "GTOOLS/gstats tab: an arm this multiplex does not implement is REFUSED as the whole "
          "command. Accepting the name and ignoring the subcommand is the shape that runs "
          "`gstats tab` as a bare summarize and reports no problem");
    check(!err.is_null() && piet::eval::coarseRc(err) == "199",
          "GTOOLS/gstats tab: ...at r(199), got r(" +
              (err.is_null() ? std::string("<none>") : piet::eval::coarseRc(err)) + ")");
  }

  // --- the community-name gate reaches this bundle too. Pattern read from
  // testExtcompatGate below; what is added here is the ISOLATION. `set
  // extcompat off` moves persisted settings, and a gate that writes the
  // operator's real settings file is the BUG-346 class -- so the store is
  // pointed at this function's own workdir for the duration and the previous
  // value is RESTORED rather than unset, because the harness itself pins
  // PIET_SETTINGS_FILE on some runs and clobbering it would break every case
  // after this one.
  //
  // POSIX-ONLY, and the skip is named rather than left to be discovered: the
  // isolation above needs setenv/unsetenv, so on Windows this leg does not
  // run. What is lost there is the bundle-C-specific half only -- testExtcompat
  // Gate below still exercises `set extcompat off` on every platform, so the
  // gate MECHANISM stays covered and it is this bundle's membership in it that
  // goes unchecked.
#ifndef _WIN32
  {
    const char* prevSettings = std::getenv("PIET_SETTINGS_FILE");
    const std::string savedSettings = prevSettings ? prevSettings : "";
    const std::string ownSettings = (fs::path(workdir) / "settings.json").u8string();
    setenv("PIET_SETTINGS_FILE", ownSettings.c_str(), 1);

    piet::SessionState session(workdir);
    (void)exec(kLoad, session);
    (void)piet::dispatch("set extcompat off", session);
    auto blocks = piet::dispatch("gcollapse (mean) fatal, by(state)", session);
    auto err = firstError(blocks);
    check(!err.is_null() && err.value("code", std::string()) == "unsupported_command" &&
              err.value("token", std::string()) == "gcollapse",
          "GTOOLS/extcompat OFF: a gtools name is gated exactly as `reghdfe` is -- these ten rows "
          "are community spellings and the opt-out has to reach them, or the setting promises an "
          "isolation it does not deliver");
    check(!err.is_null() && piet::eval::coarseRc(err) == "199",
          "GTOOLS/extcompat OFF: ...and the gate maps to r(199)");

    // The env var is restored FIRST, then the cache invalidated, then the
    // process default forced -- in that order. Invalidating AFTER the set
    // would re-resolve the flag from whatever the restored store says and
    // silently undo the restore, which is the same "cache invalidates the
    // test's own proxy" shape a cache introduction cost this project once.
    if (!savedSettings.empty()) {
      setenv("PIET_SETTINGS_FILE", savedSettings.c_str(), 1);
    } else {
      unsetenv("PIET_SETTINGS_FILE");
    }
    piet::settings::invalidateExtcompatCache();
    piet::settings::setExtcompatEnabled(true);
    // The restore is verified by DISPATCHING the name again, not by reading
    // the flag back: the flag was written by the line directly above, so
    // reading it proves the setter works and nothing about the gate. This
    // check has to be able to fail, and the cases after this one inherit
    // whatever it leaves behind.
    auto again = piet::dispatch("gcollapse (mean) fatal, by(state)", session);
    auto againErr = firstError(again);
    check(againErr.is_null() || againErr.value("code", std::string()) != "unsupported_command",
          "GTOOLS/extcompat: ...and once the default is restored the name ANSWERS again, so this "
          "function hands the following cases the state they were written against rather than a "
          "session with the community names still switched off");
  }
#endif

  fs::remove_all(workdir, ec);
}

// ── AER-SCOPE1 bundle E (TABLES, 2026-09-04) ─────────────────────────────────
//
// The pipeline this bundle exists for is `regress -> estadd -> eststo ->
// estout|esttab using f.tex`, and EVERY one of its failure modes is silent:
// a snapshot that carries no estadd bag, a `using` that returns rc 0 and
// writes no file, an `append` that overwrites the column it was asked to add,
// a refusal that has already written the file it refuses to write. An rc-0
// assertion is GREEN for all four.
//
// So no leg below stops at a return code. Each one reads either a VALUE out
// of the stored estimate or BYTES off the disk, and the substrings it looks
// for are the ones a WRONG renderer would not produce -- `\toprule` for
// booktabs, three tab-separated fields on outreg2's VARIABLES row, outreg2's
// own star legend (which differs from estout's and is the cheapest evidence
// that the two commands did not collapse into one renderer's defaults).
//
// Nothing here asserts a PATH. The workdir is this process's temp directory
// and would differ on the operator's machine; what is asserted is the file's
// CONTENT, which is the same everywhere.
void testAerTables() {
  std::printf("[selftest] --- AER-SCOPE1 bundle E: estadd/estpost/estout/esttab-using/outreg2 "
              "+ regsave/erepost + the two refusals ---\n");
  namespace fs = std::filesystem;
  std::string workdir = (fs::temp_directory_path() / "piet_native_selftest_aertables").u8string();
  std::error_code ec;
  fs::remove_all(workdir, ec);
  fs::create_directories(workdir, ec);

  auto exec = [](const std::string& src, piet::SessionState& session) {
    return piet::doexec::executeDoSource(src, session, piet::dispatch);
  };
  // Returns a NULL json rather than throwing when there is no error block --
  // the BUG-129 trap: `value()` on nothing aborts the whole run instead of
  // failing one check, and check()'s message argument is built EAGERLY, on the
  // passing path too, so every message below reads through these two helpers
  // rather than calling value() inline.
  auto firstError = [](const nlohmann::ordered_json& blocks) -> nlohmann::ordered_json {
    for (const auto& b : blocks)
      if (b.is_object() && b.value("type", std::string()) == "error") return b;
    return nlohmann::ordered_json();
  };
  auto errText = [](const nlohmann::ordered_json& e) {
    return e.is_object() ? e.value("message", std::string()) : std::string("<none>");
  };
  auto errField = [](const nlohmann::ordered_json& e, const std::string& f) {
    return e.is_object() ? e.value(f, std::string()) : std::string("<none>");
  };
  auto rcOf = [](const nlohmann::ordered_json& e) {
    return e.is_object() ? piet::eval::coarseRc(e) : std::string("<none>");
  };
  auto displays = [](const auto& blocks) {
    std::vector<std::string> v;
    for (const auto& b : blocks)
      if (b.is_object() && b.value("type", std::string()) == "display")
        v.push_back(b.value("text", std::string()));
    return v;
  };
  auto displayValue = [&](const auto& blocks, const std::string& prefix) -> double {
    for (const auto& s : displays(blocks)) {
      if (s.rfind(prefix, 0) != 0) continue;
      try {
        return std::stod(s.substr(prefix.size()));
      } catch (...) {
        return std::nan("");
      }
    }
    return std::nan("");
  };
  auto hasBlockType = [](const auto& blocks, const std::string& t) {
    for (const auto& b : blocks)
      if (b.is_object() && b.value("type", std::string()) == t) return true;
    return false;
  };
  // Walks a JSON path and answers NULL for any missing hop, so a snapshot that
  // is missing the whole `added` object fails the VALUE check below instead of
  // throwing out of the run.
  auto dig = [](const nlohmann::ordered_json& root,
                const std::vector<std::string>& path) -> nlohmann::ordered_json {
    const nlohmann::ordered_json* cur = &root;
    for (const auto& k : path) {
      if (!cur->is_object() || !cur->contains(k)) return nlohmann::ordered_json();
      cur = &((*cur)[k]);
    }
    return *cur;
  };
  auto slurp = [](const std::string& p) {
    std::ifstream f(cecon::to_native_path(p), std::ios::binary);
    return std::string((std::istreambuf_iterator<char>(f)), std::istreambuf_iterator<char>());
  };
  auto at = [&](const std::string& rel) { return (fs::path(workdir) / rel).u8string(); };
  // std::to_string gives SIX decimals, which renders two doubles differing
  // in the 8th digit as the same text -- a failure message that cannot be
  // read is worse than none, and this very leg printed both sides as
  // "-77.551724" while they genuinely differed. Value comparisons report
  // through this instead.
  auto fullPrec = [](double v) {
    char buf[48];
    std::snprintf(buf, sizeof(buf), "%.17g", v);
    return std::string(buf);
  };
  auto has = [](const std::string& hay, const std::string& needle) {
    return hay.find(needle) != std::string::npos;
  };
  auto varNames = [](piet::SessionState& s) {
    std::vector<std::string> out;
    const nlohmann::ordered_json blocks = piet::dispatch("describe", s);
    for (const auto& b : blocks)
      if (b.is_object() && b.value("type", std::string()) == "describe" && b.contains("variables"))
        for (const auto& v : b["variables"]) out.push_back(v.value("name", std::string()));
    return out;
  };
  auto hasName = [](const std::vector<std::string>& v, const std::string& n) {
    return std::find(v.begin(), v.end(), n) != v.end();
  };

  // 30 rows, deterministic, and deliberately NOT a perfect fit: `y = 2*x1 +
  // 0.5*x2` alone reproduces y exactly, which drives every standard error to
  // zero and makes the star columns (and outreg2's legend, checked below)
  // degenerate. The `+ 5 in 1/10` shift is what leaves real residuals.
  const std::string kMake30 =
      "clear\n"
      "set obs 30\n"
      "gen double x1 = _n\n"
      "gen double x2 = _n*_n\n"
      "gen double y = 2*x1 + 0.5*x2\n"
      "replace y = y + 5 in 1/10\n";

  // ── (i) estadd attaches to the ACTIVE e(), and eststo carries the bag AND
  // the frozen e() scalars into the snapshot. ────────────────────────────────
  piet::SessionState session(workdir);
  session.eval.cwd = workdir;
  session.cwd = workdir;  // resolveUserPath reads THIS field (handlers.cpp:2040);
  // eval.cwd alone leaves every `using` file in the process cwd -- the repo root.
  {
    auto r = exec(kMake30 +
                      "regress y x1\n"
                      "estadd local c \"Yes\"\n"
                      "estadd scalar k = 7\n"
                      "eststo m1\n",
                  session);
    check(firstError(r.blocks).is_null(),
          "AER-TABLES (i): regress -> estadd local -> estadd scalar -> eststo runs clean. Got `" +
              errText(firstError(r.blocks)) + "`");
    const nlohmann::ordered_json* snap = session.estimatesGet("m1");
    check(snap != nullptr,
          "AER-TABLES (i): `eststo m1` actually STORED a snapshot -- every later leg reads it, and "
          "a store that silently did nothing makes them all vacuous");
    const nlohmann::ordered_json cj = snap ? dig(*snap, {"added", "locals", "c"})
                                           : nlohmann::ordered_json();
    check(cj.is_string() && cj.get<std::string>() == "Yes",
          "AER-TABLES (i): the snapshot carries added.locals.c == \"Yes\". This is the whole "
          "reason the bag exists: Stata's estadd runs BEFORE eststo and attaches to the ACTIVE "
          "e(), so a handler that wrote into the estimates store instead would find nothing there "
          "yet and lose the addition without erroring. Got " + cj.dump());
    const nlohmann::ordered_json kj = snap ? dig(*snap, {"added", "scalars", "k"})
                                           : nlohmann::ordered_json();
    check(kj.is_number() && std::fabs(kj.get<double>() - 7.0) < 1e-12,
          "AER-TABLES (i): ...and added.scalars.k == 7, so `estadd scalar k = 7` was EVALUATED "
          "rather than stored as the literal string \"7\" (stats() formats it as a number "
          "downstream, and a string lands in the .tex as `7` with no format applied). Got " +
              kj.dump());
    const nlohmann::ordered_json nj = snap ? dig(*snap, {"escalars", "N"})
                                           : nlohmann::ordered_json();
    check(nj.is_number() && std::fabs(nj.get<double>() - 30.0) < 1e-9,
          "AER-TABLES (i): ...and escalars.N == 30, frozen AT eststo time. Without this the "
          "`stats(N ...)` footer has nothing to read and renders an empty cell while the command "
          "still returns rc 0 -- the exact shape a file-existence check cannot see. Got " +
              nj.dump());
  }

  // ── (i-b) the fingerprint half of the same mechanism. A bag left attached
  // across a DIFFERENT estimation is a wrong number on the right-looking row,
  // which no renderer check can catch. ───────────────────────────────────────
  {
    piet::SessionState s(workdir);
    s.eval.cwd = workdir;
    s.cwd = workdir;  // resolveUserPath reads THIS field (handlers.cpp:2040);
    // eval.cwd alone leaves every `using` file in the process cwd -- the repo root.
    auto r = exec(kMake30 +
                      "regress y x1\n"
                      "estadd scalar k = 7\n"
                      "regress x2 x1\n"
                      "eststo m2\n",
                  s);
    (void)r;
    const nlohmann::ordered_json* snap = s.estimatesGet("m2");
    const nlohmann::ordered_json kj = snap ? dig(*snap, {"added", "scalars", "k"})
                                           : nlohmann::ordered_json();
    check(snap != nullptr && kj.is_null(),
          "AER-TABLES (i-b): an estadd made against ONE estimate is DISCARDED when a different "
          "estimation replaces e() before eststo. The fingerprint is the only thing standing "
          "between `estadd scalar k` and it reappearing under a model that never had it -- and "
          "that failure prints a plausible number, so it is invisible everywhere else. Got " +
              kj.dump());
  }

  // ── (ii) estout writes a REAL FILE whose bytes carry the addition. ─────────
  {
    check(!fs::exists(cecon::to_native_path(at("t.tex"))),
          "AER-TABLES (ii): t.tex does not exist before `estout ... using` runs -- otherwise the "
          "content checks below could be reading a leftover from an earlier run");
    auto r = exec("estout m1 using \"t.tex\", style(tex) replace stats(N k c)\n", session);
    check(firstError(r.blocks).is_null(),
          "AER-TABLES (ii): `estout m1 using \"t.tex\", style(tex) replace stats(N k c)` returns "
          "no error. Got `" + errText(firstError(r.blocks)) + "`");
    const std::string tex = slurp(at("t.tex"));
    check(!tex.empty(),
          "AER-TABLES (ii): ...and it left BYTES on disk. Before this bundle the whole table "
          "family returned a JSON block and wrote nothing, which is rc 0 with no output file -- "
          "the defect this leg exists for");
    // W1a-4 CORRECTION. These two checks asserted `\begin{tabular}` and `\hline`
    // in estout's style(tex) output, and the ado writes NEITHER: it emits a bare
    // fragment of fixed-width right-aligned cells and no rules at all
    // (tests/eval/golden/aer_w1/w1b_estout_tex.log r1, and w1b_tables/e7.tex from
    // the 2026-09-14 capture, which shows the same thing). So this arm was
    // PINNING the defect -- it held this writer to esttab's shape, which is
    // exactly what BUG-486 is about and what made the sixth axis survive the
    // five that were fixed. The replacement asserts the fragment.
    check(!has(tex, "\\begin{tabular}") && !has(tex, "\\hline"),
          "AER-TABLES (ii): estout's style(tex) is a FRAGMENT -- no tabular, no rules. The check "
          "here used to demand both and so held this writer to esttab's shape; 148 of the corpus's "
          "219 estout lines carry tex, and every one of them got the wrong table. Got " +
              std::to_string(tex.size()) + "B:\n" + tex);
    check(has(tex, "&") && has(tex, "\\\\"),
          "AER-TABLES (ii): ...and it IS LaTeX rather than the fixed-width fallback: `&` between "
          "cells and `\\\\` ending each row (r1). That is what the old checks were reaching for, "
          "and it can be asked without asserting a wrapper the ado does not write");
    check(has(tex, "Yes"),
          "AER-TABLES (ii): ...and `stats(... c)` put the estadd LOCAL's text into the table. "
          "This is the end-to-end proof that the bag survived estadd -> eststo -> estout: a "
          "footer that read only e() renders an empty row here and still writes a valid file");
    check(has(tex, "30"),
          "AER-TABLES (ii): ...and `stats(N ...)` put the frozen observation count in. 30 is this "
          "fixture's N, so a footer that read the CURRENT dataset instead of the snapshot would "
          "still print 30 here -- which is why (i) asserts escalars.N independently");
    check(has(tex, "_cons"),
          "AER-TABLES (ii): ...and the COEFFICIENT body rendered too (`_cons` is makeSnapshot's "
          "rename of `(intercept)`). A file carrying only the stats footer satisfies every check "
          "above and is not a regression table");
    check(!has(tex, workdir),
          "AER-TABLES (ii): the rendered table does not embed the build machine's workdir. A "
          "renderer that wrote the resolved output path into the table makes every golden "
          "machine-specific");
  }

  // ── (iii) esttab's `using` half. Same block, written by one renderer. ──────
  {
    auto r = exec("esttab m1 using \"t2.tex\", replace booktabs\n", session);
    check(firstError(r.blocks).is_null(),
          "AER-TABLES (iii): `esttab m1 using \"t2.tex\", replace booktabs` returns no error. Got `" +
              errText(firstError(r.blocks)) + "`");
    check(hasBlockType(r.blocks, "estimates_table"),
          "AER-TABLES (iii): ...and the ON-SCREEN table block is still emitted. The dispatcher "
          "splits `using` off and hands runEsttab's own block to the writer; a split that "
          "swallowed the screen output would leave `esttab ... using` silently printing nothing");
    const std::string tex = slurp(at("t2.tex"));
    check(!tex.empty(), "AER-TABLES (iii): ...and t2.tex has bytes in it");
    check(has(tex, "\\toprule") && has(tex, "\\bottomrule"),
          "AER-TABLES (iii): `booktabs` renders \\toprule/\\bottomrule, NOT \\hline. This option "
          "changes only the rule macros, so an option list that arrived unread produces a file "
          "that looks right, compiles, and is the wrong table -- rc 0 either way. Got " +
              std::to_string(tex.size()) + "B");
    check(has(tex, "_cons"),
          "AER-TABLES (iii): ...and the coefficient body is in the file rather than the header "
          "alone");
  }

  // ── (iv) outreg2's .txt ledger IS the append source of truth. ──────────────
  {
    piet::SessionState s(workdir);
    s.eval.cwd = workdir;
    s.cwd = workdir;  // resolveUserPath reads THIS field (handlers.cpp:2040);
    // eval.cwd alone leaves every `using` file in the process cwd -- the repo root.
    auto r = exec(kMake30 +
                      "regress y x1\n"
                      "outreg2 using \"o\", replace tex ctitle(\"M1\")\n"
                      "regress y x1 x2\n"
                      "outreg2 using \"o\", append ctitle(\"M2\")\n",
                  s);
    check(firstError(r.blocks).is_null(),
          "AER-TABLES (iv): outreg2 replace-then-append runs clean. Got `" +
              errText(firstError(r.blocks)) + "`");
    const std::string txt = slurp(at("o.txt"));
    check(!txt.empty(),
          "AER-TABLES (iv): outreg2 always writes its `.txt` ledger, whatever else was asked for. "
          "It is the file `append` re-reads on a LATER session, so an in-memory ledger answers "
          "differently the second time the same do-file runs");
    // The VARIABLES row is the column roster. Read it by SPLITTING, not by
    // searching for "M2": a file that had been overwritten rather than
    // appended still contains "M2" -- as its ONLY column.
    std::vector<std::string> fields;
    {
      std::istringstream iss(txt);
      std::string line;
      while (std::getline(iss, line)) {
        if (line.rfind("VARIABLES", 0) != 0) continue;
        std::string cur;
        for (char ch : line) {
          if (ch == '\t') {
            fields.push_back(cur);
            cur.clear();
          } else if (ch != '\r') {
            cur += ch;
          }
        }
        fields.push_back(cur);
        break;
      }
    }
    check(fields.size() == 3,
          "AER-TABLES (iv): the VARIABLES row carries THREE tab-separated fields (the stub plus "
          "two model columns). This is the append assertion and it is made on the column COUNT "
          "because an append that overwrote instead of adding leaves a valid one-model table that "
          "returns rc 0 and contains the second ctitle. Got " + std::to_string(fields.size()));
    check(fields.size() == 3 && fields[1] == "M1" && fields[2] == "M2",
          "AER-TABLES (iv): ...and they are the two ctitle()s IN ORDER -- so the appended column "
          "went on the RIGHT and the first model was re-read from the ledger rather than "
          "re-rendered from whatever e() happens to hold now. Got `" +
              (fields.size() == 3 ? fields[1] + "` / `" + fields[2] : std::string("<row absent>")) +
              "`");
    check(has(txt, "*** p<0.01") && has(txt, "* p<0.1"),
          "AER-TABLES (iv): the legend is OUTREG2's (*** 0.01 / ** 0.05 / * 0.1), not estout's "
          "(* 0.05 / ** 0.01 / *** 0.001). The two commands share a Table model and three "
          "renderers on purpose, and this is the line that proves the shared renderer did not "
          "also share the star levels -- which would silently restate every significance claim in "
          "the output");
    check(has(txt, "Observations"),
          "AER-TABLES (iv): ...and the footer names the observation row the way outreg2 does");
    const std::string tex = slurp(at("o.tex"));
    check(!tex.empty() && has(tex, "\\begin{tabular}"),
          "AER-TABLES (iv): `tex` also wrote o.tex as a real tabular. A .txt-only handler that "
          "accepted the option and ignored it leaves the do-file's \\input pointing at nothing");
  }

  // ── (v) estpost is a pseudo-estimate whose e(mean) is what esttab reads. ───
  {
    piet::SessionState s(workdir);
    s.eval.cwd = workdir;
    s.cwd = workdir;  // resolveUserPath reads THIS field (handlers.cpp:2040);
    // eval.cwd alone leaves every `using` file in the process cwd -- the repo root.
    // Bare `esttab`, NOT `esttab, cells(...)`. estpost posts e(b)=mean and
    // e(se)=sd, so esttab's DEFAULT b-over-(se) layout already renders mean over
    // sd here -- which is why the earlier cut of this leg passed with cells()
    // in the line and proved nothing about cells(). `runEsttab` does not read
    // cells(); it is now listed as unimplemented (BUG-407) and refuses by name,
    // which the companion check below pins so this leg cannot quietly go back
    // to passing for the wrong reason.
    auto r = exec(kMake30 +
                      "estpost summarize x1 y\n"
                      "esttab\n",
                  s);
    check(firstError(r.blocks).is_null(),
          "AER-TABLES (v): `estpost summarize x1 y` then a bare `esttab` runs clean -- the "
          "pseudo-estimate is reachable through runEsttab's active-e() fallback, with nothing "
          "in the estimates store. Got `" + errText(firstError(r.blocks)) + "`");
    nlohmann::ordered_json table;
    for (const auto& b : r.blocks)
      if (b.is_object() && b.value("type", std::string()) == "estimates_table") table = b;
    check(!table.is_null(),
          "AER-TABLES (v): ...and an estimates_table block came back, so estpost's pseudo-estimate "
          "was reachable by esttab at all");
    std::vector<std::string> rowNames;
    if (table.is_object() && table.contains("coef_rows") && table["coef_rows"].is_array())
      for (const auto& cr : table["coef_rows"]) rowNames.push_back(cr.value("name", std::string()));
    check(hasName(rowNames, "x1") && hasName(rowNames, "y"),
          "AER-TABLES (v): the table's rows are the VARIABLES x1 and y. estpost's model is the "
          "1xk e(mean)/e(sd) matrices, so a handler that posted a coefficient table keyed on "
          "anything else (or on nothing) renders an empty table and still answers rc 0");
    const std::string csv = table.is_object() ? table.value("csv", std::string()) : std::string();
    check(has(csv, "15.5"),
          "AER-TABLES (v): ...and the mean cell is 15.5, which is the true mean of 1..30. This is "
          "the leg's real assertion: row LABELS alone are satisfied by a table full of the wrong "
          "statistic -- sum is 465 here and sd is 8.803, and both would print a plausible number "
          "under a `mean` heading. Got csv `" + csv.substr(0, 200) + "`");

    // BUG-407 (2026-10-29): the SCREEN path honours cells() -- esttabScreen
    // returns the writer's rendered table in place of the estimates_table block,
    // whose JSON has no cell model -- so the check that pinned the refusal now
    // pins the table: the mean 15.5 beside its sd, at rc 0.
    auto rc = exec(kMake30 + "estpost summarize x1 y\nesttab, cells(\"mean sd\")\n", s);
    const auto ec = firstError(rc.blocks);
    std::string shown;
    for (const auto& b : rc.blocks)
      if (b.is_object() && b.value("type", std::string()) == "display")
        shown += b.value("text", std::string());
    check(ec.is_null() && has(shown, "mean") && has(shown, "sd") && has(shown, "15.5"),
          "AER-TABLES (v): a SCREEN `esttab, cells(\"mean sd\")` shows the writer's table (BUG-407): "
          "mean 15.5 beside its sd, rc 0. Got `" + errText(ec) + "` / `" + shown.substr(0, 200) +
              "`");
  }

  // ── (vi) regsave with no `using` REPLACES the dataset with the estimates. ──
  {
    piet::SessionState s(workdir);
    s.eval.cwd = workdir;
    s.cwd = workdir;  // resolveUserPath reads THIS field (handlers.cpp:2040);
    // eval.cwd alone leaves every `using` file in the process cwd -- the repo root.
    (void)exec(kMake30 + "regress y x1\n", s);
    // The coefficient is read from e() in C++ BEFORE regsave runs, because
    // regsave's whole job is to overwrite the dataset the estimate came from.
    // Row 0 is `(intercept)`, not x1: cobra emits the intercept FIRST and the
    // shipped esttab freeze fixture pins that order, so this is the codebase's
    // established coefficient order rather than something regsave chose.
    // W2AK TW-DS: regsave's rows are in e(b) order (`_cons` LAST) and its
    // coef column is FLOAT (svmat), so coef[1] is float(_b[x1]) -- StataBE
    // w2at_table_writers wt_r01_v2 `coef|float`, wt_r04_r1c2 `+1.72a01eX+000`.
    double bRow0 = std::nan("");
    if (s.lastEstBlock.has_value() && (*s.lastEstBlock).contains("coeftable") &&
        (*s.lastEstBlock)["coeftable"].is_array()) {
      for (const auto& row : (*s.lastEstBlock)["coeftable"]) {
        if (row.is_object() && row.value("name", std::string()) == "x1" && row.contains("b") &&
            row["b"].is_number()) {
          bRow0 = static_cast<double>(static_cast<float>(row["b"].get<double>()));
        }
      }
    }
    check(!std::isnan(bRow0),
          "AER-TABLES (vi): the regression that regsave is about actually produced a coefficient "
          "-- the value comparison below is meaningless otherwise");
    auto r = exec("regsave\n"
                  "count\n"
                  "display \"AER_RN=\" r(N)\n"
                  "display \"AER_C1=\" %22.17f coef[1]\n",
                  s);
    check(firstError(r.blocks).is_null(),
          "AER-TABLES (vi): `regsave` with no `using` runs clean. Got `" +
              errText(firstError(r.blocks)) + "`");
    const std::vector<std::string> names = varNames(s);
    check(hasName(names, "var") && hasName(names, "coef") && hasName(names, "stderr"),
          "AER-TABLES (vi): the dataset in memory is now regsave's own {var, coef, stderr} "
          "columns. Asserted by NAME because a handler that loaded the right number of rows under "
          "different column names breaks every downstream `keep if var==` a paper writes");
    check(std::fabs(displayValue(r.blocks, "AER_RN=") - 2.0) < 1e-12,
          "AER-TABLES (vi): ...with one row per coefficient -- 2 here (x1 and _cons), not 1 and "
          "not the 30 rows of the source dataset");
    // Read back with an explicit %22.17f, NOT `display`'s default %9.0g, so no
    // formatting rounding is left to absorb -- what remains is the READ path's
    // own loss and nothing else.
    //
    // The tolerance is 9 SIGNIFICANT DIGITS and that number is a measurement,
    // not a cushion. It was first attributed to `cobra convert` truncating CSV
    // doubles (BUG-406 as filed 2026-09-04). REDIAGNOSED 2026-09-06 by the
    // first run of tools/buglog_probes.py: the STORAGE is exact -- the
    // converted hbin's bytes, `count if abs(v - <17-digit literal>) > 1e-12`,
    // `string(v, "%22.17f")` and r(mean) all carry every digit; the 9 s.f. is
    // `display %fmt <varref>`, where the value passes a %.9g before the user's
    // format is applied. So regsave's stored coefficient is NOT lossy -- but
    // this leg still READS it through displayValue(), i.e. through that same
    // display, so nine digits is what the check can see today. Asserting
    // bit-exactness here would fail on the display defect, not on regsave;
    // asserting `< 1e-9` absolute would have hidden the nine digits entirely,
    // which is how the loss went unnoticed until now. The check is relative,
    // pinned AT the read path's measured precision: it still catches a builder
    // that wrote zeros, read the wrong coefficient, or lost another digit.
    // When BUG-406's display path is fixed (or this read moves to a path that
    // is not `display`, e.g. `string(coef[1], "%22.17f")`), tighten it back
    // to equality -- a 1e-9 relative bound can no longer tell the two apart.
    const double c1 = displayValue(r.blocks, "AER_C1=");
    const double denom = std::fabs(bRow0) > 1.0 ? std::fabs(bRow0) : 1.0;
    check(!std::isnan(bRow0) && std::fabs(c1 - bRow0) / denom < 1e-9,
          "AER-TABLES (vi): ...and coef[1] is float(_b[x1]) read out of e() "
          "before the dataset was replaced. Column names and a row count are satisfied by a "
          "builder that wrote zeros; this is the leg that says the numbers came from the model. "
          "Got " + fullPrec(displayValue(r.blocks, "AER_C1=")) + " vs e() " + fullPrec(bRow0));
  }

  // ── (vii) erepost overwrites e(b) from a matrix, names included. ───────────
  {
    piet::SessionState s(workdir);
    s.eval.cwd = workdir;
    s.cwd = workdir;  // resolveUserPath reads THIS field (handlers.cpp:2040);
    // eval.cwd alone leaves every `using` file in the process cwd -- the repo root.
    auto r = exec(kMake30 +
                      "regress y x1\n"
                      "matrix M = (1,2)\n"
                      "erepost b = M, rename\n",
                  s);
    check(firstError(r.blocks).is_null(),
          "AER-TABLES (vii): `erepost b = M, rename` over a 2-coefficient e(b) runs clean (M is "
          "1x2, e(b) is x1 and _cons). Got `" + errText(firstError(r.blocks)) + "`");
    std::string n0;
    double b0 = std::nan("");
    if (s.lastEstBlock.has_value() && (*s.lastEstBlock).contains("coeftable") &&
        (*s.lastEstBlock)["coeftable"].is_array() && !(*s.lastEstBlock)["coeftable"].empty()) {
      const auto& row0 = (*s.lastEstBlock)["coeftable"][0];
      n0 = row0.value("name", std::string());
      if (row0.contains("b") && row0["b"].is_number()) b0 = row0["b"].get<double>();
    }
    check(n0 == "c1",
          "AER-TABLES (vii): with `rename` the coefficient NAMES become the matrix's column names "
          "-- c1 for an unnamed literal. Got `" + n0 + "`");
    check(!std::isnan(b0) && std::fabs(b0 - 1.0) < 1e-12,
          "AER-TABLES (vii): ...and the VALUE was actually overwritten with the matrix's first "
          "element (1), not merely relabelled. A rename that left the fitted coefficient in place "
          "passes the name check above and reports the old model under new labels. Got " +
              std::to_string(b0));
  }

  // ── (viii) the two refusals: refused BY NAME, at r(199), having written
  // nothing. ────────────────────────────────────────────────────────────────
  {
    piet::SessionState s(workdir);
    s.eval.cwd = workdir;
    s.cwd = workdir;  // resolveUserPath reads THIS field (handlers.cpp:2040);
    // eval.cwd alone leaves every `using` file in the process cwd -- the repo root.
    (void)exec(kMake30 + "regress y x1\n", s);
    auto r = exec("outreg2 using \"ow\", word\n", s);
    auto err = firstError(r.blocks);
    check(!err.is_null(),
          "AER-TABLES (viii): `outreg2 using \"ow\", word` is REFUSED. This build has no RTF "
          "writer, and the alternative is writing a differently-formatted file under the "
          "requested name -- a silently wrong answer with a plausible file beside it");
    check(errField(err, "code") == "unsupported_command",
          "AER-TABLES (viii): ...under the `unsupported_command` code, got `" +
              errField(err, "code") + "`");
    check(errField(err, "reason") == "refused:no_rtf_writer",
          "AER-TABLES (viii): ...naming the missing writer, so the message says what is absent "
          "rather than that the option is unknown. Got `" + errField(err, "reason") + "`");
    check(rcOf(err) == "199",
          "AER-TABLES (viii): ...and it maps to r(199). Asserted separately from the code because "
          "a refusal built with the default engine_error code arrives as rc 1 and every do-file "
          "branching on 199 takes the wrong branch -- bundle D shipped exactly that. Got r(" +
              rcOf(err) + ")");
    check(!fs::exists(cecon::to_native_path(at("ow.txt"))) &&
              !fs::exists(cecon::to_native_path(at("ow.doc"))) &&
              !fs::exists(cecon::to_native_path(at("ow.rtf"))),
          "AER-TABLES (viii): ...and it wrote NOTHING. outreg2 always writes a .txt ledger on the "
          "success path, so a refusal reached after the ledger write leaves a file behind and the "
          "next `append` reads a table the user was told did not happen -- the silent half of "
          "this class, which the error block alone cannot tell apart");
    auto rt = exec("tabout x1\n", s);
    auto errT = firstError(rt.blocks);
    check(!errT.is_null(),
          "AER-TABLES (viii/tabout): `tabout` is refused at the COMMAND level. Its grammar is a "
          "panel language of its own; accepting the head and refusing each option would report a "
          "missing OPTION where the truth is a missing command");
    check(errField(errT, "code") == "unsupported_command" &&
              errField(errT, "reason") == "refused:tabout_grammar",
          "AER-TABLES (viii/tabout): ...by name, got code `" + errField(errT, "code") +
              "` reason `" + errField(errT, "reason") + "`");
    check(rcOf(errT) == "199",
          "AER-TABLES (viii/tabout): ...at r(199), got r(" + rcOf(errT) + ")");
  }

  // ── (ix) estadd with nothing to attach to says so. ─────────────────────────
  {
    piet::SessionState s(workdir);
    s.eval.cwd = workdir;
    s.cwd = workdir;  // resolveUserPath reads THIS field (handlers.cpp:2040);
    // eval.cwd alone leaves every `using` file in the process cwd -- the repo root.
    auto r = exec("estadd local c \"Yes\"\n", s);
    auto err = firstError(r.blocks);
    check(!err.is_null(),
          "AER-TABLES (ix): `estadd` with no estimation in memory is an ERROR. Accepting it would "
          "park the addition in a bag no eststo will ever match, and the do-file would carry on "
          "to write a table with a silently missing row");
    check(has(errText(err), "no estimation result in memory"),
          "AER-TABLES (ix): ...and the message names the cause. Got `" + errText(err) + "`");
    check(rcOf(err) == "301",
          "AER-TABLES (ix): ...at r(301), Stata's `last estimates not found`. A generic rc 1 here "
          "is indistinguishable from a syntax problem to any `capture`-and-branch caller. Got r(" +
              rcOf(err) + ")");
  }

  // ── (x) B4-W5: the TABLE-WRITER option surface, against the Stata capture. ──
  //
  // The comparator that actually adjudicates W5 is a CELL diff of the files
  // this build writes against the 27 files real StataBE wrote on 2026-09-09
  // (tests/eval/golden/aer_b4/tables/, produced by pins_oracle_t.do and
  // _t2.do). Fifteen of the sixteen esttab arms and all five outreg2 arms come
  // back BYTE-IDENTICAL there; the sixteenth is `nolegend nolines`, which this
  // build accepts and does not apply, and says so.
  //
  // Those files are not readable from here -- the selftest runs in a scratch
  // workdir with no repo anchor, and hard-coding one would make this suite pass
  // or fail on where the binary happens to sit. So what is pinned HERE is the
  // set of facts that diff established, each one a claim this build got WRONG
  // before W5 and each one silent: the table rendered, it was simply not
  // esttab's table. Every leg reads the BYTES OF THE FILE, never a return code.
  {
    piet::SessionState s(workdir);
    s.eval.cwd = workdir;
    s.cwd = workdir;  // resolveUserPath reads THIS field (handlers.cpp:2040)
    (void)exec(kMake30 +
                   "regress y x1 x2\n"
                   "eststo w5a\n"
                   "regress y x1\n"
                   "eststo w5b\n",
               s);

    // (x.1) The DEFAULTS. t in the parentheses, `_cons` last, N alone in the
    // footer. All three were refuted by t_plain.txt.
    {
      auto r = exec("esttab w5a w5b using \"w5p.txt\", replace\n", s);
      check(firstError(r.blocks).is_null(),
            "W5 (x.1): plain `esttab ... using` runs. Got `" + errText(firstError(r.blocks)) + "`");
      const std::string t = slurp(at("w5p.txt"));
      check(has(t, "t statistics in parentheses"),
            "W5 (x.1): esttab's DEFAULT parenthesised statistic is t, not the standard error "
            "(matches esttab's behaviour, identified from its ado: t at 2 decimals; t_plain.txt's legend). This build printed SEs under no "
            "legend at all -- every number in the second row of every default table was the "
            "wrong statistic, at rc 0. Got:\n" + t);
      check(has(t, "* p<0.05, ** p<0.01, *** p<0.001"),
            "W5 (x.1): ...and the star legend reads in ASCENDING mark order, which is DESCENDING "
            "cutoff (matches esttab's behaviour, identified from its ado). Got:\n" + t);
      const size_t consAt = t.find("_cons");
      const size_t x1At = t.find("x1");
      check(consAt != std::string::npos && x1At != std::string::npos && consAt > x1At,
            "W5 (x.1): ...and `_cons` is the LAST coefficient row. The engine's coeftable puts "
            "the intercept first and this writer followed it; all 27 captured tables put it "
            "last. Got:\n" + t);
      check(!has(t, "R\xc2\xb2") && !has(t, "R-sq"),
            "W5 (x.1): ...and the default footer is N ALONE -- esttab adds an R-squared row only "
            "for `r2`/`ar2`/`stats()`. An extra footer row is a cell every comparator counts. "
            "Got:\n" + t);
    }

    // (x.2) `not` -- the one arm that separates "a gap after every coefficient"
    // from "a gap after the aux row". Both rules agree everywhere else.
    {
      auto r = exec("esttab w5a w5b using \"w5n.txt\", replace not\n", s);
      check(firstError(r.blocks).is_null(),
            "W5 (x.2): `esttab ..., not` runs. Got `" + errText(firstError(r.blocks)) + "`");
      const std::string t = slurp(at("w5n.txt"));
      check(!has(t, "t statistics in parentheses"),
            "W5 (x.2): `not` drops the t row AND its legend (t_not.txt). Got:\n" + t);
      check(!has(t, "\n\n"),
            "W5 (x.2): ...and with no aux row there are NO blank separator lines at all. This is "
            "the leg that decides the gap rule; t_not.txt is the only captured arm that can. "
            "Got:\n" + t);
    }

    // (x.3) `ci()` reads the STORED interval. Rebuilding it from a Normal
    // quantile moved every bound in t_ci.txt by about 3 -- inside no tolerance
    // and invisible without the capture.
    {
      auto r = exec("esttab w5a using \"w5c.txt\", replace ci(3)\n", s);
      check(firstError(r.blocks).is_null(),
            "W5 (x.3): `esttab ..., ci(3)` runs. Got `" + errText(firstError(r.blocks)) + "`");
      const std::string t = slurp(at("w5c.txt"));
      check(has(t, "confidence intervals in brackets") && has(t, "["),
            "W5 (x.3): ci() renders bracketed intervals and says so in the legend. Got:\n" + t);
      auto r2 = exec("esttab w5a using \"w5c2.txt\", replace ci(3) level(90)\n", s);
      auto err = firstError(r2.blocks);
      check(!err.is_null() && errField(err, "code") == "unsupported_option",
            "W5 (x.3): ...and `level(90)` is REFUSED. This build reports the interval the "
            "ESTIMATION stored; printing that 95% interval under a `90% confidence intervals` "
            "legend is the silent-wrong-answer shape, so the option is named rather than "
            "swallowed. Got code `" + errField(err, "code") + "`");
    }

    // (x.4) The quoted-list options. `substitute("_cons" "CONST")` is eight
    // characters whose first and last are both `"`, so dequoting the whole
    // value before splitting yields the tokens `_cons"` and `"CONST` and the
    // substitution silently never fires -- which is what happened on the first
    // pass, in three arms at once (mlabels, mgroups, substitute).
    {
      auto r = exec("esttab w5a w5b using \"w5s.txt\", replace "
                    "mlabels(\"AAA\" \"BBB\") substitute(\"_cons\" \"CONSTANT\")\n",
                    s);
      check(firstError(r.blocks).is_null(),
            "W5 (x.4): mlabels()+substitute() run. Got `" + errText(firstError(r.blocks)) + "`");
      const std::string t = slurp(at("w5s.txt"));
      check(has(t, "AAA") && has(t, "BBB") && !has(t, "AAA\""),
            "W5 (x.4): mlabels(\"AAA\" \"BBB\") sets BOTH column heads, unquoted. Got:\n" + t);
      check(has(t, "CONSTANT") && !has(t, "_cons"),
            "W5 (x.4): substitute() replaces the text it names. Got:\n" + t);
    }

    // (x.5) `beta` is REFUSED when the sample cannot be reproduced, rather than
    // printing a standardized coefficient from the wrong rows. The receipt's
    // REFUTE.md kills the N-vs-N-1 divisor as a discriminator (it cancels in the
    // ratio), so the SAMPLE is the only convention left that can be wrong here,
    // and it is the one this build cannot carry: there is no e(sample) mask in
    // the estimates store. The reconstruction is complete-cases-of-the-model's-
    // own-variables and it is CHECKED against e(N).
    {
      piet::SessionState sb(workdir);
      sb.eval.cwd = workdir;
      sb.cwd = workdir;
      (void)exec(kMake30 + "regress y x1 if _n <= 20\neststo w5f\n", sb);
      auto r = exec("esttab w5f using \"w5b.txt\", replace beta\n", sb);
      auto err = firstError(r.blocks);
      check(!err.is_null() && errField(err, "code") == "unsupported_option",
            "W5 (x.5): `beta` after a fit on a SUBSET is refused -- the reconstructed sample (30 "
            "complete cases) does not match e(N)=20, so sd(x)/sd(y) would be taken over rows the "
            "regression never saw. A number here is wrong by an amount nothing downstream can "
            "see. Got code `" + errField(err, "code") + "`");
      check(has(errText(err), "e(N)"),
            "W5 (x.5): ...and the message names the arithmetic that failed, so the user can tell "
            "this from `beta is not implemented`. Got `" + errText(err) + "`");
      check(!fs::exists(cecon::to_native_path(at("w5b.txt"))),
            "W5 (x.5): ...and it wrote NO file. A refusal that still leaves a table behind is the "
            "silent half of this class");
    }

    // (x.6) `nolegend nolines` are HONOURED since W2AK (matches esttab's
    // behaviour, identified from its ado): aer_b4/tables/t_noleg.txt has no rule line and no star
    // legend, only the coefficient note. They used to be accepted with a
    // "not applied" note.
    {
      auto r = exec("esttab w5a using \"w5l.txt\", replace nolegend nolines\n", s);
      check(firstError(r.blocks).is_null(),
            "W5 (x.6): `nolegend nolines` run. Got `" + errText(firstError(r.blocks)) + "`");
      const std::string t = slurp(at("w5l.txt"));
      check(!has(t, "---") && !has(t, "p<0.05") && has(t, "t statistics in parentheses"),
            "W5 (x.6): ...and the file has no rule and no star legend, keeping the aux note "
            "(aer_b4/tables/t_noleg.txt). Got:\n" + t);
    }

    // (x.7) outreg2's DEFAULT number shape is significant digits WITH thousands
    // separators, not %9.3f (matches outreg2's behaviour, identified from its
    // ado; o_plain.txt reads -49.51 /
    // 1.747 / 1,946 for the same three coefficients this build printed as
    // -49.512 / 1.747 / 1946.069). `tstat` swaps the parenthesised row and the
    // legend with it.
    {
      piet::SessionState so(workdir);
      so.eval.cwd = workdir;
      so.cwd = workdir;
      (void)exec(kMake30 + "regress y x1 x2\n", so);
      auto r = exec("outreg2 using \"w5o\", replace text\n", so);
      check(firstError(r.blocks).is_null(),
            "W5 (x.7): `outreg2 using ..., replace text` runs -- `text` is accepted, not an "
            "unknown option; all five captured outreg2 arms spell it. Got `" +
                errText(firstError(r.blocks)) + "`");
      const std::string t = slurp(at("w5o.txt"));
      check(has(t, "Constant") && !has(t, "_cons"),
            "W5 (x.7): outreg2 calls the intercept `Constant` and puts it last (o_plain.txt), "
            "whether or not `label` was given. Got:\n" + t);
      check(has(t, "Standard errors in parentheses\t"),
            "W5 (x.7): ...and its legend lines are ROWS -- they carry the trailing tab that makes "
            "them cells. This build wrote them untabbed, which is one cell wrong on two lines of "
            "every table it ever produced. Got:\n" + t);
      auto rt = exec("regress y x1 x2\noutreg2 using \"w5t\", replace text tstat\n", so);
      check(firstError(rt.blocks).is_null(),
            "W5 (x.7): `tstat` runs. Got `" + errText(firstError(rt.blocks)) + "`");
      const std::string tt = slurp(at("w5t.txt"));
      check(has(tt, "t-statistics in parentheses"),
            "W5 (x.7): ...and `tstat` moves the LEGEND with the row (o_tstat.txt). A legend that "
            "still says `Standard errors` over a column of t values is the reading error this "
            "whole option exists to prevent. Got:\n" + tt);
    }

    // (x.8) estout's numbers/nonumbers, the pair the capture itself identified.
    // `nonumbers` ALONE was non-discriminating -- estout's default header is
    // already the model name, so the plain arm and the nonumbers arm came back
    // byte-identical, and pins_oracle_t2.do replaced it. So the assertion is
    // on the PAIR: the two files must differ, and by exactly the number row.
    {
      auto rn = exec("estout w5a w5b using \"w5en.txt\", replace numbers\n", s);
      auto rf = exec("estout w5a w5b using \"w5ef.txt\", replace numbers nonumbers\n", s);
      check(firstError(rn.blocks).is_null() && firstError(rf.blocks).is_null(),
            "W5 (x.8): both estout spellings run -- before W5 `numbers` and `nonumbers` were in "
            "NEITHER vocabulary list and answered r(198)");
      const std::string a = slurp(at("w5en.txt"));
      const std::string b = slurp(at("w5ef.txt"));
      check(has(a, "(1)") && !has(b, "(1)"),
            "W5 (x.8): `numbers` emits the (1)/(2) row and `nonumbers` removes it -- and "
            "`nonumbers` WINS when both are typed, which is what e_numbers_off.txt shows. Got "
            "numbers:\n" + a + "\nnonumbers:\n" + b);
      check(a != b,
            "W5 (x.8): ...so the two arms are not the same file. A pin that cannot fail is "
            "decoration; this is the pair that can");
    }

    // ── (x.9) BUG-486: estout's DEFAULTS are estout's, not esttab's. ─────────
    // W5 diffed fifteen of sixteen esttab arms and all five outreg2 arms
    // against the capture and said so; the five estout arms were captured and
    // never compared. Every axis below is a cell a comparator reads, and all
    // five were wrong at rc 0. Oracle: tests/eval/golden/aer_w1/w1b_tables/
    // e2.txt (2026-09-14) and aer_b4/tables/e_plain.txt (2026-09-09), whose
    // first two rows are identical three months apart.
    {
      auto r = exec("estout w5a w5b using \"w5ed.txt\", replace\n", s);
      check(firstError(r.blocks).is_null(),
            "W5 (x.9): plain `estout ... using` runs. Got `" + errText(firstError(r.blocks)) + "`");
      const std::string t = slurp(at("w5ed.txt"));
      check(has(t, "\tw5a\tw5b"),
            "W5 (x.9): the default is TAB-separated and headed by the MODEL NAMES. `fixed` is the "
            "style ESTTAB passes when it wraps estout, and this build had taken the wrapper's "
            "default for the command's -- a dashed fixed-width block with `(1)`/depvar heads. "
            "Got:\n" + t);
      check(has(t, "\tb\tb"),
            "W5 (x.9): ...and a CELL-NAME row (`b`) sits under the model names, naming what the "
            "columns carry. This build emitted none. Got:\n" + t);
      const size_t consAt = t.find("_cons");
      const size_t x1At = t.find("x1");
      check(consAt != std::string::npos && x1At != std::string::npos && consAt > x1At,
            "W5 (x.9): ...and `_cons` is LAST, the same fact x.1 pins for esttab. The flag existed "
            "and was left off for estout. Got:\n" + t);
      check(t.find('*') == std::string::npos,
            "W5 (x.9): ...and the default cell is `b` with NO stars -- e2.txt carries no mark "
            "anywhere. `b(star)` is esttab's default, not estout's. Got:\n" + t);
      // The precision axis: %9.0g, not %9.3f. A three-decimal column cannot
      // produce a cell with more than three decimals, so one such cell is the
      // whole discriminator.
      bool longDecimal = false;
      for (size_t i = 0; i + 1 < t.size(); ++i) {
        if (t[i] != '.') continue;
        size_t j = i + 1, digits = 0;
        while (j < t.size() && std::isdigit(static_cast<unsigned char>(t[j]))) { ++j; ++digits; }
        if (digits > 3) { longDecimal = true; break; }
      }
      check(longDecimal,
            "W5 (x.9): ...and the estimate carries Stata's own %9.0g precision (e2.txt: "
            "-49.51222 / 1.746559 / 3673.06, three decimal counts in one column), not esttab's "
            "%9.3f rounding. Got:\n" + t);
    }

    // (x.10) BUG-486's option half: `collabels()` names the CELLS, not the
    // models. Before the fix it overwrote the model heads, so `collabels(none)`
    // wrote the literal word `none` where `w5a` belonged (w1b_tables/e7.tex
    // keeps its model names under exactly that option).
    {
      auto r = exec("estout w5a w5b using \"w5ec.txt\", replace collabels(none)\n", s);
      check(firstError(r.blocks).is_null(), "W5 (x.10): `collabels(none)` runs");
      const std::string t = slurp(at("w5ec.txt"));
      check(has(t, "\tw5a\tw5b") && !has(t, "none"),
            "W5 (x.10): `collabels(none)` removes the CELL-NAME row and leaves the model heads "
            "standing -- it never renames a model. Got:\n" + t);
      check(!has(t, "\tb\tb"), "W5 (x.10): ...and the `b` row is the row it removed. Got:\n" + t);
    }

    // (x.11) `numbers` still adds the (1)/(2) row on top of the new default,
    // and `nonumbers` still wins when both are typed (e_numbers_off.txt).
    {
      auto rn = exec("estout w5a w5b using \"w5n1.txt\", replace numbers\n", s);
      auto rb = exec("estout w5a w5b using \"w5n2.txt\", replace numbers nonumbers\n", s);
      check(firstError(rn.blocks).is_null() && firstError(rb.blocks).is_null(),
            "W5 (x.11): both number spellings still run after the default flip");
      const std::string a1 = slurp(at("w5n1.txt"));
      const std::string b1 = slurp(at("w5n2.txt"));
      check(has(a1, "(1)") && !has(b1, "(1)"),
            "W5 (x.11): `numbers` ADDS the (1)/(2) row to a default that no longer has it, and "
            "`nonumbers` still wins when both are typed");
    }

    // ── (x.12) BUG-486's RUNNING FORMAT. estout carries one current format,
    // set by the last fmt() it saw, defaulting to %9.0g, and it reaches both a
    // later cell that gives no fmt AND the stats() footer. The first cut of
    // this fix assigned the GLOBAL default to every fmt-less spec, which is a
    // different rule that happens to agree only when no fmt is given anywhere
    // -- so the discriminating arm is `cells(b(fmt(3)) se(par))`, where Stata
    // renders the se at THREE DECIMALS, not %9.0g.
    // Oracle: tests/eval/golden/aer_w1/w1b_estout_defaults.log, arms g1/g3/g4.
    {
      auto r1 = exec("estout w5a w5b using \"w5f1.txt\", replace cells(b(fmt(3)) se(par))\n", s);
      auto r3 = exec("estout w5a w5b using \"w5f3.txt\", replace stats(N r2)\n", s);
      auto r4 = exec(
          "estout w5a w5b using \"w5f4.txt\", replace cells(b(fmt(3)) se(par)) stats(N r2)\n", s);
      check(firstError(r1.blocks).is_null() && firstError(r3.blocks).is_null() &&
                firstError(r4.blocks).is_null(),
            "W5 (x.12): all three format arms run");
      const std::string f1 = slurp(at("w5f1.txt"));
      const std::string f3 = slurp(at("w5f3.txt"));
      const std::string f4 = slurp(at("w5f4.txt"));
      // The se row is the second line of each coefficient pair; under the
      // running rule it carries exactly three decimals inside parentheses.
      check(f1.find("(0.") != std::string::npos || f1.find("(-0.") != std::string::npos,
            "W5 (x.12): a cell with NO fmt() takes the running format from the cell before it -- "
            "`cells(b(fmt(3)) se(par))` renders the se at three decimals (g1: `(86.156)`), not at "
            "the %9.0g default. Got:\n" + f1);
      check(has(f3, "\nr2\t") && !has(f3, "R-squared"),
            "W5 (x.12): a stats() row is labelled with the KEY AS TYPED (`r2`), not a pretty "
            "auto-label -- g3. Got:\n" + f3);
      // g3 is %9.0g: N is an integer with no decimal point. g4 inherits fmt(3)
      // from the cells and prints 941.000. One rule, two renderings.
      check(has(f3, "\nN\t30\t30") && has(f4, "\nN\t30.000\t30.000"),
            "W5 (x.12): ...and `N` follows the SAME running format as everything else -- an "
            "integer under the %9.0g default, three decimals after `cells(b(fmt(3)))`. That is "
            "g3/g4's `74` vs `74.000` on this leg's own 30-row fixture. A hard integer format "
            "here made one of the two unreachable. Got g3:\n" + f3 + "\ng4:\n" + f4);
    }

    // ── (x.13) BUG-487: the QUOTE in cells() is an operator. `cells(a b)`
    // stacks the items as rows; `cells("a b")` puts them SIDE BY SIDE. Before
    // this the two spellings produced BYTE-IDENTICAL files, because parseCells
    // dequoted before it split and the distinction was gone by the time the
    // items were read. Oracle: tests/eval/golden/aer_w1/w1b_estout_cells.log,
    // arms h1/h2/h5/h6/h7/h9/h12.
    {
      auto ru = exec("estout w5a w5b using \"w5cu.txt\", replace cells(b se)\n", s);
      auto rq = exec("estout w5a w5b using \"w5cq.txt\", replace cells(\"b se\")\n", s);
      check(firstError(ru.blocks).is_null() && firstError(rq.blocks).is_null(),
            "W5 (x.13): both cells() spellings run");
      const std::string u = slurp(at("w5cu.txt"));
      const std::string q = slurp(at("w5cq.txt"));
      check(u != q,
            "W5 (x.13): `cells(b se)` and the QUOTED `cells(\"b se\")` are DIFFERENT tables. They "
            "were byte-identical here, which is the whole defect: the quote is an operator and it "
            "was being discarded before anything could read it. Got:\n" + u);
      check(has(u, "\tb/se\tb/se"),
            "W5 (x.13): the UNQUOTED form stays stacked -- two columns, one joined `b/se` "
            "cell-name per model (h1). Got:\n" + u);
      check(has(q, "\tb\tse\tb\tse"),
            "W5 (x.13): the QUOTED form names each of the FOUR columns (h2). Got:\n" + q);
      check(has(q, "\tw5a\t\tw5b\t"),
            "W5 (x.13): ...and a model's NAME sits in the first column it owns, the rest blank "
            "(h9 shows `m1` then two blanks for three items). Got:\n" + q);
      const size_t uLines = static_cast<size_t>(std::count(u.begin(), u.end(), '\n'));
      const size_t qLines = static_cast<size_t>(std::count(q.begin(), q.end(), '\n'));
      check(uLines > qLines,
            "W5 (x.13): ...and the wide table has FEWER rows -- one body row per coefficient "
            "instead of one per (coefficient, item). Got " + std::to_string(uLines) + " vs " +
                std::to_string(qLines));
      // A single item is the boundary case where the two layouts coincide, and
      // the capture pins that too (h5 == h6): a fix that keyed on the quote and
      // forgot the count would make these two differ.
      auto r1 = exec("estout w5a w5b using \"w5c1.txt\", replace cells(\"b\")\n", s);
      auto r2 = exec("estout w5a w5b using \"w5c2.txt\", replace cells(b)\n", s);
      check(firstError(r1.blocks).is_null() && firstError(r2.blocks).is_null(),
            "W5 (x.13): both single-item spellings run");
      check(slurp(at("w5c1.txt")) == slurp(at("w5c2.txt")),
            "W5 (x.13): with ONE item the two layouts coincide and the files are IDENTICAL "
            "(h5 == h6) -- the quote changes the shape, and with one column there is no shape "
            "to change");
      auto rs = exec("estout w5a w5b using \"w5cs.txt\", replace cells(\"b se\") stats(N)\n", s);
      check(firstError(rs.blocks).is_null(), "W5 (x.13): stats() under the wide layout runs");
      const std::string fs = slurp(at("w5cs.txt"));
      check(has(fs, "\nN\t30\t\t30\t"),
            "W5 (x.13): ...and a stats() row spans the WIDE table with the value in the first "
            "column of each model's group and blanks after (h7: `N\t74\t\t74\t`). Got:\n" + fs);
    }

    // ── (x.14) W1a-3, esttab's DISPLAY layer. Every arm below is pinned against
    // an arm of tests/eval/golden/aer_w1/w1b_esttab_display.log that was itself
    // taken against a PLAIN CONTROL -- which is the only reason three of these
    // can land as no-ops instead of as guesses.
    {
      auto ok2 = [&](const std::string& cmd, const std::string& why) {
        auto r = exec(cmd, s);
        check(firstError(r.blocks).is_null(),
              why + " [got: " + errText(firstError(r.blocks)) + "]");
      };
      ok2("esttab w5a w5b using \"w5d0.txt\", replace\n", "W5 (x.14): the control runs");
      const std::string ctl = slurp(at("w5d0.txt"));
      // nocons / noconstant: the _cons rows go, and the two spellings agree.
      ok2("esttab w5a w5b using \"w5d1.txt\", replace nocons\n", "W5 (x.14): `nocons` runs");
      ok2("esttab w5a w5b using \"w5d2.txt\", replace noconstant\n",
          "W5 (x.14): `noconstant` runs");
      const std::string nc = slurp(at("w5d1.txt"));
      check(has(ctl, "_cons") && !has(nc, "_cons"),
            "W5 (x.14): `nocons` drops the intercept rows the control carries (x6). Got:\n" + nc);
      check(nc == slurp(at("w5d2.txt")),
            "W5 (x.14): ...and `noconstant` is byte-identical to `nocons` -- two spellings, one "
            "behaviour, which is what the capture shows");
      // type / obslast / style(fixed): MEASURED no-ops. A check that they change
      // NOTHING is what stops a later session implementing them from the name.
      for (const auto& arm : std::vector<std::pair<std::string, std::string>>{
               {"w5d3", "type"}, {"w5d4", "obslast"}, {"w5d5", "style(fixed)"}}) {
        ok2("esttab w5a w5b using \"" + arm.first + ".txt\", replace " + arm.second + "\n",
            "W5 (x.14): `" + arm.second + "` runs");
        check(slurp(at(arm.first + ".txt")) == ctl,
              "W5 (x.14): `" + arm.second + "` is byte-identical to the control -- MEASURED, not "
              "assumed (w1b_esttab_display.log x1/x2/x4, and `obslast` holds even with s(N r2) "
              "because esttab's default already puts N last)");
      }
      // style() with no writer is refused BY NAME rather than rendered as
      // something else.
      {
        auto r = exec("esttab w5a using \"w5d6.txt\", replace style(html)\n", s);
        auto err = firstError(r.blocks);
        check(!err.is_null() && err.value("message", std::string()).find("style") !=
                                    std::string::npos,
              "W5 (x.14): `style(html)` is refused by name -- there is no HTML writer, and "
              "rendering fixed-width under a request for HTML is the silent-wrong-output shape");
      }
      // varlabels(): estout's spelling of coeflabels(), 11 papers / 152 uses.
      ok2("esttab w5a using \"w5d7.txt\", replace varlabels(x1 \"Reg one\")\n",
          "W5 (x.14): `varlabels()` runs");
      check(has(slurp(at("w5d7.txt")), "Reg one"),
            "W5 (x.14): ...and it relabels the stub, the same map `coeflabels()` takes");
      // A label is a stub like any other, so it goes through the abbreviation
      // too -- which is worth pinning because the first draft of this leg used
      // a 13-character label, asserted the label back verbatim, and FAILED on
      // its own correct output.
      ok2("esttab w5a using \"w5d7b.txt\", replace varlabels(x1 \"Regressor one\")\n",
          "W5 (x.14): a long `varlabels()` label runs");
      check(has(slurp(at("w5d7b.txt")), "Regressor ~e"),
            "W5 (x.14): ...and a label wider than the stub is abbreviated like any other stub "
            "(`Regressor one` -> `Regressor ~e`), not printed whole");
      // BUG-490: the stub is abbreviated, and `noabbrev` is what turns it off.
      (void)exec("generate double a_very_long_variable_name_here = x1 * 2\n", s);
      (void)exec("regress y a_very_long_variable_name_here x2\n", s);
      (void)exec("eststo w5long\n", s);
      ok2("esttab w5long using \"w5d8.txt\", replace\n", "W5 (x.14): the long-name arm runs");
      ok2("esttab w5long using \"w5d9.txt\", replace noabbrev\n",
          "W5 (x.14): the `noabbrev` arm runs");
      const std::string ab = slurp(at("w5d8.txt"));
      const std::string nab = slurp(at("w5d9.txt"));
      check(has(ab, "a_very_lon~e") && !has(ab, "a_very_long_variable_name_here"),
            "W5 (x.14): a stub wider than the column is abbreviated to ten characters, a tilde "
            "and the last one -- `a_very_lon~e`, which is exactly what StataBE renders for this "
            "name (w1b_esttab_abbrev2.log, arm name_default). Got:\n" + ab);
      check(has(nab, "a_very_long_variable_name_here"),
            "W5 (x.14): ...and `noabbrev` prints it whole (arm name_noabbrev) -- which is what "
            "this build used to do unconditionally. Got:\n" + nab);
      // The trailing-digit half of the rule, which one example cannot show.
      (void)exec("generate double abcdefghijklm1234567 = x2 * 3\n", s);
      (void)exec("regress y abcdefghijklm1234567\n", s);
      (void)exec("eststo w5dig\n", s);
      ok2("esttab w5dig using \"w5da.txt\", replace\n", "W5 (x.14): the digit-tail arm runs");
      check(has(slurp(at("w5da.txt")), "abcd~1234567"),
            "W5 (x.14): ...and the TRAILING DIGIT RUN is what survives -- `abcd~1234567`, four "
            "head characters against seven digits, not the ten-and-one of a name that ends in a "
            "letter. Two examples with different splits are what make this a rule and not a "
            "truncation");
      // nobaselevels: a no-op here, and the selftest says WHY so the next
      // reader does not file it as unimplemented.
      ok2("esttab w5a using \"w5db.txt\", replace nobaselevels\n",
          "W5 (x.14): `nobaselevels` runs -- a validated no-op: this engine's coeftable carries "
          "no base level for a factor at all, so the row Stata's default prints and this option "
          "removes never exists here (BUG-492)");
    }

    // ── (x.16) W1a-5b: the `stats()` SUB-GRAMMAR, `s()`, `sfmt()`, `nolabel`.
    // `stats(N r2, labels("Obs" "R2") fmt(0 3))` used to split on whitespace
    // and render FIVE garbage footer rows -- `r2,` / `labels("Obs"` / `"R2")` /
    // `fmt(0` / `3)` -- at rc 0. Oracle: w1b_stats_grammar{,2}.log and
    // w1b_sfmt_rule.log.
    {
      auto okc = [&](const std::string& cmd, const std::string& why) {
        auto r = exec(cmd, s);
        check(firstError(r.blocks).is_null(),
              why + " [got: " + errText(firstError(r.blocks)) + "]");
      };
      (void)exec("estadd scalar mymean = 6165.257\n", s);
      (void)exec("estadd scalar myother = 1.23456789\n", s);
      (void)exec("eststo w5sc\n", s);
      okc("esttab w5sc using \"w5t1.txt\", replace stats(N r2, labels(\"Obs\" \"R2\") fmt(0 3))\n",
          "W5 (x.16): `stats(keys, labels() fmt())` runs");
      const std::string t1 = slurp(at("w5t1.txt"));
      check(has(t1, "Obs") && has(t1, "R2"),
            "W5 (x.16): ...and labels() replaces the row names (s2/s4). Got:\n" + t1);
      check(!has(t1, "labels(") && !has(t1, "fmt(") && !has(t1, "r2,"),
            "W5 (x.16): ...and the SUBOPTIONS are parsed, not rendered as rows. This build turned "
            "them into five footer rows at rc 0 -- a wrong table nothing stopped. Got:\n" + t1);
      // labels() is positional and short lists leave the rest alone (s3/d3).
      okc("esttab w5sc using \"w5t2.txt\", replace stats(N r2, labels(\"Obs\"))\n",
          "W5 (x.16): a PARTIAL labels() runs");
      const std::string t2 = slurp(at("w5t2.txt"));
      check(has(t2, "Obs") && has(t2, "\nr2"),
            "W5 (x.16): ...and the keys it does not reach keep their own name (d3). Got:\n" + t2);
      // fmt() is positional, and ONE entry serves every key (d1/d2).
      okc("esttab w5sc using \"w5t3.txt\", replace stats(N r2, fmt(2 5))\n",
          "W5 (x.16): a two-entry fmt() runs");
      {
        // Fixture-independent: N's DEFAULT is an integer count with no decimal
        // point at all, so a dot in the N row is the whole discriminator.
        // (Asserting the oracle's `74.00` here fails on this leg's 30-row
        // fixture -- the third time in this session that a check written from
        // an oracle number failed against correct output.)
        const std::string t3 = slurp(at("w5t3.txt"));
        const size_t nAt = t3.find("\nN ");
        const size_t eol = nAt == std::string::npos ? std::string::npos : t3.find('\n', nAt + 1);
        const std::string nRow =
            nAt == std::string::npos ? std::string() : t3.substr(nAt, eol - nAt);
        check(nRow.find('.') != std::string::npos,
              "W5 (x.16): ...and it is POSITIONAL -- the FIRST fmt() entry reaches N, which "
              "otherwise renders as an integer count with no decimal point (d1). Got the N row: `" +
                  nRow + "`");
      }
      // `s()` is estout's one-character minimum for stats().
      okc("esttab w5sc using \"w5t4.txt\", replace s(N r2)\n",
          "W5 (x.16): `s()` is estout's abbreviation of stats() (s7) -- 18 of the 32 obslast uses "
          "and 13 of the 82 sfmt uses spell it, and it was r(198)");
      // sfmt governs the scalars() rows and NOTHING else.
      okc("esttab w5sc using \"w5t5.txt\", replace scalars(mymean)\n",
          "W5 (x.16): `scalars()` runs");
      okc("esttab w5sc using \"w5t6.txt\", replace scalars(mymean) sfmt(5)\n",
          "W5 (x.16): `scalars() sfmt()` runs");
      const std::string t5 = slurp(at("w5t5.txt"));
      const std::string t6 = slurp(at("w5t6.txt"));
      check(has(t5, "6165.3") && !has(t5, "6165.25700"),
            "W5 (x.16): a scalars() row defaults to esttab's ADAPTIVE a3 -- 6165.257 renders "
            "`6165.3` (q5), which three decimals cannot produce. Got:\n" + t5);
      check(has(t6, "6165.25700"),
            "W5 (x.16): ...and `sfmt(5)` is what moves it (q4). Those two arms are the ONLY pair "
            "in twelve that separates sfmt from a no-op: it is inert against stats() keys, N, r2, "
            "the r2/ar2 flags, `plain` and `b()/se()`. Got:\n" + t6);
      // A key the user NAMED keeps its own label; the FLAG keeps the pretty one.
      okc("esttab w5sc using \"w5t7.txt\", replace stats(r2)\n", "W5 (x.16): `stats(r2)` runs");
      okc("esttab w5sc using \"w5t8.txt\", replace r2\n", "W5 (x.16): the `r2` FLAG runs");
      check(has(slurp(at("w5t7.txt")), "\nr2") && has(slurp(at("w5t8.txt")), "R-sq"),
            "W5 (x.16): a key named in stats() keeps its OWN spelling (`r2`, s1) while the FLAG "
            "carries the pretty label (`R-sq`, q1) -- this build gave both the pretty one");
      // nolabel cancels the TEXT and not the WIDTH.
      okc("esttab w5sc using \"w5t9.txt\", replace label\n", "W5 (x.16): `label` runs");
      okc("esttab w5sc using \"w5ta.txt\", replace label nolabel\n",
          "W5 (x.16): `label nolabel` runs -- it was r(198), the name being in neither vocabulary "
          "list");
      okc("esttab w5sc using \"w5tb.txt\", replace nolabel\n", "W5 (x.16): `nolabel` alone runs");
      const std::string t9 = slurp(at("w5t9.txt"));
      const std::string ta = slurp(at("w5ta.txt"));
      const std::string tb = slurp(at("w5tb.txt"));
      check(t9.find('\n') == ta.find('\n') && ta.find('\n') > tb.find('\n'),
            "W5 (x.16): `nolabel` cancels the label TEXT and NOT the width -- `label nolabel` is "
            "still ruled at the 20-column stub `label` set, while `nolabel` alone keeps 12 "
            "(s11/s12/s13). Two effects, two flags");
    }

    // ── (x.17) W1a-5c: `nogaps` was ACCEPTED AND IGNORED, and `alignment()`
    // was refused while its own abbreviation `align()` was accepted-and-dropped.
    // Oracle: w1b_esttab_resid.log y5/y6 (gaps) and y11/y12/y13 (tex column).
    {
      auto okc = [&](const std::string& cmd, const std::string& why) {
        auto r = exec(cmd, s);
        check(firstError(r.blocks).is_null(),
              why + " [got: " + errText(firstError(r.blocks)) + "]");
      };
      auto blanks = [](const std::string& t) {
        size_t n = 0, pos = 0;
        while (pos <= t.size()) {
          const size_t nl = t.find('\n', pos);
          if (t.substr(pos, (nl == std::string::npos ? t.size() : nl) - pos).empty()) ++n;
          if (nl == std::string::npos) break;
          pos = nl + 1;
        }
        return n;
      };
      okc("esttab w5a using \"w5u1.txt\", replace\n", "W5 (x.17): the control runs");
      okc("esttab w5a using \"w5u2.txt\", replace nogaps\n", "W5 (x.17): `nogaps` runs");
      okc("esttab w5a using \"w5u3.txt\", replace gaps\n",
          "W5 (x.17): `gaps` runs -- it was r(198) and it is the DEFAULT, so a validated no-op");
      const size_t bCtl = blanks(slurp(at("w5u1.txt")));
      const size_t bNo = blanks(slurp(at("w5u2.txt")));
      const size_t bYes = blanks(slurp(at("w5u3.txt")));
      check(bCtl > bNo,
            "W5 (x.17): `nogaps` REMOVES the blank line between coefficients. It was in the KNOWN "
            "list and did nothing -- accepted and ignored, which is the one thing a vocabulary "
            "entry is not allowed to mean here. Got " + std::to_string(bCtl) + " vs " +
                std::to_string(bNo));
      check(bYes == bCtl,
            "W5 (x.17): ...and `gaps` matches the control, because the gap is already the default "
            "(y5). A no-op that is MEASURED is not the same as one that is assumed");
      // The tex column letter, both spellings.
      okc("esttab w5a using \"w5u4.tex\", replace tex alignment(S)\n",
          "W5 (x.17): `alignment()` runs -- it was r(198) while its own five-character "
          "abbreviation `align()` was accepted and dropped");
      okc("esttab w5a using \"w5u5.tex\", replace tex align(S)\n", "W5 (x.17): `align()` runs");
      okc("esttab w5a using \"w5u6.tex\", replace tex\n", "W5 (x.17): the tex control runs");
      check(has(slurp(at("w5u4.tex")), "{S}") && has(slurp(at("w5u5.tex")), "{S}"),
            "W5 (x.17): ...and both spellings reach the column letter -- `l*{k}{S}` (y12)");
      check(has(slurp(at("w5u6.tex")), "{c}"),
            "W5 (x.17): ...while the default stays `c`, which is why `alignment(c)` is "
            "byte-identical to the control (y11)");
    }

    // ── (x.18) W1a-5d: `pr2`, and the SECOND name its number arrives under.
    // Oracle: w1b_esttab_resid.log y8 (`pseudo R-sq 0.397`) and y9 (`pr2(4)`
    // -> four decimals). The interesting half is engine-side: this engine
    // publishes the pseudo-R2 as `r2_p` after poisson and as `r2_pseudo` after
    // logit/probit, each leaving the other missing -- and `r2_pseudo` was not
    // in the e-scalar key table, so it never reached a STORED estimate and the
    // cell came back blank for exactly the family `pr2` is used on.
    {
      piet::SessionState p(workdir);
      p.eval.cwd = workdir;
      p.cwd = workdir;
      // `y > 0` is not guaranteed to SPLIT on this fixture, and a constant
      // dependent variable makes the fit fail and `eststo` store nothing --
      // which is how this arm first read as "pr2 is still refused".
      (void)exec(kMake30 +
                     "generate byte hi = mod(_n, 2)\n"
                     "logit hi x1 x2\n"
                     "eststo pl\n",
                 p);
      auto rl = exec("esttab pl using \"w5p1.txt\", replace pr2\n", p);
      check(firstError(rl.blocks).is_null(),
            "W5 (x.18): `esttab <logit>, pr2` runs -- it was r(198) [got: " +
                errText(firstError(rl.blocks)) + "]");
      const std::string p1 = slurp(at("w5p1.txt"));
      check(has(p1, "pseudo R-sq"),
            "W5 (x.18): ...and the row is labelled `pseudo R-sq` (y8). Got:\n" + p1);
      // The discriminating part: the cell must carry a NUMBER. Reading only
      // `r2_p` leaves it blank here, which is what this build did.
      const size_t at2 = p1.find("pseudo R-sq");
      const std::string row = at2 == std::string::npos
                                  ? std::string()
                                  : p1.substr(at2, p1.find('\n', at2) - at2);
      check(row.find('.') != std::string::npos,
            "W5 (x.18): ...and it is NOT BLANK. The engine publishes this number as `r2_pseudo` "
            "after logit/probit and as `r2_p` after poisson; a reader that knows one key answers "
            "nothing for the other family, and both live corpus uses are probit. Got the row: `" +
                row + "`");
      auto r4 = exec("esttab pl using \"w5p2.txt\", replace pr2(4)\n", p);
      check(firstError(r4.blocks).is_null(), "W5 (x.18): `pr2(4)` runs");
      const std::string p2 = slurp(at("w5p2.txt"));
      const size_t at3 = p2.find("pseudo R-sq");
      const std::string row4 =
          at3 == std::string::npos ? std::string() : p2.substr(at3, p2.find('\n', at3) - at3);
      const size_t dot = row4.find('.');
      size_t dec = 0;
      for (size_t i = dot + 1; dot != std::string::npos && i < row4.size() &&
                               std::isdigit(static_cast<unsigned char>(row4[i]));
           ++i) {
        ++dec;
      }
      check(dec == 4,
            "W5 (x.18): ...and `pr2(#)` carries its own decimal count (y9), the same way `b(3)` "
            "does. Got " + std::to_string(dec) + " in `" + row4 + "`");
      auto rc2 = exec("esttab pl using \"w5p3.txt\", replace\n", p);
      check(firstError(rc2.blocks).is_null() && !has(slurp(at("w5p3.txt")), "pseudo"),
            "W5 (x.18): ...and without the option there is no such row at all");
    }

    // ── (x.19) W1a-5e: `labcol2()` -- ONE extra column between the stub and
    // the model columns, 456 corpus uses across 14 spellings. Oracle:
    // w1b_labcol2.log (k0..k8) and w1b_esttab_resid.log y15, which is where
    // the geometry comes from: the fixed field is 13 wide and CENTRED, and the
    // tex cell is plain rather than a \multicolumn.
    {
      auto okc = [&](const std::string& cmd, const std::string& why) {
        auto r = exec(cmd, s);
        check(firstError(r.blocks).is_null(),
              why + " [got: " + errText(firstError(r.blocks)) + "]");
      };
      okc("esttab w5a w5b using \"w5l0.txt\", replace\n", "W5 (x.19): the control runs");
      okc("esttab w5a w5b using \"w5l1.txt\", replace labcol2(1.5 3.5, title(Extra))\n",
          "W5 (x.19): `labcol2(values, title())` runs -- it was r(198)");
      okc("esttab w5a w5b using \"w5l2.txt\", replace labcol2(1.5 3.5)\n",
          "W5 (x.19): ...and the title is optional");
      okc("esttab w5a w5b using \"w5l3.tex\", replace tex labcol2(1.5 3.5, title(Extra))\n",
          "W5 (x.19): ...and it reaches the tex writer too");
      const std::string l0 = slurp(at("w5l0.txt"));
      const std::string l1 = slurp(at("w5l1.txt"));
      const std::string l2 = slurp(at("w5l2.txt"));
      const std::string l3 = slurp(at("w5l3.tex"));
      check(l1.find('\n') == l0.find('\n') + 13,
            "W5 (x.19): the rule grows by exactly 13 -- the field's width, measured off the "
            "oracle's own columns rather than chosen (y15: 44 -> 57). Got " +
                std::to_string(l1.find('\n')) + " against " + std::to_string(l0.find('\n')));
      check(has(l1, "   Extra    ") || has(l1, "    Extra    "),
            "W5 (x.19): ...and the title is CENTRED in it, not padded to either side -- `Extra` "
            "at 16-20 inside the field 12..24 is centring and nothing else. Got:\n" + l1);
      check(!has(l2, "Extra") && l2.find('\n') == l1.find('\n'),
            "W5 (x.19): ...while WITHOUT a title the column is still there and its head is blank "
            "(k2) -- the width does not depend on the title");
      check(has(l3, "{lc*{2}{c}}"),
            "W5 (x.19): in tex the column spec gains a plain `c` between the stub and the models "
            "(k5). Got:\n" + l3.substr(0, 120));
      check(has(l3, "&   Extra    &\\multicolumn"),
            "W5 (x.19): ...and the head cell is a PLAIN centred cell, not a \\multicolumn like "
            "the model heads beside it (k5). Got:\n" + l3.substr(0, 220));
      // The values are positional over COEFFICIENTS, so the aux row under the
      // first coefficient keeps a blank field.
      const size_t firstCoef = l1.find("\nx1");
      const size_t auxLine = firstCoef == std::string::npos
                                 ? std::string::npos
                                 : l1.find('\n', firstCoef + 1);
      const std::string aux =
          auxLine == std::string::npos ? std::string() : l1.substr(auxLine + 1, 25);
      check(aux.find("1.5") == std::string::npos,
            "W5 (x.19): ...and a value belongs to the COEFFICIENT, not to the row -- the aux row "
            "beneath it keeps a blank field (k1). Got: `" + aux + "`");
    }

    // -- (x.28) BUG-501: a string literal is DATA, and every pre-pass in
    // evalArith was rewriting its contents. Oracle: w1b_braceliteral.log (BL|*)
    // and w1b_quoteblind.log (QB|*).
    //
    // The nine-line version of this fix -- widening isSafeArithExt to skip
    // quoted spans -- was written, measured and REVERTED on 2026-09-18, because
    // the filter had been SHIELDING the pre-passes underneath it and fixing it
    // alone turned a silent echo into a silent wrong ANSWER. These arms are what
    // that reversal bought: each one is a pre-pass, not the filter.
    {
      auto say = [&](const std::string& expr) {
        auto r = exec("display \"XX|\" " + expr + " \"|\"\n", s);
        for (const auto& b : r.blocks) {
          if (b.value("type", std::string()) != "display") continue;
          const std::string t = b.value("text", std::string());
          if (t.rfind("XX|", 0) == 0 && t.size() >= 4) return t.substr(3, t.size() - 4);
        }
        return std::string("<no display>");
      };

      // The filter. Twelve characters used to stop the expression being
      // evaluated at all, and `display` echoed the SOURCE TEXT at rc 0 -- an
      // evaluation failure that surfaces as an echo is invisible to every gate
      // that reads return codes.
      check(say("strpos(\"abc\", \"b\")") == "2",
            "W5 (x.28): the control evaluates (BL|plain|2|)");
      check(say("strpos(\"a{b}c\", \"b\")") == "3",
            "W5 (x.28): a BRACE inside a literal is an ordinary character (BL|brace_hay|3|). This "
            "echoed `strpos(\"a{b}c\", \"b\")` at rc 0. Got `" + say("strpos(\"a{b}c\", \"b\")") +
                "`");
      check(say("length(\"a{b}c\")") == "5" && say("substr(\"a{b}c\", 2, 3)") == "{b}" &&
                say("upper(\"a{b}c\")") == "A{B}C",
            "W5 (x.28): ...on every string function, not just the one (BL|length/substr/upper)");
      check(say("strpos(\"a[b]c\", \"b\")") == "3" &&
                say("length(\"a;b@c&d|e~f:g#h\")") == "15",
            "W5 (x.28): ...and for the other eleven characters -- brackets and punctuation "
            "(BL|brace_needle, QB|punct|15|)");

      // THE PRE-PASSES, which is the half the reverted fix got wrong. Each of
      // these is a string whose CONTENT looks like something the expression layer
      // resolves, and in Stata all of them are just characters.
      check(say("strpos(\"A[1,1]\", \"1\")") == "3",
            "W5 (x.28): a MATRIX SUBSCRIPT inside a literal is not a subscript (QB|matrix_sub|3|). "
            "With the filter widened and this pre-pass left alone the answer was 1 -- a silent "
            "wrong number where there had been a silent echo, which is the worse of the two. Got `" +
                say("strpos(\"A[1,1]\", \"1\")") + "`");
      check(say("strpos(\"a^b\", \"b\")") == "3",
            "W5 (x.28): ...nor is a CARET an operator there -- the `^`->`**` rewrite used to change "
            "the string's length");
      check(say("strpos(\"ln\", \"n\")") == "2",
            "W5 (x.28): ...nor is `ln` the log function -- the `\\bln\\b`->`log` rewrite used to "
            "reach inside too");
      check(say("length(\"say hello\")") == "9",
            "W5 (x.28): ...and an ordinary sentence still measures itself");

      // Protection is ONE-SIDED: an unterminated quote is left exactly as it was,
      // so nothing this function already judged changes.
      check(say("strpos(\"abc\", \"b\")") == "2",
            "W5 (x.28): the balanced case still works after all of that");

      // BUG-502: STATA HAS NO ESCAPE SEQUENCES in a double-quoted literal. This
      // lexer was written to Python semantics -- its own comment said so -- and
      // every one of its callers evaluates a STATA expression.
      check(say("length(\"a\\nb\")") == "4",
            "W5 (x.502): `\"a\\nb\"` is FOUR characters -- backslash, n, and the two letters. The C "
            "table made it three, silently, and it is the ordinary way a Windows path is written. "
            "Got `" + say("length(\"a\\nb\")") + "`");
      check(say("length(\"\\begin\")") == "6" && say("length(\"a\\\\b\")") == "4",
            "W5 (x.502): ...and `\"\\begin\"` is six and `\"a\\\\b\"` is four -- `\\b` was a "
            "backspace and `\\\\` collapsed to one. Every LaTeX-writing do-file carries the first");
      check(say("strpos(\"c:\\data\\x.dta\", \"x\")") == "9",
            "W5 (x.502): ...so a path measures itself: `\\d` and `\\x` are two characters each");
      check(say("strpos(\"\\begin{tabular}{lc}\", \"tabular\")") == "8",
            "W5 (x.502): ...and the arm that found this one -- 8, not 7 -- which only comes out "
            "right with BUG-443's protection AND this table gone. The two fixes are independent "
            "and this arm needs both");
    }

    // -- (x.27) W1a-4 follow-on: `indicate()`, and the `nostar` WIDTH it turned
    // up. Oracle: w1b_indicate.log (n*/e*/u*). Censusing the five options esttab
    // still refused removed one before any arm was written: `begin` had 64
    // apparent uses and every one is `\begin{tabular}` inside a prehead()
    // argument -- `begin(` as an option is ZERO on both writers. A name census
    // counts names, and `\begin` is a name in a different language.
    {
      auto oki = [&](const std::string& cmd, const std::string& why) {
        auto r = exec(cmd, s);
        check(firstError(r.blocks).is_null(),
              why + " [got: " + errText(firstError(r.blocks)) + "]");
      };
      auto firstLineLen = [&](const std::string& f) {
        const std::string t = slurp(at(f));
        const size_t e = t.find('\n');
        return (e == std::string::npos ? t.size() : e);
      };
      auto hasRowStarting = [&](const std::string& f, const std::string& pre) {
        const std::string t = slurp(at(f));
        size_t i = 0;
        while (i < t.size()) {
          size_t e = t.find('\n', i);
          if (e == std::string::npos) e = t.size();
          if (t.compare(i, pre.size(), pre) == 0) return true;
          i = e + 1;
        }
        return false;
      };

      // THE WIDTH. The rule line measures the whole geometry, and `nostar` zeroes
      // the three-character star field: the oracle's nostar table rules at 38 and
      // its starred one at 44 (n0 against w1b_headfoot.log pb). This build wrote
      // 44 for both -- 230 corpus uses over 22 papers, every row carrying three
      // trailing spaces, and NO existing arm pinned it.
      oki("esttab w5a w5b using \"w5i0.txt\", replace b se nostar\n",
          "W5 (x.27): the nostar control runs");
      check(firstLineLen("w5i0.txt") == 38,
            "W5 (x.27): ...and `nostar` rules at 38 = 12 + 2*(1+12+0) -- the star field is GONE, "
            "not merely empty (n0). At 44 every row of every nostar table carries three trailing "
            "spaces. Got " + std::to_string(firstLineLen("w5i0.txt")));
      oki("esttab w5a w5b using \"w5i1.txt\", replace b se\n",
          "W5 (x.27): the starred control runs");
      check(firstLineLen("w5i1.txt") == 44,
            "W5 (x.27): ...and WITH stars it rules at 44 (w1b_headfoot.log pb). The pair is the "
            "measurement: one width alone cannot say whether the field is reserved by option or by "
            "content. Got " + std::to_string(firstLineLen("w5i1.txt")));

      // indicate(): the named coefficients LEAVE and one Yes/No row replaces them.
      oki("esttab w5a w5b using \"w5i2.txt\", replace b se nostar indicate(\"Controls = x2\")\n",
          "W5 (x.27): `indicate()` runs -- it was an unknown option");
      check(hasRowStarting("w5i2.txt", "Controls") && !hasRowStarting("w5i2.txt", "x2"),
            "W5 (x.27): ...and the coefficient it names is GONE, replaced by one row (n1). A row "
            "ADDED beside the coefficients would pass a presence-only check, which is why the "
            "absence is asserted too. Got:\n" + slurp(at("w5i2.txt")));
      check(has(slurp(at("w5i2.txt")), "Yes"),
            "W5 (x.27): ...whose cells say Yes for a model that has it (n1)");

      // The default second label is `No`, and it takes a model that LACKS the
      // varlist to see it. This fixture has one: w5b is `regress y x1`, so the
      // same arm shows both halves -- with every model carrying the varlist both
      // cells read Yes and `labels(Yes)` is indistinguishable from the default
      // (the oracle's n2 is byte-identical to n1 for exactly that reason).
      check(has(slurp(at("w5i2.txt")), "No"),
            "W5 (x.27): ...and No for the model that does not (n6). w5b is `regress y x1`, so this "
            "one arm carries both halves of labels(); a table where every model has the varlist "
            "cannot see the second label at all. Got:\n" + slurp(at("w5i2.txt")));
      oki("esttab w5a w5b using \"w5i4.txt\", replace b se nostar "
          "indicate(\"Controls = x2\", labels(\"YES\" \" \"))\n",
          "W5 (x.27): `labels()` runs");
      check(has(slurp(at("w5i4.txt")), "YES"),
            "W5 (x.27): ...and replaces the present-label (n3)");

      oki("esttab w5a w5b using \"w5i5.txt\", replace b se nostar indicate(\"x2\")\n",
          "W5 (x.27): an `indicate()` group with no `=` runs");
      check(hasRowStarting("w5i5.txt", "x2 ") || hasRowStarting("w5i5.txt", "x2"),
            "W5 (x.27): ...and the row's label is the VARLIST text itself (n7)");
      oki("esttab w5a w5b using \"w5i6.txt\", replace b se nostar indicate(\"Controls = x*\")\n",
          "W5 (x.27): a GLOB varlist runs");
      check(!hasRowStarting("w5i6.txt", "x1") && !hasRowStarting("w5i6.txt", "x2"),
            "W5 (x.27): ...and takes every coefficient it matches (n4 keeps the one it does NOT "
            "match, which is the same statement from the other side). Got:\n" +
                slurp(at("w5i6.txt")));
      oki("esttab w5a w5b using \"w5i7.txt\", replace b se nostar "
          "indicate(\"A = x1\" \"B = x2\")\n",
          "W5 (x.27): two quoted groups run");
      check(hasRowStarting("w5i7.txt", "A") && hasRowStarting("w5i7.txt", "B"),
            "W5 (x.27): ...as two rows (n5)");
      check(has(slurp(at("w5i7.txt")), "\n\nB"),
            "W5 (x.27): ...with a BLANK LINE between them (n5). They are a block of groups, not a "
            "run of rows, and this arm is the only thing that says so");

      // Measured no-ops, pinned as SAMENESS -- the W1a-3 treatment.
      oki("esttab w5a w5b using \"w5i8.txt\", replace b se nostar eqlabels(none)\n",
          "W5 (x.27): `eqlabels(none)` runs");
      oki("esttab w5a w5b using \"w5i9.txt\", replace b se nostar unstack\n",
          "W5 (x.27): `unstack` runs");
      check(slurp(at("w5i8.txt")) == slurp(at("w5i0.txt")) &&
                slurp(at("w5i9.txt")) == slurp(at("w5i0.txt")),
            "W5 (x.27): ...and BOTH are byte-identical to the control (e1/u1). They act on "
            "multi-equation tables, and this engine's coeftable carries no equation at all, so on "
            "every table it can produce they are no-ops -- accepted with the SAMENESS pinned, the "
            "way W1a-3 handled type/obslast/style(fixed). If the engine ever carries equations, "
            "this arm is what has to be revisited");

      // And one option whose refusal is PARITY.
      auto rtr = exec("esttab w5a w5b using \"w5ia.txt\", replace b se nostar transpose\n", s);
      check(!firstError(rtr.blocks).is_null(),
            "W5 (x.27): `transpose` stays REFUSED, and that is parity: esttab answers r(198) "
            "\"option transpose not allowed\" in Stata too (tr_pose), so the six corpus lines that "
            "spell it do not run there either. It is estout's option, not esttab's");
    }

    // -- (x.26) W1a-4: the rest of estout's option row. Oracle:
    // w1b_estout_opts.log (q*) and w1b_estout_opts2.log (y*/z*). The four seam
    // hooks are ADDITIVE here, which is the opposite of what the same four do on
    // esttab (x.24, where they REPLACE a block) -- so a shared implementation
    // would have been wrong for one of the two commands, and the arms are paired
    // across x.24/x.26 for exactly that reason.
    {
      auto oko = [&](const std::string& cmd, const std::string& why) {
        auto r = exec(cmd, s);
        check(firstError(r.blocks).is_null(),
              why + " [got: " + errText(firstError(r.blocks)) + "]");
      };
      auto lineOf = [&](const std::string& f, size_t n) {
        const std::string t = slurp(at(f));
        size_t start = 0;
        for (size_t i = 0; i < n; ++i) {
          const size_t e = t.find('\n', start);
          if (e == std::string::npos) return std::string();
          start = e + 1;
        }
        const size_t e = t.find('\n', start);
        return t.substr(start, (e == std::string::npos ? t.size() : e) - start);
      };
      auto lastLine = [&](const std::string& f) {
        std::string t = slurp(at(f));
        while (!t.empty() && (t.back() == '\n' || t.back() == '\r')) t.pop_back();
        const size_t nl = t.rfind('\n');
        return nl == std::string::npos ? t : t.substr(nl + 1);
      };

      oko("estout w5a w5b using \"w5o1.txt\", replace cells(b se) prehead(PREHEAD)\n",
          "W5 (x.26): estout `prehead()` runs -- it was a named refusal");
      check(lineOf("w5o1.txt", 0) == "PREHEAD",
            "W5 (x.26): ...and is ADDITIVE: the header rows follow it unchanged (q b). On esttab "
            "the same option REPLACES the whole opening block (x.24) -- a tab table has no block "
            "to replace, so one implementation for both commands is wrong for one of them. Got `" +
                lineOf("w5o1.txt", 0) + "`");
      oko("estout w5a w5b using \"w5o2.txt\", replace cells(b se) posthead(POSTHEAD)\n",
          "W5 (x.26): `posthead()` runs");
      check(lineOf("w5o2.txt", 2) == "POSTHEAD",
            "W5 (x.26): ...and sits between the cell-name row and the body (qc). Got `" +
                lineOf("w5o2.txt", 2) + "`");
      oko("estout w5a w5b using \"w5o3.txt\", replace cells(b se) stats(N) prefoot(PREFOOT)\n",
          "W5 (x.26): `prefoot()` runs");
      check(has(slurp(at("w5o3.txt")), "PREFOOT\nN"),
            "W5 (x.26): ...immediately above the stats block (qd). Got:\n" + slurp(at("w5o3.txt")));
      oko("estout w5a w5b using \"w5o4.txt\", replace cells(b se) stats(N) postfoot(POSTFOOT)\n",
          "W5 (x.26): `postfoot()` runs");
      check(lastLine("w5o4.txt") == "POSTFOOT",
            "W5 (x.26): ...and is the LAST line (qe). Got `" + lastLine("w5o4.txt") + "`");
      oko("estout w5a w5b using \"w5o5.txt\", replace cells(b se) prefoot(PREFOOT)\n",
          "W5 (x.26): `prefoot()` with NO stats runs");
      check(lastLine("w5o5.txt") == "PREFOOT",
            "W5 (x.26): ...and still emits, at the position the footer would have started "
            "(w1b_estout_opts2.log y9). A hook that only fired when it had something to sit above "
            "would pass every other arm here");

      oko("estout w5a w5b using \"w5o6.txt\", replace cells(b se) begin(BEGIN)\n",
          "W5 (x.26): `begin()` runs");
      check(lineOf("w5o6.txt", 0).compare(0, 5, "BEGIN") == 0 &&
                lineOf("w5o6.txt", 2).compare(0, 5, "BEGIN") == 0,
            "W5 (x.26): ...and prefixes EVERY row, header rows included, with no separator of its "
            "own (qf). Got `" + lineOf("w5o6.txt", 0) + "` / `" + lineOf("w5o6.txt", 2) + "`");

      // `legend` prints the ladder DESCENDING -- the opposite of the ladder's own
      // order -- and only when the cells carry stars.
      oko("estout w5a w5b using \"w5o7.txt\", replace cells(b(star)) legend\n",
          "W5 (x.26): `legend` runs");
      check(lastLine("w5o7.txt") == "* p<0.05, ** p<0.01, *** p<0.001",
            "W5 (x.26): ...and prints estout's default ladder DESCENDING by cutoff (y6), which is "
            "the reverse of how estoutStars() holds it. Got `" + lastLine("w5o7.txt") + "`");
      oko("estout w5a w5b using \"w5o8.txt\", replace cells(b(star)) "
          "starlevels(+ 0.10 * 0.05 ** 0.01) legend\n",
          "W5 (x.26): `legend` under a custom ladder runs");
      check(lastLine("w5o8.txt") == "+ p<0.10, * p<0.05, ** p<0.01",
            "W5 (x.26): ...and prints its levels VERBATIM -- `0.10` keeps the trailing zero (y7). "
            "Reformatting the parsed double would give `p<0.1`, which is the arm that says the "
            "option's own tokens have to be re-read for the text. Got `" + lastLine("w5o8.txt") +
                "`");
      oko("estout w5a w5b using \"w5o9.txt\", replace cells(b) legend\n",
          "W5 (x.26): `legend` with a starless spec runs");
      check(lastLine("w5o9.txt").find("p<") == std::string::npos,
            "W5 (x.26): ...and adds NOTHING, because there are no stars to explain (y8). Got `" +
                lastLine("w5o9.txt") + "`");

      // extracols() inserts EMPTY columns after the columns it names, the stub
      // being column 1.
      oko("estout w5a w5b using \"w5oa.txt\", replace cells(b se) extracols(1)\n",
          "W5 (x.26): `extracols(1)` runs");
      oko("estout w5a w5b using \"w5ob.txt\", replace cells(b se) extracols(2)\n",
          "W5 (x.26): `extracols(2)` runs");
      // Asserted on the MODEL-NAME row by content rather than by line index: the
      // fixture's table carries a row this scratch session's did not, and an
      // index would be pinning the fixture instead of the option.
      check(has(slurp(at("w5oa.txt")), "\t\tw5a\tw5b"),
            "W5 (x.26): ...and 1 puts the empty column between the STUB and the first model -- two "
            "delimiters before the first model name (y2). Got:\n" + slurp(at("w5oa.txt")));
      check(has(slurp(at("w5ob.txt")), "\tw5a\t\tw5b"),
            "W5 (x.26): ...while 2 puts it between the two models (y3). The pair is what says the "
            "stub counts as column 1. Got:\n" + slurp(at("w5ob.txt")));

      oko("estout w5a w5b using \"w5oc.txt\", replace cells(b se) rename(x1 MILEAGE)\n",
          "W5 (x.26): `rename()` runs");
      check(has(slurp(at("w5oc.txt")), "MILEAGE"),
            "W5 (x.26): ...and renames the row (q8)");
      oko("estout w5a w5b using \"w5od.txt\", replace cells(b se) rename(nosuch ZZZ)\n",
          "W5 (x.26): ...and a rename whose source is not in the model runs");
      check(!has(slurp(at("w5od.txt")), "ZZZ") && !has(slurp(at("w5od.txt")), "nosuch"),
            "W5 (x.26): ...changing nothing and erroring not at all (y b)");
    }

    // -- (x.25) W1a-4: estout's style(tex) is its OWN geometry, not esttab's.
    // BUG-486's sixth axis, and the largest block left in the bundle: 148 of the
    // corpus's 219 estout lines carry tex. Oracle: w1b_estout_tex.log (r*) and
    // w1b_estout_tex2.log (s*/v*). The assertions are FIELD WIDTHS rather than
    // whole lines, because the widths are the option's entire content and the
    // numbers inside them belong to the fixture; the two header rows, which carry
    // no fixture numbers, are asserted whole.
    {
      // The per-field widths of one row: split on `&` after dropping the `\\`.
      auto widths = [&](const std::string& line) {
        std::vector<size_t> w;
        if (line.size() < 2 || line.compare(line.size() - 2, 2, "\\\\") != 0) return w;
        const std::string body = line.substr(0, line.size() - 2);
        size_t start = 0;
        while (true) {
          const size_t amp = body.find('&', start);
          if (amp == std::string::npos) {
            w.push_back(body.size() - start);
            break;
          }
          w.push_back(amp - start);
          start = amp + 1;
        }
        return w;
      };
      auto lineN = [&](const std::string& f, size_t n) {
        const std::string t = slurp(at(f));
        size_t start = 0;
        for (size_t i = 0; i < n; ++i) {
          const size_t e = t.find('\n', start);
          if (e == std::string::npos) return std::string();
          start = e + 1;
        }
        const size_t e = t.find('\n', start);
        return t.substr(start, (e == std::string::npos ? t.size() : e) - start);
      };
      auto shown = [&](const std::vector<size_t>& v) {
        std::string o = "(";
        for (size_t i = 0; i < v.size(); ++i) {
          if (i) o += ",";
          o += std::to_string(v[i]);
        }
        return o + ")";
      };
      auto oke = [&](const std::string& cmd, const std::string& why) {
        auto r = exec(cmd, s);
        check(firstError(r.blocks).is_null(),
              why + " [got: " + errText(firstError(r.blocks)) + "]");
      };

      oke("estout w5a w5b using \"w5x1.tex\", replace style(tex) cells(b se)\n",
          "W5 (x.25): `estout ... style(tex)` runs");
      const std::string x1 = slurp(at("w5x1.tex"));
      check(!has(x1, "\\begin{tabular}") && !has(x1, "\\hline"),
            "W5 (x.25): ...and writes a FRAGMENT -- no tabular, no rules (w1b_estout_tex.log r1). "
            "This writer used to hand its table to renderTex, the esttab emitter, so all 148 tex "
            "lines in the corpus got `\\begin{tabular}{l*{2}{c}}` and `\\hline\\hline`. Got:\n" + x1);
      check(widths(lineN("w5x1.tex", 2)) == std::vector<size_t>({12, 12, 12}),
            "W5 (x.25): ...with a 12-wide stub and 12-wide cells (r1). Got " +
                shown(widths(lineN("w5x1.tex", 2))) + " in `" + lineN("w5x1.tex", 2) + "`");
      check(lineN("w5x1.tex", 0) == "            &         w5a&         w5b\\\\",
            "W5 (x.25): ...and the model-name row is right-aligned in those fields with `&` "
            "UNSPACED -- esttab's renderer writes ` & ` (r1). Got `" + lineN("w5x1.tex", 0) + "`");
      check(lineN("w5x1.tex", 1) == "            &        b/se&        b/se\\\\",
            "W5 (x.25): ...and the cell-name row sits under it. Got `" + lineN("w5x1.tex", 1) + "`");

      oke("estout w5a w5b using \"w5x2.tex\", replace style(tex) cells(b(star) se)\n",
          "W5 (x.25): a starred spec runs");
      check(widths(lineN("w5x2.tex", 2)) == std::vector<size_t>({12, 15, 15}),
            "W5 (x.25): ...and reserves a THREE-character star field after each 12-wide cell (r4). "
            "Got " + shown(widths(lineN("w5x2.tex", 2))));
      const std::string x2 = slurp(at("w5x2.tex"));
      check(has(x2, "** ") || has(x2, "*  ") || has(x2, "***"),
            "W5 (x.25): ...and the star is LEFT-aligned in it, so a two-star mark keeps a trailing "
            "space where a three-star one has none (r4). Padding value+star together to 15 would "
            "get the two-star case wrong and the three-star case right. Got:\n" + x2);

      oke("estout w5a w5b using \"w5x3.tex\", replace style(tex) cells(b se) numbers\n",
          "W5 (x.25): `numbers` runs");
      check(lineN("w5x3.tex", 0) == "            &         (1)&         (2)\\\\",
            "W5 (x.25): ...and puts the (1)/(2) row ABOVE the model names, which is the opposite "
            "of esttab's order (r a). Got `" + lineN("w5x3.tex", 0) + "`");

      oke("estout w5a w5b using \"w5x4.tex\", replace style(tex) cells(b) varwidth(25)\n",
          "W5 (x.25): `varwidth()` runs");
      check(widths(lineN("w5x4.tex", 2))[0] == 25,
            "W5 (x.25): ...and sets the stub width (w1b_estout_tex2.log v1)");
      oke("estout w5a w5b using \"w5x5.tex\", replace style(tex) cells(b) modelwidth(20)\n",
          "W5 (x.25): `modelwidth()` runs");
      check(widths(lineN("w5x5.tex", 2))[1] == 20,
            "W5 (x.25): ...and `modelwidth()` sets the cell width (v2)");

      // The stub default is the LABEL FLAG, not the label's length: a two-character
      // label still gets 20 (w1b_estout_tex2 w3 arm) and `nolabel` wins over
      // `label` when both are given (w1b_estout_opts.log q3).
      oke("estout w5a w5b using \"w5x6.tex\", replace style(tex) cells(b) label\n",
          "W5 (x.25): `label` runs");
      check(widths(lineN("w5x6.tex", 2))[0] == 20,
            "W5 (x.25): ...and moves the stub default from 12 to 20. Got " +
                shown(widths(lineN("w5x6.tex", 2))));
      oke("estout w5a w5b using \"w5x7.tex\", replace style(tex) cells(b) label nolabel\n",
          "W5 (x.25): `label nolabel` runs");
      check(widths(lineN("w5x7.tex", 2))[0] == 12,
            "W5 (x.25): ...and `nolabel` WINS, taking the width back with it (q3). That pair is "
            "the only way to see nolabel at all, since it is estout's default. Got " +
                shown(widths(lineN("w5x7.tex", 2))));

      // The fourth site of split-before-dequote in this tree.
      oke("estout w5a w5b using \"w5x8.tex\", replace style(tex) cells(b se) "
          "mlabels(\"Model One\" \"Two\")\n",
          "W5 (x.25): `mlabels()` with quoted multi-word labels runs");
      check(lineN("w5x8.tex", 0) == "            &   Model One&         Two\\\\",
            "W5 (x.25): ...and both labels survive whole. `buildHeads` dequoted the option value "
            "BEFORE splitting it, so `\"Model One\" \"Two\"` came out as `Model` and `One\" \"Two` "
            "(r8) -- the same rule `parseLabelPairs` states and the fourth site in this tree to "
            "have broken it. Got `" + lineN("w5x8.tex", 0) + "`");
    }

    // -- (x.24) W1a-4: prehead()/posthead()/prefoot()/postfoot() REPLACE their
    // block. Oracle: w1b_headfoot.log (p0..pb). All four were already accepted at
    // rc 0 and two of them were wrong in the TEX writer: `prehead()` replaced
    // only the top rule and left `{`, `\def\sym` and `\begin{tabular}` standing,
    // and `postfoot()` left `\end{tabular}` and the closing brace behind. The
    // corpus's own spelling IS a tabular opener -- 128 uses of
    // `prehead(\begin{tabular}{l*{5}{c}} \hline \hline)` over 12 papers -- so
    // every one of those files came out with two \begin{tabular} lines.
    {
      auto okh = [&](const std::string& cmd, const std::string& why) {
        auto r = exec(cmd, s);
        check(firstError(r.blocks).is_null(),
              why + " [got: " + errText(firstError(r.blocks)) + "]");
      };
      auto firstLine = [&](const std::string& f) {
        const std::string t = slurp(at(f));
        const size_t e = t.find('\n');
        return e == std::string::npos ? t : t.substr(0, e);
      };
      okh("esttab w5a w5b using \"w5h0.tex\", replace tex\n",
          "W5 (x.24): the tex control runs");
      const std::string h0 = slurp(at("w5h0.tex"));
      check(firstLine("w5h0.tex") == "{" && has(h0, "\\def\\sym#1{") &&
                has(h0, "\\begin{tabular}{l*{2}{c}}") && has(h0, "\\end{tabular}"),
            "W5 (x.24): ...and carries the default opening block and close (p0). Got:\n" + h0);

      okh("esttab w5a w5b using \"w5h1.tex\", replace tex prehead(\"PREHEAD\")\n",
          "W5 (x.24): `prehead()` runs");
      const std::string h1 = slurp(at("w5h1.tex"));
      check(firstLine("w5h1.tex") == "PREHEAD",
            "W5 (x.24): ...and is the FIRST line of the file (p1) -- it replaces the whole "
            "opening block, brace and \\def\\sym and tabular opener included. Got:\n" + h1);
      check(!has(h1, "\\def\\sym#1{") && !has(h1, "\\begin{tabular}"),
            "W5 (x.24): ...so NONE of the default opener survives. This is the arm that matters: "
            "the corpus passes a tabular opener here, and keeping the default one too is a second "
            "\\begin{tabular} in the same file. Got:\n" + h1);
      check(has(h1, "\\end{tabular}"),
            "W5 (x.24): ...while the CLOSE is untouched -- prehead() is not postfoot() (p1)");

      okh("esttab w5a w5b using \"w5h2.tex\", replace tex postfoot(\"POSTFOOT\")\n",
          "W5 (x.24): `postfoot()` runs");
      const std::string h2 = slurp(at("w5h2.tex"));
      check(has(h2, "POSTFOOT") && !has(h2, "\\end{tabular}") && !has(h2, "footnotesize"),
            "W5 (x.24): ...and replaces the whole closing block -- bottom rule, legend, "
            "\\end{tabular} and the brace. p4's file ENDS at POSTFOOT. This build wrote "
            "\\end{tabular} underneath it. Got:\n" + h2);
      check(firstLine("w5h2.tex") == "{",
            "W5 (x.24): ...while the OPENER is untouched (p4)");

      okh("esttab w5a w5b using \"w5h3.tex\", replace tex posthead(\"POSTHEAD\")\n",
          "W5 (x.24): `posthead()` runs");
      const std::string h3 = slurp(at("w5h3.tex"));
      check(has(h3, "POSTHEAD") && firstLine("w5h3.tex") == "{" && has(h3, "\\end{tabular}"),
            "W5 (x.24): ...and replaces only the rule between the header rows and the body, "
            "leaving both ends alone (p2). Got:\n" + h3);
      okh("esttab w5a w5b using \"w5h4.tex\", replace tex prefoot(\"PREFOOT\")\n",
          "W5 (x.24): `prefoot()` runs");
      check(has(slurp(at("w5h4.tex")), "PREFOOT") && has(slurp(at("w5h4.tex")), "\\end{tabular}"),
            "W5 (x.24): ...and replaces the rule before the stats block only (p3)");

      okh("esttab w5a w5b using \"w5h5.tex\", replace tex prehead(\"\")\n",
          "W5 (x.24): an EMPTY prehead() runs");
      check(firstLine("w5h5.tex").empty() && !has(slurp(at("w5h5.tex")), "\\begin{tabular}"),
            "W5 (x.24): ...and is a BLANK line, not nothing -- the block is still replaced (p6). "
            "Got first line `" + firstLine("w5h5.tex") + "`");

      // The fixed writer was already right; the pair is what says so.
      okh("esttab w5a w5b using \"w5h6.txt\", replace prehead(\"PREHEAD\")\n",
          "W5 (x.24): prehead() in the FIXED writer runs");
      check(firstLine("w5h6.txt") == "PREHEAD",
            "W5 (x.24): ...and replaces the top rule there too (p9)");
      okh("esttab w5a w5b using \"w5h7.txt\", replace postfoot(\"POSTFOOT\")\n",
          "W5 (x.24): postfoot() in the FIXED writer runs");
      const std::string h7 = slurp(at("w5h7.txt"));
      check(has(h7, "POSTFOOT") && !has(h7, "parentheses"),
            "W5 (x.24): ...and takes the legend with it (pa). The fixed writer already did this "
            "and the tex writer did not, which is the shape a single-style selftest misses");
    }

    // -- (x.23) W1a-5h: frmttable writes its OWN LaTeX, not estout's. Oracle:
    // w1b_frmttable_{base,names,cells,cells2}.log. Every expected string below
    // is copied from an oracle arm, and the inputs are literal matrices, so
    // these are the ORACLE's bytes and not a capture of what this build prints.
    // Before this the writer handed its table to `renderTex`, the estout emitter,
    // and produced a stub column and a header row the ado does not emit at all.
    {
      piet::SessionState sf(workdir);
      sf.eval.cwd = workdir;
      sf.cwd = workdir;
      auto okf = [&](const std::string& cmd, const std::string& why) {
        auto r = exec(cmd, sf);
        check(firstError(r.blocks).is_null(),
              why + " [got: " + errText(firstError(r.blocks)) + "]");
      };
      (void)exec("matrix N = (1,2,3\\4,5,6)\n", sf);
      (void)exec("matrix A = (1,2,3\\4,5,6)\nmatrix rownames A = alpha beta\n"
                 "matrix colnames A = one two three\n",
                 sf);

      // The plainest call there is. An unnamed Stata matrix still CARRIES names
      // (`r1 r2` / `c1 c2 c3`), and the oracle emits neither -- no stub column,
      // no header row, three `c` columns.
      okf("frmttable using \"w5f1.tex\", statmat(N) sdec(2) tex replace fragment nocenter\n",
          "W5 (x.23): `frmttable ... tex` runs");
      const std::string f1 = slurp(at("w5f1.tex"));
      check(f1 ==
                "\\begin{tabular}{ccc}\n"
                "\\hline \\noalign{\\smallskip}1.00 & 2.00 & 3.00\\\\\n"
                "4.00 & 5.00 & 6.00\\\\\n"
                "\\noalign{\\smallskip}\\hline\\end{tabular}\\\\\n",
            "W5 (x.23): ...byte for byte as the ado writes it (w1b_frmttable_base.log h1 with "
            "h7's nocenter). The default-SPELLED matrix names count as ABSENT -- which is why "
            "there is no `l` in the column spec and no header row. Got:\n" + f1);

      // The same command on a matrix whose names were actually set.
      okf("frmttable using \"w5f2.tex\", statmat(A) sdec(2) tex replace fragment nocenter\n",
          "W5 (x.23): the same call on a NAMED matrix runs");
      const std::string f2 = slurp(at("w5f2.tex"));
      check(f2 ==
                "\\begin{tabular}{lccc}\n"
                "\\hline \\noalign{\\smallskip} & one & two & three\\\\\n"
                "\\noalign{\\smallskip}\\hline \\noalign{\\smallskip}alpha & 1.00 & 2.00 & "
                "3.00\\\\\n"
                "beta & 4.00 & 5.00 & 6.00\\\\\n"
                "\\noalign{\\smallskip}\\hline\\end{tabular}\\\\\n",
            "W5 (x.23): ...and NOW there is a stub and a header, and the first DATA row carries "
            "the `\\noalign{\\smallskip}\\hline \\noalign{\\smallskip}` separator (base h2). The "
            "pair f1/f2 is what says the rule is the names' SPELLING and not their presence. "
            "Got:\n" + f2);

      // rtitles/ctitles: rows separated by a top-level backslash, cells by a
      // comma, each dequoted AFTER the split.
      okf("frmttable using \"w5f3.tex\", statmat(N) sdec(2) tex replace fragment nocenter "
          "rtitles(\"r1\" \\ \"r2\") ctitles(\"\", \"c1\", \"c2\", \"c3\")\n",
          "W5 (x.23): rtitles()/ctitles() run");
      const std::string f3 = slurp(at("w5f3.tex"));
      check(f3 ==
                "\\begin{tabular}{lccc}\n"
                "\\hline \\noalign{\\smallskip} & c1 & c2 & c3\\\\\n"
                "\\noalign{\\smallskip}\\hline \\noalign{\\smallskip}r1 & 1.00 & 2.00 & 3.00\\\\\n"
                "r2 & 4.00 & 5.00 & 6.00\\\\\n"
                "\\noalign{\\smallskip}\\hline\\end{tabular}\\\\\n",
            "W5 (x.23): ...and the backslash-separated list really is split (base h6). The first "
            "cut dequoted the option value BEFORE splitting it, which left the inner quotes "
            "unbalanced and collapsed every row into one cell reading `r1\" \\ \"r2` -- nine of "
            "the nineteen oracle arms at once. Got:\n" + f3);

      // A cell holding LaTeX: its backslashes must not be separators.
      okf("frmttable using \"w5f4.tex\", statmat(N) sdec(2) tex replace fragment nocenter "
          "rtitles(\"\\makecell[l]{\\it{Panel A}}\" \\ \"Any pollutant\")\n",
          "W5 (x.23): an rtitle carrying LaTeX runs");
      check(has(slurp(at("w5f4.tex")), "\\makecell[l]{\\it{Panel A}} & 1.00") &&
                has(slurp(at("w5f4.tex")), "Any pollutant & 4.00"),
            "W5 (x.23): ...and survives verbatim (names i7). This is paper 004's own spelling, "
            "and a splitter that treated every backslash as a row separator would cut it in "
            "three. Got:\n" + slurp(at("w5f4.tex")));

      // ctitles WIDER than the data sets the table width; the data rows pad.
      okf("frmttable using \"w5f5.tex\", statmat(N) sdec(2) tex replace fragment nocenter "
          "ctitles(\"\", \"c1\", \"c2\", \"c3\")\n",
          "W5 (x.23): ctitles() without rtitles() runs");
      const std::string f5 = slurp(at("w5f5.tex"));
      check(f5 ==
                "\\begin{tabular}{cccc}\n"
                "\\hline \\noalign{\\smallskip} & c1 & c2 & c3\\\\\n"
                "\\noalign{\\smallskip}\\hline \\noalign{\\smallskip}1.00 & 2.00 & 3.00 & \\\\\n"
                "4.00 & 5.00 & 6.00 & \\\\\n"
                "\\noalign{\\smallskip}\\hline\\end{tabular}\\\\\n",
            "W5 (x.23): ...and FOUR ctitles over a three-column matrix with no stub make a "
            "four-column table whose data rows carry a trailing empty cell (base h5) -- the "
            "width is the wider of the two, not the data's. Got:\n" + f5);

      // rtitles LONGER than the matrix adds rows.
      okf("frmttable using \"w5f6.tex\", statmat(N) sdec(2) tex replace fragment nocenter "
          "rtitles(\"a\" \\ \"b\" \\ \"c\")\n",
          "W5 (x.23): more rtitles than rows runs");
      check(has(slurp(at("w5f6.tex")), "c &  &  & \\\\"),
            "W5 (x.23): ...and ADDS a row with an empty data area (names ia). Got:\n" +
                slurp(at("w5f6.tex")));

      // The numeric format: thousands separators by default, and sdec()'s last
      // entry repeating.
      (void)exec("matrix BIG = (1234.5,6165.257,0.001\\2.5,3.5,4.5)\n", sf);
      okf("frmttable using \"w5f7.tex\", statmat(BIG) sdec(2) tex replace fragment nocenter\n",
          "W5 (x.23): a table of large numbers runs");
      check(has(slurp(at("w5f7.tex")), "1,234.50 & 6,165.26 & 0.00"),
            "W5 (x.23): ...with THOUSANDS SEPARATORS and no sfmt() asked for -- frmttable's "
            "default numeric format is `fc` (cells2 k6), and this build was dropping the commas. "
            "Got:\n" + slurp(at("w5f7.tex")));
      (void)exec("matrix S = (1.234,2.345,3.456\\7.891,8.912,9.123)\n", sf);
      okf("frmttable using \"w5f8.tex\", statmat(S) sdec(0,1) tex replace fragment nocenter\n",
          "W5 (x.23): a short sdec() list runs");
      check(has(slurp(at("w5f8.tex")), "1 & 2.3 & 3.5\\\\"),
            "W5 (x.23): ...and its LAST entry repeats for the remaining columns -- `sdec(0,1)` "
            "over three columns is 0, 1, 1 (cells2 k2), not 0, 1, default. Got:\n" +
                slurp(at("w5f8.tex")));

      // The wrappers.
      okf("frmttable using \"w5f9.tex\", statmat(N) sdec(2) tex replace\n",
          "W5 (x.23): the NON-fragment form runs");
      const std::string f9 = slurp(at("w5f9.tex"));
      check(has(f9, "\\documentclass[]{article}\\pagestyle{empty}\\begin{document}") &&
                has(f9, "\\begin{center}") && has(f9, "\\end{document}"),
            "W5 (x.23): ...and without `fragment` the ado writes a WHOLE DOCUMENT, and without "
            "`nocenter` it centres (base h1 against h3/h7). This build's `fragment` used to drop "
            "`\\begin{tabular}` itself and emit rows only. Got:\n" + f9);

      // W2AK: `replay` writes the STORED table (the last statmat() build) with
      // the new output options (w2at wt_f01b; matches frmttable's behaviour, identified from its ado).
      (void)exec("frmttable, statmat(N) sdec(1)\n", sf);
      auto rrep = exec("frmttable using \"w5fa.tex\", replay tex fragment replace\n", sf);
      check(firstError(rrep.blocks).is_null() && has(slurp(at("w5fa.tex")), "\\begin{tabular}"),
            "W5 (x.23): `replay` writes the stored table (w2at wt_f01b). Got: " +
                errText(firstError(rrep.blocks)));
      auto rrtf = exec("frmttable using \"w5fb.doc\", statmat(N) replace\n", sf);
      check(!firstError(rrtf.blocks).is_null(),
            "W5 (x.23): ...and the no-`tex` form stays a COMMAND-level refusal, because "
            "frmttable's default output is RTF (base h8 writes `{\\rtf1\\ansi...}`) and writing "
            "LaTeX under a .doc extension is the silent-wrong-output shape");
    }

    // -- (x.22) W1a-5g-2: `transform()` -- 18 corpus uses over four papers.
    // Oracle: w1b_transform.log (r*/s*/u*/v*/w*/x*) and w1b_transform2.log
    // (y*/z*). The assertions are RATIOS against a control rather than absolute
    // numbers, because the option's whole content is "what happened to this
    // cell relative to the untransformed one" and the fixture's coefficients
    // are not the oracle's.
    {
      // Every arm pins b()/se() to 16.10f. esttab's DEFAULT renders four
      // significant digits (the oracle control shows `1946.1`), and these
      // assertions are ratios read back OUT of the rendered text -- so at the
      // default format `2 * round(b, 4sf)` and `round(2b, 4sf)` differ and the
      // arms would fail on the printer rather than on the transform. Pinning the
      // format is not weakening them: w1b_transform2.log z5 is the arm that says
      // a transformed number is formatted by the normal rules.
      // The b and se of one coefficient, read back out of the written table.
      auto trimSp = [](const std::string& v) {
        size_t a = v.find_first_not_of(" \t");
        if (a == std::string::npos) return std::string();
        size_t b = v.find_last_not_of(" \t");
        return v.substr(a, b - a + 1);
      };
      auto cellOf = [&](const std::string& f, const std::string& coef) {
        const std::string t = slurp(at(f));
        std::pair<double, double> out{std::nan(""), std::nan("")};
        size_t i = 0;
        bool onRow = false;
        while (i < t.size()) {
          size_t e = t.find('\n', i);
          if (e == std::string::npos) e = t.size();
          const std::string line = t.substr(i, e - i);
          if (!onRow && line.compare(0, coef.size(), coef) == 0 &&
              (line.size() == coef.size() || line[coef.size()] == ' ' ||
               line[coef.size()] == '\t')) {
            try {
              out.first = std::stod(trimSp(line.substr(coef.size())));
            } catch (const std::exception&) {
            }
            onRow = true;
          } else if (onRow) {
            std::string v = trimSp(line);
            if (!v.empty() && v.front() == '(') v = v.substr(1);
            if (!v.empty() && v.back() == ')') v.pop_back();
            try {
              out.second = std::stod(v);
            } catch (const std::exception&) {
            }
            break;
          }
          i = e + 1;
        }
        return out;
      };
      auto near = [](double a, double b) {
        if (std::isnan(a) || std::isnan(b)) return false;
        return std::fabs(a - b) <= 1e-6 * std::max(1.0, std::fabs(b));
      };
      auto okt = [&](const std::string& cmd, const std::string& why) {
        auto r = exec(cmd, s);
        check(firstError(r.blocks).is_null(),
              why + " [got: " + errText(firstError(r.blocks)) + "]");
      };
      okt("esttab w5a using \"w5t0.txt\", replace b(%16.10f) se(%16.10f) nostar\n",
          "W5 (x.22): the control runs");
      const auto c0 = cellOf("w5t0.txt", "x1");
      const auto c0b = cellOf("w5t0.txt", "x2");
      check(!std::isnan(c0.first) && !std::isnan(c0.second),
            "W5 (x.22): ...and the control's x1 row reads back as a b over an se");

      // ONE token: the coefficient moves and the se does NOT. This is the arm
      // that says `df` is a separate expression rather than a format -- an
      // implementation that applied `f` to both would double the se here.
      okt("esttab w5a using \"w5t1.txt\", replace b(%16.10f) se(%16.10f) nostar transform(@*2)\n",
          "W5 (x.22): `transform(@*2)` runs -- it was r(198)");
      const auto c1 = cellOf("w5t1.txt", "x1");
      check(near(c1.first, c0.first * 2),
            "W5 (x.22): ...and the coefficient doubles (w1b_transform.log r1)");
      check(near(c1.second, c0.second),
            "W5 (x.22): ...while the se is UNTOUCHED, because a one-token list has no derivative "
            "(r1: 86.16 before and after). An implementation that reused `f` for the se would "
            "double it here and no other arm would notice");

      // TWO tokens: the second multiplies the se by abs().
      okt("esttab w5a using \"w5t2.txt\", replace b(%16.10f) se(%16.10f) nostar transform(@*2 2)\n",
          "W5 (x.22): `transform(@*2 2)` runs");
      const auto c2 = cellOf("w5t2.txt", "x1");
      check(near(c2.first, c0.first * 2) && near(c2.second, c0.second * 2),
            "W5 (x.22): ...and NOW both move -- the se by abs(df), evaluated at the coefficient "
            "(r2)");

      // THREE tokens: the first is a coefficient pattern.
      okt("esttab w5a using \"w5t3.txt\", replace b(%16.10f) se(%16.10f) nostar transform(x1 @*2 2)\n",
          "W5 (x.22): a three-token list runs");
      check(near(cellOf("w5t3.txt", "x1").first, c0.first * 2) &&
                near(cellOf("w5t3.txt", "x2").first, c0b.first),
            "W5 (x.22): ...and the pattern selects: x1 doubles, x2 does not (r3). With two tokens "
            "the SAME spelling would transform everything, so the arity is the grammar");

      // A TRAILING pair with no pattern catches everything the earlier groups
      // missed -- and its own missing df still leaves those ses alone.
      okt("esttab w5a using \"w5t4.txt\", replace b(%16.10f) se(%16.10f) nostar transform(x1 @*2 2 @*10)\n",
          "W5 (x.22): a four-token list runs");
      const auto t4a = cellOf("w5t4.txt", "x1");
      const auto t4b = cellOf("w5t4.txt", "x2");
      check(near(t4a.first, c0.first * 2) && near(t4a.second, c0.second * 2),
            "W5 (x.22): ...the first group still applies to its own pattern (r5)");
      check(near(t4b.first, c0b.first * 10) && near(t4b.second, c0b.second),
            "W5 (x.22): ...and the trailing PAIR becomes (f, df) with no pattern, so x2 takes "
            "@*10 with no derivative and keeps its se (r5). This is the one place the ado's list "
            "reader is not a plain triple split");

      okt("esttab w5a using \"w5t5.txt\", replace b(%16.10f) se(%16.10f) nostar transform(*1* @*2 2)\n",
          "W5 (x.22): a wildcard pattern runs");
      check(near(cellOf("w5t5.txt", "x1").first, c0.first * 2) &&
                near(cellOf("w5t5.txt", "x2").first, c0b.first),
            "W5 (x.22): ...and matches by glob (r8) -- which is how all four of paper 015's lines "
            "spell it, `transform(*romer* `f_scale'*@ `f_scale')`");
      okt("esttab w5a using \"w5t6.txt\", replace b(%16.10f) se(%16.10f) nostar transform(*:*1* @*2 2)\n",
          "W5 (x.22): an `eq:name` pattern runs");
      check(near(cellOf("w5t6.txt", "x1").first, c0.first * 2),
            "W5 (x.22): ...and reaches a row this engine stores with no equation at all (r9)");
      okt("esttab w5a using \"w5t7.txt\", replace b(%16.10f) se(%16.10f) nostar transform(nosuch @*2 2)\n",
          "W5 (x.22): a pattern that matches nothing runs");
      check(near(cellOf("w5t7.txt", "x1").first, c0.first),
            "W5 (x.22): ...and is the IDENTITY, not an error (r10). keep() answers r(111) for the "
            "same shape and transform() does not, so the two cannot share a rule");

      // The parenthesised row: t and p are in neither of the ado's branches.
      okt("esttab w5a using \"w5t8.txt\", replace nostar transform(@*2 2)\n",
          "W5 (x.22): the default table (t in parentheses) runs under transform()");
      auto rctl = exec("esttab w5a using \"w5t9.txt\", replace nostar\n", s);
      check(firstError(rctl.blocks).is_null(), "W5 (x.22): ...and so does its control");
      check(near(cellOf("w5t8.txt", "x1").second, cellOf("w5t9.txt", "x1").second),
            "W5 (x.22): ...and the t is UNCHANGED (s1). For a linear rescaling that is also the "
            "right answer -- b and se moved by the same factor -- which is why the arm has to be "
            "the t and not the b");

      // pattern() selects MODELS.
      okt("esttab w5a w5b using \"w5ta.txt\", replace b(%16.10f) se(%16.10f) nostar transform(@*2 2, pattern(1 0))\n",
          "W5 (x.22): `transform(, pattern())` runs");
      okt("esttab w5a w5b using \"w5tb.txt\", replace b(%16.10f) se(%16.10f) nostar transform(@*2 2, pattern(1))\n",
          "W5 (x.22): ...a pattern SHORTER than the model count runs");
      okt("esttab w5a w5b using \"w5tc.txt\", replace b(%16.10f) se(%16.10f) nostar transform(@*2 2, pattern())\n",
          "W5 (x.22): ...and an EMPTY pattern() runs");
      check(has(slurp(at("w5ta.txt")), "\n") && slurp(at("w5ta.txt")) == slurp(at("w5tb.txt")),
            "W5 (x.22): pattern(1) over two models is pattern(1 0) -- a word missing for a model "
            "means do not transform it (z1 against v1), not `carry the last one forward`");
      check(slurp(at("w5tc.txt")) != slurp(at("w5ta.txt")),
            "W5 (x.22): ...while an EMPTY pattern() transforms EVERY model (z4), same as leaving "
            "it out. The two empties do not mean opposite things");
      auto rbad =
          exec("esttab w5a w5b using \"w5td.txt\", replace b(%16.10f) se(%16.10f) nostar transform(@*2 2, pattern(2 0))\n",
               s);
      check(!firstError(rbad.blocks).is_null() &&
                has(errText(firstError(rbad.blocks)), "invalid pattern in transform"),
            "W5 (x.22): a pattern word that is neither 0 nor 1 is refused with estout's own "
            "sentence (tr_pat_two, r(198)). Got: " + errText(firstError(rbad.blocks)));

      // Paper 083's line, verbatim in shape: no comma, so pattern() lands in the
      // flat list and the whole thing is a measured NO-OP in Stata.
      okt("esttab w5a using \"w5te.txt\", replace b(%16.10f) se(%16.10f) nostar transform(@/5 1/5 pattern(1 1 0 0) "
          "@*100 100 pattern(0 0 1 1))\n",
          "W5 (x.22): paper 083's spelling runs");
      check(slurp(at("w5te.txt")) == slurp(at("w5t0.txt")),
            "W5 (x.22): ...and does NOTHING, byte for byte against the control (tr_083_verb, rc 0 "
            "in Stata too). `pattern()` is only a suboption after a comma, so without one it "
            "becomes a coefficient pattern that matches no row. Following the ado's list reader "
            "exactly is what buys this parity -- a lenient parser would have `fixed` it into a "
            "table Stata does not produce");

      // `_b[]` inside the expression resolves against EACH model.
      okt("esttab w5a w5b using \"w5tf.txt\", replace b(%16.10f) se(%16.10f) nostar transform(@/(-_b[x1]))\n",
          "W5 (x.22): paper 104's spelling -- `_b[]` inside the expression -- runs");
      check(near(cellOf("w5tf.txt", "x1").first, -1.0),
            "W5 (x.22): ...and a coefficient divided by its own negation is exactly -1 (y1/w1), "
            "which is the arm that says the expression was evaluated with THIS model current "
            "rather than with whatever estimation the session happened to hold");

      // estout, on the same specs. The point is agreement, not the numbers.
      okt("estout w5a using \"w5tg.txt\", replace cells(b(fmt(%16.10f)) se(fmt(%16.10f))) transform(@*2 2)\n",
          "W5 (x.22): estout takes transform() too -- 12 of the 18 corpus uses are on it");
      okt("estout w5a using \"w5th.txt\", replace cells(b(fmt(%16.10f)) se(fmt(%16.10f))) transform(x1 @*2 2)\n",
          "W5 (x.22): ...including the per-coefficient form");
      check(near(cellOf("w5tg.txt", "x1").first, c0.first * 2) &&
                near(cellOf("w5th.txt", "x2").first, c0b.first),
            "W5 (x.22): ...and it agrees with esttab cell for cell (y3/y4 against r2/r3). The two "
            "writers build their rows in different translation units and share ONE transform, "
            "which is the BUG-496 lesson applied before the fact rather than after");
    }

    // -- (x.21) BUG-496: keep()/drop()/order() take PATTERNS, and the two
    // commands have to agree about them. Oracle: w1b_keepglob.log (k0..kb).
    // The pair that matters is esttab-against-estout: the first fix of this
    // reached only estout's `coefNames` and left esttab's own copy exact, so
    // `keep(*2*)` selected a row on one command and emptied the table on the
    // other IN THE SAME BUILD. Every arm below is run on both.
    {
      auto bodyRows = [&](const std::string& f) {
        // The coefficient names present in the body, in order, as one string.
        const std::string t = slurp(at(f));
        std::string out;
        size_t i = 0;
        while (i < t.size()) {
          size_t e = t.find('\n', i);
          if (e == std::string::npos) e = t.size();
          const std::string line = t.substr(i, e - i);
          for (const char* nm : {"x1", "x2", "x3", "_cons"}) {
            const std::string n(nm);
            if (line.compare(0, n.size(), n) == 0) {
              out += n;
              out += " ";
              break;
            }
          }
          i = e + 1;
        }
        return out;
      };
      auto okg = [&](const std::string& cmd, const std::string& why) {
        auto r = exec(cmd, s);
        check(firstError(r.blocks).is_null(),
              why + " [got: " + errText(firstError(r.blocks)) + "]");
      };
      okg("esttab w5a w5b using \"w5g0.txt\", replace b se nostar\n",
          "W5 (x.21): the control runs");
      check(bodyRows("w5g0.txt") == "x1 x2 _cons ",
            "W5 (x.21): ...and the unfiltered body is the three coefficients in engine order. "
            "Got `" + bodyRows("w5g0.txt") + "`");

      okg("esttab w5a w5b using \"w5g1.txt\", replace b se nostar keep(*2*)\n",
          "W5 (x.21): `keep(*2*)` runs");
      okg("estout w5a w5b using \"w5g2.txt\", replace cells(b se) keep(*2*)\n",
          "W5 (x.21): ...and so does the same pattern on estout");
      check(bodyRows("w5g1.txt") == "x2 ",
            "W5 (x.21): `keep()` matches PATTERNS -- `*2*` keeps x2 (w1b_keepglob.log k2). Exact "
            "matching answered this with an EMPTY body at rc 0, which is the shape all four of "
            "paper 015's transform lines would have hit. Got `" + bodyRows("w5g1.txt") + "`");
      check(has(slurp(at("w5g2.txt")), "x2") && !has(slurp(at("w5g2.txt")), "x1"),
            "W5 (x.21): ...and estout selects the SAME row. The two commands used to have two "
            "answers about `*`. Got:\n" + slurp(at("w5g2.txt")));

      okg("esttab w5a w5b using \"w5g3.txt\", replace b se nostar keep(x?)\n",
          "W5 (x.21): `keep(x?)` runs -- `?` is one character, so this is Stata's match() and not "
          "a prefix rule (k a)");
      check(bodyRows("w5g3.txt") == "x1 x2 ",
            "W5 (x.21): ...and it keeps both two-character names and not `_cons`. Got `" +
                bodyRows("w5g3.txt") + "`");

      okg("esttab w5a w5b using \"w5g4.txt\", replace b se nostar keep(*:*2*)\n",
          "W5 (x.21): an `eq:name` pattern runs");
      check(bodyRows("w5g4.txt") == "x2 ",
            "W5 (x.21): ...and it reaches a row this engine stores with NO equation at all -- "
            "which is what makes the corpus's `keep(3:0.MI*#c.romer*)` able to match (k7). Got `" +
                bodyRows("w5g4.txt") + "`");

      okg("esttab w5a w5b using \"w5g5.txt\", replace b se nostar drop(*2* _cons)\n",
          "W5 (x.21): `drop()` takes patterns too");
      check(bodyRows("w5g5.txt") == "x1 ",
            "W5 (x.21): ...and a glob and an exact name in ONE drop() both bite (k8). Before this "
            "the exact `_cons` was removed and the glob silently was not, which is the worst of "
            "the two behaviours because the table still looks filtered. Got `" +
                bodyRows("w5g5.txt") + "`");

      okg("esttab w5a w5b using \"w5g6.txt\", replace b se nostar order(x2* x1)\n",
          "W5 (x.21): `order()` takes patterns");
      check(bodyRows("w5g6.txt") == "x2 x1 _cons ",
            "W5 (x.21): ...and promotes the matched rows in the order the option lists them, the "
            "rest keeping theirs (k9). Got `" + bodyRows("w5g6.txt") + "`");

      auto rn = exec("esttab w5a w5b using \"w5g7.txt\", replace b se nostar keep(zz*)\n", s);
      check(!firstError(rn.blocks).is_null() &&
                has(errText(firstError(rn.blocks)), "coefficient zz* not found"),
            "W5 (x.21): a keep() pattern that matches NOTHING is r(111) with Stata's own sentence "
            "(kg_glob_none), not a table with no rows. The empty table is the reading error: it "
            "says the coefficients were estimated and excluded. Got: " +
                errText(firstError(rn.blocks)));
      auto re = exec("estout w5a w5b using \"w5g8.txt\", replace cells(b se) keep(zz*)\n", s);
      check(!firstError(re.blocks).is_null() &&
                has(errText(firstError(re.blocks)), "coefficient zz* not found"),
            "W5 (x.21): ...on estout as well, because it is one filter now. Got: " +
                errText(firstError(re.blocks)));
    }

    // -- (x.20) W1a-5f: outreg2 `adec(#)` (106 corpus uses, three papers) and
    // the ado's own separator bug the User ruled we follow bug-for-bug.
    // Oracle: w1b_adec_rule{,2,3,4,5}.log. Every value asserted here is a
    // LITERAL in the addstat() call, so none of it depends on the fixture --
    // which is the whole reason the arms use literals rather than e() scalars.
    {
      piet::SessionState sa(workdir);
      sa.eval.cwd = workdir;
      sa.cwd = workdir;
      (void)exec(kMake30 + "regress y x1 x2\n", sa);
      auto run = [&](const std::string& cmd) { return exec(cmd, sa); };
      auto okc = [&](const std::string& cmd, const std::string& why) {
        auto r = run(cmd);
        check(firstError(r.blocks).is_null(),
              why + " [got: " + errText(firstError(r.blocks)) + "]");
      };
      auto refused = [&](const std::string& cmd, const std::string& needle,
                         const std::string& why) {
        auto r = run(cmd);
        const auto e = firstError(r.blocks);
        check(!e.is_null() && has(errText(e), needle),
              why + " [got: " + (e.is_null() ? std::string("NO ERROR") : errText(e)) + "]");
      };

      // The discriminator for adec() itself. `100` renders `100.0` under
      // adec(1) and `100` under the adaptive default (an integer takes no
      // decimals) -- and dec() can produce NEITHER, because it governs the
      // coefficients. So this pair is reachable only through adec().
      okc("outreg2 using \"w5ad1\", replace text addstat(M, 100) adec(1)\n",
          "W5 (x.20): `adec(#)` runs -- it was an unknown option on all 106 corpus uses");
      okc("outreg2 using \"w5ad2\", replace text addstat(M, 100)\n",
          "W5 (x.20): ...and the same line without it runs too");
      const std::string ad1 = slurp(at("w5ad1.txt"));
      const std::string ad2 = slurp(at("w5ad2.txt"));
      check(has(ad1, "\nM\t100.0\n"),
            "W5 (x.20): adec(1) renders the added statistic at ONE decimal -- `100.0`, which is "
            "w1b_adec_rule.log b6. Got:\n" + ad1);
      check(has(ad2, "\nM\t100\n") && !has(ad2, "100.0"),
            "W5 (x.20): ...while with no adec() the ADAPTIVE format takes an integer to no "
            "decimals at all. If both files said the same thing the option would be measuring "
            "nothing. Got:\n" + ad2);

      // BUG-494, and dec(4) is the only arm that separates the two formats: at
      // the default they agree, because %9.3f and the adaptive rule both give a
      // value between 1 and 10 three decimals.
      okc("outreg2 using \"w5ad3\", replace text addstat(M, 1.5) dec(4)\n",
          "W5 (x.20): `addstat()` under dec(4) runs");
      const std::string ad3 = slurp(at("w5ad3.txt"));
      check(has(ad3, "\nM\t1.500\n") && !has(ad3, "1.5000"),
            "W5 (x.20): ...and dec() does NOT reach the added statistic (BUG-494): the ado leaves "
            "it to the adaptive format, so it is `1.500` and not `1.5000` "
            "(w1b_adec_rule.log c2). Got:\n" + ad3);
      const size_t r2at = ad3.find("R-squared\t");
      const std::string r2cell =
          r2at == std::string::npos ? std::string() : ad3.substr(r2at + 10, 12);
      const size_t r2dot = r2cell.find('.');
      size_t r2dec = 0;
      while (r2dot != std::string::npos && r2dot + 1 + r2dec < r2cell.size() &&
             std::isdigit(static_cast<unsigned char>(r2cell[r2dot + 1 + r2dec]))) {
        ++r2dec;
      }
      check(r2dec == 4,
            "W5 (x.20): ...while dec(4) DID reach R-squared, which is what makes the line above a "
            "statement about the statistic rather than about dec() being ignored. Got " +
                std::to_string(r2dec) + " decimals in `" + r2cell + "`");

      // BUG-493. The refusal is on the FORMATTED string: 999.96 at one decimal
      // IS `1,000.0`, and 999.4 at zero is not. A |value| >= 1000 test passes
      // the second and fails the first.
      refused("outreg2 using \"w5ad4\", replace text addstat(M, 999.96) adec(1)\n", "1,000.0",
              "W5 (x.20): `addstat(M, 999.96) adec(1)` is REFUSED -- outreg2 formats it `1,000.0` "
              "and re-reads its own thousands separator as a field separator (r(198), "
              "w1b_adec_rule.log a1). The refusal is parity, not a gap");
      okc("outreg2 using \"w5ad5\", replace text addstat(M, 999.4) adec(0)\n",
          "W5 (x.20): ...while 999.4 at adec(0) is `999` and runs (a2) -- the rule is the STRING, "
          "not the value");

      // The width flip, which is the other end no `>= 1000` rule can reach.
      refused("outreg2 using \"w5ad6\", replace text addstat(M, 6165.257) adec(6)\n", "6,165.257000",
              "W5 (x.20): 6165.257 at adec(6) is `6,165.257000` -- 12 characters, the separator "
              "fits, refused (w1b_adec_rule5.log v2)");
      okc("outreg2 using \"w5ad7\", replace text addstat(M, 6165.257) adec(7)\n",
          "W5 (x.20): ...and at adec(7) the separated spelling is 13 characters, so Stata drops "
          "the separators and the SAME value runs (w1b_adec_rule3.log t1)");
      check(has(slurp(at("w5ad7.txt")), "\nM\t6165.2570000\n"),
            "W5 (x.20): ...rendering 6165.2570000, separator-free. Got:\n" +
                slurp(at("w5ad7.txt")));
      okc("outreg2 using \"w5ad8\", replace text addstat(M, 9999999) adec(3)\n",
          "W5 (x.20): and 9999999 at adec(3) runs for the same reason -- four orders of magnitude "
          "past `1000` and perfectly legal (w1b_adec_rule5.log v3)");
      check(has(slurp(at("w5ad8.txt")), "\nM\t9999999.000\n"),
            "W5 (x.20): ...as `9999999.000`. Got:\n" + slurp(at("w5ad8.txt")));

      // Which rc the ado dies with is positional, and both positions are
      // measured. A TRAILING pair loses its value; an earlier one pushes the
      // next pair's NAME into a value slot, where outreg2 reads it as a
      // variable -- so the message is that variable's name, not `invalid
      // syntax`.
      refused("outreg2 using \"w5ad9\", replace text addstat(A, 6165.257, B, 2.25) adec(1)\n",
              "B not found",
              "W5 (x.20): a big value in a NON-final pair shifts the next pair's name into a "
              "value slot -- outreg2 answers `B not found`, r(111), not r(198) "
              "(w1b_adec_rule.log d3)");
      refused("outreg2 using \"w5ada\", replace text addstat(A, 1.5, B, 6165.257) adec(1)\n",
              "6,165.3",
              "W5 (x.20): ...while the same value in the FINAL pair leaves that pair without a "
              "value and is r(198) (d4). One bug, two rcs, and the position is what picks");
      okc("outreg2 using \"w5adb\", replace text addstat(A, 1.5, B, 2.25) adec(1)\n",
          "W5 (x.20): ...and a multi-pair addstat() with small values runs -- the corpus's most "
          "common shape is two and three pairs, so `one pair only` would have been the wrong "
          "lesson to take from those rcs");
      check(has(slurp(at("w5adb.txt")), "\nA\t1.5\n") &&
                has(slurp(at("w5adb.txt")), "\nB\t2.2\n"),
            "W5 (x.20): ...with the ONE adec applying to every pair (d1). Got:\n" +
                slurp(at("w5adb.txt")));

      // The place this build deliberately does NOT follow the ado: two
      // separators make the field count even, so outreg2 succeeds and writes a
      // wrong number rather than refusing.
      refused("outreg2 using \"w5adc\", replace text addstat(M, 9999999) adec(0)\n", "9,999,999",
              "W5 (x.20): two separators are the NAMED divergence -- outreg2 2.x writes this table "
              "with `M 9` and an invented row `999` (w1b_adec_rule3.log t5, rc 0). Following that "
              "bug-for-bug would publish a wrong number, so this build refuses");

      // adec()'s own conditionality and bounds, each with the ado's sentence.
      refused("outreg2 using \"w5add\", replace text adec(1)\n",
              "cannot choose adec option without addstat option",
              "W5 (x.20): `adec()` with no `addstat()` is outreg2's own conditional refusal, word "
              "for word (w1b_adec_rule.log e1)");
      refused("outreg2 using \"w5ade\", replace text addstat(M, 1.5) adec(12)\n",
              "outside of allowed range",
              "W5 (x.20): adec() is `numlist int >=0 <=11`, and 12 is r(125) (g1)");
      refused("outreg2 using \"w5adf\", replace text addstat(M, 1.5) adec(1.5)\n", "noninteger",
              "W5 (x.20): ...a non-integer is a DIFFERENT rc, r(126), with its own sentence (g3)");
      refused("outreg2 using \"w5adg\", replace text addstat(M, 1.5) adec(1 3)\n",
              "single number required",
              "W5 (x.20): ...and `max=1` makes two numbers r(123) (d2). Collapsing these three "
              "into one rc would lose what the user is being told");

      // `afmt()` is the ado's escape hatch and is deliberately NOT accepted:
      // zero corpus uses and its non-`f` suffixes are unmeasured.
      refused("outreg2 using \"w5adh\", replace text addstat(M, 6165.257) adec(1) afmt(f)\n",
              "afmt",
              "W5 (x.20): `afmt()` stays REFUSED BY NAME. It is the one spelling that makes the "
              "big-mean line legal in Stata, so accepting it while guessing its other suffixes "
              "would be exactly the accept-and-ignore this campaign exists to prevent");
    }

    // ── (x.15) W1a-2 / BUG-407: cells(), and main()/aux() which ARE cells().
    // esttab builds a cells() spec out of main/aux whenever cells()
    // is absent, so all three reach one path here. Oracle:
    // tests/eval/golden/aer_w1/w1b_tables_pins.log arms c1/c3/c4/c5/c7.
    {
      auto run = [&](const std::string& cmd) { return exec(cmd, s); };
      auto okc = [&](const std::string& cmd, const std::string& why) {
        auto r = run(cmd);
        check(firstError(r.blocks).is_null(),
              why + " [got: " + errText(firstError(r.blocks)) + "]");
      };
      // c1: the coefficient carries the star and the format; the aux row is
      // parenthesised because the SPEC says par, not because it always is.
      okc("esttab w5a w5b using \"w5k1.txt\", replace cells(b(star fmt(%9.3f)) se(par))\n",
          "W5 (x.15): `cells(b(star fmt(%9.3f)) se(par))` runs -- it was refused by name until now "
          "(BUG-407)");
      const std::string k1 = slurp(at("w5k1.txt"));
      check(has(k1, "(") && k1.find('*') != std::string::npos,
            "W5 (x.15): ...and it renders a starred coefficient over a parenthesised se. Got:\n" +
                k1);
      // c4: main(se 2) aux(none) -- the MAIN row carries the standard error,
      // there is no aux row at all, and the legend names both.
      okc("esttab w5a w5b using \"w5k4.txt\", replace main(se 2) aux(none)\n",
          "W5 (x.15): `main(se 2) aux(none)` runs");
      const std::string k4 = slurp(at("w5k4.txt"));
      check(has(k4, "se coefficients; none in parentheses"),
            "W5 (x.15): ...and the legend is `se coefficients; none in parentheses` -- the word "
            "`none` really is in Stata's note (c4), which is the sort of thing only a capture "
            "tells you. Got:\n" + k4);
      check(!has(k4, "t statistics in parentheses"),
            "W5 (x.15): ...and the DEFAULT legend is gone, because the aux row is");
      // c5: main(b 3) aux(t 2) -- both named, both formats honoured.
      okc("esttab w5a w5b using \"w5k5.txt\", replace main(b 3) aux(t 2)\n",
          "W5 (x.15): `main(b 3) aux(t 2)` runs");
      check(has(slurp(at("w5k5.txt")), "b coefficients; t in parentheses"),
            "W5 (x.15): ...and its legend names both statistics (c5)");
      // `aux(none)` is NOT `not`, and the difference is four rows. `not`
      // removes the aux row and every gap (t_not.txt); `aux(none)` names a
      // cell estout does not know, so the row is still EMITTED as blanks and
      // the gap survives (c4, whose lines 5/8/11/14 are 44 columns of spaces).
      // The first cut of W1a-2 mapped both onto one enum and dropped those
      // rows; this pair is what tells them apart.
      {
        auto countBlankPadded = [&](const std::string& t) {
          size_t n = 0;
          size_t pos = 0;
          while (pos <= t.size()) {
            const size_t nl = t.find('\n', pos);
            const std::string line = t.substr(pos, (nl == std::string::npos ? t.size() : nl) - pos);
            if (!line.empty() && line.find_first_not_of(' ') == std::string::npos) ++n;
            if (nl == std::string::npos) break;
            pos = nl + 1;
          }
          return n;
        };
        const std::string an = slurp(at("w5k4.txt"));
        okc("esttab w5a w5b using \"w5kn.txt\", replace not\n", "W5 (x.15): `not` runs");
        const std::string nt = slurp(at("w5kn.txt"));
        check(countBlankPadded(an) > 0,
              "W5 (x.15): `aux(none)` EMITS its aux row as blanks -- padded-but-present lines, "
              "not removed (c4). Got:\n" + an);
        check(countBlankPadded(nt) == 0,
              "W5 (x.15): ...while `not` removes the aux row entirely and leaves no padded blank "
              "behind (t_not.txt). Two options, two shapes, one enum used to serve both. Got:\n" +
                  nt);
      }
      // Under cells() there are NO notes at all -- not the coefficient line and
      // not the star legend. All four captured cells() arms end at the rule.
      check(!has(k1, "p<0.05"),
            "W5 (x.15): under cells() the STAR LEGEND is suppressed too, not just the coefficient "
            "line -- c1/c3/c7/c8 all end at the rule under N. Suppressing only the first would "
            "have left a legend Stata does not print. Got:\n" + k1);
      {
        auto r = run("esttab w5a using \"w5kc.txt\", replace\n");
        check(firstError(r.blocks).is_null(), "W5 (x.15): the control still runs");
        check(has(slurp(at("w5kc.txt")), "t statistics in parentheses"),
              "W5 (x.15): ...and WITHOUT any of the three the default legend is untouched -- the "
              "cells() path is separate precisely so the byte-verified default cannot move");
      }
      // c7: `par([ ])` names the two delimiters. The depth-blind bracket guard
      // refused this spelling, which the corpus writes 327 times against zero
      // uses of the top-level grouping the guard exists for.
      okc("esttab w5a w5b using \"w5k7.txt\", replace cells(se(par([ ]) fmt(2)))\n",
          "W5 (x.15): `cells(se(par([ ]) fmt(2)))` runs -- the brackets are DELIMITERS, not the "
          "grouping notation");
      check(has(slurp(at("w5k7.txt")), "["),
            "W5 (x.15): ...and the se really is rendered in brackets (c7)");
      // ── The four things cells() inherits from ESTOUT, not from esttab.
      // esttab forwards the cells() spec to estout unchanged (matches esttab's
      // behaviour, identified from its ado), so on this path
      // esttab's own defaults do not apply at all. Each of these was live in
      // the first cut of BUG-407's fix and each was caught by an adversarial
      // re-read of the ado against the same captures.
      {
        const std::string c1 = slurp(at("w5k1.txt"));
        const std::string c7 = slurp(at("w5k7.txt"));
        okc("esttab w5a w5b using \"w5k3.txt\", replace cells(b(star) p(par fmt(3)))\n",
            "W5 (x.15): `cells(b(star) p(par fmt(3)))` runs");
        const std::string c3 = slurp(at("w5k3.txt"));
        const std::string ctl = slurp(at("w5kc.txt"));
        // D3 -- the cell-name row, joined with `/` when the spec stacks two.
        check(has(c1, "\tb/se") || c1.find("b/se") != std::string::npos,
              "W5 (x.15): cells() lets estout's CELL-NAME row through -- `b/se` (c1). esttab "
              "injects collabels(none) to suppress it only on the no-cells path "
              "(matches esttab's behaviour, identified from its ado). Got:\n" + c1);
        check(c3.find("b/p") != std::string::npos && c7.find("\n" ) != std::string::npos &&
                  c7.find("se") != std::string::npos,
              "W5 (x.15): ...and it names what the spec actually holds -- `b/p` for c3, `se` "
              "alone for the one-item c7");
        check(ctl.find("b/se") == std::string::npos,
              "W5 (x.15): ...while the DEFAULT table has no such row at all");
        // D4 -- the WRONG VALUE. A cells() item with no fmt() is %9.0g, not
        // esttab's adaptive a3. This is the one that printed a different number.
        // Fixture-independent: count the decimals in the first numeric cell of
        // the body. `a3` can never exceed three; %9.0g routinely does.
        auto firstDecimals = [](const std::string& t) -> int {
          size_t pos = 0;
          int line = 0;
          while (pos <= t.size()) {
            const size_t nl = t.find('\n', pos);
            const std::string l = t.substr(pos, (nl == std::string::npos ? t.size() : nl) - pos);
            if (nl == std::string::npos) break;
            pos = nl + 1;
            // The head rows and the aux rows begin with a space and the rules
            // with `-`, so the first line that survives both is the first
            // COEFFICIENT row. (An earlier cut also skipped three "head" lines
            // on top of that and therefore skipped every body row instead,
            // returning -1 — the check failed against correct output.)
            if (l.empty() || l[0] == '-' || l[0] == ' ') continue;
            (void)line;
            const size_t dot = l.find('.');
            if (dot == std::string::npos) continue;
            int n = 0;
            for (size_t i = dot + 1; i < l.size() && std::isdigit(static_cast<unsigned char>(l[i]));
                 ++i) {
              ++n;
            }
            return n;
          }
          return -1;
        };
        const int d3 = firstDecimals(c3);
        const int d1 = firstDecimals(c1);
        check(d3 > 3,
              "W5 (x.15): a cells() item with NO fmt() carries Stata's general format, which "
              "routinely runs past three decimals (`-49.51222` on the oracle's data) -- esttab's "
              "adaptive a3 never can. The first cut printed the a3 value, which is a different "
              "NUMBER in a published table. Got " + std::to_string(d3) + " decimals:\n" + c3);
        check(d1 == 3,
              "W5 (x.15): ...and an item that DOES give fmt() keeps exactly it (c1's b at %9.3f), "
              "with the next item inheriting that running format rather than reverting to the "
              "default. Got " + std::to_string(d1) + " decimals:\n" + c1);
        // D2 -- no gaps under cells().
        auto blankLines = [](const std::string& t) {
          size_t n = 0, pos = 0;
          while (pos <= t.size()) {
            const size_t nl = t.find('\n', pos);
            if (t.substr(pos, (nl == std::string::npos ? t.size() : nl) - pos).empty()) ++n;
            if (nl == std::string::npos) break;
            pos = nl + 1;
          }
          return n;
        };
        check(blankLines(c1) <= 1 && blankLines(ctl) > 1,
              "W5 (x.15): cells() tables have NO blank line between coefficients and the default "
              "table does -- the gap is esttab's, added at :495-496 only when cells() is absent. "
              "Got cells:\n" + c1);
        // D5 -- the star field is reserved only when a spec asks for stars.
        const size_t ruleC1 = c1.find('\n') == std::string::npos ? 0 : c1.find('\n');
        const size_t ruleC7 = c7.find('\n') == std::string::npos ? 0 : c7.find('\n');
        check(ruleC1 > ruleC7,
              "W5 (x.15): ...and a spec with no `star` reserves no star column, so c7's rule is "
              "NARROWER than c1's by exactly the star field on each model column (38 vs 44 on the "
              "oracle's two-model table). Got " + std::to_string(ruleC1) + " vs " +
                  std::to_string(ruleC7));
      }
      {
        auto r = run("esttab w5a using \"w5kg.txt\", replace cells([b se])\n");
        check(!firstError(r.blocks).is_null(),
              "W5 (x.15): ...while the TOP-LEVEL grouping `cells([b se])` is still refused -- the "
              "guard became depth-aware, not absent");
      }
      // W2AK: the shapes that used to be refused by name are RENDERED now that
      // esttab runs on the transcribed estout writer. The quoted form puts its
      // items side by side (one row, two columns per model; aer_w2
      // w2ak_estout_family.log ek_e33 `&       1.468&    (0.0742)&`); a third
      // item is a third stacked row (ek_e20, `[0.500]`); and a statistic e()
      // does not hold resolves to no coefficient rows at all, rc 0 (ek_c07,
      // log:3360-3375: the table is heads and rules only).
      {
        auto r = run("esttab w5a using \"w5kx1.txt\", replace cells(\"b se\")\n");
        check(firstError(r.blocks).is_null(), "W5 (x.15): cells(\"b se\") renders (ek_e33)");
        const std::string t = slurp(at("w5kx1.txt"));
        size_t xl = t.find("\nx1");
        const std::string row = xl == std::string::npos ? std::string()
                                                       : t.substr(xl + 1, t.find('\n', xl + 1) - xl - 1);
        size_t nTok = 0;
        {
          std::istringstream is(row);
          std::string tok;
          while (is >> tok) ++nTok;
        }
        check(nTok == 3,
              "W5 (x.15): ...as ONE row per coefficient with b and se side by side. Got:\n" + t);
      }
      {
        auto r = run("esttab w5a using \"w5kx2.txt\", replace cells(b se t)\n");
        check(firstError(r.blocks).is_null(), "W5 (x.15): cells(b se t) renders (ek_e20)");
      }
      {
        auto r = run("esttab w5a using \"w5kx3.txt\", replace cells(zzzbogus)\n");
        check(firstError(r.blocks).is_null() && !has(slurp(at("w5kx3.txt")), "x1"),
              "W5 (x.15): cells(zzzbogus) is rc 0 with no coefficient rows (ek_c07)");
      }
    }
  }

  fs::remove_all(workdir, ec);
}


// ── AER-SCOPE1 bundle F (RESHAPE, 2026-09-04) ────────────────────────────────
//
// Seventeen verbs that RESHAPE OR REPLACE the frame. Their whole failure class
// is rc 0 with the wrong frame, and every wrong implementation this bundle can
// plausibly ship returns 0: a `split` that counts three parts and writes three
// empty columns, an `insobs` that copies the last row forward instead of
// appending missing, a `pctile` that broadcasts one percentile down the whole
// column, a `bsample, cluster()` that resamples ROWS and calls them clusters,
// an `input` that reads two rows of text as two rows of nothing, a `recast`
// that round-trips the column through a CSV and moves the ninth digit. So NO
// leg below stops at a return code: each one reads a VALUE back out of the
// frame the verb produced, and the value chosen is one the wrong
// implementation named in its comment would get wrong.
//
// TWO HOUSE RULES ARE FOLLOWED LITERALLY HERE BECAUSE BOTH HAVE COST TIME:
//   - EVERY session sets `cwd` as well as `eval.cwd`. resolveUserPath reads
//     SessionState::cwd (handlers.cpp:2040); a session that seeds only
//     eval.cwd writes leg (xi)'s .dta into the PROCESS cwd -- the repo root --
//     and the round-trip half of that leg fails for a reason that has nothing
//     to do with `notes`.
//   - Numeric comparisons report through `fullPrec` (%.17g), never
//     std::to_string, which prints six decimals and renders a genuine
//     8th-digit difference as two identical strings.
//
// Nothing here asserts a PATH: the workdir is this process's temp directory.
// What is asserted is row counts, column contents and metadata.
void testAerReshape() {
  std::printf("[selftest] --- AER-SCOPE1 bundle F: split/xpose/insobs/stack/cumul/pctile + the "
              "three sampling verbs + input/notes/recast + the refusals ---\n");
  namespace fs = std::filesystem;
  std::string workdir = (fs::temp_directory_path() / "piet_native_selftest_aerreshape").u8string();
  std::error_code ec;
  fs::remove_all(workdir, ec);
  fs::create_directories(workdir, ec);

  auto exec = [](const std::string& src, piet::SessionState& session) {
    return piet::doexec::executeDoSource(src, session, piet::dispatch);
  };
  // Returns a NULL json when there is no error block rather than throwing --
  // the BUG-129 trap, and check()'s message argument is built EAGERLY (on the
  // passing path too), so every message below reads through these helpers.
  auto firstError = [](const nlohmann::ordered_json& blocks) -> nlohmann::ordered_json {
    for (const auto& b : blocks)
      if (b.is_object() && b.value("type", std::string()) == "error") return b;
    return nlohmann::ordered_json();
  };
  auto errText = [](const nlohmann::ordered_json& e) {
    return e.is_object() ? e.value("message", std::string()) : std::string("<none>");
  };
  auto errField = [](const nlohmann::ordered_json& e, const std::string& f) {
    return e.is_object() ? e.value(f, std::string()) : std::string("<none>");
  };
  auto rcOf = [](const nlohmann::ordered_json& e) {
    return e.is_object() ? piet::eval::coarseRc(e) : std::string("<none>");
  };
  // See the header: %.17g, because `-77.551724` twice is not a failure report.
  auto fullPrec = [](double v) {
    char buf[48];
    std::snprintf(buf, sizeof(buf), "%.17g", v);
    return std::string(buf);
  };
  auto has = [](const std::string& hay, const std::string& needle) {
    return hay.find(needle) != std::string::npos;
  };
  auto displays = [](const auto& blocks) {
    std::vector<std::string> v;
    for (const auto& b : blocks)
      if (b.is_object() && b.value("type", std::string()) == "display")
        v.push_back(b.value("text", std::string()));
    return v;
  };
  auto displayValue = [&](const auto& blocks, const std::string& prefix) -> double {
    for (const auto& s : displays(blocks)) {
      if (s.rfind(prefix, 0) != 0) continue;
      try {
        return std::stod(s.substr(prefix.size()));
      } catch (...) {
        return std::nan("");
      }
    }
    return std::nan("");
  };
  auto varNames = [](piet::SessionState& s) {
    std::vector<std::string> out;
    const nlohmann::ordered_json blocks = piet::dispatch("describe", s);
    for (const auto& b : blocks)
      if (b.is_object() && b.value("type", std::string()) == "describe" && b.contains("variables"))
        for (const auto& v : b["variables"]) out.push_back(v.value("name", std::string()));
    return out;
  };
  auto hasName = [](const std::vector<std::string>& v, const std::string& n) {
    return std::find(v.begin(), v.end(), n) != v.end();
  };
  // describe's per-variable `dtype` IS varMeta.stataType when one is recorded
  // and the "str#"/"float" default otherwise, which is exactly what legs (i)
  // and (xii) need to distinguish.
  auto dtypeOf = [](piet::SessionState& s, const std::string& name) -> std::string {
    const nlohmann::ordered_json blocks = piet::dispatch("describe", s);
    for (const auto& b : blocks)
      if (b.is_object() && b.value("type", std::string()) == "describe" && b.contains("variables"))
        for (const auto& v : b["variables"])
          if (v.value("name", std::string()) == name) return v.value("dtype", std::string());
    return std::string("<absent>");
  };
  // r() is REPLACED wholesale by a summarize (macros.cpp's captureRFromBlock),
  // so every read below happens immediately after the command that published
  // it -- never two commands later.
  auto rOf = [](piet::SessionState& s, const char* key) -> double {
    const double* p = s.eval.rValues.find(key);
    return p ? *p : std::nan("");
  };
  auto runR = [&](piet::SessionState& s, const std::string& cmd, const char* key) -> double {
    (void)piet::dispatch(cmd, s);
    return rOf(s, key);
  };
  // `count` with no `if` is _N. Used instead of `display _N` so the row count
  // and the conditional counts below come off the same surface.
  auto nRows = [&](piet::SessionState& s) { return runR(s, "count", "N"); };
  auto countIf = [&](piet::SessionState& s, const std::string& expr) {
    return runR(s, "count if " + expr, "N");
  };

  // ── (i) `input` builds a dataset out of a BLOCK. ───────────────────────────
  // The block is folded into one line at preprocess time, so this leg also
  // proves captureInputBlocks ran: an unfolded block dispatches `1 2` as a
  // command and the run halts. N==3 alone is true of an input that read three
  // rows of garbage, so the SUM is asserted too -- that is the half that says
  // the digits survived the fold, the split and the CSV staging.
  {
    piet::SessionState s(workdir);
    s.eval.cwd = workdir;
    s.cwd = workdir;  // resolveUserPath reads THIS field (handlers.cpp:2040).
    auto r = exec("clear\ninput x y\n1 2\n3 4\n5 6\nend\n", s);
    check(firstError(r.blocks).is_null(),
          "AER-RESHAPE (i): `input x y` ... `end` runs clean into an empty session. Got `" +
              errText(firstError(r.blocks)) + "`");
    check(nRows(s) == 3.0,
          "AER-RESHAPE (i): ...and leaves THREE rows. Got " + fullPrec(nRows(s)));
    const double sx = runR(s, "summarize x", "sum");
    check(sx == 9.0,
          "AER-RESHAPE (i): ...x sums to 9 (1+3+5). A row count is satisfied by an input that "
          "created three EMPTY rows, which is what a fold that dropped the data lines produces. "
          "Got " + fullPrec(sx));
    const double sy = runR(s, "summarize y", "sum");
    check(sy == 12.0,
          "AER-RESHAPE (i): ...and y sums to 12 (2+4+6), so the SECOND column got the second "
          "field of each row rather than a copy of the first. Got " + fullPrec(sy));
    check(dtypeOf(s, "x") != "str#",
          "AER-RESHAPE (i): ...and x is NUMERIC. A bare varlist declares numbers; storing them as "
          "strings makes every downstream `summarize`/`regress` fail on a dataset that lists "
          "correctly. Got dtype `" + dtypeOf(s, "x") + "`");

    // The `str#` prefix form: `s` must come back a string column.
    auto r2 = exec("clear\ninput str5 s n\n\"aa\" 1\n\"bb\" 2\nend\n", s);
    check(firstError(r2.blocks).is_null(),
          "AER-RESHAPE (i/str): `input str5 s n` runs clean. Got `" +
              errText(firstError(r2.blocks)) + "`");
    check(nRows(s) == 2.0,
          "AER-RESHAPE (i/str): ...two rows. Got " + fullPrec(nRows(s)));
    check(dtypeOf(s, "s") != "float" && dtypeOf(s, "s") != "<absent>",
          "AER-RESHAPE (i/str): ...and `str5 s` produced a STRING column, not a numeric one full "
          "of missing -- which is what an input that ignored the type prefix produces, and it "
          "reads as a legitimate all-missing variable. Got dtype `" + dtypeOf(s, "s") + "`");
    check(countIf(s, "s == \"bb\"") == 1.0,
          "AER-RESHAPE (i/str): ...carrying the QUOTED literal, unquoted, in the right row. Got " +
              fullPrec(countIf(s, "s == \"bb\"")));
    check(runR(s, "summarize n", "sum") == 3.0,
          "AER-RESHAPE (i/str): ...and the numeric column beside it still parsed (1+2). Got " +
              fullPrec(runR(s, "summarize n", "sum")));
  }

  // ── (ii) `split` decomposes a string column into k real columns. ───────────
  // r(nvars)==3 is satisfied by a handler that counted the parts and wrote
  // nothing (or wrote them all into stub1), so all three parts are read back.
  {
    piet::SessionState s(workdir);
    s.eval.cwd = workdir;
    s.cwd = workdir;  // resolveUserPath reads THIS field (handlers.cpp:2040).
    auto r = exec("clear\nset obs 6\ngen str9 sv = \"a-b-c\"\nsplit sv, parse(\"-\") gen(p)\n", s);
    check(firstError(r.blocks).is_null(),
          "AER-RESHAPE (ii): `split sv, parse(\"-\") gen(p)` runs clean. Got `" +
              errText(firstError(r.blocks)) + "`");
    const double nv = rOf(s, "nvars");
    check(nv == 3.0,
          "AER-RESHAPE (ii): r(nvars) == 3 -- three parts, so the parse() delimiter was honoured "
          "rather than the whitespace default (which would find ONE part in \"a-b-c\" and is the "
          "exact reason `gen = word(v,j)` was rejected as the implementation). Got " +
              fullPrec(nv));
    const std::vector<std::string> names = varNames(s);
    check(hasName(names, "p1") && hasName(names, "p2") && hasName(names, "p3"),
          "AER-RESHAPE (ii): ...and the columns are named p1 p2 p3 off gen()'s stub, not off the "
          "source variable");
    check(countIf(s, "p1 == \"a\"") == 6.0 && countIf(s, "p2 == \"b\"") == 6.0 &&
              countIf(s, "p3 == \"c\"") == 6.0,
          "AER-RESHAPE (ii): ...and every row of every part carries its OWN piece. This is the "
          "check r(nvars) cannot make: a split that created three columns and left them empty, or "
          "wrote the whole string into p1, satisfies the count and the names. Got p1=" +
              fullPrec(countIf(s, "p1 == \"a\"")) + " p2=" + fullPrec(countIf(s, "p2 == \"b\"")) +
              " p3=" + fullPrec(countIf(s, "p3 == \"c\"")));

    // `destring`: parts that are entirely numeric become f64.
    auto r2 = exec("clear\nset obs 4\ngen str9 sn = \"1-2\"\n"
                   "split sn, parse(\"-\") gen(q) destring\n", s);
    check(firstError(r2.blocks).is_null(),
          "AER-RESHAPE (ii/destring): `split ..., destring` runs clean. Got `" +
              errText(firstError(r2.blocks)) + "`");
    check(dtypeOf(s, "q1") != "str#",
          "AER-RESHAPE (ii/destring): ...and q1 came back NUMERIC. A destring that silently left "
          "the parts as strings still lists as `1` and fails every arithmetic use of the column. "
          "Got dtype `" + dtypeOf(s, "q1") + "`");
    const double q2sum = runR(s, "summarize q2", "sum");
    check(q2sum == 8.0,
          "AER-RESHAPE (ii/destring): ...and it holds the NUMBER (4 rows x 2 == 8), so the "
          "conversion read the digits rather than producing an all-missing numeric column. Got " +
              fullPrec(q2sum));
  }

  // ── (iii) ONE percentile rule: `_pctile` == `summarize, detail`. ───────────
  // The dataset is 1..10 -- EVEN N with distinct central values -- on purpose.
  // At even N the three plausible rules separate:
  //     Stata / Frame::xtile / winsor2 : p50 = (5+6)/2 = 5.5, p25 = 3
  //     "order statistic"              : p50 = 5,           p25 = 3
  //     numpy linear interpolation     : p50 = 5.5,         p25 = 3.25
  // so p50 falsifies the order-statistic rule and p25 falsifies the numpy one.
  // An odd-N fixture makes all three agree and this leg would assert nothing.
  //
  // BOTH halves are asserted, and separately: the EQUALITY says the product has
  // one percentile rule instead of two, and the ABSOLUTE value says that one
  // rule is Stata's. Equality alone is satisfied by two identical wrong rules,
  // which is the failure that ships quietly.
  {
    piet::SessionState s(workdir);
    s.eval.cwd = workdir;
    s.cwd = workdir;  // resolveUserPath reads THIS field (handlers.cpp:2040).
    auto r = exec("clear\nset obs 10\ngen double x = _n\n_pctile x, p(25 50)\n", s);
    check(firstError(r.blocks).is_null(),
          "AER-RESHAPE (iii): `_pctile x, p(25 50)` runs clean. Got `" +
              errText(firstError(r.blocks)) + "`");
    // Read r(r1)/r(r2) BEFORE the summarize below: captureRFromBlock REPLACES
    // the whole r() store on a summarize block, so reading them afterwards
    // would read nothing and the equality would compare two NaNs.
    const double r1 = rOf(s, "r1");
    const double r2v = rOf(s, "r2");
    check(r2v == 5.5,
          "AER-RESHAPE (iii): _pctile's p50 over 1..10 is 5.5 -- Stata averages the two straddling "
          "order statistics when N*p/100 lands on an integer. 5 means the handler took the lower "
          "order statistic (the `winsor` rule, which bundle A had to keep SEPARATE from winsor2 "
          "for exactly this reason). Got " + fullPrec(r2v));
    check(r1 == 3.0,
          "AER-RESHAPE (iii): ...and its p25 is 3, not 3.25. 3.25 is numpy's linear-interpolation "
          "percentile, which is what handlers.cpp:1096's FALLBACK summarize path computes -- so "
          "this is the number that catches a handler wired to that lambda instead of to the "
          "xtile/winsor2 rule the bundle contracted for. Got " + fullPrec(r1));
    (void)piet::dispatch("summarize x, detail", s);
    const double p50 = rOf(s, "p50");
    const double p25 = rOf(s, "p25");
    check(!std::isnan(p50) && p50 == r2v,
          "AER-RESHAPE (iii): `_pctile`'s p50 EQUALS `summarize, detail`'s p50, BIT-EXACT. Two "
          "percentile rules in one product is a silently wrong number in whichever surface the "
          "user did not check; this is the leg that says there is one. Got _pctile " +
              fullPrec(r2v) + " vs summarize,detail " + fullPrec(p50));
    check(!std::isnan(p25) && p25 == r1,
          "AER-RESHAPE (iii): ...and so does p25, which is the percentile where the two candidate "
          "rules actually differ at this N -- p50 agrees between Stata's rule and numpy's, so p50 "
          "alone would not have separated them. Got _pctile " + fullPrec(r1) +
              " vs summarize,detail " + fullPrec(p25));
  }

  // ── (iv) `cumul` is the empirical CDF, and `equal` changes the answer. ─────
  {
    piet::SessionState s(workdir);
    s.eval.cwd = workdir;
    s.cwd = workdir;  // resolveUserPath reads THIS field (handlers.cpp:2040).
    auto r = exec("clear\nset obs 10\ngen double x = _n\ncumul x, gen(cx)\n", s);
    check(firstError(r.blocks).is_null(),
          "AER-RESHAPE (iv): `cumul x, gen(cx)` runs clean. Got `" +
              errText(firstError(r.blocks)) + "`");
    (void)piet::dispatch("summarize cx", s);
    const double cmax = rOf(s, "max");
    const double cmin = rOf(s, "min");
    check(cmax == 1.0,
          "AER-RESHAPE (iv): the CDF reaches EXACTLY 1 at the top. 0.9 means the denominator was "
          "N+1, 1.1 means it was N-1; both look like a CDF and neither is one. Got " +
              fullPrec(cmax));
    // cumul's ECDF column is a FLOAT, as cumul.ado makes it
    // (w2as_summary_stats_family.log:7931 `float|%9.0g|ECDF of x`, and :7938 reads
    // float-rounded values back), so 1/N arrives as float(0.1), not the double 0.1.
    check(cmin == static_cast<double>(0.1f),
          "AER-RESHAPE (iv): ...and starts at 1/N == float(0.1), so the ranks are 1-based. A "
          "0-based rank gives 0 here and shifts every value in the column. Got " +
              fullPrec(cmin));

    // `equal`: tied observations all take the MAXIMUM rank. Without it the
    // ties take their own positions, so the two halves of `tt` would read
    // 0.1..0.5 and 0.6..1.0 instead of a flat 0.5 and 1.0.
    auto r2 = exec("clear\nset obs 10\ngen double tt = 1\nreplace tt = 2 in 6/10\n"
                   "cumul tt, gen(ct) equal\n", s);
    check(firstError(r2.blocks).is_null(),
          "AER-RESHAPE (iv/equal): `cumul tt, gen(ct) equal` runs clean. Got `" +
              errText(firstError(r2.blocks)) + "`");
    check(countIf(s, "ct == 0.5") == 5.0 && countIf(s, "ct == 1") == 5.0,
          "AER-RESHAPE (iv/equal): with `equal`, all five tied rows share the MAXIMUM rank -- 0.5 "
          "for the first level and 1 for the second. An implementation that accepted `equal` and "
          "ignored it produces ten distinct values, every one of them a plausible CDF number, and "
          "no rc says so. Got n(0.5)=" + fullPrec(countIf(s, "ct == 0.5")) + " n(1)=" +
              fullPrec(countIf(s, "ct == 1")));
  }

  // ── (v) `insobs 2, before(1)` puts two EMPTY rows at the FRONT. ───────────
  {
    piet::SessionState s(workdir);
    s.eval.cwd = workdir;
    s.cwd = workdir;  // resolveUserPath reads THIS field (handlers.cpp:2040).
    auto r = exec("clear\nset obs 5\ngen double x = _n\ninsobs 2, before(1)\n"
                  "display \"RS_INS1=\" x[1]\n"
                  "display \"RS_INS3=\" x[3]\n"
                  "display \"RS_INS7=\" x[7]\n",
                  s);
    check(firstError(r.blocks).is_null(),
          "AER-RESHAPE (v): `insobs 2, before(1)` runs clean. Got `" +
              errText(firstError(r.blocks)) + "`");
    check(nRows(s) == 7.0,
          "AER-RESHAPE (v): ...and the frame grew by exactly 2, to 7. Got " +
              fullPrec(nRows(s)));
    (void)piet::dispatch("summarize x", s);
    const double nNonMiss = rOf(s, "N");
    const double xSum = rOf(s, "sum");
    check(nNonMiss == 5.0 && xSum == 15.0,
          "AER-RESHAPE (v): ...and exactly the ORIGINAL five values are still there (1+..+5 == "
          "15) with nothing invented in the new rows. An insobs that copied a neighbouring row "
          "forward -- the cheapest way to make an append `work` -- lands 7 non-missing here and "
          "satisfies the row count above. Got N " + fullPrec(nNonMiss) + " sum " + fullPrec(xSum));
    // The POSITION half, read through subscripts rather than `summarize ... in`
    // so a missing cell is observable as one: x[1] must be missing (which is
    // what a non-numeric display renders as, hence the NaN), and the original
    // block must have moved down by exactly two -- x[3] == 1 and x[7] == 5.
    // x[3] is what proves the display path itself works, so the NaN above is
    // evidence of a missing cell and not of a broken subscript.
    const double ins1 = displayValue(r.blocks, "RS_INS1=");
    const double ins3 = displayValue(r.blocks, "RS_INS3=");
    const double ins7 = displayValue(r.blocks, "RS_INS7=");
    check(ins3 == 1.0 && ins7 == 5.0,
          "AER-RESHAPE (v): the two new rows went to the FRONT: the original block starts at row "
          "3 (x[3] == 1) and ends at row 7 (x[7] == 5). This is the entire content of `before(1)` "
          "-- an insobs that took the default end-append path passes every other check in this "
          "leg. Got x[3] " + fullPrec(ins3) + " x[7] " + fullPrec(ins7));
    check(std::isnan(ins1),
          "AER-RESHAPE (v): ...and row 1 is MISSING, not 0 and not a copy. Got x[1] `" +
              fullPrec(ins1) + "`");
  }

  // ── (vi) `xpose, clear varname` transposes the whole frame. ───────────────
  {
    piet::SessionState s(workdir);
    s.eval.cwd = workdir;
    s.cwd = workdir;  // resolveUserPath reads THIS field (handlers.cpp:2040).
    auto r = exec("clear\nset obs 3\ngen double a = _n\ngen double b = _n*10\n"
                  "xpose, clear varname\n"
                  "display \"RS_XP11=\" %22.17f v1[1]\n"
                  "display \"RS_XP32=\" %22.17f v3[2]\n",
                  s);
    check(firstError(r.blocks).is_null(),
          "AER-RESHAPE (vi): `xpose, clear varname` over 3 obs x 2 vars runs clean. Got `" +
              errText(firstError(r.blocks)) + "`");
    check(nRows(s) == 2.0,
          "AER-RESHAPE (vi): ...and the 3x2 frame became a 2-ROW frame -- rows and columns really "
          "swapped. Got " + fullPrec(nRows(s)));
    const std::vector<std::string> names = varNames(s);
    check(hasName(names, "v1") && hasName(names, "v2") && hasName(names, "v3"),
          "AER-RESHAPE (vi): ...with three columns named v1 v2 v3, one per original OBSERVATION");
    check(hasName(names, "_varname"),
          "AER-RESHAPE (vi): ...and `varname` added the `_varname` column. Without it the "
          "transpose is irreversible: nothing in the result says which row was `a`");
    check(countIf(s, "_varname == \"a\"") == 1.0 && countIf(s, "_varname == \"b\"") == 1.0,
          "AER-RESHAPE (vi): ..._varname carries the ORIGINAL NAMES, one row each -- not v1/v2 or "
          "an index. Got a=" + fullPrec(countIf(s, "_varname == \"a\"")) + " b=" +
              fullPrec(countIf(s, "_varname == \"b\"")));
    const double xp11 = displayValue(r.blocks, "RS_XP11=");
    const double xp32 = displayValue(r.blocks, "RS_XP32=");
    check(xp11 == 1.0,
          "AER-RESHAPE (vi): ...and the CELLS moved with the shape: v1[1] is a[1] == 1. The shape "
          "checks above are all satisfied by a transpose that filled the result with zeros. Got " +
              fullPrec(xp11));
    check(xp32 == 30.0,
          "AER-RESHAPE (vi): ...and v3[2] is b[3] == 30, which is the OPPOSITE corner -- a "
          "transpose that transposed the index but not the data, or transposed it twice, gets "
          "this one wrong while getting v1[1] right. Got " + fullPrec(xp32));
  }

  // ── (vii) `stack a b, into(v) clear` piles k columns into one. ────────────
  {
    piet::SessionState s(workdir);
    s.eval.cwd = workdir;
    s.cwd = workdir;  // resolveUserPath reads THIS field (handlers.cpp:2040).
    auto r = exec("clear\nset obs 4\ngen double a = _n\ngen double b = _n + 100\n"
                  "stack a b, into(sv) clear\n", s);
    check(firstError(r.blocks).is_null(),
          "AER-RESHAPE (vii): `stack a b, into(sv) clear` runs clean. Got `" +
              errText(firstError(r.blocks)) + "`");
    check(nRows(s) == 8.0,
          "AER-RESHAPE (vii): ...and 4 rows x 2 variables became 8 rows. Got " +
              fullPrec(nRows(s)));
    // Read through `summarize _stack` rather than two `count if`s: _stack is
    // numeric, and N/min/max/sum together pin the 4/4 split exactly (8 values
    // in {1,2} summing to 12 is 4 of each) without putting an underscore-led
    // name through the expression parser.
    (void)piet::dispatch("summarize _stack", s);
    const double stN = rOf(s, "N"), stMin = rOf(s, "min"), stMax = rOf(s, "max"),
                 stSum = rOf(s, "sum");
    check(stN == 8.0 && stMin == 1.0 && stMax == 2.0 && stSum == 12.0,
          "AER-RESHAPE (vii): ..._stack splits them 4/4 (8 values, min 1, max 2, sum 12), so the "
          "index says WHICH variable each row came from. A stack that appended the frame to "
          "itself gives 8 rows with _stack all 1 -- max 1, sum 8 -- and every shape check but "
          "this one passes. Got N " + fullPrec(stN) + " min " + fullPrec(stMin) + " max " +
              fullPrec(stMax) + " sum " + fullPrec(stSum));
    const double svSum = runR(s, "summarize sv", "sum");
    check(svSum == 420.0,
          "AER-RESHAPE (vii): ...and `sv` carries BOTH columns' values: (1+2+3+4) + "
          "(101+102+103+104) == 420. 20 means b was dropped and a was duplicated; 820 means the "
          "opposite. Got " + fullPrec(svSum));
  }

  // ── (viii) `sample` is SEEDED, exact, and not a head/tail shortcut. ───────
  // Four assertions, each aimed at a different wrong implementation:
  //   exact count  -> a sample that rounded the other way, or returned a range
  //   same-seed    -> a global/time-seeded RNG (the failure that makes a
  //                   replication package irreproducible and reports nothing)
  //   not-head/tail-> a "sample" that just kept the first or last k rows
  //   seed matters -> a handler that ACCEPTS `set seed` and ignores it
  // The fingerprint is sum(id^3), not sum(id): distinct 50-subsets of 1..100
  // collide on their plain sum often enough to make the last check flaky, and
  // essentially never on the cube.
  {
    const std::string kMk100 =
        "clear\nset obs 100\ngen double id = _n\ngen double w = id*id*id\n";
    auto sampleSum = [&](int seed, double& n) {
      piet::SessionState s(workdir);
      s.eval.cwd = workdir;
      s.cwd = workdir;  // resolveUserPath reads THIS field (handlers.cpp:2040).
      auto r = exec(kMk100 + "set seed " + std::to_string(seed) + "\nsample 50\n", s);
      if (!firstError(r.blocks).is_null()) {
        n = std::nan("");
        return std::nan("");
      }
      n = nRows(s);
      return runR(s, "summarize w", "sum");
    };
    double nA = 0.0, nB = 0.0, nC = 0.0;
    const double sumA = sampleSum(7, nA);
    const double sumB = sampleSum(7, nB);
    const double sumC = sampleSum(8, nC);
    check(nA == 50.0,
          "AER-RESHAPE (viii): `sample 50` over 100 rows keeps EXACTLY 50 -- an exact count, not a "
          "range: `sample #` is a percentage and round-half-up of 100*50/100 is 50 on the nose. Got "
          + fullPrec(nA));
    check(nB == 50.0 && sumB == sumA && !std::isnan(sumA),
          "AER-RESHAPE (viii): ...and the SAME SEED twice gives the SAME ROWS, bit-exact. This is "
          "the property the Philox-keyed design exists for: a global or time-seeded generator "
          "passes every other check in this leg and makes every replication package that calls "
          "`sample` irreproducible, silently. Got " + fullPrec(sumA) + " vs " + fullPrec(sumB));
    check(sumA != 1625625.0,
          "AER-RESHAPE (viii): ...and it is not the FIRST 50 rows (whose w sums to 1625625). A "
          "`sample` that returned the head is deterministic, has the right count, and is not a "
          "sample. Got " + fullPrec(sumA));
    check(sumA != 23876875.0,
          "AER-RESHAPE (viii): ...nor the LAST 50 (23876875). Got " + fullPrec(sumA));
    check(!std::isnan(sumC) && sumC != sumA,
          "AER-RESHAPE (viii): ...and a DIFFERENT seed gives a different draw, so `set seed` is "
          "actually read rather than accepted and dropped -- which is how a handler passes the "
          "determinism check above while being deterministic for the wrong reason. Got seed7 " +
              fullPrec(sumA) + " vs seed8 " + fullPrec(sumC));
  }

  // ── (ix) `bsample, cluster(g)` resamples CLUSTERS, whole. ────────────────
  // The clusters are deliberately RAGGED (sizes 1,2,3,4). The load-bearing
  // assertion is the modulus: whatever survives of cluster k must be a whole
  // multiple of k, because clusters are drawn intact. A `bsample` that
  // resampled ROWS and merely carried g along -- the single most likely wrong
  // implementation, and one that gets the row count, the value domain and the
  // cluster count all right -- produces counts that are not multiples, and
  // this is the only check here that sees it.
  {
    const std::string kMkG =
        "clear\nset obs 10\ngen double g = 1\nreplace g = 2 in 2/3\n"
        "replace g = 3 in 4/6\nreplace g = 4 in 7/10\n";
    auto draw = [&](int seed, std::vector<double>& per, double& ncMin, double& ncMax) {
      piet::SessionState s(workdir);
      s.eval.cwd = workdir;
      s.cwd = workdir;  // resolveUserPath reads THIS field (handlers.cpp:2040).
      auto r = exec(kMkG + "set seed " + std::to_string(seed) +
                        "\nbsample, cluster(g) idcluster(nc)\n",
                    s);
      per.clear();
      ncMin = std::nan("");
      ncMax = std::nan("");
      if (!firstError(r.blocks).is_null()) return std::nan("");
      for (int k = 1; k <= 4; ++k) per.push_back(countIf(s, "g == " + std::to_string(k)));
      const double outOfDomain = countIf(s, "g < 1 | g > 4");
      (void)piet::dispatch("summarize nc", s);
      ncMin = rOf(s, "min");
      ncMax = rOf(s, "max");
      if (outOfDomain != 0.0) return -1.0;
      return nRows(s);
    };
    std::vector<double> perA, perB;
    double ncMinA = 0.0, ncMaxA = 0.0, ncMinB = 0.0, ncMaxB = 0.0;
    const double nA = draw(11, perA, ncMinA, ncMaxA);
    const double nB = draw(11, perB, ncMinB, ncMaxB);
    check(nA >= 4.0 && nA <= 16.0,
          "AER-RESHAPE (ix): `bsample, cluster(g)` over four clusters of sizes 1,2,3,4 draws FOUR "
          "clusters with replacement, so the result holds between 4 and 16 rows. Got " +
              fullPrec(nA));
    check(nA != -1.0,
          "AER-RESHAPE (ix): ...and every surviving g value is one of the original four -- a "
          "resample that renumbered the cluster variable instead of copying it destroys the join "
          "key every clustered SE downstream needs");
    bool multiples = perA.size() == 4;
    std::string perTxt;
    for (size_t k = 0; k < perA.size(); ++k) {
      const double sz = static_cast<double>(k + 1);
      perTxt += (k ? ", " : "") + std::to_string(k + 1) + ":" + fullPrec(perA[k]);
      if (std::isnan(perA[k]) || std::fmod(perA[k], sz) != 0.0) multiples = false;
    }
    check(multiples,
          "AER-RESHAPE (ix): ...and each cluster survives in WHOLE COPIES: the rows left carrying "
          "g==k number 0, k, 2k, ... because a cluster bootstrap draws the cluster, not its rows. "
          "This is the check that separates a real cluster bootstrap from one that resampled rows "
          "and kept g as a passenger -- that version gets the row count, the value domain and the "
          "cluster count right and is wrong in the only way that matters. Got counts {" + perTxt +
              "}");
    double perSum = 0.0;
    for (double v : perA) perSum += v;
    check(perSum == nA,
          "AER-RESHAPE (ix): ...and those four counts account for every row in the result, so no "
          "row arrived with a missing or invented cluster. Got " + fullPrec(perSum) + " vs _N " +
              fullPrec(nA));
    check(ncMinA == 1.0 && ncMaxA == 4.0,
          "AER-RESHAPE (ix): ...and `idcluster(nc)` numbers the DRAWS 1..4, not the original "
          "cluster ids -- that renumbering is the whole point of the option, because the same "
          "cluster drawn twice must be two different units to the estimator downstream. Got min " +
              fullPrec(ncMinA) + " max " + fullPrec(ncMaxA));
    check(nB == nA && perB == perA,
          "AER-RESHAPE (ix): ...and the same seed draws the same clusters twice. Got _N " +
              fullPrec(nA) + " vs " + fullPrec(nB));
  }

  // ── (x) `drawnorm` reproduces the requested correlation. ─────────────────
  {
    const std::string kDraw =
        "clear\nmatrix C = (1, 0.6 \\ 0.6, 1)\ndrawnorm u v, n(2000) corr(C) seed(3)\n";
    piet::SessionState s(workdir);
    s.eval.cwd = workdir;
    s.cwd = workdir;  // resolveUserPath reads THIS field (handlers.cpp:2040).
    auto r = exec(kDraw, s);
    check(firstError(r.blocks).is_null(),
          "AER-RESHAPE (x): `drawnorm u v, n(2000) corr(C) seed(3)` runs clean with no data in "
          "memory. Got `" + errText(firstError(r.blocks)) + "`");
    check(nRows(s) == 2000.0,
          "AER-RESHAPE (x): ...and n() is the row count, exactly. Got " + fullPrec(nRows(s)));
    (void)piet::dispatch("summarize u", s);
    const double mu = rOf(s, "mean");
    const double sdu = rOf(s, "sd");
    check(std::fabs(mu) < 0.1,
          "AER-RESHAPE (x): ...u has mean ~0 (default means()). At n=2000 the standard error of "
          "the mean is ~0.022, so 0.1 is a four-sigma band and NOT a cushion hiding a shifted "
          "distribution. Got " + fullPrec(mu));
    check(std::fabs(sdu - 1.0) < 0.1,
          "AER-RESHAPE (x): ...and sd ~1 (default sds()). A Cholesky applied to the wrong side, or "
          "to the covariance when a correlation was given, scales this away from 1. Got " +
              fullPrec(sdu));
    const double rho = runR(s, "correlate u v", "rho");
    check(!std::isnan(rho) && std::fabs(rho - 0.6) < 0.1,
          "AER-RESHAPE (x): ...and the SAMPLE correlation is the requested 0.6. This is the only "
          "check that reaches the Cholesky itself: an identity L (or a transposed one) leaves two "
          "perfectly good standard normals with rho ~ 0, and every other assertion in this leg "
          "passes. Got " + fullPrec(rho));
    piet::SessionState s2(workdir);
    s2.eval.cwd = workdir;
    s2.cwd = workdir;  // resolveUserPath reads THIS field (handlers.cpp:2040).
    (void)exec(kDraw, s2);
    const double rho2 = runR(s2, "correlate u v", "rho");
    check(!std::isnan(rho2) && rho2 == rho,
          "AER-RESHAPE (x): ...and `seed(3)` twice draws the IDENTICAL sample -- compared "
          "bit-exact, not within a band, because the same seed must give the same numbers and not "
          "merely the same distribution. Got " + fullPrec(rho) + " vs " + fullPrec(rho2));
  }

  // ── (xi) `notes` writes characteristics, and .dta round-trips them free. ──
  {
    piet::SessionState s(workdir);
    s.eval.cwd = workdir;
    s.cwd = workdir;  // resolveUserPath reads THIS field (handlers.cpp:2040);
    // eval.cwd alone puts rs_notes.dta in the PROCESS cwd -- the repo root --
    // and the round trip below then reads a file this leg never wrote.
    auto hasChar = [](piet::SessionState& ss, const std::string& vn, const std::string& cn,
                      const std::string& val) {
      for (const auto& c : ss.characteristics)
        if (c.varname == vn && c.charname == cn && c.value == val) return true;
      return false;
    };
    auto nNotes = [](piet::SessionState& ss) {
      int n = 0;
      for (const auto& c : ss.characteristics)
        if (c.charname.rfind("note", 0) == 0) ++n;
      return n;
    };
    auto r = exec("clear\nset obs 4\ngen double x = _n\n"
                  "notes: hi\nnotes x: there\n",
                  s);
    check(firstError(r.blocks).is_null(),
          "AER-RESHAPE (xi): `notes: hi` and `notes x: there` run clean. Got `" +
              errText(firstError(r.blocks)) + "`");
    check(hasChar(s, "_dta", "note1", "hi"),
          "AER-RESHAPE (xi): the dataset note lands as _dta[note1] == \"hi\" -- Stata's own "
          "characteristic spelling, which is what makes it survive a .dta write with no new code");
    check(hasChar(s, "x", "note1", "there"),
          "AER-RESHAPE (xi): ...and the VARIABLE note lands as x[note1], in the variable's own "
          "namespace. A handler with only the dataset store puts both under _dta and `notes list` "
          "still renders something plausible");
    check(hasChar(s, "_dta", "note0", "1") && hasChar(s, "x", "note0", "1"),
          "AER-RESHAPE (xi): ...each with its note0 COUNTER set to 1. note0 is what the next "
          "`notes:` reads to pick its number; a missing counter makes note 2 overwrite note 1, "
          "which loses data and reports nothing");
    check(nNotes(s) == 4,
          "AER-RESHAPE (xi): ...and exactly four note characteristics exist, so nothing was "
          "written twice. Got " + std::to_string(nNotes(s)));
    auto r2 = exec("save \"rs_notes.dta\", replace\nuse \"rs_notes.dta\", clear\n", s);
    check(firstError(r2.blocks).is_null(),
          "AER-RESHAPE (xi/roundtrip): save -> use runs clean. Got `" +
              errText(firstError(r2.blocks)) + "`");
    check(hasChar(s, "_dta", "note1", "hi") && hasChar(s, "x", "note1", "there") &&
              nNotes(s) == 4,
          "AER-RESHAPE (xi/roundtrip): ...and BOTH notes came back off disk. This is the claim "
          "the design rests on -- characteristics are written verbatim by the .dta writer and "
          "restored by `use`, so notes persist for free. If they do not, `notes` is a "
          "session-only feature wearing a persistent feature's name, and no in-session check sees "
          "it. Got " + std::to_string(nNotes(s)) + " note characteristics after the round trip");
  }

  // ── (xii) `recast` is METADATA. The frame must not move. ─────────────────
  {
    piet::SessionState s(workdir);
    s.eval.cwd = workdir;
    s.cwd = workdir;  // resolveUserPath reads THIS field (handlers.cpp:2040).
    auto r = exec("clear\nset obs 6\ngen double x = _n / 3\n", s);
    check(firstError(r.blocks).is_null(),
          "AER-RESHAPE (xii): setup runs clean. Got `" + errText(firstError(r.blocks)) + "`");
    (void)piet::dispatch("summarize x", s);
    const double meanBefore = rOf(s, "mean");
    const std::string hbinBefore =
        s.currentHbin().has_value() ? *s.currentHbin() : std::string("<none>");
    auto r2 = exec("recast double x\n", s);
    check(firstError(r2.blocks).is_null(),
          "AER-RESHAPE (xii): `recast double x` runs clean. Got `" +
              errText(firstError(r2.blocks)) + "`");
    check(dtypeOf(s, "x") == "double",
          "AER-RESHAPE (xii): ...and the declared storage type IS `double` afterwards -- the only "
          "observable effect the command has, and the one a .dta write carries out to Stata. Got "
          "dtype `" + dtypeOf(s, "x") + "`");
    const std::string hbinAfter =
        s.currentHbin().has_value() ? *s.currentHbin() : std::string("<none>");
    check(hbinAfter == hbinBefore,
          "AER-RESHAPE (xii): ...and the FRAME DID NOT MOVE: currentHbin is the same file it was. "
          "recast is metadata-only by contract, so a handler that round-tripped the column through "
          "a CSV to `change the type` would land here with a new hbin -- and, if that CSV were "
          "written at anything under 17 digits, with 1/3 re-encoded on the way, which the mean "
          "check below then also catches. (This used to cite BUG-406 as a 9 s.f. loss inside "
          "`cobra convert`; REDIAGNOSED 2026-09-06 -- the storage is exact, the nine digits were "
          "`display %fmt <varref>`, and this leg reads r(mean), not a display.) "
          "Got `" + hbinAfter + "` vs `" + hbinBefore + "`");
    (void)piet::dispatch("summarize x", s);
    const double meanAfter = rOf(s, "mean");
    check(!std::isnan(meanBefore) && meanAfter == meanBefore,
          "AER-RESHAPE (xii): ...and the VALUES are bit-identical across the recast. x = _n/3 is "
          "chosen for that: it is not representable in binary, so any re-encoding shows up here. "
          "Got " + fullPrec(meanAfter) + " vs " + fullPrec(meanBefore));
  }

  // ── (xiii) three refusals -- by name, and having changed nothing. ────────
  {
    // (a) `split` on a NUMERIC column. Stata's split is a string operation;
    // silently stringifying the number would produce a column that looks right
    // and compares wrong.
    piet::SessionState s(workdir);
    s.eval.cwd = workdir;
    s.cwd = workdir;  // resolveUserPath reads THIS field (handlers.cpp:2040).
    (void)exec("clear\nset obs 4\ngen double n = _n\n", s);
    const size_t varsBefore = varNames(s).size();
    auto r = exec("split n, parse(\"-\") gen(zz)\n", s);
    auto err = firstError(r.blocks);
    check(!err.is_null(),
          "AER-RESHAPE (xiii/a): `split` on a NUMERIC variable is an ERROR. Coercing it to text "
          "and splitting that is the silently-wrong path: the parts exist, they are strings, and "
          "every comparison against them fails for a reason nothing reports");
    check(has(errText(err), "split"),
          "AER-RESHAPE (xiii/a): ...and the message names the command. Got `" + errText(err) + "`");
    check(varNames(s).size() == varsBefore,
          "AER-RESHAPE (xiii/a): ...having created NO columns. A refusal reached after the first "
          "`setcol --new` leaves a half-built stub set behind, and the next run of the same "
          "do-file then fails on a name collision instead of on the real cause. Got " +
              std::to_string(varNames(s).size()) + " variables vs " + std::to_string(varsBefore));

    // (b) `xpose` without `clear`. The frame is destroyed by a transpose, so
    // Stata makes the caller say so.
    piet::SessionState s2(workdir);
    s2.eval.cwd = workdir;
    s2.cwd = workdir;  // resolveUserPath reads THIS field (handlers.cpp:2040).
    (void)exec("clear\nset obs 3\ngen double a = _n\ngen double b = _n*10\n", s2);
    auto r2 = exec("xpose\n", s2);
    auto err2 = firstError(r2.blocks);
    check(!err2.is_null(),
          "AER-RESHAPE (xiii/b): `xpose` without `clear` is an ERROR -- the option is Stata's "
          "confirmation that the caller knows the dataset is about to be replaced");
    check(has(errText(err2), "clear"),
          "AER-RESHAPE (xiii/b): ...and the message names `clear`, so the fix is in the message "
          "rather than in the manual. Got `" + errText(err2) + "`");
    check(nRows(s2) == 3.0 && varNames(s2).size() == 2,
          "AER-RESHAPE (xiii/b): ...and the frame is UNTOUCHED: still 3 rows and 2 variables. A "
          "refusal raised after the CSV round trip has already replaced the data, which is the "
          "worst version of this defect -- the command reports failure and did the thing. Got " +
              fullPrec(nRows(s2)) + " rows, " + std::to_string(varNames(s2).size()) + " variables");

    // (c) `sample ..., by()` -- an option this build does not implement. It
    // must be refused as an OPTION, not accepted and dropped.
    piet::SessionState s3(workdir);
    s3.eval.cwd = workdir;
    s3.cwd = workdir;  // resolveUserPath reads THIS field (handlers.cpp:2040).
    (void)exec("clear\nset obs 20\ngen double g = 1\nreplace g = 2 in 11/20\n", s3);
    auto r3 = exec("sample 10, by(g)\n", s3);
    auto err3 = firstError(r3.blocks);
    check(!err3.is_null(),
          "AER-RESHAPE (xiii/c): `sample 10, by(g)` is REFUSED. by() changes the ANSWER -- it "
          "makes the draw stratified -- so accepting and ignoring it returns a plain sample under "
          "a stratified sample's name, with rc 0 and no way to tell");
    check(errField(err3, "code") == "unsupported_option",
          "AER-RESHAPE (xiii/c): ...under `unsupported_option`, not `unsupported_command`: the "
          "command exists and one option does not, and a caller branching on the code is entitled "
          "to that difference. Got `" + errField(err3, "code") + "`");
    check(rcOf(err3) == "198",
          "AER-RESHAPE (xiii/c): ...at r(198), Stata's option error. Asserted separately from the "
          "code because a refusal built with the default engine_error code arrives as rc 1 and "
          "every do-file branching on 198 takes the wrong branch. Got r(" + rcOf(err3) + ")");
    check(nRows(s3) == 20.0,
          "AER-RESHAPE (xiii/c): ...and it sampled NOTHING. The reject net has to fire before the "
          "handler, or the user gets a refusal message and a frame that has already lost half its "
          "rows. Got " + fullPrec(nRows(s3)));
  }

  fs::remove_all(workdir, ec);
}

// AER-SCOPE1 bundle G (IO-TEXT). The older text I/O verbs plus `putexcel`.
//
// WHAT MAKES THIS BUNDLE DIFFERENT FROM EVERY OTHER SELFTEST IN THIS FILE:
// nine of the thirteen rows exist to put BYTES ON DISK. `rc == 0` is therefore
// the weakest possible assertion here -- a handler that parsed the line, opened
// no file and returned a clean mutation result passes an rc check on every one
// of them. Every leg below reads the artifact back: the separator byte out of
// `outsheet`, the absence of a header line out of `outfile`, the exact echo
// sentence out of `saveold`, and -- leg (vii) -- the CELL VALUES out of the
// workbook `putexcel` wrote, through `xlsx::read`, which is the only check in
// the tree that can tell "wrote a workbook" from "wrote a workbook Excel and
// our own reader agree about".
//
// The other standing trap this file has paid for twice (bundle E, then F):
// `resolveUserPath` (handlers.cpp:2040) reads `SessionState::cwd`, NOT
// `SessionState::eval.cwd`. A session seeded with only the latter writes every
// `using` file into the PROCESS cwd -- the repo root -- and each leg then reads
// a file it never wrote. `seed()` below sets both, and every session in this
// function goes through it.
void testAerIoText() {
  std::printf("[selftest] --- AER-SCOPE1 bundle G: insheet/outsheet/infile/infix/outfile + "
              "saveold/putexcel/filefilter/copy + the four refusals ---\n");
  namespace fs = std::filesystem;
  std::string workdir = (fs::temp_directory_path() / "piet_native_selftest_aeriotext").u8string();
  std::error_code ec;
  fs::remove_all(workdir, ec);
  fs::create_directories(workdir, ec);

  auto exec = [](const std::string& src, piet::SessionState& session) {
    return piet::doexec::executeDoSource(src, session, piet::dispatch);
  };
  // The one place `cwd` is seeded. See the header: eval.cwd alone is the
  // sixteen-failures-for-one-reason bug this bundle cannot afford to repeat,
  // because unlike E and F almost every leg here names a file.
  auto seed = [&](piet::SessionState& s) {
    s.eval.cwd = workdir;
    s.cwd = workdir;  // resolveUserPath reads THIS field (handlers.cpp:2040).
  };
  // NULL rather than a throw when there is no error block -- the BUG-129 trap:
  // check()'s message argument is built EAGERLY, on the passing path too, so a
  // `value()` on nothing would abort the whole run instead of failing one leg.
  auto firstError = [](const nlohmann::ordered_json& blocks) -> nlohmann::ordered_json {
    for (const auto& b : blocks)
      if (b.is_object() && b.value("type", std::string()) == "error") return b;
    return nlohmann::ordered_json();
  };
  auto errText = [](const nlohmann::ordered_json& e) {
    return e.is_object() ? e.value("message", std::string()) : std::string("<none>");
  };
  auto errField = [](const nlohmann::ordered_json& e, const std::string& f) {
    return e.is_object() ? e.value(f, std::string()) : std::string("<none>");
  };
  auto rcOf = [](const nlohmann::ordered_json& e) {
    return e.is_object() ? piet::eval::coarseRc(e) : std::string("<none>");
  };
  auto displays = [](const auto& blocks) {
    std::vector<std::string> v;
    for (const auto& b : blocks)
      if (b.is_object() && b.value("type", std::string()) == "display")
        v.push_back(b.value("text", std::string()));
    return v;
  };
  // %.17g, never std::to_string: six decimals renders two doubles that differ
  // in the 8th digit as the same text, and a failure report that cannot be
  // read is worse than no report (testAerTables' own note).
  auto fullPrec = [](double v) {
    char buf[48];
    std::snprintf(buf, sizeof(buf), "%.17g", v);
    return std::string(buf);
  };
  auto has = [](const std::string& hay, const std::string& needle) {
    return hay.find(needle) != std::string::npos;
  };
  auto slurp = [](const std::string& p) {
    std::ifstream f(cecon::to_native_path(p), std::ios::binary);
    return std::string((std::istreambuf_iterator<char>(f)), std::istreambuf_iterator<char>());
  };
  auto spit = [](const std::string& p, const std::string& bytes) {
    std::ofstream f(cecon::to_native_path(p), std::ios::binary | std::ios::trunc);
    f << bytes;
  };
  auto at = [&](const std::string& rel) { return (fs::path(workdir) / rel).u8string(); };
  auto varNames = [](piet::SessionState& s) {
    std::vector<std::string> out;
    const nlohmann::ordered_json blocks = piet::dispatch("describe", s);
    for (const auto& b : blocks)
      if (b.is_object() && b.value("type", std::string()) == "describe" && b.contains("variables"))
        for (const auto& v : b["variables"]) out.push_back(v.value("name", std::string()));
    return out;
  };
  auto hasName = [](const std::vector<std::string>& v, const std::string& n) {
    return std::find(v.begin(), v.end(), n) != v.end();
  };
  auto joinNames = [](const std::vector<std::string>& v) {
    std::string s;
    for (const auto& n : v) { if (!s.empty()) s += " "; s += n; }
    return s.empty() ? std::string("<none>") : s;
  };
  // describe's per-variable `dtype` IS varMeta.stataType when one is recorded
  // and the "str#"/"float" default otherwise -- which is exactly what the
  // declared-type halves of legs (iii) and (iv) need.
  auto dtypeOf = [](piet::SessionState& s, const std::string& name) -> std::string {
    const nlohmann::ordered_json blocks = piet::dispatch("describe", s);
    for (const auto& b : blocks)
      if (b.is_object() && b.value("type", std::string()) == "describe" && b.contains("variables"))
        for (const auto& v : b["variables"])
          if (v.value("name", std::string()) == name) return v.value("dtype", std::string());
    return std::string("<absent>");
  };
  // r() is REPLACED wholesale by the next r-class command (macros.cpp's
  // captureRFromBlock), so every read happens immediately after the command
  // that published it -- never two commands later.
  auto rOf = [](piet::SessionState& s, const char* key) -> double {
    const double* p = s.eval.rValues.find(key);
    return p ? *p : std::nan("");
  };
  auto runR = [&](piet::SessionState& s, const std::string& cmd, const char* key) -> double {
    (void)piet::dispatch(cmd, s);
    return rOf(s, key);
  };
  auto nRows = [&](piet::SessionState& s) { return runR(s, "count", "N"); };
  auto countIf = [&](piet::SessionState& s, const std::string& expr) {
    return runR(s, "count if " + expr, "N");
  };
  // Bounds-safe cell read: xlsx::read pads rows rectangular, but a defective
  // writer can produce a SHORT sheet, and an out-of-range [] there would abort
  // the run instead of failing the one check that noticed.
  auto cellAt = [](const piet::xlsx::Sheet& sh, size_t r0, size_t c0) -> piet::xlsx::Cell {
    if (r0 >= sh.rows.size() || c0 >= sh.rows[r0].size()) return piet::xlsx::Cell();
    return sh.rows[r0][c0];
  };
  auto readBook = [](const std::string& p, piet::xlsx::Sheet& out) -> bool {
    try { out = piet::xlsx::read(p, /*firstRowIsHeader=*/false); }
    catch (const std::exception&) { return false; }
    return true;
  };

  // ── (i) insheet applies STATA'S naming rules, which is the whole reason it
  // is not a plain alias for `import delimited`. ─────────────────────────────
  {
    piet::SessionState s(workdir);
    seed(s);
    spit(at("is_case.csv"), "ID,Val\n1,2\n3,4\n");
    auto r = exec("insheet using \"is_case.csv\", clear\n", s);
    check(firstError(r.blocks).is_null(),
          "AER-IOTEXT (i): `insheet using \"is_case.csv\", clear` runs clean. Got `" +
              errText(firstError(r.blocks)) + "`");
    const std::vector<std::string> vn = varNames(s);
    check(hasName(vn, "id") && hasName(vn, "val"),
          "AER-IOTEXT (i): the header `ID,Val` lands as LOWERCASE {id,val}. This is the leg that "
          "separates a real insheet from a one-line alias to `import delimited`: the loader keeps "
          "the header's case, Stata's insheet lowercases it, and every downstream `summarize val` "
          "in a ported do-file then fails with `val not found` while the load itself reported rc "
          "0. Got {" + joinNames(vn) + "}");
    check(nRows(s) == 2.0,
          "AER-IOTEXT (i): ...over 2 data rows, so row 1 was consumed as the HEADER and not as "
          "data. A shim that passed `nonames` through (or failed to pass `names`) reads 3 rows "
          "with the header sitting in them as text. Got " + fullPrec(nRows(s)));
    check(countIf(s, "val == 4") == 1.0,
          "AER-IOTEXT (i): ...and the VALUES arrived: exactly one row has val == 4. Names and a "
          "row count are both true of a load that renamed the columns of the wrong file. Got " +
              fullPrec(countIf(s, "val == 4")));
  }
  {
    piet::SessionState s(workdir);
    seed(s);
    auto r = exec("insheet using \"is_case.csv\", clear case\n", s);
    check(firstError(r.blocks).is_null(),
          "AER-IOTEXT (i/case): `insheet ..., case` runs clean. Got `" +
              errText(firstError(r.blocks)) + "`");
    const std::vector<std::string> vn = varNames(s);
    check(hasName(vn, "ID") && hasName(vn, "Val"),
          "AER-IOTEXT (i/case): `case` PRESERVES the header's capitalisation -- {ID,Val}. Without "
          "this check the option can be accepted and dropped, which is rc 0 with the names the "
          "author explicitly asked to keep silently folded away. Got {" + joinNames(vn) + "}");
  }
  {
    // Stata's own auto-detection: if every field of the first row parses as a
    // number, that row is DATA and the variables are v1..vk.
    piet::SessionState s(workdir);
    seed(s);
    spit(at("is_noh.csv"), "1,2\n3,4\n");
    auto r = exec("insheet using \"is_noh.csv\", clear\n", s);
    check(firstError(r.blocks).is_null(),
          "AER-IOTEXT (i/auto-nonames): a headerless numeric file loads clean. Got `" +
              errText(firstError(r.blocks)) + "`");
    const std::vector<std::string> vn = varNames(s);
    check(hasName(vn, "v1") && hasName(vn, "v2"),
          "AER-IOTEXT (i/auto-nonames): a first row whose every field is a NUMBER is data, not a "
          "header, so the variables are {v1,v2}. Got {" + joinNames(vn) + "}");
    check(nRows(s) == 2.0,
          "AER-IOTEXT (i/auto-nonames): ...and BOTH rows survive. This is the half that matters: "
          "without the auto-detection the first row is eaten as a header, the frame silently "
          "loses an observation, and every mean computed from it is wrong by 1/N with no error "
          "anywhere. Got " + fullPrec(nRows(s)));
  }
  {
    // Plan edge case: a RAGGED file. This leg used to assert an error, which
    // pinned the defect: StataBE's insheet WIDENS (BUG-414 -- `a,b,c` over
    // `4,5` and `6,7,8,9,10` reads a b c v4 v5, 3 obs, rc 0). The unacceptable
    // outcome is still the quiet one -- the extra field dropped.
    piet::SessionState s(workdir);
    seed(s);
    spit(at("is_ragged.csv"), "a,b\n1,2\n3,4,5\n");
    auto r = exec("insheet using \"is_ragged.csv\", clear\n", s);
    check(firstError(r.blocks).is_null(),
          "AER-IOTEXT (i/ragged): a row with MORE fields than the header loads, as StataBE's "
          "insheet does (BUG-414). Got `" + errText(firstError(r.blocks)) + "`");
    const std::vector<std::string> vn = varNames(s);
    check(vn.size() == 3 && hasName(vn, "a") && hasName(vn, "b") && hasName(vn, "v3"),
          "AER-IOTEXT (i/ragged): ...widened by the extra field into v3 -- {a,b,v3}. Got {" +
              joinNames(vn) + "}");
    check(nRows(s) == 2.0 && countIf(s, "v3 == 5") == 1.0 && countIf(s, "missing(v3)") == 1.0,
          "AER-IOTEXT (i/ragged): ...over 2 rows, the extra 5 kept in v3 and the short row's v3 "
          "missing. Dropping the 5 is the frame that is quietly wrong. Got N " +
              fullPrec(nRows(s)) + ", v3==5 in " + fullPrec(countIf(s, "v3 == 5")));
  }

  // ── (ii) outsheet's default separator is a TAB, and that is a byte. ───────
  {
    piet::SessionState s(workdir);
    seed(s);
    auto r = exec("clear\nset obs 2\ngen double a = _n\ngen double b = _n*2\n"
                  "outsheet using \"os.tsv\", replace\n",
                  s);
    check(firstError(r.blocks).is_null(),
          "AER-IOTEXT (ii): `outsheet using \"os.tsv\", replace` runs clean. Got `" +
              errText(firstError(r.blocks)) + "`");
    const std::string tsv = slurp(at("os.tsv"));
    check(!tsv.empty(),
          "AER-IOTEXT (ii): ...and left BYTES on disk. A handler that parsed the line, produced a "
          "mutation result and opened no file returns rc 0 and writes nothing -- the defect this "
          "whole bundle's tests exist for");
    check(has(tsv, "a\tb"),
          "AER-IOTEXT (ii): the header row is TAB-separated (`a\\tb`). outsheet's default "
          "delimiter is a tab and `export delimited`'s is a comma, so a shim that forwarded "
          "without synthesising `delimiter(\"\\t\")` writes a comma file under a .tsv name: every "
          "value is correct, every field boundary is wrong, and nothing returns an error. Got `" +
              tsv.substr(0, 32) + "`");
    check(!has(tsv, ","),
          "AER-IOTEXT (ii): ...and no comma appears ANYWHERE in the file, so the default was not "
          "merely tab-ish in the header. Got `" + tsv.substr(0, 32) + "`");
    check(has(tsv, "a") && has(tsv, "b"),
          "AER-IOTEXT (ii): ...and the variable NAMES are present: outsheet writes a header by "
          "default (`nonames` is the refusal in this build, not the default)");
  }
  {
    piet::SessionState s(workdir);
    seed(s);
    auto r = exec("clear\nset obs 2\ngen double a = _n\ngen double b = _n*2\n"
                  "outsheet using \"os.csv\", replace comma\n",
                  s);
    check(firstError(r.blocks).is_null(),
          "AER-IOTEXT (ii/comma): `outsheet ..., comma` runs clean. Got `" +
              errText(firstError(r.blocks)) + "`");
    const std::string csv = slurp(at("os.csv"));
    check(has(csv, "a,b"),
          "AER-IOTEXT (ii/comma): `comma` overrides the tab default (`a,b`). Paired with the leg "
          "above this is what proves the separator is CHOSEN rather than hardcoded either way: "
          "one of the two checks fails for any handler that ignores the option. Got `" +
              csv.substr(0, 32) + "`");
    check(!has(csv, "\t"),
          "AER-IOTEXT (ii/comma): ...and no tab survives into the comma file. Got `" +
              csv.substr(0, 32) + "`");
  }

  // ── (iii) infix reads FIXED COLUMNS, 1-based and inclusive. ───────────────
  {
    piet::SessionState s(workdir);
    seed(s);
    spit(at("ix.dat"), "1990abc\n1991def\n");
    auto r = exec("infix int year 1-4 str3 code 5-7 using \"ix.dat\", clear\n", s);
    check(firstError(r.blocks).is_null(),
          "AER-IOTEXT (iii): `infix int year 1-4 str3 code 5-7 using \"ix.dat\", clear` runs "
          "clean. Got `" + errText(firstError(r.blocks)) + "`");
    check(nRows(s) == 2.0,
          "AER-IOTEXT (iii): two records, one per line. Got " + fullPrec(nRows(s)));
    check(countIf(s, "year == 1990") == 1.0 && countIf(s, "year == 1991") == 1.0,
          "AER-IOTEXT (iii): the column range 1-4 is 1-BASED and INCLUSIVE, so year is {1990,1991} "
          "and not {199,199} (0-based read) or {990,991} (exclusive lower bound). Both off-by-one "
          "readings produce a perfectly plausible integer column that no rc, no row count and no "
          "missing-value check can distinguish from the right one. Got " +
              fullPrec(countIf(s, "year == 1990")) + " rows at 1990, " +
              fullPrec(countIf(s, "year == 1991")) + " at 1991");
    check(countIf(s, "code == \"abc\"") == 1.0,
          "AER-IOTEXT (iii): ...and the STRING field at 5-7 is \"abc\", so the second range was "
          "measured from the line rather than from the remainder after the first field. Got " +
              fullPrec(countIf(s, "code == \"abc\"")));
    check(dtypeOf(s, "code").rfind("str", 0) == 0,
          "AER-IOTEXT (iii): ...carrying its DECLARED type (str3). A reader that ignored the type "
          "prefix and let the sniffer decide reads `abc` as numeric, silently produces a column "
          "of missings, and reports two rows loaded. Got dtype `" + dtypeOf(s, "code") + "`");
  }
  {
    // Edge case from the plan: a range past the end of the line is MISSING,
    // not an error and not garbage from the next record.
    piet::SessionState s(workdir);
    seed(s);
    spit(at("ix_short.dat"), "12\n34\n");
    auto r = exec("infix int a 1-2 int b 5-6 using \"ix_short.dat\", clear\n", s);
    check(firstError(r.blocks).is_null(),
          "AER-IOTEXT (iii/short): a range past the end of the line is not an ERROR. Got `" +
              errText(firstError(r.blocks)) + "`");
    check(countIf(s, "missing(b)") == 2.0,
          "AER-IOTEXT (iii/short): ...it is MISSING, in both rows. The alternative a naive "
          "substring reader produces is a wrapped read that pulls bytes from the NEXT record, "
          "which fabricates data and looks entirely healthy. Got " +
              fullPrec(countIf(s, "missing(b)")) + " missing");
  }

  // ── (iv) infile is FREE FORMAT: the record boundary is the varlist length,
  // not the line break. ─────────────────────────────────────────────────────
  {
    piet::SessionState s(workdir);
    seed(s);
    spit(at("if.raw"), "\"a\" 1 \"b\" 2\n");
    auto r = exec("infile str3 s x using \"if.raw\", clear\n", s);
    check(firstError(r.blocks).is_null(),
          "AER-IOTEXT (iv): `infile str3 s x using \"if.raw\", clear` runs clean. Got `" +
              errText(firstError(r.blocks)) + "`");
    check(nRows(s) == 2.0,
          "AER-IOTEXT (iv): FOUR values over a two-variable varlist are TWO observations, even "
          "though the source is one line. Stata's free-format reader ignores line breaks entirely "
          "and wraps every `varlist.size()` values; a reader that treated one line as one record "
          "loads a single row and drops half the file with rc 0. Got " + fullPrec(nRows(s)));
    check(countIf(s, "x == 2") == 1.0,
          "AER-IOTEXT (iv): ...and the second record's numeric field is 2, so the wrap put the "
          "values in the right slots rather than merely counting to the right total. Got " +
              fullPrec(countIf(s, "x == 2")));
    check(countIf(s, "s == \"b\"") == 1.0,
          "AER-IOTEXT (iv): ...and the QUOTED string token arrived without its quotes as \"b\". A "
          "tokenizer that split on whitespace alone stores `\"b\"` with the delimiters embedded, "
          "which compares unequal to every string literal the user will ever write. Got " +
              fullPrec(countIf(s, "s == \"b\"")));
    check(dtypeOf(s, "s").rfind("str", 0) == 0,
          "AER-IOTEXT (iv): ...under its declared type. Got dtype `" + dtypeOf(s, "s") + "`");
  }

  // ── (v) outfile has NO HEADER and quotes its strings. ────────────────────
  {
    piet::SessionState s(workdir);
    seed(s);
    const std::string kMake =
        "clear\nset obs 2\ngen double a = _n\ngen t = \"ab\"\n";
    auto r = exec(kMake + "outfile using \"of.raw\", replace\n", s);
    check(firstError(r.blocks).is_null(),
          "AER-IOTEXT (v): `outfile using \"of.raw\", replace` runs clean. Got `" +
              errText(firstError(r.blocks)) + "`");
    const std::string raw = slurp(at("of.raw"));
    check(!raw.empty(), "AER-IOTEXT (v): ...and left BYTES on disk");
    const std::string firstLine = raw.substr(0, raw.find('\n'));
    // Leading whitespace is skipped, not asserted away: outfile formats numbers
    // with %10.0g and a right-justified field would put spaces in front of the
    // digit. What is being asserted is that the first thing on the line is a
    // VALUE, not a name.
    const size_t firstNonSpace = firstLine.find_first_not_of(" \t");
    check(firstNonSpace != std::string::npos && firstLine[firstNonSpace] >= '0' &&
              firstLine[firstNonSpace] <= '9',
          "AER-IOTEXT (v): the file carries NO HEADER ROW -- the first non-blank character of the "
          "file is a DIGIT (the first observation's `a`), not the letter that starts the variable "
          "name `a`. outfile is the one export in this bundle that never writes names, and a "
          "handler that reused outsheet's writer emits one anyway: the receiving program then "
          "reads the header as an observation and every column shifts by a row. Got first line `" +
              firstLine + "`");
    check(has(raw, "\"ab\""),
          "AER-IOTEXT (v): ...and the string value is QUOTED (`\"ab\"`), which is outfile's "
          "default and what makes a value containing the separator survive the round trip. Got `" +
              raw.substr(0, 24) + "`");
    auto r2 = exec(kMake + "outfile using \"of_nq.raw\", replace noquote\n", s);
    check(firstError(r2.blocks).is_null(),
          "AER-IOTEXT (v/noquote): `outfile ..., noquote` runs clean. Got `" +
              errText(firstError(r2.blocks)) + "`");
    const std::string nq = slurp(at("of_nq.raw"));
    check(!nq.empty() && !has(nq, "\""),
          "AER-IOTEXT (v/noquote): ...and NOT ONE double quote is left in the file. Paired with "
          "the leg above, this is the check that says the quoting is a decision rather than a "
          "constant: an accepted-and-dropped `noquote` leaves the bytes identical to the default "
          "and returns rc 0. Got `" + nq.substr(0, 24) + "`");
    check(has(nq, "ab"),
          "AER-IOTEXT (v/noquote): ...while the VALUE itself survives -- `noquote` drops the "
          "delimiters, not the string. Got `" + nq.substr(0, 24) + "`");
    auto r3 = exec(kMake + "outfile using \"of_c.raw\", replace comma noquote\n", s);
    check(firstError(r3.blocks).is_null(),
          "AER-IOTEXT (v/comma): `outfile ..., comma noquote` runs clean. Got `" +
              errText(firstError(r3.blocks)) + "`");
    const std::string cm = slurp(at("of_c.raw"));
    check(has(cm, ","),
          "AER-IOTEXT (v/comma): ...and `comma` really changed the separator byte. The default "
          "form above is space-separated, so a dropped `comma` produces a file with no comma in "
          "it at all. Got `" + cm.substr(0, 24) + "`");
  }

  // ── (vi) saveold: the release follows version(). ─────────────────────────
  // version(11|12) writes format 115, 13 (and the bare form) 117, 14 format
  // 118 -- genuine bytes of that release (w2ar_data_io_family.log
  // dx_svo_017_v12 first byte 115, dx_svo_019 release 117), and the echo says
  // which one was written.
  {
    piet::SessionState s(workdir);
    seed(s);
    auto r = exec("clear\nset obs 1\ngen double x = 1\n"
                  "saveold \"so\", replace version(12)\n",
                  s);
    check(firstError(r.blocks).is_null(),
          "AER-IOTEXT (vi): `saveold \"so\", replace version(12)` runs clean. Got `" +
              errText(firstError(r.blocks)) + "`");
    check(fs::exists(cecon::to_native_path(at("so.dta"))),
          "AER-IOTEXT (vi): the extension defaults to .dta, so `saveold \"so\"` writes so.dta. A "
          "handler that passed the bare token through writes an extensionless file that `use "
          "\"so\"` -- which appends .dta -- can never find again");
    const std::vector<std::string> d = displays(r.blocks);
    const std::string kEcho = "(saveold: PIET writes Stata format 115)";
    bool sawEcho = false;
    for (const auto& t : d) if (t == kEcho) sawEcho = true;
    std::string dumped;
    for (const auto& t : d) { if (!dumped.empty()) dumped += " | "; dumped += t; }
    check(sawEcho,
          "AER-IOTEXT (vi): the echo is EXACTLY `" + kEcho + "` -- the release actually written. "
          "Got `" + (dumped.empty() ? std::string("<no display lines>") : dumped) + "`");
    unsigned char first = 0;
    {
      std::ifstream fin(cecon::to_native_path(at("so.dta")), std::ios::binary);
      char c0 = 0;
      if (fin.get(c0)) first = static_cast<unsigned char>(c0);
    }
    check(first == 115,
          "AER-IOTEXT (vi): ...and the file IS format 115 (first byte 115, dx_svo_017_v12 "
          "`b1=[s]`). Got " + std::to_string(static_cast<int>(first)));
    auto r2 = exec("use \"so.dta\", clear\n", s);
    check(firstError(r2.blocks).is_null(),
          "AER-IOTEXT (vi/reload): the file saveold wrote is READABLE by this build's own `use`. "
          "Got `" + errText(firstError(r2.blocks)) + "`");
    check(nRows(s) == 1.0 && countIf(s, "x == 1") == 1.0,
          "AER-IOTEXT (vi/reload): ...and carries the data back: one row with x == 1. A saveold "
          "that wrote a header and no observations still passes `fs::exists`. Got " +
              fullPrec(nRows(s)) + " rows");
  }
  {
    piet::SessionState s(workdir);
    seed(s);
    auto r = exec("clear\nset obs 1\ngen double x = 1\nsaveold \"so2\", replace\n", s);
    const std::vector<std::string> d = displays(r.blocks);
    // Bare saveold writes release 117 (Stata 13), not the current 118:
    // w2ar_data_io_family.log:4081 `PREC|dx_svo_019|0|rel=[117]|`.
    const std::string kEchoBare = "(saveold: PIET writes Stata format 117)";
    bool sawEcho = false;
    for (const auto& t : d) if (t == kEchoBare) sawEcho = true;
    std::string dumped;
    for (const auto& t : d) { if (!dumped.empty()) dumped += " | "; dumped += t; }
    check(sawEcho,
          "AER-IOTEXT (vi/no-version): with no `version()` the echo is exactly `" + kEchoBare +
              "` -- the clause about a recorded note is ABSENT, because nothing was recorded. A "
              "single hardcoded sentence that always names version 12 would pass the leg above "
              "and lie here. Got `" +
              (dumped.empty() ? std::string("<no display lines>") : dumped) + "`");
  }

  // ── (vii) putexcel: the ROUND TRIP. The decisive leg of the bundle. ──────
  // Everything else in this function reads back a text file this process also
  // wrote. A .xlsx is a ZIP of XML parts, and "the file exists and is 4 kB" is
  // true of a workbook no reader on earth will open. So the values go out
  // through the writer and come back through `xlsx::read` -- the same reader
  // `import excel` uses on Stata's own workbooks (testP1XlsxLayer leg ②).
  {
    piet::SessionState s(workdir);
    seed(s);
    auto r = exec("putexcel set \"pe.xlsx\", replace bold\n"
                  "putexcel A1 = \"n\"\n"
                  "putexcel B1 = 2.5\n"
                  "putexcel A2 = (2+3)\n",
                  s);
    check(firstError(r.blocks).is_null(),
          "AER-IOTEXT (vii): `putexcel set ... replace bold` + three assignments run clean. Got `" +
              errText(firstError(r.blocks)) + "`");
    int notes = 0;
    for (const auto& t : displays(r.blocks))
      if (has(t, "cell formatting options are accepted and ignored")) ++notes;
    check(notes == 1,
          "AER-IOTEXT (vii): the formatting-options note is shown EXACTLY ONCE per `set`, not "
          "once per assignment and not never. Never means `bold` was silently swallowed and the "
          "user believes the cell is bold; once-per-cell means a real putexcel script (the corpus "
          "has one with 1,464 calls) buries its own output under the same sentence repeated "
          "thousands of times. Got " + std::to_string(notes) + " occurrences");

    piet::xlsx::Sheet sh;
    const bool ok = readBook(at("pe.xlsx"), sh);
    check(ok,
          "AER-IOTEXT (vii): the workbook putexcel wrote is READABLE by this build's own xlsx "
          "reader. If this fails the defect is in the WRITER and the plan's instruction applies: "
          "stop and report, do not relax the check");
    if (ok) {
      const piet::xlsx::Cell a1 = cellAt(sh, 0, 0);
      const piet::xlsx::Cell b1 = cellAt(sh, 0, 1);
      const piet::xlsx::Cell a2 = cellAt(sh, 1, 0);
      check(!a1.isNumber && a1.text == "n",
            "AER-IOTEXT (vii): A1 came back as the STRING \"n\". Got isNumber=" +
                std::string(a1.isNumber ? "true" : "false") + " text=`" + a1.text + "`");
      check(b1.isNumber && b1.number == 2.5,
            "AER-IOTEXT (vii): B1 came back as the NUMBER 2.5 -- in column B, which is what says "
            "the cell ADDRESS was honoured. A writer that appended every assignment to the next "
            "free cell produces a workbook that opens fine and puts every value in the wrong "
            "place. Got isNumber=" + std::string(b1.isNumber ? "true" : "false") + " number=" +
                fullPrec(b1.number) + " text=`" + b1.text + "`");
      check(a2.isNumber && a2.number == 5.0,
            "AER-IOTEXT (vii): A2 == 5, so `A1 = (2+3)` was EVALUATED. A handler that stored the "
            "parenthesised text verbatim writes the string `(2+3)` into the cell: the workbook is "
            "valid, the command returned rc 0, and the spreadsheet is wrong. Got isNumber=" +
                std::string(a2.isNumber ? "true" : "false") + " number=" + fullPrec(a2.number) +
                " text=`" + a2.text + "`");
    }

    // The matrix forms, appended to the same open workbook.
    auto rm = exec("matrix M = (1,2\\3,4)\n"
                   "putexcel A4 = matrix(M)\n"
                   "putexcel A7 = matrix(M), names\n",
                   s);
    check(firstError(rm.blocks).is_null(),
          "AER-IOTEXT (vii/matrix): the two matrix assignments run clean. Got `" +
              errText(firstError(rm.blocks)) + "`");
    piet::xlsx::Sheet sm;
    const bool okm = readBook(at("pe.xlsx"), sm);
    check(okm, "AER-IOTEXT (vii/matrix): the rewritten workbook is still readable");
    if (okm) {
      check(cellAt(sm, 3, 0).isNumber && cellAt(sm, 3, 0).number == 1.0 &&
                cellAt(sm, 3, 1).isNumber && cellAt(sm, 3, 1).number == 2.0 &&
                cellAt(sm, 4, 0).isNumber && cellAt(sm, 4, 0).number == 3.0 &&
                cellAt(sm, 4, 1).isNumber && cellAt(sm, 4, 1).number == 4.0,
            "AER-IOTEXT (vii/matrix): `A4 = matrix(M)` writes the 2x2 block at rows 4-5, columns "
            "A-B, in ROW-MAJOR order: 1 2 / 3 4. A transposed write (2 1 / 4 3) is the classic "
            "silent defect here -- same cells, same count, every number in the wrong place. Got "
            "A4=" + fullPrec(cellAt(sm, 3, 0).number) + " B4=" + fullPrec(cellAt(sm, 3, 1).number) +
                " A5=" + fullPrec(cellAt(sm, 4, 0).number) + " B5=" +
                fullPrec(cellAt(sm, 4, 1).number));
      check(cellAt(sm, 0, 0).text == "n" && cellAt(sm, 1, 0).number == 5.0,
            "AER-IOTEXT (vii/matrix): ...and the cells written BEFORE the matrix are still there. "
            "The design rewrites the whole workbook on every assignment, so an accumulated cell "
            "map that was not carried forward loses everything above the newest write while the "
            "file still opens");
      // `names` is Stata's row-AND-column-name layout: a blank corner, the
      // column names across the first row of the block, the row names down its
      // first column, and the numbers shifted one right and one down.
      check(!cellAt(sm, 6, 1).isNumber && !cellAt(sm, 6, 1).text.empty(),
            "AER-IOTEXT (vii/names): with `names`, the FIRST row of the block (row 7) carries the "
            "matrix's column NAMES as text, not its numbers. Got isNumber=" +
                std::string(cellAt(sm, 6, 1).isNumber ? "true" : "false") + " text=`" +
                cellAt(sm, 6, 1).text + "`");
      check(cellAt(sm, 7, 1).isNumber && cellAt(sm, 7, 1).number == 1.0,
            "AER-IOTEXT (vii/names): ...and the matrix body is displaced one row down and one "
            "column right by the labels, putting M[1,1] at B8. An accepted-and-dropped `names` "
            "writes the bare numbers at A7 instead: rc 0, a readable workbook, and a table whose "
            "rows and columns are unlabelled in exactly the report the author wanted them in. "
            "Got B8 isNumber=" + std::string(cellAt(sm, 7, 1).isNumber ? "true" : "false") +
                " number=" + fullPrec(cellAt(sm, 7, 1).number));
    }
    check(!has(slurp(at("pe.xlsx")), "<mergeCells"),
          "AER-IOTEXT (vii/merge): a workbook with NO merges emits no <mergeCells> element at "
          "all. xlsx.h states this as a byte-identity guarantee against the pre-putexcel writer, "
          "and an always-emitted empty element (count=\"0\") quietly breaks it -- and is rejected "
          "outright by some readers");
  }
  {
    piet::SessionState s(workdir);
    seed(s);
    auto r = exec("putexcel set \"pm.xlsx\", replace\n"
                  "putexcel A1 = \"x\"\n"
                  "putexcel B1 = \"y\"\n"
                  "putexcel A1:B1, merge\n",
                  s);
    check(firstError(r.blocks).is_null(),
          "AER-IOTEXT (vii/merge): the range form `A1:B1, merge` runs clean. Got `" +
              errText(firstError(r.blocks)) + "`");
    check(has(slurp(at("pm.xlsx")), "<mergeCells"),
          "AER-IOTEXT (vii/merge): ...and a <mergeCells> element reaches the sheet XML. The "
          "writer emits STORED (uncompressed) ZIP entries, so this is a literal byte search in "
          "the file -- the merge either is in the workbook or it is not. A `merge` parsed and "
          "dropped returns rc 0 over an unmerged sheet, which is a layout defect the author only "
          "discovers in Excel");
  }
  {
    // `modify` PRELOADS: the classic defect is a modify that opened the path
    // with truncation and silently emptied a workbook the user asked to extend.
    piet::SessionState s(workdir);
    seed(s);
    auto r = exec("putexcel set \"pe.xlsx\", modify\nputexcel C1 = \"z\"\n", s);
    check(firstError(r.blocks).is_null(),
          "AER-IOTEXT (vii/modify): `putexcel set \"pe.xlsx\", modify` + one write runs clean. "
          "Got `" + errText(firstError(r.blocks)) + "`");
    piet::xlsx::Sheet sh;
    const bool ok = readBook(at("pe.xlsx"), sh);
    check(ok, "AER-IOTEXT (vii/modify): the modified workbook is still readable");
    if (ok) {
      check(cellAt(sh, 0, 2).text == "z",
            "AER-IOTEXT (vii/modify): the new cell C1 is there. Got `" + cellAt(sh, 0, 2).text +
                "`");
      check(cellAt(sh, 0, 0).text == "n" && cellAt(sh, 3, 0).number == 1.0,
            "AER-IOTEXT (vii/modify): ...and EVERYTHING written by the earlier session survived "
            "-- A1 is still \"n\" and the matrix block is still at A4. `modify` that truncated "
            "instead of preloading destroys a workbook the user explicitly asked to keep, "
            "reports rc 0, and leaves a file that opens perfectly with one cell in it. Got A1=`" +
                cellAt(sh, 0, 0).text + "` A4=" + fullPrec(cellAt(sh, 3, 0).number));
    }
  }
  {
    // Plan edge case: `modify` pointed at something that is NOT a workbook.
    // The failure mode this guards is the destructive one -- a modify that
    // cannot preload and therefore starts from an empty cell map, then
    // rewrites the path on the first assignment and destroys whatever the file
    // actually was.
    piet::SessionState s(workdir);
    seed(s);
    spit(at("notabook.xlsx"), "this is plainly not a zip archive");
    auto r = exec("putexcel set \"notabook.xlsx\", modify\n", s);
    const nlohmann::ordered_json e = firstError(r.blocks);
    check(!e.is_null(),
          "AER-IOTEXT (vii/not-a-workbook): `set ..., modify` over a file this build cannot read "
          "is an ERROR at the `set`, before any cell map exists");
    check(has(errText(e), "workbook") || has(errText(e), "putexcel"),
          "AER-IOTEXT (vii/not-a-workbook): ...and the message says which file and what is wrong "
          "with it, rather than surfacing the ZIP reader's complaint. Got `" + errText(e) + "`");
    auto r2 = exec("putexcel A1 = \"x\"\n", s);
    check(!firstError(r2.blocks).is_null(),
          "AER-IOTEXT (vii/not-a-workbook): ...and no workbook was opened, so the next assignment "
          "is the no-open-workbook error rather than a write");
    check(slurp(at("notabook.xlsx")) == "this is plainly not a zip archive",
          "AER-IOTEXT (vii/not-a-workbook): ...and the FILE IS INTACT. This is the whole point of "
          "the leg: a `modify` that swallowed the read failure and continued with an empty map "
          "would overwrite the user's file with a one-cell workbook on the very next line, having "
          "reported nothing. Got `" + slurp(at("notabook.xlsx")) + "`");
  }
  {
    // The round trip through PIET's own `import excel` -- the second reader.
    piet::SessionState s(workdir);
    seed(s);
    auto r = exec("putexcel set \"pr.xlsx\", replace\n"
                  "putexcel A1 = \"k\"\n"
                  "putexcel B1 = \"v\"\n"
                  "putexcel A2 = 7\n"
                  "putexcel B2 = 8\n"
                  "import excel using \"pr.xlsx\", clear firstrow\n",
                  s);
    check(firstError(r.blocks).is_null(),
          "AER-IOTEXT (vii/import): putexcel writes a workbook and `import excel ... firstrow` "
          "reads it back in the same session. Got `" + errText(firstError(r.blocks)) + "`");
    const std::vector<std::string> vn = varNames(s);
    check(hasName(vn, "k") && hasName(vn, "v"),
          "AER-IOTEXT (vii/import): the row-1 strings became the VARIABLE NAMES {k,v}, so the "
          "cells putexcel addressed as A1/B1 really are row 1 columns A and B and not, say, one "
          "string crammed into a single cell. Got {" + joinNames(vn) + "}");
    check(nRows(s) == 1.0,
          "AER-IOTEXT (vii/import): ...over exactly one data row. Got " + fullPrec(nRows(s)));
    check(countIf(s, "k == 7") == 1.0 && countIf(s, "v == 8") == 1.0,
          "AER-IOTEXT (vii/import): ...whose values are 7 and 8, as NUMBERS. This is the end of "
          "the loop the plan calls the STOP condition: a mismatch here means our writer and our "
          "reader disagree about the format, which no single-sided check can see. Got k-count " +
              fullPrec(countIf(s, "k == 7")) + ", v-count " + fullPrec(countIf(s, "v == 8")));
  }
  {
    // Writing with no open workbook, and writing after `clear`.
    piet::SessionState s(workdir);
    seed(s);
    auto r = exec("putexcel A1 = \"x\"\n", s);
    const nlohmann::ordered_json e = firstError(r.blocks);
    check(!e.is_null(),
          "AER-IOTEXT (vii/no-set): an assignment with no open workbook is an ERROR. A handler "
          "that invented a default filename writes a workbook nobody asked for, in a directory "
          "nobody chose, and reports success");
    check(has(errText(e), "putexcel set"),
          "AER-IOTEXT (vii/no-set): ...and the message names `putexcel set`, so the fix is in the "
          "message rather than in the manual. Got `" + errText(e) + "`");

    piet::SessionState s2(workdir);
    seed(s2);
    auto r2 = exec("putexcel set \"pc.xlsx\", replace\nputexcel A1 = \"x\"\nputexcel clear\n", s2);
    check(firstError(r2.blocks).is_null(),
          "AER-IOTEXT (vii/clear): set -> write -> clear runs clean. Got `" +
              errText(firstError(r2.blocks)) + "`");
    check(s2.putexcel.empty(),
          "AER-IOTEXT (vii/clear): `putexcel clear` empties SessionState::putexcel. Got " +
              s2.putexcel.dump());
    auto r3 = exec("putexcel B1 = \"y\"\n", s2);
    check(!firstError(r3.blocks).is_null(),
          "AER-IOTEXT (vii/clear): ...and a write AFTER clear is an error again. A `clear` that "
          "printed something and left the state behind lets the next assignment silently reopen "
          "and rewrite a workbook the author had finished with");
  }

  // ── (viii) filefilter: the ESCAPES are decoded, and r(occurrences) counts
  // REPLACEMENTS. ───────────────────────────────────────────────────────────
  {
    piet::SessionState s(workdir);
    seed(s);
    spit(at("ff_in.txt"), "x\"y\"z");
    // `\Q` is filefilter's escape for a double quote. `to(Q)` is a plain
    // letter on purpose: this call isolates the FROM-side escape decode from
    // any question about quoting the TO argument, which the next call covers.
    auto r = exec("filefilter \"ff_in.txt\" \"ff_out.txt\", from(\\Q) to(Q) replace\n", s);
    check(firstError(r.blocks).is_null(),
          "AER-IOTEXT (viii): `filefilter ... from(\\Q) to(Q) replace` runs clean. Got `" +
              errText(firstError(r.blocks)) + "`");
    const std::string out = slurp(at("ff_out.txt"));
    check(out == "xQyQz",
          "AER-IOTEXT (viii): the output is EXACTLY `xQyQz`, byte for byte. `\\Q` must be decoded "
          "to a double quote before the search: taken literally it matches the two-character "
          "sequence backslash-Q, which appears nowhere, so the file is copied through unchanged "
          "and the command reports success over a filter that filtered nothing. Got `" + out + "`");
    check(rOf(s, "occurrences") == 2.0,
          "AER-IOTEXT (viii): ...and r(occurrences) == 2, the number of REPLACEMENTS. Not 1 (one "
          "line touched) and not 0 (published as a name with no value): do-files branch on this "
          "number, and a line count agrees with the replacement count on exactly the one-hit "
          "input that would hide the bug. Got " + fullPrec(rOf(s, "occurrences")));
    check(slurp(at("ff_in.txt")) == "x\"y\"z",
          "AER-IOTEXT (viii): ...and the INPUT file is untouched. filefilter writes a new file; "
          "an implementation that opened the source for writing en route destroys the original");
  }
  {
    piet::SessionState s(workdir);
    seed(s);
    spit(at("ff_in2.txt"), "x\"y\"z");
    // The plan's own literal spelling, apostrophe and all.
    auto r = exec("filefilter \"ff_in2.txt\" \"ff_out2.txt\", from(\\Q) to(') replace\n", s);
    check(firstError(r.blocks).is_null(),
          "AER-IOTEXT (viii/apostrophe): the plan's literal `to(')` form parses. A lone "
          "apostrophe is the closing half of Stata's local-macro delimiter, so an option reader "
          "that scans for macro syntax before it splits options can swallow the rest of the line. "
          "Got `" + errText(firstError(r.blocks)) + "`");
    check(slurp(at("ff_out2.txt")) == "x'y'z",
          "AER-IOTEXT (viii/apostrophe): ...and produces `x'y'z`. Got `" +
              slurp(at("ff_out2.txt")) + "`");
  }
  {
    piet::SessionState s(workdir);
    seed(s);
    spit(at("ff_same.txt"), "aaa");
    auto r = exec("filefilter \"ff_same.txt\" \"ff_same.txt\", from(a) to(b) replace\n", s);
    check(!firstError(r.blocks).is_null(),
          "AER-IOTEXT (viii/same): input == output is an ERROR, refused BEFORE anything is "
          "written. This is the dest-==-source class (BUG-138): a filter that streamed through "
          "its own source truncates the file it is reading and the surviving bytes are whatever "
          "the buffer happened to hold");
    check(slurp(at("ff_same.txt")) == "aaa",
          "AER-IOTEXT (viii/same): ...and the file is INTACT. An error raised after the truncate "
          "is the worst version of this defect -- it reports failure and did the damage. Got `" +
              slurp(at("ff_same.txt")) + "`");
  }

  // ── (ix) copy: a real byte copy, an honest already-exists, and a URL that
  // is refused BY NAME. ─────────────────────────────────────────────────────
  {
    piet::SessionState s(workdir);
    seed(s);
    spit(at("cp_a.txt"), "hello");
    auto r = exec("copy \"cp_a.txt\" \"cp_b.txt\"\n", s);
    check(firstError(r.blocks).is_null(),
          "AER-IOTEXT (ix): `copy \"cp_a.txt\" \"cp_b.txt\"` runs clean. Got `" +
              errText(firstError(r.blocks)) + "`");
    check(slurp(at("cp_b.txt")) == "hello",
          "AER-IOTEXT (ix): ...and the destination holds the source's BYTES. `fs::exists` is true "
          "of the zero-length file a create-then-fail leaves behind. Got `" +
              slurp(at("cp_b.txt")) + "`");
    auto r2 = exec("copy \"cp_a.txt\" \"cp_b.txt\"\n", s);
    const nlohmann::ordered_json e2 = firstError(r2.blocks);
    check(!e2.is_null(),
          "AER-IOTEXT (ix/exists): copying onto an existing destination WITHOUT `replace` is an "
          "error. A copy that overwrote silently is data loss with a clean return code");
    check(rcOf(e2) == "602",
          "AER-IOTEXT (ix/exists): ...at r(602), Stata's own `file already exists`, so a do-file "
          "branching on `if _rc == 602` takes the branch its author wrote. Got rc " + rcOf(e2) +
              " from `" + errText(e2) + "`");
    auto r3 = exec("copy \"cp_a.txt\" \"cp_b.txt\", replace\n", s);
    check(firstError(r3.blocks).is_null(),
          "AER-IOTEXT (ix/replace): ...and `replace` makes the same call succeed, so 602 above "
          "was the guard and not a broken path. Got `" + errText(firstError(r3.blocks)) + "`");
    auto r4 = exec("copy \"cp_a.txt\" \"cp_a.txt\", replace\n", s);
    check(!firstError(r4.blocks).is_null() && slurp(at("cp_a.txt")) == "hello",
          "AER-IOTEXT (ix/self): src == dst is refused and the file is INTACT (dest-==-source, "
          "BUG-138: copy_file with overwrite_existing onto itself is where a file goes to be "
          "emptied). Got `" + slurp(at("cp_a.txt")) + "`");
  }
  {
    piet::SessionState s(workdir);
    seed(s);
    auto r = exec("copy \"http://example.invalid/x.dta\" \"cp_url.dta\"\n", s);
    const nlohmann::ordered_json e = firstError(r.blocks);
    check(!e.is_null(), "AER-IOTEXT (ix/url): a URL source is refused");
    check(errField(e, "reason") == "refused:no_network",
          "AER-IOTEXT (ix/url): ...with the cause `refused:no_network` in `reason`. The wrong "
          "implementation this catches is the one that treats `http://example.invalid/x.dta` as a "
          "relative FILENAME and answers r(601) `file not found`: the user then spends an "
          "afternoon looking for a file, when the true answer is that this build makes no network "
          "calls from Stata verbs and never will. Got reason `" + errField(e, "reason") + "`");
    check(has(errText(e), "URL") || has(errText(e), "url"),
          "AER-IOTEXT (ix/url): ...and the sentence says so in words, not only in a machine "
          "field. Got `" + errText(e) + "`");
    check(!fs::exists(cecon::to_native_path(at("cp_url.dta"))),
          "AER-IOTEXT (ix/url): ...and NOTHING was created at the destination. A refusal that "
          "already opened the output leaves an empty file that the next `use` finds and fails on "
          "for a completely different reason");
  }

  // ── (x) the refusals, each naming its OWN cause. ─────────────────────────
  // A registered row that refuses BY REASON tells the user what is missing; an
  // unregistered name answers a generic r(199) that reads like a typo. What
  // this leg really guards is the second half: rows sharing one cause string is
  // a user typing `odbc` and being told there is no shapefile reader.
  // AER tier-1 (2026-10-28): unzipfile and zipfile left this table -- they run
  // now (zip_io.h), and selftest_w2_t1_zip.cpp checks them.
  {
    struct Refusal { const char* cmd; const char* reason; };
    const std::vector<Refusal> kRefusals = {
        {"odbc list", "refused:no_odbc_driver"},
        {"spshape2dta \"shp\"", "refused:no_shapefile_reader"},
    };
    for (const auto& rf : kRefusals) {
      piet::SessionState s(workdir);
      seed(s);
      auto r = exec(std::string(rf.cmd) + "\n", s);
      const nlohmann::ordered_json e = firstError(r.blocks);
      check(!e.is_null(),
            std::string("AER-IOTEXT (x): `") + rf.cmd + "` is refused rather than silently "
            "accepted");
      check(errField(e, "reason") == rf.reason,
            std::string("AER-IOTEXT (x): `") + rf.cmd + "` refuses with its OWN cause `" +
                rf.reason + "`. Got `" + errField(e, "reason") + "` -- a shared cause string " +
                "across these rows tells an `odbc` user about a missing shapefile reader, and a " +
                "bare `piet_gap` tells them their spelling is wrong");
      check(rcOf(e) == "199",
            std::string("AER-IOTEXT (x): ...at r(199), so `capture` + `_rc` in a do-file sees the "
            "same code Stata gives an unimplemented command. Got rc ") + rcOf(e) + " for `" +
                rf.cmd + "`");
    }
  }

  fs::remove_all(workdir, ec);
}

// ── AER-SCOPE1 bundle I (UTIL, 2026-09-04) ───────────────────────────────────
//
// Twelve data-tidying verbs over thirteen registry rows (`unique` and `gunique`
// share one handler). Their failure class is NOT a return code. Every wrong
// implementation this bundle can plausibly ship answers rc 0 and leaves a frame
// that lists correctly: a `unique` that dropped missing instead of counting it,
// a `distinct` that kept it, a `mdesc` that reported the NON-missing count, a
// `missings tag` that wrote an any-missing indicator where Stata writes a
// rowmiss COUNT, a `carryforward` that leaked the last value across a group
// boundary, a `rangestat` that returned the by-group aggregate instead of the
// window, a `tsspell` whose sequence never resets, a `renvarlab` that renamed
// half a varlist before hitting a collision. So no leg below stops at a return
// code: each reads a VALUE back out of the frame, and the value is chosen so
// that the wrong implementation named in its own comment gets it wrong.
//
// FIVE OF THE PLAN'S SEVENTEEN NAMES DO NOT APPEAR HERE AND MUST NOT BE ADDED.
// `dropmiss` and `renvars` have no package under their own name, so the
// campaign's attribution rule gives them no registry row; `strdist`, `matchit`
// and `reclink` are record linkage, out of scope. All five are UNREGISTERED,
// which means they answer a GENERIC r(199) rather than a named refusal -- a
// test asserting a specific reason string for any of them would be asserting
// something the tree does not claim.
//
// THREE HOUSE RULES ARE FOLLOWED LITERALLY, ALL THREE BECAUSE THEY COST TIME:
//   - EVERY session seeds `cwd` as well as `eval.cwd`. resolveUserPath reads
//     SessionState::cwd (handlers.cpp:2040); bundle E seeded only eval.cwd and
//     sixteen checks failed for that one reason. `filelist` is file I/O.
//   - Numeric comparisons report through `fullPrec` (%.17g), never
//     std::to_string, which prints six decimals and renders a genuine
//     eighth-digit difference as two identical strings.
//   - Nothing here asserts an absolute PATH, and missing is `.`, never 0.
//
// WHY THE FIXTURES ARE BUILT WITH `set obs` + `gen` + `replace ... in #/#`
// RATHER THAN `input`: every count below is hand-arithmetic over a frame this
// file states in a comment, and the `in`-range replace is the oldest, most
// heavily frozen way to punch a specific row (BUG-077/D9-in). A fixture built
// out of the bundle-F verb under test in the next function over would make a
// bundle-I failure readable as a bundle-F failure.

void testAerUtilCounts() {
  std::printf("[selftest] --- AER-SCOPE1 bundle I: unique/gunique/distinct/mdesc/missings, "
              "hand-computed off an 8-row frame ---\n");
  namespace fs = std::filesystem;
  std::string workdir =
      (fs::temp_directory_path() / "piet_native_selftest_aerutilcounts").u8string();
  std::error_code ec;
  fs::remove_all(workdir, ec);
  fs::create_directories(workdir, ec);

  auto exec = [](const std::string& src, piet::SessionState& session) {
    return piet::doexec::executeDoSource(src, session, piet::dispatch);
  };
  auto seed = [&](piet::SessionState& s) {
    s.eval.cwd = workdir;
    s.cwd = workdir;  // resolveUserPath reads THIS field (handlers.cpp:2040).
  };
  // NULL rather than a throw when there is no error block -- the BUG-129 trap:
  // check()'s message argument is built EAGERLY, on the passing path too.
  auto firstError = [](const nlohmann::ordered_json& blocks) -> nlohmann::ordered_json {
    for (const auto& b : blocks)
      if (b.is_object() && b.value("type", std::string()) == "error") return b;
    return nlohmann::ordered_json();
  };
  auto errText = [](const nlohmann::ordered_json& e) {
    return e.is_object() ? e.value("message", std::string()) : std::string("<none>");
  };
  auto fullPrec = [](double v) {
    char buf[48];
    std::snprintf(buf, sizeof(buf), "%.17g", v);
    return std::string(buf);
  };
  auto has = [](const std::string& hay, const std::string& needle) {
    return hay.find(needle) != std::string::npos;
  };
  auto renderText = [](const auto& blocks) {
    std::string out;
    for (const auto& b : blocks) {
      if (!b.is_object()) continue;
      const std::string t = b.value("text", std::string());
      if (t.empty()) continue;
      out += t;
      out += "\n";
    }
    return out;
  };
  auto displays = [](const auto& blocks) {
    std::vector<std::string> v;
    for (const auto& b : blocks)
      if (b.is_object() && b.value("type", std::string()) == "display")
        v.push_back(b.value("text", std::string()));
    return v;
  };
  // The RAW remainder after `prefix`, so a missing cell can be compared as the
  // string "." -- the house rule that missing is never 0. `displayValue` below
  // parses the same line as a number for the non-missing cases.
  auto displayText = [&](const auto& blocks, const std::string& prefix) -> std::string {
    for (const auto& s : displays(blocks))
      if (s.rfind(prefix, 0) == 0) return s.substr(prefix.size());
    return std::string("<no such display line>");
  };
  auto rOf = [](piet::SessionState& s, const char* key) -> double {
    const double* p = s.eval.rValues.find(key);
    return p ? *p : std::nan("");
  };
  // r() is REPLACED wholesale by the next r-class command (macros.cpp's
  // captureRFromBlock), so every read happens immediately after the command
  // that published it -- never two commands later.
  auto runR = [&](piet::SessionState& s, const std::string& cmd, const char* key) -> double {
    (void)piet::dispatch(cmd, s);
    return rOf(s, key);
  };
  auto nRows = [&](piet::SessionState& s) { return runR(s, "count", "N"); };
  auto varNames = [](piet::SessionState& s) {
    std::vector<std::string> out;
    const nlohmann::ordered_json blocks = piet::dispatch("describe", s);
    for (const auto& b : blocks)
      if (b.is_object() && b.value("type", std::string()) == "describe" && b.contains("variables"))
        for (const auto& v : b["variables"]) out.push_back(v.value("name", std::string()));
    return out;
  };
  auto hasName = [](const std::vector<std::string>& v, const std::string& n) {
    return std::find(v.begin(), v.end(), n) != v.end();
  };
  auto joinNames = [](const std::vector<std::string>& v) {
    std::string s;
    for (const auto& n : v) { if (!s.empty()) s += " "; s += n; }
    return s.empty() ? std::string("<none>") : s;
  };

  // FIXTURE U -- eight rows. Everything asserted in this function is
  // arithmetic over exactly this table, worked out by hand:
  //
  //     row :  1  2  3  4  5  6  7  8
  //     ug  :  1  1  1  2  2  2  3  3
  //     uv  :  5  5  .  7  8  9  4  5
  //     uw  :  1  2  .  4  .  6  7  8
  //
  // uv's missing sits in group 1; uw's two missing (rows 3 and 5) OVERLAP uv's
  // on row 3 and not on row 5. That overlap is deliberate: it makes the number
  // of ROWS carrying a missing (2) differ from the sum of the per-variable
  // counts (3), which is the one shape that separates `missings report`'s
  // observation line from a report that added its own table up.
  static const char* kFixU =
      "clear\n"
      "set obs 8\n"
      "gen ug = 1\n"
      "replace ug = 2 in 4/6\n"
      "replace ug = 3 in 7/8\n"
      "gen uv = 5\n"
      "replace uv = . in 3\n"
      "replace uv = 7 in 4\n"
      "replace uv = 8 in 5\n"
      "replace uv = 9 in 6\n"
      "replace uv = 4 in 7\n"
      "gen uw = _n\n"
      "replace uw = . in 3\n"
      "replace uw = . in 5\n";

  // ── (i) `unique` counts MISSING as one of the values. ──────────────────────
  // uv holds {5, ., 7, 8, 9, 4} over eight records. 6 and 8 are the two numbers
  // this verb prints, and pinning both is what separates them: a handler that
  // published the record count as r(unique) matches one line and not the other.
  // 5 -- the missing-excluded answer, which is `distinct`'s rule and is asserted
  // as such in leg (iv) -- is the wrong answer this leg exists to catch.
  {
    piet::SessionState s(workdir);
    seed(s);
    (void)exec(kFixU, s);
    auto r = exec("unique uv\n", s);
    check(firstError(r.blocks).is_null(),
          "AER-UTIL/counts (i): `unique uv` runs clean. Got `" +
              errText(firstError(r.blocks)) + "`");
    const double u = rOf(s, "unique");
    check(u == 6.0,
          "AER-UTIL/counts (i): r(unique) == 6 -- {5, ., 7, 8, 9, 4}. MISSING IS A VALUE here; "
          "excluding it gives 5, which is `distinct`'s rule and a silently different answer. Got " +
              fullPrec(u));
    const double n = rOf(s, "N");
    check(n == 8.0,
          "AER-UTIL/counts (i): ...and r(N) == 8, the record count, which is the SECOND line of "
          "this verb's output. A handler that published one number twice satisfies whichever of "
          "these two checks it happened to match. Got " + fullPrec(n));
    const std::string txt = renderText(r.blocks);
    check(has(txt, "Number of unique values of uv is"),
          "AER-UTIL/counts (i): ...and it renders the unique-values line by name. Got `" + txt +
              "`");
    check(has(txt, "Number of records is"),
          "AER-UTIL/counts (i): ...and the records line under it -- two lines, not one. Got `" +
              txt + "`");
  }

  // ── (ii) a multi-variable `unique` is a TUPLE count. ───────────────────────
  // (ug,uv) over the eight rows is {(1,5),(1,.),(2,7),(2,8),(2,9),(3,4),(3,5)}
  // = 7. Every plausible non-tuple implementation lands somewhere else: first
  // variable only = 3, last variable only = 6, per-variable SUM = 3+6 = 9.
  {
    piet::SessionState s(workdir);
    seed(s);
    (void)exec(kFixU, s);
    auto r = exec("unique ug uv\n", s);
    check(firstError(r.blocks).is_null(),
          "AER-UTIL/counts (ii): `unique ug uv` runs clean. Got `" +
              errText(firstError(r.blocks)) + "`");
    const double u = rOf(s, "unique");
    check(u == 7.0,
          "AER-UTIL/counts (ii): r(unique) == 7 over the (ug,uv) TUPLES. 3 = ug alone, 6 = uv "
          "alone, 9 = the two per-variable counts added; all three are plausible numbers a "
          "non-tuple handler prints without complaint. Got " + fullPrec(u));
  }

  // ── (iii) `by() + gen()` writes the group's FIRST observation only. ────────
  //
  // BUG-422 (2026-09-06): this leg used to assert the opposite — a fill across
  // every observation of the group — on the strength of a comment in the handler
  // that said unique.ado does that. Bundle I's own P5 wave pin measured StataBE
  // 19.5 with unique 1.2.4 and settled it: `by `by': gen `gen' = `count' if
  // _n==1`, so five of the eight rows are MISSING and `summarize` reads N=3.
  // Group unique-uv counts: g1 {5,.} = 2, g2 {7,8,9} = 3, g3 {4,5} = 2, so nu is
  // 2 . . 3 . . 2 . — the three assertions below are still three different wrong
  // answers: N==3 fails a whole-group fill (which reads 8), sum==7 fails a fill
  // that wrote the group SIZE (3 + 3 + 2 = 8 here), and the per-row reads fail a
  // write-back that computed in group order and landed positionally.
  {
    piet::SessionState s(workdir);
    seed(s);
    (void)exec(kFixU, s);
    auto r = exec("unique uv, by(ug) gen(nu)\n", s);
    check(firstError(r.blocks).is_null(),
          "AER-UTIL/counts (iii): `unique uv, by(ug) gen(nu)` runs clean. Got `" +
              errText(firstError(r.blocks)) + "`");
    const double nn = runR(s, "summarize nu", "N");
    check(nn == 3.0,
          "AER-UTIL/counts (iii): nu is non-missing in exactly THREE rows -- one per group, the "
          "group's first observation (unique.ado's `if _n==1`). A whole-group fill reads 8. "
          "Got N " + fullPrec(nn));
    const double sm = runR(s, "summarize nu", "sum");
    check(sm == 7.0,
          "AER-UTIL/counts (iii): ...and nu sums to 7 (2 + 3 + 2, one row per group). A fill that "
          "wrote the group SIZE instead of its unique-value count sums to 8 and passes the count "
          "above. Got " + fullPrec(sm));
    check(displayText(exec("display \"U3A=\" nu[1]\n", s).blocks, "U3A=") == "2",
          "AER-UTIL/counts (iii): ...nu[1] == 2 (group 1: {5, .}, missing counted). Got `" +
              displayText(exec("display \"U3A=\" nu[1]\n", s).blocks, "U3A=") + "`");
    check(displayText(exec("display \"U3B=\" nu[4]\n", s).blocks, "U3B=") == "3",
          "AER-UTIL/counts (iii): ...nu[4] == 3 (group 2's FIRST row: {7, 8, 9}). Got `" +
              displayText(exec("display \"U3B=\" nu[4]\n", s).blocks, "U3B=") + "`");
    check(displayText(exec("display \"U3D=\" nu[5]\n", s).blocks, "U3D=") == ".",
          "AER-UTIL/counts (iii): ...and nu[5] is MISSING -- the second row of group 2 is where a "
          "whole-group fill and Stata's `if _n==1` disagree, so this is the discriminating read. "
          "Got `" + displayText(exec("display \"U3D=\" nu[5]\n", s).blocks, "U3D=") + "`");
    check(displayText(exec("display \"U3C=\" nu[7]\n", s).blocks, "U3C=") == "2",
          "AER-UTIL/counts (iii): ...and nu[7] == 2 (group 3's first row: {4, 5}) -- the per-row "
          "reads are what a positional write-back after an internal group sort gets wrong while "
          "the sum and the count both still agree. Got `" +
              displayText(exec("display \"U3C=\" nu[7]\n", s).blocks, "U3C=") + "`");
  }

  // ── (iv) `distinct` EXCLUDES missing, and `missing` puts it back. ──────────
  // This is the leg that makes leg (i) mean something: over the SAME column the
  // two verbs are contracted to disagree, 5 against 6, and a handler that
  // routed one to the other passes every other check in this function.
  {
    piet::SessionState s(workdir);
    seed(s);
    (void)exec(kFixU, s);
    auto r = exec("distinct uv\n", s);
    check(firstError(r.blocks).is_null(),
          "AER-UTIL/counts (iv): `distinct uv` runs clean. Got `" +
              errText(firstError(r.blocks)) + "`");
    const double nd = rOf(s, "ndistinct");
    check(nd == 5.0,
          "AER-UTIL/counts (iv): r(ndistinct) == 5 -- {5, 7, 8, 9, 4}, missing EXCLUDED. 6 is "
          "`unique`'s answer over the same column (leg (i)), so this pair is the whole "
          "distinct-vs-unique contract. Got " + fullPrec(nd));
    const double nt = rOf(s, "N");
    check(nt == 7.0,
          "AER-UTIL/counts (iv): ...and r(N) == 7, the row's TOTAL, which is also missing-free. 8 "
          "here means the total counted rows and the distinct count did not. Got " +
              fullPrec(nt));

    auto r2 = exec("distinct uv, missing\n", s);
    check(firstError(r2.blocks).is_null(),
          "AER-UTIL/counts (iv/missing): `distinct uv, missing` runs clean. Got `" +
              errText(firstError(r2.blocks)) + "`");
    check(rOf(s, "ndistinct") == 6.0,
          "AER-UTIL/counts (iv/missing): ...and `missing` puts it back: 6, agreeing with `unique` "
          "at last. An option that was consumed and ignored leaves 5 here. Got " +
              fullPrec(rOf(s, "ndistinct")));
    check(rOf(s, "N") == 8.0,
          "AER-UTIL/counts (iv/missing): ...over a total of 8, not 7 -- the option has to move "
          "BOTH numbers. Got " + fullPrec(rOf(s, "N")));
  }

  // ── (v) `joint` is a tuple count, and it is not the last per-variable row. ─
  // With `missing` no row is dropped, so this is the same 7-of-8 arithmetic as
  // leg (ii) reached by a different verb. Without `joint` the published row is
  // uv's (5 of 7); with `joint` but no `missing` it is 6 of 7. Three separate
  // numbers, so this check cannot be satisfied by the wrong one.
  {
    piet::SessionState s(workdir);
    seed(s);
    (void)exec(kFixU, s);
    auto r = exec("distinct ug uv, joint missing\n", s);
    check(firstError(r.blocks).is_null(),
          "AER-UTIL/counts (v): `distinct ug uv, joint missing` runs clean. Got `" +
              errText(firstError(r.blocks)) + "`");
    check(rOf(s, "ndistinct") == 7.0,
          "AER-UTIL/counts (v): r(ndistinct) == 7 over the (ug,uv) tuples. 5 = uv's own row (a "
          "`joint` that was parsed and dropped), 6 = joint with the missing row excluded. Got " +
              fullPrec(rOf(s, "ndistinct")));
    check(rOf(s, "N") == 8.0,
          "AER-UTIL/counts (v): ...over all 8 rows, because `missing` keeps row 3. Got " +
              fullPrec(rOf(s, "N")));
  }

  // ── (vi) `mdesc` publishes the MISSING count, not its complement. ──────────
  // uv is 1 missing of 8 = 12.5%, and 12.5 is exact in binary so it can be
  // compared with ==. The two wrong answers are 7 (the non-missing count, which
  // renders a table of exactly the same shape) and 14.2857... (a percent taken
  // over the non-missing denominator).
  {
    piet::SessionState s(workdir);
    seed(s);
    (void)exec(kFixU, s);
    auto r = exec("mdesc uv\n", s);
    check(firstError(r.blocks).is_null(),
          "AER-UTIL/counts (vi): `mdesc uv` runs clean. Got `" +
              errText(firstError(r.blocks)) + "`");
    check(rOf(s, "miss") == 1.0,
          "AER-UTIL/counts (vi): r(miss) == 1 -- the MISSING count. 7, the complement, renders an "
          "identically shaped table and is the reading this leg exists to fail. Got " +
              fullPrec(rOf(s, "miss")));
    check(rOf(s, "total") == 8.0,
          "AER-UTIL/counts (vi): ...r(total) == 8, all rows. Got " + fullPrec(rOf(s, "total")));
    check(rOf(s, "percent") == 12.5,
          "AER-UTIL/counts (vi): ...and r(percent) == 12.5, which is 1/8 as a PERCENT over the "
          "full denominator. 0.125 is the fraction, 14.285714285714286 is the percent over the "
          "non-missing denominator; 12.5 is exact in binary, so == is safe here. Got " +
              fullPrec(rOf(s, "percent")));
  }

  // ── (vii) `missings report` lists only variables that HAVE missing. ────────
  // Rows carrying a missing: 3 and 5 -- two. Per-variable counts: uv 1, uw 2 --
  // three. The fixture's overlap on row 3 is what makes those two numbers
  // differ, so "2 observations" cannot be produced by adding the table up. And
  // ug, which has none, must not appear at all: a report that tabulated every
  // variable is the other half of this row's contract.
  {
    piet::SessionState s(workdir);
    seed(s);
    (void)exec(kFixU, s);
    auto r = exec("missings report\n", s);
    check(firstError(r.blocks).is_null(),
          "AER-UTIL/counts (vii): `missings report` runs clean. Got `" +
              errText(firstError(r.blocks)) + "`");
    const std::string txt = renderText(r.blocks);
    check(has(txt, "2 observations with missing values"),
          "AER-UTIL/counts (vii): the observation line reads 2 -- rows 3 and 5. 3 is the sum of "
          "the per-variable counts (uv 1 + uw 2), which double-counts row 3, and it is the number "
          "a report that added its own table up prints. Got `" + txt + "`");
    check(has(txt, "uv") && has(txt, "uw"),
          "AER-UTIL/counts (vii): ...and both variables that HAVE missing appear in the table. "
          "Got `" + txt + "`");
    check(!has(txt, "ug"),
          "AER-UTIL/counts (vii): ...and ug, which has none, does NOT -- this row reports "
          "missingness, it does not enumerate the frame. Got `" + txt + "`");
  }

  // ── (viii) `missings tag` writes a rowmiss COUNT, not an indicator. ────────
  // rowmiss over (ug,uv,uw) is 0 0 2 0 1 0 0 0. sum 3 and max 2 are two
  // independent statements: an any-missing INDICATOR sums to 2 and maxes at 1,
  // so it fails both, and a rowmiss over only the first variable sums to 0.
  {
    piet::SessionState s(workdir);
    seed(s);
    (void)exec(kFixU, s);
    auto r = exec("missings tag, generate(mtag)\n", s);
    check(firstError(r.blocks).is_null(),
          "AER-UTIL/counts (viii): `missings tag, generate(mtag)` runs clean. Got `" +
              errText(firstError(r.blocks)) + "`");
    const double sm = runR(s, "summarize mtag", "sum");
    check(sm == 3.0,
          "AER-UTIL/counts (viii): mtag sums to 3 -- one missing on row 5 and TWO on row 3. An "
          "any-missing indicator sums to 2 over the same frame and is a column that lists "
          "correctly. Got " + fullPrec(sm));
    const double mx = runR(s, "summarize mtag", "max");
    check(mx == 2.0,
          "AER-UTIL/counts (viii): ...and its maximum is 2, which no indicator can reach. Got " +
              fullPrec(mx));
    check(displayText(exec("display \"U8A=\" mtag[3]\n", s).blocks, "U8A=") == "2",
          "AER-UTIL/counts (viii): ...mtag[3] == 2 (uv and uw both missing there). Got `" +
              displayText(exec("display \"U8A=\" mtag[3]\n", s).blocks, "U8A=") + "`");
    check(displayText(exec("display \"U8B=\" mtag[1]\n", s).blocks, "U8B=") == "0",
          "AER-UTIL/counts (viii): ...and mtag[1] == 0 -- ZERO, not missing. A tag column that "
          "left the clean rows empty has the same sum and the same max. Got `" +
              displayText(exec("display \"U8B=\" mtag[1]\n", s).blocks, "U8B=") + "`");
  }

  // FIXTURE M -- three rows, for the two DROP sub-verbs. Built so that
  // "missing in EVERY observation" and "missing in SOME observation" pick out
  // different variables, and "all variables missing" and "any variable missing"
  // pick out different rows:
  //
  //     row : 1  2  3
  //     ma  : 1  2  .
  //     mb  : .  2  .
  //     mc  : .  .  .
  static const char* kFixM =
      "clear\n"
      "set obs 3\n"
      "gen ma = _n\n"
      "replace ma = . in 3\n"
      "gen mb = ma\n"
      "replace mb = . in 1\n"
      "gen mc = ma\n"
      "replace mc = . in 1/3\n";

  // ── (ix) `missings dropvars` drops the ALL-missing variables only. ─────────
  {
    piet::SessionState s(workdir);
    seed(s);
    (void)exec(kFixM, s);
    // The fixture is a changed dataset: missings wants `force` then (matches
    // missings' behaviour, identified from its ado)
    // (w2d_uncovered.log missings_dropvars_ctl r(4), _force rc 0).
    auto r = exec("missings dropvars, force\n", s);
    check(firstError(r.blocks).is_null(),
          "AER-UTIL/counts (ix): `missings dropvars` runs clean. Got `" +
              errText(firstError(r.blocks)) + "`");
    const std::vector<std::string> vn = varNames(s);
    check(!hasName(vn, "mc"),
          "AER-UTIL/counts (ix): mc -- missing in every observation -- is GONE. A handler that "
          "dropped nothing leaves all three and says nothing about it. Got `" + joinNames(vn) +
              "`");
    check(hasName(vn, "ma") && hasName(vn, "mb"),
          "AER-UTIL/counts (ix): ...and ma and mb, which are missing in SOME observations, "
          "SURVIVE. An any-missing reading drops the whole frame here, which is silent data loss "
          "under rc 0. Got `" + joinNames(vn) + "`");
    check(nRows(s) == 3.0,
          "AER-UTIL/counts (ix): ...and no OBSERVATION was dropped -- dropvars is not dropobs. "
          "Got " + fullPrec(nRows(s)));
  }

  // ── (x) `missings dropobs` drops rows where EVERY variable is missing. ─────
  // Row 3 only. Row 1 has ma == 1 and must survive; an any-missing reading
  // keeps row 2 alone and pins _N == 1, which is a frame that still lists.
  {
    piet::SessionState s(workdir);
    seed(s);
    (void)exec(kFixM, s);
    auto r = exec("missings dropobs, force\n", s);  // missings requires force here, as (ix)
    check(firstError(r.blocks).is_null(),
          "AER-UTIL/counts (x): `missings dropobs` runs clean. Got `" +
              errText(firstError(r.blocks)) + "`");
    check(nRows(s) == 2.0,
          "AER-UTIL/counts (x): TWO rows survive -- only row 3 is missing in every variable. An "
          "any-missing reading leaves 1 (row 2 alone) and an all-of-nothing reading leaves 3. Got " +
              fullPrec(nRows(s)));
    const std::vector<std::string> vn = varNames(s);
    check(hasName(vn, "mc"),
          "AER-UTIL/counts (x): ...and mc is still THERE -- dropobs drops observations, not "
          "variables. Got `" + joinNames(vn) + "`");
  }

  fs::remove_all(workdir, ec);
}


void testAerUtilRenameLabel() {
  std::printf("[selftest] --- AER-SCOPE1 bundle I: renvarlab / labmask / splitvallabels ---\n");
  namespace fs = std::filesystem;
  std::string workdir =
      (fs::temp_directory_path() / "piet_native_selftest_aerutilrenlab").u8string();
  std::error_code ec;
  fs::remove_all(workdir, ec);
  fs::create_directories(workdir, ec);

  auto exec = [](const std::string& src, piet::SessionState& session) {
    return piet::doexec::executeDoSource(src, session, piet::dispatch);
  };
  auto seed = [&](piet::SessionState& s) {
    s.eval.cwd = workdir;
    s.cwd = workdir;  // resolveUserPath reads THIS field (handlers.cpp:2040).
  };
  auto firstError = [](const nlohmann::ordered_json& blocks) -> nlohmann::ordered_json {
    for (const auto& b : blocks)
      if (b.is_object() && b.value("type", std::string()) == "error") return b;
    return nlohmann::ordered_json();
  };
  auto errText = [](const nlohmann::ordered_json& e) {
    return e.is_object() ? e.value("message", std::string()) : std::string("<none>");
  };
  auto fullPrec = [](double v) {
    char buf[48];
    std::snprintf(buf, sizeof(buf), "%.17g", v);
    return std::string(buf);
  };
  auto has = [](const std::string& hay, const std::string& needle) {
    return hay.find(needle) != std::string::npos;
  };
  auto rOf = [](piet::SessionState& s, const char* key) -> double {
    const double* p = s.eval.rValues.find(key);
    return p ? *p : std::nan("");
  };
  auto runR = [&](piet::SessionState& s, const std::string& cmd, const char* key) -> double {
    (void)piet::dispatch(cmd, s);
    return rOf(s, key);
  };
  auto varNames = [](piet::SessionState& s) {
    std::vector<std::string> out;
    const nlohmann::ordered_json blocks = piet::dispatch("describe", s);
    for (const auto& b : blocks)
      if (b.is_object() && b.value("type", std::string()) == "describe" && b.contains("variables"))
        for (const auto& v : b["variables"]) out.push_back(v.value("name", std::string()));
    return out;
  };
  auto hasName = [](const std::vector<std::string>& v, const std::string& n) {
    return std::find(v.begin(), v.end(), n) != v.end();
  };
  auto joinNames = [](const std::vector<std::string>& v) {
    std::string s;
    for (const auto& n : v) { if (!s.empty()) s += " "; s += n; }
    return s.empty() ? std::string("<none>") : s;
  };
  // The attached value label, read straight off the session rather than out of
  // a rendered `label list`: this is the store every downstream consumer reads,
  // and a labmask that printed a correct listing without attaching anything is
  // exactly the wrong implementation worth catching.
  auto labelOf = [](piet::SessionState& s, const std::string& var, int code) -> std::string {
    auto it = s.valueLabels.find(var);
    if (it == s.valueLabels.end()) return std::string("<no label attached>");
    auto jt = it->second.find(code);
    return jt == it->second.end() ? std::string("<no such code>") : jt->second;
  };

  // FIXTURE R -- four rows, two numeric columns with DIFFERENT sums so a
  // rename can be told from a copy of the neighbour:
  //     ra : 1  2  3  4      (sum 10)
  //     rb : 10 2  3  4      (sum 19)
  static const char* kFixR =
      "clear\n"
      "set obs 4\n"
      "gen ra = _n\n"
      "gen rb = _n\n"
      "replace rb = 10 in 1\n";

  // ── (i) `renvarlab, prefix()` renames and carries the DATA. ────────────────
  {
    piet::SessionState s(workdir);
    seed(s);
    (void)exec(kFixR, s);
    auto r = exec("renvarlab ra rb, prefix(z_)\n", s);
    check(firstError(r.blocks).is_null(),
          "AER-UTIL/renlab (i): `renvarlab ra rb, prefix(z_)` runs clean. Got `" +
              errText(firstError(r.blocks)) + "`");
    const std::vector<std::string> vn = varNames(s);
    check(hasName(vn, "z_ra") && hasName(vn, "z_rb"),
          "AER-UTIL/renlab (i): both targets exist under the prefixed names. Got `" +
              joinNames(vn) + "`");
    check(!hasName(vn, "ra") && !hasName(vn, "rb"),
          "AER-UTIL/renlab (i): ...and the ORIGINALS are gone. A `rename` that cloned instead of "
          "renaming leaves four columns, doubles the frame's width on every call, and answers "
          "rc 0. Got `" + joinNames(vn) + "`");
    const double s1 = runR(s, "summarize z_rb", "sum");
    check(s1 == 19.0,
          "AER-UTIL/renlab (i): ...and z_rb carries rb's data (10+2+3+4). 10 would mean it "
          "carries ra's, which is what a rename loop that walked the varlist and the target list "
          "out of step produces. Got " + fullPrec(s1));
    const double n1 = runR(s, "summarize z_ra", "N");
    check(n1 == 4.0,
          "AER-UTIL/renlab (i): ...and z_ra is a real column of four values, not a freshly "
          "created empty one. Got N " + fullPrec(n1));
  }

  // ── (ii) `upper` is the case transform, applied to the NAME. ───────────────
  {
    piet::SessionState s(workdir);
    seed(s);
    (void)exec(kFixR, s);
    auto r = exec("renvarlab ra, upper\n", s);
    check(firstError(r.blocks).is_null(),
          "AER-UTIL/renlab (ii): `renvarlab ra, upper` runs clean. Got `" +
              errText(firstError(r.blocks)) + "`");
    const std::vector<std::string> vn = varNames(s);
    check(hasName(vn, "RA") && !hasName(vn, "ra"),
          "AER-UTIL/renlab (ii): ra became RA. Got `" + joinNames(vn) + "`");
    check(hasName(vn, "rb"),
          "AER-UTIL/renlab (ii): ...and rb, which was not in the varlist, was NOT touched -- a "
          "transform that defaulted to _all when a varlist WAS given renames the whole frame. "
          "Got `" + joinNames(vn) + "`");
    check(runR(s, "summarize RA", "sum") == 10.0,
          "AER-UTIL/renlab (ii): ...and RA still holds 1+2+3+4. Got " +
              fullPrec(runR(s, "summarize RA", "sum")));
  }

  // ── (iii) a colliding target aborts the WHOLE call, before anything moves. ─
  // p1 -> p1_x is free; p2 -> p2_x is taken. The plan's contract is that every
  // target is validated before the first `rename` runs, and this leg is the only
  // thing that tells that apart from a sequential loop: the sequential loop
  // renames p1 successfully, then fails, and leaves a frame with p1_x and p2 in
  // it -- half-applied, rc non-zero, and no way for a caller to undo it. Worse
  // still is a loop that validates nothing: p2 overwrites p2_x and 99*4 = 396
  // becomes 19.
  {
    piet::SessionState s(workdir);
    seed(s);
    (void)exec("clear\n"
               "set obs 4\n"
               "gen p1 = _n\n"
               "gen p2 = _n\n"
               "replace p2 = 10 in 1\n"
               "gen p2_x = 99\n",
               s);
    auto r = exec("renvarlab p1 p2, suffix(_x)\n", s);
    const nlohmann::ordered_json e = firstError(r.blocks);
    check(!e.is_null(),
          "AER-UTIL/renlab (iii): `renvarlab p1 p2, suffix(_x)` REFUSES -- p2_x already exists");
    const std::vector<std::string> vn = varNames(s);
    check(hasName(vn, "p1") && hasName(vn, "p2"),
          "AER-UTIL/renlab (iii): ...and NOTHING moved: both source names are still there. A "
          "sequential loop renames p1 first and leaves the frame half-transformed under a "
          "non-zero rc, which no caller can unwind. Got `" + joinNames(vn) + "`");
    check(!hasName(vn, "p1_x"),
          "AER-UTIL/renlab (iii): ...so p1_x does not exist. This is the check the error code "
          "alone cannot make. Got `" + joinNames(vn) + "`");
    check(runR(s, "summarize p2_x", "sum") == 396.0,
          "AER-UTIL/renlab (iii): ...and p2_x still holds its own data (99*4). 19 here means p2 "
          "overwrote it -- silent data loss, and the reason targets are validated up front. Got " +
              fullPrec(runR(s, "summarize p2_x", "sum")));
  }

  // FIXTURE L -- four rows, a code column and the text that names each code:
  //     lcode : 1      1      2      2
  //     ltext : alpha  alpha  beta   beta
  static const char* kFixL =
      "clear\n"
      "set obs 4\n"
      "gen lcode = 1\n"
      "replace lcode = 2 in 3/4\n"
      "gen str6 ltext = \"alpha\"\n"
      "replace ltext = \"beta\" in 3/4\n";

  // ── (iv) `labmask` attaches the code->text map it synthesised. ─────────────
  {
    piet::SessionState s(workdir);
    seed(s);
    (void)exec(kFixL, s);
    auto r = exec("labmask lcode, values(ltext)\n", s);
    check(firstError(r.blocks).is_null(),
          "AER-UTIL/renlab (iv): `labmask lcode, values(ltext)` runs clean. Got `" +
              errText(firstError(r.blocks)) + "`");
    check(labelOf(s, "lcode", 1) == "alpha",
          "AER-UTIL/renlab (iv): code 1 is labelled `alpha` on lcode itself. Read off "
          "session.valueLabels, which is the store list/browse/coeftable all read -- a labmask "
          "that rendered a correct `label list` without attaching anything passes any check made "
          "against its own output. Got `" + labelOf(s, "lcode", 1) + "`");
    check(labelOf(s, "lcode", 2) == "beta",
          "AER-UTIL/renlab (iv): ...and code 2 is `beta`, so the map is keyed on the CODE and not "
          "on the row index (which would put `alpha` on 2 by way of row 2). Got `" +
              labelOf(s, "lcode", 2) + "`");
    check(s.varLblname.count("lcode") == 1 && s.varLblname.at("lcode") == "lcode",
          "AER-UTIL/renlab (iv): ...under a label set named after the variable, which is the "
          "default when lblname() is absent. Got `" +
              (s.varLblname.count("lcode") ? s.varLblname.at("lcode") : std::string("<none>")) +
              "`");
    const std::string listing = [&] {
      std::string out;
      for (const auto& b : piet::dispatch("label list lcode", s))
        if (b.is_object()) { out += b.value("text", std::string()); out += "\n"; }
      return out;
    }();
    check(has(listing, "alpha") && has(listing, "beta"),
          "AER-UTIL/renlab (iv): ...and `label list lcode` renders both entries -- the second, "
          "independent reader of the same store. Got `" + listing + "`");
  }

  // ── (v) `lblname()` names the set, without moving the attachment. ──────────
  {
    piet::SessionState s(workdir);
    seed(s);
    (void)exec(kFixL, s);
    auto r = exec("labmask lcode, values(ltext) lblname(mymask)\n", s);
    check(firstError(r.blocks).is_null(),
          "AER-UTIL/renlab (v): `labmask lcode, values(ltext) lblname(mymask)` runs clean. Got `" +
              errText(firstError(r.blocks)) + "`");
    check(s.varLblname.count("lcode") == 1 && s.varLblname.at("lcode") == "mymask",
          "AER-UTIL/renlab (v): the set is named `mymask`. An option consumed and ignored leaves "
          "`lcode` here and is invisible in every rendering. Got `" +
              (s.varLblname.count("lcode") ? s.varLblname.at("lcode") : std::string("<none>")) +
              "`");
    check(labelOf(s, "lcode", 2) == "beta",
          "AER-UTIL/renlab (v): ...and the map is still ATTACHED to lcode under that name -- "
          "defining a set and forgetting to attach it is the half-landing shape. Got `" +
              labelOf(s, "lcode", 2) + "`");
  }

  // ── (vi) a code that carries TWO texts is refused, not resolved. ───────────
  // lcode 1 now names both `alpha` (row 1) and `gamma` (row 2). Picking the
  // first or the last seen produces a label that is wrong for half the rows and
  // says nothing about it -- the exact silent-wrong-answer this row exists to
  // avoid, and every downstream table would carry it.
  {
    piet::SessionState s(workdir);
    seed(s);
    (void)exec(kFixL, s);
    (void)exec("replace ltext = \"gamma\" in 2\n", s);
    auto r = exec("labmask lcode, values(ltext)\n", s);
    check(!firstError(r.blocks).is_null(),
          "AER-UTIL/renlab (vi): a code mapping to two different texts is REFUSED. Last-wins "
          "would label half of code 1's rows `gamma` under rc 0");
    check(s.valueLabels.count("lcode") == 0,
          "AER-UTIL/renlab (vi): ...and nothing was attached on the way out. A refusal that had "
          "already written half a label set leaves the frame in the state the refusal claims to "
          "have prevented");
  }

  // ── (vii) a non-integer masked variable is an error. ───────────────────────
  {
    piet::SessionState s(workdir);
    seed(s);
    (void)exec(kFixL, s);
    (void)exec("gen lfrac = 1.5\n", s);
    auto r = exec("labmask lfrac, values(ltext)\n", s);
    check(!firstError(r.blocks).is_null(),
          "AER-UTIL/renlab (vii): a NON-INTEGER variable cannot carry a value label and is "
          "refused. Truncating 1.5 to 1 silently relabels the column");
  }

  // ── (viii) `splitvallabels` breaks on WORD boundaries, not at length(). ────
  // "one two three" under length(8): "one two" is 7 and adding " three" makes
  // 13, so the break is after `two` -- ["one two", "three"]. "four five" is 9,
  // so it breaks into ["four", "five"]. A character split at 8 gives
  // ["one two ", "three"] and ["four fiv", "e"]; no split at all leaves the two
  // originals. All three renderings are a plausible-looking r(relabel).
  {
    piet::SessionState s(workdir);
    seed(s);
    (void)exec("clear\n"
               "set obs 2\n"
               "gen sv = 1\n"
               "replace sv = 2 in 2\n"
               "label define svl 1 \"one two three\" 2 \"four five\"\n"
               "label values sv svl\n",
               s);
    auto r = exec("splitvallabels sv, length(8)\n", s);
    check(firstError(r.blocks).is_null(),
          "AER-UTIL/renlab (viii): `splitvallabels sv, length(8)` runs clean. Got `" +
              errText(firstError(r.blocks)) + "`");
    const std::string rel = s.eval.rStrings.get("relabel", "<unset>");
    check(rel != "<unset>" && !rel.empty(),
          "AER-UTIL/renlab (viii): r(relabel) is published at all -- this command's ENTIRE answer "
          "is that macro, so an empty one is the command not having run. Got `" + rel + "`");
    check(has(rel, "1 \"one two\" \"three\""),
          "AER-UTIL/renlab (viii): ...code 1 splits at the WORD boundary: \"one two\" then "
          "\"three\". A character split at 8 yields \"one two \" (trailing space) and no split at "
          "all yields \"one two three\". Got `" + rel + "`");
    check(has(rel, "2 \"four\" \"five\""),
          "AER-UTIL/renlab (viii): ...and code 2, whose text is 9 characters, splits into two "
          "pieces rather than staying whole -- the length() bound is applied per PIECE. Got `" +
              rel + "`");
  }

  fs::remove_all(workdir, ec);
}


void testAerUtilFillers() {
  std::printf("[selftest] --- AER-SCOPE1 bundle I: carryforward / rangestat / tsspell "
              "(group resets, real windows, original row order) ---\n");
  namespace fs = std::filesystem;
  std::string workdir =
      (fs::temp_directory_path() / "piet_native_selftest_aerutilfill").u8string();
  std::error_code ec;
  fs::remove_all(workdir, ec);
  fs::create_directories(workdir, ec);

  auto exec = [](const std::string& src, piet::SessionState& session) {
    return piet::doexec::executeDoSource(src, session, piet::dispatch);
  };
  auto seed = [&](piet::SessionState& s) {
    s.eval.cwd = workdir;
    s.cwd = workdir;  // resolveUserPath reads THIS field (handlers.cpp:2040).
  };
  auto firstError = [](const nlohmann::ordered_json& blocks) -> nlohmann::ordered_json {
    for (const auto& b : blocks)
      if (b.is_object() && b.value("type", std::string()) == "error") return b;
    return nlohmann::ordered_json();
  };
  auto errText = [](const nlohmann::ordered_json& e) {
    return e.is_object() ? e.value("message", std::string()) : std::string("<none>");
  };
  auto fullPrec = [](double v) {
    char buf[48];
    std::snprintf(buf, sizeof(buf), "%.17g", v);
    return std::string(buf);
  };
  auto displays = [](const auto& blocks) {
    std::vector<std::string> v;
    for (const auto& b : blocks)
      if (b.is_object() && b.value("type", std::string()) == "display")
        v.push_back(b.value("text", std::string()));
    return v;
  };
  auto displayText = [&](const auto& blocks, const std::string& prefix) -> std::string {
    for (const auto& s : displays(blocks))
      if (s.rfind(prefix, 0) == 0) return s.substr(prefix.size());
    return std::string("<no such display line>");
  };
  auto rOf = [](piet::SessionState& s, const char* key) -> double {
    const double* p = s.eval.rValues.find(key);
    return p ? *p : std::nan("");
  };
  auto runR = [&](piet::SessionState& s, const std::string& cmd, const char* key) -> double {
    (void)piet::dispatch(cmd, s);
    return rOf(s, key);
  };
  auto countIf = [&](piet::SessionState& s, const std::string& expr) {
    return runR(s, "count if " + expr, "N");
  };
  auto varNames = [](piet::SessionState& s) {
    std::vector<std::string> out;
    const nlohmann::ordered_json blocks = piet::dispatch("describe", s);
    for (const auto& b : blocks)
      if (b.is_object() && b.value("type", std::string()) == "describe" && b.contains("variables"))
        for (const auto& v : b["variables"]) out.push_back(v.value("name", std::string()));
    return out;
  };
  auto hasName = [](const std::vector<std::string>& v, const std::string& n) {
    return std::find(v.begin(), v.end(), n) != v.end();
  };
  auto joinNames = [](const std::vector<std::string>& v) {
    std::string s;
    for (const auto& n : v) { if (!s.empty()) s += " "; s += n; }
    return s.empty() ? std::string("<none>") : s;
  };

  // FIXTURE C -- six rows, DELIBERATELY NOT SORTED BY THE GROUP VARIABLE:
  //
  //     row : 1  2  3  4  5  6
  //     cg  : 1  2  1  2  1  2
  //     cy  : 3  .  .  7  .  .
  //     cs  : aa "" "" "" "" ""
  //
  // The interleave is the whole point. Group 1's rows are 1,3,5 and group 2's
  // are 2,4,6, so a handler that sorts internally and writes back positionally
  // lands its answers on the wrong rows while still producing a column with the
  // right SUM -- which is why the per-row reads below exist and the sum alone
  // would not have been enough.
  static const char* kFixC =
      "clear\n"
      "set obs 6\n"
      "gen cg = 1\n"
      "replace cg = 2 in 2\n"
      "replace cg = 2 in 4\n"
      "replace cg = 2 in 6\n"
      "gen cy = 3\n"
      "replace cy = . in 2\n"
      "replace cy = . in 3\n"
      "replace cy = 7 in 4\n"
      "replace cy = . in 5\n"
      "replace cy = . in 6\n"
      "gen str5 cs = \"aa\"\n"
      "replace cs = \"\" in 2/6\n";

  // ── (i) `carryforward, by()` resets at the group and keeps ROW ORDER. ──────
  // Correct answer, in original row order: 3 . 3 7 3 7.
  //   * a fill with no grouping at all gives 3 3 3 7 7 7 -- no missing, sum 30;
  //   * a fill that sorted by cg and wrote back positionally gives 3 3 3 . 7 7
  //     -- FIVE non-missing and sum 23, identical to the correct answer on both
  //     summary statistics, and wrong on rows 2 and 4;
  //   * a back-fill gives 3 7 3 7 3 7.
  {
    piet::SessionState s(workdir);
    seed(s);
    (void)exec(kFixC, s);
    auto r = exec("carryforward cy, gen(cf) by(cg)\n", s);
    check(firstError(r.blocks).is_null(),
          "AER-UTIL/fill (i): `carryforward cy, gen(cf) by(cg)` runs clean. Got `" +
              errText(firstError(r.blocks)) + "`");
    check(displayText(exec("display \"F1A=\" cf[1]\n", s).blocks, "F1A=") == "3",
          "AER-UTIL/fill (i): cf[1] == 3 -- group 1's own first value. Got `" +
              displayText(exec("display \"F1A=\" cf[1]\n", s).blocks, "F1A=") + "`");
    check(displayText(exec("display \"F1B=\" cf[2]\n", s).blocks, "F1B=") == ".",
          "AER-UTIL/fill (i): cf[2] is MISSING. Row 2 is group 2's first observation and it is "
          "missing, so there is nothing to carry: this is the boundary a leaking fill crosses to "
          "put group 1's 3 there, and the leak reads as a perfectly ordinary value. Got `" +
              displayText(exec("display \"F1B=\" cf[2]\n", s).blocks, "F1B=") + "`");
    check(displayText(exec("display \"F1C=\" cf[3]\n", s).blocks, "F1C=") == "3",
          "AER-UTIL/fill (i): cf[3] == 3 -- carried from row 1, SKIPPING row 2, which belongs to "
          "the other group. Got `" +
              displayText(exec("display \"F1C=\" cf[3]\n", s).blocks, "F1C=") + "`");
    check(displayText(exec("display \"F1D=\" cf[4]\n", s).blocks, "F1D=") == "7",
          "AER-UTIL/fill (i): cf[4] == 7 -- row 4's own value, untouched. A sorted-and-not-restored "
          "handler puts MISSING here, which is the failure this per-row read exists for: its "
          "column has the same N and the same sum as the correct one. Got `" +
              displayText(exec("display \"F1D=\" cf[4]\n", s).blocks, "F1D=") + "`");
    check(displayText(exec("display \"F1E=\" cf[5]\n", s).blocks, "F1E=") == "3",
          "AER-UTIL/fill (i): cf[5] == 3 -- group 1 again, three rows after its source. Got `" +
              displayText(exec("display \"F1E=\" cf[5]\n", s).blocks, "F1E=") + "`");
    check(displayText(exec("display \"F1F=\" cf[6]\n", s).blocks, "F1F=") == "7",
          "AER-UTIL/fill (i): cf[6] == 7 -- group 2's carry. Got `" +
              displayText(exec("display \"F1F=\" cf[6]\n", s).blocks, "F1F=") + "`");
    const double nn = runR(s, "summarize cf", "N");
    check(nn == 5.0,
          "AER-UTIL/fill (i): ...five non-missing in all. An ungrouped fill has six. Got " +
              fullPrec(nn));
    const double sm = runR(s, "summarize cf", "sum");
    check(sm == 23.0,
          "AER-UTIL/fill (i): ...summing to 23 (3+3+7+3+7). An ungrouped fill sums to 30. Got " +
              fullPrec(sm));
    check(displayText(exec("display \"F1G=\" cy[2]\n", s).blocks, "F1G=") == ".",
          "AER-UTIL/fill (i): ...and the SOURCE column is untouched -- gen() writes a new column, "
          "it does not fill in place. Got `" +
              displayText(exec("display \"F1G=\" cy[2]\n", s).blocks, "F1G=") + "`");
  }

  // ── (ii) a string/factor column propagates too. ────────────────────────────
  // cs is "aa" on row 1 and empty everywhere else. Group 1 (rows 1,3,5) fills
  // to "aa"; group 2 (rows 2,4,6) never sees a non-empty value and stays empty.
  // A handler that only knows the f64 plane writes an all-empty column here and
  // is invisible in every numeric check above.
  {
    piet::SessionState s(workdir);
    seed(s);
    (void)exec(kFixC, s);
    auto r = exec("carryforward cs, gen(cfs) by(cg)\n", s);
    check(firstError(r.blocks).is_null(),
          "AER-UTIL/fill (ii): `carryforward cs, gen(cfs) by(cg)` runs clean over a STRING "
          "column. Got `" + errText(firstError(r.blocks)) + "`");
    const double n3 = countIf(s, "cfs == \"aa\"");
    check(n3 == 3.0,
          "AER-UTIL/fill (ii): three rows carry \"aa\" -- group 1's rows 1, 3 and 5. 1 means the "
          "factor plane was never propagated; 6 means the group reset was skipped on this plane "
          "even though it holds on the numeric one. Got " + fullPrec(n3));
  }

  // ── (iii) `bysort cg:` and an explicit `by(cg)` are the same command. ──────
  // The prefix SORTS the frame (dispatcher.cpp, the bundle-I by-prefix branch),
  // so row order is not comparable across the two forms and the assertions here
  // are deliberately order-free: what must agree is which rows got which value.
  {
    piet::SessionState s(workdir);
    seed(s);
    (void)exec(kFixC, s);
    auto r = exec("bysort cg: carryforward cy, gen(cf)\n", s);
    check(firstError(r.blocks).is_null(),
          "AER-UTIL/fill (iii): `bysort cg: carryforward cy, gen(cf)` runs clean -- the prefix "
          "reaches the handler with by() injected, the way egen's does. Got `" +
              errText(firstError(r.blocks)) + "`");
    check(countIf(s, "cg == 1 & cf == 3") == 3.0,
          "AER-UTIL/fill (iii): all three of group 1's rows carry 3. Got " +
              fullPrec(countIf(s, "cg == 1 & cf == 3")));
    check(countIf(s, "cg == 2 & cf == 7") == 2.0,
          "AER-UTIL/fill (iii): ...two of group 2's carry 7. Got " +
              fullPrec(countIf(s, "cg == 2 & cf == 7")));
    check(countIf(s, "cg == 2 & missing(cf)") == 1.0,
          "AER-UTIL/fill (iii): ...and exactly one of group 2's is still missing -- its earliest "
          "row, which had nothing before it. If the prefix had NOT reset at the boundary this is "
          "0 and every other count above still agrees. Got " +
              fullPrec(countIf(s, "cg == 2 & missing(cf)")));
    check(runR(s, "summarize cf", "sum") == 23.0,
          "AER-UTIL/fill (iii): ...and the total matches the explicit-by() form's 23. Got " +
              fullPrec(runR(s, "summarize cf", "sum")));
  }

  // ── (iv) plain `by cg:` SORTS as well, and answers. ───────────────────────
  // Real Stata refuses a plain `by:` over unsorted data at r(5). Replicating
  // that needs a sortedness oracle PIET does not expose to the dispatcher (the
  // `sorted_by` claim lives in the .hbin header), so the landed branch sorts for
  // both spellings -- and for these two order-dependent verbs that is the safe
  // direction, because running them unsorted produces a different, entirely
  // plausible answer. So the assertion here is the ANSWER, not a refusal: a
  // test demanding r(5) would be asserting behaviour the tree deliberately does
  // not have.
  {
    piet::SessionState s(workdir);
    seed(s);
    (void)exec(kFixC, s);
    auto r = exec("by cg: carryforward cy, gen(cf)\n", s);
    check(firstError(r.blocks).is_null(),
          "AER-UTIL/fill (iv): plain `by cg: carryforward cy, gen(cf)` over UNSORTED data runs "
          "clean rather than refusing. Got `" + errText(firstError(r.blocks)) + "`");
    check(countIf(s, "cg == 1 & cf == 3") == 3.0 && countIf(s, "cg == 2 & cf == 7") == 2.0 &&
              countIf(s, "cg == 2 & missing(cf)") == 1.0,
          "AER-UTIL/fill (iv): ...and it produces the SORTED-AND-CORRECT answer, identical to the "
          "bysort form's. Reaching the handler without sorting would carry values across group "
          "boundaries in row order and answer rc 0. Got g1==3 " +
              fullPrec(countIf(s, "cg == 1 & cf == 3")) + " g2==7 " +
              fullPrec(countIf(s, "cg == 2 & cf == 7")) + " g2 missing " +
              fullPrec(countIf(s, "cg == 2 & missing(cf)")));
  }

  // FIXTURE W -- six rows, two panels, years INTERLEAVED so the answer column
  // has to be put back in the frame's own order:
  //
  //     row   : 1     2     3     4     5     6
  //     rid   : 1     2     1     1     2     1
  //     ryear : 2002  2001  2000  2003  2000  2001
  //     rv    : 3     6     1     4     5     2
  static const char* kFixW =
      "clear\n"
      "set obs 6\n"
      "gen rid = 1\n"
      "replace rid = 2 in 2\n"
      "replace rid = 2 in 5\n"
      "gen ryear = 2002\n"
      "replace ryear = 2001 in 2\n"
      "replace ryear = 2000 in 3\n"
      "replace ryear = 2003 in 4\n"
      "replace ryear = 2000 in 5\n"
      "replace ryear = 2001 in 6\n"
      "gen rv = 3\n"
      "replace rv = 6 in 2\n"
      "replace rv = 1 in 3\n"
      "replace rv = 4 in 4\n"
      "replace rv = 5 in 5\n"
      "replace rv = 2 in 6\n";

  // ── (v) `rangestat` computes over a WINDOW, in original row order. ────────
  // interval(ryear -1 1) is the closed window [year-1, year+1] within rid, the
  // row itself included. Hand-computed, per original row:
  //     row 1 (1,2002): 2001+2002+2003 = 2+3+4 = 9
  //     row 2 (2,2001): 2000+2001      = 5+6   = 11
  //     row 3 (1,2000): 2000+2001      = 1+2   = 3
  //     row 4 (1,2003): 2002+2003      = 3+4   = 7
  //     row 5 (2,2000): 2000+2001      = 5+6   = 11
  //     row 6 (1,2001): 2000+2001+2002 = 1+2+3 = 6
  // The by-GROUP sum -- the aggregate a window-blind handler produces -- is 10
  // for every rid-1 row and 11 for every rid-2 row, so it differs on four of the
  // six rows and totals 62 against 47. And a handler that computed the right
  // window in sorted order and wrote back positionally puts 3 on row 1.
  {
    piet::SessionState s(workdir);
    seed(s);
    (void)exec(kFixW, s);
    auto r = exec("rangestat (sum) rv, interval(ryear -1 1) by(rid)\n", s);
    check(firstError(r.blocks).is_null(),
          "AER-UTIL/fill (v): `rangestat (sum) rv, interval(ryear -1 1) by(rid)` runs clean. Got `" +
              errText(firstError(r.blocks)) + "`");
    check(hasName(varNames(s), "rv_sum"),
          "AER-UTIL/fill (v): ...creating `rv_sum` off the default <var>_<stat> naming. Got `" +
              joinNames(varNames(s)) + "`");
    check(displayText(exec("display \"F5A=\" rv_sum[1]\n", s).blocks, "F5A=") == "9",
          "AER-UTIL/fill (v): rv_sum[1] == 9 (2+3+4). The by-group aggregate is 10 here and the "
          "sorted-order-write-back is 3 -- three different plausible columns, and this is the "
          "row that separates all three. Got `" +
              displayText(exec("display \"F5A=\" rv_sum[1]\n", s).blocks, "F5A=") + "`");
    check(displayText(exec("display \"F5B=\" rv_sum[3]\n", s).blocks, "F5B=") == "3",
          "AER-UTIL/fill (v): rv_sum[3] == 3 (1+2) -- an END row of its panel's year range, where "
          "the window is truncated and the group aggregate (10) is not. Got `" +
              displayText(exec("display \"F5B=\" rv_sum[3]\n", s).blocks, "F5B=") + "`");
    check(displayText(exec("display \"F5C=\" rv_sum[4]\n", s).blocks, "F5C=") == "7",
          "AER-UTIL/fill (v): rv_sum[4] == 7 (3+4) -- the other end. Got `" +
              displayText(exec("display \"F5C=\" rv_sum[4]\n", s).blocks, "F5C=") + "`");
    check(displayText(exec("display \"F5D=\" rv_sum[6]\n", s).blocks, "F5D=") == "6",
          "AER-UTIL/fill (v): rv_sum[6] == 6 (1+2+3) -- a full three-year window that is still "
          "not the panel total. Got `" +
              displayText(exec("display \"F5D=\" rv_sum[6]\n", s).blocks, "F5D=") + "`");
    check(displayText(exec("display \"F5E=\" rv_sum[2]\n", s).blocks, "F5E=") == "11",
          "AER-UTIL/fill (v): rv_sum[2] == 11 -- panel 2, whose two rows are inside one window, so "
          "here the window and the group DO agree. Got `" +
              displayText(exec("display \"F5E=\" rv_sum[2]\n", s).blocks, "F5E=") + "`");
    const double sm = runR(s, "summarize rv_sum", "sum");
    check(sm == 47.0,
          "AER-UTIL/fill (v): ...and the column totals 47. A by-group aggregate totals 62; a "
          "window that forgot to include the row itself totals 23. Got " + fullPrec(sm));
    check(runR(s, "summarize rv_sum", "N") == 6.0,
          "AER-UTIL/fill (v): ...over six non-missing rows -- every row gets a value, because the "
          "window always contains at least the row itself. Got N " +
              fullPrec(runR(s, "summarize rv_sum", "N")));
  }

  // ── (vi) `(mean)` over the same windows, and the answer is not an integer. ─
  // row 3 (1,2000): mean of {1,2} = 1.5; row 4 (1,2003): mean of {3,4} = 3.5.
  // Both are exactly representable, and both differ from panel 1's group mean
  // (2.5) -- so this leg fails a group aggregate on the same rows the sum leg
  // does, through a completely different arithmetic path.
  {
    piet::SessionState s(workdir);
    seed(s);
    (void)exec(kFixW, s);
    auto r = exec("rangestat (mean) rv, interval(ryear -1 1) by(rid)\n", s);
    check(firstError(r.blocks).is_null(),
          "AER-UTIL/fill (vi): `rangestat (mean) rv, interval(ryear -1 1) by(rid)` runs clean. "
          "Got `" + errText(firstError(r.blocks)) + "`");
    const std::string m3 = displayText(exec("display \"F6A=\" rv_mean[3]\n", s).blocks, "F6A=");
    check(m3 == "1.5",
          "AER-UTIL/fill (vi): rv_mean[3] == 1.5 -- the mean of {1,2}, not of panel 1 (2.5) and "
          "not the sum. Got `" + m3 + "`");
    const std::string m4 = displayText(exec("display \"F6B=\" rv_mean[4]\n", s).blocks, "F6B=");
    check(m4 == "3.5",
          "AER-UTIL/fill (vi): rv_mean[4] == 3.5 -- the mean of {3,4}. Got `" + m4 + "`");
  }

  // ── (vii) `tsspell` walks runs of EQUAL VALUE and resets the sequence. ────
  // tt 1..6, tx = 1 1 0 0 1 2. Four spells: [1,2] [3,4] [5] [6].
  //     spell : 1 1 2 2 3 4   (sum 13, max 4)
  //     seq   : 1 2 1 2 1 1   (sum 8)
  //     end   : 0 1 0 1 1 1   (sum 4)
  // A sequence that never resets runs 1..6 and sums to 21; a spell counter that
  // never increments sums to 6; an end flag set only on the last row sums to 1.
  static const char* kFixT =
      "clear\n"
      "set obs 6\n"
      "gen tt = _n\n"
      "gen tx = 1\n"
      "replace tx = 0 in 3/4\n"
      "replace tx = 2 in 6\n"
      "tsset tt\n";
  {
    piet::SessionState s(workdir);
    seed(s);
    (void)exec(kFixT, s);
    auto r = exec("tsspell tx, spell(tsp) seq(tsq) end(tnd)\n", s);
    check(firstError(r.blocks).is_null(),
          "AER-UTIL/fill (vii): `tsspell tx, spell(tsp) seq(tsq) end(tnd)` runs clean. Got `" +
              errText(firstError(r.blocks)) + "`");
    check(runR(s, "summarize tsp", "max") == 4.0,
          "AER-UTIL/fill (vii): FOUR spells -- [1,1] [0,0] [1] [2]. A spell counter that never "
          "increments maxes at 1 and one that started a spell per ROW maxes at 6. Got " +
              fullPrec(runR(s, "summarize tsp", "max")));
    check(runR(s, "summarize tsp", "sum") == 13.0,
          "AER-UTIL/fill (vii): ...and the spell ids sum to 13 (1+1+2+2+3+4), which is the half "
          "that says WHERE the boundaries fell and not just how many there were. Got " +
              fullPrec(runR(s, "summarize tsp", "sum")));
    check(runR(s, "summarize tsq", "sum") == 8.0,
          "AER-UTIL/fill (vii): the within-spell sequence sums to 8 (1+2+1+2+1+1). A sequence "
          "that never reset runs 1..6 and sums to 21 -- a strictly increasing column that lists "
          "perfectly. Got " + fullPrec(runR(s, "summarize tsq", "sum")));
    check(runR(s, "summarize tnd", "sum") == 4.0,
          "AER-UTIL/fill (vii): the end flag fires once per spell -- four. An end flag set only "
          "on the frame's last row sums to 1. Got " +
              fullPrec(runR(s, "summarize tnd", "sum")));
    check(displayText(exec("display \"F7A=\" tsp[5]\n", s).blocks, "F7A=") == "3",
          "AER-UTIL/fill (vii): ...and row 5 is in spell 3 -- the run of 1s that comes AFTER the "
          "run of 0s is a new spell, not a resumption of spell 1. Got `" +
              displayText(exec("display \"F7A=\" tsp[5]\n", s).blocks, "F7A=") + "`");
    check(displayText(exec("display \"F7B=\" tnd[2]\n", s).blocks, "F7B=") == "1",
          "AER-UTIL/fill (vii): ...and row 2 is an END, because row 3 leaves the spell. Got `" +
              displayText(exec("display \"F7B=\" tnd[2]\n", s).blocks, "F7B=") + "`");
  }

  // ── (viii) the bare form writes _spell / _seq / _end. ─────────────────────
  // Read off `describe` rather than through an expression, because the default
  // names begin with an underscore. What this catches is a handler that only
  // ever honours the three renaming options and writes nothing without them.
  {
    piet::SessionState s(workdir);
    seed(s);
    (void)exec(kFixT, s);
    auto r = exec("tsspell tx\n", s);
    check(firstError(r.blocks).is_null(),
          "AER-UTIL/fill (viii): the bare `tsspell tx` runs clean. Got `" +
              errText(firstError(r.blocks)) + "`");
    const std::vector<std::string> vn = varNames(s);
    check(hasName(vn, "_spell") && hasName(vn, "_seq") && hasName(vn, "_end"),
          "AER-UTIL/fill (viii): ...and writes all THREE default columns. One of three is the "
          "shape a half-landed handler ships, and the two missing ones are only noticed by the "
          "next command that reads them. Got `" + joinNames(vn) + "`");
  }

  // ── (ix) a TIME GAP breaks a run of equal values. ─────────────────────────
  // tt = 1, 2, 4 with tx constant at 1. Two spells, because 3 is absent:
  //     spell 1 1 2 / seq 1 2 1 / end 0 1 1.
  // A run-length walk over ROW order sees one spell of three (seq 1 2 3, sum 6)
  // and is indistinguishable from the correct answer on any check that does not
  // put a hole in the time index.
  {
    piet::SessionState s(workdir);
    seed(s);
    (void)exec("clear\n"
               "set obs 3\n"
               "gen tt = _n\n"
               "replace tt = 4 in 3\n"
               "gen tx = 1\n"
               "tsset tt\n",
               s);
    auto r = exec("tsspell tx, spell(gsp) seq(gsq) end(gnd)\n", s);
    check(firstError(r.blocks).is_null(),
          "AER-UTIL/fill (ix): tsspell over a gapped time index runs clean. Got `" +
              errText(firstError(r.blocks)) + "`");
    check(displayText(exec("display \"F9A=\" gsp[3]\n", s).blocks, "F9A=") == "2",
          "AER-UTIL/fill (ix): the observation at t=4 opens a NEW spell even though tx never "
          "changed -- the missing t=3 breaks the run. A row-order walk puts 1 here. Got `" +
              displayText(exec("display \"F9A=\" gsp[3]\n", s).blocks, "F9A=") + "`");
    check(runR(s, "summarize gsq", "sum") == 4.0,
          "AER-UTIL/fill (ix): ...so the sequence is 1 2 1 and sums to 4. A gap-blind walk runs "
          "1 2 3 and sums to 6. Got " + fullPrec(runR(s, "summarize gsq", "sum")));
    check(runR(s, "summarize gnd", "sum") == 2.0,
          "AER-UTIL/fill (ix): ...and two spells means two end flags. Got " +
              fullPrec(runR(s, "summarize gnd", "sum")));
  }

  // ── (x) `cond()` spells a CONDITION, not a run of equal values. ───────────
  // Over the same tx = 1 1 0 0 1 2, `cond(tx == 1)` gives spells [1,2] and [5]:
  // within-spell sequence 1 on two rows and 2 on ONE. The varname form over the
  // same column gives 1 on four rows and 2 on two, so a cond() that was quietly
  // read as a varname separates here. The rows outside every spell are counted
  // by neither check, so this holds whether they are set to 0 or left missing.
  {
    piet::SessionState s(workdir);
    seed(s);
    (void)exec(kFixT, s);
    auto r = exec("tsspell, cond(tx == 1) spell(csp) seq(csq) end(cnd)\n", s);
    check(firstError(r.blocks).is_null(),
          "AER-UTIL/fill (x): `tsspell, cond(tx == 1) ...` runs clean. Got `" +
              errText(firstError(r.blocks)) + "`");
    check(countIf(s, "csq == 1") == 2.0,
          "AER-UTIL/fill (x): TWO spells begin (rows 1 and 5). The varname form over the same "
          "column begins four. Got " + fullPrec(countIf(s, "csq == 1")));
    check(countIf(s, "csq == 2") == 1.0,
          "AER-UTIL/fill (x): ...and only ONE row is second in its spell (row 2). The varname "
          "form has two. Got " + fullPrec(countIf(s, "csq == 2")));
  }

  fs::remove_all(workdir, ec);
}


void testAerUtilRefusals() {
  std::printf("[selftest] --- AER-SCOPE1 bundle I: marksample / filelist / the option and "
              "by()-without-gen() refusals ---\n");
  namespace fs = std::filesystem;
  std::string workdir =
      (fs::temp_directory_path() / "piet_native_selftest_aerutilref").u8string();
  std::error_code ec;
  fs::remove_all(workdir, ec);
  fs::create_directories(workdir, ec);

  auto exec = [](const std::string& src, piet::SessionState& session) {
    return piet::doexec::executeDoSource(src, session, piet::dispatch);
  };
  auto seed = [&](piet::SessionState& s) {
    s.eval.cwd = workdir;
    s.cwd = workdir;  // resolveUserPath reads THIS field (handlers.cpp:2040).
  };
  auto firstError = [](const nlohmann::ordered_json& blocks) -> nlohmann::ordered_json {
    for (const auto& b : blocks)
      if (b.is_object() && b.value("type", std::string()) == "error") return b;
    return nlohmann::ordered_json();
  };
  auto errText = [](const nlohmann::ordered_json& e) {
    return e.is_object() ? e.value("message", std::string()) : std::string("<none>");
  };
  auto errField = [](const nlohmann::ordered_json& e, const std::string& f) {
    return e.is_object() ? e.value(f, std::string()) : std::string("<none>");
  };
  auto fullPrec = [](double v) {
    char buf[48];
    std::snprintf(buf, sizeof(buf), "%.17g", v);
    return std::string(buf);
  };
  auto has = [](const std::string& hay, const std::string& needle) {
    return hay.find(needle) != std::string::npos;
  };
  auto spit = [](const std::string& p, const std::string& bytes) {
    std::ofstream f(cecon::to_native_path(p), std::ios::binary | std::ios::trunc);
    f << bytes;
  };
  auto displays = [](const auto& blocks) {
    std::vector<std::string> v;
    for (const auto& b : blocks)
      if (b.is_object() && b.value("type", std::string()) == "display")
        v.push_back(b.value("text", std::string()));
    return v;
  };
  auto displayValue = [&](const auto& blocks, const std::string& prefix) -> double {
    for (const auto& s : displays(blocks)) {
      if (s.rfind(prefix, 0) != 0) continue;
      try {
        return std::stod(s.substr(prefix.size()));
      } catch (...) {
        return std::nan("");
      }
    }
    return std::nan("");
  };
  auto rOf = [](piet::SessionState& s, const char* key) -> double {
    const double* p = s.eval.rValues.find(key);
    return p ? *p : std::nan("");
  };
  auto runR = [&](piet::SessionState& s, const std::string& cmd, const char* key) -> double {
    (void)piet::dispatch(cmd, s);
    return rOf(s, key);
  };
  auto nRows = [&](piet::SessionState& s) { return runR(s, "count", "N"); };
  auto countIf = [&](piet::SessionState& s, const std::string& expr) {
    return runR(s, "count if " + expr, "N");
  };
  auto varNames = [](piet::SessionState& s) {
    std::vector<std::string> out;
    const nlohmann::ordered_json blocks = piet::dispatch("describe", s);
    for (const auto& b : blocks)
      if (b.is_object() && b.value("type", std::string()) == "describe" && b.contains("variables"))
        for (const auto& v : b["variables"]) out.push_back(v.value("name", std::string()));
    return out;
  };
  auto hasName = [](const std::vector<std::string>& v, const std::string& n) {
    return std::find(v.begin(), v.end(), n) != v.end();
  };
  auto joinNames = [](const std::vector<std::string>& v) {
    std::string s;
    for (const auto& n : v) { if (!s.empty()) s += " "; s += n; }
    return s.empty() ? std::string("<none>") : s;
  };

  // NOTE ON WHAT IS *NOT* IN HERE. The plan's scope table carries three
  // record-linkage names (strdist / matchit / reclink) and two more whose
  // authorship could not be confirmed (dropmiss / renvars). None of the five is
  // in the registry, so each answers a GENERIC r(199) that names no cause. A leg
  // asserting a specific refusal reason for them would be asserting a promise
  // the tree does not make, and it would keep passing after somebody registered
  // them with a different cause. They are absent on purpose.

  // ── (i) `marksample` at the top level refuses. ────────────────────────────
  // The local it reads (`varlist') is set by `syntax', and `syntax' only runs
  // inside a program. Marking every observation instead hands the caller a
  // touse that silently includes the rows they filtered out -- the whole point
  // of the marker being wrong in the direction nobody checks.
  {
    piet::SessionState s(workdir);
    seed(s);
    (void)exec("clear\nset obs 3\ngen q = _n\n", s);
    auto r = exec("marksample touse\n", s);
    const nlohmann::ordered_json e = firstError(r.blocks);
    check(!e.is_null(),
          "AER-UTIL/refuse (i): `marksample touse` at the TOP LEVEL is refused, not honoured");
    check(has(errText(e), "not allowed outside a program"),
          "AER-UTIL/refuse (i): ...and the sentence says why -- `not allowed outside a program`. "
          "A bare `invalid syntax` here reads as a spelling complaint about a command the user "
          "spelled correctly. Got `" + errText(e) + "`");
  }

  // ── (ii) inside a program it marks the NON-MISSING rows of `varlist'. ─────
  // Five rows; mv is missing on row 2 and mz on row 4, disjoint, so the marker
  // selects three. The two wrong answers are 5 (a marker that ignored the
  // varlist and marked everything) and 4 (one that read only the first
  // variable) -- both of which produce a byte column of 0s and 1s that lists
  // perfectly and quietly changes every estimate downstream of it.
  {
    piet::SessionState s(workdir);
    seed(s);
    auto r = exec("clear\n"
                  "set obs 5\n"
                  "gen mv = _n\n"
                  "replace mv = . in 2\n"
                  "gen mz = _n\n"
                  "replace mz = . in 4\n"
                  "program define aer_i_ms\n"
                  "    syntax varlist(min=1)\n"
                  "    marksample touse\n"
                  "    quietly count if `touse'\n"
                  "    display \"AER_I_TOUSE=\" r(N)\n"
                  "end\n"
                  "aer_i_ms mv mz\n",
                  s);
    check(!r.stoppedAtReason.has_value(),
          "AER-UTIL/refuse (ii): the program defining and calling marksample runs to its end. "
          "stop=" + r.stoppedAtReason.value_or("<none>"));
    const double n = displayValue(r.blocks, "AER_I_TOUSE=");
    check(n == 3.0,
          "AER-UTIL/refuse (ii): the touse marker selects THREE rows -- those non-missing in BOTH "
          "of `varlist'. 5 means the varlist was ignored and everything marked; 4 means only the "
          "first variable was read. Got " + fullPrec(n));
  }

  // ── (iii) `novarlist` marks everything, and that is the point of it. ──────
  {
    piet::SessionState s(workdir);
    seed(s);
    auto r = exec("clear\n"
                  "set obs 5\n"
                  "gen mv = _n\n"
                  "replace mv = . in 2\n"
                  "gen mz = _n\n"
                  "replace mz = . in 4\n"
                  "program define aer_i_msn\n"
                  "    syntax varlist(min=1)\n"
                  "    marksample touse, novarlist\n"
                  "    quietly count if `touse'\n"
                  "    display \"AER_I_NOVAR=\" r(N)\n"
                  "end\n"
                  "aer_i_msn mv mz\n",
                  s);
    check(!r.stoppedAtReason.has_value(),
          "AER-UTIL/refuse (iii): the novarlist program runs to its end. stop=" +
              r.stoppedAtReason.value_or("<none>"));
    const double n = displayValue(r.blocks, "AER_I_NOVAR=");
    check(n == 5.0,
          "AER-UTIL/refuse (iii): `novarlist` marks all FIVE rows -- it suppresses the "
          "missing-value screen entirely. 3 here is leg (ii)'s answer, which means the option was "
          "consumed and ignored, and an ignored `novarlist` drops exactly the observations the "
          "caller asked to keep. Got " + fullPrec(n));
  }

  // ── (iv) `filelist` REPLACES the frame with one row per file. ─────────────
  // A directory this leg stages itself, three files of three DIFFERENT sizes so
  // the byte total is a real discriminator: a handler that reported 0, or the
  // same size on every row, agrees with the row count and not with the sum.
  {
    const fs::path fdir = fs::path(workdir) / "fl";
    fs::create_directories(fdir, ec);
    spit((fdir / "a.txt").u8string(), "abc");        // 3 bytes
    spit((fdir / "bb.txt").u8string(), "de");        // 2 bytes
    spit((fdir / "ccc.dat").u8string(), "fghij");    // 5 bytes

    piet::SessionState s(workdir);
    seed(s);
    (void)exec("clear\nset obs 7\ngen zz = _n\n", s);
    auto r = exec("filelist, directory(\"" + fdir.u8string() + "\") norecursive\n", s);
    check(firstError(r.blocks).is_null(),
          "AER-UTIL/refuse (iv): `filelist, directory(...) norecursive` runs clean. Got `" +
              errText(firstError(r.blocks)) + "`");
    check(nRows(s) == 3.0,
          "AER-UTIL/refuse (iv): THREE rows, one per file. Got " + fullPrec(nRows(s)));
    check(!hasName(varNames(s), "zz"),
          "AER-UTIL/refuse (iv): ...and the seven-row frame that was in memory is GONE: this verb "
          "replaces the dataset, it does not append to it. A handler that appended would leave zz "
          "here and pin 10 rows. Got `" + joinNames(varNames(s)) + "`");
    const std::vector<std::string> vn = varNames(s);
    check(hasName(vn, "dirname") && hasName(vn, "filename") && hasName(vn, "fsize"),
          "AER-UTIL/refuse (iv): ...with the three contracted columns. Got `" + joinNames(vn) +
              "`");
    check(countIf(s, "filename == \"a.txt\"") == 1.0 &&
              countIf(s, "filename == \"bb.txt\"") == 1.0 &&
              countIf(s, "filename == \"ccc.dat\"") == 1.0,
          "AER-UTIL/refuse (iv): ...and filename holds the LEAF, once each. A filename column "
          "carrying the full path satisfies the row count and fails every join a caller would "
          "make on it. Got a.txt " + fullPrec(countIf(s, "filename == \"a.txt\"")) + " bb.txt " +
              fullPrec(countIf(s, "filename == \"bb.txt\"")) + " ccc.dat " +
              fullPrec(countIf(s, "filename == \"ccc.dat\"")));
    const double bytes = runR(s, "summarize fsize", "sum");
    check(bytes == 10.0,
          "AER-UTIL/refuse (iv): ...and fsize totals 10 (3+2+5). 0 is a column that was created "
          "and never filled and 9 is one that repeated a single stat() three times; both list as "
          "an ordinary numeric column. Got " + fullPrec(bytes));
  }

  // ── (v) `pattern()` is a glob, and it actually filters. ───────────────────
  {
    const fs::path fdir = fs::path(workdir) / "fl";
    piet::SessionState s(workdir);
    seed(s);
    auto r = exec("filelist, directory(\"" + fdir.u8string() +
                      "\") pattern(\"*.txt\") norecursive\n",
                  s);
    check(firstError(r.blocks).is_null(),
          "AER-UTIL/refuse (v): `filelist, ... pattern(\"*.txt\")` runs clean. Got `" +
              errText(firstError(r.blocks)) + "`");
    check(nRows(s) == 2.0,
          "AER-UTIL/refuse (v): TWO rows -- ccc.dat is excluded. 3 means the option was consumed "
          "and ignored, which is a filter that silently does not filter. Got " +
              fullPrec(nRows(s)));
    check(runR(s, "summarize fsize", "sum") == 5.0,
          "AER-UTIL/refuse (v): ...and the surviving bytes are 3+2, not 3+2+5. Got " +
              fullPrec(runR(s, "summarize fsize", "sum")));
  }

  // ── (vi) `unique ..., by()` with no `gen()` refuses BY NAME. ──────────────
  // by() without gen() has nowhere to put its per-group answer, and Stata's
  // `unique` prints nothing in that form. Printing the ungrouped count instead
  // would answer a question the user did not ask, under rc 0.
  {
    piet::SessionState s(workdir);
    seed(s);
    (void)exec("clear\nset obs 4\ngen ug = 1\nreplace ug = 2 in 3/4\ngen uv = _n\n", s);
    auto r = exec("unique uv, by(ug)\n", s);
    const nlohmann::ordered_json e = firstError(r.blocks);
    check(!e.is_null(),
          "AER-UTIL/refuse (vi): `unique uv, by(ug)` without gen() is refused rather than "
          "silently answered as the ungrouped form");
    check(errField(e, "reason") == "refused:unique_by_without_gen",
          "AER-UTIL/refuse (vi): ...naming its OWN cause, so a caller can tell this apart from a "
          "misspelled option. Got `" + errField(e, "reason") + "`");
  }

  // ── (vii) the two options this arm does not implement are refused BY NAME. ─
  // `unique, detail` and `gunique, replace` change the ANSWER, not its speed --
  // detail adds a per-group listing and replace overwrites the source column.
  // Consuming either and carrying on is the accept-note trap this campaign
  // banned outside the ENV bundle.
  {
    struct Case { const char* cmd; const char* opt; };
    const std::vector<Case> kCases = {
        {"unique uv, detail", "detail"},
        {"gunique uv, replace", "replace"},
    };
    for (const auto& c : kCases) {
      piet::SessionState s(workdir);
      seed(s);
      (void)exec("clear\nset obs 4\ngen uv = _n\n", s);
      auto r = exec(std::string(c.cmd) + "\n", s);
      const nlohmann::ordered_json e = firstError(r.blocks);
      check(!e.is_null(),
            std::string("AER-UTIL/refuse (vii): `") + c.cmd +
                "` is refused rather than quietly accepted");
      check(has(errText(e), c.opt),
            std::string("AER-UTIL/refuse (vii): ...and the sentence NAMES the option (`") + c.opt +
                "`), which is what tells the user which half of their line to drop. Got `" +
                errText(e) + "`");
    }
  }

  fs::remove_all(workdir, ec);
}

// ── AER-SCOPE1 bundle H (ESTIM, 2026-09-05) ──────────────────────────────────
//
// The numeric pins below are ORACLE values, captured from live StataBE 19.5 on
// tests/validate/auto.hbin's own source dataset -- not from this build's output.
// That direction matters: bundle H's specs were verified before implementation
// precisely because a golden captured from the same transcription as the code
// pins the transcription error as the answer. Loosening a tolerance here is
// therefore never the fix; it is the failure mode.
//
// Several of these arms exist because a correction had no other detector. The
// spearman guard pair, the sktest complement-form pin and the centile lower
// bound each caught a real defect while this bundle was being written.
void testAerEstimBundle() {
  std::printf("[selftest] --- AER-SCOPE1 bundle H (ESTIM): areg/ivreg2 + spearman/sktest/"
              "signrank/centile + xi + E3 ---\n");
  namespace fs = std::filesystem;
  std::string workdir = (fs::temp_directory_path() / "piet_native_selftest_aerestim").u8string();
  std::error_code ec;
  fs::remove_all(workdir, ec);
  fs::create_directories(workdir, ec);

  const std::string autoFix = selftestValidateDir() + "/auto.hbin";
  if (!std::ifstream(cecon::to_native_path(autoFix)).good()) {
    skip("AER bundle H (needs tests/validate/auto.hbin)", "fixture not found at " + autoFix);
    return;
  }

  auto rv = [](piet::SessionState& s, const char* k) -> double {
    const double* p = s.eval.rValues.find(k);
    return p ? *p : std::numeric_limits<double>::quiet_NaN();
  };
  auto close = [](double a, double b, double rtol) {
    if (std::isnan(a) || std::isnan(b)) return false;
    const double d = std::fabs(a - b);
    return d <= rtol * std::max(1.0, std::fabs(b));
  };
  auto anyError = [](const auto& blocks) {
    for (const auto& b : blocks)
      if (b.is_object() && b.value("type", std::string()) == "error") return true;
    return false;
  };
  auto firstError = [](const auto& blocks) -> nlohmann::json {
    for (const auto& b : blocks)
      if (b.is_object() && b.value("type", std::string()) == "error") return b;
    return nlohmann::json::object();
  };
  auto displayText = [](const auto& blocks) {
    std::string s;
    for (const auto& b : blocks)
      if (b.is_object() && b.value("type", std::string()) == "display")
        s += b.value("text", std::string());
    return s;
  };

  // (a) spearman -- the auto pin, to full precision.
  {
    piet::SessionState session(workdir);
    (void)piet::dispatch("use " + autoFix + ", clear", session);
    auto out = piet::dispatch("spearman mpg rep78", session);
    check(!anyError(out), "H/spearman: `spearman mpg rep78` runs");
    check(rv(session, "N") == 69.0, "H/spearman: r(N) == 69 (casewise: rep78 has 5 missing)");
    check(close(rv(session, "rho"), 0.3098266801580117, 1e-12),
          "H/spearman: r(rho) == 0.3098266801580117 (StataBE oracle) -- got " +
              std::to_string(rv(session, "rho")));
    check(close(rv(session, "p"), 0.0098023612827953, 1e-9),
          "H/spearman: r(p) == 0.0098023612827953 (StataBE oracle) -- got " +
              std::to_string(rv(session, "p")));
    // p_l and p_u are separate published returns and the whole point of using
    // betaitail rather than 1 - p_l. Pinned independently of p.
    check(close(rv(session, "p_l"), 0.9950988193586023, 1e-9), "H/spearman: r(p_l) oracle");
    check(close(rv(session, "p_u"), 0.0049011806413977, 1e-9), "H/spearman: r(p_u) oracle");
    const std::string t = displayText(out);
    check(t.find("Number of observations =     69") != std::string::npos,
          "H/spearman: display line 1 matches Stata's spacing");
    check(t.find("Spearman's rho = 0.3098") != std::string::npos,
          "H/spearman: display line 2 matches Stata");
    check(t.find("are independent") != std::string::npos, "H/spearman: H0 line present");
  }

  // (b) spearman on a TIE-FREE pair -- the d clamp. Without it, d lands just
  // below zero, sqrt gives NaN, and every downstream quantity including p
  // becomes missing. This arm exists because the rep78 pin above is
  // structurally blind to it: rep78 is heavily tied, so it takes the d > 0
  // branch and passes either way.
  {
    piet::SessionState session(workdir);
    (void)piet::dispatch("use " + autoFix + ", clear", session);
    auto out = piet::dispatch("spearman price weight", session);
    check(!anyError(out), "H/spearman: tie-free pair runs");
    check(!std::isnan(rv(session, "p")),
          "H/spearman: r(p) is NOT missing on a tie-free pair (the d clamp; unclamped this is NaN)");
    check(!std::isnan(rv(session, "rho")), "H/spearman: r(rho) is not missing there either");
  }

  // (c) sktest -- table shape, last-variable r(), and the r(table) matrix that
  // had nowhere to live until this bundle added an r-class matrix store.
  {
    piet::SessionState session(workdir);
    (void)piet::dispatch("use " + autoFix + ", clear", session);
    auto out = piet::dispatch("sktest mpg trunk", session);
    check(!anyError(out), "H/sktest: two-variable form runs");
    check(rv(session, "N") == 74.0, "H/sktest: r(N) is the LAST variable's N");
    check(close(rv(session, "p_skew"), 0.9115468643976649, 1e-9),
          "H/sktest: r(p_skew) is trunk's, not mpg's (StataBE oracle) -- got " +
              std::to_string(rv(session, "p_skew")));
    check(close(rv(session, "chi2"), 4.194021136220797, 1e-9), "H/sktest: r(chi2) oracle");
    const piet::eval::EvalMatrix* tbl = session.eval.findClassMatrix('r', "table");
    check(tbl != nullptr, "H/sktest: r(table) is posted");
    if (tbl != nullptr) {
      check(tbl->data.size() == 2 && tbl->data[0].size() == 5, "H/sktest: r(table) is 2 x 5");
      check(tbl->rownames.size() == 2 && tbl->rownames[0] == "mpg" && tbl->rownames[1] == "trunk",
            "H/sktest: r(table) rownames are the varlist, in order");
      check(tbl->colnames.size() == 5 && tbl->colnames[0] == "N" && tbl->colnames[4] == "p_chi2",
            "H/sktest: r(table) colnames are N p_skew p_kurt chi2 p_chi2");
    }
    const std::string t = displayText(out);
    check(t.find("Skewness and kurtosis tests for normality") != std::string::npos,
          "H/sktest: header matches Stata");
    check(t.find("Prob>chi2") != std::string::npos, "H/sktest: column head matches Stata");
  }

  // (d) sktest's COMPLEMENT form. The literal 2(1 - Phi|Z|) is right to about
  // 1.3e-11 here and 2*Phi(-|Z|) to about 1.1e-14, so only a pin at 1e-9 or
  // tighter can tell them apart -- which is why this arm is separate from the
  // display-level checks above.
  {
    piet::SessionState session(workdir);
    (void)piet::dispatch("use " + autoFix + ", clear", session);
    (void)piet::dispatch("sktest price", session);
    check(close(rv(session, "p_skew"), 1.9901828556006e-06, 1e-9),
          "H/sktest: r(p_skew) for price at rtol 1e-9 -- the literal 1-Phi form misses by "
          "1.3e-11 and trips here; got " + std::to_string(rv(session, "p_skew")));
  }

  // (e) sktest with too few observations is NOT a refusal. Measured on live
  // StataBE: n = 7 returns rc 0 with "." for all four statistics and continues.
  // Implementing the manual's Description prose as an error would abort whole
  // commands that Stata completes.
  {
    piet::SessionState session(workdir);
    (void)piet::dispatch("use " + autoFix + ", clear", session);
    auto out = piet::dispatch("sktest mpg if mpg > 40", session);
    check(!anyError(out), "H/sktest: a too-small sample is rc 0, not an error");
    check(std::isnan(rv(session, "chi2")), "H/sktest: ...and r(chi2) is missing rather than wrong");
    check(displayText(out).find(".") != std::string::npos,
          "H/sktest: ...and the row still prints");
  }

  // (f) centile -- all three centiles and both interval ends. lb_1 is the one
  // that caught the F_0 defect: the manual's boundary is F_{-1} = 0, and
  // zeroing F_0 instead leaves the t search right while making g wrong, moving
  // ONLY this bound (3292.8187 against Stata's 3291.232).
  {
    piet::SessionState session(workdir);
    (void)piet::dispatch("use " + autoFix + ", clear", session);
    auto out = piet::dispatch("centile price, centile(5 50 95)", session);
    check(!anyError(out), "H/centile: runs");
    check(rv(session, "N") == 74.0 && rv(session, "n_cent") == 3.0,
          "H/centile: r(N) and r(n_cent)");
    check(close(rv(session, "c_1"), 3727.75, 1e-9), "H/centile: r(c_1) oracle");
    check(close(rv(session, "c_2"), 5006.5, 1e-9), "H/centile: r(c_2) oracle");
    check(close(rv(session, "c_3"), 13498.0, 1e-9), "H/centile: r(c_3) oracle");
    check(close(rv(session, "lb_1"), 3291.231571513434, 1e-9),
          "H/centile: r(lb_1) == 3291.2316 -- the F_{-1}=0 boundary; F_0=0 gives 3292.8187 and "
          "leaves every OTHER bound correct. Got " + std::to_string(rv(session, "lb_1")));
    check(close(rv(session, "ub_1"), 3914.158992888472, 1e-9), "H/centile: r(ub_1) oracle");
    check(close(rv(session, "lb_2"), 4593.566284952724, 1e-9), "H/centile: r(lb_2) oracle");
    check(close(rv(session, "ub_3"), 15865.30130651407, 1e-9), "H/centile: r(ub_3) oracle");
  }

  // (g) centile's domain is the CLOSED interval [0,100] (StataBE: centile(0) and
  // centile(100) run), so q = 0 and q = 100 run (the sample minimum and
  // maximum, both interval ends held there) and only a value outside [0,100] is
  // refused, as r(125) (w2as_summary_stats_family.log:7871-7877, sx_centile_ref_100
  // `c(101)` -> "invalid numlist has elements outside of allowed range", 125). This
  // pin used to assert that 0 and 100 are refused, an rc the manual never stated.
  {
    piet::SessionState session(workdir);
    (void)piet::dispatch("use " + autoFix + ", clear", session);
    check(!anyError(piet::dispatch("centile price, centile(0)", session)) &&
              rv(session, "c_1") == 3291.0 && rv(session, "lb_1") == 3291.0 &&
              rv(session, "ub_1") == 3291.0,
          "H/centile: q = 0 runs and answers the sample minimum 3291 with both interval ends "
          "held there (StataBE: the centile() domain is [0,100]). Got c_1 " +
              std::to_string(rv(session, "c_1")));
    check(!anyError(piet::dispatch("centile price, centile(100)", session)) &&
              rv(session, "c_1") == 15906.0 && rv(session, "ub_1") == 15906.0,
          "H/centile: q = 100 runs and answers the sample maximum 15906. Got c_1 " +
              std::to_string(rv(session, "c_1")));
    auto out = piet::dispatch("centile price, centile(101)", session);
    check(anyError(out) && firstError(out).value("reason", std::string()) == "r(125)",
          "H/centile: q = 101 is refused as r(125) (w2as_summary_stats_family.log:7872-7877)");
  }

  // (h) areg. absorb() is REQUIRED -- Stata gives r(198), not a silent plain
  // regression, and the rc has to come from the error CODE (syntax_error) since
  // engine_error lands in the generic bucket and reads back as 1.
  {
    piet::SessionState session(workdir);
    (void)piet::dispatch("use " + autoFix + ", clear", session);
    auto bad = piet::dispatch("areg price mpg", session);
    check(anyError(bad), "H/areg: absorb() missing is an error");
    check(firstError(bad).value("code", std::string()) == "syntax_error",
          "H/areg: ...with the code that maps to r(198)");
    auto good = piet::dispatch("areg price mpg, absorb(rep78)", session);
    check(!anyError(good), "H/areg: with absorb() it estimates");
  }

  // (i) xi. The omitted level is the MINIMUM, the label is `v==k`, and `noomit`
  // prints NOTHING -- all three measured on live StataBE.
  {
    piet::SessionState session(workdir);
    (void)piet::dispatch("use " + autoFix + ", clear", session);
    auto out = piet::dispatch("xi i.foreign", session);
    check(!anyError(out), "H/xi: `xi i.foreign` runs");
    piet::Datastore* ds = session.datastore();
    check(ds != nullptr && ds->has("_Iforeign_1"),
          "H/xi: _Iforeign_1 exists (level 1 retained)");
    check(ds != nullptr && !ds->has("_Iforeign_0"),
          "H/xi: _Iforeign_0 does NOT exist -- the MINIMUM level is the omitted one");
    check(displayText(out).find("naturally coded; _Iforeign_0 omitted") != std::string::npos,
          "H/xi: the mapping line names the omitted column");
  }
  {
    piet::SessionState session(workdir);
    (void)piet::dispatch("use " + autoFix + ", clear", session);
    auto out = piet::dispatch("xi, noomit i.foreign", session);
    piet::Datastore* ds = session.datastore();
    check(ds != nullptr && ds->has("_Iforeign_0") && ds->has("_Iforeign_1"),
          "H/xi: noomit keeps BOTH levels");
    check(displayText(out).empty(),
          "H/xi: noomit prints NO mapping line (measured on StataBE, not assumed)");
  }
  {
    piet::SessionState session(workdir);
    (void)piet::dispatch("use " + autoFix + ", clear", session);
    (void)piet::dispatch("xi, prefix(_X) i.foreign", session);
    piet::Datastore* ds = session.datastore();
    check(ds != nullptr && ds->has("_Xforeign_1"), "H/xi: prefix() renames the generated columns");
    check(anyError(piet::dispatch("xi, prefix(_TOOLONG) i.foreign", session)),
          "H/xi: prefix() longer than 4 characters is refused");
  }
  // The prefix form: materialize AND rewrite. `_b[_Iforeign_1]` is only
  // answerable if the rewrite actually happened.
  {
    piet::SessionState session(workdir);
    (void)piet::dispatch("use " + autoFix + ", clear", session);
    auto out = piet::dispatch("xi: regress price i.foreign", session);
    check(!anyError(out), "H/xi: `xi: regress` runs");
    (void)piet::dispatch("scalar h_xib = _b[_Iforeign_1]", session);
    check(session.eval.scalars.get("h_xib", "") != "",
          "H/xi: the wrapped command estimated on the GENERATED column "
          "(_b[_Iforeign_1] resolves)");
  }

  // (j) E3. Registered so the NAME resolves, refused with a cause the route
  // drift guard can tell apart from an unrecognised token. Each name's own
  // selftest_w2_e3<cmd>.cpp now owns its refusal arm (the native task flips it);
  // this leg stays as the cross-name count of eight.
  {
    piet::SessionState session(workdir);
    (void)piet::dispatch("use " + autoFix + ", clear", session);
    static const char* kE3[] = {"lasso logit price mpg",
                                "honestdid, pre(1) post(2)"};
    int refused = 0;
    for (const char* line : kE3) {
      auto blocks = piet::dispatch(line, session);
      const nlohmann::json e = firstError(blocks);
      if (e.value("reason", std::string()) == "refused:e3_deferred") ++refused;
    }
    // Nine since 2026-09-09: `oaxaca` left E3 with AER scope-2 B2 and
    // `teffects` with B2-4 (their legs live in testAerB2Oaxaca /
    // testAerB2Nnmatch). Both keep refusing the parts they do not implement,
    // but with a DIFFERENT named cause -- `refused:oaxaca_threefold_default`,
    // `refused:teffects_ra_unimplemented` -- deliberately not `e3_deferred`,
    // so the route-drift guard can tell "not routed" from "routed and declined".
    // Eight since X2-GLM (2026-10-12): `glm` left E3 for the native fitter
    // (estimation_glm.cpp; its legs live in testW2bGlm), and the forms it does
    // not implement refuse with their own named causes (refused:glm_*).
    // Five since 2026-10-21: `swindex`, `acreg` and `suest` left E3
    // (handlers_e3_{swindex,acreg,suest}.cpp; their legs live in testW2E3Swindex /
    // testW2E3Acreg / testW2E3Suest, oracles w2j_e3_swindex.log, w2j_e3_acreg.log,
    // w2j_e3_builtin.log S_*). Four since: `rlasso` left E3
    // (handlers_e3_lasso.cpp runRlasso; testW2E3Lasso, oracle w2j_e3_rlasso.log).
    // Three since: `ritest` left E3 (handlers_e3_ritest.cpp; testW2E3Ritest,
    // oracle w2j_e3_ritest.log). Two since: `qreg2` left E3 (handlers_e3_qreg2.cpp;
    // testW2E3Qreg2, oracle w2j_e3_qreg2.log).
    check(refused == 2,
          "H/E3: both refuse with reason `refused:e3_deferred` -- got " +
              std::to_string(refused));
  }

  // (k) The engine-backed four, now that H1 has landed. These same lines used to
  // assert a REFUSAL; the flip from 199 to 0 is the signal that the cobra half
  // exists, and the handlers still ask the engine first so an older cobra says
  // so by name.
  {
    piet::SessionState session(workdir);
    (void)piet::dispatch("use " + autoFix + ", clear", session);
    auto out = piet::dispatch("pca price mpg weight length turn", session);
    check(!anyError(out), "H/pca: runs against the H1 engine");
    // Oracle values, live StataBE on auto.dta.
    const double* cond = session.eval.eScalars.find("cond");
    check(cond != nullptr && close(*cond, 9.12262537900241, 1e-9),
          "H/pca: e(cond) == sqrt(lambda_1/lambda_p) == 9.1226 -- the RATIO is 83.22, and "
          "the plan had it as the ratio");
    const double* tr = session.eval.eScalars.find("trace");
    check(tr != nullptr && *tr == 5.0, "H/pca: e(trace) is the integer-snapped 5 for correlation");
    const double* rho = session.eval.eScalars.find("rho");
    check(rho != nullptr && close(*rho, 1.0, 1e-12), "H/pca: e(rho) == 1 when f == p");
    check(session.eval.findClassMatrix('e', "components") != nullptr,
          "H/pca: e(components) is posted (the manual lists it; the plan omitted it)");
    check(session.eval.findClassMatrix('e', "sds") != nullptr,
          "H/pca: e(sds) exists for a CORRELATION pca");
    check(session.eval.eStrings.get("Ctype", "") == "correlation", "H/pca: e(Ctype) macro");
    const piet::eval::EvalMatrix* Ev = session.eval.findClassMatrix('e', "Ev");
    check(Ev != nullptr && Ev->data.size() == 1 && Ev->data[0].size() == 5,
          "H/pca: e(Ev) is 1 x p");
    if (Ev != nullptr)
      check(close(Ev->data[0][0], 3.7762071, 1e-6), "H/pca: leading eigenvalue oracle");
  }
  {
    // Covariance PCA: e(sds) must be ABSENT, and the trace is snapped to an
    // integer 4.6e-8 away from the raw sum -- 46x outside a 1e-9 golden, which
    // is why a naive sum(C_ii) fails there.
    piet::SessionState session(workdir);
    (void)piet::dispatch("use " + autoFix + ", clear", session);
    auto out = piet::dispatch("pca price mpg weight length turn, covariance", session);
    check(!anyError(out), "H/pca: covariance form runs");
    check(session.eval.findClassMatrix('e', "sds") == nullptr,
          "H/pca: e(sds) is ABSENT after a covariance pca");
    const double* tr = session.eval.eScalars.find("trace");
    check(tr != nullptr && *tr == 9304104.0,
          "H/pca: e(trace) == 9304104 exactly (raw sum 9304104.43132173, chopped)");
  }
  {
    piet::SessionState session(workdir);
    (void)piet::dispatch("use " + autoFix + ", clear", session);
    auto out = piet::dispatch("lowess mpg weight, gen(h_lw)", session);
    check(!anyError(out), "H/lowess: runs and generates");
    // lowess is NOT rclass and posts no r(bwidth): w2ae_lpoly_lowess lpl_lw_ctl
    // and lpl_lw_bw read r(bwidth) as missing (this arm used to pin the 0.8 the
    // handler posted, which no Stata run produces).
    check(session.eval.rValues.find("bwidth") == nullptr, "H/lowess: r(bwidth) is not posted");
    (void)piet::dispatch("summarize h_lw", session);
    check(close(rv(session, "mean"), 21.4854228927206, 1e-9),
          "H/lowess: the smoothed mean is the StataBE oracle -- got " +
              std::to_string(rv(session, "mean")));
  }
  {
    piet::SessionState session(workdir);
    (void)piet::dispatch("use " + autoFix + ", clear", session);
    (void)piet::dispatch("lowess mpg weight, bwidth(2) gen(h_lw2) nograph", session);
    // lowess.ado substitutes 0.8 for a bwidth outside (0,1): the smooth is the
    // default one (same oracle mean as the default-bandwidth arm above).
    (void)piet::dispatch("summarize h_lw2", session);
    check(close(rv(session, "mean"), 21.4854228927206, 1e-9),
          "H/lowess: bwidth(2) smooths with the SUBSTITUTED 0.8, not the request");
  }
  {
    piet::SessionState session(workdir);
    (void)piet::dispatch("use " + autoFix + ", clear", session);
    auto out = piet::dispatch("lpoly price mpg, nograph", session);
    check(!anyError(out), "H/lpoly: runs");
    check(close(rv(session, "bwidth"), 0.962518238058985, 1e-5),
          "H/lpoly: r(bwidth) matches the StataBE ROT within the chain's own limit -- got " +
              std::to_string(rv(session, "bwidth")));
    auto out2 = piet::dispatch("lpoly price mpg, nograph kernel(epan2)", session);
    check(!anyError(out2), "H/lpoly: epan2 runs");
    check(close(rv(session, "bwidth"), 2.15249845166361, 1e-5),
          "H/lpoly: epan2 r(bwidth) oracle (its constant was MEASURED, not analytic)");
  }
  {
    piet::SessionState session(workdir);
    (void)piet::dispatch("use " + autoFix + ", clear", session);
    check(anyError(piet::dispatch("tsfilter bw c = price", session)),
          "H/tsfilter: a non-hp filter word is an unknown SUBcommand, not an unknown command");
    // tsfilter without tsset is r(111), the same as Stata.
    check(anyError(piet::dispatch("tsfilter hp c = price", session)),
          "H/tsfilter: refuses without a tsset");
  }

  fs::remove_all(workdir, ec);
}

// ── AER-SCOPE1 bundle H prerequisite: the e()/r() MATRIX LAYER (2026-09-05) ──
//
// Measured before writing a line of H2: the matrix layer was narrower than the
// plan assumed, and in a way no gate could see. e-matrices were effectively
// WRITE-ONLY — `matlist e(...)` and `matrix X = e(...)` both hard-coded their
// regex to `[bV]`, `ereturn list` read neither session.eval.eScalars nor
// eMatrices (it rendered the regression coeftable and a fixed nine-scalar map),
// and no syntax anywhere could read an ELEMENT out of a posted class matrix
// because `\b([A-Za-z_]\w*)\s*\[` stops at the ')' in `e(Ev)[1,1]`. r-class
// matrices did not exist at all. So pca could have posted seven matrices and
// eight macros, sktest could have posted r(table), every gate would have stayed
// green, and none of it would have been readable — the
// publish-what-nobody-can-read failure that the bundle-H errata exists to stop.
//
// This bundle pins the layer itself, seeded directly into the stores rather
// than through pca/sktest, so it fails for ONE reason (the plumbing) and keeps
// failing if a later refactor narrows it again.
void testMatrixClassLayer() {
  std::printf("[selftest] --- AER-SCOPE1 bundle H prereq: e()/r() matrix layer ---\n");
  namespace fs = std::filesystem;
  std::string workdir = (fs::temp_directory_path() / "piet_native_selftest_matrixlayer").u8string();
  std::error_code ec;
  fs::remove_all(workdir, ec);
  fs::create_directories(workdir, ec);

  auto echoText = [](const auto& blocks) {
    std::string s;
    for (const auto& b : blocks)
      if (b.is_object() && b.value("type", std::string()) == "echo")
        s += b.value("text", std::string());
    return s;
  };
  auto displayText = [](const auto& blocks) {
    std::string s;
    for (const auto& b : blocks)
      if (b.is_object() && b.value("type", std::string()) == "display")
        s += b.value("text", std::string());
    return s;
  };
  auto anyError = [](const auto& blocks) {
    for (const auto& b : blocks)
      if (b.is_object() && b.value("type", std::string()) == "error") return true;
    return false;
  };
  // A 2x3 with a distinct value per cell, so an index mix-up (row/col swap,
  // off-by-one) shows up as a WRONG NUMBER rather than as a pass.
  auto mk23 = []() {
    piet::eval::EvalMatrix m;
    m.data = {{11.0, 12.0, 13.0}, {21.0, 22.0, 23.0}};
    m.rownames = {"r1", "r2"};
    m.colnames = {"c1", "c2", "c3"};
    return m;
  };

  // (a) e(<name>) beyond b/V — the pca shape.
  {
    piet::SessionState session(workdir);
    session.eval.eMatrices.emplace_back("Ev", mk23());

    auto ml = piet::dispatch("matlist e(Ev)", session);
    check(!anyError(ml), "H-prereq: `matlist e(Ev)` is not an error (was rc 111: regex was [bV])");
    const std::string mlText = echoText(ml) + displayText(ml);
    check(mlText.find("11") != std::string::npos && mlText.find("23") != std::string::npos,
          "H-prereq: `matlist e(Ev)` renders the posted cells");

    auto md = piet::dispatch("matrix EVCOPY = e(Ev)", session);
    check(!anyError(md), "H-prereq: `matrix EVCOPY = e(Ev)` is accepted");
    const piet::eval::EvalMatrix* copied = session.eval.findMatrix("EVCOPY");
    check(copied != nullptr, "H-prereq: `matrix X = e(Ev)` lands in the user matrix store");
    if (copied != nullptr) {
      check(copied->data.size() == 2 && copied->data[0].size() == 3,
            "H-prereq: the copy keeps 2 x 3");
      check(copied->data[1][2] == 23.0, "H-prereq: the copy keeps the VALUES (not a fresh zero)");
      check(copied->colnames.size() == 3 && copied->colnames[2] == "c3",
            "H-prereq: the copy keeps the stripe");
    }
  }

  // (b) element access + colsof/rowsof through the class wrapper. This is the
  // path that did not exist in ANY form, so each assertion is a live number.
  {
    piet::SessionState session(workdir);
    session.eval.eMatrices.emplace_back("Ev", mk23());
    session.eval.rMatrices.emplace_back("table", mk23());

    (void)piet::dispatch("scalar h_e12 = e(Ev)[1,2]", session);
    check(session.eval.scalars.get("h_e12", "") == "12",
          "H-prereq: `e(Ev)[1,2]` reads 12 (row-major, 1-based) — got '" +
              session.eval.scalars.get("h_e12", "<unset>") + "'");
    (void)piet::dispatch("scalar h_e23 = e(Ev)[2,3]", session);
    check(session.eval.scalars.get("h_e23", "") == "23",
          "H-prereq: `e(Ev)[2,3]` reads 23 — got '" +
              session.eval.scalars.get("h_e23", "<unset>") + "'");
    (void)piet::dispatch("scalar h_r21 = r(table)[2,1]", session);
    check(session.eval.scalars.get("h_r21", "") == "21",
          "H-prereq: `r(table)[2,1]` reads 21 — got '" +
              session.eval.scalars.get("h_r21", "<unset>") + "'");
    (void)piet::dispatch("scalar h_cols = colsof(e(Ev))", session);
    check(session.eval.scalars.get("h_cols", "") == "3",
          "H-prereq: `colsof(e(Ev))` == 3 — got '" +
              session.eval.scalars.get("h_cols", "<unset>") + "'");
    (void)piet::dispatch("scalar h_rows = rowsof(r(table))", session);
    check(session.eval.scalars.get("h_rows", "") == "2",
          "H-prereq: `rowsof(r(table))` == 2 — got '" +
              session.eval.scalars.get("h_rows", "<unset>") + "'");
  }

  // (c) `return list` grows a matrices: section — but ONLY when one was posted.
  // The conditional is the point: every frozen return-list fixture in the tree
  // was captured without that section, so an unconditional header would have
  // forced a whole-tree re-capture to say "no matrices" — the re-pin that hides
  // real drift.
  {
    piet::SessionState session(workdir);
    // The listing is a "display" block, as output is (BUG-1505); the "echo" is
    // only the command line.
    const std::string bare = displayText(piet::dispatch("return list", session));
    check(bare.find("matrices:") == std::string::npos,
          "H-prereq: `return list` with no r-matrix prints NO matrices: section "
          "(existing fixtures stay byte-identical)");

    session.eval.rMatrices.emplace_back("table", mk23());
    const std::string withMat = displayText(piet::dispatch("return list", session));
    check(withMat.find("matrices:") != std::string::npos,
          "H-prereq: `return list` prints matrices: once an r-matrix exists");
    check(withMat.find("r(table)") != std::string::npos && withMat.find("2 x 3") != std::string::npos,
          "H-prereq: `return list` names r(table) with its dims");

    // `return clear` outside a program leaves r() alone (w2o_rnames.log:528 N34);
    // inside one it empties r(), matrices included.
    (void)piet::dispatch("return clear", session);
    check(!session.eval.rMatrices.empty(),
          "H-prereq: top-level `return clear` leaves r() -- r-matrices included -- alone (N34)");
  }

  // (d) `ereturn list` reports what a NON-regression estimator posted. Before
  // this it was driven entirely by the coeftable + a fixed scalar map, so a pca
  // would have printed nothing of its own.
  {
    piet::SessionState session(workdir);
    // `fatalities` is the ONLY bundled dataset (sysuse auto is not available in
    // this build) -- the same fixture the bundle B legs above use.
    (void)piet::dispatch("sysuse fatalities, clear", session);
    (void)piet::dispatch("regress income beertax", session);  // gives us a LastModel
    session.eval.eScalars.set("rho", 0.908259483427898);
    session.eval.eStrings.set("Ctype", "correlation");
    session.eval.eMatrices.emplace_back("Ev", mk23());

    auto elBlocks = piet::dispatch("ereturn list", session);
    const std::string el = displayText(elBlocks);  // a display block (BUG-1505)
    const std::string elWhy = el.empty() ? (" -- ereturn list produced no display; blocks=" +
                                            nlohmann::json(elBlocks).dump().substr(0, 240))
                                         : (" -- got:" + el);
    check(el.find("e(rho)") != std::string::npos,
          "H-prereq: `ereturn list` prints a handler-posted e-scalar" + elWhy);
    check(el.find("e(Ctype)") != std::string::npos && el.find("correlation") != std::string::npos,
          "H-prereq: `ereturn list` prints a handler-posted e-macro" + elWhy);
    check(el.find("e(Ev)") != std::string::npos && el.find("2 x 3") != std::string::npos,
          "H-prereq: `ereturn list` prints a handler-posted e-matrix with dims" + elWhy);
    check(el.find("e(b)") != std::string::npos,
          "H-prereq: `ereturn list` still prints the coeftable-derived e(b)" + elWhy);
  }

  // (e) the negative arms. A name nobody posted must still be a clean refusal,
  // not a silent empty matrix — the generalised regex must not turn "not found"
  // into "found nothing".
  {
    piet::SessionState session(workdir);
    session.eval.eMatrices.emplace_back("Ev", mk23());
    check(anyError(piet::dispatch("matlist e(nosuch)", session)),
          "H-prereq: `matlist e(nosuch)` still errors");
    check(anyError(piet::dispatch("matlist r(table)", session)),
          "H-prereq: `matlist r(table)` errors when no r-matrix was posted");
    // Stata reads an absent r(NAME) in a matrix definition as the missing
    // value: `matrix T = r(nosuch)` is rc 0 with a 1x1 `.` (w2f_residuals.log
    // :1675 e_matrix_nosuch; w2n_followups.log:938 E05), never an empty matrix.
    check(!anyError(piet::dispatch("matrix Z = r(nosuch)", session)),
          "H-prereq: `matrix Z = r(nosuch)` is rc 0 (w2f_residuals.log:1675)");
    {
      const auto* z = session.eval.findMatrix("Z");
      check(z != nullptr && z->data.size() == 1 && z->data[0].size() == 1 &&
                (std::isnan(z->data[0][0]) || z->data[0][0] >= piet::eval::kStataMissingSentinel),
            "H-prereq: `matrix Z = r(nosuch)` defines a 1x1 missing matrix, not an empty one");
    }
    // findMatrix has ALWAYS searched eMatrices as well as the user store, so a
    // posted e-matrix is reachable bare -- pre-existing behaviour, asserted here
    // so that a future narrowing of findMatrix is a deliberate change and not a
    // silent one. rMatrices is deliberately NOT in that chain: r() is replaced
    // wholesale by the next r-class command, and letting `matlist table` answer
    // with r(table) would make a user matrix named `table` unaddressable.
    check(session.eval.findMatrix("Ev") != nullptr,
          "H-prereq: findMatrix still reaches e-matrices (unchanged)");
    check(session.eval.findMatrix("table") == nullptr,
          "H-prereq: findMatrix does NOT reach r-matrices (bare `table` stays the user store)");
  }

  fs::remove_all(workdir, ec);
}

// ── AER-SCOPE1 bundle J (GRAPH-X, 2026-09-04) ────────────────────────────────
//
// SIX registry rows, not the plan's fourteen: grc1leg2, grstyle, geodist,
// geonear, cdfplot, event_plot. `grc1leg` (un-suffixed) and the eight refusals
// (cibar binsreg spmap maptile shp2dta geoinpoly heatplot distplot) are
// UNREGISTERED -- the attribution rule gives a row only to a package that
// states its own author -- so they answer a GENERIC r(199). Leg (xv) asserts
// exactly that generic shape and nothing more: a leg pinning a specific
// `reason` string for them would be asserting a promise this tree does not
// make, and it would keep passing after somebody registered them under a
// different cause.
//
// WHAT MAKES THIS BUNDLE DANGEROUS is that every one of its wrong
// implementations returns rc 0 and draws a picture:
//   - a grc1leg2 that combined the panels and set nothing produces a VALID
//     combine block with every legend still on -- the exact picture the
//     command exists to prevent (leg i);
//   - a geodist that shipped haversine as the default is wrong by 0.07% and
//     no chart shows it (legs ii/iv);
//   - an ECDF that ends at (n-1)/n or n/(n+1) is the classic off-by-one and
//     looks right on a plot (leg x);
//   - an event_plot that forwarded without the stub filter draws a plausible
//     plot of the WRONG coefficients (leg xiii);
//   - a grstyle that silently no-ops is the accept-note behaviour with the
//     evidence removed (leg xii).
// So no leg below stops at a return code. Each asserts a VALUE or a BLOCK
// STRUCTURE, and each names, in its own comment, the wrong implementation it
// separates from the right one.
//
// TWO TRAPS THIS FUNCTION PAYS FOR UP FRONT.
//   1. `session.cwd` is seeded as well as `session.eval.cwd`: resolveUserPath
//      (handlers.cpp:2040) reads SessionState::cwd, and `geonear` resolves a
//      `using` file through it. Bundle E seeded only eval.cwd and sixteen
//      checks failed for that one reason.
//   2. Every numeric report goes through `fullPrec` (%.17g). std::to_string
//      prints six decimals, which renders a genuine 8th-digit difference as
//      two identical strings -- and a distance check whose failure message
//      reads `321.218660 vs 321.218660` is not a failure report.
//
// Nothing here asserts a PATH: the workdir is this process's temp directory.
void testAerGraphX() {
  std::printf("[selftest] --- AER-SCOPE1 bundle J: grc1leg2 / grstyle / geodist / geonear / "
              "cdfplot / event_plot + the unregistered generic-199 names ---\n");
  namespace fs = std::filesystem;
  std::string workdir = (fs::temp_directory_path() / "piet_native_selftest_aergraphx").u8string();
  std::error_code ec;
  fs::remove_all(workdir, ec);
  fs::create_directories(workdir, ec);

  auto exec = [](const std::string& src, piet::SessionState& session) {
    return piet::doexec::executeDoSource(src, session, piet::dispatch);
  };
  auto seed = [&](piet::SessionState& s) {
    s.eval.cwd = workdir;
    s.cwd = workdir;  // resolveUserPath reads THIS field (handlers.cpp:2040).
  };
  // Returns a NULL json rather than throwing when there is no error block --
  // the BUG-129 trap, and check()'s message argument is built EAGERLY (on the
  // passing path too), so every message below reads through these helpers.
  auto firstError = [](const nlohmann::ordered_json& blocks) -> nlohmann::ordered_json {
    for (const auto& b : blocks)
      if (b.is_object() && b.value("type", std::string()) == "error") return b;
    return nlohmann::ordered_json();
  };
  auto errText = [](const nlohmann::ordered_json& e) {
    return e.is_object() ? e.value("message", std::string()) : std::string("<none>");
  };
  auto errField = [](const nlohmann::ordered_json& e, const std::string& f) {
    return e.is_object() ? e.value(f, std::string()) : std::string("<none>");
  };
  auto rcOf = [](const nlohmann::ordered_json& e) {
    return e.is_object() ? piet::eval::coarseRc(e) : std::string("<none>");
  };
  // See the header: %.17g, because `321.218660` twice is not a failure report.
  auto fullPrec = [](double v) {
    char buf[48];
    std::snprintf(buf, sizeof(buf), "%.17g", v);
    return std::string(buf);
  };
  auto has = [](const std::string& hay, const std::string& needle) {
    return hay.find(needle) != std::string::npos;
  };
  auto spit = [](const std::string& p, const std::string& bytes) {
    std::ofstream f(cecon::to_native_path(p), std::ios::binary | std::ios::trunc);
    f << bytes;
  };
  auto displays = [](const auto& blocks) {
    std::vector<std::string> v;
    for (const auto& b : blocks)
      if (b.is_object() && b.value("type", std::string()) == "display")
        v.push_back(b.value("text", std::string()));
    return v;
  };
  // The first `type == "graph"` block, or NULL. Every accessor below is
  // type-guarded for the same reason firstError is: a missing key must fail
  // ONE check with a readable message, not throw out of the whole run.
  auto graphBlock = [](const auto& blocks) -> nlohmann::ordered_json {
    for (const auto& b : blocks)
      if (b.is_object() && b.value("type", std::string()) == "graph") return b;
    return nlohmann::ordered_json();
  };
  auto gstr = [](const nlohmann::ordered_json& j, const std::string& k) {
    return (j.is_object() && j.contains(k) && j[k].is_string()) ? j[k].get<std::string>()
                                                                : std::string("<absent>");
  };
  auto garr = [](const nlohmann::ordered_json& j,
                 const std::string& k) -> nlohmann::ordered_json {
    return (j.is_object() && j.contains(k) && j[k].is_array())
               ? j[k]
               : nlohmann::ordered_json::array();
  };
  auto gobj = [](const nlohmann::ordered_json& j,
                 const std::string& k) -> nlohmann::ordered_json {
    return (j.is_object() && j.contains(k) && j[k].is_object())
               ? j[k]
               : nlohmann::ordered_json::object();
  };
  auto gbool = [](const nlohmann::ordered_json& j, const std::string& k, bool dflt) {
    return (j.is_object() && j.contains(k) && j[k].is_boolean()) ? j[k].get<bool>() : dflt;
  };
  // points[i] is a two-element [x, y] array; `which` is 0 for x, 1 for y.
  auto ptAt = [](const nlohmann::ordered_json& points, size_t i, size_t which) -> double {
    if (!points.is_array() || i >= points.size()) return std::nan("");
    const auto& p = points[i];
    if (!p.is_array() || which >= p.size() || !p[which].is_number()) return std::nan("");
    return p[which].get<double>();
  };
  // r() is REPLACED wholesale by a summarize (macros.cpp's captureRFromBlock),
  // so every read below happens immediately after the command that published
  // it -- never two commands later.
  auto rOf = [](piet::SessionState& s, const char* key) -> double {
    const double* p = s.eval.rValues.find(key);
    return p ? *p : std::nan("");
  };
  auto runR = [&](piet::SessionState& s, const std::string& cmd, const char* key) -> double {
    (void)piet::dispatch(cmd, s);
    return rOf(s, key);
  };
  auto countIf = [&](piet::SessionState& s, const std::string& expr) {
    return runR(s, "count if " + expr, "N");
  };
  auto sumOf = [&](piet::SessionState& s, const std::string& var) {
    return runR(s, "summarize " + var, "sum");
  };
  auto meanOf = [&](piet::SessionState& s, const std::string& var) {
    return runR(s, "summarize " + var, "mean");
  };
  auto varNames = [](piet::SessionState& s) {
    std::vector<std::string> out;
    const nlohmann::ordered_json blocks = piet::dispatch("describe", s);
    for (const auto& b : blocks)
      if (b.is_object() && b.value("type", std::string()) == "describe" && b.contains("variables"))
        for (const auto& v : b["variables"]) out.push_back(v.value("name", std::string()));
    return out;
  };
  auto hasName = [](const std::vector<std::string>& v, const std::string& n) {
    return std::find(v.begin(), v.end(), n) != v.end();
  };
  auto joinNames = [](const std::vector<std::string>& v) {
    std::string s;
    for (const auto& n : v) { if (!s.empty()) s += " "; s += n; }
    return s.empty() ? std::string("<none>") : s;
  };

  // The three graphs legs (i) and (xv) build. Titles, not names, are what the
  // panel objects carry into the combine block, so the title is how a panel is
  // identified below.
  const std::string kThreeGraphs =
      "clear\n"
      "set obs 6\n"
      "gen gx = _n\n"
      "gen gy = 2*_n\n"
      "twoway scatter gy gx, name(g1) title(\"T1\")\n"
      "twoway line gy gx, name(g2) title(\"T2\")\n"
      "twoway connected gy gx, name(g3) title(\"T3\")\n";

  // Counts the panels whose legend is still ON, and reports which one it is.
  auto keptLegend = [&](const nlohmann::ordered_json& blk, std::string& whichTitle) {
    int kept = 0;
    whichTitle = "<none>";
    for (const auto& p : garr(blk, "panels")) {
      if (!gbool(gobj(p, "legend"), "off", false)) {
        ++kept;
        if (kept == 1) whichTitle = gstr(p, "title");
      }
    }
    return kept;
  };

  // ── (i) grc1leg2 keeps EXACTLY ONE legend. ────────────────────────────────
  // This is the whole command. A shim that resolved the names, called
  // runGraphCombine and set nothing produces a structurally valid
  // `graph_combine` block with three panels at rc 0 -- and three legends, which
  // is the picture the user ran grc1leg2 to avoid. The count is therefore the
  // assertion, not the block's existence: 3 is "did nothing", 0 is "switched
  // them all off and left the plot legend-less", and 1 is the answer. WHICH one
  // survives is the second half: the default is the FIRST panel, so a handler
  // that kept the last one agrees with the count check and disagrees here.
  {
    piet::SessionState s(workdir);
    seed(s);
    (void)exec(kThreeGraphs, s);
    auto r = exec("grc1leg2 g1 g2 g3\n", s);
    const nlohmann::ordered_json blk = graphBlock(r.blocks);
    check(gstr(blk, "kind") == "graph_combine",
          "AER-GRAPHX (i): `grc1leg2 g1 g2 g3` emits a graph_combine block (the same block "
          "`graph combine` emits -- this row is a shim over runGraphCombine, not a new "
          "renderer). Got kind `" + gstr(blk, "kind") + "`");
    check(garr(blk, "panels").size() == 3,
          "AER-GRAPHX (i): ...carrying all THREE panels. Got " +
              std::to_string(garr(blk, "panels").size()));
    std::string which;
    const int kept = keptLegend(blk, which);
    check(kept == 1,
          "AER-GRAPHX (i): ...and EXACTLY ONE panel keeps its legend. 3 here means the shim "
          "combined the graphs and set nothing -- a valid block, rc 0, and the wrong picture; "
          "0 means it switched every legend off and the combined plot has none at all. Got " +
              std::to_string(kept));
    check(which == "T1",
          "AER-GRAPHX (i): ...and with no legendfrom() it is the FIRST panel, per the plan's "
          "default. A handler that kept the last panel's legend passes the count check and "
          "fails here. Got `" + which + "`");
  }

  // ── (ii) legendfrom() moves the surviving legend. ─────────────────────────
  // Without this leg, legendfrom() could be parsed, accepted and dropped and
  // every check above would still pass -- the option would be decoration.
  {
    piet::SessionState s(workdir);
    seed(s);
    (void)exec(kThreeGraphs, s);
    auto r = exec("grc1leg2 g1 g2 g3, legendfrom(g2)\n", s);
    const nlohmann::ordered_json blk = graphBlock(r.blocks);
    std::string which;
    const int kept = keptLegend(blk, which);
    check(kept == 1,
          "AER-GRAPHX (ii): `legendfrom(g2)` still leaves exactly one legend on. Got " +
              std::to_string(kept));
    check(which == "T2",
          "AER-GRAPHX (ii): ...and it is g2's, not the default first panel's -- otherwise "
          "legendfrom() is an option the parser accepts and the handler ignores. Got `" +
              which + "`");

    // The panels are COPIES. grc1leg2 sets legend.off on the panel objects
    // inside its own combine block; if it wrote through to
    // session.namedGraphs instead, the user's `g1`/`g3` would come back
    // legend-less from every LATER command -- a mutation nobody looks for
    // because the command that caused it succeeded. A plain `graph combine`
    // afterwards must still find all three legends on.
    auto after = exec("graph combine g1 g2 g3\n", s);
    const nlohmann::ordered_json blk2 = graphBlock(after.blocks);
    std::string which2;
    const int kept2 = keptLegend(blk2, which2);
    check(kept2 == 3,
          "AER-GRAPHX (ii): ...and the SOURCE graphs are untouched -- a later `graph combine "
          "g1 g2 g3` still finds three legends. Fewer means grc1leg2 mutated "
          "session.namedGraphs in place and quietly stripped the user's own graphs. Got " +
              std::to_string(kept2));
  }

  // ── (iii) geodist: a KNOWN distance, to a tolerance that discriminates. ───
  // Seoul (37.5, 127.0) -> Busan (35.1, 129.0):
  //     WGS84 Vincenty inverse   321.218660 km   <- the contracted default
  //     haversine, R=6371        321.447478 km   <- what `sphere` must give
  // The two differ by 0.229262 km (0.0714%), so the band below is +/-0.10 km:
  // wide enough that no correct Vincenty can miss it (converged to 1e-12 rad
  // the answer is stable to millimetres) and narrow enough that shipping
  // haversine as the DEFAULT lands 2.3 tolerances away and fails. That is the
  // whole point of choosing the number rather than asserting "a column
  // appeared": a haversine default is right to three significant figures and
  // wrong, and no plot of it looks wrong.
  //
  // NOTE FOR THE PLAN'S READER: the ONESHOT plan's Done-When says this pair is
  // "~325.0 km". It is not -- 325 km is the Seoul-Busan CITY-CENTRE distance,
  // not the distance between the rounded coordinates the plan itself writes.
  // The number pinned here was computed independently on both sides (this lane
  // and the handler lane) before either was written.
  {
    piet::SessionState s(workdir);
    seed(s);
    (void)exec("clear\nset obs 1\n", s);
    // BUG-426 (2026-09-06): four LITERAL coordinates are the IMMEDIATE form —
    // geodist.ado prints the distance and returns r(distance), and generate()
    // there is r(198). This leg used to drive the literal+gen() spelling, which
    // is precisely the inversion the oracle caught, so it now reads r(distance)
    // and the variable form is exercised by leg (iv) below.
    auto r = exec("geodist 37.5 127.0 35.1 129.0\n", s);
    check(firstError(r.blocks).is_null(),
          "AER-GRAPHX (iii): `geodist 37.5 127.0 35.1 129.0` runs clean as the IMMEDIATE form "
          "(four literals, no generate()). Got `" + errText(firstError(r.blocks)) + "`");
    const double km = runR(s, "", "distance");
    check(std::isfinite(km) && std::fabs(km - 321.218660) < 0.10,
          "AER-GRAPHX (iii): ...and the value is the WGS84 Vincenty distance 321.218660 km. "
          "The tolerance is 0.10 km ON PURPOSE: haversine (R=6371.0088) answers 321.447922 for "
          "this pair, 0.229 km away, so a haversine default fails this check instead of passing "
          "it three significant figures deep. Got " + fullPrec(km));

    // `sphere` is a DIFFERENT function, not a synonym. Asserting only the
    // Vincenty value would leave a build in which both spellings return the
    // same number entirely green.
    auto r2 = exec("geodist 37.5 127.0 35.1 129.0, sphere\n", s);
    check(firstError(r2.blocks).is_null(),
          "AER-GRAPHX (iii): `sphere` is accepted. Got `" + errText(firstError(r2.blocks)) + "`");
    const double sph = runR(s, "", "distance");
    // TIGHT, and deliberately so: 1e-4 km. The 0.10 km tolerance on the line
    // above discriminates haversine-from-Vincenty (0.229 km apart); it cannot
    // see the RADIUS, and the radius is its own contract. geodist uses a
    // radius of exactly 6371 km (matches geodist's behaviour, identified from
    // its ado), not the IUGG mean 6371.0088 the plan
    // drafted -- a 0.000444 km difference here, invisible in any rendered
    // output, which the wider tolerance silently absorbed when the constant was
    // corrected. A pin that cannot fail on the number it names is not pinning
    // it.
    check(std::isfinite(sph) && std::fabs(sph - 321.447478) < 1e-4,
          "AER-GRAPHX (iii): ...and `sphere` is haversine on the PACKAGE's R=6371 km (not the IUGG "
          "6371.0088) -> 321.447478. Got " +
              fullPrec(sph));
    check(std::isfinite(km) && std::isfinite(sph) && std::fabs(sph - km) > 0.15,
          "AER-GRAPHX (iii): ...and the two answers DIFFER. Equal values here mean one spelling "
          "silently routes to the other's formula, which no single-value check can see. Vincenty " +
              fullPrec(km) + " vs sphere " + fullPrec(sph));

    // miles is a CONVERSION, not a label. A `miles` that returned kilometres
    // renders a plot with the right shape and a 61% understated axis.
    auto r3 = exec("geodist 37.5 127.0 35.1 129.0, miles\n", s);
    check(firstError(r3.blocks).is_null(),
          "AER-GRAPHX (iii): `miles` is accepted. Got `" + errText(firstError(r3.blocks)) + "`");
    const double mi = runR(s, "", "distance");
    check(std::isfinite(mi) && std::fabs(mi - 199.596022) < 0.07,
          "AER-GRAPHX (iii): ...and `miles` CONVERTS (x 0.621371192) -> 199.596022 statute "
          "miles. A handler that accepted the flag and returned kilometres answers " +
              fullPrec(km) + " here. Got " + fullPrec(mi));
    // BUG-426's discriminating arm, and the reason a value check alone is not
    // enough: the OLD handler accepted this spelling and wrote a constant
    // column, which looks like a working command. Stata answers r(198).
    auto r4 = exec("geodist 37.5 127.0 35.1 129.0, gen(dzz)\n", s);
    check(!firstError(r4.blocks).is_null() &&
              errText(firstError(r4.blocks)).find("immediate form") != std::string::npos,
          "AER-GRAPHX (iii): ...and generate() with four literals is REFUSED (Stata r(198)) -- the "
          "immediate form is a calculator, not a column writer. Got `" +
              errText(firstError(r4.blocks)) + "`");
  }

  // ── (iv) a missing coordinate gives a MISSING distance, never 0. ──────────
  // Zero is a legal distance (two identical points), so a handler that folded
  // missing to 0 puts a plausible number in the column and every downstream
  // mean is quietly wrong -- and `summarize` counts it, where a real missing
  // would have been dropped. Both directions are asserted: one missing AND no
  // zero.
  {
    piet::SessionState s(workdir);
    seed(s);
    (void)exec("clear\nset obs 2\n"
               "gen la1 = 37.5\n"
               "gen lo1 = 127.0\n"
               "gen la2 = 35.1\n"
               "gen lo2 = 129.0\n"
               "replace la2 = . in 2\n",
               s);
    auto r = exec("geodist la1 lo1 la2 lo2, gen(dm)\n", s);
    check(firstError(r.blocks).is_null(),
          "AER-GRAPHX (iv): the VARIABLE form (four column names) runs clean. Got `" +
              errText(firstError(r.blocks)) + "`");
    const double nMiss = countIf(s, "missing(dm)");
    const double nZero = countIf(s, "dm == 0");
    const double nGood = countIf(s, "dm > 321 & dm < 322");
    check(nMiss == 1,
          "AER-GRAPHX (iv): the row whose lat2 is missing gets a MISSING distance. Got " +
              fullPrec(nMiss) + " missing row(s)");
    check(nZero == 0,
          "AER-GRAPHX (iv): ...and NOT 0. Zero is a legal distance, so a missing folded to 0 is "
              "a plausible number that summarize then averages in. Got " + fullPrec(nZero) +
              " zero row(s)");
    check(nGood == 1,
          "AER-GRAPHX (iv): ...while the complete row still computes -- one bad row does not "
          "blank the column. Got " + fullPrec(nGood) + " good row(s)");
  }

  // ── (v) an out-of-range latitude is missing too, not a wrapped number. ────
  // |lat| > 90 has no point on the sphere. Vincenty's iteration still returns
  // SOMETHING for lat=95 (it wraps past the pole), so "it produced a number" is
  // exactly the failure mode: the plan's edge case says missing.
  {
    piet::SessionState s(workdir);
    seed(s);
    (void)exec("clear\nset obs 1\n"
               "gen bla = 95\n"
               "gen blo = 10\n"
               "gen bla2 = 35.1\n"
               "gen blo2 = 129.0\n",
               s);
    (void)exec("geodist bla blo bla2 blo2, gen(dbad)\n", s);
    const double nMiss = countIf(s, "missing(dbad)");
    check(nMiss == 1,
          "AER-GRAPHX (v): latitude 95 is off the sphere -> MISSING. The iteration happily "
          "returns a number for it, so a handler with no range check writes a confident wrong "
          "distance here. Got " + fullPrec(nMiss) + " missing row(s)");
  }

  // ── (vi) geonear picks the RIGHT neighbour, and names its columns. ────────
  // Three master points on the meridian at latitudes 0/10/20; four neighbours
  // half a degree north of each of the first three, plus a decoy at 40.
  // Hand-computed answer: 1->101, 2->102, 3->103, so the id column sums to 306.
  // The two wrong implementations this separates are the ones that look right:
  // "first row of the using file for everybody" sums to 303, and "last row"
  // sums to 416. The decoy at 40 exists so that a handler which simply took
  // the MAXIMUM distance is also caught.
  //
  // The distance band is deliberately WIDE (160..172 km against a Vincenty sum
  // of 165.9456 and a haversine sum of 166.7926). It is a UNIT check, not a
  // formula check: degrees would sum to 1.5, metres to 165946, miles to 103.1.
  // The handler declares the ellipsoid as geonear's default today, but Stata's
  // own geonear defaults to the SPHERE, so which one this row should ship is a
  // question the StataBE golden settles -- and a band that locked in today's
  // answer would turn red on the fix rather than on a defect. The formula IS
  // discriminated, in leg (iii), on geodist, where the contract is unambiguous.
  {
    piet::SessionState s(workdir);
    seed(s);
    spit(workdir + "/gnnb.csv",
         "nid,nlat,nlon\n101,0.5,0\n102,10.5,0\n103,20.5,0\n104,40,0\n");
    (void)exec("clear\nset obs 3\ngen mid = _n\ngen mlat = (_n-1)*10\ngen mlon = 0\n", s);
    auto r = exec("geonear mid mlat mlon using \"gnnb.csv\", neighbors(nid nlat nlon)\n", s);
    check(firstError(r.blocks).is_null(),
          "AER-GRAPHX (vi): `geonear ... using \"gnnb.csv\", neighbors(nid nlat nlon)` runs "
          "clean -- the `using` file resolves through session.cwd. Got `" +
              errText(firstError(r.blocks)) + "`");
    const std::vector<std::string> vn = varNames(s);
    check(hasName(vn, "nid") && hasName(vn, "km_to_nid"),
          "AER-GRAPHX (vi): ...and it creates `nid` + `km_to_nid` -- the stem is the "
          "neighbors() ID VARIABLE name, and the distance column carries its unit in the "
          "prefix. Got: " + joinNames(vn));
    check(runR(s, "count", "N") == 3,
          "AER-GRAPHX (vi): ...and the master keeps its THREE rows. geonear appends columns, "
          "it does not join rows. Got " + fullPrec(runR(s, "count", "N")));
    const double idSum = sumOf(s, "nid");
    check(idSum == 306,
          "AER-GRAPHX (vi): ...and each master point gets its OWN nearest neighbour (101+102+"
          "103 = 306). 303 is 'the first using row for everybody', 416 is 'the last one', and "
          "both draw a perfectly ordinary-looking map. Got " + fullPrec(idSum));
    const double pair1 = countIf(s, "mid == 1 & nid == 101");
    const double pair3 = countIf(s, "mid == 3 & nid == 103");
    check(pair1 == 1 && pair3 == 1,
          "AER-GRAPHX (vi): ...and the PAIRING is right, not just the multiset -- a handler "
          "that assigned the correct three ids in the wrong ROW order sums to 306 too. Got "
          "rows matching (mid==1,nid==101): " + fullPrec(pair1) +
              ", (mid==3,nid==103): " + fullPrec(pair3));
    const double kmSum = sumOf(s, "km_to_nid");
    check(std::isfinite(kmSum) && kmSum > 160.0 && kmSum < 172.0,
          "AER-GRAPHX (vi): ...and the distances are in KILOMETRES (three half-degree meridian "
          "arcs sum to ~166). Degrees would sum to 1.5, metres to ~165946, miles to ~103. Got " +
              fullPrec(kmSum));
  }

  // ── (vii) genstub() renames the stem and `miles` renames the unit prefix. ─
  // The unit lives in the COLUMN NAME as well as in the number. A handler that
  // converted the value but kept the `km_to_` prefix hands the user a column
  // labelled kilometres holding miles -- the single most expensive kind of
  // quiet wrong answer in a geo pipeline -- and one that renamed the prefix
  // without converting is the same defect mirrored. Both halves are asserted.
  {
    piet::SessionState s(workdir);
    seed(s);
    spit(workdir + "/gnnb.csv",
         "nid,nlat,nlon\n101,0.5,0\n102,10.5,0\n103,20.5,0\n104,40,0\n");
    (void)exec("clear\nset obs 3\ngen mid = _n\ngen mlat = (_n-1)*10\ngen mlon = 0\n", s);
    auto r = exec("geonear mid mlat mlon using \"gnnb.csv\", neighbors(nid nlat nlon) "
                  "genstub(gn) miles\n",
                  s);
    check(firstError(r.blocks).is_null(),
          "AER-GRAPHX (vii): `genstub(gn) miles` runs clean. Got `" +
              errText(firstError(r.blocks)) + "`");
    const std::vector<std::string> vn = varNames(s);
    check(hasName(vn, "gn") && hasName(vn, "mi_to_gn"),
          "AER-GRAPHX (vii): ...and the columns are `gn` + `mi_to_gn` -- genstub() replaces the "
          "stem and `miles` replaces the unit prefix. Got: " + joinNames(vn));
    check(!hasName(vn, "km_to_gn"),
          "AER-GRAPHX (vii): ...and NOT `km_to_gn`: a column named kilometres holding miles is "
          "the wrong answer that survives every review. Got: " + joinNames(vn));
    const double miSum = sumOf(s, "mi_to_gn");
    check(std::isfinite(miSum) && miSum > 99.0 && miSum < 107.0,
          "AER-GRAPHX (vii): ...and the NUMBERS converted too (~103 miles against ~166 km). A "
          "rename with no conversion lands at ~166 here. Got " + fullPrec(miSum));
  }

  // ── (viii) the pair cap refuses BEFORE it writes anything. ────────────────
  // 25000 master x 2100 neighbours = 5.25e7 pairs, just over the 5e7 cap. Two
  // things are asserted and the second is the one that matters: a refusal that
  // has already appended a half-filled column leaves the frame in a state the
  // user then analyses, and the error they saw scrolls away. (The under-cap
  // control is leg (vi): geonear succeeding on a small frame is what makes
  // this leg a cap check rather than "geonear always refuses".)
  {
    piet::SessionState s(workdir);
    seed(s);
    std::string big = "nid,nlat,nlon\n";
    big.reserve(64 * 1024);
    for (int i = 0; i < 2100; ++i) {
      big += std::to_string(200000 + i);
      big += ",";
      big += fullPrec(0.001 * i);
      big += ",0\n";
    }
    spit(workdir + "/gnbig.csv", big);
    (void)exec("clear\nset obs 25000\ngen mid = _n\ngen mlat = _n/1000\ngen mlon = 0\n", s);
    const size_t before = varNames(s).size();
    auto r = exec("geonear mid mlat mlon using \"gnbig.csv\", neighbors(nid nlat nlon)\n", s);
    const nlohmann::ordered_json e = firstError(r.blocks);
    check(!e.is_null(),
          "AER-GRAPHX (viii): 25000 x 2100 = 5.25e7 pairs is over the build's 5e7 cap and is "
          "REFUSED. Silently grinding through it is a wall-clock cliff with no message.");
    check(has(errText(e), "5e7 pair cap"),
          "AER-GRAPHX (viii): ...and the sentence names the CAP, so the user knows to restrict "
          "the sample rather than to retry. Got `" + errText(e) + "`");
    check(rcOf(e) == "1",
          "AER-GRAPHX (viii): ...at rc 1 (engine_error): nothing about the syntax is wrong "
          "(198) and the command exists (199). Got rc " + rcOf(e));
    check(varNames(s).size() == before,
          "AER-GRAPHX (viii): ...and the frame gains NO column. A refusal that has already "
          "written half a column leaves the user analysing it after the message scrolls away. "
          "Had " + std::to_string(before) + ", now " + std::to_string(varNames(s).size()));
  }

  // ── (ix) cdfplot's last point is EXACTLY 1.0. ─────────────────────────────
  // The classic ECDF off-by-one ends at (n-1)/n = 0.8 or n/(n+1) = 0.8333 for
  // n=5, and both draw a curve that looks entirely right -- the eye cannot see
  // a top-of-axis gap of one fifth on an unlabelled plot. The equality is
  // asserted EXACTLY (not within a tolerance) because bundle F's `cumul` rule
  // is y = r/N with r = N on the last point, which is 1.0 in double arithmetic
  // by construction. The FIRST point is asserted too: 1/N = 0.2 separates the
  // i/N rule from a 0-based (i-1)/N that also ends below 1.
  {
    piet::SessionState s(workdir);
    seed(s);
    (void)exec("clear\nset obs 5\ngen cv = _n\n", s);
    auto r = exec("cdfplot cv\n", s);
    check(firstError(r.blocks).is_null(),
          "AER-GRAPHX (ix): `cdfplot cv` runs clean. Got `" + errText(firstError(r.blocks)) + "`");
    const nlohmann::ordered_json blk = graphBlock(r.blocks);
    check(gstr(blk, "kind") == "twoway",
          "AER-GRAPHX (ix): ...and emits the TWOWAY block the renderer already draws -- this "
          "bundle adds no plot type. Got kind `" + gstr(blk, "kind") + "`");
    const nlohmann::ordered_json layers = garr(blk, "layers");
    check(layers.size() == 1,
          "AER-GRAPHX (ix): ...one layer with no by(). Got " + std::to_string(layers.size()));
    const nlohmann::ordered_json pts = layers.empty() ? nlohmann::ordered_json::array()
                                                      : garr(layers[0], "points");
    check(pts.size() == 5,
          "AER-GRAPHX (ix): ...with one point per observation (5). Got " +
              std::to_string(pts.size()));
    const double lastY = ptAt(pts, pts.empty() ? 0 : pts.size() - 1, 1);
    check(lastY == 1.0,
          "AER-GRAPHX (ix): ...and the LAST point's y is exactly 1.0. 0.8 is (n-1)/n and "
          "0.83333 is n/(n+1) -- the two classic off-by-ones, both of which draw a curve that "
          "looks correct. Got " + fullPrec(lastY));
    const double firstY = ptAt(pts, 0, 1);
    check(std::isfinite(firstY) && std::fabs(firstY - 0.2) < 1e-12,
          "AER-GRAPHX (ix): ...and the FIRST point's y is 1/N = 0.2, which is what separates "
          "the i/N rule from a 0-based (i-1)/N that also ends below 1. Got " + fullPrec(firstY));
    const double lastX = ptAt(pts, pts.empty() ? 0 : pts.size() - 1, 0);
    check(std::isfinite(lastX) && std::fabs(lastX - 5.0) < 1e-12,
          "AER-GRAPHX (ix): ...and x runs to the data's maximum (5), i.e. the points are the "
          "SORTED values and not row order. Got " + fullPrec(lastX));
  }

  // ── (x) by() gives one series PER GROUP, each ending at 1.0. ──────────────
  // A by() that parsed and was then dropped renders ONE pooled curve: same
  // block kind, same key set, rc 0, and a chart that answers a different
  // question. The per-group maximum x is the second half -- two layers whose
  // last x are both 6 would mean the split happened for the legend and not for
  // the data.
  {
    piet::SessionState s(workdir);
    seed(s);
    (void)exec("clear\nset obs 6\ngen cv = _n\ngen cg = 1\nreplace cg = 2 in 4/6\n", s);
    auto r = exec("cdfplot cv, by(cg)\n", s);
    check(firstError(r.blocks).is_null(),
          "AER-GRAPHX (x): `cdfplot cv, by(cg)` runs clean. Got `" +
              errText(firstError(r.blocks)) + "`");
    const nlohmann::ordered_json blk = graphBlock(r.blocks);
    const nlohmann::ordered_json layers = garr(blk, "layers");
    check(layers.size() == 2,
          "AER-GRAPHX (x): ...and the series count equals the GROUP count (2). One layer here "
          "means by() was accepted and dropped, which renders a pooled ECDF at rc 0. Got " +
              std::to_string(layers.size()));
    if (layers.size() == 2) {
      const nlohmann::ordered_json p0 = garr(layers[0], "points");
      const nlohmann::ordered_json p1 = garr(layers[1], "points");
      check(p0.size() == 3 && p1.size() == 3,
            "AER-GRAPHX (x): ...each carrying its own group's three observations. Got " +
                std::to_string(p0.size()) + " and " + std::to_string(p1.size()));
      check(ptAt(p0, p0.empty() ? 0 : p0.size() - 1, 1) == 1.0 &&
                ptAt(p1, p1.empty() ? 0 : p1.size() - 1, 1) == 1.0,
            "AER-GRAPHX (x): ...and EACH group's ECDF reaches 1.0 -- a per-group curve, not a "
            "pooled one sliced in two (whose first slice would top out at 0.5). Got " +
                fullPrec(ptAt(p0, p0.empty() ? 0 : p0.size() - 1, 1)) + " and " +
                fullPrec(ptAt(p1, p1.empty() ? 0 : p1.size() - 1, 1)));
      check(std::fabs(ptAt(p0, p0.empty() ? 0 : p0.size() - 1, 0) - 3.0) < 1e-12 &&
                std::fabs(ptAt(p1, p1.empty() ? 0 : p1.size() - 1, 0) - 6.0) < 1e-12,
            "AER-GRAPHX (x): ...and the groups hold DIFFERENT data (max x 3 and 6, in "
            "ascending group order). Two layers with the same x range would mean the split "
            "reached the legend and not the points. Got " +
                fullPrec(ptAt(p0, p0.empty() ? 0 : p0.size() - 1, 0)) + " and " +
                fullPrec(ptAt(p1, p1.empty() ? 0 : p1.size() - 1, 0)));
    }
  }

  // ── (xi) grstyle's accept-note is pinned LITERALLY. ───────────────────────
  // The note IS the feature. An accept-note exists so the user is told that
  // their styling did not take effect; a silent no-op is the same behaviour
  // with the evidence removed, and it passes every rc check ever written. So
  // the assertion is the exact sentence, byte for byte, including the em dash
  // -- the same standard the extcompat gate message is held to.
  {
    const std::string kNote =
        "(grstyle: scheme styling is not applied in this build — accepted and ignored)";
    // No `use` anywhere below: grstyle is on kNoDataCommands, and `grstyle
    // init` is routinely the first line of a do-file.
    const char* kForms[] = {"grstyle init", "grstyle set color hue", "grstyle clear"};
    for (const char* form : kForms) {
      piet::SessionState s(workdir);
      seed(s);
      auto blocks = piet::dispatch(form, s);
      const nlohmann::ordered_json e = firstError(blocks);
      check(e.is_null(),
            std::string("AER-GRAPHX (xi): `") + form +
                "` is ACCEPTED (rc 0), not refused -- a refusal stops every do-file that opens "
                "with it, before any real work. Got `" + errText(e) + "`");
      const std::vector<std::string> d = displays(blocks);
      check(!d.empty() && d[0] == kNote,
            std::string("AER-GRAPHX (xi): ...and it SAYS SO, byte for byte. A silent no-op is "
                        "this same behaviour with the evidence removed and passes every return-"
                        "code check. Expected `") +
                kNote + "`, got `" + (d.empty() ? std::string("<no display block>") : d[0]) + "`");
    }
  }

  // ── (xii) event_plot keeps the stub coefficients, in RELATIVE-TIME order. ─
  // The regressors are handed to `regress` in a DELIBERATELY SCRAMBLED order
  // (L1, F2, ctrl, L0, L2, F1) so that this leg separates three different
  // wrong forwards, all of which return a coefplot block at rc 0:
  //   - no filtering at all      -> 7 coefs including ctrl and _cons;
  //   - filtering, no reordering -> the 5 right coefs in coeftable order
  //                                 (L1ev F2ev L0ev L2ev F1ev), which plots a
  //                                 sawtooth "event study" whose x axis is not
  //                                 time at all;
  //   - the contract              -> F2ev F1ev L0ev L1ev L2ev.
  // The scramble is what makes the ORDER check able to fail; with the natural
  // declaration order the two middle cases are indistinguishable.
  {
    piet::SessionState s(workdir);
    seed(s);
    (void)exec("clear\n"
               "set obs 12\n"
               "gen F2ev = (_n <= 2)\n"
               "gen F1ev = (_n > 2 & _n <= 4)\n"
               "gen L0ev = (_n > 4 & _n <= 6)\n"
               "gen L1ev = (_n > 6 & _n <= 8)\n"
               "gen L2ev = (_n > 8 & _n <= 10)\n"
               "gen ctrl = _n\n"
               "gen ey = _n*_n\n"
               "regress ey L1ev F2ev ctrl L0ev L2ev F1ev\n"
               "eststo ev1\n",
               s);
    auto r = exec("event_plot ev1, stub_lag(L#ev) stub_lead(F#ev)\n", s);
    check(firstError(r.blocks).is_null(),
          "AER-GRAPHX (xii): `event_plot ev1, stub_lag(L#ev) stub_lead(F#ev)` runs clean. Got `" +
              errText(firstError(r.blocks)) + "`");
    const nlohmann::ordered_json blk = graphBlock(r.blocks);
    check(gstr(blk, "kind") == "coefplot",
          "AER-GRAPHX (xii): ...and forwards to the coefplot block (this row is a shim over "
          "runCoefplot, not a new renderer). Got kind `" + gstr(blk, "kind") + "`");
    const nlohmann::ordered_json models = garr(blk, "models");
    check(models.size() == 1,
          "AER-GRAPHX (xii): ...for the ONE named model. Got " + std::to_string(models.size()));
    std::vector<std::string> got;
    if (!models.empty())
      for (const auto& c : garr(models[0], "coefs")) got.push_back(gstr(c, "name"));
    check(got.size() == 5,
          "AER-GRAPHX (xii): ...and exactly the FIVE stub matches survive. 7 means the stub "
          "filter never ran and `ctrl` and `_cons` are being plotted as event-time "
          "coefficients. Got " + std::to_string(got.size()) + ": " + joinNames(got));
    check(joinNames(got) == "F2ev F1ev L0ev L1ev L2ev",
          "AER-GRAPHX (xii): ...in RELATIVE-TIME order -- leads most-negative first, then lags. "
          "The regressors were declared scrambled on purpose, so a forward that filtered but "
          "did not reorder answers `L1ev F2ev L0ev L2ev F1ev` here: a plausible plot of the "
          "right coefficients against the wrong axis. Got: " + joinNames(got));
  }

  // ── (xiii) event_plot's two refusals say which half of the line is wrong. ─
  // Both matter because both silently degrade otherwise: a stub that matches
  // nothing must not fall back to "plot every coefficient" (which is a chart of
  // the controls), and omitting the stubs entirely must not be read as "plot
  // everything" either.
  {
    piet::SessionState s(workdir);
    seed(s);
    (void)exec("clear\n"
               "set obs 12\n"
               "gen F1ev = (_n <= 4)\n"
               "gen L0ev = (_n > 4 & _n <= 8)\n"
               "gen ctrl = _n\n"
               "gen ey = _n*_n\n"
               "regress ey F1ev L0ev ctrl\n"
               "eststo ev2\n",
               s);
    auto r = exec("event_plot ev2, stub_lag(zz#)\n", s);
    const nlohmann::ordered_json e = firstError(r.blocks);
    check(!e.is_null(),
          "AER-GRAPHX (xiii): a stub matching NO coefficient is refused, not quietly widened to "
          "'plot them all' -- which would render the controls as an event study.");
    check(has(errText(e), "no coefficients match"),
          "AER-GRAPHX (xiii): ...and the sentence says the stubs matched nothing, which is the "
          "half of the line the user has to fix. Got `" + errText(e) + "`");
    auto r2 = exec("event_plot ev2\n", s);
    const nlohmann::ordered_json e2 = firstError(r2.blocks);
    check(!e2.is_null() && errField(e2, "code") == "syntax_error" && rcOf(e2) == "198",
          "AER-GRAPHX (xiii): ...and event_plot with NEITHER stub option is a syntax error "
          "r(198), not a silent forward to a plain coefplot. Got code `" +
              errField(e2, "code") + "` rc " + rcOf(e2));
  }

  // ── (xiv) grstyle / grc1leg2 / event_plot run with NO dataset loaded. ─────
  // BUG-343's class, and the reason bundle D exists: the registry row and the
  // dispatcher arm can both be right and the command still answers "No dataset
  // is loaded" because its name is missing from kNoDataCommands. `grstyle
  // init` is a preamble line; grc1leg2 and event_plot read named graphs and
  // stored estimates, which outlive the `clear` in front of them. Only the
  // no_data_loaded code is under test -- these two legitimately erroring for
  // want of a graph or an estimate is fine here.
  {
    const char* kProbes[] = {"grstyle init", "grc1leg2 g1 g2", "event_plot"};
    for (const char* probe : kProbes) {
      piet::SessionState s(workdir);  // deliberately NO use/sysuse
      seed(s);
      auto blocks = piet::dispatch(probe, s);
      bool sawNoData = false;
      for (const auto& b : blocks)
        if (b.is_object() && b.value("code", std::string()) == "no_data_loaded") sawNoData = true;
      check(!sawNoData, std::string("AER-GRAPHX (xiv): `") + probe +
                            "` runs with no dataset loaded (kNoDataCommands)");
    }
  }

  // ── (xv) the UNREGISTERED names answer a generic r(199) and nothing more. ─
  // These are asserted at the generic shape only: a check pinning a specific
  // `reason` string for a name with no registry row would be asserting a
  // promise this tree does not make.
  //
  // `grc1leg` USED TO HEAD THIS LIST, and the arm below it is where it went.
  // The reason it was here was that "its package states no author anywhere --
  // not in the ado, not in the help file", and that is still true of both of
  // those files; what changed is that a third place was found (the installer's
  // own record of the .pkg description) and it names Vince Wiggins. A refusal
  // whose stated ground was "unmeasured" is INVERTED by the measurement, not
  // deleted -- so the protection this arm gave (nobody ships an unattributed
  // community command at rc 0) is re-keyed onto the attribution itself rather
  // than dropped along with the name.
  {
    piet::SessionState s(workdir);
    seed(s);
    (void)exec(kThreeGraphs, s);
    const char* kUnregistered[] = {"cibar gy", "spmap", "binsreg gy gx",
                                   "maptile gy",    "shp2dta",  "geoinpoly", "heatplot gy",
                                   "distplot gy"};
    for (const char* cmd : kUnregistered) {
      auto blocks = piet::dispatch(cmd, s);
      const nlohmann::ordered_json e = firstError(blocks);
      check(!e.is_null() && errField(e, "code") == "unsupported_command" && rcOf(e) == "199",
            std::string("AER-GRAPHX (xv): `") + cmd +
                "` answers the GENERIC unsupported-command r(199) -- it has no registry row, "
                "because its package claims no author. Got code `" + errField(e, "code") +
                "` rc " + rcOf(e));
      check(graphBlock(blocks).is_null(),
            std::string("AER-GRAPHX (xv): ...and `") + cmd +
                "` produces NO graph block.");
    }
  }

  // ── (xv-b) `grc1leg` is the INVERSION of the arm above, and it asserts the
  // same thing from the other side: no unattributed community command ships at
  // rc 0. It now answers, so the two halves of that promise are (1) it really
  // does draw, and (2) the registry really does carry the author -- checked
  // here together, because either one alone is the failure this guards.
  {
    piet::SessionState s(workdir);
    seed(s);
    (void)exec(kThreeGraphs, s);
    auto blocks = piet::dispatch("grc1leg g1 g2", s);
    check(firstError(blocks).is_null() && !graphBlock(blocks).is_null(),
          "AER-GRAPHX (xv-b): `grc1leg g1 g2` now DRAWS -- Vince Wiggins' original answered by "
          "Mead Over's grc1leg2 rewrite, an ACCEPTED-NAMED substitution");
    const piet::registry::CommunityName* cn = piet::registry::findCommunityName("grc1leg");
    const std::string author = cn == nullptr ? std::string() : cn->author;
    check(cn != nullptr && author.find("Wiggins") != std::string::npos,
          "AER-GRAPHX (xv-b): ...and its registry row NAMES the author, which is the whole "
          "reason the un-suffixed spelling was refused until today. Got `" + author + "`");
  }

  // ── (xvi) the community-name gate reaches this bundle. ────────────────────
  // Pattern and ISOLATION read from testAerGtoolsBundle's identical leg: `set
  // extcompat off` moves PERSISTED settings, and a gate that writes the
  // operator's real settings file is the BUG-346 class, so the store is
  // pointed at this function's own workdir and the previous value is RESTORED
  // rather than unset (the harness pins PIET_SETTINGS_FILE on some runs).
  // POSIX-only, and the skip is named rather than left to be discovered: the
  // isolation needs setenv/unsetenv. What is lost on Windows is this bundle's
  // MEMBERSHIP in the gate; testExtcompatGate still covers the mechanism.
#ifndef _WIN32
  {
    const char* prevSettings = std::getenv("PIET_SETTINGS_FILE");
    const std::string savedSettings = prevSettings ? prevSettings : "";
    const std::string ownSettings = (fs::path(workdir) / "settings.json").u8string();
    setenv("PIET_SETTINGS_FILE", ownSettings.c_str(), 1);

    piet::SessionState s(workdir);
    seed(s);
    (void)exec("clear\nset obs 5\ngen cv = _n\n", s);
    (void)piet::dispatch("set extcompat off", s);
    auto blocks = piet::dispatch("cdfplot cv", s);
    const nlohmann::ordered_json e = firstError(blocks);
    check(!e.is_null() && errField(e, "code") == "unsupported_command" &&
              errField(e, "token") == "cdfplot",
          "AER-GRAPHX (xvi): a bundle-J name is gated exactly as `reghdfe` is -- all six rows "
          "are community spellings and the opt-out has to reach them, or the setting promises "
          "an isolation it does not deliver. Got code `" + errField(e, "code") + "` token `" +
              errField(e, "token") + "`");
    check(!e.is_null() && rcOf(e) == "199",
          "AER-GRAPHX (xvi): ...and the gate maps to r(199). Got rc " + rcOf(e));

    // Restore ORDER matters: env var first, then invalidate the cache, then
    // force the process default. Invalidating after the set would re-resolve
    // the flag from the restored store and silently undo the restore.
    if (!savedSettings.empty()) {
      setenv("PIET_SETTINGS_FILE", savedSettings.c_str(), 1);
    } else {
      unsetenv("PIET_SETTINGS_FILE");
    }
    piet::settings::invalidateExtcompatCache();
    piet::settings::setExtcompatEnabled(true);
    // Verified by DISPATCHING the name again, not by reading the flag back:
    // the flag was written by the line directly above, so reading it proves
    // the setter works and nothing about the gate. The cases after this one
    // inherit whatever this leg leaves behind.
    auto again = piet::dispatch("cdfplot cv", s);
    const nlohmann::ordered_json againErr = firstError(again);
    check(againErr.is_null() || errField(againErr, "code") != "unsupported_command",
          "AER-GRAPHX (xvi): ...and once the default is restored the name ANSWERS again, so "
          "this function hands the following cases the state they were written against.");
  }
#endif

  fs::remove_all(workdir, ec);
}


void testBug341VarSubscript() {
  std::printf("[selftest] --- BUG-341 `display var[i]` over a resident/virtual head ---\n");
  namespace fs = std::filesystem;
  std::string workdir = (fs::temp_directory_path() / "piet_native_selftest_bug341").u8string();
  std::error_code ec;
  fs::remove_all(workdir, ec);
  fs::create_directories(workdir, ec);

  auto displays = [](const auto& blocks) {
    std::vector<std::string> out;
    for (const auto& b : blocks)
      if (b.is_object() && b.value("type", std::string()) == "display")
        out.push_back(b.value("text", std::string()));
    return out;
  };

  piet::SessionState session(workdir);
  std::string src =
      "clear\nset obs 5\ngen double v = _n * 10\n"
      "display v[1]\ndisplay v[5]\ndisplay v[6]\ndisplay v[0]\n"
      "gen double z2 = v*2\ndisplay z2[1]\n";
  auto r = piet::doexec::executeDoSource(src, session, piet::dispatch);
  auto d = displays(r.blocks);
  int errs = 0;
  for (const auto& b : r.blocks)
    if (b.is_object() && b.value("type", std::string()) == "error") ++errs;
  check(errs == 0, "BUG-341: subscripted reads raise no error (was `matrix v not found`)");
  check(d.size() == 5, "BUG-341: five display lines came back (got " + std::to_string(d.size()) + ")");
  if (d.size() == 5) {
    check(d[0] == "10", "BUG-341: v[1] == 10 (Stata-measured), got `" + d[0] + "`");
    check(d[1] == "50", "BUG-341: v[5] == 50 (the last row), got `" + d[1] + "`");
    check(d[2] == ".", "BUG-341: v[6] is missing, not an error (Stata-measured)");
    check(d[3] == ".", "BUG-341: v[0] is missing — Stata subscripts are 1-based");
    check(d[4] == "20", "BUG-341: a column created THIS session reads through the virtual head "
                        "(z2[1] == 20), got `" + d[4] + "`");
  }
  // The matrix arm must still answer for a name that is neither variable nor matrix:
  // StataBE 19.5's `ZZZNOSUCH not found`, r(111) (BUG-1339 review, BUG-1402, 2026-11-03;
  // this arm pinned the old `matrix ZZZNOSUCH not found` at rc 1).
  {
    piet::SessionState s2(workdir);
    auto r2 = piet::doexec::executeDoSource("display ZZZNOSUCH[1,1]\n", s2, piet::dispatch);
    bool sawErr = false;
    for (const auto& b : r2.blocks)
      if (b.is_object() && b.value("type", std::string()) == "error" &&
          b.value("message", std::string()) == "ZZZNOSUCH not found" &&
          b.value("reason", std::string()) == "r(111)")
        sawErr = true;
    check(sawErr, "BUG-341: an undefined NAME[i,j] reports `NAME not found`, r(111) (BUG-162, BUG-1402)");
  }
}

void testP9ParallelBlock() {
  std::printf("[selftest] --- P9 `parallel, workers(N) { ... }` block form ---\n");
  namespace fs = std::filesystem;
  std::string workdir = (fs::temp_directory_path() / "piet_native_selftest_p9par").u8string();
  std::error_code ec;
  fs::remove_all(workdir, ec);
  fs::create_directories(workdir, ec);

  auto sawDisplay = [](const auto& blocks, const std::string& text) {
    for (const auto& b : blocks)
      if (b.is_object() && b.value("type", std::string()) == "display" &&
          b.value("text", std::string()) == text)
        return true;
    return false;
  };
  auto errorCount = [](const auto& blocks) {
    int n = 0;
    for (const auto& b : blocks)
      if (b.is_object() && b.value("type", std::string()) == "error") ++n;
    return n;
  };

  // --- Case 1: workers(1) runs every task, in source order, and does not halt.
  {
    piet::SessionState session(workdir);
    std::string src =
        "parallel, workers(1) {\n"
        "display \"p9_task_a\"\n"
        "display \"p9_task_b\"\n"
        "}\n"
        "display \"p9_after\"\n";
    auto r = piet::doexec::executeDoSource(src, session, piet::dispatch);
    check(!r.stoppedAtReason.has_value(),
          "P9: a clean `parallel, workers(1)` block does not halt, stop=" +
              r.stoppedAtReason.value_or("<none>"));
    check(sawDisplay(r.blocks, "p9_task_a") && sawDisplay(r.blocks, "p9_task_b"),
          "P9: every task in the block ran");
    check(sawDisplay(r.blocks, "p9_after"), "P9: execution continues after the block");
  }

  // --- Case 2: honest option errors. Each STOPS rather than being ignored --
  // a misspelt option that silently runs with the default is how a user ends up
  // believing they configured something they did not.
  {
    const std::vector<std::pair<std::string, std::string>> bad = {
        {"parallel, wokers(4) {\ndisplay \"x\"\n}\n", "misspelt option name"},
        {"parallel, workers(0) {\ndisplay \"x\"\n}\n", "workers(0)"},
        {"parallel workers(4) {\ndisplay \"x\"\n}\n", "options without the comma"},
    };
    for (const auto& [src, what] : bad) {
      piet::SessionState session(workdir);
      auto r = piet::doexec::executeDoSource(src, session, piet::dispatch);
      check(errorCount(r.blocks) > 0, "P9: " + what + " is an honest error, not a silent default");
    }
  }

  // --- Case 3: failure isolation (2.6) -- a failing task neither halts the
  // block nor hides itself, siblings still run, and _rc / r(n_failed) report it.
  {
    piet::SessionState session(workdir);
    std::string src =
        "parallel, workers(1) {\n"
        "display \"p9_iso_1\"\n"
        "summarize p9_no_such_variable\n"
        "display \"p9_iso_3\"\n"
        "}\n";
    auto r = piet::doexec::executeDoSource(src, session, piet::dispatch);
    check(!r.stoppedAtReason.has_value(), "P9: a failing task does not halt the do-file");
    check(sawDisplay(r.blocks, "p9_iso_1") && sawDisplay(r.blocks, "p9_iso_3"),
          "P9: tasks on both sides of a failing task still ran");
    check(errorCount(r.blocks) > 0, "P9: the failing task's error is VISIBLE, not swallowed");
    check(session.eval.locals.get("_rc") == "1",
          "P9: _rc is 1 after a task failed");
  }

  // --- Case 4: `capture, {` must NOT be parsed as a block head. The parallel
  // keyword is the first block head whose keyword may be followed by an option
  // comma, and the comma-stripping that allows it is deliberately scoped to
  // `parallel` alone -- widening it would silently turn `capture, {` into a
  // block and change what a pre-existing do-file means.
  {
    piet::SessionState session(workdir);
    auto r = piet::doexec::executeDoSource("capture, {\n", session, piet::dispatch);
    check(errorCount(r.blocks) > 0 || r.stoppedAtReason.has_value(),
          "P9: `capture, {` is NOT silently promoted to a brace block");
  }

  // --- Case 5: the task spec is the worker contract; pin its schema and the
  // inheritance set, since a child that silently loses `programs` fails as an
  // unknown command and reports something else entirely (BUG-342's second layer).
  {
    piet::SessionState session(workdir);
    (void)piet::dispatch("global p9g hello", session);
    piet::parallel::WorkerBudget budget = piet::parallel::resolveWorkers(2);
    auto spec = piet::parallel::buildTaskSpec({"display \"t\""}, session, budget, "");
    check(spec.value("schema", std::string()) == "piet.parallel.task_spec/2",
          "P9: task spec schema is task_spec/2");
    for (const char* key : {"locals", "globals", "scalars", "programs", "engine_threads",
                            "engine_memory_mb", "cwd", "parent_head", "set_state", "tasks"})
      check(spec.contains(key), std::string("P9: task spec carries `") + key + "`");
    // BUG-347: the `set` state must travel, and it must travel by VALUE — a
    // spec that carries the key with the parent's default in it would pass the
    // presence check above while still shipping the wrong flag.
    session.graphicsOff = true;
    session.level = 90;
    auto spec2 = piet::parallel::buildTaskSpec({"display \"t\""}, session, budget, "");
    check(spec2["set_state"].value("graphics_off", false) == true &&
              spec2["set_state"].value("level", 95) == 90,
          "BUG-347: task spec carries the parent's actual `set graphics off` / `set level`");
  }

  // --- Case 6: the BARE form. `parallel {` (and `parallel, {`) omits workers()
  // and asks the settings-derived pool size instead. The derivation itself is
  // pinned by the unit legs above; what was never executed end to end is the
  // PARSE branch that reaches it -- until this leg, the string `parallel {`
  // appeared nowhere in the repo, so a regression in `parseHeader`'s empty-tail
  // handling would have surfaced first in a user's do-file. Deliberately makes
  // no claim about N: the derived count depends on this machine's settings, and
  // every N >= 1 must run every task.
  {
    for (const char* head : {"parallel {\n", "parallel, {\n"}) {
      piet::SessionState session(workdir);
      std::string src = std::string(head) +
                        "display \"p9_bare_a\"\n"
                        "display \"p9_bare_b\"\n"
                        "}\n"
                        "display \"p9_bare_after\"\n";
      auto r = piet::doexec::executeDoSource(src, session, piet::dispatch);
      std::string what = std::string("`") + (head[8] == ',' ? "parallel, {" : "parallel {") + "`";
      check(!r.stoppedAtReason.has_value(),
            "P9 bare: " + what + " does not halt, stop=" + r.stoppedAtReason.value_or("<none>"));
      check(errorCount(r.blocks) == 0, "P9 bare: " + what + " raises no error");
      check(sawDisplay(r.blocks, "p9_bare_a") && sawDisplay(r.blocks, "p9_bare_b"),
            "P9 bare: every task ran under " + what);
      check(sawDisplay(r.blocks, "p9_bare_after"),
            "P9 bare: execution continues after " + what);
    }
    // The bare form's budget is the derived one, and it must satisfy the same
    // floor/cap the formula legs pin -- read here through the resolve path the
    // block actually uses, not through deriveDefaultWorkers directly.
    piet::parallel::WorkerBudget derived = piet::parallel::resolveWorkers(0);
    check(derived.n >= 1 && derived.n <= 4,
          "P9 bare: the derived worker count is inside [1, 4], got " + std::to_string(derived.n));
    check(!derived.reason.empty(),
          "P9 bare: the derived budget names its reason (the banner prints it)");
  }

  // --- Case 7 (BUG-1131): a local holding a byte that is not UTF-8 (a line
  // `file read` brought back from a Latin-1 file) reaches the workers with its
  // bytes intact. The spec and result were JSON text, whose dump threw
  // type_error.316 and ended the whole run. Each task generates a column that
  // never comes back to the parent, which is how the arm knows it fanned out.
  {
    piet::SessionState session(workdir);
    session.eval.locals.set("p9l", std::string("caf\xE9 12"));
    std::string src =
        "clear\n"
        "set obs 1\n"
        "parallel, workers(2) {\n"
        "generate p9u1 = 1\n"
        "display \"p9_latin1 \" strlen(`\"`macval(p9l)'\"')\n"
        "}\n"
        "display \"p9_latin1_after\"\n";
    auto r = piet::doexec::executeDoSource(src, session, piet::dispatch);
    piet::Datastore* ds = session.datastore();
    const std::string label = "BUG-1131 parallel: a Latin-1 local reaches the workers byte for byte";
    if (ds == nullptr || ds->has("p9u1")) {
      skip(label, "the block ran serially (budget 1 or no sibling piet_native)");
    } else {
      check(!r.stoppedAtReason.has_value() && sawDisplay(r.blocks, "p9_latin1 7") &&
                sawDisplay(r.blocks, "p9_latin1_after"),
            label + " (strlen 7, the run goes on), stop=" + r.stoppedAtReason.value_or("<none>"));
    }
  }
}

void testBUG132QuietlyNoisilyBlock() {
  std::printf("[selftest] --- BUG-132 `quietly { ... }` / `noisily { ... }` block syntax ---\n");
  namespace fs = std::filesystem;
  std::string workdir = (fs::temp_directory_path() / "piet_native_selftest_bug132").u8string();
  std::error_code ec;
  fs::remove_all(workdir, ec);
  fs::create_directories(workdir, ec);

  // Pre-fix (BUG-132), `quietly {`/`noisily {` were never in loopIfKeywords,
  // so aggregateBraces never recognised the block: the bare `{` dispatched as
  // an unknown command → "unsupported command" halt at the opening brace, body
  // 0 lines run. These legs lock the fixed behaviour: block parses, body runs,
  // quietly suppresses / noisily shows, and (unlike capture) an uncaught error
  // still HALTS.
  auto sawDisplay = [](const auto& blocks, const std::string& text) {
    for (const auto& b : blocks)
      if (b.is_object() && b.value("type", std::string()) == "display" &&
          b.value("text", std::string()) == text)
        return true;
    return false;
  };
  auto sawSummarizeOf = [](const auto& blocks, const std::string& var) {
    for (const auto& b : blocks)
      if (b.is_object() && b.value("type", std::string()) == "summarize" && b.contains("stats") &&
          b["stats"].is_object() && b["stats"].contains(var))
        return true;
    return false;
  };
  auto sawUncapturedError = [](const auto& blocks) {
    for (const auto& b : blocks)
      if (b.is_object() && b.value("type", std::string()) == "error" &&
          !b.value("captured", false))
        return true;
    return false;
  };

  // --- Case 1: quietly { ... } with a CLEAN body: body RUNS, output HIDDEN.
  {
    piet::SessionState session(workdir);
    (void)piet::dispatch("sysuse fatalities, clear", session);
    std::string src =
        "quietly {\n"
        "    summarize spirits\n"
        "    gen bug132qmark = year\n"
        "    display \"bug132_quietly_hidden\"\n"
        "}\n"
        "summarize bug132qmark\n";
    auto result = piet::doexec::executeDoSource(src, session, piet::dispatch);

    check(!result.stoppedAtReason.has_value(),
          "BUG-132: a clean `quietly { ... }` block does NOT halt (pre-fix it died on the bare "
          "`{`), stop=" + result.stoppedAtReason.value_or("<none>"));
    check(!sawDisplay(result.blocks, "bug132_quietly_hidden"),
          "BUG-132: `display` INSIDE the quietly block is suppressed");
    check(!sawSummarizeOf(result.blocks, "spirits"),
          "BUG-132: `summarize spirits` INSIDE the quietly block is suppressed");
    check(sawSummarizeOf(result.blocks, "bug132qmark"),
          "BUG-132: the body actually RAN — `gen bug132qmark` inside the quietly block created the "
          "variable, proven by the post-block `summarize bug132qmark` (outside quietly) showing it");
  }

  // --- Case 2: quietly { ... } with an ERROR: HALTS (quietly != capture).
  {
    piet::SessionState session(workdir);
    (void)piet::dispatch("sysuse fatalities, clear", session);
    std::string src =
        "quietly {\n"
        "    summarize nosuchvar_bug132\n"
        "    display \"bug132_after_error_in_block\"\n"
        "}\n"
        "display \"bug132_after_error_block\"\n";
    auto result = piet::doexec::executeDoSource(src, session, piet::dispatch);

    check(result.stoppedAtReason.has_value(),
          "BUG-132: an uncaught error inside `quietly { ... }` HALTS the do-file (quietly is "
          "output-only, it does NOT catch errors the way capture does)");
    check(sawUncapturedError(result.blocks),
          "BUG-132: the error message is still surfaced under quietly (quietly suppresses normal "
          "output, not errors)");
    check(!sawDisplay(result.blocks, "bug132_after_error_in_block"),
          "BUG-132: the line AFTER the error, inside the block, never ran (block halted)");
    check(!sawDisplay(result.blocks, "bug132_after_error_block"),
          "BUG-132: the do-file halted — nothing past the whole quietly block ran");
  }

  // --- Case 3: noisily { ... } with a CLEAN body: output SHOWN (transparent).
  {
    piet::SessionState session(workdir);
    (void)piet::dispatch("sysuse fatalities, clear", session);
    std::string src =
        "noisily {\n"
        "    summarize spirits\n"
        "    display \"bug132_noisily_shown\"\n"
        "}\n";
    auto result = piet::doexec::executeDoSource(src, session, piet::dispatch);

    check(!result.stoppedAtReason.has_value(), "BUG-132: a clean `noisily { ... }` block does NOT halt");
    check(sawSummarizeOf(result.blocks, "spirits"),
          "BUG-132: `summarize spirits` inside `noisily { ... }` IS shown (noisily is transparent)");
    check(sawDisplay(result.blocks, "bug132_noisily_shown"),
          "BUG-132: `display` inside `noisily { ... }` IS shown");
  }

  // --- Case 4: noisily { ... } with an ERROR: also HALTS (class parity).
  {
    piet::SessionState session(workdir);
    (void)piet::dispatch("sysuse fatalities, clear", session);
    std::string src =
        "noisily {\n"
        "    summarize nosuchvar_bug132b\n"
        "    display \"bug132_noisily_after_error\"\n"
        "}\n"
        "display \"bug132_noisily_after_block\"\n";
    auto result = piet::doexec::executeDoSource(src, session, piet::dispatch);

    check(result.stoppedAtReason.has_value(),
          "BUG-132: an uncaught error inside `noisily { ... }` also HALTS the do-file");
    check(!sawDisplay(result.blocks, "bug132_noisily_after_error"),
          "BUG-132: the line after the error inside the noisily block never ran");
    check(!sawDisplay(result.blocks, "bug132_noisily_after_block"),
          "BUG-132: the do-file halted past the noisily block");
  }

  // --- Case 5: abbreviation routing (A11 class sweep) — `qui {` / `noi {`.
  {
    piet::SessionState session(workdir);
    (void)piet::dispatch("sysuse fatalities, clear", session);
    std::string src =
        "qui {\n"
        "    gen bug132abbrev = 1\n"
        "    summarize spirits\n"
        "}\n"
        "noi {\n"
        "    summarize spirits\n"
        "}\n"
        "summarize bug132abbrev\n";
    auto result = piet::doexec::executeDoSource(src, session, piet::dispatch);

    check(!result.stoppedAtReason.has_value(),
          "BUG-132 A11: abbreviated `qui {`/`noi {` blocks parse + run (no halt on `{`)");
    check(sawSummarizeOf(result.blocks, "spirits"),
          "BUG-132 A11: `noi { summarize spirits }` shows its output (abbrev routes to noisily)");
    check(sawSummarizeOf(result.blocks, "bug132abbrev"),
          "BUG-132 A11: `gen` inside `qui { ... }` ran (abbrev routes to quietly, body executed)");
  }

  fs::remove_all(workdir, ec);
}

// BUG-167: a brace INSIDE a prefixed command's arguments was read as a block
// opener. `capture noisily nl (y = {b0=2}+{b1=.5}*x1)` has `capture` first and
// a `{` later, which is all the old predicate
// (`isLoopHeader(line) && line.find('{') != npos`) required — so the aggregator
// built a block headed `capture noisily nl (y = {`, ran `b0=2` as its body, and
// DROPPED `+{b1=.5}*x1)` entirely. The command the user typed never reached the
// dispatcher: no "nl is unsupported" error, `_rc` set to 1 by an unrelated
// statement. A command silently replaced by a fragment of its own arguments is
// the silent-wrong class, so these legs are the RED certificate for the fix
// (each Case-1 leg FAILS against the pre-fix predicate).
void testBUG167BraceInsidePrefixedArgs() {
  std::printf("[selftest] --- BUG-167 brace inside a prefixed command's arguments ---\n");
  namespace fs = std::filesystem;
  std::string workdir = (fs::temp_directory_path() / "piet_native_selftest_bug167").u8string();
  std::error_code ec;
  fs::remove_all(workdir, ec);
  fs::create_directories(workdir, ec);

  auto sawEchoContaining = [](const auto& blocks, const std::string& needle) {
    for (const auto& b : blocks)
      if (b.is_object() && b.value("type", std::string()) == "echo" &&
          b.value("text", std::string()).find(needle) != std::string::npos)
        return true;
    return false;
  };
  auto sawDisplay = [](const auto& blocks, const std::string& text) {
    for (const auto& b : blocks)
      if (b.is_object() && b.value("type", std::string()) == "display" &&
          b.value("text", std::string()) == text)
        return true;
    return false;
  };

  // --- Case 1: the defect itself. The braces belong to nl's parameter syntax.
  {
    piet::SessionState session(workdir);
    (void)piet::dispatch("sysuse fatalities, clear", session);
    // Uses an UNIMPLEMENTED command deliberately. The defect was found with
    // `nl`, but `nl` landed later in this same wave, and pinning the rc to 199
    // against a command that now works would make this leg assert the
    // implementation calendar instead of the parse. The invariant under test is
    // the brace handling, which is command-independent.
    std::string src =
        "capture noisily nosuchverb_bug167 (y = {b0=2}+{b1=.5}*spirits)\n"
        "display \"bug167_rc=\" _rc\n";
    auto result = piet::doexec::executeDoSource(src, session, piet::dispatch);

    check(!sawEchoContaining(result.blocks, ".  b0=2"),
          "BUG-167: `b0=2` is NOT executed as a statement of its own (pre-fix it was the block "
          "body)");
    check(sawEchoContaining(result.blocks, "nosuchverb_bug167 (y ="),
          "BUG-167: the whole braced line reaches the dispatcher intact (pre-fix it was consumed "
          "as a block header and never dispatched)");
    check(sawDisplay(result.blocks, "bug167_rc=199"),
          "BUG-167: the captured rc is the honest unsupported-command 199 (pre-fix: 1, set by the "
          "smuggled `b0=2`)");
  }

  // --- Case 2: genuine inline blocks still parse (the fix must not overreach).
  {
    piet::SessionState session(workdir);
    (void)piet::dispatch("sysuse fatalities, clear", session);
    std::string src =
        // BUG-1434: a bare capture block hides ordinary output; its noisily
        // line shows (StataBE 19.5), which is what proves the block ran.
        "capture { noisily display \"bug167_capture_inline\" }\n"
        "quietly { display \"bug167_quietly_inline\" }\n"
        "capture noisily { display \"bug167_capnoi_inline\" }\n"
        "forvalues i=1/3 { display \"bug167_loop\" }\n"
        "if 1==1 { display \"bug167_if_inline\" }\n";
    auto result = piet::doexec::executeDoSource(src, session, piet::dispatch);

    check(!result.stoppedAtReason.has_value(),
          "BUG-167: the legal inline brace forms still parse, stop=" +
              result.stoppedAtReason.value_or("<none>"));
    check(sawDisplay(result.blocks, "bug167_capture_inline"), "BUG-167: `capture { ... }` inline");
    check(!sawDisplay(result.blocks, "bug167_quietly_inline"),
          "BUG-167: `quietly { ... }` inline still suppresses");
    check(sawDisplay(result.blocks, "bug167_capnoi_inline"),
          "BUG-167: `capture noisily { ... }` inline (multi-keyword prefix header)");
    check(sawDisplay(result.blocks, "bug167_loop"), "BUG-167: `forvalues ... { ... }` inline");
    check(sawDisplay(result.blocks, "bug167_if_inline"), "BUG-167: `if COND { ... }` inline");
  }

  // --- Case 3: the control class keeps its permissive rule — a `{` after a
  // list/condition still opens a block even though the header is not a bare
  // keyword. This is the asymmetry the fix deliberately encodes.
  {
    piet::SessionState session(workdir);
    (void)piet::dispatch("sysuse fatalities, clear", session);
    std::string src = "foreach v in spirits beertax { display \"bug167_foreach\" }\n";
    auto result = piet::doexec::executeDoSource(src, session, piet::dispatch);
    check(sawDisplay(result.blocks, "bug167_foreach"),
          "BUG-167: `foreach v in ... { ... }` — header carries the list, brace still opens");
  }

  fs::remove_all(workdir, ec);
}

// BUG-154: a taken `exit [N]` inside a brace block was silently IGNORED — the
// inner executeDoSource consumed AND ERASED the clean-exit halt sentinel, so
// nothing bubbled up to re-halt the outer level: `if (cond) { exit 7 }` fell
// through and every statement after the block still ran (failure guards were
// dead — silent-wrong class). The fix re-emits the sentinel from runBody and
// carries the exact code to capture's _rc. Oracle for every leg: StataBE 19.5
// (capture{exit 5} → _rc 5, verified live 2026-08-04).
void testBUG154ExitInBlock() {
  std::printf("[selftest] --- BUG-154 `exit` inside brace blocks halts the do-file ---\n");
  namespace fs = std::filesystem;
  std::string workdir = (fs::temp_directory_path() / "piet_native_selftest_bug154").u8string();
  std::error_code ec;
  fs::remove_all(workdir, ec);
  fs::create_directories(workdir, ec);

  auto sawDisplay = [](const auto& blocks, const std::string& text) {
    for (const auto& b : blocks)
      if (b.is_object() && b.value("type", std::string()) == "display" &&
          b.value("text", std::string()) == text)
        return true;
    return false;
  };

  // --- ① RED-cert arm (the pre-fix silent-wrong): taken guard HALTS with the
  //        requested code and nothing after the block runs. Pre-fix this arm
  //        fails exactly here: "bug154_after" printed and no exit code was set.
  {
    piet::SessionState session(workdir);
    (void)piet::dispatch("sysuse fatalities, clear", session);
    std::string src =
        "local rc = 7\n"
        "if `rc' != 0 {\n"
        "    exit `rc'\n"
        "}\n"
        "display \"bug154_after\"\n";
    auto result = piet::doexec::executeDoSource(src, session, piet::dispatch);
    check(result.stoppedAtExitCode.has_value() && *result.stoppedAtExitCode == 7,
          "BUG-154 ①: taken `if { exit 7 }` halts the do-file with code 7, got " +
              (result.stoppedAtExitCode.has_value() ? std::to_string(*result.stoppedAtExitCode)
                                                    : std::string("<none>")));
    check(!sawDisplay(result.blocks, "bug154_after"),
          "BUG-154 ①: nothing after a taken exit-guard runs (pre-fix it printed)");
  }

  // --- ② false guard: body SKIPPED, execution continues past the block.
  {
    piet::SessionState session(workdir);
    (void)piet::dispatch("sysuse fatalities, clear", session);
    std::string src =
        "if 0 != 0 {\n"
        "    exit 9\n"
        "}\n"
        "display \"bug154_false_ok\"\n";
    auto result = piet::doexec::executeDoSource(src, session, piet::dispatch);
    check(!result.stoppedAtExitCode.has_value() && !result.stoppedAtReason.has_value(),
          "BUG-154 ②: false guard does not halt");
    check(sawDisplay(result.blocks, "bug154_false_ok"),
          "BUG-154 ②: execution continues after a false guard");
  }

  // --- ③ nested if-in-if: the halt propagates through EVERY level.
  {
    piet::SessionState session(workdir);
    (void)piet::dispatch("sysuse fatalities, clear", session);
    std::string src =
        "if 1 {\n"
        "    if 2 > 1 {\n"
        "        exit 5\n"
        "    }\n"
        "    display \"bug154_inner_after\"\n"
        "}\n"
        "display \"bug154_outer_after\"\n";
    auto result = piet::doexec::executeDoSource(src, session, piet::dispatch);
    check(result.stoppedAtExitCode.has_value() && *result.stoppedAtExitCode == 5,
          "BUG-154 ③: nested `exit 5` halts with code 5 through both levels");
    check(!sawDisplay(result.blocks, "bug154_inner_after") &&
              !sawDisplay(result.blocks, "bug154_outer_after"),
          "BUG-154 ③: neither inner-after nor outer-after ran");
  }

  // --- ④ foreach body: `exit` stops the WHOLE file mid-iteration.
  {
    piet::SessionState session(workdir);
    (void)piet::dispatch("sysuse fatalities, clear", session);
    std::string src =
        "local n = 0\n"
        "foreach k in 1 2 3 {\n"
        "    if `k' == 2 {\n"
        "        exit 3\n"
        "    }\n"
        "    local n = `n' + 1\n"
        "}\n"
        "display \"bug154_post_loop\"\n";
    auto result = piet::doexec::executeDoSource(src, session, piet::dispatch);
    check(result.stoppedAtExitCode.has_value() && *result.stoppedAtExitCode == 3,
          "BUG-154 ④: exit inside a foreach body halts the file with code 3");
    check(!sawDisplay(result.blocks, "bug154_post_loop"),
          "BUG-154 ④: nothing after the loop runs");
    check(session.eval.locals.get("n", "") == "1",
          "BUG-154 ④: iteration 2 stopped mid-body (n stayed 1), got n=" +
              session.eval.locals.get("n", "<unset>"));
  }

  // --- ⑤ capture traps a clean exit with its EXACT code and continues
  //        (StataBE 19.5: `capture { exit 5 }` → _rc 5, file continues).
  {
    piet::SessionState session(workdir);
    (void)piet::dispatch("sysuse fatalities, clear", session);
    std::string src =
        "capture {\n"
        "    exit 5\n"
        "}\n"
        "display \"bug154_continued\"\n";
    auto result = piet::doexec::executeDoSource(src, session, piet::dispatch);
    check(!result.stoppedAtExitCode.has_value() && !result.stoppedAtReason.has_value(),
          "BUG-154 ⑤: capture traps the exit — file does not halt");
    check(session.eval.locals.get("_rc", "") == "5",
          "BUG-154 ⑤: _rc carries the exact exit code 5 (oracle: StataBE 19.5), got _rc=" +
              session.eval.locals.get("_rc", "<unset>"));
    check(sawDisplay(result.blocks, "bug154_continued"),
          "BUG-154 ⑤: execution continues after the captured block");
  }

  fs::remove_all(workdir, ec);
}

// P1 wave: the .xlsx layer (piet/native/src/xlsx.{h,cpp}). The decisive leg is
// the REAL vector — a workbook written by Stata itself, whose parts are all
// DEFLATE-compressed, so it can only be read if the inflate implementation is
// correct. A self-roundtrip alone would prove nothing about that, because our
// own writer emits STORED entries.
void testP1XlsxLayer() {
  std::printf("[selftest] --- P1 xlsx: self-roundtrip, real Stata vector, honest rejects ---\n");
  namespace fs = std::filesystem;
  std::string workdir = (fs::temp_directory_path() / "piet_native_selftest_xlsx").u8string();
  std::error_code ec;
  fs::remove_all(workdir, ec);
  fs::create_directories(workdir, ec);

  // --- ① self-roundtrip: values and blanks survive a write/read cycle.
  {
    std::string path = workdir + "/rt.xlsx";
    std::vector<piet::xlsx::OutColumn> cols(2);
    cols[0].name = "num";
    cols[0].isNumber = {true, true, false};
    cols[0].isBlank = {false, false, true};
    cols[0].numbers = {1.5, -2.0, 0.0};
    cols[0].strings = {"", "", ""};
    cols[1].name = "txt";
    cols[1].isNumber = {false, false, false};
    cols[1].isBlank = {false, false, false};
    cols[1].numbers = {0, 0, 0};
    cols[1].strings = {"a,b", "quote\"inside", "<xml>&amp;"};
    bool wrote = true;
    try { piet::xlsx::write(path, cols, /*writeHeader=*/true); }
    catch (const std::exception&) { wrote = false; }
    check(wrote, "P1 xlsx ①: writer produced a workbook");

    if (wrote) {
      piet::xlsx::Sheet s = piet::xlsx::read(path, /*firstRowIsHeader=*/true);
      check(s.header.size() == 2 && s.header[0] == "num" && s.header[1] == "txt",
            "P1 xlsx ①: header round-trips");
      check(s.rows.size() == 3, "P1 xlsx ①: 3 data rows round-trip, got " +
                                    std::to_string(s.rows.size()));
      if (s.rows.size() == 3) {
        check(s.rows[0][0].isNumber && s.rows[0][0].number == 1.5,
              "P1 xlsx ①: a number round-trips exactly");
        check(s.rows[2][0].blank, "P1 xlsx ①: a blank cell stays blank");
        check(s.rows[1][1].text == "quote\"inside",
              "P1 xlsx ①: an embedded quote round-trips (XML escaping)");
        check(s.rows[2][1].text == "<xml>&amp;",
              "P1 xlsx ①: markup-looking text round-trips verbatim");
      }
    }
  }

  // --- ② REAL vector: Stata's own p8_results.xlsx (every part DEFLATEd).
  //        This is the leg that actually exercises inflate.
  {
    // The real workbook is a GENERATED artifact under the repo's waves dir (it
    // is gitignored bulk, so a clean checkout legitimately lacks it). Walk up
    // from the running binary to find the repo, and SKIP honestly when absent.
    std::string real;
    {
      std::optional<std::string> exe = piet::executablePath();
      fs::path dir = exe.has_value() ? fs::path(*exe).parent_path() : fs::current_path();
      for (int up = 0; up < 8 && !dir.empty(); ++up) {
        fs::path cand = dir / "tests" / "kitchensink" / "pangram" / "waves" / "_runs" / "p8_results.xlsx";
        if (fs::exists(cand)) { real = cand.u8string(); break; }
        if (!dir.has_parent_path() || dir.parent_path() == dir) break;
        dir = dir.parent_path();
      }
    }
    if (real.empty()) {
      skip("P1 xlsx ②: real Stata workbook", "generated artifact absent from this tree");
    } else {
      bool ok = true;
      size_t nrows = 0, ncols = 0;
      try {
        piet::xlsx::Sheet s = piet::xlsx::read(real, /*firstRowIsHeader=*/true);
        nrows = s.rows.size();
        ncols = s.header.size();
      } catch (const std::exception&) { ok = false; }
      check(ok, "P1 xlsx ②: a Stata-written (DEFLATE) workbook decompresses — inflate works");
      check(nrows == 4800, "P1 xlsx ②: real workbook yields its 4800 data rows, got " +
                               std::to_string(nrows));
      check(ncols > 0, "P1 xlsx ②: real workbook yields a header row");
    }
  }

  // --- ③ honest rejects: a non-ZIP and a truncated file must say so, not crash.
  {
    std::string bogus = workdir + "/not_a_workbook.xlsx";
    { std::ofstream f(bogus, std::ios::binary); f << "this is plainly not a zip archive"; }
    bool threw = false;
    try { (void)piet::xlsx::read(bogus, true); } catch (const std::exception&) { threw = true; }
    check(threw, "P1 xlsx ③: a non-ZIP file is an honest error, not a crash");
  }

  fs::remove_all(workdir, ec);
}

// AER scope-2 W3a: `import excel` / `export excel` / `import delimited`'s option
// cluster -- the highest-frequency one in the twelve-paper corpus (`import
// excel` appears 273 times, 243 of them in paper 015).
//
// The decisive leg is ⑤, and it is the reason this function exists at all. Until
// W3a the reader located "the worksheet" by trying xl/worksheets/sheet1.xml and
// then any xl/worksheets/*.xml, and NEVER opened xl/workbook.xml. Sheet order on
// disk is not sheet order in the workbook and the part filename carries no
// identity, so that reader returns a DIFFERENT SHEET at rc 0 with plausible
// numbers in it. Leg ⑤ builds exactly the package that exposes it -- one sheet,
// whose relationship Target is the package-absolute `/xl/worksheets/sheet2.xml`,
// with a decoy sheet1.xml also present -- and asserts the value that only a
// reader walking name -> r:id -> Target -> part can return.
void testW3aSpreadsheetOptions() {
  std::printf("[selftest] --- AER scope-2 W3a: import/export excel options + import delimited "
              "row/col windows ---\n");
  namespace fs = std::filesystem;
  std::string workdir = (fs::temp_directory_path() / "piet_native_selftest_w3a").u8string();
  std::error_code ec;
  fs::remove_all(workdir, ec);
  fs::create_directories(workdir, ec);
  auto at = [&](const std::string& rel) { return (fs::path(workdir) / rel).u8string(); };

  // A numeric column and a string column, in the OutColumn shape the writer takes.
  auto numCol = [](const std::string& name, std::vector<double> v) {
    piet::xlsx::OutColumn c;
    c.name = name;
    c.isNumber.assign(v.size(), true);
    c.isBlank.assign(v.size(), false);
    c.numbers = std::move(v);
    c.strings.assign(c.numbers.size(), std::string());
    return c;
  };

  const std::string book = at("w3a.xlsx");
  std::vector<piet::xlsx::OutColumn> alpha = {numCol("a1", {1, 2, 3}), numCol("a2", {4, 5, 6})};
  std::vector<piet::xlsx::OutColumn> beta = {numCol("x", {10, 20, 30}), numCol("y", {40, 50, 60}),
                                             numCol("z", {70, 80, 90})};
  bool built = true;
  try {
    piet::xlsx::write(book, alpha, /*writeHeader=*/true, "Alpha");
    piet::xlsx::writeSheetInto(book, "Beta", beta, /*writeHeader=*/true);
  } catch (const std::exception&) {
    built = false;
  }
  check(built, "W3a ①: `export excel, sheet(Alpha)` then `sheet(Beta) sheetreplace` builds a "
               "TWO-sheet workbook. This is the merge path -- read every part, insert the new "
               "worksheet, patch workbook.xml + its rels + [Content_Types].xml, repackage -- and a "
               "failure here means the workbook a user asked to add a sheet to was not rewritten.");

  if (built) {
    // ── ② the workbook names its sheets, and `describe` reads them from there.
    std::vector<piet::xlsx::SheetInfo> info;
    try { info = piet::xlsx::sheets(book); } catch (const std::exception&) {}
    check(info.size() == 2, "W3a ②: the merged workbook declares 2 worksheets, got " +
                                std::to_string(info.size()));
    if (info.size() == 2) {
      check(info[0].name == "Alpha" && info[1].name == "Beta",
            "W3a ②: sheets come back in WORKBOOK order with their declared names, got {" +
                info[0].name + ", " + info[1].name + "}");
      check(info[0].range == "A1:B4" && info[1].range == "A1:C4",
            "W3a ②: each sheet reports its own used range (r(range_#)), got {" + info[0].range +
                ", " + info[1].range + "}");
    }

    // ── ③ sheet("Beta") returns BETA. Alpha is 2 columns of 1..6, Beta is 3 of
    //      10..90, so a reader that picked the wrong part cannot pass this.
    {
      piet::xlsx::ReadOptions ro;
      ro.firstRowIsHeader = true;
      ro.sheetName = "Beta";
      piet::xlsx::Sheet s;
      bool ok = true;
      try { s = piet::xlsx::read(book, ro); } catch (const std::exception&) { ok = false; }
      check(ok && s.header.size() == 3, "W3a ③: sheet(\"Beta\") reads Beta's THREE columns, got " +
                                            std::to_string(s.header.size()));
      const double first = (!s.rows.empty() && !s.rows[0].empty() && s.rows[0][0].isNumber)
                               ? s.rows[0][0].number
                               : std::nan("");
      check(first == 10.0,
            "W3a ③: sheet(\"Beta\")'s first cell is Beta's 10, not Alpha's 1. A reader that guesses "
            "the part by filename answers 1 here -- at rc 0, with plausible data.");
      check(s.firstCol == 1, "W3a ③: with no cellrange the window starts at spreadsheet column A");
    }

    // ── ④ a MISSING sheet is Stata's r(601), with Stata's own sentence
    //      (aer_b4 pins_oracle_g.log:136-139).
    {
      piet::xlsx::ReadOptions ro;
      ro.sheetName = "NoSuchSheet";
      std::string got = "<no throw>";
      bool rightType = false;
      try {
        (void)piet::xlsx::read(book, ro);
      } catch (const piet::xlsx::SheetNotFound& e) {
        rightType = true;
        got = e.what();
      } catch (const std::exception& e) {
        got = e.what();
      }
      check(rightType && got == "worksheet NoSuchSheet not found",
            "W3a ④: a sheet name the workbook does not have throws SheetNotFound carrying Stata's "
            "captured message `worksheet NoSuchSheet not found`; got `" + got + "`");
    }

    // ── cellrange, closed and open-ended.
    {
      piet::xlsx::ReadOptions ro;
      ro.firstRowIsHeader = true;
      ro.sheetName = "Beta";
      ro.firstCol = 1; ro.firstRow = 1; ro.lastCol = 2; ro.lastRow = 4;
      piet::xlsx::Sheet s;
      bool ok = true;
      try { s = piet::xlsx::read(book, ro); } catch (const std::exception&) { ok = false; }
      check(ok && s.header.size() == 2 && s.rows.size() == 3,
            "W3a ⑤: a CLOSED cellrange(A1:B4) over Beta yields 2 vars x 3 obs, got " +
                std::to_string(s.header.size()) + " x " + std::to_string(s.rows.size()));
    }
    {
      // cellrange(B2): open on both ends of the far corner. The window starts at
      // spreadsheet column B, and firstCol is what keeps `import excel`'s default
      // names Stata's (`B`, `C`) instead of renaming the window's head to `A`.
      piet::xlsx::ReadOptions ro;
      ro.sheetName = "Beta";
      ro.firstCol = 2; ro.firstRow = 2;
      piet::xlsx::Sheet s;
      bool ok = true;
      try { s = piet::xlsx::read(book, ro); } catch (const std::exception&) { ok = false; }
      const double first = (ok && !s.rows.empty() && !s.rows[0].empty() && s.rows[0][0].isNumber)
                               ? s.rows[0][0].number
                               : std::nan("");
      check(ok && s.rows.size() == 3 && s.firstCol == 2 && first == 40.0,
            "W3a ⑤: an OPEN-ENDED cellrange(B2) yields the 3 data rows from column B on, and "
            "remembers that the window's first column IS spreadsheet column B (firstCol=" +
                std::to_string(s.firstCol) + ", first cell " +
                (std::isnan(first) ? std::string("<none>") : std::to_string(first)) + ")");
    }

    // ── B4 P2: a cellrange PAST the data area REFUSES, and the two axes say
    //    different things. W3a clamped and named it a limitation "not a measured
    //    Stata match"; oracle_q.log is the measurement, and it says r(198) with
    //    two distinct sentences (:74-79 column, :84-89 row). Beta is A1:C4, so
    //    Z is past its last column and 200 past its last row.
    //
    //    Both sentences are compared IN FULL, second line included, because the
    //    second line is the entire difference between them — an assertion on the
    //    first line alone would pass with the axes swapped.
    {
      struct Axis {
        int lastCol;
        int lastRow;
        bool wantColumn;
        std::string want;
        const char* range;
        const char* logLine;
      };
      const std::vector<Axis> kAxes = {
          {26, 4, true,
           "invalid column range in option cellrange();\n"
           "    The lower right column is right of the data area in the worksheet.",
           "A1:Z4", "oracle_q.log:74-79"},
          {3, 200, false,
           "invalid row range in option cellrange();\n"
           "    The lower right row is after the data area in the worksheet.",
           "A1:C200", "oracle_q.log:84-89"},
      };
      for (const auto& ax : kAxes) {
        piet::xlsx::ReadOptions ro;
        ro.firstRowIsHeader = true;
        ro.sheetName = "Beta";
        ro.firstCol = 1;
        ro.firstRow = 1;
        ro.lastCol = ax.lastCol;
        ro.lastRow = ax.lastRow;
        std::string got = "<no throw>";
        bool rightType = false;
        try {
          (void)piet::xlsx::read(book, ro);
        } catch (const piet::xlsx::CellRangeOutsideData& e) {
          rightType = e.isColumn == ax.wantColumn;
          got = e.what();
        } catch (const std::exception& e) {
          got = e.what();
        }
        check(rightType && got == ax.want,
              std::string("W3a/B4 P2: cellrange(") + ax.range +
                  ") past the data area throws CellRangeOutsideData on the right AXIS carrying "
                  "StataBE's own two-line sentence (" + ax.logLine +
                  ") -- before this it CLAMPED and returned data; got `" + got + "`");
      }
      // The user-visible surface: rc, not just the exception. r(198), which is
      // what `unsupported_option` maps to.
      {
        piet::SessionState session(
            (std::filesystem::temp_directory_path() / "piet_native_selftest_b4p2").u8string());
        std::string rc = "0";
        std::string msg;
        for (const auto& b : piet::dispatch(
                 "import excel using \"" + book + "\", sheet(\"Beta\") cellrange(A1:Z4) firstrow "
                 "clear",
                 session)) {
          if (!b.is_object() || b.value("type", std::string()) != "error") continue;
          rc = piet::eval::coarseRc(b);
          msg = b.value("message", std::string());
        }
        check(rc == "198",
              "W3a/B4 P2: ...and `import excel ..., cellrange(A1:Z4)` answers r(198) as StataBE "
              "does, not rc 0 with a clamped window; got " + rc);
        check(msg.find("invalid column range") != std::string::npos,
              "W3a/B4 P2: ...with Stata's wording reaching the user unprefixed; got " + msg);
      }
      // Non-regression: a range that ENDS EXACTLY on the data area is inside it.
      // An off-by-one in the bound would refuse a legal `cellrange(A1:C4)`.
      {
        piet::xlsx::ReadOptions ro;
        ro.firstRowIsHeader = true;
        ro.sheetName = "Beta";
        ro.firstCol = 1;
        ro.firstRow = 1;
        ro.lastCol = 3;
        ro.lastRow = 4;
        piet::xlsx::Sheet s;
        bool ok = true;
        try { s = piet::xlsx::read(book, ro); } catch (const std::exception&) { ok = false; }
        check(ok && s.header.size() == 3 && s.rows.size() == 3,
              "W3a/B4 P2: cellrange(A1:C4) — exactly the data area — still READS; the bound is "
              "`past`, not `at`, and an off-by-one here would refuse a legal range");
      }
    }
  }

  // ── ⑥ THE SEEDED-RED. A package whose ONLY declared sheet resolves, through
  //      the package-ABSOLUTE relationship Target `/xl/worksheets/sheet2.xml`,
  //      to sheet2 -- while a decoy sheet1.xml sits in the same package. The
  //      pre-W3a reader takes sheet1.xml and returns 111 at rc 0; only a reader
  //      that walks name -> r:id -> Target -> part returns 222.
  {
    // A minimal STORED .xlsx, written here rather than through xlsx::write
    // because the whole point is a relationship shape this writer never emits.
    auto crc32of = [](const std::string& data) {
      static uint32_t table[256];
      static bool built2 = false;
      if (!built2) {
        for (uint32_t i = 0; i < 256; ++i) {
          uint32_t c = i;
          for (int k = 0; k < 8; ++k) c = (c & 1) ? (0xEDB88320u ^ (c >> 1)) : (c >> 1);
          table[i] = c;
        }
        built2 = true;
      }
      uint32_t c = 0xFFFFFFFFu;
      for (unsigned char ch : data) c = table[(c ^ ch) & 0xFF] ^ (c >> 8);
      return c ^ 0xFFFFFFFFu;
    };
    auto le16 = [](std::string& b, uint16_t v) {
      b.push_back(static_cast<char>(v & 0xFF));
      b.push_back(static_cast<char>((v >> 8) & 0xFF));
    };
    auto le32 = [](std::string& b, uint32_t v) {
      for (int i = 0; i < 4; ++i) b.push_back(static_cast<char>((v >> (8 * i)) & 0xFF));
    };
    auto storedZip = [&](const std::vector<std::pair<std::string, std::string>>& entries) {
      std::string out;
      std::vector<uint32_t> offsets;
      std::vector<uint32_t> crcs;
      for (const auto& e : entries) {
        offsets.push_back(static_cast<uint32_t>(out.size()));
        const uint32_t crc = crc32of(e.second);
        crcs.push_back(crc);
        out += "PK\x03\x04";
        le16(out, 20); le16(out, 0); le16(out, 0); le16(out, 0); le16(out, 0);
        le32(out, crc);
        le32(out, static_cast<uint32_t>(e.second.size()));
        le32(out, static_cast<uint32_t>(e.second.size()));
        le16(out, static_cast<uint16_t>(e.first.size())); le16(out, 0);
        out += e.first;
        out += e.second;
      }
      const uint32_t cdOff = static_cast<uint32_t>(out.size());
      for (size_t i = 0; i < entries.size(); ++i) {
        out += "PK\x01\x02";
        le16(out, 20); le16(out, 20); le16(out, 0); le16(out, 0); le16(out, 0); le16(out, 0);
        le32(out, crcs[i]);
        le32(out, static_cast<uint32_t>(entries[i].second.size()));
        le32(out, static_cast<uint32_t>(entries[i].second.size()));
        le16(out, static_cast<uint16_t>(entries[i].first.size()));
        le16(out, 0); le16(out, 0); le16(out, 0); le16(out, 0);
        le32(out, 0);
        le32(out, offsets[i]);
        out += entries[i].first;
      }
      const uint32_t cdSize = static_cast<uint32_t>(out.size()) - cdOff;
      out += "PK\x05\x06";
      le16(out, 0); le16(out, 0);
      le16(out, static_cast<uint16_t>(entries.size()));
      le16(out, static_cast<uint16_t>(entries.size()));
      le32(out, cdSize); le32(out, cdOff); le16(out, 0);
      return out;
    };
    auto oneCellSheet = [](const char* v) {
      return std::string(
                 "<?xml version=\"1.0\" encoding=\"UTF-8\" standalone=\"yes\"?>\n"
                 "<worksheet xmlns=\"http://schemas.openxmlformats.org/spreadsheetml/2006/main\">"
                 "<sheetData><row r=\"1\"><c r=\"A1\"><v>") +
             v + "</v></c></row></sheetData></worksheet>";
    };
    const std::vector<std::pair<std::string, std::string>> parts = {
        {"[Content_Types].xml",
         "<?xml version=\"1.0\" encoding=\"UTF-8\" standalone=\"yes\"?>\n"
         "<Types xmlns=\"http://schemas.openxmlformats.org/package/2006/content-types\">"
         "<Default Extension=\"rels\" ContentType=\"application/vnd.openxmlformats-package."
         "relationships+xml\"/><Default Extension=\"xml\" ContentType=\"application/xml\"/>"
         "</Types>"},
        {"_rels/.rels",
         "<?xml version=\"1.0\" encoding=\"UTF-8\" standalone=\"yes\"?>\n"
         "<Relationships xmlns=\"http://schemas.openxmlformats.org/package/2006/relationships\">"
         "<Relationship Id=\"rId1\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/"
         "relationships/officeDocument\" Target=\"xl/workbook.xml\"/></Relationships>"},
        {"xl/workbook.xml",
         "<?xml version=\"1.0\" encoding=\"UTF-8\" standalone=\"yes\"?>\n"
         "<workbook xmlns=\"http://schemas.openxmlformats.org/spreadsheetml/2006/main\" "
         "xmlns:r=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships\">"
         "<sheets><sheet name=\"Only\" sheetId=\"7\" r:id=\"rId9\"/></sheets></workbook>"},
        {"xl/_rels/workbook.xml.rels",
         "<?xml version=\"1.0\" encoding=\"UTF-8\" standalone=\"yes\"?>\n"
         "<Relationships xmlns=\"http://schemas.openxmlformats.org/package/2006/relationships\">"
         "<Relationship Id=\"rId9\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/"
         "relationships/worksheet\" Target=\"/xl/worksheets/sheet2.xml\"/></Relationships>"},
        // The decoy. Alphabetically and conventionally first; not the sheet the
        // workbook points at.
        {"xl/worksheets/sheet1.xml", oneCellSheet("111")},
        {"xl/worksheets/sheet2.xml", oneCellSheet("222")},
    };
    const std::string relsBook = at("rels_target.xlsx");
    {
      std::ofstream f(cecon::to_native_path(relsBook), std::ios::binary | std::ios::trunc);
      const std::string bytes = storedZip(parts);
      f.write(bytes.data(), static_cast<std::streamsize>(bytes.size()));
    }
    double got = std::nan("");
    std::string byName = "<none>";
    try {
      piet::xlsx::Sheet s = piet::xlsx::read(relsBook, /*firstRowIsHeader=*/false);
      if (!s.rows.empty() && !s.rows[0].empty() && s.rows[0][0].isNumber) got = s.rows[0][0].number;
      const std::vector<piet::xlsx::SheetInfo> info = piet::xlsx::sheets(relsBook);
      if (info.size() == 1) byName = info[0].name + " -> " + info[0].part;
    } catch (const std::exception& e) {
      byName = std::string("threw: ") + e.what();
    }
    check(got == 222.0,
          "W3a ⑥ (seeded-RED): the workbook's ONLY sheet resolves through the package-absolute "
          "relationship Target `/xl/worksheets/sheet2.xml`, and a decoy sheet1.xml is present. The "
          "cell must read 222. A reader that ignores xl/_rels/workbook.xml.rels reads the decoy and "
          "answers 111 -- rc 0, plausible data, WRONG SHEET. Got " +
              (std::isnan(got) ? std::string("<none>") : std::to_string(got)));
    check(byName == "Only -> xl/worksheets/sheet2.xml",
          "W3a ⑥: and the sheet's declared NAME comes from workbook.xml, mapped to the part the "
          "rels Target names; got `" + byName + "`");
  }

  // ── ⑦ the Stata surface: describe leaves the data alone, case()/allstring
  //      reshape the load, a missing sheet is rc 601, and `import delimited`'s
  //      row/col window reproduces [D] import delimited's own example.
  {
    auto exec = [](const std::string& src, piet::SessionState& session) {
      return piet::doexec::executeDoSource(src, session, piet::dispatch);
    };
    auto varNames = [](piet::SessionState& s) {
      std::vector<std::string> out;
      const nlohmann::ordered_json blocks = piet::dispatch("describe", s);
      for (const auto& b : blocks)
        if (b.is_object() && b.value("type", std::string()) == "describe" && b.contains("variables"))
          for (const auto& v : b["variables"]) out.push_back(v.value("name", std::string()));
      return out;
    };
    auto dtypes = [](piet::SessionState& s) {
      std::vector<std::string> out;
      const nlohmann::ordered_json blocks = piet::dispatch("describe", s);
      for (const auto& b : blocks)
        if (b.is_object() && b.value("type", std::string()) == "describe" && b.contains("variables"))
          for (const auto& v : b["variables"]) out.push_back(v.value("dtype", std::string()));
      return out;
    };
    auto join = [](const std::vector<std::string>& v) {
      std::string s;
      for (const auto& n : v) { if (!s.empty()) s += " "; s += n; }
      return s.empty() ? std::string("<none>") : s;
    };
    auto firstError = [](const nlohmann::ordered_json& blocks) -> nlohmann::ordered_json {
      for (const auto& b : blocks)
        if (b.is_object() && b.value("type", std::string()) == "error") return b;
      return nlohmann::ordered_json();
    };

    piet::SessionState s(workdir);
    s.eval.cwd = workdir;
    s.cwd = workdir;  // resolveUserPath reads THIS field (handlers.cpp:2040).

    // `describe` is a QUERY: it publishes r() and must not disturb the dataset.
    auto r0 = exec("sysuse fatalities, clear\nkeep in 1/5\n", s);
    (void)r0;
    const std::vector<std::string> before = varNames(s);
    auto rd = exec("import excel using \"w3a.xlsx\", describe\n", s);
    check(firstError(rd.blocks).is_null(),
          "W3a ⑦: `import excel using \"w3a.xlsx\", describe` runs clean. Got `" +
              (firstError(rd.blocks).is_object()
                   ? firstError(rd.blocks).value("message", std::string())
                   : std::string("<none>")) + "`");
    const double* nws = s.eval.rValues.find("N_worksheet");
    check(nws != nullptr && *nws == 2.0,
          "W3a ⑦: describe stores r(N_worksheet) == 2 ([D] import excel), got " +
              (nws ? std::to_string(*nws) : std::string("<unset>")));
    check(varNames(s) == before,
          "W3a ⑦: and it does NOT touch the dataset -- `describe` is a query over the FILE. The "
          "loaded variables were {" + join(before) + "}, they are now {" + join(varNames(s)) + "}");

    auto ru = exec("import excel using \"w3a.xlsx\", sheet(\"Beta\") firstrow case(upper) clear\n",
                   s);
    check(firstError(ru.blocks).is_null() && join(varNames(s)) == "X Y Z",
          "W3a ⑦: case(upper) upper-cases the names `firstrow` read, got {" + join(varNames(s)) +
              "}");

    auto ras = exec("import excel using \"w3a.xlsx\", sheet(\"Beta\") firstrow allstring clear\n",
                    s);
    const std::vector<std::string> dt = dtypes(s);
    bool allStr = !dt.empty();
    for (const auto& d : dt) if (d.rfind("str", 0) != 0) allStr = false;
    check(firstError(ras.blocks).is_null() && allStr,
          "W3a ⑦: allstring makes EVERY column a string column, got {" + join(dt) + "}");

    // The captured rc. `sheet("NoSuchSheet")` is r(601) in Stata, with the
    // message `worksheet NoSuchSheet not found` (aer_b4 pins_oracle_g.log).
    auto rmiss =
        exec("import excel using \"w3a.xlsx\", sheet(\"NoSuchSheet\") firstrow clear\n", s);
    const nlohmann::ordered_json e = firstError(rmiss.blocks);
    check(e.is_object() && e.value("message", std::string()) == "worksheet NoSuchSheet not found" &&
              piet::eval::coarseRc(e) == "601",
          "W3a ⑦: `sheet(\"NoSuchSheet\")` answers Stata's captured r(601) and its captured "
          "sentence. Got rc " + (e.is_object() ? piet::eval::coarseRc(e) : std::string("<none>")) +
              " / `" + (e.is_object() ? e.value("message", std::string()) : std::string("<none>")) +
              "`");

    // Follows the SHAPE of the import delimited help file's rowrange/colrange
    // example, in our own invented data: rowrange(2:4) colrange(1:4) over a
    // five-column csv gives 4 vars and 3 obs, and the varnames still come from
    // physical row 1 even though the range starts at 2.
    {
      std::ofstream f(cecon::to_native_path(at("auto.csv")), std::ios::binary | std::ios::trunc);
      f << "make,price,mpg,rep78,foreign\n"
           "\"Alder Coupe\",5230,24,4,\"Local\"\n"
           "\"Birch Sedan\",6115,19,2,\"Local\"\n"
           "\"Cedar Wagon\",4870,26,,\"Import\"\n"
           "\"Dogwood Van\",7340,16,3,\"Local\"\n";
    }
    auto rdl = exec("import delimited using \"auto.csv\", rowrange(2:4) colrange(1:4) clear\n", s);
    const double* nAfter = nullptr;
    (void)piet::dispatch("count", s);
    nAfter = s.eval.rValues.find("N");
    check(firstError(rdl.blocks).is_null() && join(varNames(s)) == "make price mpg rep78" &&
              nAfter != nullptr && *nAfter == 3.0,
          "W3a ⑦: `rowrange(2:4) colrange(1:4)` (the help file's example shape, our data) -- 4 "
          "vars, 3 obs, and the names still read from physical row 1. Got {" +
              join(varNames(s)) + "} x " +
              (nAfter ? std::to_string(*nAfter) : std::string("<unset>")));

    // BUG-477: `import delimited`'s OWN case() rule. This is a DIFFERENT
    // default from import excel's (tested at "case(upper) upper-cases the
    // names `firstrow` read" above, whose default is `preserve` --
    // [D] import excel p.495): import delimited's own default LOWER-CASES
    // the header. Measured against StataBE 19.5 on a `make,price,MPG,Foreign`
    // header (tests/eval/golden/aer_b4/b5_importcase_pins.log):
    //   B5VAL|vars_default|make price mpg foreign|x|0   <- no option at all
    //   B5VAL|vars_preserve|make price MPG Foreign|x|0  <- case(preserve)
    //   B5VAL|vars_lower|make price mpg foreign|x|0
    //   B5VAL|vars_upper|MAKE PRICE MPG FOREIGN|x|0
    //   B5REC|import_delimited|case_bogus|198|
    {
      std::ofstream f(cecon::to_native_path(at("b477.csv")), std::ios::binary | std::ios::trunc);
      f << "make,price,MPG,Foreign\n"
           "\"Elm Roadster\",8420,21,\"Import\"\n"
           "\"Fir Hatchback\",3960,29,\"Local\"\n";
    }
    auto rDefault = exec("import delimited using \"b477.csv\", clear\n", s);
    check(firstError(rDefault.blocks).is_null() && join(varNames(s)) == "make price mpg foreign",
          "BUG-477: import delimited's DEFAULT (no case() at all) lower-cases the header -- "
          "Stata's own default, oracle B5VAL|vars_default|make price mpg foreign. Got {" +
              join(varNames(s)) + "}");

    auto rPreserve = exec("import delimited using \"b477.csv\", case(preserve) clear\n", s);
    check(firstError(rPreserve.blocks).is_null() && join(varNames(s)) == "make price MPG Foreign",
          "BUG-477: case(preserve) keeps the header exactly as authored, oracle "
          "B5VAL|vars_preserve|make price MPG Foreign. Got {" + join(varNames(s)) + "}");

    auto rLower = exec("import delimited using \"b477.csv\", case(lower) clear\n", s);
    check(firstError(rLower.blocks).is_null() && join(varNames(s)) == "make price mpg foreign",
          "BUG-477: case(lower) answers the same as the default, oracle "
          "B5VAL|vars_lower|make price mpg foreign. Got {" + join(varNames(s)) + "}");

    auto rUpper2 = exec("import delimited using \"b477.csv\", case(upper) clear\n", s);
    check(firstError(rUpper2.blocks).is_null() && join(varNames(s)) == "MAKE PRICE MPG FOREIGN",
          "BUG-477: case(upper) upper-cases every name, oracle "
          "B5VAL|vars_upper|MAKE PRICE MPG FOREIGN. Got {" + join(varNames(s)) + "}");

    auto rBogus = exec("import delimited using \"b477.csv\", case(bogus) clear\n", s);
    const nlohmann::ordered_json eBogus = firstError(rBogus.blocks);
    check(eBogus.is_object() && piet::eval::coarseRc(eBogus) == "198",
          "BUG-477: case(bogus) is refused, not silently ignored -- oracle "
          "B5REC|import_delimited|case_bogus|198. Got rc " +
              (eBogus.is_object() ? piet::eval::coarseRc(eBogus) : std::string("<none>")));

    // item2 (this lane's brief): `collapse ..., fast` was classified
    // unimplemented even though the handler already answers rc 0 for it --
    // measured cell for cell against StataBE 19.5 (tests/eval/golden/aer_b4/
    // b5_importcase_pins.log): B5REC|collapse|fast|0| / B5VAL|rows_collapse|2.
    {
      std::ofstream f(cecon::to_native_path(at("b2_collapse.csv")), std::ios::binary | std::ios::trunc);
      f << "price,foreign\n10,0\n20,0\n30,1\n40,1\n50,1\n";
    }
    auto rCollapse =
        exec("import delimited using \"b2_collapse.csv\", clear\ncollapse (mean) price, by(foreign) fast\n", s);
    (void)piet::dispatch("count", s);
    const double* nCollapse = s.eval.rValues.find("N");
    check(firstError(rCollapse.blocks).is_null() && nCollapse != nullptr && *nCollapse == 2.0,
          "item2: `collapse ..., fast` is rc 0 with the grouped row count intact -- oracle "
          "B5REC|collapse|fast|0 / B5VAL|rows_collapse|2. Got " +
              (nCollapse ? std::to_string(*nCollapse) : std::string("<unset>")) + " rows");

    // item3 (this lane's brief): `joinby ..., unmatched(none)` is a real Stata
    // spelling for the drop-every-unmatched-row join this build's bare
    // joinby already computes (measured, StataBE 19.5: b5_io_pins.log
    // B5REC|joinby|unmatched_none|0, rows_none == rows on that fixture without
    // unmatched() at all). `unmatched(master)`/`unmatched(both)` need the
    // engine to keep rows this build's joinby drops -- named refusals, not
    // landed here (see the session report).
    {
      std::ofstream fm(cecon::to_native_path(at("b3_jmaster.csv")), std::ios::binary | std::ios::trunc);
      fm << "jkey,mval\n1,10\n2,20\n3,30\n";
      std::ofstream fu(cecon::to_native_path(at("b3_jusing.csv")), std::ios::binary | std::ios::trunc);
      fu << "jkey,uval\n2,200\n3,300\n4,400\n";
    }
    auto rjNone = exec("import delimited using \"b3_jmaster.csv\", clear\n"
                       "joinby jkey using \"b3_jusing.csv\", unmatched(none)\n",
                       s);
    (void)piet::dispatch("count", s);
    const double* nJoinNone = s.eval.rValues.find("N");
    check(firstError(rjNone.blocks).is_null() && nJoinNone != nullptr && *nJoinNone == 2.0,
          "item3: `joinby ..., unmatched(none)` runs -- it is this build's existing bare-join "
          "behaviour under its real Stata name. Got " +
              (nJoinNone ? std::to_string(*nJoinNone) : std::string("<unset>")) + " rows, want 2");

    // unmatched(master)/unmatched(both) are served since the engine keeps the
    // unmatched rows (joinby.ado; w2aw_data_combine_family.log dc_j_master
    // N=6, dc_j_both N=7): master keeps jkey 1 (3 rows), both adds jkey 4 (4).
    auto rjMaster = exec("import delimited using \"b3_jmaster.csv\", clear\n"
                         "joinby jkey using \"b3_jusing.csv\", unmatched(master)\n",
                         s);
    (void)piet::dispatch("count", s);
    const double* nJoinMaster = s.eval.rValues.find("N");
    check(firstError(rjMaster.blocks).is_null() && nJoinMaster != nullptr && *nJoinMaster == 3.0,
          "item3: `unmatched(master)` keeps the master row without a using match. Got " +
              (nJoinMaster ? std::to_string(*nJoinMaster) : std::string("<unset>")) + " rows, want 3");

    auto rjBoth = exec("import delimited using \"b3_jmaster.csv\", clear\n"
                       "joinby jkey using \"b3_jusing.csv\", unmatched(both)\n",
                       s);
    (void)piet::dispatch("count", s);
    const double* nJoinBoth = s.eval.rValues.find("N");
    check(firstError(rjBoth.blocks).is_null() && nJoinBoth != nullptr && *nJoinBoth == 4.0,
          "item3: `unmatched(both)` keeps the unmatched rows of both sides with a `_merge` "
          "marker. Got " +
              (nJoinBoth ? std::to_string(*nJoinBoth) : std::string("<unset>")) + " rows, want 4");
  }

  fs::remove_all(workdir, ec);
}

// --- N. Registry <-> dispatcher route drift guard (BETA campaign Phase A0) -
//
// registry.cpp's commandRegistry() is a hand-transcribed DESCRIPTION of
// dispatcher.cpp's ~75 `if (cmd == "...")` arms (809-2203) — nothing
// enforces that the description stays in sync with the real if-chain as
// dispatcher.cpp evolves. This leg IS that enforcement (model:
// testVersionSingleSource() above): for every canonical/abbrev spelling in
// the table, dispatch a minimal probe and assert the result is NOT
// dispatcher.cpp:2201-2203's generic `unsupported_command`("piet_gap")
// fallthrough — i.e. the name genuinely routes to a real arm. Whatever
// happens AFTER that (missing args, an engine error, a no-data reply, ...)
// is fine and not checked here; only "this name isn't recognized as a
// command at all" is a failure.
//
// A minimal SessionState with a real dataset loaded (`sysuse fatalities`)
// is required, not optional: with NO data loaded, dispatcher.cpp:758-762's
// own "no dataset loaded" guard short-circuits almost every command NOT in
// kNoDataCommands BEFORE the routing table is ever consulted — that guard
// fires purely off a fixed allow-list + hasData(), with no knowledge of
// whether cmd matches a real arm. Without loading data first, this leg
// would PASS VACUOUSLY for ~2/3 of the registry regardless of whether the
// arm actually exists (noDataLoaded()'s code is "no_data_loaded", never
// "unsupported_command", so a no-data short-circuit and genuine drift would
// look identical to a check that only tests the empty-session case).
//
// Two rows (`scalar`, `label`) need an extra sub-token to even ENTER their
// dispatcher.cpp arm (both require a specific first varlist token — `list`/
// `dir` for scalar's display sub-arm, one of variable/values/define/list/
// dir/drop for label — bare `scalar`/`label` alone matches NO 809-2203
// condition and would otherwise fall all the way through to the exact same
// 2201-2203 fallthrough this leg exists to distinguish from real drift).
// kProbeSuffix supplies the minimal extra token for exactly these two rows;
// every other row is probed by its bare canonical/abbrev spelling alone —
// deliberately not hand-tuned per command beyond that (see the A0 task's
// return summary for the design assumption this rests on: no handler is
// expected to independently manufacture an `unsupported_command` error
// whose token happens to exactly equal the bare command word it was
// legitimately given).
void testRegistryRoutes() {
  std::printf("[selftest] --- registry <-> dispatcher route drift guard (BETA A0) ---\n");

#ifdef _WIN32
  std::error_code rwec;
  std::string workdir =
      (std::filesystem::temp_directory_path() / "piet_native_selftest_registry").u8string();
  std::filesystem::create_directories(workdir, rwec);
#else
  std::string workdir = "/tmp/piet_native_selftest_registry";
  (void)std::system(("mkdir -p '" + workdir + "'").c_str());
#endif

  static const std::map<std::string, std::string> kProbeSuffix = {
      {"scalar", "list"},
      {"label", "list"},
      // BETA campaign C4: `ereturn`'s dispatch arm only matches
      // `ereturn list` (parsed.varlist[0]=="list") — a bare `ereturn`
      // probe would otherwise legitimately fall through to the generic
      // unsupported_command fallback, same reason scalar/label are here.
      {"ereturn", "list"},
      // AER-SCOPE1 bundle B: same reason as ereturn -- the `return` arm answers
      // list/clear and reports anything else as an unknown subcommand, so a bare
      // probe would read as drift rather than as the syntax error it is.
      {"return", "list"},
      // AER-SCOPE1 bundle G: `putexcel` is STATEFUL -- every form other than
      // `set` needs an open workbook -- so a bare probe reaches the arm and
      // then errors on the missing state. `describe` is the one sub-verb that
      // is a pure query, which keeps this guard's probe free of side effects
      // (it is a route check, not a behaviour check; the behaviour lives in
      // testAerIoText leg (vii)). Drift detection is unchanged either way:
      // the guard keys on reason == "piet_gap", which no arm-reaching form
      // can produce.
      {"putexcel", "describe"},
  };

  int probed = 0;
  int drifted = 0;
  auto probeOne = [&](const std::string& name) {
    piet::SessionState session(workdir);
    // Fresh dataset re-derived from the immutable bundled CSV on EVERY
    // probe (not shared/mutated across probes): even though the on-disk
    // workdir is reused, a brand-new SessionState + a fresh `sysuse` means
    // an earlier probe's destructive command (drop/collapse/reshape/...)
    // can never leak into a later probe.
    (void)piet::dispatch("sysuse fatalities, clear", session);
    std::string probe = name;
    // BUG-105 (WS-K): key this by the CANONICAL spelling. kProbeSuffix is a
    // second copy of a spelling set, and keying it by the literal made the
    // `label` row's new abbreviations (la/lab/labe) probe as a BARE command and
    // drift-fail — exactly as bare `label` would without its `list` suffix. One
    // lookup through the resolution point instead of three more table rows.
    auto sfx = kProbeSuffix.find(piet::registry::resolveCanonical(name));
    if (sfx != kProbeSuffix.end()) probe += " " + sfx->second;
    auto blocks = piet::dispatch(probe, session);
    bool driftedToUnknown = false;
    for (const auto& b : blocks) {
      // AER scope-1 (2026-09-03): `reason` is what separates DRIFT from a
      // deliberate refusal. Both emit `unsupported_command` with the command
      // word as `token`; only drift — the generic dispatcher fallthrough at
      // dispatcher.cpp's tail — carries the `piet_gap` reason. A row that is
      // registered and refuses with a named cause (`refused:<cause>`, via
      // eval::refusedCommand) is reaching its arm exactly as intended, which
      // is the opposite of what this guard exists to catch. Without this
      // clause the campaign's ~30 register-and-refuse rows would each read as
      // a drifted route and the guard would have to be switched off.
      if (b.is_object() && b.value("type", std::string()) == "error" &&
          b.value("code", std::string()) == "unsupported_command" &&
          b.value("token", std::string()) == name &&
          b.value("reason", std::string()) == "piet_gap") {
        driftedToUnknown = true;
        break;
      }
    }
    ++probed;
    if (driftedToUnknown) ++drifted;
    check(!driftedToUnknown, "registry route `" + name + "` reaches a real dispatcher arm");
  };

  for (const auto& spec : piet::registry::commandRegistry()) {
    probeOne(spec.canonical);
    for (const auto& ab : spec.abbrev) probeOne(ab);
  }

  std::printf("[selftest]      probed %d registry canonical/abbrev spellings (%d drifted)\n", probed,
              drifted);

#ifdef _WIN32
  std::error_code rrec;
  std::filesystem::remove_all(workdir, rrec);
#else
  (void)std::system(("rm -rf '" + workdir + "'").c_str());
#endif
}


// Small formatter so a ratchet failure NAMES the rows instead of just counting
// them — a bare count sends the reader back to the dump to find out which.
static std::string joinForMsg(const std::vector<std::string>& xs) {
  std::string out;
  for (size_t i = 0; i < xs.size(); ++i) {
    if (i != 0) out += ", ";
    if (i == 8) { out += "... (" + std::to_string(xs.size() - 8) + " more)"; break; }
    out += xs[i];
  }
  return out;
}



// ── AER scope 2, bundle K1: tolower / move / renvars, plus the varlist glob ──
//
// Every expected value below is a MEASUREMENT against StataNow 19.5 BE with
// tolower.ado (Nick Cox) and renvars.ado (dm88_1, Cox/Weesie) installed, taken
// on 2026-09-07 BEFORE any of this was written. That order is the point: the
// plan for this bundle said `move` was `order v1, before(v2)` and that `renvars`
// could be an alias for `renvarlab`, and the captures falsified both.
//
// THREE LEGS ARE DISCRIMINATORS -- they are the checks a plausible wrong
// implementation fails, and they are why this function is not just a smoke test:
//
//   (a) `move a c` on `a b c` is `b c a`, not `b a c`. A before()-always
//       implementation gets the first direction right and this one wrong, and
//       nothing about the wrong answer looks wrong.
//   (b) bare `tolower` on `AA bb CC` answers rc 110 AND LEAVES `aa bb CC`.
//       tolower is a while-loop around `rename`, so it renames until one fails.
//       An implementation that validated the list first (which is what the
//       sibling `renvars` correctly does, and what reads as more careful) leaves
//       `AA bb CC` untouched -- a different answer at the same rc.
//   (c) `renvars share_sigvar*, postsub("_" "")` is a NO-OP at rc 0, because
//       postsub substitutes at the END only. That exact line is in the corpus.
//       An implementation that read postsub as "substitute everywhere" renames
//       the columns to `sharesigvara` and answers rc 0 -- a silent wrong answer
//       with no diagnostic on any surface.
void testAerK1() {
  std::printf("[selftest] --- AER scope-2 bundle K1: tolower / move / renvars + varlist glob ---\n");
  namespace fs = std::filesystem;
  std::string workdir = (fs::temp_directory_path() / "piet_native_selftest_aerk1").u8string();
  std::error_code ec;
  fs::remove_all(workdir, ec);
  fs::create_directories(workdir, ec);

  // Runs a do-source in a FRESH session and reports the trailing `ds` line plus
  // the rc of the last `capture`d statement. Every leg is independent: these
  // commands mutate the variable plane, and a shared session would make leg N+1
  // depend on leg N's failure mode.
  auto run = [&](const std::string& src) {
    piet::SessionState s(workdir);
    s.eval.cwd = workdir;
    s.cwd = workdir;
    return piet::doexec::executeDoSource(src, s, piet::dispatch);
  };
  // The LAST display block, which every fixture below makes a `ds`.
  auto lastDisplay = [](const nlohmann::ordered_json& blocks) {
    std::string out;
    for (const auto& b : blocks) {
      if (b.is_object() && b.value("type", std::string()) == "display")
        out = b.value("text", std::string());
    }
    return out;
  };
  auto namesAfter = [&](const std::string& body) {
    return lastDisplay(run(body + "\nds\n").blocks);
  };
  // rc via a local, because `_rc` is not resolvable inside a gen expression.
  auto rcOfSrc = [&](const std::string& body) {
    return lastDisplay(run(body + "\nlocal rc = _rc\ndisplay \"`rc'\"\n").blocks);
  };

  const std::string kThree = "clear\nset obs 2\ngen a = 1\ngen b = 2\ngen c = 3\n";

  // ---- tolower -----------------------------------------------------------
  check(namesAfter("clear\nset obs 2\ngen AAA = 1\ngen BbB = 2\ngen ccc = 3\ntolower AAA BbB") ==
            "aaa bbb ccc",
        "K1 tolower: named variables are lowercased and the one NOT named is left alone "
        "(Stata: aaa bbb ccc)");
  {
    auto r = run("clear\nset obs 2\ngen AAA = 1\nlabel variable AAA \"Label for AAA\"\n"
                 "label define lb2 1 \"one\"\nlabel values AAA lb2\ntolower AAA\n"
                 "local L : variable label aaa\ndisplay \"`L'\"\n");
    check(lastDisplay(r.blocks) == "Label for AAA",
          "K1 tolower: the VARIABLE LABEL survives, because this routes through runRename and "
          "rename does not touch the label plane (measured)");
  }
  {
    auto r = run("clear\nset obs 2\ngen AAA = 1\nlabel define lb2 1 \"one\"\n"
                 "label values AAA lb2\ntolower AAA\n"
                 "local V : value label aaa\ndisplay \"`V'\"\n");
    check(lastDisplay(r.blocks) == "lb2",
          "K1 tolower: the VALUE LABEL survives too (measured `lb2`)");
  }
  check(namesAfter("clear\nset obs 2\ngen QQ = 1\ngen Rr = 2\ntolower") == "qq rr",
        "K1 tolower: bare `tolower` is _all");
  // (b) the non-atomic discriminator.
  check(rcOfSrc("clear\nset obs 2\ngen AA = 1\ngen bb = 2\ngen CC = 3\ncapture tolower") == "110",
        "K1 tolower: bare `tolower` over `AA bb CC` STOPS at r(110) -- `rename bb bb` is a "
        "collision, not a skip");
  check(namesAfter("clear\nset obs 2\ngen AA = 1\ngen bb = 2\ngen CC = 3\ncapture tolower") ==
            "aa bb CC",
        "K1 tolower: ...and it leaves `aa bb CC` behind -- the first rename LANDED and the third "
        "was never reached. A validate-first implementation leaves `AA bb CC`, which is a "
        "different answer at the same rc");
  check(rcOfSrc("clear\nset obs 2\ngen abc = 1\ncapture tolower abc") == "110",
        "K1 tolower: a name that is ALREADY lowercase is r(110), not a no-op (Stata issues the "
        "self-rename and gets the collision)");
  check(namesAfter("clear\nset obs 2\ngen AL1 = 1\ngen MID = 2\ngen KONEV_L = 3\ngen ZZ = 4\n"
                   "tolower AL1- KONEV_L") == "al1 mid konev_l ZZ",
        "K1 tolower: the corpus's range form, hyphen followed by a SPACE (`tolower AL1- KONEV_L`)");

  // ---- move --------------------------------------------------------------
  check(namesAfter(kThree + "move c a") == "c a b",
        "K1 move: `move c a` puts c in a's position -> c a b");
  // (a) the direction discriminator.
  check(namesAfter(kThree + "move a c") == "b c a",
        "K1 move: `move a c` is `b c a`, NOT `b a c`. This is the leg that fails if move is "
        "implemented as `order v1, before(v2)` in both directions");
  check(namesAfter(kThree + "move a a") == "a b c",
        "K1 move: moving a variable onto itself is rc 0 and changes nothing");
  check(rcOfSrc(kThree + "capture move zz a") == "111",
        "K1 move: an absent source is r(111) `variable zz not found`");
  check(rcOfSrc(kThree + "capture move a b c") == "103",
        "K1 move: three names is r(103) `too many variables specified`");
  check(rcOfSrc(kThree + "capture move a") == "102",
        "K1 move: one name is r(102) `too few variables specified`");

  // ---- renvars -----------------------------------------------------------
  check(namesAfter("clear\nset obs 2\ngen date = 1\ngen mschool = 2\ngen zz = 3\n"
                   "renvars date-mschool, prefix(bl_)") == "bl_date bl_mschool zz",
        "K1 renvars: prefix() over a hyphen range (a real corpus line)");
  check(namesAfter("clear\nset obs 2\ngen state = 1\ngen county = 2\n"
                   "renvars state county, postfix(\"10\")") == "state10 county10",
        "K1 renvars: postfix() with a QUOTED argument -- the quotes come off, or the target name "
        "is `state\"10\"` and illegal");
  check(namesAfter("clear\nset obs 2\ngen s_kfr = 1\ngen s_kir = 2\n"
                   "renvars s_kfr s_kir, suff(_)") == "s_kfr_ s_kir_",
        "K1 renvars: `suff()` is renvars' own synonym for postfix(), and the corpus spells it "
        "that way");
  check(namesAfter("clear\nset obs 2\ngen state10 = 1\ngen county10 = 2\n"
                   "renvars state10 county10, postsub(10)") == "state county",
        "K1 renvars: one-argument postsub() DROPS the trailing text (replacement is empty)");
  // (c) the silent-wrong-answer discriminator.
  check(namesAfter("clear\nset obs 2\ngen share_sigvar_a = 1\ngen share_sigvar_b = 2\n"
                   "renvars share_sigvar*, postsub(\"_\" \"\")") ==
            "share_sigvar_a share_sigvar_b",
        "K1 renvars: postsub() matches at the END ONLY, so this real corpus line is a NO-OP at "
        "rc 0. Reading postsub as substitute-everywhere renames them to `sharesigvara` and says "
        "nothing");
  check(namesAfter("clear\nset obs 2\ngen n_state = 1\ngen n_county = 2\ngen keepme = 3\n"
                   "renvars n_state n_county, presub(n_)") == "state county keepme",
        "K1 renvars: presub() matches at the START only");
  check(namesAfter("clear\nset obs 2\ngen a_cen_2010 = 1\ngen b_cen_2010 = 2\n"
                   "renvars *2010, subst(\"_cen_\" \"\")") == "a2010 b2010",
        "K1 renvars: subst() replaces ANYWHERE -- and the varlist is a LEADING wildcard, which "
        "the expander could not do before this bundle");
  check(namesAfter("clear\nset obs 2\ngen j6qe_a = 1\ngen j6qe_b = 2\nrenvars j6qe*, upper") ==
            "J6QE_A J6QE_B",
        "K1 renvars: upper");
  check(namesAfter("clear\nset obs 2\ngen v2 = 1\ngen v3 = 2\ngen v4 = 3\n"
                   "renvars v2-v4 \\ id age income") == "id age income",
        "K1 renvars: the backslash one-to-one MAP form, which renvarlab has no syntax for at all "
        "-- this is why the alias the plan proposed could not have worked");
  check(rcOfSrc("clear\nset obs 2\ngen v2 = 1\ngen v3 = 2\ncapture renvars v2-v3 \\ onlyone") ==
            "198",
        "K1 renvars: a map form whose two lists differ in length is r(198)");
  check(rcOfSrc("clear\nset obs 2\ngen aa = 1\ncapture renvars aa, prefix(x_) upper") == "198",
        "K1 renvars: TWO transformation options is r(198) -- the ado counts them and demands "
        "exactly one");
  check(rcOfSrc("clear\nset obs 2\ngen a = 1\ngen bl_a = 2\ncapture renvars a, prefix(bl_)") ==
            "110",
        "K1 renvars: a collision is r(110)");
  check(namesAfter("clear\nset obs 2\ngen a = 1\ngen bl_a = 2\ncapture renvars a, prefix(bl_)") ==
            "a bl_a",
        "K1 renvars: ...and NOTHING was renamed -- renvars runs `confirm new var` over the whole "
        "plan first, so it is atomic where tolower above is not");
  check(namesAfter("clear\nset obs 2\ngen AA = 1\nrenvars AA, lower test") == "AA",
        "K1 renvars: `test` prints the plan and renames nothing");
  check(namesAfter("clear\nset obs 2\ngen AA = 1\ngen BB = 2\nrenvars, lower") == "aa bb",
        "K1 renvars: no varlist at all is _all");
  {
    auto r = run("clear\nset obs 2\ngen AAA = 1\nlabel variable AAA \"Label for AAA\"\n"
                 "renvars AAA, lower\nlocal L : variable label aaa\ndisplay \"`L'\"\n");
    check(lastDisplay(r.blocks) == "Label for AAA",
          "K1 renvars: the variable label survives here too");
  }

  // ---- the varlist glob, which K1b widened from prefix-only --------------
  // Measured with `unab` on auto.dta: t* -> trunk turn, *e -> make price,
  // tr*k -> trunk, ?rice -> price, zz* -> r(111).
  {
    const std::string fixture =
        "clear\nset obs 2\ngen price = 1\ngen mpg = 2\ngen trunk = 3\ngen turn = 4\n";
    auto seen = [&](const std::string& pat) {
      auto r = run(fixture + "local s = \"\"\nforeach v of varlist " + pat +
                   " {\nlocal s = \"`s' `v'\"\n}\ndisplay \"`s'\"\n");
      std::string t = lastDisplay(r.blocks);
      while (!t.empty() && t.front() == ' ') t.erase(t.begin());
      return t;
    };
    check(seen("t*") == "trunk turn", "K1 glob: a TRAILING wildcard (the only shape that worked "
                                      "before this bundle)");
    check(seen("*e") == "price", "K1 glob: a LEADING wildcard (only price ends in e in this fixture)");
    check(seen("tr*k") == "trunk", "K1 glob: a wildcard in the MIDDLE");
    check(seen("?rice") == "price", "K1 glob: `?` matches exactly ONE character");
    check(rcOfSrc(fixture + "capture unab z : zz*") == "111",
          "K1 glob: a pattern matching nothing is r(111), which is what Stata answers -- not this "
          "expander's old private message at rc 1");
  }
}




// ── AER scope 2, bundle K1c: `parallel`, answered sequentially ──────────────
//
// The package CANNOT BE RUN on this machine -- `parallel setclusters 2` answers
// r(601) even with an explicit statapath(), so $PLL_STATA_PATH never gets set
// and no child process can start. Every rule asserted below therefore comes
// from parallel.ado's OWN SOURCE rather than from a live capture, and the two
// forms whose answer depends on how the data is split are REFUSED rather than
// approximated, because there is no oracle to check a reproduction against.
//
// What the source says, and what these legs pin:
//   · `parallel do` requires $PLL_CLUSTERS and exits 198 without it.
//   · with `nodata` the children get no data and nothing is pasted back, so
//     the parent's dataset must be UNTOUCHED afterwards. That is the leg that
//     fails if the sequential run is allowed to leak into the parent.
//   · without `nodata` the rows are SPLIT across clusters and the results are
//     pasted back, so with more than one cluster the answer depends on the
//     split -- refused, named.
//   · `initialize` is not a subcommand of the installed 1.15.8 (measured
//     r(198)) but IS what the corpus writes. It is accepted as a spelling of
//     `setclusters`: the ACCEPTED-NAMED exception for a third-party ado whose
//     own versions disagree. This leg is the record of that decision, so
//     reversing it is a visible change and not a quiet one.
void testAerK1cParallel() {
  std::printf("[selftest] --- AER scope-2 K1c: parallel (sequential) ---\n");
  namespace fs = std::filesystem;
  std::string workdir = (fs::temp_directory_path() / "piet_native_selftest_pll").u8string();
  std::error_code ec;
  fs::remove_all(workdir, ec);
  fs::create_directories(workdir, ec);
  const std::string child = workdir + "/pll_child.do";
  {
    std::ofstream f(child);
    f << "clear\nset obs 4\ngen fromchild = 99\n";
  }

  auto run = [&](const std::string& src) {
    piet::SessionState s(workdir);
    s.eval.cwd = workdir;
    s.cwd = workdir;
    return piet::doexec::executeDoSource(src, s, piet::dispatch);
  };
  auto lastDisplay = [](const nlohmann::ordered_json& blocks) {
    std::string out;
    for (const auto& b : blocks) {
      if (b.is_object() && b.value("type", std::string()) == "display")
        out = b.value("text", std::string());
    }
    return out;
  };
  auto rcOfSrc = [&](const std::string& body) {
    return lastDisplay(run(body + "\nlocal rc = _rc\ndisplay \"`rc'\"\n").blocks);
  };
  const std::string kData = "clear\nset obs 5\ngen parentvar = _n\n";

  check(rcOfSrc(kData + "capture parallel do \"" + child + "\", nodata processors(1)") == "198",
        "K1c parallel: `do` with no cluster count set is r(198) -- parallel.ado's own first check");
  check(lastDisplay(run(kData + "parallel initialize 4\ndisplay \"${PLL_CLUSTERS}\"\n").blocks) ==
            "4",
        "K1c parallel: `initialize` records the cluster count in $PLL_CLUSTERS, which is the "
        "global the package itself uses. It is NOT a subcommand of the installed 1.15.8 (r(198), "
        "measured) and is accepted anyway, because it is what the corpus writes");
  check(lastDisplay(run(kData + "parallel setclusters 2\ndisplay \"${PLL_CLUSTERS}\"\n").blocks) ==
            "2",
        "K1c parallel: `setclusters` is the same arm under the spelling this version documents");
  check(rcOfSrc(kData + "parallel initialize 1\ncapture parallel do \"" + child +
                "\", nodata processors(1)") == "0",
        "K1c parallel: `do ... , nodata` RUNS the file");
  check(lastDisplay(run(kData + "parallel initialize 1\nparallel do \"" + child +
                        "\", nodata processors(1)\nds\n")
                        .blocks) == "parentvar",
        "K1c parallel: ...and the parent's dataset is UNTOUCHED. With `nodata` the children get "
        "no data and nothing is pasted back, so a sequential run that leaked into the parent "
        "would be a different dataset at rc 0 -- this is the leg that catches it");
  check(rcOfSrc(kData + "parallel initialize 4\ncapture parallel do \"" + child + "\"") == "199",
        "K1c parallel: WITHOUT `nodata` the package splits the rows across clusters and pastes "
        "the results back, so the answer depends on the split. Refused, named -- the package "
        "cannot be run here to check a reproduction against");
  check(rcOfSrc(kData + "parallel initialize 1\ncapture parallel do \"" + child +
                "\", nodata seeds(random)") == "198",
        "K1c parallel: an option that changes what a cluster RECEIVES is refused rather than "
        "accepted-and-ignored");
  check(rcOfSrc(kData + "capture parallel bogus") == "198",
        "K1c parallel: an unknown subcommand is r(198) with parallel.ado's own wording");
  check(rcOfSrc(kData + "capture parallel clean") == "0",
        "K1c parallel: `clean` is rc 0 -- measured in Stata, where it is rc 0 even with no "
        "cluster ever started");
  check(rcOfSrc(kData + "capture parallel append , do(ds) e(\"x_%g.dta, 1/3\")") == "199",
        "K1c parallel: `append` goes through the cluster machinery this build cannot start, so "
        "the whole verb is refused rather than half-done");
}

// ── BUG-450: the varlist expansion point ────────────────────────────────────
//
// `expandVarlist` calls itself "the ONE varlist wildcard/range expander" and,
// until 2026-09-08, its callers were the loop header, `ds`/`unab` and a handful
// of AER handlers written against it directly. The plain data verbs were not
// among them, so `drop t*` answered r(111) while `foreach v of varlist t*`
// expanded correctly in the same session on the same data.
//
// Every expected value below is a MEASUREMENT against StataNow 19.5 BE over
// auto.dta, taken before the wiring was written.
//
// THE TWO LEGS THAT ARE GUARDS RATHER THAN FEATURES, and they are the reason
// this is a flag and not a blanket change:
//   * `rename t* T*` must NOT be expanded. It is Stata's rename-GROUPS syntax
//     -- measured, it renames trunk->Trunk and turn->Turn -- so the `*` on each
//     side stands for the same captured text. Expanding the left side and
//     leaving the right literal would rename both columns to `T*`. `rename` is
//     therefore absent from the opt-in list and reaches its own arm unexpanded,
//     where it answers honestly (BUG-453).
//   * A varlist with NO pattern character must pass through byte-identically,
//     so the common case cannot regress behind the new code path.
void testVarlistExpansionWiring() {
  std::printf("[selftest] --- BUG-450: varlist wildcard/range wiring on the data verbs ---\n");
  namespace fs = std::filesystem;
  std::string workdir = (fs::temp_directory_path() / "piet_native_selftest_varlist").u8string();
  std::error_code ec;
  fs::remove_all(workdir, ec);
  fs::create_directories(workdir, ec);

  // A fixture whose names mirror auto.dta's, so the measured shapes read the
  // same way. Built in-body: this leg is about NAME resolution, not values.
  const std::string kFix =
      "clear\nset obs 3\ngen make = 1\ngen price = 2\ngen mpg = 3\ngen rep78 = 4\n"
      "gen headroom = 5\ngen trunk = 6\ngen weight = 7\ngen length = 8\ngen turn = 9\n";

  auto run = [&](const std::string& src) {
    piet::SessionState s(workdir);
    s.eval.cwd = workdir;
    s.cwd = workdir;
    return piet::doexec::executeDoSource(src, s, piet::dispatch);
  };
  auto lastDisplay = [](const nlohmann::ordered_json& blocks) {
    std::string out;
    for (const auto& b : blocks) {
      if (b.is_object() && b.value("type", std::string()) == "display")
        out = b.value("text", std::string());
    }
    return out;
  };
  auto namesAfter = [&](const std::string& body) {
    return lastDisplay(run(kFix + body + "\nds\n").blocks);
  };
  auto rcOfSrc = [&](const std::string& body) {
    return lastDisplay(run(kFix + body + "\nlocal rc = _rc\ndisplay \"`rc'\"\n").blocks);
  };

  check(namesAfter("drop t*") == "make price mpg rep78 headroom weight length",
        "BUG-450 drop: a trailing wildcard drops trunk and turn");
  check(namesAfter("drop price-trunk") == "make weight length turn",
        "BUG-450 drop: a hyphen RANGE drops the five names between the endpoints, inclusive");
  check(namesAfter("keep t*") == "trunk turn",
        "BUG-450 keep: the same expansion on the other verb");
  check(namesAfter("keep price-trunk") == "price mpg rep78 headroom trunk",
        "BUG-450 keep: ...and the same range");
  check(namesAfter("order t*") == "trunk turn make price mpg rep78 headroom weight length",
        "BUG-450 order: the matched names move to the front IN CORPUS ORDER, not pattern order");
  check(lastDisplay(run(kFix + "quietly summarize t*\ndisplay r(N)\n").blocks) == "3",
        "BUG-450 summarize: a read-only verb takes the pattern too");
  check(lastDisplay(run(kFix + "quietly summarize t?rn\ndisplay r(N)\n").blocks) == "3",
        "BUG-450: `?` matches exactly one character here as well as in `unab`");
  check(lastDisplay(run(kFix + "quietly summarize _all\ndisplay r(N)\n").blocks) == "3",
        "BUG-450: `_all` is a varlist keyword on these rows too");
  check(rcOfSrc("capture summarize zz*") == "111",
        "BUG-450: a pattern matching nothing is r(111), which is what Stata answers");
  check(rcOfSrc("capture drop zz*") == "111", "BUG-450: ...on the writing verbs too");

  // ---- the two guards ---------------------------------------------------
  // The rename arm now serves the group form itself (2026-10-21), so the
  // measured Stata result is the expectation: trunk->Trunk, turn->Turn (the
  // measurement this leg's header records), with the `*`s paired, never the
  // left side expanded on its own.
  check(namesAfter("capture rename t* T*") ==
            "make price mpg rep78 headroom Trunk weight length Turn",
        "BUG-450 GUARD: `rename t* T*` is rename-GROUPS, where the two `*`s are a PAIRING -- "
        "trunk->Trunk and turn->Turn as measured, never both columns onto one literal name");
  check(namesAfter("drop trunk turn") == "make price mpg rep78 headroom weight length",
        "BUG-450 GUARD: a varlist with no pattern character takes the unchanged path -- the common "
        "case cannot regress behind the new one");
}

// ── AER scope 2, bundle B2: strdist ─────────────────────────────────────────
//
// Every expected value is a MEASUREMENT against StataNow 19.5 BE with
// strdist 1.2 installed, captured before the handler was written and committed
// as tests/validate/b2_oracle.{do,json}. `strdist` is the last name that blocked
// paper 100 at the name level.
//
// THE LEGS THAT ARE DISCRIMINATORS RATHER THAN SMOKE:
//   * "a" vs "A" is 1, not 0. The package's Mata kernel compares `ascii()`
//     bytes, so the distance is BYTE-wise; a codepoint- or case-folded
//     implementation answers 0 and looks more helpful while disagreeing.
//   * maxdist() does not clamp, it BLANKS: over the limit is missing, not the
//     limit. `strdist p q, maxdist(2)` on kitten/sitting gives an all-missing
//     column (r(N) == 0), not a column of 2s.
//   * `strdist p` with ONE argument is legal and is not `strdist p p`. It is
//     the distance from the EMPTY string, i.e. the length: 6 for "kitten".
//   * With no gen(), the new variable is called `strdist` -- the literal word.
//     Measured with `ds`, not assumed from the help file.
void testAerB2Strdist() {
  std::printf("[selftest] --- AER scope-2 bundle B2: strdist ---\n");
  namespace fs = std::filesystem;
  std::string workdir = (fs::temp_directory_path() / "piet_native_selftest_aerb2").u8string();
  std::error_code ec;
  fs::remove_all(workdir, ec);
  fs::create_directories(workdir, ec);

  auto run = [&](const std::string& src) {
    piet::SessionState s(workdir);
    s.eval.cwd = workdir;
    s.cwd = workdir;
    return piet::doexec::executeDoSource(src, s, piet::dispatch);
  };
  auto lastDisplay = [](const nlohmann::ordered_json& blocks) {
    std::string out;
    for (const auto& b : blocks) {
      if (b.is_object() && b.value("type", std::string()) == "display")
        out = b.value("text", std::string());
    }
    return out;
  };
  // One pair, through summarize: `d[1]` inside a display reads as a MATRIX
  // reference in this build, which is a separate gap and not this bundle's.
  auto dist = [&](const std::string& a, const std::string& b, const std::string& opts) {
    return lastDisplay(run("clear\nset obs 1\ngen str32 sa = \"" + a +
                           "\"\ngen str32 sb = \"" + b + "\"\nstrdist sa sb, gen(dd)" + opts +
                           "\nquietly summarize dd\ndisplay r(mean)\n")
                           .blocks);
  };
  auto rcOfSrc = [&](const std::string& body) {
    return lastDisplay(run(body + "\nlocal rc = _rc\ndisplay \"`rc'\"\n").blocks);
  };

  check(dist("kitten", "sitting", "") == "3", "B2 strdist: kitten -> sitting is 3");
  check(dist("sitting", "kitten", "") == "3", "B2 strdist: ...and the metric is symmetric");
  check(dist("flaw", "lawn", "") == "2", "B2 strdist: flaw -> lawn is 2");
  check(dist("abcdef", "abcdef", "") == "0", "B2 strdist: identical strings are 0");
  check(dist("", "abc", "") == "3", "B2 strdist: an empty side is the other's length");
  check(dist("abc", "", "") == "3", "B2 strdist: ...from either side");
  check(dist("", "", "") == "0", "B2 strdist: two empties are 0");
  check(dist("a", "A", "") == "1",
        "B2 strdist: `a` vs `A` is 1. BYTE-wise, because the package compares ascii() codes -- a "
        "case-folded implementation answers 0 and is wrong in the helpful direction");
  check(dist("ab cd", "abcd", "") == "1", "B2 strdist: a space is an ordinary character");

  // maxdist blanks rather than clamps.
  check(lastDisplay(run("clear\nset obs 1\ngen str9 p = \"kitten\"\ngen str9 q = \"sitting\"\n"
                        "strdist p q, gen(m1) maxdist(2)\nquietly summarize m1\ndisplay r(N)\n")
                        .blocks) == "0",
        "B2 strdist: maxdist(2) over a distance of 3 leaves MISSING (r(N)==0), it does not clamp "
        "to 2");
  check(dist("kitten", "sitting", " maxdist(3)") == "3",
        "B2 strdist: maxdist(3) admits a distance of exactly 3");
  check(dist("kitten", "sitting", " maxdist(0)") == "3",
        "B2 strdist: maxdist(0) means NO limit (the ado normalises anything below 1)");

  // The single-argument form, the default name, and the two-literal form.
  check(lastDisplay(run("clear\nset obs 1\ngen str9 p = \"kitten\"\nstrdist p\n"
                        "quietly summarize strdist\ndisplay r(mean)\n")
                        .blocks) == "6",
        "B2 strdist: ONE argument is the distance from the empty string, i.e. the length (6). It "
        "is not `strdist p p`, which would be 0");
  check(lastDisplay(run("clear\nset obs 1\ngen str9 p = \"kitten\"\ngen str9 q = \"sitting\"\n"
                        "strdist p q\nds\n")
                        .blocks) == "p q strdist",
        "B2 strdist: with no gen() the new variable is called `strdist` -- the literal word");
  check(lastDisplay(run("clear\nset obs 1\ngen x = 1\nstrdist \"abc\" x\n"
                        "quietly summarize strdist\ndisplay r(mean)\n")
                        .blocks) != "",
        "B2 strdist: a LITERAL paired with a variable is the per-row distance to that literal");
  check(lastDisplay(run("clear\nset obs 1\ngen str9 p = \"kitten\"\nstrdist \"abc\" p\n"
                        "quietly summarize strdist\ndisplay r(mean)\n")
                        .blocks) == "6",
        "B2 strdist: ...abc -> kitten is 6");
  {
    auto r = run("clear\nset obs 1\ngen x = 1\nstrdist \"kitten\" \"sitting\"\ndisplay r(d)\n");
    check(lastDisplay(r.blocks) == "3",
          "B2 strdist: TWO literals set r(d) and create nothing");
  }

  // The refusals, each with the rc Stata answers.
  check(rcOfSrc("clear\nset obs 1\ngen str9 p = \"a\"\ngen str9 q = \"b\"\n"
                "capture strdist p q p") == "103",
        "B2 strdist: three arguments is r(103)");
  check(rcOfSrc("clear\nset obs 1\ngen str9 p = \"a\"\ncapture strdist p nosuchvar, gen(z)") ==
            "111",
        "B2 strdist: an absent variable is r(111)");
  check(rcOfSrc("clear\nset obs 1\ngen str9 p = \"a\"\ngen str9 q = \"b\"\n"
                "capture strdist p q, gen(p)") == "110",
        "B2 strdist: a target that already exists is r(110) -- `confirm new variable`, not this "
        "build's generic bad_input at rc 1");
}

// ── AER scope-1 (2026-09-03): the two campaign ratchets ──────────────────────
//
// The AER scope-1 campaign wires ~145 new commands through one 14-step
// checklist. Two of those steps had no gate of their own, so they are the two
// that silently got skipped before: commit 5a49d52d added xtile/ipolate/tssmooth
// with no floors.json classification and no effect-table row, and the floor debt
// only surfaced a month later as a structural RED nobody had touched. A hundred
// more rows would have multiplied that silence. These two checks make the
// omission fail at the moment it lands, which is the only moment it is cheap.
//
//   (1) EFFECT-TABLE COVERAGE. Every registry row is either classified in
//       parallel_effects.cpp's table or named on the frozen pre-campaign
//       exemption list. Absence is SAFE at runtime — parallel_effects.h's
//       axiom makes an unclassified head refuse the whole auto-parallel region
//       rather than guess — but it is a silent loss of auto eligibility, and
//       silence is exactly what a campaign of this size cannot afford.
//       The exemption list is FROZEN at the 70 rows that were unclassified on
//       2026-09-03. It may SHRINK, never grow: a new command classifies, or it
//       is not finished.
//
//   (2) NO-DATA ROUTES. A command that must run with no dataset loaded
//       actually does. This is the BUG-343 defect class: a correct registry
//       row and a correct dispatcher arm still answered `No dataset is
//       loaded.` because dispatcher.cpp's kNoDataCommands set never learned
//       the name — the failure is invisible to the route drift guard above,
//       which loads a dataset before every probe. Probed behaviourally (the
//       set itself is a static local), so the test needs no new export.
// AER scope-2 bundle B2 -- oaxaca. Every numeric pin is a StataBE 19.5 +
// oaxaca 4.1.1 %21x value from tests/validate/b2_oracle.json, captured on the
// in-body fixture below BEFORE the kernel was written. The five SE formulas
// the first pass guessed were all wrong by >= 5.5e-4 on group_1; the pins
// here are at 1e-9, which none of the five could pass.
// AER scope-2 bundle B2-3: `bcal create` + bofd()/dofb() (paper 066).
//
// THE PIN IS THE FILE'S BYTES. Every kXxx literal below is a `.stbcal` file
// StataBE 19.5 wrote, `type`d verbatim into internal capture
// capture*.log / refute0.log between begin/end TYPE markers -- not a file re-read
// from that directory (which holds each calendar only as LAST written), and
// not a shape this build produced and was then blessed with.
//
// Two legs are the ones the receipt's first, INFERRED rule got wrong ("emit an
// `omit date` for every calendar day in the range that is not one of the
// values"): k_nonint and z_ni, both with non-integer from() values. They come
// out right only under Stata's consecutive-difference rule. z_ni has an
// 11.5-day RAW gap and still passes maxgap(10), emitting no omit-date line at
// all -- REFUTE-0 T5's discriminating shape, and the reason this file is here.
void testAerB2Bcal() {
  std::printf("[selftest] --- AER scope-2 bundle B2-3: bcal / bofd / dofb ---\n");
  namespace fs = std::filesystem;
  const std::string workdir =
      (fs::temp_directory_path() / "piet_native_selftest_aerb2bcal").u8string();
  std::error_code ec;
  fs::remove_all(workdir, ec);
  fs::create_directories(workdir, ec);

  static const char* kAWk =
      "* Business calendar \"a_wk\" created by -bcal create-\n"
      "* Created/replaced on  8 Sep 2026\n"
      "\n"
      "version 19.5\n"
      "dateformat ymd\n"
      "\n"
      "range 2020jan01 2020feb09\n"
      "centerdate 2020jan01\n"
      "\n"
      "omit dayofweek (Mo Tu)\n";

  static const char* kBHol =
      "* Business calendar \"b_hol\" created by -bcal create-\n"
      "* Created/replaced on  8 Sep 2026\n"
      "\n"
      "version 19.5\n"
      "dateformat ymd\n"
      "\n"
      "range 2020jan01 2020feb28\n"
      "centerdate 2020jan01\n"
      "\n"
      "omit dayofweek (Sa Su)\n"
      "omit date 2020jan03\n"
      "omit date 2020jan20\n"
      "omit date 2020feb12\n"
      "omit date 2020feb13\n"
      "omit date 2020feb17\n";

  static const char* kBDaily =
      "* Business calendar \"b_daily\" created by -bcal create-\n"
      "* Created/replaced on  8 Sep 2026\n"
      "\n"
      "version 19.5\n"
      "dateformat ymd\n"
      "\n"
      "range 2020jan01 2020jan31\n"
      "centerdate 2020jan01\n"
      "\n"
      "omit date 2020jan05\n"
      "omit date 2020jan15\n"
      "omit date 2020jan16\n";

  static const char* kCG11 =
      "* Business calendar \"c_g11\" created by -bcal create-\n"
      "* Created/replaced on  8 Sep 2026\n"
      "\n"
      "version 19.5\n"
      "dateformat ymd\n"
      "\n"
      "range 2020jan01 2020jan31\n"
      "centerdate 2020jan01\n"
      "\n"
      "omit date 2020jan10\n"
      "omit date 2020jan11\n"
      "omit date 2020jan12\n"
      "omit date 2020jan13\n"
      "omit date 2020jan14\n"
      "omit date 2020jan15\n"
      "omit date 2020jan16\n"
      "omit date 2020jan17\n"
      "omit date 2020jan18\n"
      "omit date 2020jan19\n";

  static const char* kCG12 =
      "* Business calendar \"c_g12\" created by -bcal create-\n"
      "* Created/replaced on  8 Sep 2026\n"
      "\n"
      "version 19.5\n"
      "dateformat ymd\n"
      "\n"
      "range 2020jan01 2020jan31\n"
      "centerdate 2020jan01\n"
      "\n"
      "omit date 2020jan10\n"
      "omit date 2020jan11\n"
      "omit date 2020jan12\n"
      "omit date 2020jan13\n"
      "omit date 2020jan14\n"
      "omit date 2020jan15\n"
      "omit date 2020jan16\n"
      "omit date 2020jan17\n"
      "omit date 2020jan18\n"
      "omit date 2020jan19\n"
      "omit date 2020jan20\n";

  static const char* kDSrt =
      "* Business calendar \"d_srt\" created by -bcal create-\n"
      "* Created/replaced on  8 Sep 2026\n"
      "\n"
      "version 19.5\n"
      "dateformat ymd\n"
      "\n"
      "range 2020jan01 2020feb28\n"
      "centerdate 2020jan01\n"
      "\n"
      "omit dayofweek (Sa Su)\n"
      "omit date 2020jan03\n"
      "omit date 2020jan20\n"
      "omit date 2020feb12\n"
      "omit date 2020feb13\n"
      "omit date 2020feb17\n";

  static const char* kGCtr =
      "* Business calendar \"g_ctr\" created by -bcal create-\n"
      "* Created/replaced on  8 Sep 2026\n"
      "\n"
      "version 19.5\n"
      "dateformat ymd\n"
      "\n"
      "range 2020jan06 2020feb07\n"
      "centerdate 2020jan15\n"
      "\n"
      "omit dayofweek (Sa Su)\n";

  static const char* kGLead =
      "* Business calendar \"g_lead\" created by -bcal create-\n"
      "* Created/replaced on  8 Sep 2026\n"
      "\n"
      "version 19.5\n"
      "purpose \"Demo purpose text\"\n"
      "dateformat dmy\n"
      "\n"
      "range 06jan2020 07feb2020\n"
      "centerdate 06jan2020\n"
      "\n"
      "omit dayofweek (Sa Su)\n";

  static const char* kKNonint =
      "* Business calendar \"k_nonint\" created by -bcal create-\n"
      "* Created/replaced on  8 Sep 2026\n"
      "\n"
      "version 19.5\n"
      "dateformat ymd\n"
      "\n"
      "range 2020jan01 2020jan05\n"
      "centerdate 2020jan01\n"
      "\n"
      "omit dayofweek (Mo Tu Fr)\n"
      "omit date 2020jan02\n";

  static const char* kRLead =
      "* Business calendar \"r_lead\" created by -bcal create-\n"
      "* Created/replaced on  8 Sep 2026\n"
      "\n"
      "version 19.5\n"
      "dateformat ymd\n"
      "\n"
      "range 2020jan01 2020feb12\n"
      "centerdate 2020jan01\n"
      "\n"
      "omit dayofweek (Sa Su)\n"
      "omit date 2020jan02\n"
      "omit date 2020jan03\n"
      "omit date 2020feb10\n"
      "omit date 2020feb11\n";

  static const char* kZNi =
      "* Business calendar \"z_ni\" created by -bcal create-\n"
      "* Created/replaced on  8 Sep 2026\n"
      "\n"
      "version 19.5\n"
      "dateformat ymd\n"
      "\n"
      "range 2020jan01 2020jan15\n"
      "centerdate 2020jan01\n"
      "\n"
      "omit dayofweek (Mo Tu Su)\n";

  static const char* kESp =
      "* Business calendar \"e_sp\" created by -bcal create-\n"
      "* Created/replaced on  8 Sep 2026\n"
      "\n"
      "version 19.5\n"
      "dateformat ymd\n"
      "\n"
      "range 2020jan02 2021dec31\n"
      "centerdate 2020jan02\n"
      "\n"
      "omit dayofweek (Sa Su)\n"
      "omit date 2020jan20\n"
      "omit date 2020feb17\n"
      "omit date 2020apr10\n"
      "omit date 2020may25\n"
      "omit date 2020jul03\n"
      "omit date 2020sep07\n"
      "omit date 2020nov26\n"
      "omit date 2020dec25\n"
      "omit date 2021jan01\n"
      "omit date 2021jan18\n"
      "omit date 2021feb15\n"
      "omit date 2021apr02\n"
      "omit date 2021may31\n"
      "omit date 2021jul05\n"
      "omit date 2021sep06\n"
      "omit date 2021nov25\n"
      "omit date 2021dec24\n";


  const std::string kToday = "* Created/replaced on  8 Sep 2026";
  auto td = [](int y, unsigned m, unsigned d) {
    return static_cast<double>(piet::bcal::daysFromCivil(y, m, d));
  };
  // `WK n` and the daily fixture are the capture do-files' own programs.
  auto wk = [&](int n) {
    std::vector<double> v;
    for (int i = 0; i < n; ++i) {
      const double d = td(2020, 1, 1) + i;
      const int w = piet::bcal::dowOf(static_cast<std::int64_t>(d));
      if (w != 0 && w != 6) v.push_back(d);
    }
    return v;
  };
  auto daily = [&](int n) {
    std::vector<double> v;
    for (int i = 0; i < n; ++i) v.push_back(td(2020, 1, 1) + i);
    return v;
  };
  auto without = [](std::vector<double> v, const std::vector<double>& drop) {
    std::vector<double> o;
    for (double x : v) {
      bool skip = false;
      for (double d : drop)
        if (x == d) skip = true;
      if (!skip) o.push_back(x);
    }
    return o;
  };
  auto induce = [&](const std::string& name, const std::vector<double>& v,
                    piet::bcal::InduceOpts o) {
    o.calName = name;
    o.todayLine = kToday;
    return piet::bcal::induceFromDates(v, o);
  };
  auto byteCheck = [&](const std::string& name, const std::vector<double>& v,
                       const piet::bcal::InduceOpts& o, const char* want) {
    piet::bcal::InduceResult r = induce(name, v, o);
    check(r.ok && r.text == want,
          "B2-3 bcal write: " + name + ".stbcal byte-identical to StataBE's own file" +
              (r.ok ? (r.text == want ? std::string() : " -- GOT:\n" + r.text)
                    : " -- rc " + std::to_string(r.rc) + " " + r.message));
  };

  const piet::bcal::InduceOpts kPlain;

  // --- 1..3: the plain shapes ---------------------------------------------
  {  // (a) 40 days from 01jan2020 minus Monday and Tuesday
    std::vector<double> v;
    for (double d : daily(40)) {
      const int w = piet::bcal::dowOf(static_cast<std::int64_t>(d));
      if (w != 1 && w != 2) v.push_back(d);
    }
    byteCheck("a_wk", v, kPlain, kAWk);
  }
  byteCheck("b_hol",
            without(wk(59), {td(2020, 1, 3), td(2020, 1, 20), td(2020, 2, 12), td(2020, 2, 13),
                             td(2020, 2, 17)}),
            kPlain, kBHol);
  // A DAILY calendar missing three days emits `omit date` lines and NO
  // `omit dayofweek` line at all -- one Sunday absent out of four does not
  // make Sunday an omitted weekday (the census is "occurs in NO value").
  byteCheck("b_daily", without(daily(31), {td(2020, 1, 5), td(2020, 1, 15), td(2020, 1, 16)}),
            kPlain, kBDaily);

  // --- 4..6: the maxgap boundary ------------------------------------------
  {
    std::vector<double> hole10, hole11;
    for (double d : daily(31)) {
      if (d < td(2020, 1, 10) || d > td(2020, 1, 19)) hole10.push_back(d);
      if (d < td(2020, 1, 10) || d > td(2020, 1, 20)) hole11.push_back(d);
    }
    byteCheck("c_g11", hole10, kPlain, kCG11);  // 10 omitted days: exactly maxgap
    piet::bcal::InduceResult bad = induce("c_g12", hole11, kPlain);
    check(!bad.ok && bad.rc == 198,
          "B2-3 bcal maxgap: an 11-day hole is rc 198 under the default maxgap(10) (oracle "
          "c12_rc), got rc " + std::to_string(bad.rc));
    piet::bcal::InduceOpts mg11;
    mg11.maxgap = 11;
    byteCheck("c_g12", hole11, mg11, kCG12);
    piet::bcal::InduceOpts mg0;
    mg0.maxgap = 0;
    piet::bcal::InduceResult z = induce("c_g12", hole11, mg0);
    check(!z.ok && z.rc == 198,
          "B2-3 bcal maxgap: maxgap(0) is rc 198 `should be at least 1' (oracle c_mg0_rc)");
  }

  // --- 7: order and duplicates are irrelevant ------------------------------
  {
    std::vector<double> v = without(wk(59), {td(2020, 1, 3), td(2020, 1, 20), td(2020, 2, 12),
                                             td(2020, 2, 13), td(2020, 2, 17)});
    std::vector<double> shuffled;
    for (size_t i = 0; i < v.size(); ++i) shuffled.push_back(v[(i * 7 + 3) % v.size()]);
    for (size_t i = 0; i < v.size(); i += 4) shuffled.push_back(v[i]);  // duplicates
    byteCheck("d_srt", shuffled, kPlain, kDSrt);
  }

  // --- 8..10: centerdate, dateformat/purpose, range() ---------------------
  {
    std::vector<double> g;
    for (double d : wk(40))
      if (d >= td(2020, 1, 6)) g.push_back(d);
    piet::bcal::InduceOpts ctr;
    ctr.haveCenter = true;
    ctr.center = static_cast<std::int64_t>(td(2020, 1, 15));
    byteCheck("g_ctr", g, ctr, kGCtr);

    piet::bcal::InduceOpts dmy;
    dmy.dateformat = "dmy";
    dmy.purpose = "Demo purpose text";
    byteCheck("g_lead", g, dmy, kGLead);

    // range() on BOTH sides: the endpoints become business days even though
    // they are not in the data, and the days between them and the data are
    // emitted as `omit date` unless their weekday is already omitted.
    piet::bcal::InduceOpts rng;
    rng.haveRangeLo = rng.haveRangeHi = true;
    rng.rangeLo = static_cast<std::int64_t>(td(2020, 1, 1));
    rng.rangeHi = static_cast<std::int64_t>(td(2020, 2, 12));
    byteCheck("r_lead", g, rng, kRLead);
  }

  // --- 11..12: the two non-integer shapes ---------------------------------
  byteCheck("k_nonint", {21915.0, 21916.5, 21918.0, 21919.0}, kPlain, kKNonint);
  byteCheck("z_ni", {21915.0, 21916.0, 21917.0, 21918.0, 21929.5}, kPlain, kZNi);

  // --- 13: the S&P-shaped 505-day calendar --------------------------------
  {
    std::vector<double> e;
    const std::vector<double> hol = {
        td(2020, 1, 1),  td(2020, 1, 20), td(2020, 2, 17), td(2020, 4, 10), td(2020, 5, 25),
        td(2020, 7, 3),  td(2020, 9, 7),  td(2020, 11, 26), td(2020, 12, 25), td(2021, 1, 1),
        td(2021, 1, 18), td(2021, 2, 15), td(2021, 4, 2),  td(2021, 5, 31), td(2021, 7, 5),
        td(2021, 9, 6),  td(2021, 11, 25), td(2021, 12, 24)};
    for (int i = 0; i < 731; ++i) {
      const double d = td(2020, 1, 1) + i;
      const int w = piet::bcal::dowOf(static_cast<std::int64_t>(d));
      if (w == 0 || w == 6) continue;
      bool isHol = false;
      for (double h : hol)
        if (h == d) isHol = true;
      if (!isHol) e.push_back(d);
    }
    byteCheck("e_sp", e, kPlain, kESp);
  }

  // --- 14..18: the reader, and the index arithmetic on it ------------------
  {
    piet::bcal::ParseResult p = piet::bcal::parseStbcal(kAWk, "a_wk");
    check(p.ok, "B2-3 bcal read: the file bcal create wrote loads back (the self-describe step)");
    // capture.log's a_bofd_* sweep over 30dec2019..11feb2020, spot-checked at
    // every boundary it contains.
    check(std::isnan(piet::bcal::bofd(p.cal, td(2019, 12, 30))),
          "B2-3 bofd: a date BEFORE the range is missing (a_bofd_21913)");
    check(piet::bcal::bofd(p.cal, td(2020, 1, 1)) == 0,
          "B2-3 bofd: the range start is index 0 (a_bofd_21915)");
    check(std::isnan(piet::bcal::bofd(p.cal, td(2020, 1, 6))),
          "B2-3 bofd: an OMITTED weekday is missing, never the previous business day "
          "(a_bofd_21920, arm A8)");
    check(piet::bcal::bofd(p.cal, td(2020, 2, 9)) == 29 &&
              std::isnan(piet::bcal::bofd(p.cal, td(2020, 2, 11))),
          "B2-3 bofd: the range end is the last index (a_r_max_date_tb = 29), past it is "
          "missing");
    // Truncation is toward ZERO, and the fractional part never moves the answer.
    check(piet::bcal::bofd(p.cal, 21916.5) == 1 && piet::bcal::bofd(p.cal, 21916.0001) == 1 &&
              piet::bcal::bofd(p.cal, 21915.9999) == 0,
          "B2-3 bofd: trunc toward zero (a_bofd_halfday/_eps/_negeps)");
    check(std::isnan(piet::bcal::bofd(p.cal, std::nan(""))),
          "B2-3 bofd: a missing date is missing");
    check(piet::bcal::dofb(p.cal, 2.5) == 21917 && piet::bcal::dofb(p.cal, 2.0001) == 21917,
          "B2-3 dofb: trunc toward zero (a_dofb_half/_eps)");
    check(std::isnan(piet::bcal::dofb(p.cal, -1)) && std::isnan(piet::bcal::dofb(p.cal, 30)) &&
              std::isnan(piet::bcal::dofb(p.cal, 1e10)),
          "B2-3 dofb: out of range is MISSING, never clamped (arm A9)");
    // Round trip over every business day.
    bool rt = true;
    for (std::int64_t i = p.cal.minTb; i <= p.cal.maxTb; ++i) {
      const double d = piet::bcal::dofb(p.cal, static_cast<double>(i));
      if (std::isnan(d) || piet::bcal::bofd(p.cal, d) != static_cast<double>(i)) rt = false;
    }
    check(rt, "B2-3 round trip: dofb(bofd(d)) == d on every business day (a_rt_mismatch = 0)");
  }
  {  // negative indices before an explicit centerdate (g_ctr, centerdate 15jan)
    piet::bcal::ParseResult p = piet::bcal::parseStbcal(kGCtr, "g_ctr");
    check(p.ok && piet::bcal::bofd(p.cal, td(2020, 1, 6)) == -7 &&
              piet::bcal::bofd(p.cal, td(2020, 1, 14)) == -1 &&
              piet::bcal::bofd(p.cal, td(2020, 1, 15)) == 0,
          "B2-3 bofd: indices are NEGATIVE before the centerdate (g_c15_bofd_06jan/_14jan)");
    check(piet::bcal::dofb(p.cal, -7) == td(2020, 1, 6) && std::isnan(piet::bcal::dofb(p.cal, -8)),
          "B2-3 dofb: -7 is 06jan2020 and -8 is missing (g_c15_dofb_neg7/_neg8)");
  }
  {  // z_ni: 9 business days and bofd(15jan2020) == 8 (REFUTE-0 T5's numbers)
    piet::bcal::ParseResult p = piet::bcal::parseStbcal(kZNi, "z_ni");
    check(p.ok && p.cal.maxTb - p.cal.minTb + 1 == 9 &&
              piet::bcal::bofd(p.cal, td(2020, 1, 15)) == 8,
          "B2-3 bcal: z_ni has r(included) 9 and bofd(15jan2020) 8 -- the diff-walk's answer, "
          "not the presence census's");
  }
  {  // the reader's own rejections, each one a measured rc 197
    struct R {
      const char* text;
      const char* what;
    };
    const std::vector<R> bad = {
        {"version 19.5\ndateformat ymd\nrange 2020jan01 2020feb07\ncenterdate 2020jan01\n"
         "omit dayofweek (Sa Su)\nomit dayofweek We if month(Jan) & year(2020)\n",
         "the range start becomes a holiday (h_ifand)"},
        {"version 19.5\ndateformat ymd\nrange 2020jan01 2020feb07\ncenterdate 2020jan01\n"
         "omit dayofweek We if month(Jan) | month(Feb)\n",
         "`|' joining if() conditions (h_ifor)"},
        {"version 19.5\ndateformat ymd\nrange 2020jan01 2020feb07\ncenterdate 2020jan01\n"
         "omit dayofweek (Sa Sa Su)\n",
         "a repeated day of week (h_dowdup)"},
        // z_win.stbcal verbatim (REFUTE-0 T6). dateformat dmy, so `16jun2020`
        // really parses -- an ymd spelling here would be refused as a bad DATE
        // and the leg would pass for the wrong reason.
        {"version 19.5\ndateformat dmy\nrange 02jan2020 31dec2020\ncenterdate 02jan2020\n"
         "omit dayofweek (Sa Su)\n"
         "from 16jun2020 to 30jun2020: omit date 16jun2020 and -1\n"
         "from 16jun2020 to 30jun2020: omit date 30jun2020 and +1\n",
         "a from/to window on a FULL-date omit (REFUTE-0 T6, z_win.stbcal)"},
        {"version 19.5\ndateformat ymd\ncenterdate 2020jan01\nrange 2020jan01 2020feb07\n",
         "centerdate before range"},
        {"", "an empty file (range undefined)"},
    };
    for (const auto& b : bad) {
      piet::bcal::ParseResult p = piet::bcal::parseStbcal(b.text, "probe");
      check(!p.ok && p.err.rc == 197,
            std::string("B2-3 bcal read: rc 197 for ") + b.what + " -- got " +
                (p.ok ? "ACCEPTED" : "rc " + std::to_string(p.err.rc)));
    }
    // ... and the shapes that must be ACCEPTED, including the manual's own
    // Christmas rules and the fifth-Monday case (arm A10).
    piet::bcal::ParseResult dim = piet::bcal::parseStbcal(
        "version 19.5\ndateformat dmy\nrange 02jan2020 30dec2021\ncenterdate 02jan2020\n"
        "omit dayofweek (Sa Su)\nomit dowinmonth -1 Mo of May\n",
        "dim");
    check(dim.ok && std::isnan(piet::bcal::bofd(dim.cal, td(2021, 5, 31))) &&
              !std::isnan(piet::bcal::bofd(dim.cal, td(2021, 5, 24))),
          "B2-3 bcal read: `-1 Mo of May' is 31may2021, the FIFTH Monday (arm A10 rejected)");
    piet::bcal::ParseResult star = piet::bcal::parseStbcal(
        "version 19.5\ndateformat ymd\nrange 2020jan02 2021dec31\ncenterdate 2020jan02\n"
        "omit dayofweek (Sa Su)\nomit date *jan01\nomit date *jul04\n",
        "star");
    check(star.ok && std::isnan(piet::bcal::bofd(star.cal, td(2021, 1, 1))) &&
              !std::isnan(piet::bcal::bofd(star.cal, td(2021, 1, 4))),
          "B2-3 bcal read: `*jan01' omits the date in every year of the range (h_star)");
    piet::bcal::ParseResult win = piet::bcal::parseStbcal(
        "version 19.5\ndateformat dmy\nrange 02jan2020 31dec2021\ncenterdate 02jan2020\n"
        "omit dayofweek (Sa Su)\nfrom . to 31dec2020: omit dayofweek Fr if month(Aug)\n",
        "win");
    check(win.ok && std::isnan(piet::bcal::bofd(win.cal, td(2020, 8, 7))) &&
              !std::isnan(piet::bcal::bofd(win.cal, td(2021, 8, 6))),
          "B2-3 bcal read: a from/to window really restricts the rule (arm A13 rejected)");
    piet::bcal::ParseResult offs = piet::bcal::parseStbcal(
        "version 19.5\ndateformat dmy\nrange 02jan2020 31dec2021\ncenterdate 02jan2020\n"
        "omit dayofweek (Sa Su)\nfrom 16jun2020 to 30jun2020: omit date 16jun* and -1\n"
        "from 16jun2020 to 30jun2020: omit date 30jun* and +1\n",
        "offs");
    check(offs.ok && std::isnan(piet::bcal::bofd(offs.cal, td(2020, 6, 15))) &&
              std::isnan(piet::bcal::bofd(offs.cal, td(2020, 7, 1))),
          "B2-3 bcal read: an `and +/-k' offset may land OUTSIDE the window (REFUTE-0 T7)");
    // The loader's default dateformat is dmy -- the manual says ymd and is
    // wrong about this loader (h_nodf_dmy loads, h_nodf_ymd does not).
    piet::bcal::ParseResult nodfDmy = piet::bcal::parseStbcal(
        "version 19.5\nrange 1/1/2020 2/7/2020\ncenterdate 1/1/2020\n", "nodf");
    piet::bcal::ParseResult nodfYmd = piet::bcal::parseStbcal(
        "version 19.5\nrange 2020jan01 2020feb07\ncenterdate 2020jan01\n", "nodf");
    check(nodfDmy.ok && nodfDmy.cal.hi == static_cast<std::int64_t>(td(2020, 7, 2)) &&
              !nodfYmd.ok,
          "B2-3 bcal read: with no `dateformat' line the default is DMY -- `2/7/2020' is 2 JULY "
          "(oracle max_date_td 22098), and an ymd-spelled date fails. The manual says ymd is "
          "assumed and is wrong about this loader.");
  }

  // --- 19..: the command surface, driven through dispatch ------------------
  auto errOf = [](const nlohmann::ordered_json& blocks) -> nlohmann::ordered_json {
    for (const auto& b : blocks)
      if (b.is_object() && b.value("type", std::string()) == "error") return b;
    return nlohmann::ordered_json::object();
  };
  {
    piet::SessionState s(workdir);
    s.eval.cwd = workdir;
    s.cwd = workdir;
    auto rcAfter = [&](const std::string& src) {
      (void)piet::doexec::executeDoSource("capture " + src + "\n", s, piet::dispatch);
      return s.eval.locals.get("_rc", "<unset>");
    };
    (void)piet::doexec::executeDoSource(
        "clear\nset obs 40\ngen bd = td(01jan2020) + _n - 1\ndrop if inlist(dow(bd), 1, 2)\n", s,
        piet::dispatch);
    auto out = piet::dispatch("bcal create selfwk, from(bd) replace", s);
    check(errOf(out).empty(), "B2-3 bcal: `bcal create NAME, from(v) replace' runs");
    check(fs::exists(fs::path(workdir) / "selfwk.stbcal"),
          "B2-3 bcal: the .stbcal lands in the session's cwd, not the scratch workdir");
    const double* minTd = s.eval.rValues.find("min_date_td");
    const double* maxTb = s.eval.rValues.find("max_date_tb");
    const double* omitted = s.eval.rValues.find("omitted");
    const double* oy = s.eval.rValues.find("omitted_year");
    check(minTd != nullptr && *minTd == 21915 && maxTb != nullptr && *maxTb == 29 &&
              omitted != nullptr && *omitted == 10,
          "B2-3 bcal: r(min_date_td)=21915, r(max_date_tb)=29, r(omitted)=10 (oracle a_r_*)");
    check(oy != nullptr && std::fabs(*oy - 91.3) < 1e-9,
          "B2-3 bcal: r(omitted_year) is rounded to one decimal, as Stata posts it");
    // The name resolves on every expression surface, through ONE loader.
    (void)piet::dispatch("gen b = bofd(\"selfwk\", bd)", s);
    (void)piet::dispatch("gen rt = dofb(b, \"selfwk\")", s);
    (void)piet::dispatch("count if rt != bd", s);
    const double* nBad = s.eval.rValues.find("N");
    check(nBad != nullptr && *nBad == 0,
          "B2-3 bcal: gen/dofb round trip over the whole column has 0 mismatches");
    (void)piet::dispatch("local dl = bofd(\"selfwk\", 21916)", s);
    check(s.eval.locals.get("dl", "") == "1",
          "B2-3 bcal: `local = bofd(...)' reaches the SAME loader as gen (evalArith's "
          "process namespace), got `" + s.eval.locals.get("dl", "<unset>") + "`");
    // Unknown / suffixed / prefixed names -- Stata answers missing with rc 0.
    (void)piet::dispatch("local u1 = bofd(\"nosuchcal\", 21916)", s);
    (void)piet::dispatch("local u2 = bofd(\"selfwk.stbcal\", 21916)", s);
    (void)piet::dispatch("local u3 = bofd(\"%tbselfwk\", 21916)", s);
    check(s.eval.locals.get("u1", "") == "." && s.eval.locals.get("u2", "") == "." &&
              s.eval.locals.get("u3", "") == "1",
          "B2-3 bofd: unknown name and a `.stbcal' SUFFIX are missing (rc 0); a `%tb' PREFIX "
          "names the same calendar");
    check(rcAfter("display bofd(\"selfwk\", \"21916\")") == "109",
          "B2-3 bofd: a STRING date is r(109) type mismatch (a_bofd_strdate_rc)");
    check(rcAfter("gen bad2 = bofd(21916, \"selfwk\")") == "109",
          "B2-3 bofd: swapped arguments are r(109) on the GEN surface too -- macros.cpp's "
          "stringFnArgSpecs row, the rule BUG-456's landing added (a_bofd_swapped_rc)");
    check(rcAfter("display bofd(\"selfwk\")") == "198" &&
              rcAfter("display bofd(\"selfwk\", 21916, 1)") == "198",
          "B2-3 bofd: arity 1 and arity 3 are r(198) (a_bofd_arity1_rc/_arity3_rc)");
    // NAMED DIVERGENCE (pre-existing, not bcal's): on the GEN surface an
    // exception raised INSIDE a function is reported as a generic evaluation
    // failure, rc 1 -- `gen x = substr("abcdef")` and `gen x = strlen("a","b")`
    // measure the same 1 on this build. The answer is still an error, never a
    // silent wrong number; only the code is coarse. BUGLOG-461.
    check(rcAfter("gen bad3 = bofd(\"selfwk\")") != "0",
          "B2-3 bofd: a bad-arity call on the GEN surface still ERRORS (rc 1 there, the shared "
          "pre-existing coarse code -- BUGLOG-461)");
    // A calendar name held in a STRING VARIABLE, per row.
    (void)piet::dispatch("gen str8 cn = \"selfwk\"", s);
    (void)piet::dispatch("gen bv = bofd(cn, bd)", s);
    (void)piet::dispatch("count if bv != b", s);
    const double* nv = s.eval.rValues.find("N");
    check(nv != nullptr && *nv == 0,
          "B2-3 bofd: the calendar name may be a string VARIABLE, resolved per row");
    // `format v %tbNAME` is accepted and `display %tbNAME i` renders the date.
    check(errOf(piet::dispatch("format b %tbselfwk", s)).empty(),
          "B2-3 bcal: `format v %tbNAME' is accepted (Stata accepts it even for an unknown "
          "calendar)");
    auto disp = piet::dispatch("display %tbselfwk 3", s);
    std::string dtext;
    for (const auto& b : disp)
      if (b.is_object() && b.value("type", std::string()) == "display")
        dtext = b.value("text", std::string());
    check(dtext.find("04jan2020") != std::string::npos,
          "B2-3 bcal: `display %tbNAME 3' prints the calendar date (a_disp_tb_3 = 04jan2020), "
          "got `" + dtext + "`");
    auto dispOut = piet::dispatch("display %tbselfwk 99", s);
    std::string otext;
    for (const auto& b : dispOut)
      if (b.is_object() && b.value("type", std::string()) == "display")
        otext = b.value("text", std::string());
    check(otext.find("99") != std::string::npos,
          "B2-3 bcal: an index OUTSIDE the calendar prints the raw number (a_disp_tb_99)");
    // File-level rcs.
    check(rcAfter("bcal create selfwk, from(bd)") == "602",
          "B2-3 bcal: an existing file without `replace' is r(602)");
    check(rcAfter("bcal create abcdefghijk, from(bd) replace") == "198",
          "B2-3 bcal: an 11-character calendar name is r(198)");
    check(rcAfter("bcal create selfwk.txt, from(bd) replace") == "198",
          "B2-3 bcal: an extension other than .stbcal is r(198)");
    check(rcAfter("bcal create 9bad, from(bd) replace") == "198",
          "B2-3 bcal: a name that is not a valid Stata name is r(198)");
    check(rcAfter("bcal create nodir/x, from(bd) replace") == "601",
          "B2-3 bcal: a path whose directory does not exist is r(601)");
    check(rcAfter("bcal describe nosuchcal") == "601",
          "B2-3 bcal: `bcal describe' on an unknown calendar is r(601)");
    // 06jan2020 is a MONDAY, and this calendar omits Monday and Tuesday, so
    // the centerdate lands on a business holiday -- g_sat's shape.
    check(rcAfter("bcal create selfsat, from(bd) centerdate(2020jan06) replace") == "197",
          "B2-3 bcal: a centerdate on an omitted weekday fails the self-describe with r(197) "
          "(g_sat_rc)");
    check(!fs::exists(fs::path(workdir) / "selfsat.stbcal"),
          "B2-3 bcal: the r(197) self-describe failure leaves NO file behind (g_sat_file_rc "
          "601)");
    // generate(): a long column formatted %tbNAME.
    check(errOf(piet::dispatch("bcal create selfgen, from(bd) generate(gv) replace", s)).empty(),
          "B2-3 bcal: `generate(newvar)' runs");
    check(s.varMeta.count("gv") != 0 && s.varMeta["gv"].format.has_value() &&
              *s.varMeta["gv"].format == "%tbselfgen",
          "B2-3 bcal: generate() formats the new variable %tbNAME");
    check(rcAfter("bcal create selfgen, from(bd) generate(gv) replace") == "110",
          "B2-3 bcal: generate() onto an EXISTING variable is r(110)");
    check(rcAfter("bcal create selfper, from(bd) personal replace") == "198",
          "B2-3 bcal: `personal' is refused by name -- PIET models no PERSONAL directory "
          "(named divergence D4), never silently written somewhere it cannot be found");
    // The cache refresh the paper depends on: a second create over a NARROWER
    // date set turns the later dates missing at the very next bofd.
    (void)piet::dispatch("local pre = bofd(\"selfwk\", td(09feb2020))", s);
    (void)piet::doexec::executeDoSource("drop if bd > td(20jan2020)\n", s, piet::dispatch);
    (void)piet::dispatch("bcal create selfwk, from(bd) replace", s);
    (void)piet::dispatch("local post = bofd(\"selfwk\", td(09feb2020))", s);
    check(s.eval.locals.get("pre", "") == "29" && s.eval.locals.get("post", "") == ".",
          "B2-3 bcal: a second `bcal create ..., replace' REFRESHES the cache -- the paper's "
          "38/80 hazard (pre=" + s.eval.locals.get("pre", "?") + ", post=" +
              s.eval.locals.get("post", "?") + ")");
    // bcal dir / load / check
    auto dirOut = piet::dispatch("bcal dir self*", s);
    check(errOf(dirOut).empty() &&
              s.eval.rStrings.get("calendars", "").find("selfwk") != std::string::npos,
          "B2-3 bcal: `bcal dir PATTERN' lists the cwd and fills r(calendars)");
    check(errOf(piet::dispatch("bcal load selfwk", s)).empty(),
          "B2-3 bcal: `bcal load' re-reads the file and reports success");
    (void)piet::dispatch("format b %tbnosuchcal", s);
    check(rcAfter("bcal check b") == "459",
          "B2-3 bcal: `bcal check' over a %tb format with no calendar is r(459)");
    check(rcAfter("bcal check b, rc0") == "0" &&
              s.eval.rStrings.get("undefined", "") == "nosuchcal",
          "B2-3 bcal: `bcal check, rc0' is rc 0 with r(undefined) naming the calendar");
  }
  {  // no data in memory: `bcal create` is Stata's rc 3, not a refusal
    piet::SessionState s(workdir);
    s.eval.cwd = workdir;
    s.cwd = workdir;
    (void)piet::doexec::executeDoSource("capture bcal create nodatacal, from(bd)\n", s,
                                        piet::dispatch);
    check(s.eval.locals.get("_rc", "") == "3",
          "B2-3 bcal: `bcal create' with nothing in memory is r(3) `no dataset in use', got _rc=" +
              s.eval.locals.get("_rc", "<unset>"));
  }

  // --- the calendar-NAME rule on the READ path -----------------------------
  // [D] bcal printed p.29: "calname has to be a valid Stata name but limited to
  // 10 characters". The landing enforced it only in the create branch, so PIET
  // ANSWERED where Stata refuses -- and on the data plane it answered a NUMBER
  // where Stata answers missing. Every rc below is measured, StataBE 19.5 on
  // this machine, with the SAME valid five-line .stbcal present in the cwd
  // (/private/tmp/bcalfix/stata/s1.log, s2.log, s3.log; the review's
  // /private/tmp/bcalrev/stata/probe2.log agrees).
  {
    const std::string namedir = (fs::path(workdir) / "names").u8string();
    fs::create_directories(namedir, ec);
    static const char* kValidCal =
        "version 19.5\n"
        "dateformat ymd\n"
        "range 2020jan01 2020feb07\n"
        "centerdate 2020jan01\n"
        "omit dayofweek (Sa Su)\n";
    for (const char* nm : {"elevenchars", "9bad", "tenchars10"}) {
      std::ofstream f((fs::path(namedir) / (std::string(nm) + ".stbcal")).u8string(),
                      std::ios::binary);
      f << kValidCal;
    }
    piet::SessionState s(namedir);
    s.eval.cwd = namedir;
    s.cwd = namedir;
    auto rcAfter = [&](const std::string& src) {
      (void)piet::doexec::executeDoSource("capture " + src + "\n", s, piet::dispatch);
      return s.eval.locals.get("_rc", "<unset>");
    };
    auto valOf = [&](const std::string& expr) {
      (void)piet::doexec::executeDoSource("local __v = " + expr + "\n", s, piet::dispatch);
      return s.eval.locals.get("__v", "<unset>");
    };
    check(rcAfter("bcal load elevenchars") == "198" &&
              rcAfter("bcal describe elevenchars") == "198",
          "B2-3 bcal name rule: an 11-character name is r(198) on BOTH read verbs, with a "
          "perfectly readable file right there (e11_load_rc/e11_desc_rc = 198)");
    check(rcAfter("bcal load 9bad") == "198" && rcAfter("bcal describe 9bad") == "198",
          "B2-3 bcal name rule: a name that is not a valid Stata name is r(198) on both read "
          "verbs (b9_load_rc = 198)");
    check(rcAfter("bcal describe %tbelevenchars") == "198",
          "B2-3 bcal name rule: the rule is applied AFTER the %tb strip -- `bcal describe "
          "%tbelevenchars' is r(198), not a lookup of a name called `%tbelevenchars'");
    check(rcAfter("bcal load elevenchr11") == "198",
          "B2-3 bcal name rule: the name rule beats the missing-file rule -- an 11-character "
          "name with NO file is r(198), not r(601) (measured, s3.log M01)");
    check(rcAfter("bcal load nosuchcal") == "601",
          "B2-3 bcal name rule: a LEGAL name with no file keeps its own r(601) -- the two "
          "refusals are distinct in Stata and stay distinct here");
    check(valOf("bofd(\"elevenchars\", 21916)") == "." &&
              valOf("bofd(\"9bad\", 21916)") == "." &&
              valOf("dofb(1, \"elevenchars\")") == ".",
          "B2-3 bcal name rule: the DATA plane answers MISSING with rc 0 for an invalid name "
          "-- it answered 1 before this fix (e11_bofd/b9_bofd = `.')");
    check(rcAfter("bcal load tenchars10") == "0" && valOf("bofd(\"tenchars10\", 21916)") == "1",
          "B2-3 bcal name rule: TEN characters is inside the rule -- the boundary is <= 10, "
          "not < 10 (measured, s1.log R09/R10)");
    (void)piet::doexec::executeDoSource(
        "clear\nset obs 5\ngen bd = td(01jan2020) + _n - 1\n"
        "gen b11 = bofd(\"elevenchars\", bd)\ncount if missing(b11)\n",
        s, piet::dispatch);
    const double* nMiss = s.eval.rValues.find("N");
    check(nMiss != nullptr && *nMiss == 5,
          "B2-3 bcal name rule: over 5 rows ALL five are missing (Stata 5; this branch answered "
          "2 before the fix) -- the silent-wrong-answer half of the finding");
    auto dirOut = piet::dispatch("bcal dir *", s);
    const std::string cals = s.eval.rStrings.get("calendars", "");
    check(errOf(dirOut).empty() && cals.find("elevenchars") != std::string::npos,
          "B2-3 bcal name rule: `bcal dir' does NOT apply it -- an invalid-named .stbcal is "
          "still listed (e11_dir_cals), got `" + cals + "`");
    // --- the option net, per sub-command ----------------------------------
    // kVocabBcal is the UNION of five `syntax` lines; rejecting against it
    // before the sub-command is resolved let every sub-command swallow every
    // other sub-command's options as a silent no-op. All seven of these
    // answered rc 0 before the fix.
    check(rcAfter("bcal describe tenchars10, maxgap(5)") == "101" &&
              rcAfter("bcal describe tenchars10, from(bd)") == "101" &&
              rcAfter("bcal describe tenchars10, purpose(\"x\")") == "101",
          "B2-3 bcal options: `bcal describe' is a BARE `syntax' -- ANY option is r(101) "
          "`options not allowed'");
    check(rcAfter("bcal load tenchars10, replace") == "101",
          "B2-3 bcal options: `bcal load' is a bare `syntax' too -- r(101)");
    check(rcAfter("bcal describe elevenchars, maxgap(5)") == "101",
          "B2-3 bcal options: the OPTION error beats the calendar-name error, as in Stata "
          "(measured 101, not 198)");
    check(rcAfter("bcal dir, rc0") == "198",
          "B2-3 bcal options: `bcal dir' takes no rc0 -- r(198)");
    check(rcAfter("bcal check, maxgap(4)") == "198" && rcAfter("bcal check, rc0") == "0",
          "B2-3 bcal options: `bcal check' takes rc0 and NOTHING else -- maxgap() is r(198), "
          "rc0 is rc 0");
    check(rcAfter("bcal create c1, from(bd) replace rc0") == "198",
          "B2-3 bcal options: `bcal create' has no rc0 -- r(198)");
    check(rcAfter("bcal dir, testmode") != "0",
          "B2-3 bcal options: `bcal dir, testmode' is bcal_dir's undocumented hook (Stata rc 0, "
          "re-measured 2026-09-09 in BOTH a populated and an empty cwd -- cap2.log "
          "D_dir_testmode_rc / cap3.log E_testmode_empty_rc; the review's r(3300) does not "
          "reproduce here); PIET has no such mode and refuses it BY NAME, not as a no-op");
    // --- non-blocking review items, pinned so the agreement is not accidental
    (void)piet::doexec::executeDoSource(
        "clear\nset obs 5\ngen obd = td(02jan2020)\n", s, piet::dispatch);
    check(rcAfter("bcal create onecal, from(obd) replace") == "197" &&
              !fs::exists(fs::path(namedir) / "onecal.stbcal"),
          "B2-3 bcal: a from() column with ONE distinct date is r(197) from the self-describe, "
          "as in Stata -- there is no writer-side range guard (measured 197, "
          "/private/tmp/bcalrev/stata/probe4.log one_rc)");
    piet::bcal::ParseResult vc = piet::bcal::parseStbcal(
        "version 19.5 // trailing comment\nrange 2020jan01 2020feb07\n"
        "centerdate 2020jan01\n",
        "vercmt");
    check(!vc.ok && vc.err.rc == 197,
          "B2-3 bcal read: `version 19.5 // trailing comment' -- the [D] manual's OWN listing "
          "style -- is r(197) in StataBE (vercmt_rc, REFUTE-1 SC) and r(197) here; the "
          "agreement is pinned, not accidental");
  }

  // --- the calendar-NAME rule on the FORMAT plane --------------------------
  // Review 2026-09-09, BLOCKING 2. The landing bound the 10-character rule on
  // the create plane and (in the same commit's review pass) on the read plane,
  // but `format x %tbNAME` -- the third surface the same commit added -- took
  // ANY identifier. That is a LENIENCY divergence, which this repo's own
  // adjudication law defaults to refusing. Every rc below is StataBE 19.5 on
  // this machine, /private/tmp/fix-bcal/st/cap.log keys A_*:
  //   A_ten_rc 0 · A_ten_detail_rc 0 · A_one_rc 0 · A_eleven2_rc 0
  //   A_eleven_rc 120 · A_eleven_detail_rc 120 · A_dash_rc 120
  //   A_digitstart_rc 120 · A_zz_rc 120
  // The 120 also fixes a SECOND, pre-existing gap the review named (its
  // non-blocking 8): every invalid format used to leave here as the generic
  // engine_error, i.e. rc 1, because "invalid_format" is not one of the frozen
  // error codes. `%zz` measures 120 in Stata too, so the whole refusal now
  // carries the rc rather than the %tb arm carrying a special case.
  {
    const std::string fmtdir = (fs::path(workdir) / "fmt").u8string();
    fs::create_directories(fmtdir, ec);
    piet::SessionState s(fmtdir);
    s.eval.cwd = fmtdir;
    s.cwd = fmtdir;
    auto rcAfter = [&](const std::string& src) {
      (void)piet::doexec::executeDoSource("capture " + src + "\n", s, piet::dispatch);
      return s.eval.locals.get("_rc", "<unset>");
    };
    (void)piet::doexec::executeDoSource("clear\nset obs 3\ngen x = _n\n", s, piet::dispatch);
    check(rcAfter("format x %tbelevenchars") == "120",
          "B2-3 format name rule: an 11-character calendar name in a %tb format is r(120) -- "
          "this branch ACCEPTED it at rc 0 before the fix (oracle A_eleven_rc = 120)");
    check(rcAfter("format x %tbelevenchars:day") == "120",
          "B2-3 format name rule: the detail-coded form is judged on the NAME, not on the "
          "whole spec (A_eleven_detail_rc = 120)");
    check(rcAfter("format x %tbabcdefghij") == "0" &&
              rcAfter("format x %tbabcdefghij:day") == "0",
          "B2-3 format name rule: TEN characters is inside the rule, with and without a detail "
          "code -- the boundary is <= 10 (A_ten_rc / A_ten_detail_rc = 0)");
    check(rcAfter("format x %tba") == "0",
          "B2-3 format name rule: a one-character name is fine (A_one_rc = 0)");
    check(rcAfter("format x %tbab-cd") == "120" && rcAfter("format x %tb9abc") == "120",
          "B2-3 format name rule: a name that is not a valid Stata name is r(120) -- and it is "
          "r(120), not the generic rc 1 this build used to answer (A_dash_rc/A_digitstart_rc)");
    check(rcAfter("format x %zz") == "120",
          "B2-3 format: EVERY unrecognised %fmt is r(120), not rc 1 -- the review's "
          "non-blocking 8 class, closed by the same refusal (A_zz_rc = 120)");
    check(rcAfter("format x %td") == "0" && rcAfter("format x %9.2f") == "0" &&
              rcAfter("format x %tbtenchars10") == "0",
          "B2-3 format: the accepting arms are untouched by the r(120) change");
  }

  // --- the calendar cache is keyed by NAME, and `cd` does not drop it ------
  // Review 2026-09-09, BLOCKING 1. The cache key used to be (search directory,
  // name), and runCd re-points the search directory on every `cd` -- so a `cd`
  // SILENTLY DROPPED a loaded calendar (missing, rc 0) and a `cd` back
  // resurrected a stale one (wrong value, rc 0). Both are Doctrine-(1). Stata's
  // cache is NAME-keyed; measured this review, StataBE 19.5,
  // /private/tmp/fix-bcal/st/cap.log:
  //   B_before 1 · B_in_sub 1 · B_sub_recreate -1 · B_back -1
  //   C_after_erase 1 · C_in_sub 1 · C_back 1   (the file is gone throughout)
  // and the OTHER direction still has to hold -- a not-yet-loaded calendar is
  // found in the new cwd (capture2.log l_cd_bofd_in_sub = 1), which is why
  // `cd` still re-points the search DIRECTORY. Resolution is by directory;
  // memory is by name.
  {
    const std::string cddir = (fs::path(workdir) / "cd").u8string();
    fs::create_directories(fs::path(cddir) / "sub", ec);
    piet::SessionState s(cddir);
    s.eval.cwd = cddir;
    s.cwd = cddir;
    auto run = [&](const std::string& src) {
      (void)piet::doexec::executeDoSource(src, s, piet::dispatch);
    };
    auto valOf = [&](const std::string& expr) {
      (void)piet::doexec::executeDoSource("local __v = " + expr + "\n", s, piet::dispatch);
      return s.eval.locals.get("__v", "<unset>");
    };
    run("clear\nset obs 30\ngen bd = td(01jan2020) + _n - 1\nformat bd %td\n");
    run("quietly bcal create cdcal, from(bd) replace\n");
    const std::string before = valOf("bofd(\"cdcal\", td(02jan2020))");
    run("cd sub\n");
    const std::string inSub = valOf("bofd(\"cdcal\", td(02jan2020))");
    check(before == "1" && inSub == "1",
          "B2-3 bcal cache: a `cd' does NOT drop a loaded calendar -- Stata answers 1 in the "
          "subdirectory (B_in_sub); this branch answered `.', a MISSING at rc 0, got `" +
              inSub + "'");
    run("quietly bcal create cdcal, from(bd) centerdate(2020jan03) replace\n");
    const std::string subRecreate = valOf("bofd(\"cdcal\", td(02jan2020))");
    run("cd ..\n");
    const std::string back = valOf("bofd(\"cdcal\", td(02jan2020))");
    check(subRecreate == "-1" && back == "-1",
          "B2-3 bcal cache: a `bcal create' refreshes the cache BY NAME, so coming back out of "
          "the subdirectory still answers the SUB calendar's -1 (B_sub_recreate/B_back) -- this "
          "branch answered 1 from the stale cwd-keyed entry, a WRONG value at rc 0, got `" +
              back + "'");
    // The erase arm: the FILE is irrelevant once the calendar is in the cache,
    // across a cd in both directions (C_after_erase/C_in_sub/C_back = 1).
    run("quietly bcal create ecal, from(bd) replace\n");
    fs::remove(fs::path(cddir) / "ecal.stbcal", ec);
    const std::string afterErase = valOf("bofd(\"ecal\", td(02jan2020))");
    run("cd sub\n");
    const std::string eraseInSub = valOf("bofd(\"ecal\", td(02jan2020))");
    run("cd ..\n");
    const std::string eraseBack = valOf("bofd(\"ecal\", td(02jan2020))");
    check(afterErase == "1" && eraseInSub == "1" && eraseBack == "1",
          "B2-3 bcal cache: erasing the .stbcal changes nothing, and a `cd' out and back does "
          "not change that either (C_after_erase/C_in_sub/C_back = 1)");
    // The other direction, unchanged by the key: a calendar NEVER loaded is
    // resolved against the NEW cwd after a cd (oracle l_cd_bofd_in_sub = 1).
    {
      std::ofstream f((fs::path(cddir) / "sub" / "subonly.stbcal").u8string(), std::ios::binary);
      f << "version 19.5\ndateformat ymd\nrange 2020jan01 2020feb07\n"
           "centerdate 2020jan01\nomit dayofweek (Sa Su)\n";
    }
    const std::string beforeCd = valOf("bofd(\"subonly\", td(02jan2020))");
    run("cd sub\n");
    const std::string afterCd = valOf("bofd(\"subonly\", td(02jan2020))");
    run("cd ..\n");
    check(beforeCd == "." && afterCd == "1",
          "B2-3 bcal cache: `cd' still re-points the SEARCH DIRECTORY -- an unloaded calendar "
          "in the new cwd is found there (l_cd_bofd_in_sub = 1) and was missing before the cd");
    // Session isolation is the RESET's job now, not the key's: the cache holds
    // `cdcal' and `ecal' with no file behind ecal, and a NEW SessionState must
    // not inherit either. This is what SessionState::resetProcessCaches() buys;
    // before this review bcal::clearCache() had zero callers and the isolation
    // was carried, by accident, by the search directory sitting in the key.
    {
      const std::string isodir = (fs::path(workdir) / "iso").u8string();
      fs::create_directories(isodir, ec);
      piet::SessionState s2(isodir);
      s2.eval.cwd = isodir;
      s2.cwd = isodir;
      (void)piet::doexec::executeDoSource("local __v = bofd(\"ecal\", td(02jan2020))\n", s2,
                                          piet::dispatch);
      check(s2.eval.locals.get("__v", "<unset>") == ".",
            "B2-3 bcal cache: a NEW session does not inherit the previous session's calendars "
            "-- `ecal' has no file, so only the process cache could have answered");
    }
  }

  // --- r(fn) is a presentation string, and %tb pads its fallbacks ----------
  // Review 2026-09-09, non-blocking 3 and 4. Both are measured, StataBE 19.5
  // (/private/tmp/fix-bcal/st/cap2.log D_create_r_fn / D_desc_r_fn / D_dir_fn,
  // cap4.log F*).
  {
    const std::string pdir = (fs::path(workdir) / "pres").u8string();
    fs::create_directories(pdir, ec);
    piet::SessionState s(pdir);
    s.eval.cwd = pdir;
    s.cwd = pdir;
    auto run = [&](const std::string& src) {
      (void)piet::doexec::executeDoSource(src, s, piet::dispatch);
    };
    run("clear\nset obs 30\ngen bd = td(01jan2020) + _n - 1\nformat bd %td\n");
    run("quietly bcal create a_wk, from(bd) replace\n");
    const std::string createFn = s.eval.rStrings.get("fn", "<unset>");
    run("quietly bcal describe a_wk\n");
    const std::string descFn = s.eval.rStrings.get("fn", "<unset>");
    run("quietly bcal dir a_wk\n");
    const std::string dirFn = s.eval.rStrings.get("fn_a_wk", "<unset>");
    check(createFn == "a_wk.stbcal" && descFn == "./a_wk.stbcal" && dirFn == "./a_wk.stbcal",
          "B2-3 bcal r(fn): create posts the BARE name, describe and dir post `./NAME.stbcal' "
          "-- describe/dir posted the ABSOLUTE machine path before this fix, got `" + createFn +
              "' / `" + descFn + "' / `" + dirFn + "'");
    // `: display %fmt v' (the extended macro function) is not a surface this
    // build has, so the pin is taken off the `display' block itself.
    auto dispOf = [&](const std::string& spec, const std::string& val) {
      auto blocks = piet::dispatch("display \"[\" " + spec + " " + val + " \"]\"", s);
      std::string text;
      if (blocks.is_array()) {
        for (const auto& b : blocks)
          if (b.is_object() && b.value("type", std::string()) == "display")
            text = b.value("text", std::string());
      } else if (blocks.is_object() && blocks.value("type", std::string()) == "display") {
        text = blocks.value("text", std::string());
      }
      return text;
    };
    check(dispOf("%tba_wk", "3") == "[04jan2020]" && dispOf("%tba_wk", "-1") == "[       -1]" &&
              dispOf("%tba_wk", "99") == "[       99]" && dispOf("%tba_wk", ".") == "[        .]",
          "B2-3 %tb display: an out-of-range index and a missing fall back to the raw number "
          "RIGHT-ALIGNED in width 9, not flush left (cap4.log Fneg/F99/Fmiss)");
    check(dispOf("%tbnosuchcl", "3") == "[        3]" &&
              dispOf("%tbnosuchcl", "-1") == "[       -1]",
          "B2-3 %tb display: the unloadable-calendar fallback is padded too (cap4.log "
          "Fnocal/Fnocalneg) -- the width is the same 9 whether the calendar is missing or the "
          "index is");
  }

  fs::remove_all(workdir, ec);
}

void testAerB2Oaxaca() {
  std::printf("[selftest] --- AER scope-2 bundle B2: oaxaca ---\n");
  namespace fs = std::filesystem;
  std::string workdir = (fs::temp_directory_path() / "piet_native_selftest_aerb2ox").u8string();
  std::error_code ec;
  fs::remove_all(workdir, ec);
  fs::create_directories(workdir, ec);
  auto close = [](double a, double b, double rtol) {
    return std::fabs(a - b) <= rtol * std::max(1.0, std::fabs(b));
  };
  auto anyError = [](const nlohmann::ordered_json& blocks) {
    for (const auto& b : blocks)
      if (b.is_object() && b.value("type", std::string()) == "error") return true;
    return false;
  };
  auto firstError = [](const nlohmann::ordered_json& blocks) -> nlohmann::ordered_json {
    for (const auto& b : blocks)
      if (b.is_object() && b.value("type", std::string()) == "error") return b;
    return nlohmann::ordered_json::object();
  };
  piet::SessionState s(workdir);
  s.eval.cwd = workdir;
  s.cwd = workdir;
  // tests/validate/b2_oracle.do's fixture, verbatim: 200 rows, no RNG.
  (void)piet::doexec::executeDoSource(
      "clear\nset obs 200\n"
      "gen double x1 = mod(_n * 7, 23) / 23\n"
      "gen double x2 = mod(_n * 13, 17) / 17\n"
      "gen byte   g  = mod(_n, 2)\n"
      "gen byte   t  = mod(floor((_n - 1) / 3), 2)\n"
      "gen double y  = 1 + 2*x1 - 0.5*x2 + 0.3*g + 0.25*t + mod(_n * 11, 31)/31 - 0.5\n",
      s, piet::dispatch);
  auto scalarOf = [&](const std::string& expr) {
    (void)piet::dispatch("scalar ox_tmp = " + expr, s);
    const std::string v = s.eval.scalars.get("ox_tmp", "");
    (void)piet::dispatch("scalar drop ox_tmp", s);
    try {
      return v.empty() || v == "." ? std::nan("") : std::stod(v);
    } catch (const std::exception&) {
      return std::nan("");  // an unparsable store value is a FAIL below, never an abort
    }
  };
  auto reasonOf = [&](const nlohmann::ordered_json& blocks) {
    return firstError(blocks).value("reason", std::string());
  };

  {
    auto out = piet::dispatch("oaxaca y x1 x2, by(g) pooled relax", s);
    check(!anyError(out), "B2 oaxaca: the corpus form (pooled relax) runs against the engine");
    const double* N = s.eval.eScalars.find("N");
    const double* N1 = s.eval.eScalars.find("N_1");
    const double* N2 = s.eval.eScalars.find("N_2");
    check(N != nullptr && *N == 200 && N1 != nullptr && *N1 == 100 && N2 != nullptr && *N2 == 100,
          "B2 oaxaca: e(N)=200, e(N_1)=e(N_2)=100 (oracle ox_N/ox_N_1/ox_N_2)");
    check(s.eval.eStrings.get("cmd", "") == "oaxaca" && s.eval.eStrings.get("model", "") == "linear",
          "B2 oaxaca: e(cmd)=oaxaca, e(model)=linear (oracle ox_cmd/ox_model)");
    // BUG-456 (2026-09-08): the e-STRING on every expression surface, driven
    // through doString (the BUG-382 lesson: dispatch() shortcuts the real
    // substitution path). Stata truth: capture.log L1/L6/S1/G1/G9/G10/I1/A1/A6/
    // A10/D1/D7 on the regress twin, and the corpus lines of probe_b2.do on
    // oaxaca itself. Every leg here was RED on the pre-fix binary: the store
    // held `oaxaca` (the check just above passed) while `local c = e(cmd)`
    // answered `.`, `if e(cmd)=="oaxaca" {` took the else branch, and every
    // assert/gen/count stopped with "function e() is not supported".
    {
      auto runDo = [&](const std::string& src) {
        nlohmann::json body{{"source", src}};
        auto r = piet::routes::doString(s, body.dump());
        return nlohmann::json::parse(r.json);
      };
      auto firstReason = [](const nlohmann::json& j) -> std::string {
        for (const auto& b : j.value("blocks", nlohmann::json::array()))
          if (b.value("type", std::string()) == "error") return b.value("reason", std::string("<no-reason>"));
        return "";
      };
      (void)runDo("local c = e(cmd)\nlocal eq = (e(cmd)==\"oaxaca\")\nscalar s2 = (e(cmd)==\"oaxaca\")\n"
                  "local hit 0\nif e(cmd)==\"oaxaca\" {\n  local hit 1\n}\n");
      check(s.eval.locals.get("c", "<unset>") == "oaxaca", "BUG-456: `local c = e(cmd)` is `oaxaca` (Stata L1), not `.`");
      check(s.eval.locals.get("eq", "<unset>") == "1", "BUG-456: `local eq = (e(cmd)==\"oaxaca\")` is 1 (Stata L6)");
      check(s.eval.scalars.get("s2", "<unset>") == "1", "BUG-456: `scalar s2 = (e(cmd)==\"oaxaca\")` is 1 (Stata S1)");
      check(s.eval.locals.get("hit", "0") == "1", "BUG-456: `if e(cmd)==\"oaxaca\" { }` takes the branch (Stata I1)");
      check(firstReason(runDo("assert e(cmd) == \"oaxaca\"\nassert _se[overall:group_1] > 0\n")).empty(),
            "BUG-456: the two probe_b2.do corpus asserts pass (Stata rc 0 / rc 0)");
      check(firstReason(runDo("assert e(cmd) == \"nope\"\n")) == "r(9)",
            "BUG-456: `assert e(cmd) == \"nope\"` is a real r(9), the claim was evaluated (Stata A6)");
      check(firstReason(runDo("assert e(cmd) == 1\n")) == "r(109)",
            "BUG-456: `assert e(cmd) == 1` is r(109) type mismatch, never a folded 0 (Stata A10)");
      {
        auto j = runDo("gen byte z456 = (e(cmd)==\"oaxaca\")\nsummarize z456\n");
        double mean = -1;
        for (const auto& b : j.value("blocks", nlohmann::json::array()))
          if (b.value("type", std::string()) == "summarize" && b.contains("stats") && b["stats"].contains("z456"))
            mean = b["stats"]["z456"].value("mean", -1.0);
        check(mean == 1.0, "BUG-456: `gen z = (e(cmd)==\"oaxaca\")` is all ones (Stata G1 mean 1)");
        (void)runDo("count if e(cmd)==\"nope\"\n");
        const double* n0 = s.eval.rValues.find("N");
        check(n0 != nullptr && *n0 == 0.0, "BUG-456: `count if e(cmd)==\"nope\"` is 0 (Stata G10)");
        (void)runDo("count if e(cmd)==\"oaxaca\"\n");
        const double* n1 = s.eval.rValues.find("N");
        check(n1 != nullptr && *n1 == 200.0, "BUG-456: `count if e(cmd)==\"oaxaca\"` is every row (Stata G9)");
        check(firstReason(runDo("count if e(cmd) == 1\n")) == "r(109)",
              "BUG-456: `count if e(cmd) == 1` is r(109) on the row plane too (refute3 M1), not 0");
      }
      {
        // The display twin: the dual-layer discriminator -- `display e(cmd)`
        // and `local c = e(cmd)` must agree ([[two-evaluator-layers-predicate-split]]).
        auto j = runDo("display e(cmd)\ndisplay length(e(cmd))\n");
        std::vector<std::string> shown;
        for (const auto& b : j.value("blocks", nlohmann::json::array()))
          if (b.value("type", std::string()) == "display") shown.push_back(b.value("text", std::string()));
        check(shown.size() == 2 && shown[0] == "oaxaca" && shown[1] == "6",
              "BUG-456: `display e(cmd)` prints oaxaca and `display length(e(cmd))` prints 6 (was `.` and 22 -- the missing sentinel's strlen)");
      }
    }
    check(s.eval.eStrings.get("vce", "") == "robust" && s.eval.eStrings.get("suest", "") == "suest",
          "B2 oaxaca: e(vce)=robust and e(suest)=suest -- `pooled` IMPLIES robust suest, "
          "the fact the first pass never read");
    const piet::eval::EvalMatrix* b = s.eval.findClassMatrix('e', "b");
    const piet::eval::EvalMatrix* V = s.eval.findClassMatrix('e', "V");
    check(b != nullptr && b->data.size() == 1 && b->data[0].size() == 10,
          "B2 oaxaca: e(b) is 1 x 10 (twofold: 5 overall + 2 explained + 3 unexplained)");
    check(V != nullptr && V->data.size() == 10 && V->data[0].size() == 10, "B2 oaxaca: e(V) is 10 x 10");
    static const char* kNames[] = {"overall:group_1", "overall:group_2", "overall:difference",
                                   "overall:explained", "overall:unexplained", "explained:x1",
                                   "explained:x2", "unexplained:x1", "unexplained:x2",
                                   "unexplained:_cons"};
    bool namesOk = b != nullptr && b->colnames.size() == 10;
    for (int j = 0; namesOk && j < 10; ++j) namesOk = b->colnames[static_cast<size_t>(j)] == kNames[j];
    check(namesOk, "B2 oaxaca: e(b) column names are Stata's eq:name spellings in Stata's order "
                   "(ox_coleq x ox_colnames)");
    // %21x pins (b2_oracle.json ox_*/oxse_*), decimal here for legibility.
    check(close(scalarOf("_b[overall:group_1]"), 1.8743234881610429, 1e-9),
          "B2 oaxaca: _b[overall:group_1] == 1.87432348816104 (ox_1)");
    check(close(scalarOf("_b[overall:difference]"), -0.22631857932513788, 1e-9),
          "B2 oaxaca: _b[overall:difference] == -0.226318579325138 (ox_3)");
    check(close(scalarOf("_b[explained:x1]"), -0.011416864937049324, 1e-9),
          "B2 oaxaca: _b[explained:x1] == -0.0114168649370493 (ox_6)");
    check(close(scalarOf("_b[unexplained:_cons]"), -0.1438085260555051, 1e-9),
          "B2 oaxaca: _b[unexplained:_cons] == -0.143808526055505 (ox_10)");
    check(close(scalarOf("_se[overall:group_1]"), 0.06460215610069572, 1e-9),
          "B2 oaxaca: _se[overall:group_1] == 0.0646021561006957 (oxse_1) -- the number five "
          "guessed formulas missed by 5.5e-4 .. 4.5e-3");
    check(close(scalarOf("_se[overall:difference]"), 0.09456790593139917, 1e-9),
          "B2 oaxaca: _se[overall:difference] == 0.0945679059313992 (oxse_3)");
    check(close(scalarOf("_se[explained:x2]"), 0.014662373922876901, 1e-9),
          "B2 oaxaca: _se[explained:x2] == 0.0146623739228769 (oxse_7)");
    check(close(scalarOf("_se[unexplained:_cons]"), 0.10626846783547478, 1e-9),
          "B2 oaxaca: _se[unexplained:_cons] == 0.106268467835475 (oxse_10)");
    if (b != nullptr && b->data[0].size() == 10) {
      const auto& r = b->data[0];
      check(close(r[2], r[0] - r[1], 1e-12) && close(r[2], r[3] + r[4], 1e-12),
            "B2 oaxaca: difference == group_1 - group_2 == explained + unexplained (identity)");
    }
  }
  {
    // The threefold DEFAULT is a different table; a named refusal, never the
    // twofold numbers under a different name.
    auto out = piet::dispatch("oaxaca y x1 x2, by(g)", s);
    check(reasonOf(out) == "refused:oaxaca_threefold_default",
          "B2 oaxaca: without `pooled` the refusal names the threefold default -- got `" +
              reasonOf(out) + "`");
    auto out2 = piet::dispatch("oaxaca y x1 x2, by(g) pooled swap", s);
    check(firstError(out2).value("code", std::string()) == "unsupported_option",
          "B2 oaxaca: `swap` is a real option this build does not implement -> option-refuse");
    auto out3 = piet::dispatch("oaxaca y x1 x2, pooled", s);
    check(reasonOf(out3) == "r(198)", "B2 oaxaca: by() is required, r(198) -- got `" + reasonOf(out3) + "`");
  }
  {
    // relax: a duplicate regressor is r(499) without it (edges.log RC 499) and
    // a ZERO (not missing) coefficient with it; overall:* is unchanged because
    // the group means do not depend on the design.
    (void)piet::dispatch("gen double dup = 2*x1", s);
    auto out = piet::dispatch("oaxaca y x1 x2 dup, by(g) pooled", s);
    check(reasonOf(out) == "r(499)",
          "B2 oaxaca: dropped coefficient without relax is r(499) -- got `" + reasonOf(out) + "`");
    auto out2 = piet::dispatch("oaxaca y x1 x2 dup, by(g) pooled relax", s);
    check(!anyError(out2), "B2 oaxaca: relax runs with the duplicate present");
    check(scalarOf("_b[explained:x1]") == 0.0 && scalarOf("_se[explained:x1]") == 0.0,
          "B2 oaxaca: relax drops the FIRST duplicate (x1) to 0 with SE 0 -- Stata keeps the "
          "later one (rank_oracle.txt CASE 13), the opposite of regress");
    check(close(scalarOf("_b[overall:group_1]"), 1.8743234881610429, 1e-9),
          "B2 oaxaca: overall:group_1 is invariant to the design (means only)");
  }
  {
    // The corpus writes a RANGE (`sch2-sch531`) inside the estimation varlist.
    (void)piet::dispatch("gen byte sch2 = mod(_n, 4) == 0", s);
    (void)piet::dispatch("gen byte sch3 = mod(_n, 4) == 1", s);
    auto out = piet::dispatch("oaxaca y x1 sch2-sch3, by(g) pooled relax noisily", s);
    check(!anyError(out), "B2 oaxaca: `x1 sch2-sch3` (a varlist range, the paper-034 shape) runs");
    const piet::eval::EvalMatrix* b = s.eval.findClassMatrix('e', "b");
    check(b != nullptr && b->colnames.size() == 12 && b->colnames[7] == "explained:sch3",
          "B2 oaxaca: the range expanded to sch2 sch3 (12 columns, explained:sch3 present)");
    bool note = false;
    for (const auto& blk : out)
      if (blk.value("type", std::string()) == "display" &&
          blk.value("text", std::string()).find("noisily") != std::string::npos)
        note = true;
    check(note, "B2 oaxaca: `noisily` is an accept-NOTE, never a silent no-op");
  }
  {
    auto out = piet::dispatch("oaxaca y x1 x2 if _n <= 150, by(g) pooled relax", s);
    check(!anyError(out), "B2 oaxaca: an if qualifier runs");
    const double* N = s.eval.eScalars.find("N");
    check(N != nullptr && *N == 150, "B2 oaxaca: e(N) == 150 under `if _n <= 150` (the qualifier reached the engine)");
  }
  {
    (void)piet::dispatch("gen byte g3 = mod(_n, 3)", s);
    auto out = piet::dispatch("oaxaca y x1 x2, by(g3) pooled relax", s);
    check(anyError(out) && reasonOf(out) == "r(420)",
          "B2 oaxaca: three groups is an error, r(420) as Stata answers -- got `" + reasonOf(out) + "`");
  }
  fs::remove_all(workdir, ec);
}

void testAerB2Nnmatch() {
  std::printf("[selftest] --- AER scope-2 bundle B2-4: teffects nnmatch ---\n");
  namespace fs = std::filesystem;
  std::string workdir = (fs::temp_directory_path() / "piet_native_selftest_aerb2nn").u8string();
  std::error_code ec;
  fs::remove_all(workdir, ec);
  fs::create_directories(workdir, ec);
  auto close = [](double a, double b, double rtol) {
    return std::fabs(a - b) <= rtol * std::max(1.0, std::fabs(b));
  };
  auto anyError = [](const nlohmann::ordered_json& blocks) {
    for (const auto& b : blocks)
      if (b.is_object() && b.value("type", std::string()) == "error") return true;
    return false;
  };
  auto firstError = [](const nlohmann::ordered_json& blocks) -> nlohmann::ordered_json {
    for (const auto& b : blocks)
      if (b.is_object() && b.value("type", std::string()) == "error") return b;
    return nlohmann::ordered_json::object();
  };
  auto reasonOf = [&](const nlohmann::ordered_json& blocks) {
    return firstError(blocks).value("reason", std::string());
  };
  piet::SessionState s(workdir);
  s.eval.cwd = workdir;
  s.cwd = workdir;
  auto scalarOf = [&](const std::string& expr) {
    (void)piet::dispatch("scalar nn_tmp = " + expr, s);
    const std::string v = s.eval.scalars.get("nn_tmp", "");
    (void)piet::dispatch("scalar drop nn_tmp", s);
    try {
      return v.empty() || v == "." ? std::nan("") : std::stod(v);
    } catch (const std::exception&) {
      return std::nan("");
    }
  };
  // `mm1[1]` is a SUBSCRIPTED reference, which this build resolves on `display`
  // but not inside a scalar/assert expression (a pre-existing limitation the
  // bcal probe hit too). `summarize v in i/i, meanonly` is the idiom that reads
  // one cell through a surface that works.
  auto cellOf = [&](const std::string& var, int row) {
    (void)piet::dispatch("summarize " + var + " in " + std::to_string(row) + "/" +
                             std::to_string(row) + ", meanonly",
                         s);
    const double* v = s.eval.rValues.find("min");
    return v != nullptr ? *v : std::nan("");
  };
  auto countIf = [&](const std::string& cond) {
    (void)piet::dispatch("count if " + cond, s);
    const double* v = s.eval.rValues.find("N");
    return v != nullptr ? *v : std::nan("");
  };

  // tests/validate/b2_oracle.do's fixture, verbatim -- the same 200 rows whose
  // te_* keys the B2 answer key already carried, and REPORT.md's fixture F1.
  (void)piet::doexec::executeDoSource(
      "clear\nset obs 200\n"
      "gen double x1 = mod(_n * 7, 23) / 23\n"
      "gen double x2 = mod(_n * 13, 17) / 17\n"
      "gen byte   g  = mod(_n, 2)\n"
      "gen byte   t  = mod(floor((_n - 1) / 3), 2)\n"
      "gen double y  = 1 + 2*x1 - 0.5*x2 + 0.3*g + 0.25*t + mod(_n * 11, 31)/31 - 0.5\n",
      s, piet::dispatch);
  {
    auto out = piet::dispatch("teffects nnmatch (y x1 x2) (t), gen(mm)", s);
    check(!anyError(out), "B2-4 nnmatch: the corpus form runs against the engine");
    const double* N = s.eval.eScalars.find("N");
    const double* n0 = s.eval.eScalars.find("n0");
    const double* n1 = s.eval.eScalars.find("n1");
    check(N != nullptr && *N == 200 && n0 != nullptr && *n0 == 101 && n1 != nullptr && *n1 == 99,
          "B2-4 nnmatch: e(N)=200 e(n0)=101 e(n1)=99 (oracle te_N + capture.log F1)");
    check(s.eval.eStrings.get("cmd", "") == "teffects" &&
              s.eval.eStrings.get("subcmd", "") == "nnmatch",
          "B2-4 nnmatch: e(cmd)=teffects and e(subcmd)=nnmatch -- the ENGINE verb is `nnmatch', "
          "and publishing that as e(cmd) would be a wrong answer to `if e(cmd)==\"teffects\"'");
    check(s.eval.eStrings.get("vce", "") == "robust" &&
              s.eval.eStrings.get("vcetype", "") == "AI robust" &&
              s.eval.eStrings.get("stat", "") == "ate" &&
              s.eval.eStrings.get("metric", "") == "mahalanobis",
          "B2-4 nnmatch: e(vce)=robust e(vcetype)=`AI robust' e(stat)=ate e(metric)=mahalanobis "
          "(INFO|nn| lines of aer_estim2_oracle.log)");
    check(s.eval.eStrings.get("title", "") == "Treatment-effects estimation" &&
              s.eval.eStrings.get("tvar", "") == "t" &&
              s.eval.eStrings.get("depvar", "") == "y",
          "B2-4 nnmatch: e(title)/e(tvar)/e(depvar)");
    // b2_oracle.json te_ate__hex +1.a3491f36cbd54X-006 / te_se__hex.
    check(close(scalarOf("_b[ATE:r1vs0.t]"), 0.025591164095371689, 1e-9),
          "B2-4 nnmatch: _b[ATE:r1vs0.t] == 0.0255911640953717 (te_ate__hex) -- and the "
          "reference RESOLVES: the `.' in the eq:name is what `_b[' used to choke on");
    check(close(scalarOf("_se[ATE:r1vs0.t]"), 0.058322183303489719, 1e-9),
          "B2-4 nnmatch: _se[ATE:r1vs0.t] == 0.0583221833034897 (te_se__hex)");
    const piet::eval::EvalMatrix* b = s.eval.findClassMatrix('e', "b");
    const piet::eval::EvalMatrix* V = s.eval.findClassMatrix('e', "V");
    check(b != nullptr && b->data.size() == 1 && b->data[0].size() == 1 &&
              b->colnames.size() == 1 && b->colnames[0] == "ATE:r1vs0.t" &&
              b->rownames.size() == 1 && b->rownames[0] == "y1",
          "B2-4 nnmatch: e(b) is 1x1, colname `ATE:r1vs0.t', rowname `y1' (te_bcolnames)");
    check(V != nullptr && V->data.size() == 1 && V->data[0].size() == 1 &&
              close(V->data[0][0], 0.0034014770652858553, 1e-9),
          "B2-4 nnmatch: e(V) is 1x1 and equals te_v11__hex (+1.bdd6a181ca555X-009)");
    const double* kmin = s.eval.eScalars.find("k_nnmin");
    const double* kmax = s.eval.eScalars.find("k_nnmax");
    const double* krob = s.eval.eScalars.find("k_robust");
    const double* dtol = s.eval.eScalars.find("dtolerance");
    check(kmin != nullptr && *kmin == 1 && kmax != nullptr && *kmax == 2 && krob != nullptr &&
              *krob == 2,
          "B2-4 nnmatch: e(k_nnmin)=1 e(k_nnmax)=2 e(k_robust)=2 (the default is TWO matches for "
          "the conditional variance, causal.pdf p.637)");
    check(dtol != nullptr && close(*dtol, 1.4901161193847656e-8, 1e-15),
          "B2-4 nnmatch: e(dtolerance) == sqrt(c(epsdouble)) (+1.fffffffff8f7aX-01b)");
    check(s.eval.eStrings.get("indexvar", "") == "mm1 mm2",
          "B2-4 nnmatch: gen(mm) minted TWO columns and e(indexvar) names them (te_mm_list)");
    check(cellOf("mm1", 1) == 90 && cellOf("mm1", 2) == 130 && cellOf("mm1", 5) == 133 &&
              cellOf("mm1", 200) == 124,
          "B2-4 nnmatch: mm1[1]=90 mm1[2]=130 mm1[5]=133 mm1[200]=124 (te_mm1_* oracle keys) -- "
          "these ids, not the estimate, are what paper 076 consumes");
    check(cellOf("mm1", 104) == 130 && cellOf("mm2", 104) == 78,
          "B2-4 nnmatch: row 104's NONZERO-distance tie is listed DESCENDING (130 then 78). "
          "Always-ascending and first-member-only are both falsified arms (REPORT.md §5); the "
          "REFUTED anchored-group rule would also put a different id first here");
    check(countIf("!missing(mm1)") == 200,
          "B2-4 nnmatch: every row of the estimation sample got an id");
  }
  {
    // gen() refuses BEFORE it estimates, exactly as Stata does (r(110),
    // INFO|nn_edge|gen_collision_rc).
    auto out = piet::dispatch("teffects nnmatch (y x1 x2) (t), gen(mm)", s);
    check(reasonOf(out) == "r(110)",
          "B2-4 nnmatch: a gen() stub whose columns already exist is r(110) `variable mm1 "
          "already defined' -- got `" + reasonOf(out) + "`");
    auto o2 = piet::dispatch("teffects nnmatch (y x1 x2) (t), vce(robust, nn(1))", s);
    check(reasonOf(o2) == "r(198)",
          "B2-4 nnmatch: vce(robust, nn(1)) is r(198) -- Stata's nn(#) floor is 2 (probe.log:189) "
          "-- got `" + reasonOf(o2) + "`");
    auto o3 = piet::dispatch("teffects nnmatch (y x1 x2) (t), nneighbor(500)", s);
    check(reasonOf(o3) == "r(198)",
          "B2-4 nnmatch: nneighbor(#) above the smallest group is r(198) (ParseNNeighbor) -- got `" +
              reasonOf(o3) + "`");
    auto o4 = piet::dispatch("teffects nnmatch (y x1 x2) (t), biasadj(x1 x2)", s);
    check(firstError(o4).value("code", std::string()) == "unsupported_option",
          "B2-4 nnmatch: biasadj() is a real Stata option this build does not implement -> "
          "option-refuse, never a silent default-OFF answer under a name the user typed");
    auto o5 = piet::dispatch("teffects nnmatch (y x1 x2) (t), vce(iid)", s);
    check(reasonOf(o5) == "refused:teffects_nnmatch_vce_iid",
          "B2-4 nnmatch: vce(iid) is a DIFFERENT variance (captured once for the record, never "
          "verified) and is refused BY NAME -- got `" + reasonOf(o5) + "`");
    auto o6 = piet::dispatch("teffects nnmatch (y x1 x2) (t), metric(matrix M)", s);
    check(reasonOf(o6) == "refused:teffects_nnmatch_metric_matrix",
          "B2-4 nnmatch: metric(matrix ...) is refused by name -- got `" + reasonOf(o6) + "`");
    auto o7 = piet::dispatch("teffects nnmatch (y i.x1#i.x2) (t)", s);
    check(reasonOf(o7) == "refused:teffects_nnmatch_interaction_terms",
          "B2-4 nnmatch: an interaction term is refused by name (no fixture ever expanded one) "
          "-- got `" + reasonOf(o7) + "`");
    auto o8 = piet::dispatch("teffects nnmatch (y L.x1) (t)", s);
    check(reasonOf(o8) == "refused:teffects_nnmatch_fv_operator",
          "B2-4 nnmatch: a time-series/base-level operator is refused by name -- got `" +
              reasonOf(o8) + "`");
    auto o9 = piet::dispatch("teffects nnmatch (y x1 x2) (t), ate atet", s);
    check(firstError(o9).value("code", std::string()) == "syntax_error",
          "B2-4 nnmatch: `ate atet' together is a syntax error (r(198) class), not a silent "
          "last-one-wins");
    (void)piet::dispatch("gen byte t3 = mod(_n, 3)", s);
    auto o10 = piet::dispatch("teffects nnmatch (y x1 x2) (t3)", s);
    check(reasonOf(o10) == "r(198)",
          "B2-4 nnmatch: a three-level treatment is r(198) in this build (control()/tlevel() were "
          "never measured) -- got `" + reasonOf(o10) + "`");
    // vce(robust, nn(#)) AT the smallest group (n1 == 99 here) is NOT a parse
    // error -- Stata accepts it and then dies at runtime, because Psi(i) draws
    // from the 98 OTHER treated rows. Measured on this exact fixture, StataBE
    // 2026-09-09: nn(99) -> r(459) "fewer than 99 nearest-neighbor matches for
    // observation 4 ..."; nn(100)/nn(101) -> r(198) (ParseVCE). Before this
    // check the engine truncated h silently and answered rc 0 with SE
    // .1046884 -- a wrong number under a number the user typed.
    auto o11 = piet::dispatch("teffects nnmatch (y x1 x2) (t), vce(robust, nn(99))", s);
    check(reasonOf(o11) == "r(459)",
          "B2-4 nnmatch: vce(robust, nn(#)) AT the smallest group is Stata's RUNTIME r(459), not "
          "a silently truncated h -- got `" + reasonOf(o11) + "`");
    check(firstError(o11).value("message", std::string()).find(
              "fewer than 99 nearest-neighbor matches for observation 4") != std::string::npos,
          "B2-4 nnmatch: ... carrying Stata's own per-observation text (it names the first "
          "deficient FRAME row, _n 4 -- the first treated row of this fixture)");
    auto o12 = piet::dispatch("teffects nnmatch (y x1 x2) (t), vce(robust, nn(100))", s);
    check(reasonOf(o12) == "r(198)",
          "B2-4 nnmatch: one ABOVE the smallest group is still ParseVCE's r(198) -- the two sides "
          "of the bound carry different rc -- got `" + reasonOf(o12) + "`");
  }
  {
    // The LEGAL boundary, h == nmin - 1: the arm that proves the r(459) above
    // refuses only what Stata refuses. StataBE 2026-09-09 on this fixture:
    // e(k_robust) 98, sqrt(e(V)) 1.04580722228670e-01.
    auto out = piet::dispatch("teffects nnmatch (y x1 x2) (t), vce(robust, nn(98))", s);
    check(!anyError(out), "B2-4 nnmatch: vce(robust, nn(nmin-1)) RUNS (the bound is off-by-one "
                          "tight, not one too wide)");
    const double* krob = s.eval.eScalars.find("k_robust");
    check(krob != nullptr && *krob == 98, "B2-4 nnmatch: nn(98) sets e(k_robust)=98");
    check(close(scalarOf("_se[ATE:r1vs0.t]"), 0.104580722228670, 1e-9),
          "B2-4 nnmatch: nn(98) SE == 0.104580722228670 (StataBE oracle) -- the largest h Stata "
          "accepts, and it is parity-clean");
  }
  {
    // The gen() collision rule as MEASURED, not as assumed (StataBE 19.5,
    // 2026-09-09, this fixture: default nneighbor(1), k_nnmax 2). Stata does NOT
    // scan the whole stub* family before estimating -- it refuses on the stubs
    // it can name (stub1..stub(nneighbor)) with one text, and on the ones only
    // the fitted K reveals with another. The middle leg is the one that was
    // WRONG before this pass: mm3 present with K == 2 runs in Stata.
    (void)piet::dispatch("drop mm1 mm2", s);
    (void)piet::dispatch("gen double mm3 = 1", s);
    auto g1 = piet::dispatch("teffects nnmatch (y x1 x2) (t), gen(mm)", s);
    check(!anyError(g1),
          "B2-4 nnmatch: gen(mm) with only mm3 present and k_nnmax 2 RUNS -- Stata rc 0, mm1/mm2 "
          "created, mm3 untouched (the 1..64 pre-scan used to refuse this)");
    (void)piet::dispatch("drop mm1 mm2", s);
    auto g2 = piet::dispatch("teffects nnmatch (y x1 x2) (t), nneighbor(3) gen(mm)", s);
    check(reasonOf(g2) == "r(110)" &&
              firstError(g2).value("message", std::string()).find("variable mm3 already defined") !=
                  std::string::npos,
          "B2-4 nnmatch: the SAME mm3 with nneighbor(3) IS r(110) `variable mm3 already defined' "
          "-- three stubs are guaranteed before a single distance is computed -- got `" +
              reasonOf(g2) + "`");
    (void)piet::dispatch("drop mm3", s);
    (void)piet::dispatch("gen double mm2 = 1", s);
    auto g3 = piet::dispatch("teffects nnmatch (y x1 x2) (t), gen(mm)", s);
    check(reasonOf(g3) == "r(110)" &&
              firstError(g3).value("message", std::string())
                      .find("maximum number of nearest neighbors is 2, but variable mm2 already "
                            "exists") != std::string::npos,
          "B2-4 nnmatch: a stub only the fitted K names carries Stata's OTHER text -- got `" +
              firstError(g3).value("message", std::string()) + "`");
    auto probe = piet::dispatch("display mm1[1]", s);
    check(anyError(probe),
          "B2-4 nnmatch: ... and it refuses BEFORE minting mm1, so a collision at stub2 leaves no "
          "half-written stub family behind");
    (void)piet::dispatch("drop mm2", s);
  }
  {
    // A REPEATED matching variable is a collinear design, not a syntax error.
    // The first landing refused `(y x1 x1)` with an invented r(198) "duplicate
    // matching variable x1"; StataBE 19.5 (2026-09-09, this fixture) answers
    // `note: x1 omitted because of collinearity.` with ATE 1.47459772296015e-01,
    // SE 5.11611461378533e-02, e(k_nnmin) 3, e(k_nnmax) 6 -- and the kernel's
    // own _rmcoll sweep reproduces every one of those to the last digit once the
    // CLI stops preempting it.
    auto out = piet::dispatch("teffects nnmatch (y x1 x1) (t)", s);
    check(!anyError(out),
          "B2-4 nnmatch: a repeated matching variable RUNS -- got `" + reasonOf(out) + "`");
    bool note = false;
    for (const auto& blk : out)
      if (blk.value("type", std::string()) == "display" &&
          blk.value("text", std::string()).find("collinear") != std::string::npos)
        note = true;
    check(note, "B2-4 nnmatch: ... and the repeat is NAMED as omitted for collinearity");
    check(close(scalarOf("_b[ATE:r1vs0.t]"), 0.147459772296015, 1e-9) &&
              close(scalarOf("_se[ATE:r1vs0.t]"), 0.0511611461378533, 1e-9),
          "B2-4 nnmatch: `(y x1 x1)' ATE/SE == 0.147459772296015 / 0.0511611461378533 (StataBE "
          "oracle) -- matching on x1 alone, which is what dropping the repeat means");
    const double* kmin = s.eval.eScalars.find("k_nnmin");
    const double* kmax = s.eval.eScalars.find("k_nnmax");
    check(kmin != nullptr && *kmin == 3 && kmax != nullptr && *kmax == 6,
          "B2-4 nnmatch: ... e(k_nnmin)=3 e(k_nnmax)=6 -- one covariate ties far more widely than "
          "two, so the tie WIDTH is the discriminating leg here");
  }
  {
    // vce(robust, nn(3)) changes h, and the SE with it: the DOC arm captured on
    // this very fixture (oracle.txt `DOC F1 vce(robust,nn(3))`, SE
    // +1.fef018e6e2ca4X-005), reproduced by the verified rule with h=3.
    auto out = piet::dispatch("teffects nnmatch (y x1 x2) (t), vce(robust, nn(3))", s);
    check(!anyError(out), "B2-4 nnmatch: vce(robust, nn(3)) runs");
    const double* krob = s.eval.eScalars.find("k_robust");
    check(krob != nullptr && *krob == 3, "B2-4 nnmatch: vce(robust, nn(3)) sets e(k_robust)=3");
    check(close(scalarOf("_se[ATE:r1vs0.t]"), 0.06237034667636834, 1e-9),
          "B2-4 nnmatch: nn(3) SE == 0.0623703466763683 (DOC F1 vce(robust,nn(3)) "
          "+1.fef018e6e2ca4X-005) -- the conditional-variance neighbour count is REAL, not "
          "decorative");
  }
  {
    // `if`: the sample shrinks but the ids stay _n of the FULL frame. MEASURED
    // on an ODD-ROWS-only subsample (INFO|nn_edge|ifodd_*): Stata answers 47 and
    // 131, both odd, and ZERO even ids -- so a handler that renumbered to the
    // kept subsample would pair paper 076 with the wrong people at rc 0.
    auto out = piet::dispatch("teffects nnmatch (y x1 x2) (t) if mod(_n,2)==1, gen(ifm)", s);
    check(!anyError(out), "B2-4 nnmatch: an `if' qualifier runs");
    const double* N = s.eval.eScalars.find("N");
    check(N != nullptr && *N == 100, "B2-4 nnmatch: e(N)==100 under `if mod(_n,2)==1'");
    check(cellOf("ifm1", 1) == 47 && cellOf("ifm1", 3) == 131,
          "B2-4 nnmatch: under `if', ifm1[1]=47 and ifm1[3]=131 (INFO|nn_edge|ifodd_mm1_*)");
    check(countIf("!missing(ifm1)") == 100 && countIf("!missing(ifm1) & mod(ifm1,2)==0") == 0,
          "B2-4 nnmatch: exactly the 100 kept rows carry ids and EVERY id is odd -- the ids are "
          "row numbers of the CURRENT data, not of the kept subsample");
  }
  {
    // The production shape of clean_15_matching.do:366 and the consumer's join.
    (void)piet::doexec::executeDoSource(
        "clear\nset obs 600\n"
        "gen byte f1 = mod(_n, 2)\n"
        "gen byte f2 = mod(floor(_n / 3), 3)\n"
        "gen byte f3 = mod(floor(_n / 5), 5)\n"
        "gen byte f4 = mod(floor(_n / 11), 4)\n"
        "gen byte f5 = mod(floor(_n / 13), 2)\n"
        "gen byte f6 = mod(floor(_n / 17), 3)\n"
        "gen byte treatment = (mod(_n, 5) == 0)\n"
        "gen double outcome = 1 + 0.5*f1 + 0.3*f2 - 0.2*f3 + 0.1*f4 - 0.4*f5 + 0.15*f6 + "
        "0.25*treatment + mod(_n * 13, 37)/37\n",
        s, piet::dispatch);
    auto out = piet::dispatch(
        "teffects nnmatch (outcome i.f1 i.f2 i.f3 i.f4 i.f5 i.f6) (treatment), gen(match_id)", s);
    check(!anyError(out), "B2-4 nnmatch: the paper-076 shape (six i. factors + gen()) runs");
    check(close(scalarOf("_b[ATE:r1vs0.treatment]"), 0.22694069069068998, 1e-9),
          "B2-4 nnmatch: production-shape ATE == 0.226940690690690 (+1.d0c647e52f724X-003)");
    const double* kmax = s.eval.eScalars.find("k_nnmax");
    check(kmax != nullptr && *kmax == 3 && s.eval.eStrings.get("indexvar", "") ==
                                               "match_id1 match_id2 match_id3",
          "B2-4 nnmatch: K = e(k_nnmax) = 3 gen columns -- the count comes from the WIDEST tie, "
          "not from nneighbor()");
    check(cellOf("match_id1", 1) == 575 && cellOf("match_id1", 5) == 309 &&
              cellOf("match_id1", 365) == 319 && cellOf("match_id1", 530) == 132 &&
              cellOf("match_id1", 600) == 554,
          "B2-4 nnmatch: match_id1 at rows 1/5/365/530/600 == 575/309/319/132/554. Rows 365 and "
          "530 are EXACT-CELL (distance 0) ties, where the order is ASCENDING observation "
          "number -- the opposite of the nonzero-distance rule, and the whole reason `sort PNR' "
          "matters to the paper");
    check(countIf("treatment==1 & !missing(match_id1)") == 120,
          "B2-4 nnmatch: every one of the 120 treated rows has a match_id1 -- the paper's "
          "`keep if treatment==1 & !missing(match_id1)' then `merge 1:m' is lossless");
  }
  {
    // atet on indicator cells: the CONTROL rows carry ids too, because Omega is
    // built for every row and not only the treated ones.
    (void)piet::doexec::executeDoSource(
        "clear\nset obs 90\n"
        "gen byte a = mod(_n, 2)\n"
        "gen byte b = mod(floor(_n / 2), 3)\n"
        "gen byte c = mod(floor(_n / 5), 5)\n"
        "gen byte t = (mod(_n, 5) != 0)\n"
        "gen double y = 1 + 0.5*a + 0.3*b - 0.2*c + 0.25*t + mod(_n * 11, 31)/31\n",
        s, piet::dispatch);
    auto out = piet::dispatch("teffects nnmatch (y i.a i.b i.c) (t), atet nneighbor(2) gen(am)", s);
    check(!anyError(out), "B2-4 nnmatch: `atet nneighbor(2)' runs");
    check(s.eval.eStrings.get("stat", "") == "atet",
          "B2-4 nnmatch: e(stat)=atet");
    check(close(scalarOf("_b[ATET:r1vs0.t]"), 0.21807795698924731, 1e-9),
          "B2-4 nnmatch: ATET == 0.218077956989247 and the e(b) column is `ATET:r1vs0.t'");
    check(close(scalarOf("_se[ATET:r1vs0.t]"), 0.12234534456996479, 1e-9),
          "B2-4 nnmatch: ATET SE == 0.122345344569965. The manual's TYPESET sigma^2_delta puts "
          "t_i on the whole bracket and is FALSIFIED here; Abadie-Imbens (2006) Thm 7, with the "
          "K-term on the CONTROLS, is what Stata computes");
    check(countIf("t==0 & !missing(am1)") == 18,
          "B2-4 nnmatch: all 18 control rows carry ids under atet (control_rows_filled)");
    check(cellOf("am1", 1) == 25 && cellOf("am1", 5) == 59 && cellOf("am1", 90) == 18,
          "B2-4 nnmatch: atet ids at rows 1/5/90 == 25/59/18");
  }
  {
    // NESTED FACTORS: 1.a == 2.b + 3.b exactly, so _rmcoll must drop a column
    // before the pooled covariance is formed. MEASURED (INFO|nn_rmcoll):
    // e(fvdvarlist) = `0b.a 1.a 0b.b 1.b 2.b 3o.b' -- Stata keeps 1.a and drops
    // the LATER redundant 3.b.
    (void)piet::doexec::executeDoSource(
        "clear\nset obs 120\n"
        "gen byte b = mod(_n, 4)\n"
        "gen byte a = (b >= 2)\n"
        "gen byte t = mod(floor((_n - 1) / 3), 2)\n"
        "gen double y = 1 + 0.5*a + 0.3*b + 0.25*t + mod(_n * 11, 31)/31\n",
        s, piet::dispatch);
    auto out = piet::dispatch("teffects nnmatch (y i.a i.b) (t), gen(rm)", s);
    check(!anyError(out),
          "B2-4 nnmatch: a nested-factor design runs -- without _rmcoll the pooled covariance is "
          "singular and there is no answer at all");
    bool note = false;
    for (const auto& blk : out)
      if (blk.value("type", std::string()) == "display" &&
          blk.value("text", std::string()).find("collinear") != std::string::npos)
        note = true;
    check(note, "B2-4 nnmatch: the dropped column is NAMED in a note, never dropped silently");
    check(close(scalarOf("_b[ATE:r1vs0.t]"), 0.27701612903225808, 1e-9) &&
              close(scalarOf("_se[ATE:r1vs0.t]"), 0.058824155719795081, 1e-9),
          "B2-4 nnmatch: nested-factor ATE/SE == 0.277016129032258 / 0.0588241557197951 "
          "(+1.1baa1dbaa1dbaX-002) -- drop the WRONG column and the metric, hence every id, "
          "moves");
    check(cellOf("rm1", 1) == 5 && cellOf("rm1", 2) == 6 && cellOf("rm1", 120) == 8,
          "B2-4 nnmatch: nested-factor ids at rows 1/2/120 == 5/6/8");
  }
  {
    // ---- B2-4 review pass (2026-09-09) -----------------------------------
    // Five axes NO gate read before: the reported interval, level(#), e(level),
    // e(mvarlist)'s operators, e(tlevels)'s coding, and the data_mutation
    // envelope for gen(). Every pin below is a StataBE 19.5 capture in
    // tests/eval/golden/aer_estim2_oracle.log (ORACLEX|...ci_lo/ci_hi and the
    // INFO|nn_level| block); all six legs are RED on the pre-review binary.
    (void)piet::doexec::executeDoSource(
        "clear\nset obs 200\n"
        "gen double x1 = mod(_n * 7, 23) / 23\n"
        "gen double x2 = mod(_n * 13, 17) / 17\n"
        "gen byte   g  = mod(_n, 2)\n"
        "gen byte   t  = mod(floor((_n - 1) / 3), 2)\n"
        "gen double y  = 1 + 2*x1 - 0.5*x2 + 0.3*g + 0.25*t + mod(_n * 11, 31)/31 - 0.5\n",
        s, piet::dispatch);
    auto ciOf = [](const nlohmann::ordered_json& blocks, const char* field) {
      for (const auto& b : blocks) {
        if (!b.is_object() || b.value("type", std::string()) != "estimation") continue;
        if (!b.contains("coeftable") || !b["coeftable"].is_array() || b["coeftable"].empty())
          continue;
        const auto& row = b["coeftable"][0];
        if (row.contains(field) && row[field].is_number()) return row[field].get<double>();
      }
      return std::nan("");
    };
    auto out = piet::dispatch("teffects nnmatch (y x1 x2) (t)", s);
    check(close(ciOf(out, "ci_lo"), -0.088718214679211385, 1e-9) &&
              close(ciOf(out, "ci_hi"), 0.13990054286995485, 1e-9),
          "B2-4 nnmatch: the DEFAULT interval is Stata's 95% one, [-.0887182, .1399005] "
          "(ORACLEX ci_lo -1.6b63ca69b5201X-004 / ci_hi +1.1e842d028d856X-003). z_critical takes "
          "the WHOLE two-sided tail: passing 0.025 built a 97.5% interval wearing a 95% label");
    check(std::isnan(scalarOf("e(level)")),
          "B2-4 nnmatch: e(level) is NOT posted -- `display e(level)' answers `.' in StataBE "
          "(INFO|nn_level|default_e_level) and the 14-fixture ereturn capture has no such scalar");
    auto o90 = piet::dispatch("teffects nnmatch (y x1 x2) (t), level(90)", s);
    check(close(ciOf(o90, "ci_lo"), -0.070340290643101957, 1e-9) &&
              close(ciOf(o90, "ci_hi"), 0.12152261883384541, 1e-9),
          "B2-4 nnmatch: level(90) MOVES the interval to [-.07034029, .12152262] "
          "(INFO|nn_level|l90_lo/l90_hi) -- a value-carrying reporting option, not an "
          "accept-note");
    check(std::isnan(scalarOf("e(level)")),
          "B2-4 nnmatch: level(90) still posts no e(level) (INFO|nn_level|l90_e_level)");
    auto l9 = piet::dispatch("teffects nnmatch (y x1 x2) (t), level(9)", s);
    auto l101 = piet::dispatch("teffects nnmatch (y x1 x2) (t), level(101)", s);
    auto labc = piet::dispatch("teffects nnmatch (y x1 x2) (t), level(abc)", s);
    auto l9999 = piet::dispatch("teffects nnmatch (y x1 x2) (t), level(99.99)", s);
    check(reasonOf(l9) == "r(198)" && reasonOf(l101) == "r(198)" && reasonOf(labc) == "r(198)" &&
              !anyError(l9999),
          "B2-4 nnmatch: level()'s band is Stata's MEASURED one -- 9/101/abc are r(198) and "
          "99.99 runs (INFO|nn_level|l9_rc l101_rc labc_rc l9999_rc = 198 198 198 0)");
    (void)piet::dispatch("gen byte a = mod(_n, 2)", s);
    (void)piet::dispatch("gen byte b = mod(floor((_n - 1) / 2), 3)", s);
    (void)piet::dispatch("teffects nnmatch (y x1 i.a i.b) (t)", s);
    const std::string mvMixed = s.eval.eStrings.get("mvarlist", "");
    (void)piet::dispatch("teffects nnmatch (y c.x1 i.a) (t)", s);
    const std::string mvCdot = s.eval.eStrings.get("mvarlist", "");
    (void)piet::dispatch("teffects nnmatch (y i.a i.b) (t)", s);
    const std::string mvFac = s.eval.eStrings.get("mvarlist", "");
    check(mvMixed == "x1 a b" && mvCdot == "x1 a" && mvFac == "a b",
          "B2-4 nnmatch: e(mvarlist) is the TYPED order with the operator STRIPPED -- Stata "
          "answers `x1 a b' / `x1 a' / `a b' (INFO|nn_level|mixed_mvarlist, |cdot_mvarlist, "
          "INFO|nn_rmcoll|mvarlist), got `" + mvMixed + "' / `" + mvCdot + "' / `" + mvFac + "'");
    (void)piet::dispatch("gen byte t12 = t + 1", s);
    (void)piet::dispatch("teffects nnmatch (y x1 x2) (t12)", s);
    const std::string tl12 = s.eval.eStrings.get("tlevels", "");
    (void)piet::dispatch("teffects nnmatch (y x1 x2) (t)", s);
    const std::string tl01 = s.eval.eStrings.get("tlevels", "");
    check(tl12 == "1 2" && tl01 == "0 1",
          "B2-4 nnmatch: e(tlevels) FOLLOWS the coding -- `1 2' on a 1/2-coded treatment "
          "(INFO|nn_level|t12_tlevels) and `0 1' on the 0/1 one. The literal `0 1' contradicted "
          "e(treated)=2/e(control)=1 and the colname `ATE:r2vs1.t12' in its own e() set; got `" +
              tl12 + "' / `" + tl01 + "'");
    auto og = piet::dispatch("teffects nnmatch (y x1 x2) (t), gen(revmm)", s);
    bool sawMut = false;
    for (const auto& b : og) {
      if (!b.is_object() || b.value("type", std::string()) != "data_mutation") continue;
      if (!b.contains("varlist_after") || !b["varlist_after"].is_array()) continue;
      bool m1 = false, m2 = false;
      for (const auto& v : b["varlist_after"]) {
        const std::string nm = v.value("name", std::string());
        if (nm == "revmm1") m1 = true;
        if (nm == "revmm2") m2 = true;
      }
      if (m1 && m2) sawMut = true;
    }
    check(sawMut,
          "B2-4 nnmatch: gen() returns the data_mutation envelope naming revmm1/revmm2 -- "
          "mutation_result.h's contract, and the ONLY source routes.cpp has for the /api/command "
          "`varlist_after' the console's Variables pane reads (app.js:1007)");
  }
  {
    // Every OTHER teffects estimator is a different method with its own
    // inference, and each says so under its OWN name -- not the shared
    // `e3_deferred` (which now means "not routed at all") and not a wrong
    // number under a name the user typed.
    static const char* kSubs[] = {"ra", "ipw", "ipwra", "aipw", "psmatch"};
    int named = 0;
    for (const char* sub : kSubs) {
      auto out = piet::dispatch(std::string("teffects ") + sub + " (y a) (t b)", s);
      if (reasonOf(out) == std::string("refused:teffects_") + sub + "_unimplemented") ++named;
    }
    check(named == 5,
          "B2-4 nnmatch: ra/ipw/ipwra/aipw/psmatch each refuse under their OWN name "
          "(`refused:teffects_<sub>_unimplemented') -- got " + std::to_string(named) + "/5");
    auto out = piet::dispatch("teffects", s);
    check(firstError(out).value("code", std::string()) == "syntax_error",
          "B2-4 nnmatch: a bare `teffects' is a syntax error naming the estimators, not a crash");
    auto o2 = piet::dispatch("teffects nnmatch (y a)", s);
    check(firstError(o2).value("code", std::string()) == "syntax_error",
          "B2-4 nnmatch: one parenthesised group is a syntax error");
  }
  fs::remove_all(workdir, ec);
}

void testAerCampaignRatchets() {
  std::printf("[selftest] --- AER scope-1 campaign ratchets (effect table + no-data routes) ---\n");

  // (1) ---------------------------------------------------------------------
  static const std::set<std::string> kEffectTableExempt = {
      "binscatter", "chow", "clonevar", "coefplot", "compress", "corr", "cross",
      "datasignature", "dfuller", "did_imputation", "drdid", "erase", "ereturn",
      "eventstudyinteract", "feols", "file", "fracreg", "frget", "frlink", "gmm", "hausman",
      "heckman", "irf", "isid", "ivprobit", "ivtobit", "labelbook", "logistic",
      "marginsplot", "mean", "mediate", "mi", "mixed", "mkdir", "mkspline", "mlogit", "newey",
      "nl", "ologit", "oprobit", "pperron", "prais", "proportion", "pwd", "qreg", "rddensity",
      "rdplot", "rdrobust", "reg3", "rm", "rmdir", "sdid", "sdtest", "ssc", "stcox", "streg",
      "stset", "svyset", "tabstat", "tobit", "tsline", "var", "vargranger", "version",
      "wntestq", "xtabond", "xtline", "zinb", "zip"
  };

  std::vector<std::string> unclassified;
  for (const auto& spec : piet::registry::commandRegistry()) {
    if (piet::parallel::lookupCommand(spec.canonical) != nullptr) continue;
    if (kEffectTableExempt.count(spec.canonical) != 0) continue;
    unclassified.push_back(spec.canonical);
  }
  check(unclassified.empty(),
        "every registry row is effect-table classified or frozen-exempt" +
            (unclassified.empty() ? std::string()
                                  : std::string(" (unclassified: ") +
                                        joinForMsg(unclassified) + ")"));

  // The exemption list may only shrink. If a name on it has since been
  // classified that is progress, not a failure — but the list must be pruned
  // so it never shelters a NEW row behind an old name.
  std::vector<std::string> staleExempt;
  for (const auto& name : kEffectTableExempt) {
    if (piet::parallel::lookupCommand(name) != nullptr) staleExempt.push_back(name);
  }
  check(staleExempt.empty(),
        "no frozen-exempt name has been classified without being pruned" +
            (staleExempt.empty() ? std::string()
                                 : std::string(" (prune: ") + joinForMsg(staleExempt) + ")"));

  // (2) ---------------------------------------------------------------------
  // Seeded with the five no-data routes that exist today; each AER bundle adds
  // its own rows here as it lands (ENV contributes all nineteen of its own).
  //
  // The bundle-D block is why this axis exists at all: an environment verb is
  // what a do-file runs BEFORE it loads anything, so a `net install` that
  // answered "No dataset is loaded" would fail on line 1 of every replication
  // package that needs it -- BUG-343's class, one layer earlier. Only the
  // no_data_loaded code is under test here, so the probes that legitimately
  // refuse (winexec, bcal, twoway__histogram_gen) or legitimately error
  // (findfile on a miss) belong on this list exactly as much as the rest.
  static const std::vector<std::string> kNoDataProbes = {
      "display 1", "pwd", "version", "timer on 1", "scalar list",
      // AER-SCOPE1 bundle D (ENV, 2026-09-03).
      "shell echo nodata_probe",
      "winexec notepad.exe",
      "type nodata_probe_absent.txt",
      "dir",
      "ls",
      "net install reghdfe",
      "ado uninstall moremata",
      "adopath + nodata_probe_dir",
      "sysdir set PLUS nodata_probe_dir",
      "findfile nodata_probe_absent.ado",
      "sleep 1",
      "pause on",
      "cls",
      "gr_edit .plotregion1.style.editstyle margin(medium) editcopy",
      "error 0",
      "bcal create nodata_probe_cal",
      "twoway__histogram_gen y, gen(ndh ndx)",
      "frames reset",
      // AER-SCOPE1 bundle I (UTIL, 2026-09-04). `filelist` is the one verb in
      // that bundle whose entire job runs BEFORE anything is loaded -- it
      // REPLACES the frame with a directory listing, so a do-file's first line
      // is exactly where it belongs and exactly where a missing
      // kNoDataCommands entry would answer "No dataset is loaded". Only the
      // no_data_loaded code is under test; an empty probe directory legitimately
      // producing some other outcome is fine here, the same way `findfile` on a
      // miss is.
      "filelist, directory(\".\") norecursive",
  };

#ifdef _WIN32
  std::error_code ndec;
  std::string ndWorkdir =
      (std::filesystem::temp_directory_path() / "piet_native_selftest_nodata").u8string();
  std::filesystem::create_directories(ndWorkdir, ndec);
#else
  std::string ndWorkdir = "/tmp/piet_native_selftest_nodata";
  (void)std::system(("mkdir -p '" + ndWorkdir + "'").c_str());
#endif

  for (const auto& probe : kNoDataProbes) {
    piet::SessionState session(ndWorkdir);  // deliberately NO sysuse
    auto blocks = piet::dispatch(probe, session);
    bool sawNoData = false;
    for (const auto& b : blocks) {
      if (b.is_object() && b.value("code", std::string()) == "no_data_loaded") {
        sawNoData = true;
        break;
      }
    }
    check(!sawNoData, "`" + probe + "` runs with no dataset loaded (kNoDataCommands)");
  }

#ifdef _WIN32
  std::error_code ndrec;
  std::filesystem::remove_all(ndWorkdir, ndrec);
#else
  (void)std::system(("rm -rf '" + ndWorkdir + "'").c_str());
#endif
}

// ── WS-B (extcompat, 2026-08-06): the community-name gate ────────────────────
//
// Three separable things are pinned here, because three different mistakes
// are possible:
//   (1) TABLE DRIFT — communityNameTable() (author + native equivalent, the
//       gate message's only source) and the per-row CommandSpec::communityNames
//       tagging are two hand-kept lists of the same 17 names. Either can be
//       edited alone. The cross-check below makes that impossible to ship.
//   (2) GATE BEHAVIOUR — off rejects with r(199) and the pinned message shape
//       (both variants: with and without a native equivalent); on/default runs
//       the command exactly as before; PIET's OWN names are never gated.
//   (3) THE `set` VERB — moves the session state in both directions and
//       honestly rejects a malformed value instead of silently leaving the
//       names enabled (which would be the silent-wrong-answer class).
//
// The gate default is ON, and this function restores it before returning, so
// no later selftest case inherits a disabled registry.
void testExtcompatGate() {
  std::printf("[selftest] --- extcompat community-name gate (WS-B) ---\n");

  // (1) Drift: the two lists must name exactly the same 17 spellings.
  {
    std::set<std::string> fromTable;
    for (const auto& cn : piet::registry::communityNameTable()) fromTable.insert(cn.name);
    std::set<std::string> fromRows;
    for (const auto& spec : piet::registry::commandRegistry()) {
      for (const auto& n : spec.communityNames) fromRows.insert(n);
    }
    // AER-SCOPE1: the campaign adds community names bundle by bundle (A adds
    // Cox's `winsor`; C adds the eight gtools names and the two ftools ones,
    // 18 -> 28; E adds the twelve TABLES packages -- estadd estpost estout
    // outreg2 texsave texdoc tabout frmttable regsave parmest mat2txt erepost
    // -- 28 -> 40), so this literal moves with it. `tex` is NOT among them and
    // must not be counted: it is texdoc's line verb, a spelling of the same
    // package rather than a package of its own, and it carries its own registry
    // row only because it reaches the dispatcher as a head. The count is a
    // tripwire against a name silently DISAPPEARING; the cross-check below is
    // the real lock, and it is the one that cannot be satisfied by editing a
    // number. `fastreshape` is NOT among the 40 and must not be added to make a
    // count come out: its author is not established, and communityNameTable()
    // is also the source of the NOTICE.txt attribution this project owes.
    //
    // I adds the twelve UTIL packages -- unique gunique distinct missings mdesc
    // labmask renvarlab splitvallabels filelist carryforward rangestat tsspell
    // -- 40 -> 52. `marksample` is NOT among them and must not be counted: it
    // is StataCorp's own built-in, so it carries a registry row and no
    // community tag. Neither is `dropmiss` (no package under that name on any
    // path -- only the successor `missings` -- so no author to attribute), nor
    // the three record-linkage names, which have no registry row at all.
    // `renvars` was refused here for the same "no package" reason and that
    // reason turned out to be SSC-shaped: the package is on the Stata Journal
    // as dm88 (`net install dm88_1, from(.../sj5-4)`), and the installed
    // renvars.ado header names Nicholas J. Cox and Jeroen Weesie. K1 gives it
    // its own handler (an alias onto renvarlab would have answered r(198) on
    // the real corpus lines) and it IS counted below.
    //
    // J adds the six GRAPH-X packages -- grc1leg2 grstyle geodist geonear
    // cdfplot event_plot -- 52 -> 58. `grc1leg` (un-suffixed) was NOT among
    // them, on the ground that "its package states no author anywhere" and a
    // row invented from a distribution URL is precisely what this rule exists
    // to stop. Both halves of that were right about the two files it read (the
    // .ado and the .sthlp); what it did not read is the installer's own record
    // of the .pkg description, `ado/plus/stata.trk`, whose `d` lines for
    // grc1leg.pkg say "Program by Vince Wiggins, StataCorp" and give the 2003
    // Statalist distribution date. That is the package's OWN claim rather than
    // an inference from where it is hosted, so the refusal is inverted and the
    // name is counted below. Still NOT among them are the eight refusals
    // (cibar binsreg spmap maptile shp2dta geoinpoly heatplot distplot), which
    // have no registry row at all.
    // 58 -> 60: AER bundle H adds ivreg2 and xtivreg2. ivreg2's attribution is
    // VERIFIED against the package installed on this machine -- ivreg2.sthlp's
    // citation block reads "Baum, C.F., Schaffer, M.E., Stillman, S. 2010." and
    // names all three. (The .ado header's "authors cfb & mes" is a code
    // shorthand; taking it literally would have dropped Stillman.) xtivreg2 is
    // not installed here, so its row rests on the published module citation.
    // 64 -> 65: bundle K1c adds `parallel`, whose ado header credits George G.
    // Vega Yon and Brian Quistorff.
    // 63 -> 64: AER scope 2 bundle B2 adds `strdist`, whose ado header names
    // Michael D Barker and Felix Pöge. It was previously excluded as "record
    // linkage, out of scope"; the scope moved, not the attribution rule.
    // 60 -> 63: AER scope 2 bundle K1 adds `grc1leg` on the stata.trk evidence
    // described above, plus `tolower` (tolower.ado's own first line credits Nick
    // Cox, Statalist Digest 895) and `renvars` (renvars.ado's `*!` line credits
    // njc/jw, STB-60 dm88). `move` is NOT among them and must not be added to
    // make a count come out: it is StataCorp's own built-in, so it takes a
    // registry row and no community tag, exactly like `marksample` above.
    // 68 -> 78: AER tier-1 (2026-10-28) adds require (Correia, Seay -- require.sthlp's
    // Authors block), labvars, astile, matsort, matselrc, fillmissing, findname,
    // sencode, zipsave and zipuse, each read from its package's `ssc describe`
    // record on the oracle Mac (matselrc from STB-56 dm79's record; zipuse ships in
    // the zipsave package). The official verbs of the same bundle take rows, no tag.
    // 66 -> 68: package-007 unblock (T7) adds `ihstrans` (ihstrans.ado's `*!` line
    // credits Jan Helmdag) and `sctorezone` (sctorezone.ado's header credits
    // SurveyCTO / William Blackmon, IPA, package scto). `lookfor` is StataCorp's
    // own ado and takes a registry row, no community tag.
    // 78 -> 79: package-007 lane LB adds `leebounds` (leebounds.ado's `*!` line
    // credits Harald Tauchmann); it landed on main as 68 -> 69 while the tier-1
    // branch was out, and the two counts met at its merge.
    check(fromTable.size() == 79,
          "extcompat: communityNameTable() carries exactly the 79 documented names, got " +
              std::to_string(fromTable.size()));
    check(fromTable == fromRows,
          "extcompat: CommandSpec::communityNames tagging == communityNameTable() (no drift)");

    // Every gated name must be a REGISTERED spelling, or the gate would be
    // rejecting a name the dispatcher never had an arm for anyway — and the
    // message would promise a compatibility that does not exist.
    bool allRegistered = true;
    bool allAttributed = true;
    for (const auto& cn : piet::registry::communityNameTable()) {
      if (piet::registry::findByName(cn.name) == nullptr) allRegistered = false;
      if (cn.author.empty()) allAttributed = false;
      // A declared native equivalent must itself be a real command.
      if (!cn.nativeEquivalent.empty() &&
          piet::registry::findByName(cn.nativeEquivalent) == nullptr) {
        allRegistered = false;
      }
    }
    check(allRegistered,
          "extcompat: every community name (and every declared native equivalent) is a "
          "registered spelling");
    check(allAttributed, "extcompat: every community name carries a NOTICE.txt author string");
  }

  // Canonical flip (WS-B): our own name owns the row; the package name is the
  // alias. Both spellings still resolve.
  {
    const auto* viaCommunity = piet::registry::findByName("reghdfe");
    const auto* viaNative = piet::registry::findByName("feols");
    check(viaCommunity != nullptr && viaCommunity->canonical == "feols",
          "extcompat: `reghdfe` resolves to the row whose canonical is `feols` (canonical flip)");
    check(viaNative != nullptr && viaNative->canonical == "feols",
          "extcompat: `feols` is the canonical spelling of its own row");
  }

  // Message shape — built from the table, asserted verbatim.
  {
    const auto* withNative = piet::registry::findCommunityName("reghdfe");
    const auto* withoutNative = piet::registry::findCommunityName("csdid");
    check(withNative != nullptr &&
              piet::registry::communityGateMessage(*withNative) ==
                  "'reghdfe' is a community-package compatibility name (package by Sergio "
                  "Correia (+ Paulo Guimaraes, Tom Zylkin), not affiliated). PIET's native "
                  "command is 'feols'. Run: set extcompat on",
          "extcompat: gate message (native-equivalent variant) is byte-exact");
    check(withoutNative != nullptr &&
              piet::registry::communityGateMessage(*withoutNative) ==
                  "'csdid' is a community-package compatibility name (package by Fernando "
                  "Rios-Avila; Brantly Callaway, Pedro H. C. Sant'Anna, not affiliated). Run: "
                  "set extcompat on",
          "extcompat: gate message drops the middle sentence when there is no native equivalent");
  }

  // (2)/(3) Live dispatch behaviour.
  namespace fs = std::filesystem;
  std::error_code ec;
  fs::path tmp = fs::temp_directory_path() / "piet_native_selftest_extcompat";
  fs::remove_all(tmp, ec);
  fs::create_directories(tmp, ec);
  std::string workdir = tmp.u8string();

  auto firstError = [](const nlohmann::ordered_json& blocks) -> nlohmann::ordered_json {
    for (const auto& b : blocks) {
      if (b.is_object() && b.value("type", std::string()) == "error") return b;
    }
    return nlohmann::ordered_json();
  };

  {
    piet::SessionState session(workdir);
    (void)piet::dispatch("sysuse fatalities, clear", session);

    // Default (nothing persisted, no `set`): the names work. This is the
    // state every gate/wave/freeze run is in.
    check(piet::settings::extcompatEnabled(),
          "extcompat: default is ON (absent settings file -> the 17 names answer)");
    {
      auto blocks = piet::dispatch("reghdfe fatal beertax, absorb(state)", session);
      auto err = firstError(blocks);
      check(err.is_null() || err.value("code", std::string()) != "unsupported_command",
            "extcompat ON: `reghdfe` reaches its real handler (not the gate)");
    }

    // `set extcompat off` — the verb moves the session state.
    (void)piet::dispatch("set extcompat off", session);
    check(!piet::settings::extcompatEnabled(), "extcompat: `set extcompat off` disables the names");

    {
      auto blocks = piet::dispatch("reghdfe fatal beertax, absorb(state)", session);
      auto err = firstError(blocks);
      check(!err.is_null() && err.value("code", std::string()) == "unsupported_command" &&
                err.value("token", std::string()) == "reghdfe",
            "extcompat OFF: `reghdfe` is rejected as an unsupported command");
      check(!err.is_null() &&
                err.value("message", std::string())
                        .find("is a community-package compatibility name") != std::string::npos,
            "extcompat OFF: the reject carries the community-package message");
      check(!err.is_null() && piet::eval::coarseRc(err) == "199",
            "extcompat OFF: the reject maps to Stata r(199)");
    }

    // Our own spellings are untouched by the gate.
    {
      auto blocks = piet::dispatch("feols fatal beertax, absorb(state)", session);
      auto err = firstError(blocks);
      check(err.is_null() || err.value("code", std::string()) != "unsupported_command",
            "extcompat OFF: PIET's own `feols` still runs");
    }
    {
      auto blocks = piet::dispatch("regress fatal beertax", session);
      auto err = firstError(blocks);
      check(err.is_null() || err.value("code", std::string()) != "unsupported_command",
            "extcompat OFF: an ordinary Stata command is unaffected");
    }

    // A row whose canonical IS a community name is gated on that canonical.
    {
      auto blocks = piet::dispatch("winsor2 fatal", session);
      auto err = firstError(blocks);
      check(!err.is_null() && err.value("token", std::string()) == "winsor2",
            "extcompat OFF: a row whose canonical IS the community name is gated too");
    }

    // Back on, and the same line runs again.
    (void)piet::dispatch("set extcompat on", session);
    check(piet::settings::extcompatEnabled(), "extcompat: `set extcompat on` re-enables the names");
    {
      auto blocks = piet::dispatch("reghdfe fatal beertax, absorb(state)", session);
      auto err = firstError(blocks);
      check(err.is_null() || err.value("code", std::string()) != "unsupported_command",
            "extcompat: after `set extcompat on` the name answers again");
    }

    // Malformed value: an honest reject, and the state does NOT move.
    {
      auto blocks = piet::dispatch("set extcompat maybe", session);
      auto err = firstError(blocks);
      check(!err.is_null() && err.value("code", std::string()) == "unsupported_option",
            "extcompat: `set extcompat <garbage>` is an honest reject");
      check(piet::settings::extcompatEnabled(),
            "extcompat: a malformed `set` leaves the previous state intact");
    }
  }

  // Settings persistence + the consent pair, in an isolated store.
  {
    std::string settingsFile = (tmp / "settings.json").u8string();
#ifndef _WIN32
    setenv("PIET_SETTINGS_FILE", settingsFile.c_str(), 1);
#else
    _putenv_s("PIET_SETTINGS_FILE", settingsFile.c_str());
#endif
    check(piet::settings::testIsolationActive(),
          "extcompat: $PIET_SETTINGS_FILE marks a gate/test isolation run");
    {
      auto r = piet::routes::settingsGet("{}");
      auto j = nlohmann::json::parse(r.json);
      check(j.value("extcompat", false), "extcompat: a fresh store reports extcompat true");
      check(j.value("extcompat_consent_at", std::string("x")).empty(),
            "extcompat: a fresh store reports no consent timestamp");
      // The test-mode auto-accept: no dialog is ever requested under
      // isolation, which is what keeps --ui-smoke and the DOM gate unblocked.
      check(!j.value("consent_required", true),
            "extcompat: consent is NEVER required under test isolation (auto-accept)");
    }
    {
      nlohmann::ordered_json body;
      body["extcompat"] = false;
      body["extcompat_consent_at"] = "2026-08-06T00:00:00Z";
      auto rs = piet::routes::settingsSet(body.dump());
      check(rs.ok, "extcompat: settings.set persists the consent pair");
      piet::settings::Settings reread = piet::settings::load();
      check(!reread.extcompat && reread.extcompatConsentAt == "2026-08-06T00:00:00Z",
            "extcompat: a fresh load() reads the pair back off disk");
      check(!piet::settings::extcompatEnabled(),
            "extcompat: a persisted choice applies to the next command (cache refreshed)");
      auto r2 = piet::routes::settingsGet("{}");
      auto j2 = nlohmann::json::parse(r2.json);
      check(!j2.value("consent_required", true),
            "extcompat: a stored consent timestamp clears consent_required");
    }

    // WS-B step 6: the pack scan ENUMERATES and does nothing else. Pinned
    // here because the whole value of a stub is that it stayed a stub — a
    // future loader must be a deliberate change, not something that grew.
    {
      check(piet::settings::enumeratePacks().empty(),
            "packs: no packs dir -> empty enumeration (the normal case)");
      fs::path packs = fs::path(piet::settings::packsDir());
      fs::create_directories(packs / "demo-pack", ec);
      fs::create_directories(packs / "not-a-pack", ec);
      // A directory WITHOUT a manifest is not a pack...
      check(piet::settings::enumeratePacks().empty(),
            "packs: a directory with no manifest.json is not enumerated");
      // ...and one WITH a manifest is listed by id, with the manifest itself
      // left unread (this one is deliberately unparseable: a loader would
      // choke on it, an enumerator must not care).
      std::ofstream(packs / "demo-pack" / "manifest.json") << "{ not valid json";
      auto ids = piet::settings::enumeratePacks();
      check(ids.size() == 1 && ids[0] == "demo-pack",
            "packs: a directory carrying manifest.json is enumerated by its id");
      check(ids.size() == 1,
            "packs: the enumeration reads no manifest and loads nothing (an invalid "
            "manifest is still merely listed)");
      auto rp = piet::routes::settingsGet("{}");
      auto jp = nlohmann::json::parse(rp.json);
      check(jp.contains("packs") && jp["packs"].is_array() && jp["packs"].size() == 1,
            "packs: settings.get carries the boot-time enumeration");
      fs::remove_all(packs, ec);
    }
#ifndef _WIN32
    unsetenv("PIET_SETTINGS_FILE");
#else
    _putenv_s("PIET_SETTINGS_FILE", "");
#endif
  }

  // The OTHER half of the auto-accept, and the one that can actually fail
  // silently: a gate that only proves "no dialog under isolation" is GREEN
  // even if the dialog can never appear at all. Drop the isolation hook and
  // point the real config-dir resolution at a throwaway HOME — a genuine
  // first launch — and consent MUST be requested.
#ifndef _WIN32
  {
    const char* realHome = std::getenv("HOME");
    std::string savedHome = realHome ? realHome : "";
    fs::path fakeHome = tmp / "fresh_home";
    fs::create_directories(fakeHome, ec);
    setenv("HOME", fakeHome.u8string().c_str(), 1);
#if !defined(__APPLE__)
    const char* realXdg = std::getenv("XDG_CONFIG_HOME");
    std::string savedXdg = realXdg ? realXdg : "";
    unsetenv("XDG_CONFIG_HOME");
#endif
    auto r = piet::routes::settingsGet("{}");
    auto j = nlohmann::json::parse(r.json);
    check(j.value("consent_required", false),
          "extcompat: a genuine first launch (no isolation, no stored consent) DOES require "
          "consent — the auto-accept is scoped to gate runs, it did not disable the dialog");
    if (!savedHome.empty()) {
      setenv("HOME", savedHome.c_str(), 1);
    } else {
      unsetenv("HOME");
    }
#if !defined(__APPLE__)
    if (!savedXdg.empty()) setenv("XDG_CONFIG_HOME", savedXdg.c_str(), 1);
#endif
  }
#endif

  // Restore the process default for every case that runs after this one.
  piet::settings::invalidateExtcompatCache();
  piet::settings::setExtcompatEnabled(true);
  fs::remove_all(tmp, ec);
}

// P1-W2-0-LABELBOOK-BUG102: `labelbook` is a direct-read report over
// session.labelDefs/valueLabels/varLblname — no engine change, the data
// already arrives via `use`'s --out-meta sidecar (session_state.h:1054-
// 1067). Checks label-set name + code:text definition + attached-variable
// presence, and the label-less fallback text (mirrors runLabelList/
// runLabelDir's existing "(no value labels defined)" idiom).
void testLabelbook() {
  std::printf("[selftest] --- labelbook (P1-W2-0) ---\n");

#ifdef _WIN32
  std::error_code lbec;
  std::string workdir =
      (std::filesystem::temp_directory_path() / "piet_native_selftest_labelbook").u8string();
  std::filesystem::create_directories(workdir, lbec);
#else
  std::string workdir = "/tmp/piet_native_selftest_labelbook";
  (void)std::system(("mkdir -p '" + workdir + "'").c_str());
#endif

  {
    piet::SessionState session(workdir);
    (void)piet::dispatch("sysuse fatalities, clear", session);
    (void)piet::dispatch("gen state_num = mod(_n,3)+1", session);
    (void)piet::dispatch("label define statelbl 1 \"CA\" 2 \"NY\" 3 \"TX\"", session);
    (void)piet::dispatch("label values state_num statelbl", session);
    auto blocks = piet::dispatch("labelbook", session);
    std::string text;
    for (const auto& b : blocks) {
      if (b.is_object() && b.value("type", std::string()) == "display")
        text += b.value("text", std::string());
    }
    check(text.find("statelbl") != std::string::npos,
          "labelbook: reports the defined label set name");
    check(text.find("CA") != std::string::npos && text.find("NY") != std::string::npos &&
              text.find("TX") != std::string::npos,
          "labelbook: reports the code:text definition");
    check(text.find("state_num") != std::string::npos,
          "labelbook: reports the attached variable");
  }

  {
    // Label-less fallback: a fresh session with no value labels defined.
    piet::SessionState session(workdir);
    (void)piet::dispatch("sysuse fatalities, clear", session);
    auto blocks = piet::dispatch("labelbook", session);
    std::string text;
    for (const auto& b : blocks) {
      if (b.is_object() && b.value("type", std::string()) == "display")
        text += b.value("text", std::string());
    }
    check(text.find("no value labels defined") != std::string::npos,
          "labelbook: label-less fallback message");
  }

#ifdef _WIN32
  std::error_code lrec;
  std::filesystem::remove_all(workdir, lrec);
#else
  (void)std::system(("rm -rf '" + workdir + "'").c_str());
#endif
}

// BUG-102: a factor-variable coefficient row substitutes the attached value
// label for the bare level (verified live against StataBE 19.5: `regress y
// i.state_num` with `label values state_num statelbl` prints "Arizona"/
// "Idaho" rows, not "2.state_num"/"3.state_num") — checks the substituted
// case (regress's own M2 slice, handlers.cpp's cobraToEstimation) and the
// label-less fallback (bare "<level>.<var>" unchanged, same session shape).
void testBug102CoeftableValueLabels() {
  std::printf("[selftest] --- BUG-102 coeftable value-label substitution ---\n");

#ifdef _WIN32
  std::error_code bec;
  std::string workdir =
      (std::filesystem::temp_directory_path() / "piet_native_selftest_bug102").u8string();
  std::filesystem::create_directories(workdir, bec);
#else
  std::string workdir = "/tmp/piet_native_selftest_bug102";
  (void)std::system(("mkdir -p '" + workdir + "'").c_str());
#endif

  {
    piet::SessionState session(workdir);
    (void)piet::dispatch("sysuse fatalities, clear", session);
    (void)piet::dispatch("gen state_num = int((_n-1)/112)+1", session);
    (void)piet::dispatch("label define statelbl 1 \"CA\" 2 \"NY\" 3 \"TX\"", session);
    (void)piet::dispatch("label values state_num statelbl", session);
    auto blocks = piet::dispatch("regress beertax i.state_num", session);
    nlohmann::ordered_json coeftable;
    for (const auto& b : blocks) {
      if (b.is_object() && b.value("type", std::string()) == "estimation") {
        coeftable = b.value("coeftable", nlohmann::ordered_json::array());
      }
    }
    // BUG-397 (2026-09-02, re-keyed to the g12 oracle): the row NAME is Stata's e(b) colname and
    // stays the bare level (`2.state_num`); the label rides on `stub` (display shape) and `label`.
    bool sawStub = false, sawBareName = false, sawLabelInName = false, sawLabel = false;
    for (const auto& row : coeftable) {
      std::string nm = row.value("name", std::string());
      std::string st = row.value("stub", std::string());
      std::string lb = row.value("label", std::string());
      if (st == "NY.state_num" || st == "TX.state_num") sawStub = true;
      if (nm == "2.state_num" || nm == "3.state_num") sawBareName = true;
      if (nm == "NY.state_num" || nm == "TX.state_num") sawLabelInName = true;
      if (lb == "NY" || lb == "TX") sawLabel = true;
    }
    check(sawStub, "BUG-102/397: a labeled factor level carries the substituted display name in `stub` (NY.state_num)");
    check(sawLabel, "BUG-397: a labeled factor level carries the bare label text in `label` (NY)");
    check(sawBareName, "BUG-397: the row `name` stays Stata's e(b) colname (2.state_num) — _b[2.state_num] keeps resolving");
    check(!sawLabelInName, "BUG-397: the label never replaces the e(b) colname in `name`");
  }

  {
    // Label-less fallback: same factor variable, no `label values` attached.
    piet::SessionState session(workdir);
    (void)piet::dispatch("sysuse fatalities, clear", session);
    (void)piet::dispatch("gen state_num = int((_n-1)/112)+1", session);
    auto blocks = piet::dispatch("regress beertax i.state_num", session);
    nlohmann::ordered_json coeftable;
    for (const auto& b : blocks) {
      if (b.is_object() && b.value("type", std::string()) == "estimation") {
        coeftable = b.value("coeftable", nlohmann::ordered_json::array());
      }
    }
    bool sawBareLevel = false;
    for (const auto& row : coeftable) {
      std::string nm = row.value("name", std::string());
      if (nm == "2.state_num" || nm == "3.state_num") sawBareLevel = true;
    }
    check(sawBareLevel, "BUG-102: label-less fallback keeps the bare level.varname name");
  }

#ifdef _WIN32
  std::error_code brec;
  std::filesystem::remove_all(workdir, brec);
#else
  (void)std::system(("rm -rf '" + workdir + "'").c_str());
#endif
}

// --- BUG-105 abbreviation stopgap (2026-07-31): the 5 command
// abbreviations real Stata accepts that PIET silently rejected as unknown
// commands — `l`(list), `su`(summarize), `d`(describe), `ta`(tabulate),
// `cor`(correlate). This is the BUGLOG's own sanctioned STOPGAP: five
// hand-written aliases at the dispatcher arms, NOT a general
// minimum-unambiguous-prefix resolver (that is a separate arc, BACKLOG
// BUG105-112-HARDENING-REMAINDER).
//
// The assertion shape is deliberately stronger than testRegistryRoutes'
// drift guard above (which only proves a spelling does not fall through to
// `unsupported_command`): each abbreviation is run against its OWN fresh
// session and its non-echo block stream is compared for EQUALITY with the
// canonical spelling's. "Routes somewhere" is not the claim being made —
// "is the same command" is, and only equality can carry that. The echo
// block is the one legitimate difference (it quotes the raw input text).
void testBUG105AbbreviationStopgap() {
  std::printf("[selftest] --- BUG-105 abbreviation stopgap (l/su/d/ta/cor) ---\n");

#ifdef _WIN32
  std::error_code abec;
  std::string workdir =
      (std::filesystem::temp_directory_path() / "piet_native_selftest_bug105abbrev").u8string();
  std::filesystem::create_directories(workdir, abec);
#else
  std::string workdir = "/tmp/piet_native_selftest_bug105abbrev";
  (void)std::system(("mkdir -p '" + workdir + "'").c_str());
#endif

  auto meat = [](const nlohmann::json& blocks) {
    nlohmann::json out = nlohmann::json::array();
    for (const auto& b : blocks) {
      if (b.is_object() && b.value("type", std::string()) == "echo") continue;
      out.push_back(b);
    }
    return out;
  };
  // Fresh SessionState + fresh `sysuse` per invocation, so the canonical
  // and the abbreviation are each measured from an identical starting
  // state and neither can inherit the other's session mutations.
  auto runFresh = [&](const std::string& cmd) {
    piet::SessionState session(workdir);
    (void)piet::dispatch("sysuse fatalities, clear", session);
    return meat(piet::dispatch(cmd, session));
  };
  auto hasErrorBlock = [](const nlohmann::json& blocks) {
    for (const auto& b : blocks) {
      if (b.is_object() && b.value("type", std::string()) == "error") return true;
    }
    return false;
  };

  static const std::vector<std::pair<std::string, std::string>> kAbbrevPairs = {
      {"list beertax", "l beertax"},
      {"summarize beertax", "su beertax"},
      {"describe", "d"},
      {"tabulate year", "ta year"},
      {"correlate beertax unemp", "cor beertax unemp"},
  };
  for (const auto& pr : kAbbrevPairs) {
    const std::string& canonical = pr.first;
    const std::string& abbrev = pr.second;
    nlohmann::json canonBlocks = runFresh(canonical);
    nlohmann::json abbrevBlocks = runFresh(abbrev);
    // VACUITY GUARD. An equality assertion between two EMPTY block streams
    // passes trivially, and so does an absence-of-error check over an empty
    // stream — if `sysuse` ever stopped loading here, every assertion below
    // would go green while measuring nothing. Require real output first.
    check(!canonBlocks.empty(),
          "BUG-105 abbrev vacuity guard: `" + canonical + "` produced a non-empty block stream");
    check(!hasErrorBlock(canonBlocks),
          "BUG-105 abbrev control: `" + canonical + "` itself answers without an error block");
    check(abbrevBlocks == canonBlocks,
          "BUG-105 abbrev: `" + abbrev + "` produces the same blocks as `" + canonical + "`");
  }

  // DISCRIMINATOR. The equality comparator above is only worth anything if
  // it can also tell two DIFFERENT things apart. A deliberately unknown
  // token stands in for the seeded-RED: it must NOT compare equal to the
  // canonical. `zzlist` is used rather than a plausible near-spelling like
  // `li` on purpose — a real Stata abbreviation would become legal the day
  // the general prefix-resolver arc lands, turning this control into a
  // false RED; a nonsense token never will.
  {
    nlohmann::json canonList = runFresh("list beertax");
    nlohmann::json bogus = runFresh("zzlist beertax");
    check(bogus != canonList,
          "BUG-105 abbrev discriminator: an unknown token (`zzlist`) does NOT compare equal to "
          "`list` — the block-equality comparator distinguishes, it does not pass everything");
    check(hasErrorBlock(bogus),
          "BUG-105 abbrev discriminator: `zzlist` is still an honest error, so the 5 aliases "
          "widened the accepted set by exactly the 5 spellings and not by a catch-all");
  }

  // BUG-105 secondary (2) interaction, called out by this task's DoD: the
  // tokenizer's `in`-range gate resolves the command token through
  // registry::findByName(), and it runs at Step 5 — BEFORE dispatch ever
  // sees the command. So a dispatcher-only alias would ROUTE correctly and
  // still be rejected the moment an `in` qualifier is attached. This
  // assertion is what pins the registry `abbrev` half of the fix; it fails
  // if `l` is ever removed from the `list` row while the dispatcher arm
  // keeps the alias.
  {
    nlohmann::json canonIn = runFresh("list beertax in 1/5");
    nlohmann::json abbrevIn = runFresh("l beertax in 1/5");
    check(!hasErrorBlock(canonIn),
          "BUG-105 abbrev control: `list beertax in 1/5` answers without an error block");
    check(!hasErrorBlock(abbrevIn),
          "BUG-105 abbrev: `l beertax in 1/5` clears the registry-driven `in` gate too");
    check(abbrevIn == canonIn,
          "BUG-105 abbrev: `l ... in 1/5` matches `list ... in 1/5` block-for-block");
  }

#ifdef _WIN32
  std::error_code abrec;
  std::filesystem::remove_all(workdir, abrec);
#else
  (void)std::system(("rm -rf '" + workdir + "'").c_str());
#endif
}

// --- BUG-105 secondary ① (2026-07-31): unsupported_command message honesty.
//
// The retired fallback sentence ("If this is a valid Stata command, it may be
// added in a later milestone") was ONE string covering three unrelated causes,
// and it cast doubt on Stata-validity in every one of them — actively wrong for
// the abbreviation gaps above, where the command IS valid Stata and the real
// reason was that PIET's own table lacked the prefix.
//
// So the claim under test is not "an error was raised" — that was already true
// and already asserted elsewhere by `code`. It is that the three causes now say
// three DIFFERENT things. Each arm therefore asserts both its own wording and
// the ABSENCE of the other two's: an assertion that only checked for its own
// substring would still pass if the fix collapsed back into one shared string
// that happened to contain all three phrases.
void testBUG105UnsupportedCommandHonesty() {
  std::printf("[selftest] --- BUG-105 secondary (1): unsupported_command honesty ---\n");

#ifdef _WIN32
  std::error_code uhec;
  std::string workdir =
      (std::filesystem::temp_directory_path() / "piet_native_selftest_bug105unsupp").u8string();
  std::filesystem::create_directories(workdir, uhec);
#else
  std::string workdir = "/tmp/piet_native_selftest_bug105unsupp";
  (void)std::system(("mkdir -p '" + workdir + "'").c_str());
#endif

  // Fresh session + fresh `sysuse` per invocation: `graph bar`'s honest-error
  // branch sits behind graph's own inner hasData() re-check, so an empty
  // session would answer no_data_loaded and the arm would measure nothing.
  auto errOf = [&](const std::string& cmd) {
    piet::SessionState session(workdir);
    (void)piet::dispatch("sysuse fatalities, clear", session);
    nlohmann::json blocks = piet::dispatch(cmd, session);
    for (const auto& b : blocks) {
      if (b.is_object() && b.value("type", std::string()) == "error") return b;
    }
    return nlohmann::json();
  };
  auto says = [](const nlohmann::json& b, const std::string& needle) {
    return b.value("message", std::string()).find(needle) != std::string::npos;
  };

  // The defect string and the doubt-casting clause it lived in. Neither may
  // survive on ANY of the three arms.
  const std::string kRetiredTail = "later milestone";
  const std::string kRetiredDoubt = "valid Stata command";
  // Each cause's own signature phrase.
  const std::string kTableSig = "command table has no entry";
  const std::string kGapSig = "recognized Stata feature";
  const std::string kSubSig = "this subcommand is not";

  // Arm 1 — kUnknownToken: the token never resolved to a table entry. This is
  // the arm every BUG-105 abbreviation gap landed on.
  {
    nlohmann::json b = errOf("totallyunknownxyz123");
    check(b.value("code", std::string()) == "unsupported_command",
          "BUG-105(1): an unrecognized token is still an honest unsupported_command");
    check(says(b, kTableSig),
          "BUG-105(1): the unknown-token message names PIET's command table as the reason");
    check(!says(b, kRetiredTail) && !says(b, kRetiredDoubt),
          "BUG-105(1): it no longer casts doubt on the command's Stata-validity");
    check(!says(b, kGapSig) && !says(b, kSubSig),
          "BUG-105(1): unknown-token does not also claim the other two causes");
  }

  // Arm 2 — kNotImplemented: `graph pie` IS valid Stata; PIET just lacks it.
  // Telling this user to check their spelling would be the same class of lie
  // the retired sentence told, pointed the other way. (graph-family AI-1:
  // `graph bar`, the arm's first subject, is implemented now.)
  {
    nlohmann::json b = errOf("graph pie beertax, over(state)");
    check(b.value("code", std::string()) == "unsupported_command",
          "BUG-105(1): `graph pie` is still an honest unsupported_command");
    check(says(b, kGapSig),
          "BUG-105(1): a known gap is named as unimplemented, not as a spelling problem");
    check(!says(b, kRetiredTail) && !says(b, kRetiredDoubt),
          "BUG-105(1): the known-gap arm dropped the retired milestone wording too");
    check(!says(b, kTableSig) && !says(b, kSubSig),
          "BUG-105(1): known-gap does not also claim the other two causes");
  }

  // Arm 3 — kUnknownSubcommand: `label` is implemented, `nosuchsub` is not.
  // "PIET has no entry under that name" would be false — it has `label`.
  {
    nlohmann::json b = errOf("label nosuchsub beertax");
    check(b.value("code", std::string()) == "unsupported_command",
          "BUG-105(1): an unknown `label` subcommand is still an honest unsupported_command");
    check(says(b, kSubSig),
          "BUG-105(1): the subcommand arm says the head command IS implemented");
    check(!says(b, kRetiredTail) && !says(b, kRetiredDoubt),
          "BUG-105(1): the subcommand arm dropped the retired milestone wording too");
    check(!says(b, kTableSig) && !says(b, kGapSig),
          "BUG-105(1): unknown-subcommand does not also claim the other two causes");
  }

#ifdef _WIN32
  std::error_code uhrec;
  std::filesystem::remove_all(workdir, uhrec);
#else
  (void)std::system(("rm -rf '" + workdir + "'").c_str());
#endif
}

// --- BUG-105 secondary ②: the in/weight qualifier gates fire before the
// command token has been resolved, so an unrouted word came back as a feature
// gap ("`xyzzy` does not support the `in` row-range qualifier") instead of
// "command not found". Fixed at the gate (eval/tokenizer.cpp) rather than by
// moving extractQualifiers past command resolution: the gates already REJECT
// every unrouted word (a registry miss makes allowInRange/FweightOnly false),
// so re-ordering the two facts changes the MESSAGE and nothing else — no input
// that used to run stops running.
//
// The by/bysort legs are the drift guard for the one exemption this needs:
// dispatcher.cpp routes those five spellings without a registry row, so the
// tokenizer keeps its own copy of that list. If the copies ever diverge, the
// exempted spelling starts answering unsupported_command and these legs fail.
void testBUG105InQualPrescan() {
  std::printf("[selftest] --- BUG-105 secondary (2): qualifier gate vs unknown command ---\n");

  const std::string kTableSig = "command table has no entry";
  const std::string kInGapSig = "row-range qualifier";
  const std::string kWeightGapSig = "weighted estimation";

  // An object (not a default-constructed null) so a NON-throwing line answers
  // "no code / no message" through value() instead of a json type_error.
  auto errOf = [](const std::string& line) {
    nlohmann::json b = nlohmann::json::object();
    try {
      (void)piet::eval::tokenize(line);
    } catch (const piet::eval::TokenizerError& e) {
      b = e.block;
    }
    return b;
  };
  auto says = [](const nlohmann::json& b, const std::string& needle) {
    return b.value("message", std::string()).find(needle) != std::string::npos;
  };

  // (1) unknown command + `in` -> command-not-found, NOT a feature gap. This is
  // the finding's own repro shape (BUGLOG's `l` case, pre-abbreviation-stopgap).
  {
    nlohmann::json b = errOf("xyzzy state in 1/5");
    check(b.value("code", std::string()) == "unsupported_command",
          "BUG-105(2): unknown command + `in` is an honest unsupported_command");
    check(says(b, kTableSig) && !says(b, kInGapSig),
          "BUG-105(2): it names PIET's command table, not a made-up `in` limitation");
  }
  // Same defect one gate up: the weight qualifier invented a feature gap too.
  {
    nlohmann::json b = errOf("xyzzy state [aw=pop]");
    check(b.value("code", std::string()) == "unsupported_command",
          "BUG-105(2): unknown command + [aw=] is an honest unsupported_command");
    check(says(b, kTableSig) && !says(b, kWeightGapSig),
          "BUG-105(2): the weight gate no longer claims an unrouted word lacks weight support");
  }

  // (2) known commands are untouched — both the legal and the rejected side.
  {
    piet::eval::ParsedCommand pc = piet::eval::tokenize("list id year in 1/5");
    check(pc.inRange && *pc.inRange == "1/5",
          "BUG-105(2): a routed command that ALLOWS `in` still parses it (no regression)");
  }
  {
    nlohmann::json b = errOf("tabstat wage in 1/5");
    check(b.value("code", std::string()) == "unsupported_option" && says(b, kInGapSig) &&
              says(b, "tabstat"),
          "BUG-105(2): a routed command that REJECTS `in` keeps its feature-gap message");
  }
  {
    // `regress` moved to WeightPolicy::AllWeights in the P3 weights wave
    // ([aw=] is now legal there — see testBS096QualifierPolicyTable), and `corr`,
    // its first replacement, serves [aw=]/[fw=] since BUG-1014 (help correlate;
    // w2aj_qualifiers.log:1869 qf_co_aw rc 0), and `tobit`, its next, serves all four
    // types since BUG-1544. `reg3` (WeightPolicy::None, while help reg3 allows
    // aweights and fweights) is the same "routed command that REJECTS a weight" shape
    // the test name promises: an engine gap, not Stata's rule.
    nlohmann::json b = errOf("reg3 y x1 [aw=x2]");
    check(b.value("code", std::string()) == "unsupported_option" && says(b, kWeightGapSig),
          "BUG-105(2): a routed command that REJECTS a weight keeps its feature-gap message");
  }
  // by/bysort: routed WITHOUT a registry row, so the outer token must stay
  // exempt from the unknown-command verdict on every spelling -- and (SUM-BYWEIGHT)
  // a weight there belongs to the sub-command, which the by-driver re-tokenizes:
  // the outer pass passes it through (w2as_summary_stats_family sx_cumul_by_equal
  // `by d, sort: cumul y [aw=aw], gen(cyb) equal` rc 0).
  for (const std::string& sp : {"bysort", "by", "bys", "byso", "bysor"}) {
    nlohmann::json b = errOf(sp + " grp: summarize wage [fw=x1]");
    check(b.empty(),
          "BUG-105(2): `" + sp + "` prefix is neither an unknown command nor a weight gate "
          "(tokenizer/dispatcher by-list drift guard; the sub-command's row judges the weight)");
  }

  // (3) the quoted-`in` trap: a literal " in " inside a string is not a
  // qualifier, so neither gate may fire and no verdict may be reached at all
  // ([[piet-quote-aware-qualifier]] / BUG-115 class).
  {
    piet::eval::ParsedCommand pc = piet::eval::tokenize("gen s1 = \"value in range\"");
    check(!pc.inRange, "BUG-105(2): a quoted ` in ` is still not read as an `in` qualifier");
  }
  {
    // Same trap on the arm that would now answer unsupported_command: an
    // unrouted command with a quoted `in` must fall through to the dispatcher
    // untouched by these gates (it errors there, not here).
    piet::eval::ParsedCommand pc = piet::eval::tokenize("xyzzy \"a in b\"");
    check(!pc.inRange && pc.cmd == "xyzzy",
          "BUG-105(2): the new unknown-command verdict is reachable ONLY behind a real qualifier");
  }
}

// --- O. BS-097 option consume-or-reject net + BS-018 `do`/`run FILE,
// nostop` (BETA campaign Phase A2). ---
//
// BS-097: before this phase, dispatcher.cpp/estimation_m4.cpp/
// eststo_esttab.cpp had exactly 3 ad-hoc "unknown option -> honest reject"
// nets (summarize inline in dispatcher.cpp; handlers.cpp's runRegress;
// estimation_m4.cpp's shared xtreg(fe/re)/logit/probit builder — all
// exercised above by testClusterVceAndUnknownOptionFixes). `margins` had
// ZERO such net (the B6 audit finding this phase is named for). This phase
// adds ONE shared helper (eval::rejectUnknownOptions, eval/errors.h/.cpp —
// PIET's analog of the engine's g_argv_consumed/check_unconsumed_flags E6
// net) and wires it into margins plus 18 more previously-net-less arms.
//
// Each leg below pairs two assertions: (a) a bogus extra option is an
// honest reject that NAMES the bogus token (the primary evidence the net
// works), and (b) for arms with a real recorded shape, the SAME invocation
// internal capture actually captures from debug_all.do still
// succeeds unchanged — that freeze corpus line is quoted in each leg's
// comment as the ground truth being preserved (an over-rejection guard,
// same spirit as testClusterVceAndUnknownOptionFixes's leg (c) above).
//
// tabstat WAS deliberately left un-netted here (debug_all.do's frozen
// `tabstat y x1, by(region) stat(mean sd n)` uses the singular `stat(...)`
// spelling, which the arm only silently defaulted around rather than
// reading) — BUG105-OPTNET-STATVERBS closes that gap by recognizing `stat`
// as a real alias for `stats`/`statistics` in the SAME change that adds the
// net, so the frozen invocation is now honored (not just silently
// defaulted) instead of newly rejected. See its leg below.
// AER FINISH W1a — the table bundle's ONE-CHARACTER option spellings.
//
// W0's replay found six of this bundle's highest-use corpus spellings are one
// character long (`tab y, m` alone is 12 papers / 106 uses) and that PIET
// refused every one with r(198). The refusal was not a defect in the nets:
// eval::resolveOptionAbbrevAcross has a deliberate 2-character floor, because
// widening below it without an oracle row is fabricated parity — the class that
// once let `export delimited using "f.csv", re` OVERWRITE a file. So the fix is
// a MEASURED row, not a looser rule, and this arm is the row's other half.
//
// Oracle: tests/eval/golden/aer_w1/w1a_optmin_pins{,2}.log (StataBE 19.5,
// `sysuse auto`), one prefix per length per option. Both directions are pinned:
// the spelling Stata accepts must now work, and a spelling Stata REFUSES must
// still be refused — `tabulate, n` and `tabulate, no` are r(198) in Stata
// (w1a_optmin_pins2.log), so they stay r(198) here.
//
// `table, contents()` is the arm that must NOT be implemented. This StataBE
// answers it "option contents() not allowed since Stata 17; see help table for
// updated syntax" — at EVERY prefix length including the full spelling. The
// corpus line that spells it (090, 3 papers / 9 uses) therefore does not run in
// this Stata either, so PIET's r(198) is parity, and the pin below is what stops
// a future session from "fixing" it into a divergence.
void testW1aTableOptionMinimums() {
  std::printf("[selftest] --- W1a table bundle: measured 1-char option minimums ---\n");
  namespace fs = std::filesystem;
  // Own workdir AND own SessionState: this arm fits models, and the arms after
  // it replay lastModel/currentHbin (BUG-479's second half).
  std::string workdir = (fs::temp_directory_path() / "piet_native_selftest_w1a").u8string();
  std::error_code ec;
  fs::remove_all(workdir, ec);
  fs::create_directories(workdir, ec);
  piet::SessionState session(workdir);

  auto firstError = [](const nlohmann::ordered_json& blocks) -> nlohmann::ordered_json {
    for (const auto& b : blocks) {
      if (b.is_object() && b.value("type", std::string()) == "error") return b;
    }
    return nlohmann::ordered_json();
  };
  auto ok = [&](const std::string& cmd, const std::string& why) {
    auto err = firstError(piet::dispatch(cmd, session));
    check(err.is_null(), why + (err.is_null() ? "" : " [got: " + err.value("message", std::string()) + "]"));
  };
  auto rejects = [&](const std::string& cmd, const std::string& token, const std::string& why) {
    auto err = firstError(piet::dispatch(cmd, session));
    check(!err.is_null() && err.value("code", std::string()) == "unsupported_option" &&
              err.value("message", std::string()).find(token) != std::string::npos,
          why);
  };

  ok("sysuse fatalities, clear", "W1a setup: `sysuse fatalities, clear` succeeds");

  // tabulate — missing (min 1) and generate (min 1), both MEASURED rc 0 in Stata.
  ok("tabulate year, m", "W1a tabulate: `m` reaches missing() (Stata min 1)");
  ok("tabulate year, missing", "W1a tabulate: the full `missing` spelling still works");
  ok("tabulate year, g(w1atab)", "W1a tabulate: `g()` reaches generate() (Stata min 1)");
  // The narrowing direction. Stata refuses both of these (w1a_optmin_pins2.log),
  // and `n` is a proper prefix of tabulate's `nofreq`, so a looser rule would
  // have silently turned it into a different option.
  rejects("tabulate year, n", "n", "W1a tabulate: `n` stays r(198) — Stata refuses it too");
  rejects("tabulate year, no", "no", "W1a tabulate: `no` stays r(198) — Stata refuses it too");
  rejects("tabulate year, zzzq", "zzzq", "W1a tabulate: an invented option is still named and rejected");

  // estpost — columns (min 1) and statistics (min 1). The colliding sibling for
  // `c` is `casewise`, which takes no argument; the oracle arm passes one.
  ok("regress fatal beertax spirits", "W1a setup: regress seeds an estimate");
  ok("estpost tabstat fatal beertax, c(statistics) statistics(mean sd)",
     "W1a estpost: `c()` reaches columns() (Stata min 1)");
  ok("estpost tabstat fatal beertax, s(mean sd)",
     "W1a estpost: `s()` reaches statistics() (Stata min 1)");

  // esttab — label (min 1). `l` is the spelling two papers write.
  ok("eststo w1am1", "W1a setup: eststo stores the model");
  ok("esttab w1am1 using \"" + workdir + "/w1a_l.txt\", replace l",
     "W1a esttab: `l` reaches label (Stata min 1)");

  // table, contents() — the one that must STAY refused. Parity, not a gap.
  rejects("table year, c(mean fatal)", "c",
          "W1a table: `c()`/`contents()` stays r(198) — Stata 17+ removed the option "
          "(w1a_optmin_pins2.log: \"option contents() not allowed since Stata 17\")");

  // ── W1a-1 (2026-09-14): the two options that were ABSENT from their nets.
  // tabulate nolabel (min 3) -- "display numeric codes rather than value
  // labels". Both directions on one labelled variable: labelled rows without
  // the option (BUG-355's contract), numeric codes with it, the measured
  // refusals around it.
  auto tabRows = [&](const std::string& cmd) {
    std::vector<std::string> out;
    for (const auto& b : piet::dispatch(cmd, session)) {
      if (!b.is_object() || b.value("type", std::string()) != "tabulate") continue;
      if (!b.contains("table") || !b["table"].contains("rows")) continue;
      for (const auto& r : b["table"]["rows"]) out.push_back(r.get<std::string>());
    }
    return out;
  };
  auto has = [](const std::vector<std::string>& v, const std::string& x) {
    return std::find(v.begin(), v.end(), x) != v.end();
  };
  ok("generate byte w1ag = 1 + mod(_n, 3)", "W1a-1 setup: a three-level code");
  ok("label define w1alab 1 \"one\" 2 \"two\"", "W1a-1 setup: label define");
  ok("label values w1ag w1alab", "W1a-1 setup: label values");
  {
    auto labelled = tabRows("tabulate w1ag");
    auto coded = tabRows("tabulate w1ag, nol");
    auto codedFull = tabRows("tabulate w1ag, nolabel");
    if (labelled.empty() || coded.empty()) {
      skip("W1a-1 tabulate nolabel", "tabulate produced no table in this environment");
    } else {
      check(has(labelled, "one") && has(labelled, "two") && has(labelled, "3.0"),
            "W1a-1 tabulate: without nolabel the rows carry the labels (BUG-355's mix holds)");
      check(!has(coded, "one") && !has(coded, "two"),
            "W1a-1 tabulate: `nol` (Stata min 3) drops the label text");
      check(has(coded, "1.0") && has(coded, "2.0") && has(coded, "3.0"),
            "W1a-1 tabulate: `nol` renders the numeric codes Stata prints "
            "(w1a_optmin_pins.log: `tabulate foreign, nol` rows are 0/1)");
      check(coded == codedFull, "W1a-1 tabulate: `nol` and `nolabel` render the same table");
    }
  }
  ok("tabulate w1ag, nokey",
     "W1a-1 tabulate: `nokey` is rc 0 in Stata (w1a_optmin_pins3.log) — a validated no-op here");
  rejects("tabulate w1ag, nolog", "nolog",
          "W1a-1 tabulate: `nolog` stays r(198) — Stata refuses it too (w1a_optmin_pins3.log)");

  // list abbreviate (min 2). `ab(40)` is the corpus spelling (3 papers / 18 uses).
  ok("list fatal in 1/2, ab(40)", "W1a-1 list: `ab()` reaches abbreviate() (Stata min 2)");
  ok("list fatal in 1/2, abbreviate(8)", "W1a-1 list: the full spelling works");
  rejects("list fatal in 1/2, a(40)", "a",
          "W1a-1 list: `a` stays r(198) — Stata refuses it too (w1a_optmin_pins.log)");
  rejects("list fatal in 1/2, ab", "abbreviate",
          "W1a-1 list: bare `ab` with no width is refused — the number IS the option");
  rejects("list fatal in 1/2, ab(x)", "abbreviate", "W1a-1 list: a non-numeric width is refused");

  fs::remove_all(workdir, ec);
}

void testBS097OptionNetAndBS018DoNostop() {
  std::printf(
      "[selftest] --- BS-097 option consume-or-reject net + BS-018 do/run nostop ---\n");
  namespace fs = std::filesystem;
  std::string workdir = (fs::temp_directory_path() / "piet_native_selftest_bs097").u8string();
  std::error_code ec;
  fs::remove_all(workdir, ec);
  fs::create_directories(workdir, ec);

  auto firstBlockOfType = [](const nlohmann::ordered_json& blocks,
                             const std::string& type) -> nlohmann::ordered_json {
    for (const auto& b : blocks) {
      if (b.is_object() && b.value("type", std::string()) == type) return b;
    }
    return nlohmann::ordered_json();
  };
  auto isUnknownOptionReject = [&](const nlohmann::ordered_json& blocks, const std::string& token) {
    auto err = firstBlockOfType(blocks, "error");
    return !err.is_null() && err.value("code", std::string()) == "unsupported_option" &&
           err.value("message", std::string()).find(token) != std::string::npos;
  };

  piet::SessionState session(workdir);
  auto setup1 = piet::dispatch("sysuse fatalities, clear", session);
  check(firstBlockOfType(setup1, "error").is_null(), "BS-097 setup: `sysuse fatalities, clear` succeeds");
  auto setup2 = piet::dispatch("regress fatal beertax spirits", session);
  check(firstBlockOfType(setup2, "error").is_null(),
        "BS-097 setup: `regress fatal beertax spirits` succeeds (seeds lastModel for "
        "margins/test/lincom/nlcom/estat below)");

  // margins — the B6 headline (previously ZERO net).
  {
    auto rej = piet::dispatch("margins, bogusopt", session);
    check(isUnknownOptionReject(rej, "bogusopt"),
          "BS-097 margins: `margins, bogusopt` honestly rejects, naming `bogusopt`");
    auto ok = piet::dispatch("margins, at(beertax=0.5)", session);
    check(firstBlockOfType(ok, "error").is_null(),
          "BS-097 margins over-rejection guard: `margins, at(beertax=0.5)` "
          "(a valid option in the net's allow-list) still succeeds — no over-rejection");
  }

  // AER-B4 margins-dydx-OLS — `margins, dydx(x)` after a linear model.
  // This is the arm BUG-479 is about, restored WITH the fix its entry asks for:
  // the abort it records was this lambda reading `.value("blocks", ...)` off a
  // block ARRAY, in a draft that had no catch yet — not a throw crossing a
  // `noexcept` boundary inside dispatch. With the catch in place the same throw
  // is CAUGHT and reported (measured: `FAIL ... threw instead of reporting:
  // [json.exception.type_error.306] cannot use value() with array`), which is the
  // refutation of that theory. The second half of the fix is the arm's own
  // session, below. Until 2026-09-09 this
  // combination was refused outright (the NB that used to sit above called it
  // a known Stata-divergence); the oracle
  // tests/eval/golden/aer_b4/pins_oracle_r.do:75-79 says Stata answers it
  // rc 0, with dy/dx, std. err., t, P>|t| and the CI ALL equal to the fitted
  // regression's own row for that variable — a linear model's dy/dx IS its
  // coefficient.
  //
  // That identity is the pin, and it is the discriminating one: cobra's
  // cmd_margins AME path has no OLS branch and defaults to `--model logit`
  // (apps/cmds/cmds_postest.cpp:929), so the failure mode this closure had to
  // avoid is a LOGISTIC average marginal effect silently standing in for the
  // coefficient — a number that differs by orders of magnitude, not by
  // rounding. Asserted at EXACT equality (not a tolerance): estimation_m4c's
  // buildLinearAmeRawM4 copies the fitted row, it does not recompute it, so
  // any future re-route through the engine breaks this bit-for-bit.
  try {
    // Its OWN session and scratch dir, not the shared `session` above. The LPM
    // leg has to FIT a second model, and lastModel/currentHbin are exactly what
    // every arm BELOW (test/lincom/nlcom/estat) replays — measured: sharing the
    // session turned three of those RED for reasons that had nothing to do with
    // what they test, and re-seeding the original fit afterwards did NOT
    // reliably put it back. An arm that needs different state gets its own.
    const std::string wd478 = (fs::path(workdir) / "bug478").string();
    std::error_code ec478;
    fs::create_directories(wd478, ec478);
    piet::SessionState session(wd478);
    (void)piet::dispatch("sysuse fatalities, clear", session);
    auto setup2 = piet::dispatch("regress fatal beertax spirits", session);
    // NB: `piet::dispatch` hands this scope the BLOCK ARRAY itself, not a
    // {"blocks": [...]} envelope — same shape firstBlockOfType above iterates.
    auto coefRow = [](const nlohmann::ordered_json& blocks, const char* want) {
      for (const auto& b : blocks) {
        if (!b.is_object() || b.value("type", std::string()) != "estimation") continue;
        for (const auto& row : b.value("coeftable", nlohmann::ordered_json::array()))
          if (row.is_object() && row.value("name", std::string()) == want) return row;
      }
      return nlohmann::ordered_json();
    };
    const auto fitted = coefRow(setup2, "beertax");
    check(!fitted.is_null() && fitted.contains("b"),
          "AER-B4 margins-dydx-OLS setup: the seeding `regress fatal beertax spirits` has a beertax row");

    auto ame = piet::dispatch("margins, dydx(beertax)", session);
    check(firstBlockOfType(ame, "error").is_null(),
          "AER-B4 margins-dydx-OLS: `margins, dydx(beertax)` after `regress` is answered, not refused");
    const auto got = coefRow(ame, "beertax");
    check(!got.is_null(), "AER-B4 margins-dydx-OLS: the margins block carries a `beertax` dy/dx row");
    if (!fitted.is_null() && !got.is_null()) {
      bool same = true;
      for (const char* k : {"b", "se", "t", "p", "ci_lo", "ci_hi"})
        same = same && fitted.contains(k) && got.contains(k) && got[k] == fitted[k];
      check(same,
            "AER-B4 margins-dydx-OLS: every column of the dy/dx row (b/se/t/p/ci) is EXACTLY the fitted "
            "coefficient's — not a logistic AME computed from a defaulted --model");
      // The margins table is the REQUESTED effect only: one row, no intercept,
      // no second covariate. `spirits` is in the model and must not appear.
      bool onlyBeertax = true;
      for (const auto& b : ame) {
        if (!b.is_object() || b.value("type", std::string()) != "estimation") continue;
        onlyBeertax = onlyBeertax && b.value("coeftable", nlohmann::ordered_json::array()).size() == 1;
      }
      check(onlyBeertax,
            "AER-B4 margins-dydx-OLS: dydx(beertax) publishes that one effect — no `spirits`, no `(intercept)`");
    }
    // The refusal narrowed, it did not vanish: a name the model has no
    // coefficient for is still an honest named error, never an empty table.
    auto miss = piet::dispatch("margins, dydx(nosuchvarBUG478)", session);
    const auto missErr = firstBlockOfType(miss, "error");
    const std::string missMsg =
        missErr.is_object() ? missErr.value("message", std::string()) : std::string();
    check(missMsg.find("nosuchvarBUG478") != std::string::npos,
          "AER-B4 margins-dydx-OLS: `margins, dydx(<not a covariate>)` refuses and names the variable");

    // The SILENT half, pinned on its own. Seeding the naive fix (empty
    // kLinearAmeCmds + the five OLS names dropped from kLinearCmds) shows the
    // hazard is narrower than "any linear model" and much sharper where it
    // bites: for a CONTINUOUS outcome cobra's margins(logit) refuses out loud
    // ("outcome 'price' is not binary (found 4099)"), but for a LINEAR
    // PROBABILITY MODEL — a 0/1 outcome, an everyday Stata idiom — it answers
    // rc 0 with the LOGIT average marginal effect and says nothing. Measured
    // on `regress foreign mpg weight` (sysuse auto) under that seed: the LPM
    // coefficient is -.0194295 (se .0126701) and margins returned
    // -.0197187 (se .0096987) — which is, to every digit, what `logit foreign
    // mpg weight` -> `margins, dydx(mpg)` returns. A 31% error in the standard
    // error, from a different estimator, with no return code between them.
    // Nothing above catches that: the arms so far run on a continuous outcome,
    // where the seed trips the engine's binary guard instead.
    (void)piet::dispatch("gen byte ybinBUG478 = spirits > 2", session);
    auto lpmFit = piet::dispatch("regress ybinBUG478 beertax spirits", session);
    const auto lpmRow = coefRow(lpmFit, "beertax");
    check(!lpmRow.is_null(), "AER-B4 margins-dydx-OLS LPM setup: the 0/1-outcome regress has a beertax row");
    auto lpmAme = piet::dispatch("margins, dydx(beertax)", session);
    const auto lpmGot = coefRow(lpmAme, "beertax");
    check(!lpmGot.is_null() && !lpmRow.is_null() && lpmGot.contains("b") &&
              lpmGot["b"] == lpmRow["b"] && lpmGot["se"] == lpmRow["se"],
          "AER-B4 margins-dydx-OLS: after a LINEAR PROBABILITY MODEL the dy/dx is the LPM coefficient "
          "exactly — not the logit AME the engine would compute unasked");
  } catch (const std::exception& e) {
    // A throwing probe is a probe with no verdict: fail loudly rather than
    // abort the whole binary (which would report nothing at all).
    check(false, std::string("AER-B4 margins-dydx-OLS arm threw instead of reporting: ") + e.what());
  }

  // corr/pwcorr/correlate.
  {
    auto rej = piet::dispatch("pwcorr fatal beertax spirits, bogusopt", session);
    check(isUnknownOptionReject(rej, "bogusopt"),
          "BS-097 pwcorr: unknown option honestly rejects, naming it");
    auto ok = piet::dispatch("pwcorr fatal beertax spirits, sig", session);
    check(firstBlockOfType(ok, "error").is_null(),
          "BS-097 pwcorr over-rejection guard: `pwcorr ..., sig` "
          "(freeze corpus shape: `pwcorr y x1 x2, sig`) still succeeds");
  }

  // ttest.
  {
    (void)piet::dispatch("gen ybinBS097 = spirits > 2", session);
    auto rej = piet::dispatch("ttest beertax, by(ybinBS097) bogusopt", session);
    check(isUnknownOptionReject(rej, "bogusopt"), "BS-097 ttest: unknown option honestly rejects, naming it");
    auto ok = piet::dispatch("ttest beertax, by(ybinBS097)", session);
    check(firstBlockOfType(ok, "error").is_null(),
          "BS-097 ttest over-rejection guard: `ttest ..., by(...)` "
          "(freeze corpus shape: `ttest y, by(female)`) still succeeds");
  }

  // test / lincom / nlcom — zero pre-existing consumption (the dispatcher
  // arm forwards only the joined varlist string; parsed.opts was never even
  // passed to the handler before this phase).
  {
    auto rejTest = piet::dispatch("test beertax spirits, bogusopt", session);
    check(isUnknownOptionReject(rejTest, "bogusopt"), "BS-097 test: unknown option honestly rejects, naming it");
    auto okTest = piet::dispatch("test beertax spirits", session);
    check(firstBlockOfType(okTest, "error").is_null(),
          "BS-097 test over-rejection guard: plain `test varlist` (freeze corpus shape) still succeeds");

    auto rejLincom = piet::dispatch("lincom beertax - spirits, bogusopt", session);
    check(isUnknownOptionReject(rejLincom, "bogusopt"),
          "BS-097 lincom: unknown option honestly rejects, naming it");
    auto okLincom = piet::dispatch("lincom beertax - spirits", session);
    check(firstBlockOfType(okLincom, "error").is_null(),
          "BS-097 lincom over-rejection guard: plain `lincom expr` (freeze corpus shape) still succeeds");

    auto rejNlcom = piet::dispatch("nlcom _b[beertax]/_b[spirits], bogusopt", session);
    check(isUnknownOptionReject(rejNlcom, "bogusopt"),
          "BS-097 nlcom: unknown option honestly rejects, naming it");
    auto okNlcom = piet::dispatch("nlcom _b[beertax]/_b[spirits]", session);
    check(firstBlockOfType(okNlcom, "error").is_null(),
          "BS-097 nlcom over-rejection guard: plain `nlcom expr` (freeze corpus shape) still succeeds");
  }

  // eststo/estimates/est — zero pre-existing consumption.
  {
    auto rej = piet::dispatch("eststo mBS097a, bogusopt", session);
    check(isUnknownOptionReject(rej, "bogusopt"), "BS-097 eststo: unknown option honestly rejects, naming it");
    auto ok = piet::dispatch("eststo mBS097a", session);
    check(firstBlockOfType(ok, "error").is_null(),
          "BS-097 eststo over-rejection guard: plain `eststo NAME` (freeze corpus shape) still succeeds");
  }

  // esttab.
  {
    auto setup3 = piet::dispatch("regress fatal spirits", session);
    check(firstBlockOfType(setup3, "error").is_null(), "BS-097 setup: `regress fatal spirits` succeeds");
    (void)piet::dispatch("eststo mBS097b", session);
    auto rej = piet::dispatch("esttab mBS097a mBS097b, bogusopt", session);
    check(isUnknownOptionReject(rej, "bogusopt"), "BS-097 esttab: unknown option honestly rejects, naming it");
    auto ok = piet::dispatch("esttab mBS097a mBS097b, se star(* 0.10 ** 0.05 *** 0.01)", session);
    check(firstBlockOfType(ok, "error").is_null(),
          "BS-097 esttab over-rejection guard: `esttab ..., se star(...)` "
          "(freeze corpus shape: `esttab m1 m2, se star(* 0.10 ** 0.05 *** 0.01)`) still succeeds");
  }

  // estat — diag family (hettest/ovtest/vif/dwatson/bgodfrey/archlm/durbinalt).
  {
    auto setup4 = piet::dispatch("regress fatal beertax spirits", session);
    check(firstBlockOfType(setup4, "error").is_null(), "BS-097 setup: re-`regress fatal beertax spirits` succeeds");
    auto rej = piet::dispatch("estat vif, bogusopt", session);
    check(isUnknownOptionReject(rej, "bogusopt"), "BS-097 estat vif: unknown option honestly rejects, naming it");
    auto ok = piet::dispatch("estat vif", session);
    check(firstBlockOfType(ok, "error").is_null(),
          "BS-097 estat vif over-rejection guard: plain `estat vif` (freeze corpus shape) still succeeds");

    // estat's csdid sub-family net is branch-scoped BY `sub` (event has its
    // own {window, post} known-set; simple/calendar/group/pretrend read
    // none) — this leg does not set up a PIET-native csdid model, so it only
    // proves the net did not get reordered AHEAD of the pre-existing "no
    // csdid result in memory" guard (which must still fire first, unchanged).
    auto noCsdid = piet::dispatch("estat event, bogusopt", session);
    auto errNoCsdid = firstBlockOfType(noCsdid, "error");
    check(!errNoCsdid.is_null() &&
              errNoCsdid.value("message", std::string()).find("no csdid result in memory") !=
                  std::string::npos,
          "BS-097 estat event: without a prior csdid, still reports the pre-existing "
          "\"no csdid result in memory\" guard (the branch-scoped option net does not "
          "run ahead of it)");
  }

  // levelsof.
  {
    auto rej = piet::dispatch("levelsof year, bogusopt", session);
    check(isUnknownOptionReject(rej, "bogusopt"), "BS-097 levelsof: unknown option honestly rejects, naming it");
    auto ok = piet::dispatch("levelsof year, clean", session);
    check(firstBlockOfType(ok, "error").is_null(),
          "BS-097 levelsof over-rejection guard: `levelsof ..., clean` still succeeds");
  }

  // winsor2.
  {
    auto rej = piet::dispatch("winsor2 beertax, cuts(1 99) bogusopt", session);
    check(isUnknownOptionReject(rej, "bogusopt"), "BS-097 winsor2: unknown option honestly rejects, naming it");
    auto ok = piet::dispatch("winsor2 beertax, cuts(1 99)", session);
    check(firstBlockOfType(ok, "error").is_null(),
          "BS-097 winsor2 over-rejection guard: `winsor2 ..., cuts(1 99)` "
          "(freeze corpus shape: `winsor2 y, cuts(1 99)`) still succeeds");

    // BUG-112(4) PIET-half: cuts() must strict-consume each number (mirrors the
    // engine-side collapse pNN fix @9f86577) — a partial-consume token like "5x"
    // used to silently parse as 5.0, so `winsor2 fatal, cuts(5x 95)` succeeded.
    auto badCuts = piet::dispatch("winsor2 beertax, cuts(5x 95)", session);
    auto errBadCuts = firstBlockOfType(badCuts, "error");
    check(!errBadCuts.is_null() &&
              errBadCuts.value("message", std::string()).find("cuts(5x 95)") != std::string::npos,
          "BUG-112(4): winsor2 cuts(5x 95) — partial-consume token \"5x\" is honestly "
          "rejected, not silently read as 5");
  }

  // tabulate/tab/tab1/tab2.
  {
    auto rej = piet::dispatch("tabulate year, bogusopt", session);
    check(isUnknownOptionReject(rej, "bogusopt"), "BS-097 tabulate: unknown option honestly rejects, naming it");
    auto ok = piet::dispatch("tabulate year, sum(beertax)", session);
    check(firstBlockOfType(ok, "error").is_null(),
          "BS-097 tabulate over-rejection guard: `tabulate ..., sum(...)` "
          "(freeze corpus shape: `tabulate region, sum(y)`) still succeeds");
  }

  // table.
  {
    auto rej = piet::dispatch("table year, bogusopt", session);
    check(isUnknownOptionReject(rej, "bogusopt"), "BS-097 table: unknown option honestly rejects, naming it");
    auto ok = piet::dispatch("table year", session);
    check(firstBlockOfType(ok, "error").is_null(),
          "BS-097 table over-rejection guard: plain `table rowvar` (freeze corpus shape) still succeeds");
  }

  // duplicates.
  {
    auto rej = piet::dispatch("duplicates report year, bogusopt", session);
    check(isUnknownOptionReject(rej, "bogusopt"),
          "BS-097 duplicates: unknown option honestly rejects, naming it");
    auto ok = piet::dispatch("duplicates report year", session);
    check(firstBlockOfType(ok, "error").is_null(),
          "BS-097 duplicates over-rejection guard: `duplicates report varlist` "
          "(freeze corpus shape) still succeeds");
  }

  // encode — `state` is the bundled fatalities dataset's one real string
  // column (2-letter state abbreviation), the same role `grp` plays in the
  // kitchensink corpus's own `encode grp, gen(grpn)` frozen fixture.
  {
    auto rej = piet::dispatch("encode state, gen(state_nBS097) bogusopt", session);
    check(isUnknownOptionReject(rej, "bogusopt"), "BS-097 encode: unknown option honestly rejects, naming it");
    auto ok = piet::dispatch("encode state, gen(state_nBS097ok)", session);
    check(firstBlockOfType(ok, "error").is_null(),
          "BS-097 encode over-rejection guard: `encode ..., gen(...)` "
          "(freeze corpus shape: `encode grp, gen(grpn)`) still succeeds");
  }

  // count.
  {
    auto rej = piet::dispatch("count, bogusopt", session);
    check(isUnknownOptionReject(rej, "bogusopt"), "BS-097 count: unknown option honestly rejects, naming it");
    auto ok = piet::dispatch("count", session);
    check(firstBlockOfType(ok, "error").is_null(),
          "BS-097 count over-rejection guard: plain `count` (freeze corpus shape) still succeeds");
  }

  // drop / keep — zero pre-existing consumption. `drop` round-trips a
  // disposable var it creates itself so the reject probe (which must NOT
  // actually drop anything) is verifiable by the accept probe succeeding
  // right after. `keep` only gets the reject probe: shrinking the shared
  // session's varlist here would break every later leg that reuses it.
  {
    (void)piet::dispatch("gen dropProbeBS097 = 1", session);
    auto rej = piet::dispatch("drop dropProbeBS097, bogusopt", session);
    check(isUnknownOptionReject(rej, "bogusopt"), "BS-097 drop: unknown option honestly rejects, naming it");
    auto ok = piet::dispatch("drop dropProbeBS097", session);
    check(firstBlockOfType(ok, "error").is_null(),
          "BS-097 drop over-rejection guard: plain `drop varlist` still succeeds "
          "(also proves the reject probe just above did NOT actually drop the variable)");

    auto rejKeep = piet::dispatch("keep fatal beertax spirits, bogusopt", session);
    check(isUnknownOptionReject(rejKeep, "bogusopt"), "BS-097 keep: unknown option honestly rejects, naming it");
  }

  // append — zero pre-existing consumption (the arm never reads
  // parsed.opts at all; only a regex over parsed.raw + parsed.varlist). The
  // net is the FIRST line in the arm, so it fires before the `using`
  // filename is even parsed — a nonexistent path is enough to prove it,
  // no second on-disk dataset needed for this leg.
  {
    auto rej =
        piet::dispatch("append using \"/nonexistent/piet_bs097_probe.hbin\", bogusopt", session);
    check(isUnknownOptionReject(rej, "bogusopt"),
          "BS-097 append: unknown option honestly rejects, naming it, even when the `using` "
          "file does not exist (the net runs before file resolution)");
  }

  // B5-D10: `append using F, generate(NAME)` -- src marks which rows came
  // from `using` (0 for master, 1 for using). Measured B4REC|append|generate|0|
  // (tests/eval/golden/aer_b4/pins_oracle_r.log:96-97). append is in
  // kOptMinComplete; its GENerate minimum was measured later: `gen(src)` rc 0
  // (aer_w2 w2_data_io.log app9, w2b_dataio append_gen(src)) and `ge(src)`
  // r(198) (w2b_dataio append_ge) -- dispatcher.cpp kOptMinimumsLater.
  {
    std::string agWd = workdir + "/append_gen";
    fs::create_directories(agWd, ec);
    const std::string usingPath = agWd + "/using.hbin";
    {
      piet::SessionState setup(agWd);
      (void)piet::dispatch("clear", setup);
      (void)piet::dispatch("set obs 2", setup);
      (void)piet::dispatch("gen double gid = _n + 10", setup);
      (void)piet::dispatch("save \"" + usingPath + "\", replace", setup);
    }
    piet::SessionState ag(agWd);
    (void)piet::dispatch("clear", ag);
    (void)piet::dispatch("set obs 2", ag);
    (void)piet::dispatch("gen double gid = _n", ag);
    auto genBlocks =
        piet::dispatch("append using \"" + usingPath + "\", generate(srcBS097)", ag);
    check(firstBlockOfType(genBlocks, "error").is_null(),
          "B5-D10: `append using F, generate(NAME)` is accepted (rc 0)");
    piet::Datastore* agDs = ag.datastore();
    bool genOk = agDs != nullptr && agDs->has("srcBS097") && agDs->nRows() == 4;
    check(genOk, "B5-D10: the generate() column is created and the row count is nMaster+nUsing");
    if (genOk) {
      check(agDs->col("srcBS097").f64()[0] == 0.0 && agDs->col("srcBS097").f64()[1] == 0.0 &&
                agDs->col("srcBS097").f64()[2] == 1.0 && agDs->col("srcBS097").f64()[3] == 1.0,
            "B5-D10: generate() marks 0 for the 2 master rows, 1 for the 2 appended using rows");
    }
    // append.ado declares GENerate(name); the abbreviation is measured now
    // (w2aw_data_combine_family.log dc_a_gen `gen(src)` rc 0).
    auto genAbbrev = piet::dispatch("append using \"" + usingPath + "\", gen(srcBS097abbrev)", ag);
    check(firstBlockOfType(genAbbrev, "error").is_null(),
          "B5-D10: `gen(...)` is rc 0 on `append` (w2_data_io.log app9)");
    auto geAbbrev = piet::dispatch("append using \"" + usingPath + "\", ge(srcBS097ge)", ag);
    check(!firstBlockOfType(geAbbrev, "error").is_null(),
          "B5-D10: `ge(...)` stays r(198) on `append` (w2b_dataio append_ge)");
  }

  // hausman (BUG-105 remainder) — previously had NO opts parameter at all
  // (real Stata's constant/sigmamore/sigmaless/force/alleqs are none of them
  // implemented by this handler, which always recomputes both sides from
  // raw data via cobra's own --tidy hausman — a knob-less call), so every
  // one of them silently no-op'd instead of an honest reject.
  {
    (void)piet::dispatch("xtset state_nBS097ok year", session);
    (void)piet::dispatch("xtreg fatal beertax spirits, fe", session);
    (void)piet::dispatch("eststo feHausBS097", session);
    (void)piet::dispatch("xtreg fatal beertax spirits, re", session);
    (void)piet::dispatch("eststo reHausBS097", session);
    auto rej = piet::dispatch("hausman feHausBS097 reHausBS097, bogusopt", session);
    check(isUnknownOptionReject(rej, "bogusopt"),
          "BS-097 hausman: unknown option honestly rejects, naming it (previously had no opts "
          "channel at all)");
    auto ok = piet::dispatch("hausman feHausBS097 reHausBS097", session);
    check(firstBlockOfType(ok, "error").is_null(),
          "BS-097 hausman over-rejection guard: plain `hausman A B` (D5e oracle shape) still "
          "succeeds");

    // BUG-105 secondary ⑤: `alleqs` is real Stata `hausman` syntax ([R]
    // hausman) this handler doesn't implement — distinct wording from the
    // `bogusopt` typo case just above, same "not allowed" code both ways.
    auto rejReal = piet::dispatch("hausman feHausBS097 reHausBS097, alleqs", session);
    auto realErr = firstBlockOfType(rejReal, "error");
    check(!realErr.is_null() &&
              realErr.value("code", std::string()) == "unsupported_option" &&
              realErr.value("message", std::string())
                      .find("is a valid Stata option that this version of PIET does not yet "
                            "implement") != std::string::npos,
          "BUG-105 secondary ⑤: hausman's `alleqs` (a real Stata option this build doesn't "
          "implement) is named as such, not lumped with a bogus typo");
  }

  // BUG-1940: hausman when V_b-V_B is not positive definite. Stata inverts
  // the difference with a generalized inverse and reports the statistic with
  // the note "(V_b-V_B is not positive definite)"; PIET's PSD-clip fallback
  // answered chi2 ~ 2.6e16 (near-singular clipped matrix) or refused with an
  // engine_error. Oracle: StataBE 19.5, 2026-11-06, the bundled fatalities
  // sample imported asdouble, frate = fatal/pop*10000, encode state, xtset:
  //   beertax unemp         -> r(chi2) 1.15382326678694  r(df) 2  r(p) .5616302108923181  (not PD)
  //   beertax spirits unemp -> r(chi2) 70.30558871723755 r(df) 3  r(p) 3.67130877062e-15  (not PD)
  //   beertax spirits       -> r(chi2) 30.02004414363056 r(df) 2  r(p) 3.02851856992e-07  (PD, no note)
  {
    piet::SessionState hs(workdir + "/bug1940");
    std::filesystem::create_directories(workdir + "/bug1940");
    (void)piet::dispatch("sysuse fatalities, clear", hs);
    if (!hs.hasData()) {
      skip("BUG-1940 (all legs)", "`sysuse fatalities` setup returned no data");
    } else {
      (void)piet::dispatch("generate double frate = fatal/pop*10000", hs);
      (void)piet::dispatch("encode state, gen(snum)", hs);
      (void)piet::dispatch("xtset snum year", hs);
      struct Arm { const char* xs; double chi2; int df; double p; bool notpd; };
      const Arm arms[] = {
          {"beertax unemp", 1.15382326678694, 2, 0.5616302108923181, true},
          {"beertax spirits unemp", 70.30558871723755, 3, 3.67130877062e-15, true},
          {"beertax spirits", 30.02004414363056, 2, 3.02851856992e-07, false},
      };
      int armNo = 0;
      for (const Arm& a : arms) {
        ++armNo;
        std::string tag = "h1940_" + std::to_string(armNo);
        (void)piet::dispatch(std::string("xtreg frate ") + a.xs + ", fe", hs);
        (void)piet::dispatch("estimates store " + tag + "f", hs);
        (void)piet::dispatch(std::string("xtreg frate ") + a.xs + ", re", hs);
        (void)piet::dispatch("estimates store " + tag + "r", hs);
        auto blocks = piet::dispatch("hausman " + tag + "f " + tag + "r", hs);
        auto err = firstBlockOfType(blocks, "error");
        nlohmann::ordered_json hb;
        for (const auto& b : blocks)
          if (b.is_object() && b.value("estimator", std::string()) == "hausman") { hb = b; break; }
        std::string label = std::string("BUG-1940 hausman `") + a.xs + "`";
        check(err.is_null() && hb.is_object(),
              label + ": answers with a hausman block, no engine_error (was: refused or chi2 ~ 1e16)");
        if (!hb.is_object()) continue;
        double chi2 = hb.value("chi2", 0.0);
        double p = hb.contains("p") && hb["p"].is_number() ? hb["p"].get<double>() : -1.0;
        check(std::fabs(chi2 - a.chi2) <= 1e-9 * std::fabs(a.chi2),
              label + ": chi2 matches StataBE r(chi2) " + std::to_string(a.chi2) + " at rtol 1e-9, got " +
                  std::to_string(chi2));
        check(hb.value("dof", -1) == a.df,
              label + ": dof is Stata's r(df) " + std::to_string(a.df) + " (the rank of V_b-V_B)");
        check(std::fabs(p - a.p) <= 1e-9 * std::fabs(a.p) + 1e-300,
              label + ": p matches StataBE r(p) at rtol 1e-9, got " + std::to_string(p));
        bool noted = false;
        if (hb.contains("notes"))
          for (const auto& n : hb["notes"])
            if (n.is_string() && n.get<std::string>() == "(V_b-V_B is not positive definite)") noted = true;
        check(hb.value("not_pd", !a.notpd) == a.notpd && noted == a.notpd,
              label + (a.notpd ? ": carries Stata's note \"(V_b-V_B is not positive definite)\""
                               : ": positive definite, so no note"));
      }
    }
  }

  // tabstat (BUG-105 remainder) — `stat`/`stats`/`statistics` are the only
  // options this arm reads; the singular `stat(...)` spelling had to be
  // recognized in the SAME change as the reject net (freeze corpus proof:
  // internal script debug_all.do:92 / class_demo.do:246 both use
  // `stat(mean sd n)` — a net keyed only on {by,stats,statistics} would have
  // newly rejected that exact frozen line instead of preserving it).
  {
    auto rej = piet::dispatch("tabstat beertax spirits, bogusopt", session);
    check(isUnknownOptionReject(rej, "bogusopt"),
          "BS-097 tabstat: unknown option honestly rejects, naming it");
    auto ok = piet::dispatch("tabstat beertax spirits, stat(mean sd n)", session);
    check(firstBlockOfType(ok, "error").is_null(),
          "BS-097 tabstat over-rejection guard: `tabstat ..., stat(mean sd n)` (freeze corpus "
          "shape: debug_all.do:92 / class_demo.do:246, singular `stat`) still succeeds");
  }

  // egen (BUG-105 remainder) — cobra's OWN `--egen` CLI parsing never
  // validates its comma-suffix tail at all (live-verified against the
  // compiled engine: `--egen "x=mean(v),bogusopt(5)"` -> exit 0, x computed,
  // bogusopt silently dropped), so verbatim passthrough via buildOptsSuffix
  // reached NO rejecting net anywhere until egen.cpp's own PIET-layer check
  // added this phase (the judgment call this BUG-105 sub-item required).
  {
    auto rej = piet::dispatch("egen meanBS097 = mean(beertax), bogusopt", session);
    check(isUnknownOptionReject(rej, "bogusopt"), "BS-097 egen: unknown option honestly rejects, naming it");
    auto ok = piet::dispatch("egen meanBS097ok = mean(beertax), by(state_nBS097ok)", session);
    check(firstBlockOfType(ok, "error").is_null(),
          "BS-097 egen over-rejection guard: `egen ... = mean(v), by(g)` still succeeds");
  }

  // --- BS-018: `do`/`run FILE [args] [, nostop]` option parse ---
  //
  // Previously there was no comma handling in the do/run pre-classify step
  // at all: `do file.do, nostop` let the comma glue onto the end of the
  // filename token (scanOneToken stops at whitespace, not ','), so the path
  // never resolved; `do file.do , nostop` (space before the comma) instead
  // shredded ","/"nostop" into the positional-args vector. `nostop` itself
  // is now parsed/consumed (so it hits neither failure mode); its "continue
  // past an error instead of stopping the do-file" semantic is a SEPARATE
  // follow-up — doexec's stop-on-first-error loop is intentionally
  // unchanged here (out of BS-018's parsing-bug scope; see the return
  // summary).
  {
    std::string doFile = workdir + "/bs018_probe.do";
    {
      std::ofstream f(cecon::to_native_path(doFile));
      f << "gen bs018Marker = 1\n";
    }

    // (a) `do FILE, nostop` resolves FILE correctly.
    piet::SessionState s1(workdir);
    (void)piet::dispatch("sysuse fatalities, clear", s1);
    auto r1 = piet::dispatch("do \"" + doFile + "\", nostop", s1);
    check(s1.hasData() && s1.datastore() != nullptr && s1.datastore()->has("bs018Marker"),
          "BS-018: `do FILE, nostop` resolves FILE correctly and runs it (previously the "
          "comma glued onto the filename, breaking resolution outright)");
    bool sawFileError = false;
    for (const auto& b : r1) {
      if (b.is_object() && b.value("type", std::string()) == "error" &&
          b.value("message", std::string()).find("not found") != std::string::npos) {
        sawFileError = true;
      }
    }
    check(!sawFileError, "BS-018: no \"file not found\"-shaped error for `do FILE, nostop`");

    // (b) a space before the comma — the OTHER shape the bug report called
    // out (","/"nostop" shredded into positional args, corrupting `1'`/`2'`).
    piet::SessionState s2(workdir);
    (void)piet::dispatch("sysuse fatalities, clear", s2);
    (void)piet::dispatch("do \"" + doFile + "\" , nostop", s2);
    check(s2.hasData() && s2.datastore() != nullptr && s2.datastore()->has("bs018Marker"),
          "BS-018: `do FILE , nostop` (space before the comma) also resolves FILE correctly");

    // (c) a genuinely-unknown do/run option is still an honest reject
    // (BS-097 synergy: the do/run options tail now goes through the SAME
    // shared net as every other arm).
    piet::SessionState s3(workdir);
    auto r3 = piet::dispatch("do \"" + doFile + "\", bogusopt", s3);
    check(isUnknownOptionReject(r3, "bogusopt"),
          "BS-018/BS-097: `do FILE, bogusopt` honestly rejects, naming it");

    // (d) plain `do FILE` (no comma at all) is completely unaffected — the
    // common case, and the one every existing do-file invocation relies on.
    piet::SessionState s4(workdir);
    (void)piet::dispatch("sysuse fatalities, clear", s4);
    (void)piet::dispatch("do \"" + doFile + "\"", s4);
    check(s4.hasData() && s4.datastore() != nullptr && s4.datastore()->has("bs018Marker"),
          "BS-018 regression guard: plain `do FILE` (no options at all) is unaffected");
  }

  fs::remove_all(workdir, ec);
}

void testSuccessfulReg3TestLincomResetRc() {
  std::printf("[selftest] --- successful reg3/test/lincom reset stale _rc ---\n");
  namespace fs = std::filesystem;
  std::string workdir =
      (fs::temp_directory_path() / "piet_native_selftest_success_rc").u8string();
  std::error_code ec;
  fs::remove_all(workdir, ec);
  fs::create_directories(workdir, ec);

  auto hasError = [](const nlohmann::ordered_json& blocks) {
    for (const auto& b : blocks) {
      if (b.is_object() && b.value("type", std::string()) == "error") return true;
    }
    return false;
  };

  piet::SessionState session(workdir);
  auto opened = piet::dispatch("sysuse fatalities, clear", session);
  check(!hasError(opened), "stale _rc setup: `sysuse fatalities, clear` succeeds");

  session.eval.locals.set("_rc", "198");
  auto reg3 = piet::dispatch("reg3 (income beertax spirits) (emppop unemp income)", session);
  check(!hasError(reg3), "stale _rc: target `reg3` succeeds");
  check(session.eval.locals.get("_rc", "") == "0",
        "stale _rc: successful `reg3` resets seeded _rc=198 to 0");

  auto fitted = piet::dispatch("regress income beertax spirits", session);
  check(!hasError(fitted), "stale _rc setup: `regress income beertax spirits` succeeds");

  // BUG-1509 re-pin: test.ado runs no internal capture, so StataBE 19.5 leaves
  // `_rc` as it was (scratch-laneA/agents/file-new-1/i4b.do `RS2|test x1|111`,
  // rlife/side.do `PO|test x1|rc=111`).
  session.eval.locals.set("_rc", "1");
  auto test = piet::dispatch("test beertax spirits", session);
  check(!hasError(test), "stale _rc: target `test` succeeds");
  check(session.eval.locals.get("_rc", "") == "1",
        "stale _rc: successful `test` leaves a seeded _rc=1 alone (BUG-1509)");

  session.eval.locals.set("_rc", "1");
  auto lincom = piet::dispatch("lincom beertax - spirits", session);
  check(!hasError(lincom), "stale _rc: target `lincom` succeeds");
  check(session.eval.locals.get("_rc", "") == "0",
        "stale _rc: successful `lincom` resets seeded _rc=1 to 0");

  fs::remove_all(workdir, ec);
}

// --- P. BETA campaign Phase A3: registry-driven qualifier policy table
// (BS-096) + D7 `in` mapping. ------------------------------------------
//
// A3 replaced eval/tokenizer.cpp's two hardcoded qualifier allow-lists
// (weight, `in`) with lookups against the SAME registry A0 built
// (registry::findByName()), and taught dispatcher.cpp's by:/bysort:
// fallback reject to distinguish Stata-structurally-illegal stems
// (codebook/describe/levelsof/table — audit G3) from Stata-legal-but-
// not-yet-implemented ones (everything else reaching that fallback) via
// the new CommandSpec::byIllegalInStata field. This leg is the
// policy-matrix gate BS-096's own SCOPE.md row calls for: a representative
// {command x qualifier} grid asserting LEGAL cells still pass through
// UNCHANGED (the freeze-preservation promise) and ILLEGAL cells reject
// with a command-aware — not command-blind — message.
void testBS096QualifierPolicyTable() {
  std::printf("[selftest] --- BS-096 qualifier policy table (BETA A3) ---\n");

  using piet::eval::tokenize;
  using piet::eval::TokenizerError;

  // --- registry sanity: byIllegalInStata lands on EXACTLY the 4
  // confirmed-illegal rows and nothing else — a drift guard for this new
  // field, same spirit as testRegistryRoutes() above. ------------------
  {
    int illegalCount = 0;
    // T7 (package-007 unblock) adds `lookfor`: StataBE answers a by-prefixed
    // lookfor with r(190) (lane L1 probe), so it is the fifth stem.
    bool codebookOk = false, describeOk = false, levelsofOk = false, tableOk = false;
    bool lookforOk = false;
    for (const auto& spec : piet::registry::commandRegistry()) {
      if (!spec.byIllegalInStata) continue;
      ++illegalCount;
      if (spec.canonical == "codebook") codebookOk = true;
      else if (spec.canonical == "describe") describeOk = true;
      else if (spec.canonical == "levelsof") levelsofOk = true;
      else if (spec.canonical == "table") tableOk = true;
      else if (spec.canonical == "lookfor") lookforOk = true;
    }
    check(illegalCount == 5 && codebookOk && describeOk && levelsofOk && tableOk && lookforOk,
          "A3: registry byIllegalInStata is set on exactly {codebook, describe, levelsof, table, "
          "lookfor} (audit G3's 4 Stata-structurally-illegal-with-by stems, plus lookfor from T7), "
          "nothing more/less");
  }

  // --- weight policy: LEGAL cells pass through unchanged ----------------
  try {
    auto pc = tokenize("summarize wage [fweight=x1]");
    check(pc.weightType && *pc.weightType == "fweight",
          "A3 weight: summarize+fweight still legal (freeze-preservation)");
  } catch (const TokenizerError&) {
    check(false, "A3 weight: summarize+fweight must NOT throw (freeze-preservation)");
  }
  try {
    auto pc = tokenize("tabulate industry [fw=x1]");
    check(pc.weightType && *pc.weightType == "fw",
          "A3 weight: tabulate+fw (abbrev spelling) still legal (freeze-preservation)");
  } catch (const TokenizerError&) {
    check(false, "A3 weight: tabulate+fw must NOT throw (freeze-preservation)");
  }

  // --- weight policy: ILLEGAL cells reject, command-aware ---------------
  // (a) zero weight support anywhere (corr — WeightPolicy::None, untouched
  // by the P3 weights wave) -> message NAMES it (was fully command-blind
  // before A3 — audit g#15/SCOPE.md BS-105). `regress` used to be this
  // probe's command but moved to WeightPolicy::AllWeights in P3 — see
  // testP3WeightsWave below for its newly-legal cells.
  // `corr` was this probe's command until BUG-1014 served correlate's [aw=]/[fw=]
  // (help correlate; w2aj_qualifiers.log:1869 qf_co_aw rc 0), then `tobit` until
  // BUG-1544 served its weights; `reg3` stays WeightPolicy::None while help reg3
  // allows aweights and fweights -- an engine gap.
  try {
    tokenize("reg3 y x1 [aw=x2]");
    check(false, "A3 weight: reg3+aweight must still throw (WeightPolicy::None)");
  } catch (const TokenizerError& e) {
    check(e.block.at("code") == "unsupported_option", "A3 weight: reg3+aweight -> unsupported_option");
    std::string msg = e.block.at("message").get<std::string>();
    check(msg.find("reg3") != std::string::npos,
          "A3 weight: reject message NAMES the command (was command-blind pre-A3) — got: " + msg);
  }
  try {
    auto pc = tokenize("corr x1 x2 [aw=x2]");
    check(pc.weightType && *pc.weightType == "aw",
          "A3 weight: corr+aweight is LEGAL now, as Stata's (help correlate; "
          "w2aj_qualifiers.log:1869 qf_co_aw rc 0)");
  } catch (const TokenizerError&) {
    check(false, "A3 weight: corr+aweight must NOT throw (help correlate)");
  }
  // (b) fweight-only command given a DIFFERENT weight type -> message
  // distinguishes "fweight-only" from "no weight support at all" (the
  // g#15/BS-105 nuance). `tabulate` was this probe's command until the
  // qualifier wave served [aw=]/[iw=] (f8413c27; w2aj_qualifiers.log:2041
  // qf_tb_aw_sp rc 0), then `collapse` until it served its documented
  // `[aw fw iw pw]` (w2au_collapse_family.log cz_c_w_aweight rc 0); `tab2` keeps
  // FweightOnly and refuses an aweight in Stata's own words.
  try {
    tokenize("tab2 x1 x2 [aweight=x1]");
    check(false, "A3 weight: tab2+aweight must still throw (FweightOnly in this engine)");
  } catch (const TokenizerError& e) {
    std::string msg = e.block.at("message").get<std::string>();
    check(msg.find("aweights not allowed") != std::string::npos,
          "A3 weight: tab2+aweight is refused as `aweights not allowed` — got: " + msg);
  }
  try {
    auto pc = tokenize("collapse (mean) x1 [aweight=x1]");
    check(pc.weightType && *pc.weightType == "aweight",
          "A3 weight: collapse+aweight is LEGAL now (collapse takes [aw fw iw pw]; "
          "w2au_collapse_family.log cz_c_w_aweight rc 0)");
  } catch (const TokenizerError&) {
    check(false, "A3 weight: collapse+aweight must NOT throw (collapse takes aweight)");
  }
  try {
    auto pc = tokenize("tabulate industry [aweight=x1]");
    check(pc.weightType && *pc.weightType == "aweight",
          "A3 weight: tabulate+aweight is LEGAL now (help tabulate_oneway; "
          "w2aj_qualifiers.log:2041 qf_tb_aw_sp rc 0)");
  } catch (const TokenizerError&) {
    check(false, "A3 weight: tabulate+aweight must NOT throw (help tabulate_oneway)");
  }
  // (c) a `bysort`-prefixed line: the weight is the SUB-command's; the outer
  // pass carries it and the by-driver's re-tokenize of the sub-command gates it
  // (SUM-BYWEIGHT, w2as_summary_stats_family sx_cumul_by_equal rc 0).
  try {
    auto pc = tokenize("bysort grp: summarize wage [fw=x1]");
    check(true, "A3 weight: bysort-prefixed weight passes the outer token");
    (void)pc;
  } catch (const TokenizerError&) {
    check(false, "A3 weight: bysort-prefixed weight must not be refused by the outer token");
  }

  // --- `in` policy: LEGAL cells pass through unchanged (D7) -------------
  try {
    auto pc = tokenize("list id year in 1/5");
    check(pc.inRange && *pc.inRange == "1/5", "A3/D7 in: list+in still legal (freeze-preservation)");
  } catch (const TokenizerError&) {
    check(false, "A3/D7 in: list+in must NOT throw (freeze-preservation)");
  }
  try {
    auto pc = tokenize("gen byte flag = 1 in 1/5");
    check(pc.inRange && *pc.inRange == "1/5", "A3/D7 in: gen+in still legal (freeze-preservation)");
  } catch (const TokenizerError&) {
    check(false, "A3/D7 in: gen+in must NOT throw (freeze-preservation)");
  }

  // --- `in` policy: ILLEGAL cells reject, command-aware ------------------
  // BS-090 (BETA campaign, Phase G): this leg used to name `summarize` —
  // summarize's allowInRange is now TRUE (see testBS090InRangeExpansion
  // below for its own dedicated positive coverage), so this leg was
  // repointed at `tabstat`, deliberately left OUT of BS-090's flip list
  // (tabstat/tobit share applyIfFilterM4 with corr/ttest but their call
  // sites still pass no inRange argument — registry.cpp's own comment).
  try {
    tokenize("tabstat wage in 1/5");
    check(false, "A3/D7 in: tabstat+in must still throw (freeze-preservation; BS-090 left it "
                 "out of scope)");
  } catch (const TokenizerError& e) {
    std::string msg = e.block.at("message").get<std::string>();
    check(msg.find("tabstat") != std::string::npos,
          "A3/D7 in: reject message NAMES the command (was command-blind pre-A3) — got: " + msg);
  }
  // BS-090: egen's allowInRange is now TRUE (flipped this phase — real
  // `in`-range support, reusing the SAME synthetic row-index column the
  // if-merge-back path already materializes; see egen.cpp's runEgen) —
  // this leg used to assert the opposite ("must still throw", Phase-F
  // scope). Flipped to a positive legality check; the actual composition
  // behavior (in ANDed with if, correct group-relative merge-back) is
  // exercised end-to-end by testBS090InRangeExpansion below.
  try {
    auto pc = tokenize("egen newv = mean(x1) in 1/5");
    check(pc.inRange && *pc.inRange == "1/5", "BS-090: egen+in now legal (allowInRange flipped)");
  } catch (const TokenizerError&) {
    check(false, "BS-090: egen+in must NOT throw (allowInRange flipped true this phase)");
  }

  // --- D7 end-to-end: `in` composes with `if` (AND) on a legal command --
  {
    namespace fs = std::filesystem;
    std::string workdir = (fs::temp_directory_path() / "piet_native_selftest_bs096_d7").u8string();
    std::error_code ec;
    fs::remove_all(workdir, ec);
    fs::create_directories(workdir, ec);
    piet::SessionState session(workdir);
    (void)piet::dispatch("sysuse fatalities, clear", session);
    auto blocks = piet::dispatch("list state year if year>=1983 in 1/3", session);
    bool sawBrowse = false;
    bool sawError = false;
    for (const auto& b : blocks) {
      if (b.is_object() && b.value("type", std::string()) == "browse") sawBrowse = true;
      if (b.is_object() && b.value("type", std::string()) == "error") sawError = true;
    }
    check(sawBrowse && !sawError,
          "A3/D7: `list ... if COND in a/b` composes both qualifiers on a legal command "
          "(no error, produces a browse block)");
    fs::remove_all(workdir, ec);
  }

  // --- by-gate: structurally-illegal stems get the NEW honest message;
  // Stata-legal-but-unimplemented stems KEEP the old "not supported yet"
  // wording; the real gen/replace/egen implementation is untouched. All
  // via full dispatch() since the by-gate lives in dispatcher.cpp, not
  // the tokenizer. -------------------------------------------------------
  {
    namespace fs = std::filesystem;
    std::string workdir = (fs::temp_directory_path() / "piet_native_selftest_bs096_by").u8string();
    std::error_code ec;
    fs::remove_all(workdir, ec);
    fs::create_directories(workdir, ec);

    auto firstError = [](const nlohmann::ordered_json& blks) -> nlohmann::ordered_json {
      for (const auto& b : blks) {
        if (b.is_object() && b.value("type", std::string()) == "error") return b;
      }
      return nlohmann::ordered_json();
    };

    // (a) codebook: structurally illegal in Stata -> NEW wording, no more
    // misleading "not supported yet" (audit G3 finding #10).
    {
      piet::SessionState session(workdir);
      (void)piet::dispatch("sysuse fatalities, clear", session);
      auto blocks = piet::dispatch("bysort state: codebook year", session);
      auto err = firstError(blocks);
      check(!err.is_null(), "A3 by-gate: `bysort: codebook` still rejects (freeze-preservation)");
      std::string msg = err.value("message", std::string());
      check(msg.find("not supported yet") == std::string::npos &&
                msg.find("may not be combined") != std::string::npos,
            "A3 by-gate: `bysort: codebook` gets the NEW honest 'Stata disallows this' wording, "
            "not the misleading 'not supported yet' text (audit G3#10/BS-096) — got: " + msg);
    }
    // (b) describe: same illegal bucket as codebook.
    {
      piet::SessionState session(workdir);
      (void)piet::dispatch("sysuse fatalities, clear", session);
      auto blocks = piet::dispatch("bysort state: describe", session);
      auto err = firstError(blocks);
      check(!err.is_null(), "A3 by-gate: `bysort: describe` still rejects (freeze-preservation)");
      std::string msg = err.value("message", std::string());
      check(msg.find("not supported yet") == std::string::npos,
            "A3 by-gate: `bysort: describe` drops the misleading 'not supported yet' text — got: " + msg);
    }
    // (c) count: graduated out of the BS-107 "not supported yet" bucket (FU-163):
    // `bysort state: count` now runs per group, so it raises no error block.
    // (BS-092 had repointed this leg from summarize to count for the same reason.)
    {
      piet::SessionState session(workdir);
      (void)piet::dispatch("sysuse fatalities, clear", session);
      auto blocks = piet::dispatch("bysort state: count", session);
      check(firstError(blocks).is_null(),
            "A3 by-gate: `bysort: count` runs per group (FU-163, graduated out of BS-107)");
    }
    // (d) gen: the REAL by-group implementation is untouched by this
    // message-only refactor — regression guard.
    {
      piet::SessionState session(workdir);
      (void)piet::dispatch("sysuse fatalities, clear", session);
      auto blocks = piet::dispatch("bysort state: gen byte flag = 1", session);
      auto err = firstError(blocks);
      check(err.is_null(), "A3 by-gate regression guard: `bysort: gen` still WORKS (real "
                            "implementation untouched by the message-only refactor)");
    }

    fs::remove_all(workdir, ec);
  }
}

// --- P3 weights wave: registry.cpp's WeightPolicy grew from a 2-value
// (None/FweightOnly) blanket rule into a genuine per-command allow-set
// (AweightFweight on summarize, PweightOnly on the new mean/proportion rows,
// AllWeights on regress/reghdfe/feols) — the engine side (cobra) is being
// taught real weighted estimation in a parallel stint, so PIET's job here is
// to stop REJECTING the newly-legal combinations and forward them, without
// loosening anything that's still genuinely unsupported.
//
// NOTE: cobra itself may not have landed every new flag yet at the time this
// runs (concurrent engine work) — so the dispatch-level legs below only
// assert ROUTING (the tokenizer let the qualifier through and the real
// handler ran, same "not unsupported_command/unsupported_option" bar
// testRegistryRoutes() uses), never a specific numeric result. The
// TOKENIZER-level legs (no cobra invocation at all) are the ones asserting
// the actual policy — parses/doesn't-throw, or throws with the right
// command-aware message.
void testP3WeightsWave() {
  std::printf("[selftest] --- P3 weights wave: registry-driven weight policy expansion ---\n");

  using piet::eval::tokenize;
  using piet::eval::TokenizerError;

  // --- registry sanity: the exact rows this wave was supposed to move,
  // and nothing else — a drift guard mirroring testBS096's byIllegalInStata
  // leg above. ------------------------------------------------------------
  {
    using piet::registry::WeightPolicy;
    auto policyOf = [](const std::string& canon) -> std::optional<WeightPolicy> {
      const auto* spec = piet::registry::findByName(canon);
      return spec ? std::optional<WeightPolicy>(spec->weight) : std::nullopt;
    };
    check(policyOf("regress") == WeightPolicy::AllWeights, "P3: regress row is AllWeights");
    check(policyOf("reghdfe") == WeightPolicy::AllWeights, "P3: reghdfe row is AllWeights");
    // summarize serves [iw=] since the residual sweep (help summarize; w2aj
    // qf_sw_iw_tight), pweight still Stata's r(101) via kStataLegalWeights; mean
    // takes every type (help mean; the engine serves pw and aw, w2aj
    // qf_mn_aw_sp, and refuses fw/iw by name).
    check(policyOf("summarize") == WeightPolicy::AllWeights, "P3: summarize row is AllWeights");
    check(policyOf("mean") == WeightPolicy::AllWeights, "P3: mean row is AllWeights");
    // proportion takes fweights and iweights too since BUG-1541; its aweight is
    // Stata's r(101) via kStataLegalWeights (StataBE 19.5, scratch-laneA2/agents/wml/x1.log).
    check(policyOf("proportion") == WeightPolicy::AllWeights, "P3: proportion row is AllWeights (BUG-1541)");
    // Regression guard: the OLD FweightOnly allow-list members that did NOT
    // move this wave stay exactly where they were.
    check(policyOf("tab2") == WeightPolicy::FweightOnly, "P3: tab2 row still FweightOnly (unchanged)");
    // collapse moved later: it takes aw, fw, iw and pw weights (w2au_collapse_family.log cz_c_w_*).
    check(policyOf("collapse") == WeightPolicy::AllWeights, "P3: collapse row is AllWeights");
    // Rows LATER waves moved, each to the set Stata documents: tabulate/tab1 serve
    // [aw=]/[iw=] since the qualifier wave (f8413c27; help tabulate_oneway,
    // w2aj_qualifiers.log:2041 qf_tb_aw_sp, :2065 qf_tb_iw_sp), with pweight refused
    // as Stata's r(101) by the tokenizer's kStataLegalWeights row; corr/pwcorr serve
    // [aw=]/[fw=] since BUG-1014 (help correlate; w2aj_qualifiers.log:1869 qf_co_aw).
    check(policyOf("tabulate") == WeightPolicy::AllWeights, "P3: tabulate row is AllWeights (qualifier wave)");
    check(policyOf("tab1") == WeightPolicy::AllWeights, "P3: tab1 row is AllWeights (qualifier wave)");
    check(policyOf("corr") == WeightPolicy::AweightFweight, "P3: corr row is AweightFweight (BUG-1014)");
    // A command no wave touched (still None) — spot-check one. (tobit was this
    // check's command until BUG-1544 served its four weight types.)
    check(policyOf("reg3") == WeightPolicy::None, "P3: reg3 row still None (unchanged)");
  }

  // --- tokenizer level: every newly-allowed (command, weight-type) pair
  // parses without throwing, and pc.weightType/weightVar carry the exact
  // spelling the user typed. -----------------------------------------------
  {
    static const std::vector<std::pair<std::string, std::string>> kNewlyLegal = {
        {"regress y x1 [aw=w]", "aw"},       {"regress y x1 [aweight=w]", "aweight"},
        {"regress y x1 [fw=w]", "fw"},       {"regress y x1 [fweight=w]", "fweight"},
        {"regress y x1 [iw=w]", "iw"},       {"regress y x1 [iweight=w]", "iweight"},
        {"regress y x1 [pw=w]", "pw"},       {"regress y x1 [pweight=w]", "pweight"},
        {"reghdfe y x1 [pw=w]", "pw"},       {"summarize wage [aw=w]", "aw"},
        {"summarize wage [aweight=w]", "aweight"}, {"mean wage [pw=w]", "pw"},
        {"mean wage [pweight=w]", "pweight"}, {"proportion state [pw=w]", "pw"},
        {"proportion state [pweight=w]", "pweight"}, {"proportion state [fw=w]", "fw"},
        {"proportion state [iw=w]", "iw"},
    };
    for (const auto& [line, expectType] : kNewlyLegal) {
      try {
        auto pc = tokenize(line);
        check(pc.weightType && *pc.weightType == expectType && pc.weightVar && *pc.weightVar == "w",
              "P3 weight: newly-legal `" + line + "` parses (weightType/weightVar captured)");
      } catch (const TokenizerError& e) {
        check(false, "P3 weight: newly-legal `" + line +
                         "` must NOT throw — got: " + e.block.value("message", std::string()));
      }
    }
  }

  // --- tokenizer level: pairs that are STILL illegal after this wave reject
  // with a command-aware message (a narrower allow-set does not become a
  // blanket one). -----------------------------------------------------------
  {
    // proportion: fw/iw are legal since BUG-1541 (above); its aweight is Stata's
    // own r(101) `aweights not allowed` (StataBE 19.5, scratch-laneA2/agents/wml/
    // x1.log). (mean admits every type since the residual sweep, see the row check.)
    {
      const std::string line = "proportion wage [aw=w]";
      try {
        tokenize(line);
        check(false, "P3 weight: `" + line + "` must still throw (Stata's r(101))");
      } catch (const TokenizerError& e) {
        check(e.block.value("code", std::string()) == "engine_error" &&
                  e.block.value("reason", std::string()) == "r(101)" &&
                  e.block.value("message", std::string()) == "aweights not allowed",
              "P3 weight: `" + line + "` is Stata's r(101) `aweights not allowed` — got: " +
                  e.block.dump());
      }
    }
    // summarize: pw is illegal in Stata itself (r(101) "pweights not allowed";
    // oracle w2_pweight.log:764-768 S1_summarize_pw_refused, aer_b4
    // esttab-beta.log:338). iw is served now (QF-SUM-IW, w2aj_qualifiers.log:826).
    for (const std::string wt : {"pw"}) {
      std::string line = "summarize wage [" + wt + "=w]";
      try {
        tokenize(line);
        check(false, "P3 weight: `" + line + "` must still throw (AweightFweight)");
      } catch (const TokenizerError& e) {
        std::string msg = e.block.value("message", std::string());
        if (wt == "pw") {
          check(e.block.value("code", std::string()) == "engine_error" &&
                    e.block.value("reason", std::string()) == "r(101)" &&
                    msg == "pweights not allowed",
                "P3 weight: `" + line + "` is Stata's r(101) `pweights not allowed` — got: " +
                    e.block.dump());
        } else {
          check(msg.find("summarize") != std::string::npos && msg.find("analytic") != std::string::npos,
                "P3 weight: `" + line + "` names the command AND clarifies analytic-or-frequency — got: " + msg);
        }
      }
    }
  }

  // --- full dispatch: newly-legal weights REACH the real handler (routing
  // only — cobra's own new flags may still be landing concurrently, so this
  // never asserts a specific numeric result, only "not a qualifier-gap
  // reject"). ----------------------------------------------------------------
  {
    namespace fs = std::filesystem;
    std::string workdir = (fs::temp_directory_path() / "piet_native_selftest_p3_weights").u8string();
    std::error_code ec;
    fs::remove_all(workdir, ec);
    fs::create_directories(workdir, ec);

    auto routedOk = [](const nlohmann::ordered_json& blocks) {
      for (const auto& b : blocks) {
        if (!b.is_object() || b.value("type", std::string()) != "error") continue;
        std::string code = b.value("code", std::string());
        if (code == "unsupported_command" || code == "unsupported_option") return false;
      }
      return true;
    };

    {
      piet::SessionState session(workdir);
      (void)piet::dispatch("sysuse fatalities, clear", session);
      auto blocks = piet::dispatch("regress fatal beertax [aw=beertax]", session);
      check(routedOk(blocks), "P3 weight: `regress ... [aw=]` reaches the real handler (not a qualifier reject)");
    }
    {
      piet::SessionState session(workdir);
      (void)piet::dispatch("sysuse fatalities, clear", session);
      auto blocks = piet::dispatch("mean beertax [pw=fatal]", session);
      check(routedOk(blocks), "P3 weight: `mean ... [pw=]` reaches the real handler (not a qualifier reject)");
    }
    {
      piet::SessionState session(workdir);
      (void)piet::dispatch("sysuse fatalities, clear", session);
      auto blocks = piet::dispatch("proportion beertax [pw=fatal]", session);
      check(routedOk(blocks),
            "P3 weight: `proportion ... [pw=]` reaches the real handler (not a qualifier reject)");
    }
    {
      // Bare `mean`/`proportion` (registry drift guard's own probe shape,
      // testRegistryRoutes above) — must land on the handler's own
      // "requires at least one variable" syntax_error, never fall through
      // to unsupported_command.
      piet::SessionState session(workdir);
      (void)piet::dispatch("sysuse fatalities, clear", session);
      auto blocks = piet::dispatch("mean", session);
      bool sawSyntaxError = false;
      for (const auto& b : blocks) {
        if (b.is_object() && b.value("type", std::string()) == "error" &&
            b.value("code", std::string()) == "syntax_error") {
          sawSyntaxError = true;
        }
      }
      check(sawSyntaxError, "P3 weight: bare `mean` (no varlist) is an honest syntax_error, not a crash");
    }

    fs::remove_all(workdir, ec);
  }
}

// --- O. BETA Phase A4 — context spine (BS-013/046/047/048/091/098/100/101) -
// One leg per mechanism, mirroring the A1-A3 phases' "focused leg per named
// defect" convention. None of these are exercised by the frozen kitchensink
// corpus (verified at implementation time: debug_all.do's ONE post-
// estimation section uses a plain, unclustered `regress` and is truncated by
// an earlier, unrelated `predict ck, cooksd` MUST-ERROR probe before it ever
// reaches test/lincom/nlcom/estat/margins; it also has zero capture/_rc,
// zero c(...) tokens, and zero `set level|clevel|seed|graphics` lines) — so
// these selftest legs are the ONLY exercise of this phase's fix, in-process.

void testBS013VceInheritancePostEstimation() {
  std::printf("[selftest] --- BS-013/BS-098 lastModel vcov/cluster inheritance: "
              "test/lincom/nlcom no longer silently revert to iid ---\n");
  namespace fs = std::filesystem;
  std::string workdir = (fs::temp_directory_path() / "piet_native_selftest_bs013").u8string();
  std::error_code ec;
  fs::remove_all(workdir, ec);
  fs::create_directories(workdir, ec);

  auto runCmd = [](piet::SessionState& session, const std::string& cmd) {
    nlohmann::json body{{"cmd", cmd}};
    auto r = piet::routes::command(session, body.dump());
    return nlohmann::json::parse(r.json);
  };
  auto firstBlockOfType = [](const nlohmann::json& j, const std::string& type) -> nlohmann::json {
    for (const auto& b : j.value("blocks", nlohmann::json::array())) {
      if (b.value("type", std::string()) == type) return b;
    }
    return nlohmann::json();
  };
  auto coefSe = [](const nlohmann::json& est, const std::string& field,
                   const std::string& name) -> double {
    for (const auto& row : est.value(field, nlohmann::json::array())) {
      if (row.value("name", std::string()) == name || row.value("exp", std::string()) == name) {
        return row.value("se", -1.0);
      }
    }
    return -1.0;
  };

  double seClusterFromRegress = -1.0, seClusterFromLincom = -1.0, seIidFromLincom = -1.0;

  // --- clustered lastModel: test/lincom/nlcom must inherit vcov=cluster +
  // cluster(year), not silently revert to iid (the exact §1f finding).
  {
    std::string wd = workdir + "/clustered";
    fs::create_directories(wd, ec);
    piet::SessionState session(wd);
    runCmd(session, "sysuse fatalities, clear");
    if (!session.hasData()) {
      // Same isolated/subset-build fixture gap as mission 3 / BUG A / BUG-039
      // / BUG-055 / BUG-056 above (FIX-SELFTEST-ISOBUILD-CRASH): without
      // fatalities.csv, `est` below would be a null "error" block and
      // coefSe()'s unguarded .value() would crash. Skip the whole clustered
      // leg honestly (seClusterFromRegress/seClusterFromLincom stay at their
      // -1.0 default, so the headline §1f comparison below FAILs honestly
      // rather than crashing).
      skip("BS-013 clustered leg", "`sysuse fatalities` setup returned no data");
    } else {
      auto jReg = runCmd(session, "regress fatal beertax, cluster(year)");
      auto est = firstBlockOfType(jReg, "estimation");
      seClusterFromRegress = coefSe(est, "coeftable", "beertax");
      check(seClusterFromRegress > 0,
            "BS-013 setup: `regress fatal beertax, cluster(year)` reports a beertax SE");

      auto jLincom = runCmd(session, "lincom beertax");
      auto lincomEst = firstBlockOfType(jLincom, "estimation");
      check(!lincomEst.is_null(), "BS-013: `lincom beertax` after a clustered regress succeeds");
      seClusterFromLincom = coefSe(lincomEst, "coefs", "beertax");
      check(lincomEst.value("vcov_type", std::string()).rfind("cluster", 0) == 0,
            "BS-013: lincom's OWN reported vcov_type is 'cluster' — before this fix "
            "lastModelBaseArgv never forwarded --vcov/--cluster, so this silently read 'iid'");
      check(seClusterFromLincom > 0 &&
                std::abs(seClusterFromLincom - seClusterFromRegress) < 1e-6,
            "BS-013: `lincom beertax`'s SE matches the clustered regress's OWN beertax SE exactly "
            "(a single-variable lincom is mathematically identical to reading _se[beertax])");

      auto jTest = runCmd(session, "test beertax");
      auto testEst = firstBlockOfType(jTest, "estimation");
      check(!testEst.is_null(), "BS-013: `test beertax` after a clustered regress succeeds");
      check(testEst.value("vcov_type", std::string()).rfind("cluster", 0) == 0,
            "BS-013: test's OWN reported vcov_type is 'cluster' too (same shared "
            "lastModelBaseArgv fix)");

      auto jNlcom = runCmd(session, "nlcom 2*_b[beertax]");
      auto nlcomEst = firstBlockOfType(jNlcom, "estimation");
      check(!nlcomEst.is_null(), "BS-013: `nlcom 2*_b[beertax]` after a clustered regress succeeds");
      check(nlcomEst.value("vcov_type", std::string()).rfind("cluster", 0) == 0,
            "BS-013: nlcom's OWN reported vcov_type is 'cluster' too (runNlcom now shares "
            "lastModelBaseArgv instead of hand-rolling {data,y,x,fe} without vcov/cluster)");
    }
  }

  // --- plain (iid) lastModel: lincom/test correctly STAY iid — the fix must
  // not force cluster onto a model that never used it.
  {
    std::string wd = workdir + "/iid";
    fs::create_directories(wd, ec);
    piet::SessionState session(wd);
    runCmd(session, "sysuse fatalities, clear");
    if (!session.hasData()) {
      // Same isolated/subset-build fixture gap as the clustered leg above
      // (FIX-SELFTEST-ISOBUILD-CRASH). seIidFromLincom stays at its -1.0
      // default, so the headline §1f comparison below FAILs honestly.
      skip("BS-013 iid regression-guard leg", "`sysuse fatalities` setup returned no data");
    } else {
      runCmd(session, "regress fatal beertax");

      auto jLincom = runCmd(session, "lincom beertax");
      auto lincomEst = firstBlockOfType(jLincom, "estimation");
      seIidFromLincom = coefSe(lincomEst, "coefs", "beertax");
      check(lincomEst.value("vcov_type", std::string()) == "iid",
            "BS-013 regression guard: lincom after a PLAIN regress stays iid (the fix does not "
            "force cluster everywhere)");

      auto jTest = runCmd(session, "test beertax");
      auto testEst = firstBlockOfType(jTest, "estimation");
      check(testEst.value("vcov_type", std::string()) == "iid",
            "BS-013 regression guard: test after a PLAIN regress stays iid too");
    }
  }

  // --- the headline §1f assertion: the SAME single-variable lincom's SE is
  // CLEARLY different depending on whether the underlying model was clustered.
  check(seClusterFromLincom > 0 && seIidFromLincom > 0,
        "BS-013: both lincom SEs were captured (setup sanity)");
  check(std::abs(seClusterFromLincom - seIidFromLincom) > 1e-4,
        "BS-013 (audit sec1f probe shape): lincom's cluster-inherited SE (" +
            std::to_string(seClusterFromLincom) + ") is CLEARLY DISTINCT from the iid SE (" +
            std::to_string(seIidFromLincom) +
            ") for the exact same beertax coefficient — before this fix both were silently "
            "identical (lincom always read iid regardless of the fitted model's own vcov)");

  fs::remove_all(workdir, ec);
}

// FIX-RESTIMATE: two coupled parity gaps that broke a real User script
// (analysis.do's `capture lincom ... / if !_rc & !missing(r(estimate)) ...`
// idiom, skipping whole run_one_depvar groups):
//   half 1 — an UNSET r() inside an if/while CONDITION must evaluate to Stata
//            missing (`.`), NOT raise "r(name) is not set". (The command-line
//            path — `gen z = r(mean)` — keeps its honest error; goldens pin it.)
//   half 2 — `lincom`/`nlcom` are r-class: they must populate r(estimate)/
//            r(se)/… . captureRFromBlock had the logic (Branch 2) but was wired
//            only after `summarize`, so r() stayed empty after every lincom.
void testFIXRestimateUnsetRAndLincomFill() {
  std::printf("[selftest] --- FIX-RESTIMATE unset-r-in-condition = missing + lincom r-class fill ---\n");
  namespace fs = std::filesystem;
  std::string workdir = (fs::temp_directory_path() / "piet_native_selftest_restimate").u8string();
  std::error_code ec;
  fs::remove_all(workdir, ec);
  fs::create_directories(workdir, ec);

  // --- half 1: the guard idiom survives an unset r() after a failed capture.
  {
    std::string wd = workdir + "/half1";
    fs::create_directories(wd, ec);
    piet::SessionState session(wd);
    // Fit a model, then capture a lincom of a coefficient that does NOT exist:
    // _rc != 0 and r() is left unset — exactly analysis.do's shape.
    std::string src =
        "sysuse fatalities, clear\n"
        "regress fatal beertax\n"
        "capture lincom nosuchcoef_zzz\n"
        "if !_rc & !missing(r(estimate)) & !missing(r(se)) {\n"
        "    gen restimate_should_not_exist = 1\n"
        "}\n"
        "gen restimate_reached_end = 1\n";
    auto result = piet::doexec::executeDoSource(src, session, piet::dispatch);
    check(!result.stoppedAtReason.has_value(),
          "FIX-RESTIMATE half1: `if !_rc & !missing(r(estimate))` after a failed `capture lincom` "
          "does NOT error on the unset r() (Stata evaluates it as missing; pre-fix engine_error "
          "halted the do-file here, skipping the whole downstream group)");
    check(session.hasData() && session.datastore()->has("restimate_reached_end"),
          "FIX-RESTIMATE half1: execution reached the line AFTER the guard — the do-file did not halt");
    check(session.hasData() && !session.datastore()->has("restimate_should_not_exist"),
          "FIX-RESTIMATE half1: the guarded body did NOT run — the guard is correctly False "
          "(_rc!=0 and r(estimate) missing), matching Stata's non-short-circuit `&`");
  }

  // --- half 2: lincom after a reghdfe-style FE model fills r(estimate)/r(se)
  // and the guard then runs the post body.
  {
    std::string wd = workdir + "/half2";
    fs::create_directories(wd, ec);
    piet::SessionState session(wd);
    std::string src =
        "sysuse fatalities, clear\n"
        // BUG-473 (User ruling 2026-09-09: match Stata): plain `regress`
        // now honestly rejects `absorb()` (r(198), matches StataBE —
        // tests/eval/golden/aer_b4/b5_absorb_class.log:32-36). `areg` is
        // the command that HAS this option and gives the same numbers by
        // construction (runAreg -> runRegress("areg") through the same FE
        // code path) — swap the command word, not the test's subject.
        "areg fatal beertax, absorb(year)\n"  // reghdfe-style FE (absorb)
        "lincom beertax\n"
        "if !_rc & !missing(r(estimate)) & !missing(r(se)) {\n"
        "    gen restimate_posted = 1\n"
        "}\n";
    auto result = piet::doexec::executeDoSource(src, session, piet::dispatch);
    check(!result.stoppedAtReason.has_value(),
          "FIX-RESTIMATE half2: reghdfe-style regress + lincom + guarded post runs cleanly");
    const double* est = session.eval.rValues.find("estimate");
    const double* se = session.eval.rValues.find("se");
    check(est != nullptr && se != nullptr,
          "FIX-RESTIMATE half2: `lincom beertax` populates r(estimate) AND r(se) — "
          "captureRFromBlock was wired only for summarize before, so lincom left r() empty and "
          "every downstream `r(estimate)` read errored");
    check(est != nullptr && std::isfinite(*est) && se != nullptr && std::isfinite(*se) && *se > 0,
          "FIX-RESTIMATE half2: the captured r(estimate)/r(se) are finite (a single-variable "
          "lincom equals _b[beertax]/_se[beertax])");
    check(session.hasData() && session.datastore()->has("restimate_posted"),
          "FIX-RESTIMATE half2: the guard was TRUE (r() non-missing) so the post body ran — "
          "the full `capture lincom / if !missing(r()) { post }` idiom now works end-to-end");
  }

  fs::remove_all(workdir, ec);
}

void testBS013EstatDiagFeHonestReject() {
  std::printf("[selftest] --- BS-013 estat diagnostic family: honest reject after an "
              "FE model instead of a silently-wrong plain-OLS number ---\n");
  namespace fs = std::filesystem;
  std::string workdir =
      (fs::temp_directory_path() / "piet_native_selftest_bs013_estat_fe").u8string();
  std::error_code ec;
  fs::remove_all(workdir, ec);
  fs::create_directories(workdir, ec);
  piet::SessionState session(workdir);

  (void)piet::dispatch("sysuse fatalities, clear", session);
  // `absorb(year)` (reghdfe-style; year is confirmed numeric — see
  // testClusterVceAndUnknownOptionFixes's own comment on why `year`, not the
  // string/factor-coded `state`, is used as a plain numeric column elsewhere
  // in this dataset) sets LastModel.fe WITHOUT needing xtset at all.
  // BUG-473 (User ruling 2026-09-09: match Stata): plain `regress` now
  // honestly rejects `absorb()` (r(198), matches StataBE —
  // tests/eval/golden/aer_b4/b5_absorb_class.log:32-36). `areg` is the
  // command that HAS this option and sets LastModel.fe the same way
  // (runAreg -> runRegress("areg")) — swap the command word; the setup's
  // subject (an FE model in LastModel) is unchanged.
  auto blocks1 = piet::dispatch("areg fatal beertax, absorb(year)", session);
  bool regOk = true;
  for (const auto& b : blocks1) {
    if (b.value("type", "") == "error") regOk = false;
  }
  check(regOk, "BS-013 setup: `areg fatal beertax, absorb(year)` succeeds");
  check(session.lastModel().has_value() && !session.lastModel()->fe.empty(),
        "BS-013 setup: LastModel.fe is non-empty after absorb(year)");

  // estat hettest with NO explicit varlist relies on the lastModel fallback —
  // cobra's hettest/ovtest/vif/dwatson/bgodfrey/durbinalt/archlm CLI has no
  // --fe flag at all (verified against apps/cmds/cmds_diag.cpp), so silently
  // running plain OLS here would answer a DIFFERENT question than the one
  // just estimated. Must honest-reject, not silently succeed.
  auto blocks2 = piet::dispatch("estat hettest", session);
  bool sawError = false;
  std::string errMsg;
  for (const auto& b : blocks2) {
    if (b.value("type", "") == "error") {
      sawError = true;
      errMsg = b.value("message", std::string());
    }
  }
  check(sawError,
        "BS-013: `estat hettest` (no varlist) after an FE model is an HONEST REJECT, not a "
        "silently-wrong plain-OLS Breusch-Pagan number");
  // BUG-1222: the reject is Stata's own -- estat hettest is regress's, and after
  // areg StataBE 19.5 answers r(321) "estat hettest not valid" (scratch-laneA/
  // agents/N1/b2.do), with or without a varlist.
  check(errMsg == "estat hettest not valid",
        "BS-013/BUG-1222: the reject is Stata's `estat hettest not valid` — got: " + errMsg);

  // BUG-1222: an EXPLICIT varlist is hettest's z-list, not a model of its own,
  // and StataBE refuses it after areg too (r(321)); it used to test a plain-OLS
  // refit at rc 0.
  auto blocks3 = piet::dispatch("estat hettest fatal beertax", session);
  std::string explicitMsg;
  for (const auto& b : blocks3) {
    if (b.value("type", "") == "error") explicitMsg = b.value("message", std::string());
  }
  check(explicitMsg == "estat hettest not valid",
        "BS-013/BUG-1222: `estat hettest` WITH a varlist after areg is r(321) `estat hettest "
        "not valid` too — got: " + explicitMsg);

  fs::remove_all(workdir, ec);
}

void testBS100RcCoarseMap() {
  std::printf("[selftest] --- BS-100 rc coarse map behind `capture`'s _rc (replaces the old "
              "boolean-collapsed _rc=1 hardcode) ---\n");
  namespace fs = std::filesystem;
  std::string base = (fs::temp_directory_path() / "piet_native_selftest_bs100").u8string();
  std::error_code ec;
  fs::remove_all(base, ec);
  fs::create_directories(base, ec);

  // unsupported_command -> 199 (Stata's own r(199) "unrecognized command").
  {
    std::string wd = base + "/cmd";
    fs::create_directories(wd, ec);
    piet::SessionState session(wd);
    piet::dispatch("sysuse fatalities, clear", session);  // else the no-data guard yields r(111), not the unsupported_command -> 199 path under test
    piet::dispatch("capture this_is_not_a_real_stata_command_xyz", session);
    check(session.eval.locals.get("_rc", "") == "199",
          "BS-100: an unrecognized command inside `capture` sets _rc=199 "
          "(coarse: unsupported_command)");
  }

  // unsupported_option -> 198 (Stata's own r(198) "invalid syntax").
  {
    std::string wd = base + "/opt";
    fs::create_directories(wd, ec);
    piet::SessionState session(wd);
    piet::dispatch("sysuse fatalities, clear", session);
    piet::dispatch("capture regress fatal beertax, floob", session);
    check(session.eval.locals.get("_rc", "") == "198",
          "BS-100: a bogus option inside `capture` sets _rc=198 (coarse: unsupported_option)");
  }

  // no_data_loaded -> 111 (closest coarse analog: variable/dataset not found).
  {
    std::string wd = base + "/nodata";
    fs::create_directories(wd, ec);
    piet::SessionState session(wd);
    piet::dispatch("capture regress y x", session);
    check(session.eval.locals.get("_rc", "") == "111",
          "BS-100: `regress` with no dataset loaded, inside `capture`, sets _rc=111 "
          "(coarse: no_data_loaded)");
  }

  // engine_error naming a missing FILE -> 601 (file not found).
  {
    std::string wd = base + "/filenf";
    fs::create_directories(wd, ec);
    piet::SessionState session(wd);
    piet::dispatch("capture use \"" + wd + "/does_not_exist_xyz.dta\"", session);
    check(session.eval.locals.get("_rc", "") == "601",
          "BS-100: `use` on a nonexistent file, inside `capture`, sets _rc=601 "
          "(coarse: engine_error naming a missing file)");
  }

  // engine_error naming an existing file without `replace` -> 602 (file
  // already exists).
  {
    std::string wd = base + "/fileexists";
    fs::create_directories(wd, ec);
    piet::SessionState session(wd);
    piet::dispatch("sysuse fatalities, clear", session);
    std::string target = wd + "/dup.hbin";
    piet::dispatch("save \"" + target + "\"", session);           // first save: succeeds
    piet::dispatch("capture save \"" + target + "\"", session);   // second: no replace -> exists
    check(session.eval.locals.get("_rc", "") == "602",
          "BS-100: `save` onto an existing file without `replace`, inside `capture`, sets "
          "_rc=602 (coarse: engine_error naming an existing file)");
  }

  // The engine's absent-column error is Stata's r(111) "variable not found":
  // `eststo: regress y nosuchvar` and `eststo bad: regress y nosuchvar` are
  // r(111) in StataBE (aer_w2 w2ak_estout_family.log:219, :227). It used to be
  // pinned here as the generic _rc=1 (FU-1079 moved it, W2AK).
  {
    std::string wd = base + "/generic";
    fs::create_directories(wd, ec);
    piet::SessionState session(wd);
    piet::dispatch("sysuse fatalities, clear", session);
    piet::dispatch("capture regress fatal nonexistentvar_bs100_xyz", session);
    check(session.eval.locals.get("_rc", "") == "111",
          "BS-100: an engine \"column not found\" error is _rc=111, Stata's variable-not-found "
          "(w2ak_estout_family.log:219)");
  }

  fs::remove_all(base, ec);
}

void testBS091CClassRegistryInExpressions() {
  std::printf("[selftest] --- BS-091/BS-101 c()-class registry in NON-display expression "
              "contexts (gen/scalar/if), single source with display ---\n");
  namespace fs = std::filesystem;
  std::string workdir = (fs::temp_directory_path() / "piet_native_selftest_bs091").u8string();
  std::error_code ec;
  fs::remove_all(workdir, ec);
  fs::create_directories(workdir, ec);
  piet::SessionState session(workdir);

  (void)piet::dispatch("sysuse fatalities, clear", session);
  int64_t n = session.hasData() ? session.datastore()->nRows() : 0;
  check(n > 0, "BS-091 setup: fatalities loaded with >0 rows");

  // (a) `gen k = c(N)` — a NUMERIC expression context, NOT display. Before
  // this fix, c() resolution lived ONLY inside display's own bespoke
  // tokenizer (BS-091's exact finding) — a bare `c(N)` reaching cobra's
  // row-wise `eval --gen` would have been an undefined-name failure.
  auto genBlocks = piet::dispatch("gen nobs_c = c(N)", session);
  bool genOk = true;
  for (const auto& b : genBlocks) {
    if (b.value("type", "") == "error") genOk = false;
  }
  check(genOk, "BS-091: `gen nobs_c = c(N)` does not error");
  check(session.hasData() && session.datastore()->has("nobs_c"),
        "BS-091: `gen nobs_c = c(N)` created the new variable");
  if (session.hasData() && session.datastore()->has("nobs_c") &&
      session.datastore()->nRows() > 0) {
    double v = session.datastore()->col("nobs_c").f64()[0];
    check(v == static_cast<double>(n), "BS-091: `nobs_c`'s value equals c(N), the row count");
  }

  // (b) `di c(N)*2` — c() combined with a real arithmetic operator, through
  // the SAME evalArith path `gen`'s cobra-forwarded expression used above —
  // single source, not two divergent resolvers.
  auto dblocks = piet::dispatch("display c(N)*2", session);
  std::string dtext;
  for (const auto& b : dblocks) {
    if (b.value("type", "") == "display") dtext = b.value("text", std::string());
  }
  double dval = -1.0;
  try {
    dval = std::stod(dtext);
  } catch (...) {
  }
  check(std::abs(dval - static_cast<double>(n) * 2.0) < 1e-6,
        "BS-091: `display c(N)*2` shows N*2 (got '" + dtext + "')");

  // (c) `scalar bs091_k = c(N)` — the scalar/local capture-definition path
  // (dispatcher.cpp's tryCaptureDefinition call site), a THIRD distinct
  // context sharing the same substituteCRefs pre-pass.
  (void)piet::dispatch("scalar bs091_k = c(N)", session);
  const std::string* scalarVal = session.eval.scalars.find("bs091_k");
  check(scalarVal != nullptr && *scalarVal == std::to_string(n),
        "BS-091: `scalar bs091_k = c(N)` resolves via the same substituteCRefs pre-pass");

  // (d) a string-valued key (c(os)) resolves to one of Stata's own c(os)
  // strings through display.
  auto osBlocks = piet::dispatch("display c(os)", session);
  std::string osText;
  for (const auto& b : osBlocks) {
    if (b.value("type", "") == "display") osText = b.value("text", std::string());
  }
  check(osText == "MacOSX" || osText == "Windows" || osText == "Unix",
        "BS-091: `display c(os)` resolves to one of Stata's own c(os) strings (got: '" + osText +
            "')");

  // (e) an UNKNOWN c(...) name (outside this build's ~15-key spine) still
  // surfaces an honest error — never silently swallowed (BUG-090/BUG-091
  // philosophy preserved by the new, larger registry).
  auto unkBlocks = piet::dispatch("display c(totally_bogus_key_xyz)", session);
  bool unkIsError = false;
  for (const auto& b : unkBlocks) {
    if (b.value("type", "") == "error") unkIsError = true;
  }
  check(unkIsError,
        "BS-091: an unknown c(...) name surfaces an honest error, never silently swallowed");

  fs::remove_all(workdir, ec);
}

void testBS046To048SetRegistry() {
  std::printf("[selftest] --- BS-046/047/048/101 set registry: level/seed/graphics honored, "
              "unknown set subcommand gets a visible note (never silent, never an error) ---\n");
  namespace fs = std::filesystem;
  std::string base = (fs::temp_directory_path() / "piet_native_selftest_bs046").u8string();
  std::error_code ec;
  fs::remove_all(base, ec);
  fs::create_directories(base, ec);

  auto runCmd = [](piet::SessionState& session, const std::string& cmd) {
    nlohmann::json body{{"cmd", cmd}};
    auto r = piet::routes::command(session, body.dump());
    return nlohmann::json::parse(r.json);
  };
  auto firstBlockOfType = [](const nlohmann::json& j, const std::string& type) -> nlohmann::json {
    for (const auto& b : j.value("blocks", nlohmann::json::array())) {
      if (b.value("type", std::string()) == type) return b;
    }
    return nlohmann::json();
  };

  // --- set level 90 (a) updates session.level, (b) reaches c(level), and
  // (c) genuinely narrows a `ttest`'s CI — the ONE PIET-wired command whose
  // cobra CLI actually reads --level (verified: cmd_ttest, cmds_summary.cpp
  // reads opt(a,"--level") and applies it to alpha/t_critical throughout;
  // cmd_feols/cmd_xtreg/cmd_logit/cmd_probit do NOT — see estimation_m4.cpp/
  // handlers.cpp's own comments on why the session.level fallback was
  // deliberately NOT extended to those).
  {
    std::string wd = base + "/level";
    fs::create_directories(wd, ec);
    piet::SessionState session(wd);
    check(session.level == 95, "BS-048 setup: session.level defaults to 95");
    runCmd(session, "sysuse fatalities, clear");
    if (!session.hasData()) {
      // Same isolated/subset-build fixture gap as the earlier BUG-039/
      // BUG-055/BUG-056/BS-013 legs above (FIX-SELFTEST-ISOBUILD-CRASH):
      // without fatalities.csv, `ttest fatal == 5` never produces a real
      // "estimation" block and the unguarded est90/est95 `.value()` calls
      // would crash. Skip the whole level-fallback leg honestly (both
      // sessions share the same missing fixture, so session95 would fail
      // identically).
      skip("BS-048 level-fallback leg", "`sysuse fatalities` setup returned no data");
    } else {
      runCmd(session, "set level 90");
      check(session.level == 90, "BS-048: `set level 90` updates session.level");

      auto jc = runCmd(session, "display c(level)");
      auto dispC = firstBlockOfType(jc, "display");
      check(dispC.value("text", std::string()) == "90",
            "BS-091: c(level) reflects the `set level` just run");

      auto j90 = runCmd(session, "ttest fatal == 5");
      auto est90 = firstBlockOfType(j90, "estimation");
      auto coefs90 = est90.value("coefs", nlohmann::json::array());
      check(!coefs90.empty(), "BS-048 setup: `ttest fatal == 5` (session level 90) returns coefs");
      double width90 = coefs90.empty()
                            ? -1.0
                            : (coefs90[0].value("ci_hi", 0.0) - coefs90[0].value("ci_lo", 0.0));

      std::string wd95 = base + "/level95";
      fs::create_directories(wd95, ec);
      piet::SessionState session95(wd95);
      runCmd(session95, "sysuse fatalities, clear");
      // no `set level` here -> stays at the untouched 95 default.
      auto j95 = runCmd(session95, "ttest fatal == 5");
      auto est95 = firstBlockOfType(j95, "estimation");
      auto coefs95 = est95.value("coefs", nlohmann::json::array());
      double width95 = coefs95.empty()
                            ? -1.0
                            : (coefs95[0].value("ci_hi", 0.0) - coefs95[0].value("ci_lo", 0.0));

      check(width90 > 0 && width95 > 0, "BS-048 setup: both ttest CI widths were captured");
      check(width95 > width90,
            "BS-048: a session default of `set level 90` (width " + std::to_string(width90) +
                ") produces a NARROWER ttest CI than the untouched 95 default (width " +
                std::to_string(width95) +
                ") for the identical one-sample test, with NEITHER command passing an explicit "
                "level() — the session default genuinely reaches ttest's own --level flow");

      // Regression-safety: `set level 90` must NOT break an ordinary plain
      // regress afterward (cobra's feols CLI never reads --level at all —
      // see the comment in handlers.cpp::runRegress on why that fallback
      // was deliberately NOT wired there).
      auto jReg = runCmd(session, "regress fatal beertax");
      bool regOk = true;
      for (const auto& b : jReg.value("blocks", nlohmann::json::array())) {
        if (b.value("type", std::string()) == "error") regOk = false;
      }
      check(regOk,
            "BS-048 regression guard: `regress` after `set level 90` still succeeds (the fallback "
            "is scoped to ttest only, not extended to feols/xtreg/logit/probit)");
    }
  }

  // --- set seed persistence + c(seed) exposure (BS-046).
  {
    std::string wd = base + "/seed";
    fs::create_directories(wd, ec);
    piet::SessionState session(wd);
    check(!session.seed.has_value(), "BS-046 setup: seed unset by default");
    runCmd(session, "set seed 20260712");
    check(session.seed.has_value() && *session.seed == 20260712,
          "BS-046: `set seed 20260712` persists on the session");
    // c(seed) is the generator state `set seed` produced, as c(rngstate) is
    // (BUG-1051: StataBE 19.5 answers the 5011-character state, not the number).
    auto j = runCmd(session, "display c(seed)");
    auto disp = firstBlockOfType(j, "display");
    check(disp.value("text", std::string()) == cecon::Mt64(20260712).state_string(),
          "BS-046: c(seed) reflects the `set seed` just run");
  }

  // --- set graphics off honored by the renderer's `suppressed` field (BS-047).
  {
    std::string wd = base + "/graphics";
    fs::create_directories(wd, ec);
    piet::SessionState session(wd);
    runCmd(session, "sysuse fatalities, clear");
    if (!session.hasData()) {
      // Same isolated/subset-build fixture gap as the level leg above
      // (FIX-SELFTEST-ISOBUILD-CRASH): without fatalities.csv, `twoway`
      // never produces a real "graph" block and the unguarded `g.value()`
      // below would crash. Skip the whole graphics-suppression leg honestly.
      skip("BS-047 graphics-suppression leg", "`sysuse fatalities` setup returned no data");
    } else {
      runCmd(session, "set graphics off");
      check(session.graphicsOff == true, "BS-047: `set graphics off` sets session.graphicsOff");
      auto j = runCmd(session, "twoway (scatter fatal beertax)");
      auto g = firstBlockOfType(j, "graph");
      check(g.value("suppressed", false) == true,
            "BS-047: a twoway graph built AFTER `set graphics off` reports suppressed=true "
            "(previously hardcoded false regardless of `set graphics`)");
      runCmd(session, "set graphics on");
      check(session.graphicsOff == false, "BS-047: `set graphics on` clears session.graphicsOff");
    }
  }

  // --- unknown `set` subcommand: explicit no-op NOTE, never silent, never
  // an error (real Stata do-files run `set more off`/`set matsize N`
  // constantly; turning these into errors would halt them for no reason).
  {
    std::string wd = base + "/unknown";
    fs::create_directories(wd, ec);
    piet::SessionState session(wd);
    auto j = runCmd(session, "set matsize 800");
    bool sawErr = false, sawNote = false;
    for (const auto& b : j.value("blocks", nlohmann::json::array())) {
      if (b.value("type", std::string()) == "error") sawErr = true;
      if (b.value("type", std::string()) == "echo" &&
          b.value("text", std::string()).find("matsize") != std::string::npos) {
        sawNote = true;
      }
    }
    check(!sawErr, "BS-101: an unrecognized `set` subcommand is NEVER an error");
    check(sawNote,
          "BS-101: `set matsize 800` (an unimplemented subcommand) now emits a visible note "
          "naming it, instead of a totally silent no-op");
  }

  fs::remove_all(base, ec);
}

// BETA campaign Phase B (B-data cluster): sort real dispatch (BS-001),
// destring/tostring (BS-003/D4), joinby (BS-004/D5), format (BS-005/D6).

void testBS001SortRealDispatch() {
  std::printf("[selftest] --- BS-001 `sort` real dispatch (was silent no-op) ---\n");
  namespace fs = std::filesystem;
  std::string workdir = (fs::temp_directory_path() / "piet_native_selftest_bs001").u8string();
  std::error_code ec;
  fs::remove_all(workdir, ec);
  fs::create_directories(workdir, ec);

  piet::SessionState session(workdir);
  (void)piet::dispatch("sysuse fatalities, clear", session);
  (void)piet::dispatch("keep in 1/30", session);
  // Force a KNOWN non-ascending order first via the already-correct
  // `gsort`, so the subsequent `sort` has unambiguous work to do —
  // isolates this test from any assumption about fatalities' own natural
  // row order.
  (void)piet::dispatch("gsort -year", session);

  piet::Datastore* dsDesc = session.datastore();
  bool haveFixture = dsDesc != nullptr && dsDesc->nRows() > 1 && dsDesc->has("year");
  check(haveFixture, "BS-001 setup: fixture loaded with >1 row and a `year` column");
  if (!haveFixture) {
    fs::remove_all(workdir, ec);
    return;
  }

  bool wasNonIncreasing = true;
  {
    const double* years = dsDesc->col("year").f64();
    for (int64_t i = 1; i < dsDesc->nRows(); ++i) {
      if (years[i] > years[i - 1]) {
        wasNonIncreasing = false;
        break;
      }
    }
  }
  check(wasNonIncreasing, "BS-001 setup: `gsort -year` produced a non-increasing `year` column");

  auto blocks = piet::dispatch("sort year", session);
  bool sawError = false;
  for (const auto& b : blocks) {
    if (b.is_object() && b.value("type", std::string()) == "error") sawError = true;
  }
  check(!sawError, "BS-001: `sort year` does not error");

  piet::Datastore* ds = session.datastore();
  bool nowNonDecreasing = (ds != nullptr && ds->has("year"));
  if (nowNonDecreasing) {
    const double* years = ds->col("year").f64();
    for (int64_t i = 1; i < ds->nRows(); ++i) {
      if (years[i] < years[i - 1]) {
        nowNonDecreasing = false;
        break;
      }
    }
  }
  check(nowNonDecreasing,
        "BS-001: `sort year` actually reorders rows ascending — previously a silent no-op "
        "(it shelled out to `eval --sort`, a flag cobra's `eval` verb never recognized; cobra's "
        "own `gsort` verb is the real thing)");

  fs::remove_all(workdir, ec);
}

void testBS003DestringTostring() {
  std::printf("[selftest] --- BS-003 destring/tostring (PIET-native, D4) ---\n");
  namespace fs = std::filesystem;
  std::string workdir = (fs::temp_directory_path() / "piet_native_selftest_bs003").u8string();
  std::error_code ec;
  fs::remove_all(workdir, ec);
  fs::create_directories(workdir, ec);

  piet::SessionState session(workdir);
  (void)piet::dispatch("sysuse fatalities, clear", session);
  (void)piet::dispatch("keep in 1/5", session);

  // --- destring: ignore() strips characters before parsing ---
  (void)piet::dispatch("gen str10 bs003dirty = \"1,234\"", session);
  auto destringBlocks =
      piet::dispatch("destring bs003dirty, gen(bs003clean) ignore(\",\")", session);
  bool destringErr = false;
  for (const auto& b : destringBlocks) {
    if (b.is_object() && b.value("type", std::string()) == "error") destringErr = true;
  }
  check(!destringErr, "BS-003: `destring ..., ignore(\",\")` on a comma-formatted string succeeds");
  piet::Datastore* ds1 = session.datastore();
  bool cleanOk = ds1 != nullptr && ds1->has("bs003clean") && ds1->dtype("bs003clean") == "f64";
  check(cleanOk, "BS-003: destring's target lands as a NUMERIC (f64) column");
  if (cleanOk && ds1->nRows() > 0) {
    check(ds1->col("bs003clean").f64()[0] == 1234.0,
          "BS-003: `ignore(\",\")` strips the comma before parsing (\"1,234\" -> 1234)");
  }

  // --- destring: skip note without force; missing under force ---
  // BUG-664: Stata's destring leaves a variable with nonnumeric content as is and
  // prints "VAR: contains nonnumeric characters; no replace|generate" at rc 0
  // (tests/eval/golden/aer_w2/w2b_dataio.log:350, destring_nodp_ctl). This
  // check used to pin an error block here.
  (void)piet::dispatch("gen str10 bs003bad = \"abc\"", session);
  auto badBlocks = piet::dispatch("destring bs003bad, gen(bs003badnum)", session);
  bool badErr = false;
  bool badNote = false;
  for (const auto& b : badBlocks) {
    if (!b.is_object()) continue;
    const std::string type = b.value("type", std::string());
    if (type == "error") badErr = true;
    if (type == "display" && b.value("text", std::string())
                                     .find("bs003bad: contains nonnumeric characters; no generate") !=
                                 std::string::npos)
      badNote = true;
  }
  check(!badErr && badNote,
        "BS-003: destring without `force` on a non-numeric string is skipped with Stata's note "
        "(w2b_dataio.log:350 destring_nodp_ctl), not an error");
  piet::Datastore* dsBad = session.datastore();
  check(dsBad != nullptr && !dsBad->has("bs003badnum"),
        "BS-003: the skipped destring creates no generate() target");
  (void)piet::dispatch("capture destring bs003bad, gen(bs003badnum)", session);
  std::string badRc;
  for (const auto& b : piet::dispatch("display _rc", session)) {
    if (b.is_object() && b.value("type", std::string()) != "echo")
      badRc += b.value("text", std::string());
  }
  badRc.erase(std::remove_if(badRc.begin(), badRc.end(), ::isspace), badRc.end());
  check(badRc == "0", "BS-003: the skipped destring leaves _rc 0 (got `" + badRc + "')");

  auto forcedBlocks = piet::dispatch("destring bs003bad, gen(bs003badnum2) force", session);
  bool forcedErr = false;
  for (const auto& b : forcedBlocks) {
    if (b.is_object() && b.value("type", std::string()) == "error") forcedErr = true;
  }
  check(!forcedErr, "BS-003: destring WITH `force` on a non-numeric string succeeds");
  piet::Datastore* ds2 = session.datastore();
  bool forcedOk = ds2 != nullptr && ds2->has("bs003badnum2") && ds2->nRows() > 0;
  check(forcedOk && std::isnan(ds2->col("bs003badnum2").f64()[0]),
        "BS-003: `force` converts the unparseable value to missing, not a silent wrong number");

  // --- tostring: default rendering vs usedisplayformat ---
  (void)piet::dispatch("format year %9.2f", session);
  (void)piet::dispatch("tostring year, gen(bs003yeardef)", session);
  (void)piet::dispatch("tostring year, gen(bs003yearfmt) usedisplayformat", session);
  piet::Datastore* ds3 = session.datastore();
  bool tostringOk = ds3 != nullptr && ds3->has("bs003yeardef") && ds3->has("bs003yearfmt") &&
                    ds3->dtype("bs003yeardef") == "factor" && ds3->dtype("bs003yearfmt") == "factor";
  check(tostringOk, "BS-003: tostring's target lands as a STRING (factor) column, both forms");
  if (tostringOk && ds3->nRows() > 0) {
    int32_t code0 = ds3->col("bs003yeardef").codes()[0];
    int32_t code1 = ds3->col("bs003yearfmt").codes()[0];
    const auto& lv0 = ds3->col("bs003yeardef").levels;
    const auto& lv1 = ds3->col("bs003yearfmt").levels;
    std::string defStr =
        (code0 >= 0 && static_cast<size_t>(code0) < lv0.size()) ? lv0[static_cast<size_t>(code0)] : "";
    std::string fmtStr =
        (code1 >= 0 && static_cast<size_t>(code1) < lv1.size()) ? lv1[static_cast<size_t>(code1)] : "";
    check(defStr.find('.') == std::string::npos,
          "BS-003: tostring's DEFAULT rendering of a whole-number year has no decimal point");
    check(fmtStr.find('.') != std::string::npos,
          "BS-003: tostring `usedisplayformat` honors the variable's own `format ... %9.2f` "
          "(decimal point present)");
  }

  // --- B5-D1: tostring `force` and the `g()` alias for `generate` ---
  // BUG-665: `force` is no longer a no-op -- it overrides tostring.ado's
  // reversibility test. Whole-number years convert reversibly, so the
  // rendering must be the same with or without it, which is what this pins.
  auto forceBlocks = piet::dispatch("tostring year, gen(bs003forcegen) force", session);
  bool forceErr = false;
  for (const auto& b : forceBlocks) {
    if (b.is_object() && b.value("type", std::string()) == "error") forceErr = true;
  }
  check(!forceErr, "B5-D1: `tostring ..., force` is accepted (rc 0), not r(198)");
  piet::Datastore* ds4 = session.datastore();
  bool forceOk = ds4 != nullptr && ds4->has("bs003forcegen") && ds4->has("bs003yeardef") &&
                ds4->dtype("bs003forcegen") == "factor";
  check(forceOk, "B5-D1: tostring's target under `force` still lands as a STRING (factor) column");
  if (forceOk && ds4->nRows() > 0) {
    auto decode = [&](const char* var) -> std::string {
      int32_t code = ds4->col(var).codes()[0];
      const auto& lv = ds4->col(var).levels;
      return (code >= 0 && static_cast<size_t>(code) < lv.size()) ? lv[static_cast<size_t>(code)]
                                                                   : "";
    };
    check(decode("bs003forcegen") == decode("bs003yeardef"),
          "B5-D1: on a reversible variable `force` does not change the rendered value "
          "byte-for-byte vs. plain tostring (internal capture "
          "tostring_missing_oracle.log:67)");
  }
  auto gAliasBlocks = piet::dispatch("tostring year, g(bs003galias)", session);
  bool gAliasErr = false;
  for (const auto& b : gAliasBlocks) {
    if (b.is_object() && b.value("type", std::string()) == "error") gAliasErr = true;
  }
  check(!gAliasErr, "B5-D1: `tostring ..., g(newvar)` (the `g` alias of `generate`) is accepted");
  piet::Datastore* ds5 = session.datastore();
  check(ds5 != nullptr && ds5->has("bs003galias") && ds5->dtype("bs003galias") == "factor",
        "B5-D1: the `g()` alias target lands as a STRING (factor) column, same as `gen()`");

  fs::remove_all(workdir, ec);
}

// BUG-191 RED certificate (P2-PERF ARC-B/B2). A silent-wrong-answer fix needs a
// probe that FAILS on the defect, and no existing gate had one: the corruption
// only appears when a column is renamed ON THE RESIDENT FRAME, which nothing
// asked for until `rename` was given the residency opt-in.
//
// The defect: cecon_cli's resident swap reattaches a pending column that still
// borrows the OUTGOING frame's buffer by looking the column up BY NAME. A
// rename is the one mutation that keeps the bytes and changes the name, so the
// lookup missed, the reattach was skipped, and the renamed column went on
// pointing at a buffer freed by the swap. Pre-fix, the summarize below reported
// mean 8.6e+109 over four values that are 1, 2, 1, 2.
//
// Deliberately built from a VIRTUAL head (`set obs` + `gen`, never saved), which
// is the state that makes every column an owned buffer of the outgoing frame —
// a file-backed head borrows the shared root mmap instead and survives by a
// different route, which is why the benchmark's own rename loop looked fine.
void testBUG191ResidentRenameKeepsValues() {
  std::printf("[selftest] --- BUG-191 resident `rename` preserves the renamed column's values ---\n");
  namespace fs = std::filesystem;
  std::string workdir = (fs::temp_directory_path() / "piet_native_selftest_bug191").u8string();
  std::error_code ec;
  fs::remove_all(workdir, ec);
  fs::create_directories(workdir, ec);

  piet::SessionState session(workdir);
  (void)piet::dispatch("clear", session);
  (void)piet::dispatch("set obs 4", session);
  (void)piet::dispatch("gen double side = cond(_n==1 | _n==3, 1, 2)", session);
  (void)piet::dispatch("rename side other_side", session);

  piet::Datastore* ds = session.datastore();
  bool ok = ds != nullptr && ds->has("other_side") && ds->nRows() == 4;
  check(ok, "BUG-191: the renamed column exists with the original row count");
  if (ok) {
    const double* v = ds->col("other_side").f64();
    check(v[0] == 1.0 && v[1] == 2.0 && v[2] == 1.0 && v[3] == 2.0,
          "BUG-191: the renamed column still holds 1,2,1,2 — not the freed predecessor buffer");
  }
}

void testBS004JoinbyInnerKeyJoin() {
  std::printf("[selftest] --- BS-004 `joinby` inner key-join (PIET-native, D5) ---\n");
  namespace fs = std::filesystem;
  std::string workdir = (fs::temp_directory_path() / "piet_native_selftest_bs004").u8string();
  std::error_code ec;
  fs::remove_all(workdir, ec);
  fs::create_directories(workdir, ec);

  piet::SessionState session(workdir);
  (void)piet::dispatch("clear", session);
  (void)piet::dispatch("set obs 4", session);
  (void)piet::dispatch("gen double gid = cond(_n<=2, 1, 2)", session);
  // NB: mod-free by historical accident: written when cobra-eval lacked mod()
  // (BS-094 / BUG-038b — since LANDED engine-side; `gen z=mod(...)` works now).
  // The fixture keeps its original shape for freeze stability, not because this
  // leg's SETUP and mask the joinby behaviour under test. _n==1|_n==3 gives 1,2,1,2.
  (void)piet::dispatch("gen double side = cond(_n==1 | _n==3, 1, 2)", session);

  (void)piet::dispatch("tempfile bs004using", session);
  (void)piet::dispatch("preserve", session);
  (void)piet::dispatch("rename side other_side", session);
  (void)piet::dispatch("label variable other_side \"Using side label\"", session);
  (void)piet::dispatch("save `bs004using', replace", session);
  (void)piet::dispatch("restore", session);

  // --- the core case: BOTH sides have 2 rows per key -> full 2x2 cross ---
  auto blocks = piet::dispatch("joinby gid using `bs004using'", session);
  bool sawError = false;
  for (const auto& b : blocks) {
    if (b.is_object() && b.value("type", std::string()) == "error") sawError = true;
  }
  check(!sawError, "BS-004: bare `joinby gid using FILE` does not error");

  piet::Datastore* ds = session.datastore();
  bool structureOk = ds != nullptr && ds->has("gid") && ds->has("side") && ds->has("other_side");
  check(structureOk, "BS-004: joined dataset carries master's `side` + using's `other_side`");
  (void)piet::dispatch("local bs004label : variable label other_side", session);
  check(session.eval.locals.get("bs004label") == "Using side label",
        "BS-004: genuine DTA tempfile keeps the using variable label");
  if (structureOk) {
    check(ds->nRows() == 8,
          "BS-004: 2 master rows x 2 using rows per gid-group, 2 groups -> 8 rows (the full "
          "within-key Cartesian cross, not a 1:1 pairing)");
    std::set<std::pair<int, int>> g1Pairs, g2Pairs;
    const double* gidv = ds->col("gid").f64();
    const double* sidev = ds->col("side").f64();
    const double* otherv = ds->col("other_side").f64();
    for (int64_t i = 0; i < ds->nRows(); ++i) {
      auto p = std::make_pair(static_cast<int>(sidev[i]), static_cast<int>(otherv[i]));
      if (gidv[i] == 1.0) g1Pairs.insert(p);
      else if (gidv[i] == 2.0) g2Pairs.insert(p);
    }
    std::set<std::pair<int, int>> expected = {{1, 1}, {1, 2}, {2, 1}, {2, 2}};
    check(g1Pairs == expected, "BS-004: gid=1 group produces all 4 (side,other_side) combinations");
    check(g2Pairs == expected, "BS-004: gid=2 group produces all 4 (side,other_side) combinations");
  }

  // --- unmatched(none) default: a master row with no using match is DROPPED ---
  (void)piet::dispatch("clear", session);
  (void)piet::dispatch("set obs 1", session);
  (void)piet::dispatch("gen double gid = 999", session);
  auto noMatchBlocks = piet::dispatch("joinby gid using `bs004using'", session);
  bool noMatchErr = false;
  for (const auto& b : noMatchBlocks) {
    if (b.is_object() && b.value("type", std::string()) == "error") noMatchErr = true;
  }
  check(!noMatchErr, "BS-004: a master row with no using match does not error");
  piet::Datastore* dsEmpty = session.datastore();
  check(dsEmpty != nullptr && dsEmpty->nRows() == 0,
        "BS-004: unmatched(none) (the only mode this build implements) drops the non-matching "
        "master row (0 rows out)");

  // --- D5: ANY joinby option is an honest reject (bare form only) ---
  (void)piet::dispatch("clear", session);
  (void)piet::dispatch("set obs 4", session);
  (void)piet::dispatch("gen double gid = cond(_n<=2, 1, 2)", session);
  // NB: mod-free by historical accident: written when cobra-eval lacked mod()
  // (BS-094 / BUG-038b — since LANDED engine-side; `gen z=mod(...)` works now).
  // The fixture keeps its original shape for freeze stability, not because this
  // leg's SETUP and mask the joinby behaviour under test. _n==1|_n==3 gives 1,2,1,2.
  (void)piet::dispatch("gen double side = cond(_n==1 | _n==3, 1, 2)", session);
  auto optBlocks = piet::dispatch("joinby gid using `bs004using', update", session);
  bool optErr = false;
  for (const auto& b : optBlocks) {
    if (b.is_object() && b.value("type", std::string()) == "error") optErr = true;
  }
  check(optErr,
        "BS-004: `joinby ..., update` (an unimplemented option) is an honest reject, not a "
        "silently-ignored option (D5 — unmatched()/update/_merge()/... -> post-beta WP-18)");

  fs::remove_all(workdir, ec);
}

void testBUG127PredictTypePrefix() {
  std::printf("[selftest] --- BUG-127 `predict <type> newvar` storage-type prefix ---\n");
  namespace fs = std::filesystem;
  std::string workdir = (fs::temp_directory_path() / "piet_native_selftest_bug127").u8string();
  std::error_code ec;
  fs::remove_all(workdir, ec);
  fs::create_directories(workdir, ec);

  piet::SessionState session(workdir);
  (void)piet::dispatch("sysuse fatalities, clear", session);
  (void)piet::dispatch("regress fatal beertax", session);

  // --- `double` prefix: accepted, stripped, the REAL name is used ---
  auto dblBlocks = piet::dispatch("predict double yh, xb", session);
  bool dblErr = false;
  for (const auto& b : dblBlocks) {
    if (b.is_object() && b.value("type", std::string()) == "error") dblErr = true;
  }
  check(!dblErr, "BUG-127: `predict double yh, xb` succeeds (double = PIET's own f64 storage)");
  piet::Datastore* ds = session.datastore();
  check(ds != nullptr && ds->has("yh") && ds->dtype("yh") == "f64",
        "BUG-127: the REAL name `yh` exists as an f64 column (was: silently discarded — the "
        "type token became the variable's name)");
  check(ds != nullptr && !ds->has("double"),
        "BUG-127: no column literally named `double` is created (the old misparse)");

  // --- `float` prefix: served, the column holds float values (BUG-924) ---
  // StataBE serves `predict float pf, xb` rc 0, typed float, values float-rounded
  // (w2aa_predict_type_restricted.log:133 a_pf_float_xb). The engine rounds on
  // store (--store-type), so every stored value is exactly a float.
  auto fltBlocks = piet::dispatch("predict float yf, xb", session);
  bool fltErr = false;
  for (const auto& b : fltBlocks) {
    if (b.is_object() && b.value("type", std::string()) == "error") fltErr = true;
  }
  check(!fltErr,
        "BUG-127/BUG-924: `predict float yf, xb` succeeds, as StataBE does "
        "(w2aa_predict_type_restricted.log:133) -- it was refused r(198)");
  piet::Datastore* ds2 = session.datastore();
  check(ds2 != nullptr && ds2->has("yf") && !ds2->has("float"),
        "BUG-127: the REAL name `yf` exists; no column literally named `float`");
  check(session.varMeta.count("yf") != 0 && session.varMeta["yf"].stataType.has_value() &&
            *session.varMeta["yf"].stataType == "float",
        "BUG-924: `yf` is recorded as float (a_pf_float_xb `: type` float)");
  if (ds2 != nullptr && ds2->has("yf")) {
    const double* yf = ds2->col("yf").f64();
    const double* yh = ds2->has("yh") ? ds2->col("yh").f64() : nullptr;
    bool allFloat = true, anyDiffers = false;
    for (int64_t i = 0; i < ds2->nRows(); ++i) {
      if (!std::isfinite(yf[i])) continue;
      if (static_cast<double>(static_cast<float>(yf[i])) != yf[i]) allFloat = false;
      if (yh != nullptr && yf[i] != yh[i]) anyDiffers = true;
      if (yh != nullptr && static_cast<double>(static_cast<float>(yh[i])) != yf[i])
        allFloat = false;
    }
    check(allFloat,
          "BUG-924: every `yf` value is the float rounding of the double prediction "
          "(a_pf_float_xb %21x pf[1] +1.dda8fe0000000X+003: a float's mantissa)");
    check(yh == nullptr || anyDiffers,
          "BUG-924: ...and `yf` is NOT the double column (a_eq_p_pd: 0 rows equal)");
  }

  fs::remove_all(workdir, ec);
}

void testBUG155PredictOnlyRequestedColumn() {
  std::printf("[selftest] --- BUG-155 `predict, xb` creates ONLY the requested column ---\n");
  namespace fs = std::filesystem;
  std::string workdir = (fs::temp_directory_path() / "piet_native_selftest_bug155").u8string();
  std::error_code ec;
  fs::remove_all(workdir, ec);
  fs::create_directories(workdir, ec);

  piet::SessionState session(workdir);
  (void)piet::dispatch("sysuse fatalities, clear", session);
  if (!session.hasData()) {
    // BUG-1939: with no rows the sentinel read below walked off an empty
    // column (segfault in a public clone whose sysuse could not find the
    // sample); a setup miss is a declared skip, never a crash.
    skip("BUG-155 (all legs)", "`sysuse fatalities` setup returned no data");
    fs::remove_all(workdir, ec);
    return;
  }

  // Arm 1 (THE RED ARM — this is the pre-fix defect verbatim): a user variable
  // that happens to be called `resid` must survive `predict <name>, xb`. Pre-fix,
  // the engine appended BOTH columns under their default names on every call, so
  // this sentinel was silently replaced by the regression's residuals.
  (void)piet::dispatch("generate double resid = 99999", session);
  (void)piet::dispatch("regress fatal beertax", session);
  (void)piet::dispatch("predict double yhat, xb", session);
  piet::Datastore* ds = session.datastore();
  check(ds != nullptr && ds->has("yhat"), "BUG-155: the requested column `yhat` is created");
  bool sentinelIntact = false;
  if (ds != nullptr && ds->has("resid")) {
    const double* vals = ds->col("resid").f64();
    sentinelIntact = vals != nullptr && ds->nRows() > 0 && vals[0] == 99999.0;
  }
  check(sentinelIntact,
        "BUG-155: a pre-existing user variable named `resid` is NOT overwritten by "
        "`predict, xb` (was: silently replaced by the regression residuals — user data "
        "destroyed by a command that Stata says touches only the named newvar)");

  // Arm 2: the unrequested column is not conjured into existence either.
  (void)piet::dispatch("drop resid", session);
  (void)piet::dispatch("regress fatal beertax", session);
  (void)piet::dispatch("predict double yhat2, xb", session);
  piet::Datastore* ds2 = session.datastore();
  check(ds2 != nullptr && ds2->has("yhat2") && !ds2->has("resid"),
        "BUG-155: `predict, xb` appends no second `resid` column of its own");

  // Arm 3: the residual side still works when it IS what was asked for.
  (void)piet::dispatch("predict double e1, resid", session);
  piet::Datastore* ds3 = session.datastore();
  check(ds3 != nullptr && ds3->has("e1") && !ds3->has("xb"),
        "BUG-155: `predict, resid` appends only the named residual column (no stray `xb`)");

  fs::remove_all(workdir, ec);
}

// BUG-1939: every dev-tree path (sysuse sample, frontend index.html,
// c(sysdir_sample), the notices route) was anchored on __FILE__ alone. A build
// with -ffile-prefix-map — the public build script — makes __FILE__ relative,
// so each anchor fell back to "../.." against the cwd and `sysuse fatalities`
// answered "file not found" in a public clone (and BUG-155's arm then crashed
// on the empty column). The shared resolver must find the tree from the
// executable's own location, with no __FILE__ involved.
void testBUG1939DevTreeRootResolution() {
  std::printf("[selftest] --- BUG-1939 dev-tree root resolves from the executable, not __FILE__ ---\n");
  if (piet::bundleResourcesDir().has_value()) {
    skip("BUG-1939 (all legs)", "running from inside a packaged bundle; the dev tree does not apply");
    return;
  }
  namespace fs = std::filesystem;
  std::error_code ec;
  std::optional<std::string> exe = piet::executablePath();
  check(exe.has_value(), "BUG-1939: executablePath() resolves for a dev-tree binary");
  std::optional<std::string> fromExe;
  if (exe.has_value()) {
    auto sep = exe->find_last_of("/\\");
    if (sep != std::string::npos) fromExe = piet::devTreeRootFrom(exe->substr(0, sep));
  }
  check(fromExe.has_value(),
        "BUG-1939: the checkout root is found by walking up from the executable's directory "
        "(no __FILE__ in that path) -- the arm that a -ffile-prefix-map build failed");
  check(fromExe.has_value() &&
            fs::is_regular_file(cecon::to_native_path(*fromExe + "/piet/packaging/sample/fatalities.csv"), ec),
        "BUG-1939: ...and that root holds piet/packaging/sample/fatalities.csv");
  std::optional<std::string> root = piet::devTreeRoot();
  check(root.has_value() &&
            fs::is_regular_file(cecon::to_native_path(*root + "/piet/frontend/index.html"), ec),
        "BUG-1939: devTreeRoot() (the production resolver) reaches piet/frontend/index.html");
  check(piet::devTreePath("/piet/packaging/sample") == (root.has_value() ? *root : std::string("../..")) + "/piet/packaging/sample",
        "BUG-1939: devTreePath() is root + suffix (the \"../..\" guess only when nothing resolves)");
  check(!piet::devTreeRootFrom("/").has_value(),
        "BUG-1939: a start point with no checkout above it resolves to nothing, not to a guess");
}

void testBS005FormatDisplayLayer() {
  std::printf("[selftest] --- BS-005 `format VAR %%fmt` display-layer attribute (D6) ---\n");
  namespace fs = std::filesystem;
  std::string workdir = (fs::temp_directory_path() / "piet_native_selftest_bs005").u8string();
  std::error_code ec;
  fs::remove_all(workdir, ec);
  fs::create_directories(workdir, ec);

  piet::SessionState session(workdir);
  (void)piet::dispatch("sysuse fatalities, clear", session);
  (void)piet::dispatch("keep in 1/3", session);

  auto fmtBlocks = piet::dispatch("format year %td", session);
  bool fmtErr = false;
  for (const auto& b : fmtBlocks) {
    if (b.is_object() && b.value("type", std::string()) == "error") fmtErr = true;
  }
  check(!fmtErr, "BS-005: `format year %td` (a recognized format family) does not error");

  auto listBlocks = piet::dispatch("list year", session);
  bool foundFormat = false;
  for (const auto& b : listBlocks) {
    if (!b.is_object() || b.value("type", std::string()) != "browse") continue;
    for (const auto& col : b.value("columns", nlohmann::ordered_json::array())) {
      if (col.value("name", std::string()) == "year" && col.value("format", std::string()) == "%td") {
        foundFormat = true;
      }
    }
  }
  check(foundFormat,
        "BS-005: `list` honors the session format — `year`'s column-meta carries "
        "\"format\": \"%td\"");

  auto badBlocks = piet::dispatch("format year %notaformat", session);
  bool badErr = false;
  for (const auto& b : badBlocks) {
    if (b.is_object() && b.value("type", std::string()) == "error") badErr = true;
  }
  check(badErr, "BS-005: an unrecognized %fmt is an honest reject, not a silent accept (D6)");

  // format-display-default-lifecycle: a session that never calls `format`
  // lists each column in the format describe reports for it (the one resolver,
  // SessionState::displayFormat: here the .dta's own format). This arm used to
  // pin the opposite -- NO "format" key, so `list` of a byte or a double never
  // learned its %8.0g/%10.0g (w2p_estim_ev.log:1725/:1793).
  std::string workdir2 = workdir + "_2";
  fs::remove_all(workdir2, ec);
  fs::create_directories(workdir2, ec);
  piet::SessionState session2(workdir2);
  (void)piet::dispatch("sysuse fatalities, clear", session2);
  (void)piet::dispatch("keep in 1/3", session2);
  auto plainListBlocks = piet::dispatch("list year", session2);
  std::string listFmt;
  for (const auto& b : plainListBlocks) {
    if (!b.is_object() || b.value("type", std::string()) != "browse") continue;
    for (const auto& col : b.value("columns", nlohmann::ordered_json::array())) {
      if (col.value("name", std::string()) == "year") listFmt = col.value("format", std::string());
    }
  }
  std::string descFmt;
  for (const auto& b : piet::dispatch("describe year", session2)) {
    if (!b.is_object() || b.value("type", std::string()) != "describe") continue;
    for (const auto& v : b.value("variables", nlohmann::ordered_json::array())) {
      if (v.value("name", std::string()) == "year") descFmt = v.value("format", std::string());
    }
  }
  check(!listFmt.empty() && listFmt == descFmt,
        "BS-005/format-display-default-lifecycle: a session that never calls `format` lists "
        "`year` in the format describe reports (one resolver) -- list [" + listFmt +
            "] describe [" + descFmt + "]");

  fs::remove_all(workdir, ec);
  fs::remove_all(workdir2, ec);
}

// BETA campaign Phase B (B-log cluster): `log using FILE [, replace|append]
// [text]` really opens a file and tees subsequent command output to it as a
// plain-text transcript (BUG-028 / BS-006 — previously a pure no-op shim
// that only tracked session.logPath). Real coverage, not just a golden
// diff: open -> run commands -> close -> read the file back off disk and
// assert real content, plus append-vs-replace, the double-open / file-
// exists / smcl honest-rejects, and log off/on pausing.
void testBS006LogUsingRealFileWrite() {
  std::printf("[selftest] --- BS-006 `log using`/`log close` real file write (BUG-028) ---\n");
  namespace fs = std::filesystem;
  std::string workdir = (fs::temp_directory_path() / "piet_native_selftest_bs006").u8string();
  std::error_code ec;
  fs::remove_all(workdir, ec);
  fs::create_directories(workdir, ec);
  std::string logPath = workdir + "/test.log";

  piet::SessionState session(workdir);
  (void)piet::dispatch("sysuse fatalities, clear", session);

  // 1. `log using FILE, replace text` opens a REAL file on disk (no error).
  auto openBlocks = piet::dispatch("log using \"" + logPath + "\", replace text", session);
  bool openErr = false;
  for (const auto& b : openBlocks) {
    if (b.is_object() && b.value("type", std::string()) == "error") openErr = true;
  }
  check(!openErr, "BS-006: `log using FILE, replace text` does not error");
  check(fs::exists(logPath, ec), "BS-006: `log using ... replace` creates the file on disk");

  // 2. Run a couple of commands while the log is open.
  (void)piet::dispatch("count", session);
  (void)piet::dispatch("summarize year", session);

  // 3. `log close` flushes + closes.
  (void)piet::dispatch("log close", session);

  {
    std::ifstream in(cecon::to_native_path(logPath));
    std::ostringstream ss;
    ss << in.rdbuf();
    std::string content = ss.str();
    check(!content.empty(), "BS-006: the log file has non-empty content after `log close`");
    check(content.find("count") != std::string::npos,
          "BS-006: the log transcript contains the echoed `count` command");
    check(content.find("summarize year") != std::string::npos,
          "BS-006: the log transcript contains the echoed `summarize year` command");
    // `summarize` has no pre-rendered "text" field anywhere in this codebase
    // (the webview renders it from raw JSON) -- logTee()'s generic
    // JSON->text fallback should still surface its own fields, headed by a
    // "[summarize]" marker line, not a stub placeholder.
    check(content.find("[summarize]") != std::string::npos,
          "BS-006: the summarize block's OWN fields reached the log via the generic "
          "JSON->text fallback (not just its echo line)");
  }

  // 4. `append` mode preserves prior content instead of truncating.
  auto appendOpenBlocks = piet::dispatch("log using \"" + logPath + "\", append text", session);
  bool appendOpenErr = false;
  for (const auto& b : appendOpenBlocks) {
    if (b.is_object() && b.value("type", std::string()) == "error") appendOpenErr = true;
  }
  check(!appendOpenErr, "BS-006: re-opening the SAME file with `append text` does not error");
  (void)piet::dispatch("display 2+2", session);
  (void)piet::dispatch("log close", session);
  {
    std::ifstream in(cecon::to_native_path(logPath));
    std::ostringstream ss;
    ss << in.rdbuf();
    std::string content = ss.str();
    check(content.find("summarize year") != std::string::npos,
          "BS-006: `append` preserves the PRIOR session's content (not truncated)");
    check(content.find("display 2+2") != std::string::npos,
          "BS-006: `append` also contains the NEW content written after re-opening");
  }

  // 5. `replace` truncates -- prior content is gone.
  (void)piet::dispatch("log using \"" + logPath + "\", replace text", session);
  (void)piet::dispatch("display 1+1", session);
  (void)piet::dispatch("log close", session);
  {
    std::ifstream in(cecon::to_native_path(logPath));
    std::ostringstream ss;
    ss << in.rdbuf();
    std::string content = ss.str();
    check(content.find("summarize") == std::string::npos,
          "BS-006: `replace` truncates -- the earlier session's content is gone");
    check(content.find("display 1+1") != std::string::npos,
          "BS-006: `replace` still contains the fresh content written after re-opening");
  }

  // 6. Bare `log using` (no replace/append) on an EXISTING file is an honest
  // reject (Stata's real "file already exists" r(602) idiom), not a silent
  // overwrite or silent append.
  {
    auto rejBlocks = piet::dispatch("log using \"" + logPath + "\"", session);
    bool sawErr = false;
    for (const auto& b : rejBlocks) {
      if (b.is_object() && b.value("type", std::string()) == "error") sawErr = true;
    }
    check(sawErr, "BS-006: bare `log using` on an EXISTING file (no replace/append) is an "
                  "honest reject, not silently accepted");
    // errors.cpp's coarseRc() maps this engine_error (message mentions
    // "file" + "already exists") to Stata's real r(602) with no new mapping
    // rule needed -- verify `capture`'s `_rc` actually lands there.
    (void)piet::dispatch("capture log using \"" + logPath + "\"", session);
    std::string rc = session.eval.locals.get("_rc");
    check(rc == "602",
          "BS-006: `capture log using` (existing file, no replace/append) sets _rc=602 (got '" +
              rc + "')");
  }

  // 7. A second `log using` while one is already open is ALSO an honest
  // reject (real Stata requires `log close` first) -- not a silent
  // discard-and-reopen.
  {
    std::string logPath2 = workdir + "/second.log";
    auto firstOpen = piet::dispatch("log using \"" + logPath2 + "\", replace text", session);
    bool firstOpenErr = false;
    for (const auto& b : firstOpen) {
      if (b.is_object() && b.value("type", std::string()) == "error") firstOpenErr = true;
    }
    check(!firstOpenErr, "BS-006: opening a fresh second log succeeds");
    std::string logPath3 = workdir + "/third.log";
    auto dupBlocks = piet::dispatch("log using \"" + logPath3 + "\", replace text", session);
    bool sawErr = false;
    for (const auto& b : dupBlocks) {
      if (b.is_object() && b.value("type", std::string()) == "error") sawErr = true;
    }
    check(sawErr, "BS-006: a second `log using` while one is already open is an honest reject");
    check(!fs::exists(logPath3, ec),
          "BS-006: the rejected second `log using` did not create third.log");
    (void)piet::dispatch("log close", session);
  }

  // 8. SMCL logs (`log using x.smcl`, or `log using FILE, smcl`) are written for
  // real; a file that claims SMCL is SMCL. The layout pinned below -- the
  // {smcl} marker, header, tagged echo and display lines, the log off / log on /
  // log close blocks, the final marker with no newline, the `append` run-on --
  // is what StataBE 19.5 wrote for the same do-file lines (captures of
  // `log using x.smcl` with display lines, `name()`, `append`, `log off` and
  // `log on`). Only the date stamps vary, so they are masked. The text arm at the
  // end pins the plain-text transcript byte for byte, captured from this build
  // BEFORE the SMCL writer existed, so the text path cannot drift unseen.
  {
    auto slurp8 = [](const std::string& p) {
      std::ifstream in(cecon::to_native_path(p), std::ios::binary);
      std::ostringstream ss;
      ss << in.rdbuf();
      return ss.str();
    };
    // "...on:  {res}28 Oct 2026, 02:46:04\n" -> "...on:  {res}<STAMP>\n"
    auto maskStamps = [](const std::string& s) {
      static const std::regex re(
          R"(on:  \{res\}[ 0-9]{2} [A-Z][a-z]{2} [0-9]{4}, [0-9]{2}:[0-9]{2}:[0-9]{2}\n)");
      return std::regex_replace(s, re, "on:  {res}<STAMP>\n");
    };
    auto fill = [](std::string s, const std::string& token, const std::string& value) {
      for (size_t at = s.find(token); at != std::string::npos; at = s.find(token, at + value.size())) {
        s.replace(at, token.size(), value);
      }
      return s;
    };
    // check() prints its label on a pass too, so the observed text is shown only
    // when the check fails.
    auto checkGot = [](bool ok, const std::string& label, const std::string& got) {
      check(ok, label);
      if (!ok) std::printf("[selftest]        got:\n%s\n[selftest]        --\n", got.c_str());
    };
    auto sawError = [](const nlohmann::ordered_json& blocks) {
      for (const auto& b : blocks) {
        if (b.is_object() && b.value("type", std::string()) == "error") return true;
      }
      return false;
    };

    // 8a. An unnamed .smcl log: display lines, a literal-brace command line,
    // log off / log on, log close.
    {
      const std::string P = workdir + "/x.smcl";
      const bool openErr = sawError(piet::dispatch("log using \"" + P + "\", replace", session));
      check(!openErr, "BS-006: `log using x.smcl, replace` opens (no unsupported_option reject)");
      (void)piet::dispatch("display \"plain\"", session);
      (void)piet::dispatch("display \"a {c -(} b {c )-} c\"", session);
      (void)piet::dispatch("display", session);
      (void)piet::dispatch("log off", session);
      (void)piet::dispatch("display \"not logged\"", session);
      (void)piet::dispatch("log on", session);
      (void)piet::dispatch("display \"after on\"", session);
      (void)piet::dispatch("log close", session);
      const std::string expected = fill(
          R"SMCL({smcl}
{txt}{sf}{ul off}{.-}
      name:  {res}<unnamed>
       {txt}log:  {res}@P@
  {txt}log type:  {res}smcl
 {txt}opened on:  {res}<STAMP>
{txt}
{com}. display "plain"
{res}plain
{txt}
{com}. display "a {c -(}c -({c )-} b {c -(}c )-{c )-} c"
{res}a {c -(} b {c )-} c
{txt}
{com}. display
{res}
{txt}
{com}. log off
      {txt}name:  {res}<unnamed>
       {txt}log:  {res}@P@
  {txt}log type:  {res}smcl
 {txt}paused on:  {res}<STAMP>
{txt}{.-}
{smcl}
{txt}{sf}{ul off}{smcl}
{com}{sf}{ul off}{txt}{.-}
      name:  {res}<unnamed>
       {txt}log:  {res}@P@
  {txt}log type:  {res}smcl
{txt}resumed on:  {res}<STAMP>
{txt}
{com}. display "after on"
{res}after on
{txt}
{com}. log close
      {txt}name:  {res}<unnamed>
       {txt}log:  {res}@P@
  {txt}log type:  {res}smcl
 {txt}closed on:  {res}<STAMP>
{txt}{.-}
{smcl}
{txt}{sf}{ul off})SMCL",
          "@P@", P);
      const std::string got = maskStamps(slurp8(P));
      checkGot(got == expected,
               "BS-006: the SMCL log is byte-for-byte StataBE's layout (header, tagged echo and "
               "display lines, escaped braces, log off/on blocks, closing marker)",
               got);
    }

    // 8b. A named log, closed and re-opened with `append`: the second segment
    // runs on from the first's closing marker with the continuation header.
    {
      const std::string Q = workdir + "/nm.smcl";
      (void)piet::dispatch("log using \"" + Q + "\", replace name(nm)", session);
      (void)piet::dispatch("display \"named hello\"", session);
      (void)piet::dispatch("log close nm", session);
      (void)piet::dispatch("log using \"" + Q + "\", append name(nm)", session);
      (void)piet::dispatch("display \"appended\"", session);
      (void)piet::dispatch("log close nm", session);
      const std::string expected = fill(
          R"SMCL({smcl}
{txt}{sf}{ul off}{.-}
      name:  {res}nm
       {txt}log:  {res}@Q@
  {txt}log type:  {res}smcl
 {txt}opened on:  {res}<STAMP>
{txt}
{com}. display "named hello"
{res}named hello
{txt}
{com}. log close nm
      {txt}name:  {res}nm
       {txt}log:  {res}@Q@
  {txt}log type:  {res}smcl
 {txt}closed on:  {res}<STAMP>
{txt}{.-}
{smcl}
{txt}{sf}{ul off}{smcl}
{com}{sf}{ul off}{txt}{.-}
      name:  {res}nm
       {txt}log:  {res}@Q@
  {txt}log type:  {res}smcl
 {txt}opened on:  {res}<STAMP>
{txt}
{com}. display "appended"
{res}appended
{txt}
{com}. log close nm
      {txt}name:  {res}nm
       {txt}log:  {res}@Q@
  {txt}log type:  {res}smcl
 {txt}closed on:  {res}<STAMP>
{txt}{.-}
{smcl}
{txt}{sf}{ul off})SMCL",
          "@Q@", Q);
      const std::string got = maskStamps(slurp8(Q));
      checkGot(got == expected,
               "BS-006: a named SMCL log, closed and re-opened with `append`, matches StataBE's "
               "layout (continuation header after the first closing marker)",
               got);
    }

    // 8c. Which format a file gets, and the extension it is given. StataBE:
    // `.smcl` -> SMCL, `.log` -> text, no extension -> `set logtype` (SMCL) and
    // ".smcl" appended, or ".log" when `text` is given; `text`/`smcl` decide
    // regardless of the extension. A dot in a directory name is not an extension.
    {
      const std::string dotted = workdir + "/d.v2";
      fs::create_directories(dotted, ec);
      auto runLogCase = [&](const std::string& typed, const std::string& opts) {
        (void)piet::dispatch("log using \"" + typed + "\", replace" + opts, session);
        (void)piet::dispatch("display \"body\"", session);
        (void)piet::dispatch("log close", session);
      };
      auto startsSmcl = [&](const std::string& p) {
        return slurp8(p).compare(0, 7, "{smcl}\n") == 0;
      };

      runLogCase(workdir + "/noext", "");
      check(fs::exists(workdir + "/noext.smcl", ec) && !fs::exists(workdir + "/noext", ec),
            "BS-006: no extension and no format option -> SMCL, \".smcl\" appended");
      check(startsSmcl(workdir + "/noext.smcl"), "BS-006: the extensionless default is SMCL");

      runLogCase(workdir + "/noext2", ", text");
      check(fs::exists(workdir + "/noext2.log", ec) && !fs::exists(workdir + "/noext2", ec),
            "BS-006: no extension with `text` -> \".log\" appended");
      check(!startsSmcl(workdir + "/noext2.log"), "BS-006: `text` writes a text log");

      runLogCase(dotted + "/noext3", "");
      check(fs::exists(dotted + "/noext3.smcl", ec) && !fs::exists(dotted + "/noext3", ec),
            "BS-006: a dot in the directory name is not a file extension");

      runLogCase(workdir + "/ext.log", "");
      check(fs::exists(workdir + "/ext.log", ec) && !startsSmcl(workdir + "/ext.log"),
            "BS-006: a .log file with no format option is a text log");

      runLogCase(workdir + "/ext2.smcl", ", text");
      check(fs::exists(workdir + "/ext2.smcl", ec) && !startsSmcl(workdir + "/ext2.smcl"),
            "BS-006: `text` wins over a .smcl extension");

      runLogCase(workdir + "/ext3.log", ", smcl");
      check(fs::exists(workdir + "/ext3.log", ec) && startsSmcl(workdir + "/ext3.log"),
            "BS-006: `smcl` wins over a .log extension");

      runLogCase(workdir + "/UPPER.SMCL", "");
      check(startsSmcl(workdir + "/UPPER.SMCL"), "BS-006: the .smcl extension is case-blind");

      check(sawError(piet::dispatch("log using \"" + workdir + "/both.log\", replace text smcl",
                                    session)),
            "BS-006: `text` and `smcl` together are a syntax error");
      check(!fs::exists(workdir + "/both.log", ec), "BS-006: the rejected open left no file");
    }

    // 8d. Non-display blocks and errors in an SMCL log: tagged, and literal
    // braces in PIET-made text escaped. A captured (noisily) error has no
    // r() line; an uncaptured one links its return code.
    {
      const std::string R = workdir + "/blocks.smcl";
      (void)piet::dispatch("log using \"" + R + "\", replace", session);
      (void)piet::dispatch("summarize year", session);
      (void)piet::dispatch("capture noisily confirm variable nosuchvar", session);
      const std::string braceFile = workdir + "/no{such}.dta";
      (void)piet::dispatch("use \"" + braceFile + "\"", session);
      (void)piet::dispatch("confirm variable nosuchvar2", session);
      // Text a command other than `display` prints is plain: `type` of a file
      // with SMCL-looking braces must not turn them into directives.
      const std::string typed = workdir + "/typed.txt";
      {
        std::ofstream f(cecon::to_native_path(typed), std::ios::binary);
        f << "type {bf:me} {x}\n";
      }
      (void)piet::dispatch("type \"" + typed + "\"", session);
      (void)piet::dispatch("log close", session);
      const std::string got = slurp8(R);
      check(got.find("{res}type {c -(}bf:me{c )-} {c -(}x{c )-}\n") != std::string::npos &&
                got.find("type {bf:me}") == std::string::npos,
            "BS-006: text a command other than `display` prints has its braces escaped");
      check(got.find("{com}. summarize year\n{txt}[summarize]\n") != std::string::npos,
            "BS-006: a result block follows its command line in {txt} mode");
      check(got.find("{com}. capture noisily confirm variable nosuchvar\n{err}") != std::string::npos,
            "BS-006: an error line is in {err} mode");
      check(got.find("{txt}{search r(111), local:r(111);}\n") != std::string::npos,
            "BS-006: an uncaptured error is followed by its linked return code");
      check(got.find("{search r(", got.find("{search r(111)") + 1) == std::string::npos,
            "BS-006: `capture noisily` prints no return-code line (only the uncaptured error does)");
      check(got.find("no{c -(}such{c )-}.dta") != std::string::npos && got.find("no{such}") == std::string::npos,
            "BS-006: literal braces in logged non-display text are escaped as {c -(} / {c )-}");
    }

    // 8e. A text log and an SMCL log open together each keep their own format.
    {
      const std::string T = workdir + "/both_t.log";
      const std::string S = workdir + "/both_s.smcl";
      (void)piet::dispatch("log using \"" + T + "\", replace text", session);
      (void)piet::dispatch("log using \"" + S + "\", replace name(s)", session);
      (void)piet::dispatch("display \"two formats\"", session);
      (void)piet::dispatch("log close s", session);
      (void)piet::dispatch("log close", session);
      const std::string t = slurp8(T);
      const std::string s = slurp8(S);
      check(t.compare(0, 1, "\n") == 0 && t.find("two formats\n") != std::string::npos &&
                t.find("{smcl}") == std::string::npos && t.find("{res}") == std::string::npos,
            "BS-006: the text log stays plain text while an SMCL log is open beside it");
      check(s.compare(0, 7, "{smcl}\n") == 0 && s.find("{res}two formats\n") != std::string::npos &&
                s.find("{com}. display \"two formats\"\n") != std::string::npos,
            "BS-006: the SMCL log beside a text log carries the tagged lines");
    }

    // 8g. Under `quietly` / `capture` the banner and footer text are suppressed
    // output, so StataBE writes only its structural markers where they would
    // stand ("{smcl}\n{com}{sf}{ul off}", no newline); `capture noisily` keeps
    // the full text. (Captures: `qui log off`, `qui log on`, `cap log close`,
    // `cap noisily log off`.)
    {
      const std::string K = workdir + "/quiet.smcl";
      (void)piet::dispatch("log using \"" + K + "\", replace", session);
      (void)piet::dispatch("display \"A\"", session);
      (void)piet::dispatch("qui log off", session);
      (void)piet::dispatch("display \"hidden\"", session);
      (void)piet::dispatch("qui log on", session);
      (void)piet::dispatch("display \"C\"", session);
      (void)piet::dispatch("cap noisily log off", session);
      (void)piet::dispatch("display \"hidden too\"", session);
      (void)piet::dispatch("cap noisily log on", session);
      (void)piet::dispatch("cap log close", session);
      const std::string expected = fill(
          R"SMCL({smcl}
{txt}{sf}{ul off}{.-}
      name:  {res}<unnamed>
       {txt}log:  {res}@K@
  {txt}log type:  {res}smcl
 {txt}opened on:  {res}<STAMP>
{txt}
{com}. display "A"
{res}A
{txt}
{com}. qui log off
{smcl}
{com}{sf}{ul off}{smcl}
{com}{sf}{ul off}{txt}
{com}. display "C"
{res}C
{txt}
{com}. cap noisily log off
      {txt}name:  {res}<unnamed>
       {txt}log:  {res}@K@
  {txt}log type:  {res}smcl
 {txt}paused on:  {res}<STAMP>
{txt}{.-}
{smcl}
{txt}{sf}{ul off}{smcl}
{com}{sf}{ul off}{txt}{.-}
      name:  {res}<unnamed>
       {txt}log:  {res}@K@
  {txt}log type:  {res}smcl
{txt}resumed on:  {res}<STAMP>
{txt}
{com}. cap log close
{smcl}
{com}{sf}{ul off})SMCL",
          "@K@", K);
      const std::string got = maskStamps(slurp8(K));
      checkGot(got == expected,
               "BS-006: quiet/capture `log off` / `log on` / `log close` write StataBE's short "
               "markers, `cap noisily` the full blocks",
               got);
    }

    // 8h. `log off` / `log on` inside a nested `do` file: the frame that carries
    // the whole file's blocks is written when it ends, and the pause takes effect
    // at its own line -- the lines between are not recorded and the `log on`
    // line is not either. (StataBE n1.smcl capture, same sub-do.)
    {
      const std::string N = workdir + "/nested.smcl";
      const std::string sub = workdir + "/nested_sub.do";
      {
        std::ofstream f(cecon::to_native_path(sub), std::ios::binary);
        f << "display \"sub A\"\ncap log off nest\ndisplay \"sub while off\"\n"
             "cap log on nest\ndisplay \"sub C\"\n";
      }
      (void)piet::dispatch("log using \"" + N + "\", replace name(nest)", session);
      (void)piet::dispatch("display \"master before\"", session);
      (void)piet::dispatch("do \"" + sub + "\"", session);
      (void)piet::dispatch("display \"master after\"", session);
      (void)piet::dispatch("log close nest", session);
      const std::string got = maskStamps(slurp8(N));
      const size_t offAt = got.find("{com}. cap log off nest\n{smcl}\n{com}{sf}{ul off}{smcl}\n"
                                    "{com}{sf}{ul off}{txt}\n{com}. display \"sub C\"\n");
      checkGot(offAt != std::string::npos &&
                   got.find("{com}. display \"sub A\"\n{res}sub A\n{txt}\n{com}. cap log off nest\n") !=
                       std::string::npos,
               "BS-006: a pause inside a nested do file takes effect at its own line, "
               "with the quiet markers",
               got);
      check(got.find("sub while off") == std::string::npos &&
                got.find("cap log on nest") == std::string::npos,
            "BS-006: lines between the nested `log off` and `log on`, and the `log on` line "
            "itself, are not recorded");
      const std::string tail = "{txt}{.-}\n{smcl}\n{txt}{sf}{ul off}";
      check(got.find("{com}. display \"master after\"\n{res}master after\n{txt}\n"
                     "{com}. log close nest\n      {txt}name:  {res}nest\n") != std::string::npos &&
                got.size() > tail.size() &&
                got.compare(got.size() - tail.size(), tail.size(), tail) == 0,
            "BS-006: the log closed after the nested file still gets its footer, in order");
    }

    // 8f. The text transcript, byte for byte, as this build wrote it before the
    // SMCL writer existed (captured from the pre-change binary on the same
    // lines): `log off` / `log on` echo skipping, a second named text log, an
    // error line, and a `.log` file with no format option. The extensionless
    // `text` log is the one intended change: it now gets ".log" appended.
    {
      const std::string A = workdir + "/t8a.log";
      const std::string B = workdir + "/t8b.txt";
      const std::string C = workdir + "/t8c.log";
      const std::string D = workdir + "/t8d";
      (void)piet::dispatch("log using \"" + A + "\", replace text", session);
      (void)piet::dispatch("display \"plain\"", session);
      (void)piet::dispatch("display \"brace {c -(} x\"", session);
      (void)piet::dispatch("count", session);
      (void)piet::dispatch("capture noisily confirm variable nosuchvar", session);
      (void)piet::dispatch("log using \"" + B + "\", replace text name(two)", session);
      (void)piet::dispatch("display \"both\"", session);
      (void)piet::dispatch("log off two", session);
      (void)piet::dispatch("display \"only first\"", session);
      (void)piet::dispatch("log on two", session);
      (void)piet::dispatch("display \"both again\"", session);
      (void)piet::dispatch("log close two", session);
      (void)piet::dispatch("display \"only first again\"", session);
      (void)piet::dispatch("log off", session);
      (void)piet::dispatch("display \"hidden\"", session);
      (void)piet::dispatch("log on", session);
      (void)piet::dispatch("display \"after\"", session);
      (void)piet::dispatch("log close", session);
      (void)piet::dispatch("log using \"" + C + "\", replace", session);
      (void)piet::dispatch("display \"ext log\"", session);
      (void)piet::dispatch("log close", session);
      (void)piet::dispatch("log using \"" + D + "\", replace text", session);
      (void)piet::dispatch("display \"noext text\"", session);
      (void)piet::dispatch("log close", session);
      const std::string expectA =
          "\n.  log using \"" + A + "\", replace text\n"
          "\n.  display \"plain\"\nplain\n"
          "\n.  display \"brace {c -(} x\"\nbrace {c -(} x\n"
          "\n.  count\n336\n"
          "\n.  capture noisily confirm variable nosuchvar\n"
          "variable nosuchvar not found\n(engine_error)\n"
          "\n.  log using \"" + B + "\", replace text name(two)\n"
          "\n.  display \"both\"\nboth\n"
          "\n.  log off two\n"
          "\n.  display \"only first\"\nonly first\n"
          "\n.  log on two\n"
          "\n.  display \"both again\"\nboth again\n"
          "\n.  log close two\n"
          "\n.  display \"only first again\"\nonly first again\n"
          "\n.  log on\n"
          "\n.  display \"after\"\nafter\n";
      const std::string expectB =
          "\n.  log using \"" + B + "\", replace text name(two)\n"
          "\n.  display \"both\"\nboth\n"
          "\n.  log on two\n"
          "\n.  display \"both again\"\nboth again\n";
      const std::string expectC =
          "\n.  log using \"" + C + "\", replace\n\n.  display \"ext log\"\next log\n";
      const std::string expectD =
          "\n.  log using \"" + D + "\", replace text\n\n.  display \"noext text\"\nnoext text\n";
      checkGot(slurp8(A) == expectA,
               "BS-006: the unnamed text log is byte-identical to the pre-SMCL transcript", slurp8(A));
      checkGot(slurp8(B) == expectB,
               "BS-006: the named text log (.txt, `text`) is byte-identical to the pre-SMCL "
               "transcript",
               slurp8(B));
      checkGot(slurp8(C) == expectC,
               "BS-006: a .log file with no format option is byte-identical to the pre-SMCL "
               "text transcript",
               slurp8(C));
      checkGot(slurp8(D + ".log") == expectD && !fs::exists(D, ec),
               "BS-006: an extensionless `text` log is the same transcript, now in \"<name>.log\"",
               slurp8(D + ".log"));
    }
  }

  // 9. `log off` suspends writes (stream stays open); `log on` resumes.
  {
    std::string pausePath = workdir + "/pause.log";
    (void)piet::dispatch("log using \"" + pausePath + "\", replace text", session);
    (void)piet::dispatch("display 111222333", session);
    (void)piet::dispatch("log off", session);
    (void)piet::dispatch("display 444555666", session);
    (void)piet::dispatch("log on", session);
    (void)piet::dispatch("display 777888999", session);
    (void)piet::dispatch("log close", session);
    std::ifstream in(cecon::to_native_path(pausePath));
    std::ostringstream ss;
    ss << in.rdbuf();
    std::string content = ss.str();
    check(content.find("111222333") != std::string::npos,
          "BS-006: content written BEFORE `log off` reaches the file");
    check(content.find("444555666") == std::string::npos,
          "BS-006: `log off` suspends writes -- paused-period content is absent");
    check(content.find("777888999") != std::string::npos,
          "BS-006: `log on` resumes writes after a pause");
  }

  fs::remove_all(workdir, ec);
}

// BETA campaign Phase B (B-graph part A cluster): title()/subtitle()/
// xtitle()/ytitle() dequote + glued-suboption strip (BS-008/U1), note()
// wiring (BS-009/U2), bare-form name() -> namedGraphs registration
// (BS-010/U3), and `graph combine ..., name(X, replace)` suffix-leak fix
// (BS-057). All four share ONE mechanism (BS-099's "single title/axis/
// legend/name/note consumer") added in graph_m4.cpp.
void testBS008To057GraphTitleNoteName() {
  std::printf("[selftest] --- BS-008/009/010/057 graph title/note/name (B-graph part A) ---\n");
  namespace fs = std::filesystem;
  std::string base = (fs::temp_directory_path() / "piet_native_selftest_bs008graph").u8string();
  std::error_code ec;
  fs::remove_all(base, ec);
  fs::create_directories(base, ec);

  auto runCmd = [](piet::SessionState& session, const std::string& cmd) {
    nlohmann::json body{{"cmd", cmd}};
    auto r = piet::routes::command(session, body.dump());
    return nlohmann::json::parse(r.json);
  };
  auto firstBlockOfType = [](const nlohmann::json& j, const std::string& type) -> nlohmann::json {
    for (const auto& b : j.value("blocks", nlohmann::json::array())) {
      if (b.value("type", std::string()) == type) return b;
    }
    return nlohmann::json();
  };

  // Every leg below builds its graphs from real `fatal`/`beertax` columns
  // and chains firstBlockOfType(...).value(...) unguarded. In the isolated/
  // subset-build environment (no piet/packaging/sample/fatalities.csv), that
  // throws the same json.exception.type_error.306 as the earlier BUG-039/
  // BUG-055/BUG-056/BS-013/BS-048/BS-047 legs (FIX-SELFTEST-ISOBUILD-CRASH).
  // One up-front probe covers all five legs below (a single skip() call,
  // same as the block-level skips elsewhere in this file) instead of
  // guarding each block individually.
  {
    std::string probeWd = base + "/_fixture_probe";
    fs::create_directories(probeWd, ec);
    piet::SessionState probeSession(probeWd);
    runCmd(probeSession, "sysuse fatalities, clear");
    if (!probeSession.hasData()) {
      skip("BS-008/009/010/057 graph title/note/name (all 5 legs)",
           "`sysuse fatalities` setup returned no data");
      fs::remove_all(base, ec);
      return;
    }
  }

  // --- BS-008 (U1): title()/xtitle()/ytitle() dequote + glued sub-option
  // strip -- the idiomatic quoted-title-with-a-suboption shape analysis.do
  // actually uses (e.g. `title("`depvar_label'", size(medsmall))`).
  {
    std::string wd = base + "/title";
    fs::create_directories(wd, ec);
    piet::SessionState session(wd);
    runCmd(session, "sysuse fatalities, clear");
    auto j = runCmd(session,
        R"DO(scatter fatal beertax, title("Fatalities vs Beertax", size(large)) xtitle("Beer tax ($)") ytitle("Traffic fatalities"))DO");
    auto g = firstBlockOfType(j, "graph");
    check(g.value("title", std::string()) == "Fatalities vs Beertax",
          "BS-008: quoted title() with a glued size() suboption dequotes to clean text (got \"" +
              g.value("title", std::string()) + "\")");
    check(g.value("title", std::string()).find('"') == std::string::npos,
          "BS-008: dequoted title carries no literal quote characters");
    check(g.value("x_label", std::string()) == "Beer tax ($)",
          "BS-008: quoted xtitle() dequotes to clean text (got \"" + g.value("x_label", std::string()) +
              "\")");
    check(g.value("y_label", std::string()) == "Traffic fatalities",
          "BS-008: quoted ytitle() dequotes to clean text (got \"" + g.value("y_label", std::string()) +
              "\")");
  }

  // --- BS-008 regression guard: an UNQUOTED bare title with a glued
  // suboption also gets the suboption stripped (not just the quoted case).
  {
    std::string wd = base + "/title_bare";
    fs::create_directories(wd, ec);
    piet::SessionState session(wd);
    runCmd(session, "sysuse fatalities, clear");
    auto j = runCmd(session, "scatter fatal beertax, title(Beertax, size(large))");
    auto g = firstBlockOfType(j, "graph");
    check(g.value("title", std::string()) == "Beertax",
          "BS-008: an unquoted bare title(Beertax, size(large)) still strips the glued "
          "suboption (got \"" +
              g.value("title", std::string()) + "\")");
  }

  // --- BS-009 (U2): note() reaches the block, dequoted; absent note() ->
  // present-but-empty (never dropped, never errors).
  {
    std::string wd = base + "/note";
    fs::create_directories(wd, ec);
    piet::SessionState session(wd);
    runCmd(session, "sysuse fatalities, clear");
    auto j = runCmd(session, R"(scatter fatal beertax, note("Source: test fixture."))");
    auto g = firstBlockOfType(j, "graph");
    check(g.contains("note"),
          "BS-009: the graph block now carries a `note` key at all (previously absent entirely)");
    check(g.value("note", std::string()) == "Source: test fixture.",
          "BS-009: note() text reaches the block, dequoted (got \"" + g.value("note", std::string()) +
              "\")");

    auto j2 = runCmd(session, "scatter fatal beertax");
    auto g2 = firstBlockOfType(j2, "graph");
    check(g2.contains("note") && g2.value("note", std::string()).empty(),
          "BS-009 regression guard: a graph with no note() still carries a `note` key, empty by "
          "default");
  }

  // --- BS-010 (U3): bare-form name() registers into namedGraphs (mirrors
  // the already-working parenthesised twoway path at dispatcher.cpp).
  {
    std::string wd = base + "/name";
    fs::create_directories(wd, ec);
    piet::SessionState session(wd);
    runCmd(session, "sysuse fatalities, clear");
    check(session.namedGraphs.empty(), "BS-010 setup: namedGraphs starts empty");

    runCmd(session, "scatter fatal beertax, name(scatterG)");
    check(session.namedGraphs.count("scatterG") == 1,
          "BS-010: bare `scatter ..., name(scatterG)` registers scatterG in namedGraphs "
          "(previously bare forms never registered at all)");

    runCmd(session, "histogram fatal, name(histG, replace)");
    check(session.namedGraphs.count("histG") == 1,
          "BS-010: bare `histogram ..., name(histG, replace)` registers the BARE name "
          "(glued `, replace` suboption stripped, same rule as the twoway path)");
    check(session.namedGraphs.count("histG, replace") == 0,
          "BS-010: the raw \"histG, replace\" string is NOT used as the stored key");

    runCmd(session, "kdensity fatal, name(kdensG)");
    check(session.namedGraphs.count("kdensG") == 1, "BS-010: bare `kdensity ..., name(kdensG)` registers");

    runCmd(session, "line fatal beertax, name(lineG)");
    check(session.namedGraphs.count("lineG") == 1, "BS-010: bare `line ..., name(lineG)` registers");

    // xtset ALSO seeds session.timevar (handlers_m3.cpp::runXtset), so one
    // call unblocks both xtline (needs panelvar+timevar) and tsline (needs
    // only timevar) -- no separate tsset needed on this multi-state panel.
    // The panel id is numeric: xtset refuses the string `state` (BUG-1164).
    runCmd(session, "egen sid = group(state)");
    runCmd(session, "xtset sid year");
    runCmd(session, "xtline fatal, name(xtlineG)");
    check(session.namedGraphs.count("xtlineG") == 1, "BS-010: bare `xtline ..., name(xtlineG)` registers");
    runCmd(session, "tsline fatal, name(tslineG)");
    check(session.namedGraphs.count("tslineG") == 1, "BS-010: bare `tsline ..., name(tslineG)` registers");

    // End-to-end proof: a bare-form-registered graph can actually be
    // combined -- the whole point of the named-panels -> `graph combine`
    // idiom this fix unblocks (previously `graph combine` honestly
    // rejected with "no graph named 'scatterG'" for every one of these).
    auto jc = runCmd(session, "graph combine scatterG histG");
    auto errC = firstBlockOfType(jc, "error");
    check(errC.is_null(),
          "BS-010: `graph combine scatterG histG` succeeds (both bare-form names resolve)");
  }

  // --- BS-057: `graph combine ..., name(X, replace)` -- stored key has no
  // suffix (previously "combined_X, replace" was baked in verbatim).
  {
    std::string wd = base + "/combine_name";
    fs::create_directories(wd, ec);
    piet::SessionState session(wd);
    runCmd(session, "sysuse fatalities, clear");
    runCmd(session, "scatter fatal beertax, name(panelA)");
    runCmd(session, "histogram fatal, name(panelB)");
    auto j = runCmd(session, "graph combine panelA panelB, name(combined_X, replace)");
    auto errC = firstBlockOfType(j, "error");
    check(errC.is_null(), "BS-057 setup: `graph combine panelA panelB, name(combined_X, replace)` succeeds");
    check(session.namedGraphs.count("combined_X") == 1,
          "BS-057: the stored namedGraphs key is the bare \"combined_X\" (suffix stripped)");
    check(session.namedGraphs.count("combined_X, replace") == 0,
          "BS-057: the literal \"combined_X, replace\" string is NOT baked into the stored key "
          "(previously it was)");
    auto gc = firstBlockOfType(j, "graph");
    check(gc.value("name", std::string()) == "combined_X",
          "BS-057: the returned block's own `name` field is also the bare \"combined_X\", not "
          "\"combined_X, replace\"");

    // Regression guard: `, replace` genuinely replaces (re-running under
    // the same cleaned name overwrites in place, doesn't accumulate a
    // second, differently-keyed entry).
    size_t countBefore = session.namedGraphs.size();
    runCmd(session, "graph combine panelA panelB, name(combined_X, replace)");
    check(session.namedGraphs.size() == countBefore,
          "BS-057 regression guard: re-combining under the same cleaned name replaces in place "
          "(map size unchanged), does not accumulate duplicate suffixed keys");
  }

  fs::remove_all(base, ec);
}

// BETA campaign Phase B (B-graph part B cluster): `graph combine` on-disk
// `.gph` file-path resolution (BS-007/D3), coefplot/marginsplot ->
// lastGraph/namedGraphs registration (BS-011), `graph export` `as(fmt)`
// parse + honest PNG/PDF-fallback wording (BS-012/D8).
void testBS007To012GraphCombineExportRegister() {
  std::printf(
      "[selftest] --- BS-007/011/012 graph combine .gph + coefplot/marginsplot register + "
      "export as() (B-graph part B) ---\n");
  namespace fs = std::filesystem;
  std::string base = (fs::temp_directory_path() / "piet_native_selftest_bs007graphb").u8string();
  std::error_code ec;
  fs::remove_all(base, ec);
  fs::create_directories(base, ec);

  auto runCmd = [](piet::SessionState& session, const std::string& cmd) {
    nlohmann::json body{{"cmd", cmd}};
    auto r = piet::routes::command(session, body.dump());
    return nlohmann::json::parse(r.json);
  };
  auto firstBlockOfType = [](const nlohmann::json& j, const std::string& type) -> nlohmann::json {
    for (const auto& b : j.value("blocks", nlohmann::json::array())) {
      if (b.value("type", std::string()) == type) return b;
    }
    return nlohmann::json();
  };
  auto readFile = [](const std::string& path) -> std::string {
    std::ifstream in(cecon::to_native_path(path), std::ios::binary);
    std::ostringstream ss;
    ss << in.rdbuf();
    return ss.str();
  };

  // --- BS-007 (D3): `graph save NAME "file.gph"` writes a real spec-JSON
  // file (never a raster/frozen-pixel format); `graph combine "a.gph"
  // "b.gph"` (quoted FILE-PATH args, not names) loads and re-renders them.
  // Mirrors analysis.do's actual loop-then-combine idiom: `graph save` a
  // DIFFERENT tempfile each iteration while reusing the SAME in-memory
  // name -- so only the on-disk files carry each iteration's distinct
  // graph by the time `graph combine` runs (analysis.do:1533's
  // `graph_list` accumulates quoted tempfile paths, not names).
  {
    std::string wd = base + "/combine_gph";
    fs::create_directories(wd, ec);
    piet::SessionState session(wd);
    runCmd(session, "sysuse fatalities, clear");
    if (!session.hasData()) {
      // Same isolated/subset-build fixture gap as the earlier BUG-039/
      // BUG-055/BUG-056/BS-013/BS-048/BS-047/BS-008..057 legs above
      // (FIX-SELFTEST-ISOBUILD-CRASH): without fatalities.csv, `scatter`/
      // `histogram` never produce real graph blocks and the unguarded
      // .value() calls below would crash. Skip the whole .gph-combine leg.
      skip("BS-007 .gph-combine leg", "`sysuse fatalities` setup returned no data");
    } else {
      std::string p1 = wd + "/panel1.gph";
      std::string p2 = wd + "/panel2.gph";

      runCmd(session, "scatter fatal beertax, name(loopG)");
      auto jSave1 = runCmd(session, "graph save loopG \"" + p1 + "\", replace");
      check(firstBlockOfType(jSave1, "error").is_null(),
            "BS-007 setup: `graph save loopG \"panel1.gph\"` succeeds");
      check(fs::exists(p1, ec), "BS-007: `graph save` writes a real file to disk at the given path");

      std::string content1 = readFile(p1);
      check(content1.find("\"_magic\":\"PIETGPH1\"") != std::string::npos,
            "BS-007 (D3): the saved .gph file is the spec-JSON envelope (PIETGPH1 magic), never a "
            "raster/frozen-pixel format");
      check(content1.find("\"kind\":\"scatter\"") != std::string::npos,
            "BS-007: the saved .gph's embedded block is the actual scatter spec");

      // Same in-memory name, DIFFERENT graph, saved to a DIFFERENT file.
      // serset-twoway SS: redrawing onto a name in memory needs `replace` --
      // without it Stata answers `graph loopG already exists`, r(110)
      // (w2al_twoway_family.log:5024-5029 tf_st_dup2), so the loop idiom this
      // leg models writes name(loopG, replace).
      runCmd(session, "histogram fatal, name(loopG, replace)");
      auto jSave2 = runCmd(session, "graph save loopG \"" + p2 + "\", replace");
      check(firstBlockOfType(jSave2, "error").is_null(),
            "BS-007 setup: `graph save loopG \"panel2.gph\"` (2nd iteration, same name) succeeds");
      check(session.namedGraphs.count("loopG") == 1 &&
                session.namedGraphs.at("loopG").value("kind", std::string()) == "histogram",
            "BS-007 setup: the in-memory \"loopG\" now holds only the LAST iteration (histogram) -- "
            "proving a name-only combine could not have recovered the scatter panel");

      // `graph combine` with QUOTED FILE-PATH args (not names) -- BS-007's
      // actual fix. Previously this was a hard failure: "no graph named
      // '\"panel1.gph\"'" (the literal quoted string as a namedGraphs key,
      // since the tokenizer is not quote-aware and nothing tried a file load).
      auto jCombine = runCmd(session, "graph combine \"" + p1 + "\" \"" + p2 + "\"");
      auto errCombine = firstBlockOfType(jCombine, "error");
      check(errCombine.is_null(),
            "BS-007: `graph combine \"panel1.gph\" \"panel2.gph\"` (on-disk paths) succeeds (was a "
            "hard failure before)");
      auto gCombine = firstBlockOfType(jCombine, "graph");
      check(gCombine.value("kind", std::string()) == "graph_combine",
            "BS-007: the combine result is a graph_combine block");
      auto panels = gCombine.value("panels", nlohmann::json::array());
      check(panels.size() == 2, "BS-007: the combine has both panels (2), not 0/1");
      if (panels.size() == 2) {
        check(panels[0].value("kind", std::string()) == "scatter",
              "BS-007: panel 1 (loaded from panel1.gph) is the ORIGINAL scatter, not the "
              "later-overwritten in-memory histogram");
        check(panels[1].value("kind", std::string()) == "histogram",
              "BS-007: panel 2 (loaded from panel2.gph) is the histogram");
      }

      // Regression guard: a plain bare NAME still resolves via namedGraphs
      // (the pre-existing behavior is untouched by the new file-load branch).
      auto jCombineName = runCmd(session, "graph combine loopG loopG");
      check(firstBlockOfType(jCombineName, "error").is_null(),
            "BS-007 regression guard: bare-name `graph combine loopG loopG` (no file paths) still "
            "resolves via session.namedGraphs as before");

      // Honest reject: a token that resolves as NEITHER an in-memory graph
      // NOR a readable .gph file.
      auto jBad = runCmd(session, "graph combine nosuchgraph123");
      auto errBad = firstBlockOfType(jBad, "error");
      check(!errBad.is_null(),
            "BS-007: `graph combine` on an unresolvable token (no name, no file) is an honest "
            "error, not a crash");
    }
  }

  // --- BS-011: coefplot/marginsplot populate session.lastGraph + (when
  // name() is given) session.namedGraphs, mirroring scatter/twoway. Without
  // this, `graph export`/`graph save`/`graph combine` unconditionally
  // failed with "no graph in memory" immediately after either command.
  {
    std::string wd = base + "/coefplot_register";
    fs::create_directories(wd, ec);
    piet::SessionState session(wd);
    runCmd(session, "sysuse fatalities, clear");
    if (!session.hasData()) {
      // Same isolated/subset-build fixture gap as BS-007 above
      // (FIX-SELFTEST-ISOBUILD-CRASH): without fatalities.csv, `regress`/
      // `coefplot`/`logit`/`marginsplot` never produce real blocks and the
      // unguarded .value() calls below would crash. Skip the whole
      // coefplot/marginsplot-register leg.
      skip("BS-011 coefplot/marginsplot-register leg", "`sysuse fatalities` setup returned no data");
    } else {
      check(!session.lastGraph.has_value(), "BS-011 setup: lastGraph starts unset");

      runCmd(session, "regress fatal beertax unemp");
      auto jCoef = runCmd(session, "coefplot");
      check(firstBlockOfType(jCoef, "error").is_null(), "BS-011 setup: bare `coefplot` succeeds");
      check(session.lastGraph.has_value() && session.lastGraph->value("kind", std::string()) == "coefplot",
            "BS-011: `coefplot` now populates session.lastGraph (previously never set at all)");

      // The actual proof: export succeeds right after coefplot (was an
      // honest "no graph in memory" failure before this fix).
      std::string coefSvg = wd + "/coef.svg";
      auto jExpCoef = runCmd(session, "graph export \"" + coefSvg + "\", replace");
      check(firstBlockOfType(jExpCoef, "error").is_null(),
            "BS-011: `graph export` succeeds immediately after `coefplot` (was \"no graph in "
            "memory\" before this fix)");
      check(fs::exists(coefSvg, ec), "BS-011: the coefplot export actually wrote a file");
      check(readFile(coefSvg).rfind("<svg", 0) == 0,
            "BS-011: the coefplot export is a real SVG document (starts with <svg -- proves "
            "buildSvgDispatch has a coefplot branch, not a crash/garbage render)");

      // name() registration also works for coefplot.
      runCmd(session, "coefplot, name(coefG)");
      check(session.namedGraphs.count("coefG") == 1,
            "BS-011: `coefplot ..., name(coefG)` registers into namedGraphs same as scatter/twoway");

      // marginsplot: same proof, after logit + margins.
      runCmd(session, "gen ybin = spirits > 2");
      runCmd(session, "logit ybin unemp");
      runCmd(session, "margins, dydx(*)");
      auto jMp = runCmd(session, "marginsplot");
      check(firstBlockOfType(jMp, "error").is_null(), "BS-011 setup: bare `marginsplot` succeeds");
      check(session.lastGraph.has_value() && session.lastGraph->value("kind", std::string()) == "marginsplot",
            "BS-011: `marginsplot` now populates session.lastGraph (previously never set at all)");

      std::string mpSvg = wd + "/mp.svg";
      auto jExpMp = runCmd(session, "graph export \"" + mpSvg + "\", replace");
      check(firstBlockOfType(jExpMp, "error").is_null(),
            "BS-011: `graph export` succeeds immediately after `marginsplot` (was \"no graph in "
            "memory\" before this fix)");
      check(fs::exists(mpSvg, ec), "BS-011: the marginsplot export actually wrote a file");
      check(readFile(mpSvg).rfind("<svg", 0) == 0,
            "BS-011: the marginsplot export is a real SVG document (buildSvgDispatch has a "
            "marginsplot branch)");

      runCmd(session, "marginsplot, name(mpG)");
      check(session.namedGraphs.count("mpG") == 1,
            "BS-011: `marginsplot ..., name(mpG)` registers into namedGraphs same as scatter/twoway");

      // End-to-end: the two newly-registered named graphs (different kinds)
      // can be combined together.
      auto jCombineBoth = runCmd(session, "graph combine coefG mpG");
      check(firstBlockOfType(jCombineBoth, "error").is_null(),
            "BS-011: coefplot+marginsplot named graphs can be `graph combine`d together");
    }
  }

  // --- L2-FIX-B (BUG-066 / C3-F5): LIVE-VIEW point decimation. A big scatter
  // is thinned for the console/bridge block (bounded DOM + bridge copy) with an
  // honest n_shown_points/n_total_points tag, while session.lastGraph -- what
  // `graph export`/`save`/`combine` read -- keeps EVERY point (golden-pinned,
  // no re-pin). A sub-threshold graph is left completely untouched.
  {
    std::string wd = base + "/liveview_decimation";
    fs::create_directories(wd, ec);
    piet::SessionState session(wd);

    // 6000 finite points > the 5000-point view budget -> must decimate.
    runCmd(session, "set obs 6000");
    runCmd(session, "gen x = _n");
    runCmd(session, "gen y = _n * 2");
    auto jBig = runCmd(session, "scatter y x");
    auto gBig = firstBlockOfType(jBig, "graph");
    check(gBig.value("kind", std::string()) == "scatter",
          "L2-FIX-B setup: 6000-row `scatter y x` renders a scatter graph block");

    const size_t viewBudget = 5000;
    check(gBig.contains("n_total_points") && gBig.contains("n_shown_points"),
          "L2-FIX-B: an over-budget scatter is tagged with n_total_points/n_shown_points");
    size_t nTotal = gBig.value("n_total_points", size_t{0});
    size_t nShown = gBig.value("n_shown_points", size_t{0});
    check(nTotal == 6000,
          "L2-FIX-B: n_total_points reports the TRUE plotted-point count (6000), not the thinned one");
    check(nShown < nTotal && nShown <= viewBudget,
          "L2-FIX-B: the live view is thinned below the view budget (n_shown < n_total, <= 5000)");
    check(gBig["points"].is_array() && gBig["points"].size() == nShown,
          "L2-FIX-B: the live-view block's points array size equals the reported n_shown_points");

    // The FULL block is what `graph export` reads -- session.lastGraph must
    // still hold all 6000 points and carry NO thinning tag.
    check(session.lastGraph.has_value(),
          "L2-FIX-B: session.lastGraph is populated after the scatter");
    check(session.lastGraph->value("points", nlohmann::ordered_json::array()).size() == 6000,
          "L2-FIX-B: session.lastGraph (the `graph export` source) keeps ALL 6000 points -- live-view "
          "decimation never touches the export path");
    check(!session.lastGraph->contains("n_shown_points"),
          "L2-FIX-B: the cached full block is NOT tagged as decimated (only the live-view copy is)");

    // A `graph export` off that full block succeeds and writes real SVG (the
    // golden-pinned path is reached with the untouched point set).
    std::string svgOut = wd + "/full_export.svg";
    auto jExp = runCmd(session, "graph export \"" + svgOut + "\", replace");
    check(firstBlockOfType(jExp, "error").is_null(),
          "L2-FIX-B: `graph export` after a decimated live view still succeeds");
    check(fs::exists(svgOut, ec) && readFile(svgOut).rfind("<svg", 0) == 0,
          "L2-FIX-B: the exported file is real SVG built from the full (undecimated) block");

    // Sub-threshold guard: a small scatter is passed through verbatim -- no
    // thinning tag, no dropped points, so ordinary classroom graphs are
    // byte-identical to before this fix.
    fs::create_directories(wd + "/small", ec);
    piet::SessionState small(wd + "/small");
    runCmd(small, "set obs 200");
    runCmd(small, "gen x2 = _n");
    runCmd(small, "gen y2 = _n + 1");
    auto jSmall = runCmd(small, "scatter y2 x2");
    auto gSmall = firstBlockOfType(jSmall, "graph");
    check(!gSmall.contains("n_shown_points") && !gSmall.contains("n_total_points"),
          "L2-FIX-B: a sub-budget scatter (200 pts) carries NO decimation tag");
    check(gSmall["points"].is_array() && gSmall["points"].size() == 200,
          "L2-FIX-B: a sub-budget scatter keeps every point (no thinning)");
  }

  // --- BS-012 (D8): `graph export FILE.png` -- honest .svg fallback +
  // explicit "rasterizer pending" warning, NEVER SVG bytes saved under the
  // literal .png name. `as(fmt)` parse (format wins over/supplies a missing
  // extension).
  {
    std::string wd = base + "/export_png_fallback";
    fs::create_directories(wd, ec);
    piet::SessionState session(wd);
    runCmd(session, "sysuse fatalities, clear");
    if (!session.hasData()) {
      // Same isolated/subset-build fixture gap as BS-007/BS-011 above
      // (FIX-SELFTEST-ISOBUILD-CRASH): without fatalities.csv, `scatter`
      // never produces a real graph to export and the unguarded `disp`
      // .value() call below would crash. Skip the whole export-fallback leg.
      skip("BS-012 export-png-fallback leg", "`sysuse fatalities` setup returned no data");
    } else {
      runCmd(session, "scatter fatal beertax");

      // graph-family AI-13: the png is written AS a png at the path given
      // (w2ai gf_exp_004 `file ... saved as PNG format`, log:1939-1951); the
      // .svg sibling fallback and its "rasterizer pending" note are retired.
      std::string pngPath = wd + "/plot.png";
      auto j = runCmd(session, "graph export \"" + pngPath + "\", replace");
      check(firstBlockOfType(j, "error").is_null(), "BS-012 setup: `graph export FILE.png` does not error");
      check(fs::exists(pngPath, ec), "AI-13: the .png is written at the literal path");
      check(readFile(pngPath).rfind("\x89PNG\r\n\x1a\n", 0) == 0,
            "AI-13: the .png file is a real PNG (signature), never SVG bytes under a .png name");
      auto disp = firstBlockOfType(j, "display");
      check(disp.value("text", std::string()).find("saved as PNG format") != std::string::npos,
            "AI-13: the response says the file was saved as PNG (gr_export's own wording)");

      // `as(png)` with an EXTENSIONLESS path: the format comes from as(), and
      // the file is written at the path AS GIVEN -- Stata appends nothing
      // (w2ai gf_exp_asonly_f 0, gf_exp_asonly_png_f 601, log:1987-2001).
      std::string noExtPath = wd + "/noext_plot";
      auto j2 = runCmd(session, "graph export \"" + noExtPath + "\", as(png) replace");
      check(firstBlockOfType(j2, "error").is_null(),
            "BS-012 (D8): `as(png)` on an extensionless filename is honored (format comes from "
            "as(), not the missing extension)");
      check(fs::exists(noExtPath, ec), "AI-13: as(png) writes the bare extensionless path");
      check(!fs::exists(noExtPath + ".png", ec) && !fs::exists(noExtPath + ".svg", ec),
            "AI-13: nothing is written under an appended suffix");

      // `as(svg)` writes real SVG directly to the path AS GIVEN (not the
      // png/pdf fallback branch).
      std::string asSvgPath = wd + "/explicit_as_svg";
      auto j3 = runCmd(session, "graph export \"" + asSvgPath + "\", as(svg) replace");
      check(firstBlockOfType(j3, "error").is_null(), "BS-012: `as(svg)` on an extensionless path succeeds");
      check(fs::exists(asSvgPath, ec),
            "BS-012: `as(svg)` writes to the path AS GIVEN (no .svg appended -- the real format, "
            "not the png/pdf fallback)");

      // Regression guard: an unrecognised extension with no as() is still an
      // honest reject.
      auto j4 = runCmd(session, "graph export \"" + (wd + "/bad.xyz") + "\", replace");
      auto err4 = firstBlockOfType(j4, "error");
      check(!err4.is_null(),
            "BS-012 regression guard: an unrecognised extension (no as()) is still an honest "
            "\"unsupported format\" reject");
    }
  }

  // --- BUG-796..799 (FU-112/FU-113): legend(order(...)) is parsed once into
  // its top-level suboptions (quote- and paren-aware). Oracle: Stata's
  // legend_options -- a quoted key label may hold any character; `off` is a
  // suboption token; order() takes bare indices; an index with no plot is
  // ignored. Every arm below fails on the pre-fix regex parse.
  {
    std::string wd = base + "/legend_order_labels";
    fs::create_directories(wd, ec);
    piet::SessionState session(wd);
    runCmd(session, "clear");
    runCmd(session, "set obs 10");
    runCmd(session, "gen double lx = _n");
    runCmd(session, "gen double ly1 = lx");
    runCmd(session, "gen double ly2 = 2*lx");
    runCmd(session, "gen double ly3 = 3*lx");
    runCmd(session, "gen double ly4 = 4*lx");
    runCmd(session, "label variable ly2 \"Second series\"");
    auto legendOf = [&](const std::string& cmd) {
      auto j = runCmd(session, cmd);
      nlohmann::json g;
      for (const auto& b : j.value("blocks", nlohmann::json::array())) {
        if (b.value("type", std::string()) == "graph") g = b;
      }
      return g.is_object() ? g.value("legend", nlohmann::json::object()) : nlohmann::json::object();
    };
    const std::string four = "twoway (line ly1 lx) (line ly2 lx) (line ly3 lx) (line ly4 lx)";
    const std::string two = "twoway (line ly1 lx) (line ly2 lx)";

    // (1) FU-112: a parenthesised label keeps its entry.
    auto lg1 = legendOf(four + ", legend(order(1 \"a\" 4 \"All ages (pooled)\"))");
    check(lg1.value("order", nlohmann::json::array()) ==
              nlohmann::json::parse("[[0,\"a\"],[3,\"All ages (pooled)\"]]"),
          "BUG-796: legend(order(1 \"a\" 4 \"All ages (pooled)\")) keeps BOTH entries (the label's `)` "
          "ended the old order() capture). Got " + lg1.value("order", nlohmann::json::array()).dump());
    {
      const std::string svg = wd + "/paren.svg";
      runCmd(session, "graph export \"" + svg + "\", replace");
      std::ifstream in(svg);
      std::string txt((std::istreambuf_iterator<char>(in)), std::istreambuf_iterator<char>());
      check(txt.find(">All ages (pooled)</text>") != std::string::npos,
            "BUG-796: ...and the exported SVG carries a <text> reading All ages (pooled)");
    }
    // nested parens in a label (compound quotes are refused upstream of this parser)
    auto lg1b = legendOf(two + ", legend(order(1 \"p (q (r))\" 2 \"z\"))");
    check(lg1b.value("order", nlohmann::json::array()) ==
              nlohmann::json::parse("[[0,\"p (q (r))\"],[1,\"z\"]]"),
          "BUG-796: a label with nested parens parses. Got " +
              lg1b.value("order", nlohmann::json::array()).dump());

    // (2) `off` inside a label is not the off token; legend(off) still is.
    auto lg2 = legendOf(two + ", legend(order(1 \"Payoff\" 2 \"Cutoff\"))");
    check(!lg2.value("off", true) && lg2.value("order", nlohmann::json::array()).size() == 2,
          "BUG-797: legend(order(1 \"Payoff\" 2 \"Cutoff\")) keeps the legend ON with two entries. Got " +
              lg2.dump());
    auto lg2b = legendOf(two + ", legend(off)");
    check(lg2b.value("off", false), "BUG-797 control: legend(off) still turns the legend off");

    // (3) bare indices keep the plot's default key text (y-variable label, else name).
    auto lg3 = legendOf(two + ", legend(order(2 1))");
    check(lg3.value("order", nlohmann::json::array()) ==
              nlohmann::json::parse("[[1,\"Second series\"],[0,\"ly1\"]]"),
          "BUG-798: legend(order(2 1)) reorders with the default key text (variable label, else "
          "name). Got " + lg3.value("order", nlohmann::json::array()).dump());
    auto lg3b = legendOf(two + ", legend(order(2 \"B\" 1))");
    check(lg3b.value("order", nlohmann::json::array()) ==
              nlohmann::json::parse("[[1,\"B\"],[0,\"ly1\"]]"),
          "BUG-798: a bare index beside a labelled one keeps its default text. Got " +
              lg3b.value("order", nlohmann::json::array()).dump());

    // (5) size( / cols( inside a label do not bind to the suboptions.
    auto lg5 = legendOf(two + ", legend(order(1 \"has size(big) here\" 2 \"cols(3) too\"))");
    check(lg5.value("size", nlohmann::json()).is_null() && lg5.value("cols", nlohmann::json()).is_null(),
          "BUG-799: labels containing size( / cols( leave legend.size and legend.cols null. Got " +
              lg5.dump());
    auto lg5b = legendOf(two + ", legend(order(1 \"a\") cols(2) size(small))");
    check(lg5b.value("cols", 0) == 2 && lg5b.value("size", std::string()) == "small",
          "BUG-799 control: real cols(2) size(small) suboptions still bind. Got " + lg5b.dump());

    // (4) FU-113: an out-of-range index leaves no blank row (consecutive y values).
    legendOf(two + ", legend(order(1 \"a\" 3 \"b\" 2 \"c\"))");
    {
      const std::string svg = wd + "/range.svg";
      runCmd(session, "graph export \"" + svg + "\", replace");
      std::ifstream in(svg);
      std::vector<double> ys;
      std::string line;
      while (std::getline(in, line)) {
        if (line.find("text-anchor=\"start\"") == std::string::npos) continue;
        auto p = line.find(" y=\"");
        if (p == std::string::npos) continue;
        ys.push_back(std::strtod(line.c_str() + p + 4, nullptr));
      }
      check(ys.size() == 2 && ys[1] - ys[0] == 14.0,
            "BUG-798/FU-113: order(1 \"a\" 3 \"b\" 2 \"c\") on a 2-plot graph draws exactly 2 legend rows "
            "with no gap. Got " + std::to_string(ys.size()) + " rows" +
                (ys.size() == 2 ? ", dy " + std::to_string(ys[1] - ys[0]) : std::string()));
    }

    // cdfplot shares the off-token rule.
    auto lg6 = legendOf("cdfplot ly1, by(lx) legend(order(1 \"Payoff\"))");
    check(!lg6.value("off", true), "BUG-797: cdfplot legend(order(1 \"Payoff\")) does not switch the legend off. Got " + lg6.dump());
    auto lg6b = legendOf("cdfplot ly1, legend(off)");
    check(lg6b.value("off", false), "BUG-797 control: cdfplot legend(off) still switches it off");
  }

  fs::remove_all(base, ec);
}

// --- BETA campaign Phase C batch C1 (silent-wrong sweep: estimation/summary
// adapters + spine defects). Every numeric expectation below is pinned from
// a real StataBE 19.5 oracle capture
// (internal capture c-oracle-stata.log),
// re-run against sysuse fatalities + `gen high = (beertax > .5)`, NOT from
// memory. BS-023 (reghdfe without absorb()) is deliberately NOT covered by
// a leg here: the oracle showed real Stata's own `reghdfe income beertax`
// (no absorb()) SUCCEEDING with numbers identical to plain OLS — the
// opposite of this batch's original "should r(198) error" brief — so
// nothing was changed there (see the batch's final report for the evidence).

void testC1N1CaptureNoisilyAbbrev() {
  std::printf("[selftest] --- C1/N1 capture noisily abbreviation + success/error visibility ---\n");
  namespace fs = std::filesystem;
  std::string workdir = (fs::temp_directory_path() / "piet_native_selftest_c1_n1").u8string();
  std::error_code ec;
  fs::remove_all(workdir, ec);
  fs::create_directories(workdir, ec);

  // (a) `noi` (previously missing from kQuietlyPrefixes) must be recognised
  // as the `noisily` abbreviation, not dispatched as an unknown command
  // (which was swallowing the WHOLE inner command's output, rc=199).
  {
    piet::SessionState session(workdir);
    (void)piet::dispatch("sysuse fatalities, clear", session);
    auto blocks = piet::dispatch("cap noi count", session);
    check(session.eval.locals.get("_rc", "") == "0",
          "C1/N1(a): `cap noi count` recognises `noi` as noisily (not an unknown command) -- "
          "_rc=0, not 199");
    bool sawDisplay = false;
    for (const auto& b : blocks) {
      if (b.is_object() && b.value("type", std::string()) == "display") sawDisplay = true;
    }
    check(sawDisplay, "C1/N1(a)+(b): `cap noi count` (success) shows its result");
  }

  // (b) `cap noi` on an ERRORING inner command shows the error too (not
  // just swallowed) -- noisily-rooted error path.
  {
    piet::SessionState session(workdir);
    (void)piet::dispatch("sysuse fatalities, clear", session);
    auto blocks = piet::dispatch("cap noi summarize nonexistvar_c1n1", session);
    bool sawError = false;
    for (const auto& b : blocks) {
      if (b.is_object() && b.value("type", std::string()) == "error") sawError = true;
    }
    check(sawError, "C1/N1(b): `cap noi <erroring cmd>` shows the error");
  }

  // (b) regression guard: bare `cap` (no noisily) on a SUCCESSFUL command
  // suppresses the result entirely (previously it was always forwarded,
  // regardless of noisily).
  {
    piet::SessionState session(workdir);
    (void)piet::dispatch("sysuse fatalities, clear", session);
    auto blocks = piet::dispatch("cap count", session);
    check(blocks.size() == 1, "C1/N1(b) regression guard: bare `cap count` (success) shows "
          "nothing but its own echo");
  }

  fs::remove_all(workdir, ec);
}

void testC1N3CoarseRcGaps() {
  std::printf("[selftest] --- C1/N3 coarseRc gaps: variable-not-found -> 111, confirm "
              "type-mismatch -> 7 ---\n");
  namespace fs = std::filesystem;
  std::string workdir = (fs::temp_directory_path() / "piet_native_selftest_c1_n3").u8string();
  std::error_code ec;
  fs::remove_all(workdir, ec);
  fs::create_directories(workdir, ec);

  // variable-not-found (summarize) -> r(111), oracle-pinned.
  {
    piet::SessionState session(workdir);
    (void)piet::dispatch("sysuse fatalities, clear", session);
    (void)piet::dispatch("capture summarize nonexistvar_c1n3", session);
    check(session.eval.locals.get("_rc", "") == "111",
          "C1/N3: `capture summarize <missing var>` sets _rc=111 (was falling to the generic "
          "\"1\" default)");
  }

  // confirm variable not found -> r(111) too (same class, different
  // message shape: "variable 'X' not found in dataset").
  {
    piet::SessionState session(workdir);
    (void)piet::dispatch("sysuse fatalities, clear", session);
    (void)piet::dispatch("capture confirm variable nonexistvar_c1n3", session);
    check(session.eval.locals.get("_rc", "") == "111",
          "C1/N3: `capture confirm variable <missing var>` sets _rc=111");
  }

  // confirm string/numeric type mismatch -> r(7), oracle-pinned (`confirm
  // string variable income` on a numeric var -> rc=7).
  {
    piet::SessionState session(workdir);
    (void)piet::dispatch("sysuse fatalities, clear", session);
    (void)piet::dispatch("capture confirm string variable income", session);
    check(session.eval.locals.get("_rc", "") == "7",
          "C1/N3: `capture confirm string variable income` (income is numeric) sets _rc=7");
  }

  // Regression guard: file-not-found (601) is NOT swallowed by the new
  // "variable"+"not found" substring rule.
  {
    piet::SessionState session(workdir);
    (void)piet::dispatch("sysuse fatalities, clear", session);
    (void)piet::dispatch("capture use \"" + workdir + "/does_not_exist_c1n3.dta\"", session);
    check(session.eval.locals.get("_rc", "") == "601",
          "C1/N3 regression guard: file-not-found still maps to _rc=601");
  }

  // testBS100's own case: a cobra "column not found" error (regress on a
  // missing X) is r(111), as in StataBE (w2ak_estout_family.log:219, :227;
  // FU-1079, W2AK) -- it was pinned at the generic _rc=1 before.
  {
    piet::SessionState session(workdir);
    (void)piet::dispatch("sysuse fatalities, clear", session);
    (void)piet::dispatch("capture regress fatal nonexistentvar_c1n3_xyz", session);
    check(session.eval.locals.get("_rc", "") == "111",
          "C1/N3: a cobra \"column not found\" engine error is _rc=111 "
          "(w2ak_estout_family.log:219)");
  }

  fs::remove_all(workdir, ec);
}

void testC1BS022LogisticOddsRatio() {
  std::printf("[selftest] --- C1/BS-022 logistic reports odds ratios, not log-odds ---\n");
  namespace fs = std::filesystem;
  std::string workdir = (fs::temp_directory_path() / "piet_native_selftest_c1_bs022").u8string();
  std::error_code ec;
  fs::remove_all(workdir, ec);
  fs::create_directories(workdir, ec);
  piet::SessionState session(workdir);

  (void)piet::dispatch("sysuse fatalities, clear", session);
  (void)piet::dispatch("gen high = (beertax > .5)", session);
  auto blocks = piet::dispatch("logistic high income", session);

  const nlohmann::ordered_json* est = nullptr;
  for (const auto& b : blocks) {
    if (b.is_object() && b.value("type", std::string()) == "estimation") est = &b;
  }
  check(est != nullptr, "C1/BS-022 setup: `logistic high income` returns an estimation block");
  if (est != nullptr) {
    check(est->value("estimator", std::string()) == "logistic",
          "C1/BS-022: the block's estimator is \"logistic\", not \"logit\" (previously identical "
          "to logit's block)");
    // Oracle (real Stata): income row OR = .9995511; _cons row OR = 195.857.
    bool sawIncomeOr = false, sawConsOr = false;
    if (est->contains("coeftable") && (*est)["coeftable"].is_array()) {
      for (const auto& row : (*est)["coeftable"]) {
        std::string name = row.value("name", std::string());
        if (name == "income" && row.contains("b") && row["b"].is_number()) {
          double b = row["b"].get<double>();
          check(std::abs(b - 0.9995511) < 1e-4,
                "C1/BS-022: income's OR ~= .9995511 (oracle), got " + std::to_string(b));
          sawIncomeOr = true;
        }
        if (name == "(intercept)" && row.contains("b") && row["b"].is_number()) {
          double b = row["b"].get<double>();
          check(std::abs(b - 195.857) < 0.5,
                "C1/BS-022: _cons's OR ~= 195.857 (oracle), got " + std::to_string(b));
          sawConsOr = true;
        }
      }
    }
    check(sawIncomeOr, "C1/BS-022: coeftable has an income row with a numeric OR");
    check(sawConsOr, "C1/BS-022: coeftable has an intercept row with a numeric OR");
  }

  // Regression guard: `logit` itself is untouched (log-odds, not OR).
  auto blocksLogit = piet::dispatch("logit high income", session);
  const nlohmann::ordered_json* estLogit = nullptr;
  for (const auto& b : blocksLogit) {
    if (b.is_object() && b.value("type", std::string()) == "estimation") estLogit = &b;
  }
  check(estLogit != nullptr && estLogit->value("estimator", std::string()) == "logit",
        "C1/BS-022 regression guard: `logit` still reports estimator \"logit\" (log-odds)");
  if (estLogit != nullptr && estLogit->contains("coeftable") && (*estLogit)["coeftable"].is_array()) {
    for (const auto& row : (*estLogit)["coeftable"]) {
      if (row.value("name", std::string()) == "income" && row.contains("b") && row["b"].is_number()) {
        check(row["b"].get<double>() < 0,
              "C1/BS-022 regression guard: `logit`'s income b is still the (negative) log-odds "
              "coefficient, not exponentiated");
        check(row.contains("p") && row["p"].is_number(),
              "C1/BS-022: logit coeftable p is backfilled (not left null)");
        check(row.contains("ci_lo") && row["ci_lo"].is_number(),
              "C1/BS-022: logit coeftable ci_lo is backfilled (not left null)");
        check(row.contains("ci_hi") && row["ci_hi"].is_number(),
              "C1/BS-022: logit coeftable ci_hi is backfilled (not left null)");
      }
    }
  }

  // Complete separation is an honest Stata-parity reject, while the
  // income-based control above remains a normal estimation table.
  auto separated = piet::dispatch("capture noisily logit high beertax", session);
  bool sawPerfectReject = false;
  for (const auto& b : separated) {
    if (b.is_object() && b.value("type", std::string()) == "error" &&
        b.value("message", std::string()).find("predicts data perfectly") != std::string::npos) {
      sawPerfectReject = true;
    }
  }
  check(sawPerfectReject,
        "F2: separated logit returns a visible captured error block naming perfect prediction");
  check(session.eval.locals.get("_rc", "") == "2000",
        "F2: capture maps the perfect-prediction reject to Stata rc 2000");

  fs::remove_all(workdir, ec);
}

void testC1BS024HettestVarlist() {
  std::printf("[selftest] --- C1/BS-024 estat hettest explicit varlist = auxiliary test "
              "regressors ---\n");
  namespace fs = std::filesystem;
  std::string workdir = (fs::temp_directory_path() / "piet_native_selftest_c1_bs024").u8string();
  std::error_code ec;
  fs::remove_all(workdir, ec);
  fs::create_directories(workdir, ec);
  piet::SessionState session(workdir);

  (void)piet::dispatch("sysuse fatalities, clear", session);
  (void)piet::dispatch("gen high = (beertax > .5)", session);
  (void)piet::dispatch("regress income beertax", session);
  auto blocks = piet::dispatch("estat hettest spirits unemp", session);

  const nlohmann::ordered_json* est = nullptr;
  for (const auto& b : blocks) {
    if (b.is_object() && b.value("type", std::string()) == "estimation") est = &b;
  }
  check(est != nullptr, "C1/BS-024 setup: `estat hettest spirits unemp` returns an estimation "
        "block");
  if (est != nullptr) {
    // Oracle (real Stata): chi2(2) = 14.82 for `estat hettest spirits
    // unemp` after `regress income beertax`. Previously this arm silently
    // dropped "spirits" (misread as a replacement y for the base
    // regression) and only tested against "unemp" alone -- df=1,
    // chi2~=5.97, a completely different, silently-wrong number.
    check(est->contains("df"), "C1/BS-024: the block has a df field");
    if (est->contains("df")) {
      double df = (*est)["df"].get<double>();
      check(std::abs(df - 2.0) < 0.01,
            "C1/BS-024: df==2 (both spirits AND unemp used as auxiliary regressors), got " +
                std::to_string(df));
    }
    check(est->contains("chi2") && (*est)["chi2"].is_number(), "C1/BS-024: the block has a "
          "numeric chi2");
    if (est->contains("chi2") && (*est)["chi2"].is_number()) {
      double chi2 = (*est)["chi2"].get<double>();
      check(std::abs(chi2 - 14.82) < 0.1,
            "C1/BS-024: chi2 ~= 14.82 (oracle), got " + std::to_string(chi2));
    }
  }

  // Regression guard: the lastModel FALLBACK path (no explicit varlist)
  // still uses lastModel's y/x exactly as before (untouched by this fix).
  auto blocksPlain = piet::dispatch("estat hettest", session);
  bool sawPlainError = false;
  for (const auto& b : blocksPlain) {
    if (b.is_object() && b.value("type", std::string()) == "error") sawPlainError = true;
  }
  check(!sawPlainError, "C1/BS-024 regression guard: `estat hettest` (no varlist, fallback to "
        "lastModel) still succeeds");

  fs::remove_all(workdir, ec);
}

void testC1BS025CodebookIfWiring() {
  std::printf("[selftest] --- C1/BS-025 codebook: honors `if`, carries codebook payload ---\n");
  namespace fs = std::filesystem;
  std::string workdir = (fs::temp_directory_path() / "piet_native_selftest_c1_bs025").u8string();
  std::error_code ec;
  fs::remove_all(workdir, ec);
  fs::create_directories(workdir, ec);
  piet::SessionState session(workdir);

  (void)piet::dispatch("sysuse fatalities, clear", session);
  (void)piet::dispatch("gen high = (beertax > .5)", session);

  auto blocksPlain = piet::dispatch("codebook income", session);
  const nlohmann::ordered_json* describePlain = nullptr;
  for (const auto& b : blocksPlain) {
    if (b.is_object() && b.value("type", std::string()) == "describe") describePlain = &b;
  }
  check(describePlain != nullptr && describePlain->contains("variables") &&
            (*describePlain)["variables"].is_array() && !(*describePlain)["variables"].empty(),
        "C1/BS-025 setup: `codebook income` returns a describe-shaped block with one variable");
  if (describePlain != nullptr && !(*describePlain)["variables"].empty()) {
    const auto& v = (*describePlain)["variables"][0];
    // Oracle (real Stata, unfiltered): mean=13880.2, p90=16915.3,
    // n_unique=333.
    check(v.contains("mean") && v["mean"].is_number() &&
              std::abs(v["mean"].get<double>() - 13880.2) < 1.0,
          "C1/BS-025: unfiltered codebook income mean ~= 13880.2 (oracle)");
    check(v.contains("p90") && v["p90"].is_number() &&
              std::abs(v["p90"].get<double>() - 16915.3) < 1.0,
          "C1/BS-025: unfiltered codebook income p90 ~= 16915.3 (oracle) -- previously codebook "
          "carried no percentile fields at all");
    check(v.value("n_unique", -1) == 333, "C1/BS-025: unfiltered n_unique == 333 (oracle)");
  }

  // `if` must actually filter -- the pre-fix arm was a bare `describe`
  // alias that dropped `if` entirely.
  auto blocksIf = piet::dispatch("codebook income if year==1982", session);
  const nlohmann::ordered_json* describeIf = nullptr;
  for (const auto& b : blocksIf) {
    if (b.is_object() && b.value("type", std::string()) == "describe") describeIf = &b;
  }
  check(describeIf != nullptr && describeIf->contains("variables") &&
            (*describeIf)["variables"].is_array() && !(*describeIf)["variables"].empty(),
        "C1/BS-025: `codebook income if year==1982` returns a describe-shaped block");
  if (describeIf != nullptr && !(*describeIf)["variables"].empty()) {
    const auto& v = (*describeIf)["variables"][0];
    // Oracle (real Stata, year==1982): mean=12998.3, n_unique=46, 48 obs.
    check(v.contains("mean") && v["mean"].is_number() &&
              std::abs(v["mean"].get<double>() - 12998.3) < 1.0,
          "C1/BS-025: `if year==1982`-filtered codebook income mean ~= 12998.3 (oracle) -- "
          "differs from the unfiltered 13880.2 above, proving `if` actually filtered");
    check(v.value("n_unique", -1) == 46,
          "C1/BS-025: `if year==1982`-filtered n_unique == 46 (oracle)");
    check(v.value("n_obs", -1) == 48,
          "C1/BS-025: `if year==1982`-filtered n_obs == 48 (oracle: 48 rows in 1982)");
  }

  fs::remove_all(workdir, ec);
}

void testC1BS026TabstatAdapter() {
  std::printf("[selftest] --- C1/BS-026 tabstat adapter forwards stats/total/vars ---\n");
  namespace fs = std::filesystem;
  std::string workdir = (fs::temp_directory_path() / "piet_native_selftest_c1_bs026").u8string();
  std::error_code ec;
  fs::remove_all(workdir, ec);
  fs::create_directories(workdir, ec);
  piet::SessionState session(workdir);

  (void)piet::dispatch("sysuse fatalities, clear", session);
  (void)piet::dispatch("gen high = (beertax > .5)", session);
  auto blocks = piet::dispatch("tabstat income beertax, stats(mean sd n)", session);

  const nlohmann::ordered_json* est = nullptr;
  for (const auto& b : blocks) {
    if (b.is_object() && b.value("type", std::string()) == "estimation") est = &b;
  }
  check(est != nullptr && est->value("estimator", std::string()) == "tabstat",
        "C1/BS-026 setup: `tabstat income beertax, stats(mean sd n)` returns a tabstat block");
  if (est != nullptr) {
    check(est->contains("total") && (*est)["total"].is_object() && !(*est)["total"].empty(),
          "C1/BS-026: the block carries \"total\" (previously an empty shell -- only "
          "estimator/n_obs/by were forwarded)");
    check(est->contains("vars") && (*est)["vars"].is_array(),
          "C1/BS-026: the block carries \"vars\" (the ordered var list)");
    check(est->contains("stats") && (*est)["stats"].is_array(),
          "C1/BS-026: the block carries \"stats\" (the requested stat-name list)");
    if (est->contains("total") && (*est)["total"].contains("income")) {
      // Oracle (real Stata): Mean income=13880.18, SD=2253.046.
      const auto& incomeStats = (*est)["total"]["income"];
      check(incomeStats.contains("mean") &&
                std::abs(incomeStats["mean"].get<double>() - 13880.18) < 0.5,
            "C1/BS-026: total.income.mean ~= 13880.18 (oracle)");
      check(incomeStats.contains("sd") &&
                std::abs(incomeStats["sd"].get<double>() - 2253.046) < 0.5,
            "C1/BS-026: total.income.sd ~= 2253.046 (oracle)");
    }
  }

  fs::remove_all(workdir, ec);
}

void testC1BS027TabulateTwowaySummarize() {
  std::printf("[selftest] --- C1/BS-027 tabulate v1 v2, summarize(v3) two-way form ---\n");
  namespace fs = std::filesystem;
  std::string workdir = (fs::temp_directory_path() / "piet_native_selftest_c1_bs027").u8string();
  std::error_code ec;
  fs::remove_all(workdir, ec);
  fs::create_directories(workdir, ec);
  piet::SessionState session(workdir);

  (void)piet::dispatch("sysuse fatalities, clear", session);
  (void)piet::dispatch("gen high = (beertax > .5)", session);
  auto blocks = piet::dispatch("tabulate year high, summarize(income)", session);

  const nlohmann::ordered_json* tab = nullptr;
  for (const auto& b : blocks) {
    if (b.is_object() && b.value("type", std::string()) == "tabulate") tab = &b;
  }
  check(tab != nullptr && tab->value("mode", std::string()) == "summarize_twoway",
        "C1/BS-027 setup: `tabulate year high, summarize(income)` returns a two-way summarize "
        "block (previously silently dropped `high` and returned a one-way table)");

  // Row/col labels come from tabulate.cpp's own pyFloatStr-based labelFor()
  // (Python str(float) convention) -- found by PREFIX rather than hardcoded
  // exactly, so this leg doesn't depend on that unrelated formatting detail.
  std::string rowLabel, col0Label, col1Label;
  if (tab != nullptr) {
    if (tab->contains("rows") && (*tab)["rows"].is_array()) {
      for (const auto& r : (*tab)["rows"]) {
        std::string s = r.get<std::string>();
        if (s.rfind("1982", 0) == 0) rowLabel = s;
      }
    }
    if (tab->contains("cols") && (*tab)["cols"].is_array()) {
      for (const auto& c : (*tab)["cols"]) {
        std::string s = c.get<std::string>();
        if (s.rfind("0", 0) == 0) col0Label = s;
        if (s.rfind("1", 0) == 0) col1Label = s;
      }
    }
  }
  check(!rowLabel.empty() && !col0Label.empty() && !col1Label.empty(),
        "C1/BS-027 setup: the two-way table has a 1982 row and 0/1 (high) columns");

  if (tab != nullptr && !rowLabel.empty() && tab->contains("cells") &&
      (*tab)["cells"].contains(rowLabel)) {
    const auto& row1982 = (*tab)["cells"][rowLabel];
    // Oracle (real Stata) + independently re-derived from the raw CSV
    // (sample stdev, n-1 denominator): 1982/high=0: mean=13502.351, N=34;
    // 1982/high=1: mean=11774.037, N=14.
    if (!col0Label.empty() && row1982.contains(col0Label)) {
      const auto& c0 = row1982[col0Label];
      check(c0.contains("mean") && std::abs(c0["mean"].get<double>() - 13502.351) < 0.5,
            "C1/BS-027: cells[1982][high=0].mean ~= 13502.351 (oracle)");
      check(c0.contains("N") && c0["N"].get<int64_t>() == 34,
            "C1/BS-027: cells[1982][high=0].N == 34 (oracle)");
    }
    if (!col1Label.empty() && row1982.contains(col1Label)) {
      const auto& c1 = row1982[col1Label];
      check(c1.contains("mean") && std::abs(c1["mean"].get<double>() - 11774.037) < 0.5,
            "C1/BS-027: cells[1982][high=1].mean ~= 11774.037 (oracle)");
      check(c1.contains("N") && c1["N"].get<int64_t>() == 14,
            "C1/BS-027: cells[1982][high=1].N == 14 (oracle)");
    }
  }
  if (tab != nullptr && tab->contains("grand")) {
    check((*tab)["grand"].contains("mean") &&
              std::abs((*tab)["grand"]["mean"].get<double>() - 13880.185) < 0.5,
          "C1/BS-027: grand.mean ~= 13880.185 (oracle)");
    check((*tab)["grand"].contains("N") && (*tab)["grand"]["N"].get<int64_t>() == 336,
          "C1/BS-027: grand.N == 336 (oracle)");
  }

  // Regression guard: one-way form (single grouping var) is untouched.
  auto blocksOneway = piet::dispatch("tabulate year, summarize(income)", session);
  const nlohmann::ordered_json* tabOneway = nullptr;
  for (const auto& b : blocksOneway) {
    if (b.is_object() && b.value("type", std::string()) == "tabulate") tabOneway = &b;
  }
  check(tabOneway != nullptr && tabOneway->value("mode", std::string()) == "summarize",
        "C1/BS-027 regression guard: one-way `tabulate year, summarize(income)` still uses mode "
        "\"summarize\" (byte-identical old path), not the new two-way mode");

  fs::remove_all(workdir, ec);
}

void testC1BS028PwcorrObs() {
  std::printf("[selftest] --- C1/BS-028 correlate/pwcorr `, obs` no longer mismapped to `sig` "
              "---\n");
  namespace fs = std::filesystem;
  std::string workdir = (fs::temp_directory_path() / "piet_native_selftest_c1_bs028").u8string();
  std::error_code ec;
  fs::remove_all(workdir, ec);
  fs::create_directories(workdir, ec);
  piet::SessionState session(workdir);

  (void)piet::dispatch("sysuse fatalities, clear", session);
  (void)piet::dispatch("gen high = (beertax > .5)", session);

  // `correlate, obs` (non-pairwise): real Stata rejects this outright
  // (oracle: "option obs not allowed", rc=198) -- previously it was
  // mismapped into `sig`, which then hard-errored cobra's OWN "corr --sig
  // requires --pairwise" instead.
  auto blocksCorr = piet::dispatch("correlate income beertax, obs", session);
  bool sawCorrError = false;
  std::string corrErrMsg;
  for (const auto& b : blocksCorr) {
    if (b.is_object() && b.value("type", std::string()) == "error") {
      sawCorrError = true;
      corrErrMsg = b.value("message", std::string());
    }
  }
  check(sawCorrError, "C1/BS-028: `correlate income beertax, obs` is an honest reject");
  check(corrErrMsg.find("obs") != std::string::npos,
        "C1/BS-028: the reject message names `obs` as the disallowed option, got: " + corrErrMsg);

  (void)piet::dispatch("capture correlate income beertax, obs", session);
  check(session.eval.locals.get("_rc", "") == "198",
        "C1/BS-028: `capture correlate ..., obs` sets _rc=198 (oracle-pinned)");

  // `pwcorr, obs`: succeeds, and the block no longer force-carries `sig`
  // (previously `obs` silently became `sig`, showing p-values the user
  // never asked for).
  auto blocksPw = piet::dispatch("pwcorr income beertax, obs", session);
  const nlohmann::ordered_json* corrBlock = nullptr;
  for (const auto& b : blocksPw) {
    if (b.is_object() && b.value("type", std::string()) == "estimation") corrBlock = &b;
  }
  check(corrBlock != nullptr, "C1/BS-028: `pwcorr income beertax, obs` succeeds (estimation "
        "block)");
  if (corrBlock != nullptr) {
    check(corrBlock->value("sig", true) == false,
          "C1/BS-028: `pwcorr ..., obs` no longer force-sets sig=true (obs != sig)");
    check(corrBlock->contains("nobs") && (*corrBlock)["nobs"].is_array(),
          "C1/BS-028: the block carries the per-pair `nobs` matrix (cobra forwards it under "
          "--pairwise regardless of --sig -- the data layer is correct even though the frontend "
          "has no per-cell N renderer yet)");
  }

  fs::remove_all(workdir, ec);
}

void testC1BS029LevelsofSeparateMissing() {
  std::printf("[selftest] --- C1/BS-029 levelsof separate()/missing + r(levels) wiring ---\n");
  namespace fs = std::filesystem;
  std::string workdir = (fs::temp_directory_path() / "piet_native_selftest_c1_bs029").u8string();
  std::error_code ec;
  fs::remove_all(workdir, ec);
  fs::create_directories(workdir, ec);
  piet::SessionState session(workdir);

  (void)piet::dispatch("sysuse fatalities, clear", session);
  (void)piet::dispatch("gen r7 = year", session);
  // Inject the missing marker into the first 49 observations via the `in`
  // range qualifier. (Was `if rownames<50`, but P8-A17 stripped the demo
  // CSV's leading `rownames` column — an R-export row-index artifact, not
  // real data — so this now uses the Stata-idiomatic observation range,
  // which is oracle-identical: 49 rows span <7 states so every 1982-1988
  // level survives elsewhere and only the missing "." is newly introduced.)
  (void)piet::dispatch("replace r7 = . in 1/49", session);

  // separate(SEP): joins levels with SEP instead of the default space.
  // Oracle: r(levels)=[1982|1983|1984|1985|1986|1987|1988].
  auto blocksSep = piet::dispatch("levelsof r7, separate(|)", session);
  bool sawSepError = false;
  for (const auto& b : blocksSep) {
    if (b.is_object() && b.value("type", std::string()) == "error") sawSepError = true;
  }
  check(!sawSepError, "C1/BS-029: `levelsof r7, separate(|)` is no longer an honest-reject on "
        "`separate`");
  check(session.eval.rStrings.get("levels", "") == "1982|1983|1984|1985|1986|1987|1988",
        "C1/BS-029: r(levels) == \"1982|1983|1984|1985|1986|1987|1988\" (oracle-pinned, "
        "pipe-separated, missing excluded) -- r(levels) was never wired up at all before this fix");

  // missing: appends the dataset's own missing marker "." after the
  // ordinary levels (Stata sorts missing last). Oracle:
  // r(levels)=[1982 1983 1984 1985 1986 1987 1988 .].
  auto blocksMiss = piet::dispatch("levelsof r7, missing", session);
  bool sawMissError = false;
  for (const auto& b : blocksMiss) {
    if (b.is_object() && b.value("type", std::string()) == "error") sawMissError = true;
  }
  check(!sawMissError, "C1/BS-029: `levelsof r7, missing` is no longer an honest-reject on "
        "`missing`");
  check(session.eval.rStrings.get("levels", "") == "1982 1983 1984 1985 1986 1987 1988 .",
        "C1/BS-029: r(levels) == \"1982 1983 1984 1985 1986 1987 1988 .\" (oracle-pinned, "
        "space-separated, missing appended LAST)");

  fs::remove_all(workdir, ec);
}

// ---------------------------------------------------------------------------
// BETA campaign Phase C batch C2 (data-verb integrity): BS-030 tsset/xtset
// delta(), BS-031 silent-if/in-drop sweep, BS-032 egen group()/tag()+by
// reject, corr `obs` field composing with C1/BS-028.

void testC2BS030TssetDelta() {
  std::printf("[selftest] --- C2/BS-030 tsset delta() forward + honest reject ---\n");
  namespace fs = std::filesystem;
  std::string workdir = (fs::temp_directory_path() / "piet_native_selftest_c2_bs030").u8string();
  std::error_code ec;
  fs::remove_all(workdir, ec);
  fs::create_directories(workdir, ec);
  piet::SessionState session(workdir);

  (void)piet::dispatch("sysuse fatalities, clear", session);
  (void)piet::dispatch("gen high = (beertax > .5)", session);

  // Reject case (live-verified against StataBE this stint — the shipped
  // oracle log's own BS-030 stanza covers exactly this scenario): t=_n has
  // a minimum gap of 1; declaring delta(2) is narrower than the data
  // actually supports -> real Stata errors "time values with period less
  // than delta() found" and the ts context is left UNSET.
  (void)piet::dispatch("gen t=_n", session);
  auto blocksReject = piet::dispatch("tsset t, delta(2)", session);
  bool sawRejectError = false;
  std::string rejectMsg;
  for (const auto& b : blocksReject) {
    if (b.is_object() && b.value("type", std::string()) == "error") {
      sawRejectError = true;
      rejectMsg = b.value("message", std::string());
    }
  }
  check(sawRejectError, "C2/BS-030: `tsset t, delta(2)` on gap-1 data is an honest reject");
  check(rejectMsg.find("time values with period less than delta") != std::string::npos,
        "C2/BS-030: reject message matches the oracle text, got: " + rejectMsg);
  check(!session.timevar.has_value(),
        "C2/BS-030: the ts context stays UNSET after the rejected tsset (matches the oracle's "
        "subsequent `gen lag1=L.income` -> \"time variable not set\")");

  // B4-W3b SUPERSEDES BS-030's reject here. The period options were rejected
  // because nothing on this side represented them; they are now implemented,
  // and Stata's own answer is rc 0 with the format landing on r(tsfmt) AND on
  // the column (pins_oracle_g.log:257-273, `tsset t, quarterly` ->
  // r(tsfmt) "%tq" + `describe t` %tq). Keeping the old assertion would be
  // pinning a divergence: this leg now asserts what StataBE does, on the same
  // spelling the old one used.
  auto blocksUnitopt = piet::dispatch("tsset t, daily", session);
  bool sawUnitoptError = false;
  for (const auto& b : blocksUnitopt) {
    if (b.is_object() && b.value("type", std::string()) == "error") sawUnitoptError = true;
  }
  check(!sawUnitoptError,
        "C2/BS-030 -> B4-W3b: `tsset t, daily` is now rc 0 (Stata's own answer), not the "
        "unitoption reject BS-030 shipped");
  {
    const std::string* dailyFmt = session.eval.rStrings.find("tsfmt");
    check(dailyFmt != nullptr && *dailyFmt == "%td",
          "C2/BS-030 -> B4-W3b: ...and `daily` names %td in r(tsfmt) — an accepted-and-ignored "
          "period would be rc 0 with the %tg default still standing");
  }
  // Restore the state the legs below expect: they re-tsset t2 anyway, but the
  // format the line above put on `t` must not travel into them as a surprise.
  (void)piet::dispatch("tsset t", session);

  // Success + forward case (live-verified against StataBE this stint): t2
  // is spaced by EXACTLY delta(2), so tsset succeeds, and delta must reach
  // the engine for L. to resolve at all. Before this fix, delta was
  // silently dropped -> the engine defaulted to delta=1 -> `regress income
  // L.spirits` errored "[no_obs] not enough observations: n <= k" (no row's
  // t2-1 matched another row's t2, since all t2 values are even).
  (void)piet::dispatch("gen t2=_n*2", session);
  auto blocksOk = piet::dispatch("tsset t2, delta(2)", session);
  bool sawOkError = false;
  for (const auto& b : blocksOk) {
    if (b.is_object() && b.value("type", std::string()) == "error") sawOkError = true;
  }
  check(!sawOkError, "C2/BS-030: `tsset t2, delta(2)` on gap-2 data succeeds");

  auto blocksEst = piet::dispatch("regress income L.spirits", session);
  const nlohmann::ordered_json* est = nullptr;
  for (const auto& b : blocksEst) {
    if (b.is_object() && b.value("type", std::string()) == "estimation") est = &b;
  }
  check(est != nullptr,
        "C2/BS-030: `regress income L.spirits` under delta(2) succeeds -- delta reached the "
        "engine via --tsdelta (previously errored \"not enough observations\")");
  if (est != nullptr) {
    double nObs = est->value("n_obs", 0.0);
    check(std::abs(nObs - 335.0) < 0.5,
          "C2/BS-030: n_obs == 335 (one row lost to the lag, oracle-pinned), got " +
              std::to_string(nObs));
  }

  fs::remove_all(workdir, ec);
}

void testXtsetPhysicalSortAndN() {
  std::printf("[selftest] --- xtset physically sorts panel/time before downstream _n ---\n");
  namespace fs = std::filesystem;
  std::string workdir =
      (fs::temp_directory_path() / "piet_native_selftest_xtset_sort").u8string();
  std::error_code ec;
  fs::remove_all(workdir, ec);
  fs::create_directories(workdir, ec);
  piet::SessionState session(workdir);

  (void)piet::dispatch("set obs 4", session);
  (void)piet::dispatch("gen panel=(_n==1)+(_n==3)+1", session);  // 2,1,2,1
  (void)piet::dispatch("gen time=(_n<=2)+1", session);           // 2,2,1,1
  (void)piet::dispatch("gen before=_n", session);

  auto xtset = piet::dispatch("xtset panel time", session);
  bool sawError = false;
  bool sawMutation = false;
  for (const auto& b : xtset) {
    if (!b.is_object()) continue;
    sawError = sawError || b.value("type", std::string()) == "error";
    sawMutation = sawMutation || b.value("type", std::string()) == "data_mutation";
  }
  check(!sawError, "xtset sort: unsorted unique panel/time data succeeds");
  check(!sawMutation,
        "xtset sort: physical reorder preserves xtset's established echo-only output blocks");

  (void)piet::dispatch("gen after=_n", session);
  piet::Datastore* ds = session.datastore();
  check(ds != nullptr && ds->has("panel") && ds->has("time") && ds->has("before") &&
            ds->has("after"),
        "xtset sort: sorted fixture columns remain available");
  if (ds != nullptr && ds->has("panel") && ds->has("time") && ds->has("before") &&
      ds->has("after")) {
    const double* panel = ds->col("panel").f64();
    const double* time = ds->col("time").f64();
    const double* before = ds->col("before").f64();
    const double* after = ds->col("after").f64();
    check(panel[0] == 1.0 && panel[1] == 1.0 && panel[2] == 2.0 && panel[3] == 2.0 &&
              time[0] == 1.0 && time[1] == 2.0 && time[2] == 1.0 && time[3] == 2.0,
          "xtset sort: live rows are physically ordered by panel then time");
    check(before[0] == 4.0 && before[1] == 2.0 && before[2] == 3.0 && before[3] == 1.0,
          "xtset sort: pre-sort row identity follows the physical reorder (4,2,3,1)");
    check(after[0] == 1.0 && after[1] == 2.0 && after[2] == 3.0 && after[3] == 4.0,
          "xtset sort: downstream `gen after=_n` uses the sorted row order");
  }

  fs::remove_all(workdir, ec);
}

void testC2BS031SilentIfDropSweep() {
  std::printf("[selftest] --- C2/BS-031 silent-if/in-drop sweep (duplicates tag/list, recode, "
              "clonevar, string gen/replace `in`) ---\n");
  namespace fs = std::filesystem;
  std::string workdir = (fs::temp_directory_path() / "piet_native_selftest_c2_bs031").u8string();
  std::error_code ec;
  fs::remove_all(workdir, ec);
  fs::create_directories(workdir, ec);
  piet::SessionState session(workdir);

  auto freshData = [&]() {
    (void)piet::dispatch("sysuse fatalities, clear", session);
    (void)piet::dispatch("gen high = (beertax > .5)", session);
  };

  // (a) duplicates tag ... if ..., gen() -- oracle (live-verified this
  // stint, StataBE): N=48 (if-sample size), mean=min=max=47 (every one of
  // the 48 in-sample rows shares year==1982 with the other 47), the other
  // 288 out-of-sample rows are MISSING (dataset row count unchanged: 336).
  freshData();
  {
    auto tagBlocks = piet::dispatch("duplicates tag year if year==1982, gen(dtag)", session);
    const nlohmann::ordered_json* mut = nullptr;
    for (const auto& b : tagBlocks) {
      if (b.is_object() && b.value("type", std::string()) == "data_mutation") mut = &b;
    }
    check(mut != nullptr && mut->value("n_rows_after", -1) == 336,
          "C2/BS-031(a): `duplicates tag ... if ..., gen(dtag)` keeps all 336 rows (missing "
          "outside the sample, not dropped)");
    auto sumBlocks = piet::dispatch("summarize dtag", session);
    const nlohmann::ordered_json* sumBlock = nullptr;
    for (const auto& b : sumBlocks) {
      if (b.is_object() && b.value("type", std::string()) == "summarize") sumBlock = &b;
    }
    check(sumBlock != nullptr && sumBlock->contains("stats") &&
              (*sumBlock)["stats"].contains("dtag"),
          "C2/BS-031(a): `summarize dtag` returns dtag stats");
    if (sumBlock != nullptr && sumBlock->contains("stats") && (*sumBlock)["stats"].contains("dtag")) {
      const auto& st = (*sumBlock)["stats"]["dtag"];
      check(st.value("N", -1.0) == 48.0,
            "C2/BS-031(a): dtag N==48 (if-sample size, oracle-pinned), got " +
                std::to_string(st.value("N", -1.0)));
      check(std::abs(st.value("mean", -1.0) - 47.0) < 1e-9,
            "C2/BS-031(a): dtag mean==47 (oracle-pinned)");
      check(std::abs(st.value("min", -1.0) - 47.0) < 1e-9 &&
                std::abs(st.value("max", -1.0) - 47.0) < 1e-9,
            "C2/BS-031(a): dtag min==max==47 (every in-sample row has the same 48-member group)");
    }
  }

  // (a-cont) duplicates list ... if ... -- live-verified this stint: within
  // the year==1982 subset, `state` has no duplicates (0), `year` is all
  // duplicates (all 48 share the value).
  freshData();
  {
    auto listNoneBlocks = piet::dispatch("duplicates list state if year==1982", session);
    bool sawNoDup = false;
    for (const auto& b : listNoneBlocks) {
      if (b.is_object() && b.value("type", std::string()) == "display" &&
          b.value("text", std::string()) == "No duplicates found.") {
        sawNoDup = true;
      }
    }
    check(sawNoDup,
          "C2/BS-031(a): `duplicates list state if year==1982` correctly reports 0 duplicates "
          "(each state appears once per year within the if-sample) -- previously ran unfiltered");

    auto listSomeBlocks = piet::dispatch("duplicates list year if year==1982", session);
    bool sawFortyEight = false;
    for (const auto& b : listSomeBlocks) {
      if (b.is_object() && b.value("note", std::string()) == "48 duplicate observations") {
        sawFortyEight = true;
      }
    }
    check(sawFortyEight,
          "C2/BS-031(a): `duplicates list year if year==1982` lists exactly the 48 in-sample "
          "rows (oracle-pinned), not all 336");
  }

  // (b) recode ... if ..., gen() -- oracle (live-verified this stint,
  // StataBE): `recode year (1982/1984=1) if high==0, gen(rec1)` ->
  // rec1==1 for 98 rows, 1985/1986/1987/1988 unchanged at 33 rows each,
  // Total (non-missing) 230; the 106 if-excluded (high==1) rows are
  // MISSING.
  freshData();
  {
    (void)piet::dispatch("recode year (1982/1984=1) if high==0, gen(rec1)", session);
    auto tabBlocks = piet::dispatch("tabulate rec1", session);
    const nlohmann::ordered_json* tab = nullptr;
    for (const auto& b : tabBlocks) {
      if (b.is_object() && b.value("type", std::string()) == "tabulate") tab = &b;
    }
    check(tab != nullptr, "C2/BS-031(b): `tabulate rec1` returns a tabulate block");
    if (tab != nullptr && tab->contains("table")) {
      const auto& table = (*tab)["table"];
      check(table.contains("values") && table["values"].value("1.0", -1) == 98,
            "C2/BS-031(b): rec1==1 has 98 rows (oracle-pinned), got " +
                std::to_string(table["values"].value("1.0", -1)));
      check(table["values"].value("1985.0", -1) == 33 && table["values"].value("1986.0", -1) == 33 &&
                table["values"].value("1987.0", -1) == 33 && table["values"].value("1988.0", -1) == 33,
            "C2/BS-031(b): rec1's unmapped year categories (1985-1988) each keep 33 rows "
            "(oracle-pinned)");
      check(table.contains("margins") && table["margins"].value("total", -1) == 230,
            "C2/BS-031(b): rec1 non-missing total == 230 (336 - 106 if-excluded), got " +
                std::to_string(table["margins"].value("total", -1)));
    }
  }
  // `recode ... if ...` WITHOUT gen() recodes in place inside the sample and
  // leaves every other row as it was ([D] recode, option generate(): values
  // outside the if or in range are not modified). It was refused until
  // data-verbs-effects-rename-recode-label; the guard this replaces asserted
  // that refusal. Not a silent full-dataset
  // recode: the 98 in-sample rows of (b) become 1, the high==1 rows keep their
  // years.
  freshData();
  {
    auto noGenBlocks = piet::dispatch("recode year (1982/1984=1) if high==0", session);
    bool sawNoGenError = false;
    for (const auto& b : noGenBlocks) {
      if (b.is_object() && b.value("type", std::string()) == "error") sawNoGenError = true;
    }
    auto countN = [&](const std::string& cond) {
      (void)piet::dispatch("quietly count if " + cond, session);
      const double* n = session.eval.rValues.find("N");
      return n == nullptr ? -1.0 : *n;
    };
    const double nOne = countN("year==1");
    const double nKept = countN("inrange(year, 1982, 1984)");
    check(!sawNoGenError && nOne == 98.0,
          "C2/BS-031(b): in-place `recode ... if ...` maps the 98 in-sample rows (as gen() does)");
    check(nKept > 0.0,
          "C2/BS-031(b): in-place `recode ... if ...` leaves the out-of-sample rows unchanged");
  }

  // (c) clonevar ... if ... -- oracle (live-verified this stint, StataBE):
  // `clonevar inc2 = income if year==1982` -> 48 non-missing (matching the
  // if-sample), mean matches BS-025's own independently oracle-pinned
  // year==1982 income mean (12998.3) -- clonevar is gen-class, so the other
  // 288 rows are MISSING, not dropped (n_rows_after stays 336).
  freshData();
  {
    auto cloneBlocks = piet::dispatch("clonevar inc2 = income if year==1982", session);
    const nlohmann::ordered_json* mut = nullptr;
    for (const auto& b : cloneBlocks) {
      if (b.is_object() && b.value("type", std::string()) == "data_mutation") mut = &b;
    }
    check(mut != nullptr && mut->value("n_rows_after", -1) == 336,
          "C2/BS-031(c): `clonevar inc2 = income if year==1982` keeps all 336 rows");
    auto sumBlocks = piet::dispatch("summarize inc2", session);
    const nlohmann::ordered_json* sumBlock = nullptr;
    for (const auto& b : sumBlocks) {
      if (b.is_object() && b.value("type", std::string()) == "summarize") sumBlock = &b;
    }
    if (sumBlock != nullptr && sumBlock->contains("stats") && (*sumBlock)["stats"].contains("inc2")) {
      const auto& st = (*sumBlock)["stats"]["inc2"];
      check(st.value("N", -1.0) == 48.0,
            "C2/BS-031(c): inc2 N==48 (oracle-pinned, if-sample size), got " +
                std::to_string(st.value("N", -1.0)));
      check(std::abs(st.value("mean", -1.0) - 12998.3) < 1.0,
            "C2/BS-031(c): inc2 mean ~= 12998.3 (oracle-pinned, matches BS-025's independently "
            "verified year==1982 income mean)");
    } else {
      check(false, "C2/BS-031(c): `summarize inc2` returns inc2 stats");
    }
  }

  // (d) string `gen ... in a/b` -- oracle (live-verified this stint,
  // StataBE): `gen str8 sv = "x" in 1/10` -> 10 rows == "x", 326 rows == ""
  // (Stata string-missing).
  freshData();
  {
    (void)piet::dispatch("gen str8 sv = \"x\" in 1/10", session);
    (void)piet::dispatch("count if sv==\"x\"", session);
    const double* nX = session.eval.rValues.find("N");
    check(nX != nullptr && *nX == 10.0,
          "C2/BS-031(d): `count if sv==\"x\"` == 10 (oracle-pinned in-range count)");
    (void)piet::dispatch("count if sv==\"\"", session);
    const double* nEmpty = session.eval.rValues.find("N");
    check(nEmpty != nullptr && *nEmpty == 326.0,
          "C2/BS-031(d): `count if sv==\"\"` == 326 (oracle-pinned out-of-range missing count)");
  }

  // (e) string `replace ... in a/b` -- oracle (live-verified this stint,
  // StataBE): starting from all-"x", `replace sv = "y" in 5/8` -> 4 rows
  // become "y", the other 332 KEEP "x" (replace-class: unchanged, not
  // missing).
  freshData();
  {
    (void)piet::dispatch("gen str8 sv = \"x\"", session);
    (void)piet::dispatch("replace sv = \"y\" in 5/8", session);
    (void)piet::dispatch("count if sv==\"y\"", session);
    const double* nY = session.eval.rValues.find("N");
    check(nY != nullptr && *nY == 4.0,
          "C2/BS-031(e): `count if sv==\"y\"` == 4 (oracle-pinned in-range count)");
    (void)piet::dispatch("count if sv==\"x\"", session);
    const double* nStillX = session.eval.rValues.find("N");
    check(nStillX != nullptr && *nStillX == 332.0,
          "C2/BS-031(e): `count if sv==\"x\"` == 332 (out-of-range rows KEPT their original "
          "value, oracle-pinned replace-class semantics)");
  }

  // Regression guard: `duplicates drop ... if ...` is now an honest reject
  // (the recombination this would need wasn't implemented this stint),
  // not a silent full-dataset dedup.
  freshData();
  {
    // `force' spelled so the guard reaches the `if' refusal (without it the
    // varlist drop is r(198) first, as measured on StataBE).
    auto dropBlocks = piet::dispatch("duplicates drop year if year==1982, force", session);
    bool sawDropError = false;
    for (const auto& b : dropBlocks) {
      if (b.is_object() && b.value("type", std::string()) == "error") sawDropError = true;
    }
    check(sawDropError,
          "C2/BS-031 regression guard: `duplicates drop ... if ...` is an honest reject (was "
          "silently collapsing the WHOLE dataset before this sweep)");
  }

  fs::remove_all(workdir, ec);
}

void testC2BS032EgenGroupTagByReject() {
  std::printf("[selftest] --- C2/BS-032 egen group()/tag() + by-context reject ---\n");
  namespace fs = std::filesystem;
  std::string workdir = (fs::temp_directory_path() / "piet_native_selftest_c2_bs032").u8string();
  std::error_code ec;
  fs::remove_all(workdir, ec);
  fs::create_directories(workdir, ec);
  piet::SessionState session(workdir);

  (void)piet::dispatch("sysuse fatalities, clear", session);
  (void)piet::dispatch("gen high = (beertax > .5)", session);

  // bysort-injected by() form.
  auto blocksBysort = piet::dispatch("bysort state: egen g1=group(year)", session);
  bool sawBysortError = false;
  std::string bysortMsg;
  for (const auto& b : blocksBysort) {
    if (b.is_object() && b.value("type", std::string()) == "error") {
      sawBysortError = true;
      bysortMsg = b.value("message", std::string());
    }
  }
  check(sawBysortError,
        "C2/BS-032: `bysort state: egen g1=group(year)` is an honest reject (real Stata: "
        "\"group() may not be combined with by\", r(190)) -- previously ran silently");
  check(bysortMsg.find("group()") != std::string::npos && bysortMsg.find("by") != std::string::npos,
        "C2/BS-032: reject message names group() and by, got: " + bysortMsg);

  // Explicit by() option form.
  auto blocksExplicit = piet::dispatch("egen g2=tag(year), by(state)", session);
  bool sawExplicitError = false;
  for (const auto& b : blocksExplicit) {
    if (b.is_object() && b.value("type", std::string()) == "error") sawExplicitError = true;
  }
  check(sawExplicitError,
        "C2/BS-032: `egen g2=tag(year), by(state)` (explicit by()) is ALSO an honest reject");

  // Regression guard: every OTHER egen function still legitimately combines
  // with by() -- this fix must not overreach.
  auto blocksOther = piet::dispatch("bysort state: egen g3=mean(income)", session);
  bool sawOtherError = false;
  for (const auto& b : blocksOther) {
    if (b.is_object() && b.value("type", std::string()) == "error") sawOtherError = true;
  }
  check(!sawOtherError,
        "C2/BS-032 regression guard: `bysort state: egen g3=mean(income)` (non group/tag "
        "function) still succeeds -- the by-reject is scoped to group()/tag() only");

  fs::remove_all(workdir, ec);
}

void testC2CorrObsFlagComposing() {
  std::printf("[selftest] --- C2 corr `obs` flag composes with C1/BS-028 (pwcorr obs -> "
              "block[\"obs\"]=true) ---\n");
  namespace fs = std::filesystem;
  std::string workdir = (fs::temp_directory_path() / "piet_native_selftest_c2_corrobs").u8string();
  std::error_code ec;
  fs::remove_all(workdir, ec);
  fs::create_directories(workdir, ec);
  piet::SessionState session(workdir);

  (void)piet::dispatch("sysuse fatalities, clear", session);
  (void)piet::dispatch("gen high = (beertax > .5)", session);

  auto blocks = piet::dispatch("pwcorr income beertax, obs", session);
  const nlohmann::ordered_json* corrBlock = nullptr;
  for (const auto& b : blocks) {
    if (b.is_object() && b.value("type", std::string()) == "estimation") corrBlock = &b;
  }
  check(corrBlock != nullptr, "C2/corr-obs: `pwcorr income beertax, obs` succeeds");
  if (corrBlock != nullptr) {
    check(corrBlock->value("obs", false) == true,
          "C2/corr-obs: the emitted block carries obs=true so a frontend can decide whether to "
          "render the per-pair N matrix -- previously `obs` was read but never recorded on the "
          "block itself");
    check(corrBlock->contains("nobs"),
          "C2/corr-obs regression guard: the per-pair `nobs` matrix (C1/BS-028) still flows "
          "unchanged");
  }

  // Regression guard: `pwcorr` WITHOUT `obs` does not carry the field.
  auto blocksNoObs = piet::dispatch("pwcorr income beertax", session);
  const nlohmann::ordered_json* noObsBlock = nullptr;
  for (const auto& b : blocksNoObs) {
    if (b.is_object() && b.value("type", std::string()) == "estimation") noObsBlock = &b;
  }
  check(noObsBlock != nullptr && !noObsBlock->contains("obs"),
        "C2/corr-obs regression guard: `pwcorr` without `obs` does not set block[\"obs\"]");

  fs::remove_all(workdir, ec);
}

