void testD5BS082IvDiag() {
  std::printf("[selftest] --- D5c/BS-082 estat endogenous/overid/firststage (IV diagnostics) ---\n");
  namespace fs = std::filesystem;
  std::string workdir = (fs::temp_directory_path() / "piet_native_selftest_d5_bs082").u8string();
  std::error_code ec;
  fs::remove_all(workdir, ec);
  fs::create_directories(workdir, ec);
  piet::SessionState session(workdir);

  (void)piet::dispatch("sysuse fatalities, clear", session);
  (void)piet::dispatch("ivregress 2sls income emppop (beertax = spirits unemp)", session);

  // BETA Phase G REWIRE: `cobra iv-diag` (a SEPARATE cobra CLI command from
  // `cobra iv`, apps/cmds/cmds_diag.cpp::cmd_ivdiag) genuinely computes
  // Durbin/Wu-Hausman/Sargan/Basmann — the D5 batch's honest-reject below
  // was right that `cobra iv --tidy`'s OWN payload has none of these, but
  // wrong that the engine has no such test at all. Cross-check pattern
  // (same style as testBS090InRangeExpansion/testBS092BysortSummarize):
  // call `cobra iv-diag` DIRECTLY with the same data/spec the ivregress
  // command above used, and confirm `estat endogenous`/`estat overid`
  // return the IDENTICAL numbers — proving the wiring reconstructs the
  // right --endog/--x/--instruments from LastModel, not just that SOME
  // number came back.
  nlohmann::json directDiag;
  bool haveDirect = false;
  // e(sample) T2: the fit leaves the head on its mask-install frame, which on
  // the resident plane exists only in the worker; this direct call reads the
  // head as a FILE, so it is written first (a no-op on a clean head).
  session.ensureMaterializedHead("selftest-d5c");
  if (session.currentHbin().has_value()) {
    try {
      directDiag = piet::runCobraJson({"iv-diag", "--y", "income", "--endog", "beertax", "--x",
                                        "emppop", "--instruments", "spirits,unemp", "--data",
                                        *session.currentHbin()});
      haveDirect = true;
    } catch (const piet::CobraError&) {
      haveDirect = false;
    }
  }
  check(haveDirect, "D5c/BS-082 setup: direct `cobra iv-diag` cross-check call succeeds");

  // estat endogenous: Durbin score chi2 + Wu-Hausman F, now wired (was an
  // honest reject pre-Phase-G).
  {
    auto blocks = piet::dispatch("estat endogenous", session);
    const auto* est = firstBlockOfTypeD1(blocks, "estimation");
    check(est != nullptr, "D5c/BS-082: `estat endogenous` returns an estimation block");
    if (est != nullptr && haveDirect && directDiag.contains("endogeneity")) {
      const auto& e = directDiag["endogeneity"];
      check(std::abs(est->value("durbin_chi2", -999.0) - e.value("durbin", -998.0)) < 1e-9,
            "D5c/BS-082: estat endogenous durbin_chi2 matches the direct `cobra iv-diag` call");
      check(std::abs(est->value("wu_hausman_F", -999.0) - e.value("wu_hausman", -998.0)) < 1e-9,
            "D5c/BS-082: estat endogenous wu_hausman_F matches the direct `cobra iv-diag` call");
    }
  }

  // estat overid: 2 instruments (spirits, unemp) > 1 endog (beertax) ->
  // overidentified -> a real Sargan/Basmann stat, not the just-identified
  // note (was an honest reject pre-Phase-G).
  {
    auto blocks = piet::dispatch("estat overid", session);
    const auto* est = firstBlockOfTypeD1(blocks, "estimation");
    check(est != nullptr, "D5c/BS-082: `estat overid` returns an estimation block");
    if (est != nullptr) {
      check(!est->contains("note"),
            "D5c/BS-082: this model is overidentified (2 instruments > 1 endog) — a real Sargan/"
            "Basmann stat, not the just-identified note");
      if (haveDirect && directDiag.contains("overid") && !directDiag["overid"].contains("note")) {
        const auto& o = directDiag["overid"];
        check(std::abs(est->value("sargan_chi2", -999.0) - o.value("sargan", -998.0)) < 1e-9,
              "D5c/BS-082: estat overid sargan_chi2 matches the direct `cobra iv-diag` call");
        check(std::abs(est->value("basmann_chi2", -999.0) - o.value("basmann", -998.0)) < 1e-9,
              "D5c/BS-082: estat overid basmann_chi2 matches the direct `cobra iv-diag` call");
      }
    }
  }

  // estat firststage: F(2,332)=2.56678 for beertax, oracle-matched (UNCHANGED).
  {
    auto blocks = piet::dispatch("estat firststage", session);
    const auto* est = firstBlockOfTypeD1(blocks, "estimation");
    check(est != nullptr, "D5c: `estat firststage` returns an estimation block");
    if (est != nullptr && est->contains("firststage") && (*est)["firststage"].is_array()) {
      double f = -999.0;
      for (const auto& row : (*est)["firststage"]) {
        if (row.value("name", std::string()) == "beertax") f = row.value("F", -999.0);
      }
      check(std::abs(f - 2.5667784083942093) < 0.001,
            "D5c oracle: firststage F(beertax) ~= 2.56678, got " + std::to_string(f));
    } else {
      check(false, "D5c: `estat firststage` block has a \"firststage\" array");
    }
  }

  fs::remove_all(workdir, ec);
}

void testD5BS086MarginsAt() {
  std::printf("[selftest] --- D5d/BS-086 margins at()/dydx() context forward ---\n");
  namespace fs = std::filesystem;
  std::string workdir = (fs::temp_directory_path() / "piet_native_selftest_d5_bs086").u8string();
  std::error_code ec;
  fs::remove_all(workdir, ec);
  fs::create_directories(workdir, ec);
  piet::SessionState session(workdir);

  (void)piet::dispatch("sysuse fatalities, clear", session);
  (void)piet::dispatch("gen high = (beertax > .5)", session);
  (void)piet::dispatch("logit high income unemp", session);

  // D5d dydx(income): dydx=-.0001192 se=.0000112 (this path was ALREADY
  // correct pre-batch — cobra margins --dydx --model logit genuinely
  // applies the logistic link; pinned here as a regression guard).
  {
    auto blocks = piet::dispatch("margins, dydx(income)", session);
    const auto* est = firstBlockOfTypeD1(blocks, "estimation");
    check(est != nullptr, "D5d: `margins, dydx(income)` after logit returns an estimation block");
    if (est != nullptr) {
      auto dydx = coefFieldD1(*est, "income", "b");
      check(dydx.has_value() && std::abs(*dydx - (-0.0001192)) < 0.000001,
            "D5d oracle: dydx(income) ~= -.0001192, got " +
                (dydx.has_value() ? std::to_string(*dydx) : "MISSING"));
      auto se = coefFieldD1(*est, "income", "se");
      check(se.has_value() && std::abs(*se - 0.0000112) < 0.000001,
            "D5d oracle: se ~= .0000112, got " + (se.has_value() ? std::to_string(*se) : "MISSING"));
    }
  }

  // D5d/BS-086, SUPERSEDED BY THE BUG-188 FIX (ONESHOT-PREP9, 2026-08-06).
  //
  // This leg used to pin the HONEST REFUSAL: the plain-`at()` branch rejected
  // after any non-OLS lastModel (kAtSafeCmds gate) because the engine was
  // believed to re-fit plain OLS regardless of --model, which would have
  // returned 0.41098... against Stata's logistic-link 0.4074234 — a ~1% gap.
  // The refusal was the right call WHILE it was true.
  //
  // What the fix changed: the branch now forwards `--model` for the
  // kDydxAtModels family, exactly as the neighbouring dydx()+at() branch had
  // always done. So the premise the refusal rested on is gone — the engine's
  // GLM at() site (cmds_postest.cpp) honours --model and applies the real link.
  //
  // The pin therefore INVERTS rather than disappears: it must now assert the
  // right ANSWER, using the very oracle the old comment recorded. That number
  // was captured from real Stata by a different investigation BEFORE this fix
  // existed, which makes it an independent check on the fix rather than a
  // restatement of it. Measured on the fixed build: 0.40742339233027786.
  // Deleting this leg instead of inverting it would have thrown away the one
  // in-tree witness that distinguishes "forwards --model" from "re-fits OLS".
  {
    auto blocks = piet::dispatch("margins, at(income=13000)", session);
    const auto* est = firstBlockOfTypeD1(blocks, "estimation");
    check(est != nullptr,
          "D5d/BS-086: `margins, at(...)` after `logit` now ANSWERS (BUG-188 fixed; the "
          "kAtSafeCmds refusal is superseded by forwarding --model)");
    if (est != nullptr) {
      // NOT coefFieldD1, and NOT "coeftable": an at()-form margins block puts
      // its rows under a "margins" array, keyed by "at" (not "name") with the
      // value in "margin" (not "b"). coefFieldD1 returns nullopt on all three
      // counts, so the leg would read MISSING — a false RED that looks exactly
      // like a real regression. Verified against the live block shape:
      // keys = [type, estimator, depvar, n_obs, margins, df].
      std::optional<double> m;
      if (est->contains("margins") && (*est)["margins"].is_array()) {
        for (const auto& row : (*est)["margins"]) {
          if (row.value("at", std::string()) == "income=13000" &&
              row.contains("margin") && row["margin"].is_number()) {
            m = row["margin"].get<double>();
          }
        }
      }
      check(m.has_value() && std::abs(*m - 0.4074234) < 0.000001,
            "D5d/BS-086 oracle: margin ~= .4074234 (Stata's logistic link), NOT .41098 (the "
            "OLS-refit answer the old refusal existed to avoid); got " +
                (m.has_value() ? std::to_string(*m) : "MISSING"));
    }
  }

  // Regression guard: margins, at(...) after a plain OLS fit (feols/
  // regress) is genuinely safe (the engine's OLS refit reproduces the
  // model's own coefficients exactly) and must still WORK.
  (void)piet::dispatch("regress income beertax", session);
  {
    auto blocks = piet::dispatch("margins, at(beertax=0.5)", session);
    const auto* est = firstBlockOfTypeD1(blocks, "estimation");
    check(est != nullptr,
          "D5d/BS-086: `margins, at(...)` after `regress` (kAtSafeCmds) still succeeds");
  }

  fs::remove_all(workdir, ec);
}

void testD5BS083Hausman() {
  std::printf("[selftest] --- D5e/BS-083 hausman (xtreg fe/re specification test) ---\n");
  namespace fs = std::filesystem;
  std::string workdir = (fs::temp_directory_path() / "piet_native_selftest_d5_bs083").u8string();
  std::error_code ec;
  fs::remove_all(workdir, ec);
  fs::create_directories(workdir, ec);
  piet::SessionState session(workdir);

  (void)piet::dispatch("sysuse fatalities, clear", session);
  (void)piet::dispatch("encode state, gen(snum)", session);
  (void)piet::dispatch("xtset snum year", session);
  (void)piet::dispatch("xtreg income beertax unemp, fe", session);
  (void)piet::dispatch("eststo feM", session);
  (void)piet::dispatch("xtreg income beertax unemp, re", session);
  (void)piet::dispatch("eststo reM", session);

  // D5e: chi2=2.62, p=0.2697, beertax diff=376.6603, unemp diff=-.6916189.
  {
    auto blocks = piet::dispatch("hausman feM reM", session);
    const auto* est = firstBlockOfTypeD1(blocks, "estimation");
    check(est != nullptr, "D5e: `hausman feM reM` returns an estimation block");
    if (est != nullptr) {
      double chi2 = est->value("chi2", -999.0);
      check(std::abs(chi2 - 2.6205813255838897) < 0.001,
            "D5e oracle: chi2 ~= 2.62, got " + std::to_string(chi2));
      double p = est->value("p", -999.0);
      check(std::abs(p - 0.26974164113052557) < 0.001,
            "D5e oracle: p ~= .2697, got " + std::to_string(p));
      double diffBeertax = -999.0, diffUnemp = -999.0;
      if (est->contains("coefs") && (*est)["coefs"].is_array()) {
        for (const auto& row : (*est)["coefs"]) {
          if (row.value("name", std::string()) == "beertax") diffBeertax = row.value("diff", -999.0);
          if (row.value("name", std::string()) == "unemp") diffUnemp = row.value("diff", -999.0);
        }
      }
      check(std::abs(diffBeertax - 376.6602970137676) < 0.01,
            "D5e oracle: beertax diff ~= 376.6603, got " + std::to_string(diffBeertax));
      check(std::abs(diffUnemp - (-0.691618945067205)) < 0.01,
            "D5e oracle: unemp diff ~= -.6916189, got " + std::to_string(diffUnemp));
    }
  }

  // Missing store name.
  (void)piet::dispatch("capture hausman feM bogusName", session);
  check(session.eval.locals.get("_rc", "") != "0",
        "D5/BS-083: `hausman feM bogusName` (missing store) honestly rejects");

  // Two of the SAME type (both fe) — not a valid fe/re pair.
  (void)piet::dispatch("xtreg income beertax unemp, fe", session);
  (void)piet::dispatch("eststo feM2", session);
  (void)piet::dispatch("capture hausman feM feM2", session);
  check(session.eval.locals.get("_rc", "") != "0",
        "D5/BS-083: `hausman feM feM2` (two fe stores, not an fe/re pair) honestly rejects");

  fs::remove_all(workdir, ec);
}

void testD5BS084Chow() {
  std::printf("[selftest] --- D5f/BS-084 chow (PIET convenience wrapper) ---\n");
  namespace fs = std::filesystem;
  std::string workdir = (fs::temp_directory_path() / "piet_native_selftest_d5_bs084").u8string();
  std::error_code ec;
  fs::remove_all(workdir, ec);
  fs::create_directories(workdir, ec);
  piet::SessionState session(workdir);

  (void)piet::dispatch("sysuse fatalities, clear", session);
  (void)piet::dispatch("gen high = (beertax > .5)", session);

  // D5f: manually-computed oracle chowF=28.074171, df1=2, df2=332
  // (real Stata has no `chow` command — see runChow's header comment).
  auto blocks = piet::dispatch("chow income beertax, by(high)", session);
  const auto* est = firstBlockOfTypeD1(blocks, "estimation");
  check(est != nullptr, "D5f: `chow income beertax, by(high)` returns an estimation block");
  if (est != nullptr && est->contains("classic")) {
    double f = (*est)["classic"].value("F", -999.0);
    check(std::abs(f - 28.07417107825576) < 0.001,
          "D5f oracle: chowF ~= 28.074171, got " + std::to_string(f));
    int df1 = (*est)["classic"].value("df1", -1);
    int df2 = (*est)["classic"].value("df2", -1);
    check(df1 == 2 && df2 == 332, "D5f oracle: df1=2 df2=332, got df1=" + std::to_string(df1) +
                                       " df2=" + std::to_string(df2));
  } else {
    check(false, "D5f: `chow` block has a \"classic\" sub-object");
  }

  // by() is required.
  (void)piet::dispatch("capture chow income beertax", session);
  check(session.eval.locals.get("_rc", "") != "0",
        "D5/BS-084: `chow income beertax` without by() honestly rejects");

  fs::remove_all(workdir, ec);
}

void testD5BS087Mkspline() {
  std::printf("[selftest] --- D5g/BS-087(part) mkspline (cubic restricted spline) ---\n");
  namespace fs = std::filesystem;
  std::string workdir = (fs::temp_directory_path() / "piet_native_selftest_d5_bs087").u8string();
  std::error_code ec;
  fs::remove_all(workdir, ec);
  fs::create_directories(workdir, ec);
  piet::SessionState session(workdir);

  (void)piet::dispatch("sysuse fatalities, clear", session);

  // nknots() ENGINE FIX (see runMkspline's header comment, estimation_m4.cpp):
  // cobra eval --mkspline's own nknots(#) clause was broken through 0.24.0
  // (a paren_arg substring collision), fixed in 0.25.0 — the D5g oracle's
  // own exact invocation (`nknots(4)`) now SUCCEEDS cleanly instead of
  // surfacing an engine_error.
  {
    auto blocks =
        piet::dispatch("capture noisily mkspline inc_sp = income, cubic nknots(4)", session);
    check(session.eval.locals.get("_rc", "") == "0",
          "D5g/BS-087: `mkspline inc_sp = income, cubic nknots(4)` (the D5g oracle's own "
          "invocation) now SUCCEEDS (cobra 0.25.0 fix), got _rc=" +
              session.eval.locals.get("_rc", "<unset>"));
    const auto* mut = firstBlockOfTypeD1(blocks, "data_mutation");
    check(mut != nullptr, "D5g: `mkspline inc_sp = ..., cubic nknots(4)` returns a data_mutation "
                          "block");
    if (mut != nullptr && mut->contains("new_vars")) {
      check((*mut)["new_vars"].size() == 3,
            "D5g oracle: nknots(4) -> 3 spline basis columns, got " +
                std::to_string((*mut)["new_vars"].size()));
    }
  }

  // Wiring proof: the explicit knots() form independently exercises the
  // mkspline plumbing under a FRESH stub name (`ek_sp`, not `inc_sp` —
  // now that nknots() above also succeeds and already created the
  // inc_sp1..3 columns, reusing that stub here would collide with them
  // instead of proving this leg's OWN new_vars wiring).
  {
    auto blocks =
        piet::dispatch("mkspline ek_sp = income, cubic knots(10000,12000,14000,16000)", session);
    const auto* mut = firstBlockOfTypeD1(blocks, "data_mutation");
    check(mut != nullptr,
          "D5g: `mkspline ek_sp = ..., cubic knots(...)` (explicit knots, fresh stub) returns a "
          "data_mutation block");
    if (mut != nullptr && mut->contains("new_vars")) {
      check((*mut)["new_vars"].size() == 3,
            "D5g: 4 explicit knots -> 3 spline basis columns, got " +
                std::to_string((*mut)["new_vars"].size()));
    }
  }

  // Linear (no `cubic`) honestly rejects — the engine has no linear basis
  // (it would silently compute a cubic one instead).
  (void)piet::dispatch("capture mkspline lin_sp = income", session);
  check(session.eval.locals.get("_rc", "") != "0",
        "D5/BS-087: `mkspline stub = var` (no `cubic`) honestly rejects (engine has no linear "
        "spline — always computes cubic regardless of the keyword)");

  fs::remove_all(workdir, ec);
}

// BETA campaign Phase E (graphics batch, native geometry/options side):
// BUG-099 real lfit/qfit fits, BS-049 kdensity kernel()/Epanechnikov
// default + bandwidth/grid fixes, BS-050 multi-y `scatter y1 y2 x`,
// BS-052 by() honest reject, BS-053 `||` layer separator, BS-054 twoway
// kdensity/histogram umbrella-prefixed forms, BS-055 xtline/tsline SVG
// export real data, BS-056 `graph drop` multi-name + `_all`, BUG-103
// TMPDIR-dependent as(png) extensionless-fallback path bug. All numeric
// legs pinned against a live-Stata oracle probe on the SAME bundled
// fatalities.csv (internal capture
// e-oracle-stata.log) -- not re-derived here.
void testBetaEGraphicsBatch() {
  std::printf("[selftest] --- BETA E graphics batch: BUG-099 lfit/qfit, BS-049/050/052/053/054/055/056, "
              "BUG-103 ---\n");
  namespace fs = std::filesystem;
  std::string base = (fs::temp_directory_path() / "piet_native_selftest_betae_graphics").u8string();
  std::error_code ec;
  fs::remove_all(base, ec);
  fs::create_directories(base, ec);

  auto runCmd = [](piet::SessionState& session, const std::string& cmd) {
    nlohmann::json body{{"cmd", cmd}};
    auto r = piet::routes::command(session, body.dump());
    return nlohmann::json::parse(r.json);
  };
  auto firstBlockOfType = [](const nlohmann::json& j, const std::string& type) -> nlohmann::json {
    for (const auto& b : j.value("blocks", nlohmann::json::array())) {
      if (b.value("type", std::string()) == type) return b;
    }
    return nlohmann::json();
  };
  auto findLayerByKind = [](const nlohmann::json& twowayBlock, const std::string& kind) -> nlohmann::json {
    for (const auto& l : twowayBlock.value("layers", nlohmann::json::array())) {
      if (l.value("kind", std::string()) == kind) return l;
    }
    return nlohmann::json();
  };
  auto readFile = [](const std::string& path) -> std::string {
    std::ifstream in(cecon::to_native_path(path), std::ios::binary);
    std::ostringstream ss;
    ss << in.rdbuf();
    return ss.str();
  };

  // Every leg below (BUG-099, BS-049/050/052/053/054/055/056, BUG-103) opens
  // with `sysuse fatalities, clear` and then chains
  // firstBlockOfType(...).value(...)/findLayerByKind(...) unguarded. In the
  // isolated/subset-build environment (no piet/packaging/sample/
  // fatalities.csv), that throws the same json.exception.type_error.306 as
  // the earlier BUG-039/BUG-055/BUG-056/BS-013/BS-048/BS-047/BS-008-057 legs
  // (FIX-SELFTEST-ISOBUILD-CRASH). One up-front probe covers every leg below.
  {
    std::string probeWd = base + "/_fixture_probe";
    fs::create_directories(probeWd, ec);
    piet::SessionState probeSession(probeWd);
    runCmd(probeSession, "sysuse fatalities, clear");
    if (!probeSession.hasData()) {
      skip("BETA E graphics batch (all legs: BUG-099, BS-049/050/052/053/054/055/056, BUG-103)",
           "`sysuse fatalities` setup returned no data");
      fs::remove_all(base, ec);
      return;
    }
  }

  // --- BUG-099: `lfit`/`qfit` real OLS fits (parenthesised-layer form).
  // Oracle: `regress income beertax` on fatalities.csv (all 336 obs, no
  // if-filter) -> b_cons=14842.18, b_beertax=-1874.3005; xmin=.04331088,
  // xmax=2.7207637; yhat_at_xmin=14761.003, yhat_at_xmax=9742.6517.
  // `regress income beertax beertax2` -> b_cons=15931.426,
  // b_beertax=-5823.7769, b_beertax2=1909.7359.
  {
    std::string wd = base + "/bug099_lfit_qfit";
    fs::create_directories(wd, ec);
    piet::SessionState session(wd);
    runCmd(session, "sysuse fatalities, clear");

    auto jLfit = runCmd(session, "twoway (scatter income beertax) (lfit income beertax)");
    check(firstBlockOfType(jLfit, "error").is_null(), "BUG-099 setup: scatter+lfit twoway succeeds");
    auto graphLfit = firstBlockOfType(jLfit, "graph");
    auto lfitLayer = findLayerByKind(graphLfit, "lfit");
    check(!lfitLayer.is_null(), "BUG-099: the twoway result has a layer with kind==\"lfit\" (not "
                                 "aliased to \"line\")");
    if (!lfitLayer.is_null()) {
      auto pts = lfitLayer.value("points", nlohmann::json::array());
      check(pts.size() == 2,
            "BUG-099: lfit renders as a 2-point line (a real fit), not a 336-point connect-the-dots "
            "polyline through the raw data — got " + std::to_string(pts.size()) + " points");
      if (pts.size() == 2) {
        check(std::abs(pts[0][0].get<double>() - 0.04331088) < 1e-4,
              "BUG-099: lfit's first point x == the data's own xmin (r(min))");
        check(std::abs(pts[0][1].get<double>() - 14761.003) < 0.5,
              "BUG-099: lfit's fitted y at xmin matches the oracle's yhat_at_xmin=14761.003");
        check(std::abs(pts[1][0].get<double>() - 2.7207637) < 1e-4,
              "BUG-099: lfit's last point x == the data's own xmax (r(max))");
        check(std::abs(pts[1][1].get<double>() - 9742.6517) < 0.5,
              "BUG-099: lfit's fitted y at xmax matches the oracle's yhat_at_xmax=9742.6517");
      }
      double cons = lfitLayer.value("coef", nlohmann::json::object()).value("cons", 0.0);
      double slope = lfitLayer.value("coef", nlohmann::json::object()).value("slope", 0.0);
      check(std::abs(cons - 14842.18) < 0.05, "BUG-099: lfit b_cons matches oracle 14842.18");
      check(std::abs(slope - (-1874.3005)) < 0.01, "BUG-099: lfit b_beertax matches oracle -1874.3005");
    }

    auto jQfit = runCmd(session, "twoway (scatter income beertax) (qfit income beertax)");
    check(firstBlockOfType(jQfit, "error").is_null(), "BUG-099 setup: scatter+qfit twoway succeeds");
    auto graphQfit = firstBlockOfType(jQfit, "graph");
    auto qfitLayer = findLayerByKind(graphQfit, "qfit");
    check(!qfitLayer.is_null(), "BUG-099: the twoway result has a layer with kind==\"qfit\"");
    if (!qfitLayer.is_null()) {
      auto pts = qfitLayer.value("points", nlohmann::json::array());
      check(pts.size() == 100, "BUG-099: qfit samples the fitted curve at n=100 points, got " +
                                    std::to_string(pts.size()));
      double cons = qfitLayer.value("coef", nlohmann::json::object()).value("cons", 0.0);
      double b1 = qfitLayer.value("coef", nlohmann::json::object()).value("b1", 0.0);
      double b2 = qfitLayer.value("coef", nlohmann::json::object()).value("b2", 0.0);
      check(std::abs(cons - 15931.426) < 0.5, "BUG-099: qfit b_cons matches oracle 15931.426");
      check(std::abs(b1 - (-5823.7769)) < 0.5, "BUG-099: qfit b_beertax matches oracle -5823.7769");
      check(std::abs(b2 - 1909.7359) < 0.5, "BUG-099: qfit b_beertax2 matches oracle 1909.7359");
    }
  }

  // --- BS-049: kdensity kernel()/Epanechnikov default, bandwidth 1.349
  // constant, and the xmin-h/xmax+h grid range (was xmin-3h/xmax+3h).
  // Oracle: `kdensity income, n(50)` -> bwidth=633.4973; kx/kd row 1 =
  // (8880.2644, 4.979e-06); row 5 = (10018.77, .00003834); row 50 =
  // (22826.952, 1.261e-06). Gaussian variant row 1 = (8880.2644, 4.915e-06).
  {
    std::string wd = base + "/bs049_kdensity_kernel";
    fs::create_directories(wd, ec);
    piet::SessionState session(wd);
    runCmd(session, "sysuse fatalities, clear");

    auto jEpan = runCmd(session, "kdensity income, n(50)");
    check(firstBlockOfType(jEpan, "error").is_null(), "BS-049 setup: default kdensity succeeds");
    auto gEpan = firstBlockOfType(jEpan, "graph");
    check(gEpan.value("kernel", std::string()) == "epanechnikov",
          "BS-049: default kernel is epanechnikov (Stata's own default), not gaussian");
    check(std::abs(gEpan.value("bwidth", 0.0) - 633.4973) < 0.01,
          "BS-049: bandwidth matches the oracle's Silverman-rule value 633.4973 (1.349 constant)");
    auto ptsEpan = gEpan.value("points", nlohmann::json::array());
    check(ptsEpan.size() == 50, "BS-049 setup: n(50) grid has 50 points");
    if (ptsEpan.size() == 50) {
      check(std::abs(ptsEpan[0][0].get<double>() - 8880.2644) < 0.01,
            "BS-049: grid point 1's x == oracle's kx[1]=8880.2644 (xmin-1*bwidth, was xmin-3*bwidth)");
      check(std::abs(ptsEpan[0][1].get<double>() - 4.979e-06) < 5e-8,
            "BS-049: grid point 1's density matches oracle Epanechnikov kd[1]=4.979e-06");
      check(std::abs(ptsEpan[4][1].get<double>() - 3.834e-05) < 5e-7,
            "BS-049: grid point 5's density matches oracle Epanechnikov kd[5]=.00003834");
      check(std::abs(ptsEpan[49][0].get<double>() - 22826.952) < 0.01,
            "BS-049: grid point 50's x == oracle's kx[50]=22826.952 (xmax+1*bwidth)");
      check(std::abs(ptsEpan[49][1].get<double>() - 1.261e-06) < 5e-8,
            "BS-049: grid point 50's density matches oracle Epanechnikov kd[50]=1.261e-06");
    }

    auto jGauss = runCmd(session, "kdensity income, n(50) kernel(gaussian)");
    check(firstBlockOfType(jGauss, "error").is_null(), "BS-049 setup: kernel(gaussian) succeeds");
    auto gGauss = firstBlockOfType(jGauss, "graph");
    check(gGauss.value("kernel", std::string()) == "gaussian", "BS-049: kernel(gaussian) is honored");
    auto ptsGauss = gGauss.value("points", nlohmann::json::array());
    if (ptsGauss.size() == 50) {
      check(std::abs(ptsGauss[0][1].get<double>() - 4.915e-06) < 5e-8,
            "BS-049: kernel(gaussian) grid point 1's density matches oracle kd[1]=4.915e-06 "
            "(different value from the Epanechnikov default -- proves kernel() is actually read)");
    }

    // gfx-histogram-kdensity-family: all eight kernels are served now, so an
    // unknown name is Stata's own refusal (w2aq_histogram_family hk_r_kd_kern:
    // `invalid kernel function`, r(198)), not a "supported here" gap.
    auto jBadKernel = runCmd(session, "kdensity income, kernel(uniform)");
    auto errBadKernel = firstBlockOfType(jBadKernel, "error");
    check(!errBadKernel.is_null() && errBadKernel.value("message", std::string()) == "invalid kernel function" &&
              errBadKernel.value("reason", std::string()) == "r(198)",
          "BS-049: an unknown kernel() name is refused as Stata refuses it (r(198) invalid kernel "
          "function), not a silent substitution");
  }

  // --- BS-050: `scatter y1 y2 x` multi-y -- last var is x, every var
  // before it is an independent y-series.
  {
    std::string wd = base + "/bs050_multiy_scatter";
    fs::create_directories(wd, ec);
    piet::SessionState session(wd);
    runCmd(session, "sysuse fatalities, clear");

    auto jSingle = runCmd(session, "scatter income beertax");
    check(firstBlockOfType(jSingle, "error").is_null(), "BS-050 regression: single-y scatter still works");
    auto gSingle = firstBlockOfType(jSingle, "graph");
    check(!gSingle.contains("series"),
          "BS-050 regression: the single-y (2-token) case keeps the EXACT legacy flat JSON shape -- "
          "no \"series\" key at all");
    check(gSingle.value("x_var", std::string()) == "beertax" && gSingle.value("y_var", std::string()) == "income",
          "BS-050 regression: single-y x_var/y_var unchanged");

    auto jMulti = runCmd(session, "scatter income spirits beertax");
    check(firstBlockOfType(jMulti, "error").is_null(), "BS-050: `scatter income spirits beertax` succeeds");
    auto gMulti = firstBlockOfType(jMulti, "graph");
    check(gMulti.value("x_var", std::string()) == "beertax",
          "BS-050: the LAST token (beertax) is the shared x, not the first");
    auto series = gMulti.value("series", nlohmann::json::array());
    check(series.size() == 2, "BS-050: two y-series (income, spirits) registered, got " +
                                   std::to_string(series.size()));
    if (series.size() == 2) {
      check(series[0].value("y_var", std::string()) == "income" &&
                series[1].value("y_var", std::string()) == "spirits",
            "BS-050: series are in the typed order income, spirits (not alphabetized/reordered)");
      check(series[0]["n"].get<int64_t>() > 0 && series[1]["n"].get<int64_t>() > 0,
            "BS-050: both series carry real (non-empty) point data");
    }
  }

  // --- BS-052: `by()` real faceting is honestly rejected everywhere it's
  // read (scatter/histogram/kdensity/twoway), not silently dropped.
  {
    std::string wd = base + "/bs052_by_facet_reject";
    fs::create_directories(wd, ec);
    piet::SessionState session(wd);
    runCmd(session, "sysuse fatalities, clear");

    auto jScatterBy = runCmd(session, "scatter income beertax, by(state)");
    check(firstBlockOfType(jScatterBy, "error").value("code", std::string()) == "unsupported_option",
          "BS-052: `scatter ..., by(state)` is an honest unsupported_option reject");
    // gfx-histogram-kdensity-family: histogram's by() is served (one panel per
    // group, common start and width: w2aq_histogram_family hk_h_bystr, hk_h_byfw).
    auto jHistBy = runCmd(session, "histogram income, by(state)");
    auto gHistBy = firstBlockOfType(jHistBy, "graph");
    check(firstBlockOfType(jHistBy, "error").is_null() && !gHistBy.is_null() &&
              gHistBy.value("panels", nlohmann::json::array()).size() > 1,
          "BS-052: `histogram ..., by(state)` draws one panel per state");
    auto jKdensBy = runCmd(session, "kdensity income, by(state)");
    check(firstBlockOfType(jKdensBy, "error").value("code", std::string()) == "unsupported_option",
          "BS-052: `kdensity ..., by(state)` is an honest unsupported_option reject");
    auto jTwowayBy = runCmd(session, "twoway (scatter income beertax), by(state)");
    check(firstBlockOfType(jTwowayBy, "error").value("code", std::string()) == "unsupported_option",
          "BS-052: parenthesised `twoway (scatter ...), by(state)` (global option) is an honest "
          "unsupported_option reject");
  }

  // --- BS-053: `||` double-pipe layer separator -- an alternate spelling
  // of the parenthesised multi-layer form, same layer semantics.
  {
    std::string wd = base + "/bs053_double_pipe";
    fs::create_directories(wd, ec);
    piet::SessionState session(wd);
    runCmd(session, "sysuse fatalities, clear");

    auto jPipe = runCmd(session, "twoway scatter income beertax || lfit income beertax");
    check(firstBlockOfType(jPipe, "error").is_null(), "BS-053: `scatter ... || lfit ...` succeeds");
    auto gPipe = firstBlockOfType(jPipe, "graph");
    check(gPipe.value("kind", std::string()) == "twoway",
          "BS-053: `||` routes through the SAME multi-layer twoway path as the parenthesised form");
    auto layers = gPipe.value("layers", nlohmann::json::array());
    check(layers.size() == 2,
          "BS-053: `||` produced TWO layers (was silently truncating to just the first plot) -- got " +
              std::to_string(layers.size()));
    if (layers.size() == 2) {
      check(layers[0].value("kind", std::string()) == "scatter" &&
                layers[1].value("kind", std::string()) == "lfit",
            "BS-053: layer order/kinds preserved (scatter, then lfit)");
      auto pts = layers[1].value("points", nlohmann::json::array());
      check(pts.size() == 2, "BS-053: the `||`-form lfit layer is a real 2-point fit, not raw data");
    }

    // A single `|` (Stata's logical-or inside an `if`) must NOT be
    // mistaken for the `||` layer separator.
    auto jSingleBar = runCmd(session, "twoway scatter income beertax if year==1982 | year==1983");
    check(firstBlockOfType(jSingleBar, "error").is_null(),
          "BS-053 regression: a single `|` inside an `if` expression still parses fine (not "
          "mistaken for `||`)");
  }

  // --- BS-054: `twoway kdensity x` / `twoway histogram x` (umbrella-
  // prefixed spellings) route to the SAME already-working runKdensity/
  // runHistogram, instead of "variable kdensity not found".
  {
    std::string wd = base + "/bs054_twoway_prefixed";
    fs::create_directories(wd, ec);
    piet::SessionState session(wd);
    runCmd(session, "sysuse fatalities, clear");

    // serset-twoway HKL: `twoway kdensity|histogram` is the twoway PLOT TYPE
    // (twoway__kdensity_gen's 300-point grid over [min, max]; no start() unless
    // given -- w2al tf_kd_n log:3524-3540, tf_hist_082), drawn as a twoway graph
    // with one kdensity / histogram layer, not the kdensity/histogram COMMAND's
    // block.
    auto jTwKdens = runCmd(session, "twoway kdensity income");
    check(firstBlockOfType(jTwKdens, "error").is_null(),
          "BS-054: `twoway kdensity income` no longer errors \"variable kdensity not found\"");
    auto gTwKdens = firstBlockOfType(jTwKdens, "graph");
    auto kdLayers = gTwKdens.value("layers", nlohmann::json::array());
    check(gTwKdens.value("kind", std::string()) == "twoway" && kdLayers.size() == 1 &&
              kdLayers[0].value("kind", std::string()) == "kdensity",
          "BS-054: `twoway kdensity income` renders a real kdensity layer");

    auto jTwHist = runCmd(session, "twoway histogram income");
    check(firstBlockOfType(jTwHist, "error").is_null(),
          "BS-054: `twoway histogram income` no longer errors \"variable histogram not found\"");
    auto gTwHist = firstBlockOfType(jTwHist, "graph");
    auto hLayers = gTwHist.value("layers", nlohmann::json::array());
    check(gTwHist.value("kind", std::string()) == "twoway" && hLayers.size() == 1 &&
              hLayers[0].value("kind", std::string()) == "histogram",
          "BS-054: `twoway histogram income` renders a real histogram layer");

    // serset-twoway SS: every graph leaves its sersets in the session store
    // (w2al_twoway_family.log:5380-5456): a data plot and a fit are two sersets,
    // the current one the last made; `graph drop _all` takes them with it.
    runCmd(session, "graph drop _all");
    runCmd(session, "serset clear");
    runCmd(session, "twoway (scatter income beertax) (lfit income beertax), name(ssG, replace)");
    const auto* ss0 = session.sersets.get(0);
    const auto* ss1 = session.sersets.get(1);
    check(session.sersets.all().size() == 2 && session.sersets.current() == 1 && ss0 != nullptr &&
              ss1 != nullptr && ss0->cols.size() == 2 && ss0->cols[0].name == "income" &&
              ss1->n == 3 && ss1->cols.size() == 2 && ss1->cols[1].name == "beertax" &&
              ss1->cols[1].type == "float",
          "SS: `twoway (scatter) (lfit)` leaves 2 sersets (income beertax; the 3-point fit grid)");
    runCmd(session, "graph drop _all");
    check(session.sersets.empty() && session.sersets.current() == -1,
          "SS: `graph drop _all` drops every serset");
  }

  // --- BS-055: xtline/tsline `graph export` now draws real data, not just
  // an empty frame (buildSvgDispatch had no kind branch for either, so both
  // fell through to buildSvgScatter's "points" key, which neither block
  // shape carries).
  {
    std::string wd = base + "/bs055_xtline_tsline_export";
    fs::create_directories(wd, ec);
    piet::SessionState session(wd);
    runCmd(session, "sysuse fatalities, clear");
    runCmd(session, "egen sid = group(state)");  // xtset refuses a string panel (BUG-1164)
    runCmd(session, "xtset sid year");  // also seeds session.timevar for tsline

    auto jXt = runCmd(session, "xtline fatal");
    check(firstBlockOfType(jXt, "error").is_null(), "BS-055 setup: `xtline fatal` succeeds");
    std::string xtSvgPath = wd + "/xtline.svg";
    auto jXtExp = runCmd(session, "graph export \"" + xtSvgPath + "\", replace");
    check(firstBlockOfType(jXtExp, "error").is_null(), "BS-055 setup: xtline `graph export` succeeds");
    check(fs::exists(xtSvgPath, ec), "BS-055 setup: the xtline export actually wrote a file");
    std::string xtSvg = readFile(xtSvgPath);
    check(xtSvg.find("<path") != std::string::npos,
          "BS-055: the exported xtline SVG contains real <path> data (was frame/axes/title only, "
          "zero data)");

    auto jTs = runCmd(session, "tsline fatal");
    check(firstBlockOfType(jTs, "error").is_null(), "BS-055 setup: `tsline fatal` succeeds");
    std::string tsSvgPath = wd + "/tsline.svg";
    auto jTsExp = runCmd(session, "graph export \"" + tsSvgPath + "\", replace");
    check(firstBlockOfType(jTsExp, "error").is_null(), "BS-055 setup: tsline `graph export` succeeds");
    std::string tsSvg = readFile(tsSvgPath);
    check(tsSvg.find("<path") != std::string::npos,
          "BS-055: the exported tsline SVG contains real <path> data (was frame/axes/title only, "
          "zero data)");
  }

  // --- BS-056: `graph drop namelist | _all` -- multi-name + honest reject
  // on an unknown name, `_all` clears everything.
  {
    std::string wd = base + "/bs056_graph_drop";
    fs::create_directories(wd, ec);
    piet::SessionState session(wd);
    runCmd(session, "sysuse fatalities, clear");

    runCmd(session, "scatter income beertax, name(g1)");
    runCmd(session, "scatter income spirits, name(g2)");
    check(session.namedGraphs.count("g1") == 1 && session.namedGraphs.count("g2") == 1,
          "BS-056 setup: g1 and g2 both registered");

    auto jDrop2 = runCmd(session, "graph drop g1 g2");
    check(firstBlockOfType(jDrop2, "error").is_null(), "BS-056: `graph drop g1 g2` (multi-name) succeeds");
    check(session.namedGraphs.count("g1") == 0 && session.namedGraphs.count("g2") == 0,
          "BS-056: BOTH g1 and g2 are gone (was first-name-only -- g2 used to survive silently)");

    auto jDropMissing = runCmd(session, "graph drop g1");
    auto errMissing = firstBlockOfType(jDropMissing, "error");
    check(!errMissing.is_null(),
          "BS-056: dropping an already-gone name is an honest reject, not a silent \"(graph "
          "dropped)\" false success");
    check(errMissing.value("message", std::string()).find("g1") != std::string::npos,
          "BS-056: the reject names the missing graph");

    runCmd(session, "scatter income beertax, name(g3)");
    runCmd(session, "scatter income spirits, name(g4)");
    auto jDropAll = runCmd(session, "graph drop _all");
    check(firstBlockOfType(jDropAll, "error").is_null(), "BS-056: `graph drop _all` succeeds");
    check(session.namedGraphs.empty(), "BS-056: `_all` clears every named graph");
  }

  // --- BUG-103: `as(png)` extensionless-path fallback must resolve the
  // same regardless of whether the workdir/TMPDIR happens to contain a
  // dot in a path component (e.g. a scratch dir literally named
  // `.dotted-scratch`, standing in for a real dotted TMPDIR like
  // `<volume>/<workspace>/.tmp-scratch`) -- this reproduces the bug
  // in-process without depending on the ambient TMPDIR env var.
  {
    std::string wd = base + "/bug103_dotted_dir";
    std::string dottedDir = wd + "/.dotted-scratch";
    fs::create_directories(dottedDir, ec);
    piet::SessionState session(wd);
    runCmd(session, "sysuse fatalities, clear");
    runCmd(session, "scatter income beertax");

    std::string noExtPath = dottedDir + "/noext_plot";
    auto j = runCmd(session, "graph export \"" + noExtPath + "\", as(png) replace");
    check(firstBlockOfType(j, "error").is_null(),
          "BUG-103: `as(png)` on an extensionless path under a DOTTED directory still succeeds");
    // graph-family AI-13: the file lands at the path as given (w2ai
    // gf_exp_asonly_f, log:1987-2001), inside the dotted directory -- the
    // directory's dot is never read as the file's extension.
    check(fs::exists(noExtPath, ec),
          "BUG-103: the png lands at the CORRECT path (dottedDir/noext_plot), not a path truncated "
          "at the directory's dot");
    if (fs::exists(noExtPath, ec)) {
      check(readFile(noExtPath).rfind("\x89PNG", 0) == 0, "BUG-103: the file is a real PNG");
    }
  }

  fs::remove_all(base, ec);
}

// BETA campaign Phase G (BS-090): `in a/b` row-range expansion beyond
// list/browse/gen/replace — summarize/sum, count, ttest, corr/correlate/
// pwcorr, regress/reg/r/feols/reghdfe, tabulate/tab/tab1/tab2, duplicates
// (report/tag/list real, drop honest-rejects — same disclosed boundary as
// its pre-existing `if` reject), egen, drop, keep, collapse. Every leg
// below cross-checks the qualifier-restricted call against an
// INDEPENDENTLY reduced copy (`keep in a/b` on a fresh session, then the
// plain unqualified command) rather than a hardcoded oracle number — this
// is self-verifying (two independent code paths must agree) and exercises
// `keep`'s own new `in` support as a side effect of every leg. All legs use
// the bundled `fatalities` panel, whose rows are state-blocked in CSV
// appearance order (7 consecutive rows per state, live-verified this
// stint) — `in 1/N` for N a multiple of 7 always selects a whole number of
// complete states.
void testBS090InRangeExpansion() {
  std::printf("[selftest] --- BS-090 `in` row-range expansion (BETA campaign Phase G) ---\n");
  namespace fs = std::filesystem;
  std::string base = (fs::temp_directory_path() / "piet_native_selftest_bs090").u8string();
  std::error_code ec;
  fs::remove_all(base, ec);
  fs::create_directories(base, ec);
  std::string wdA = base + "/a";
  std::string wdB = base + "/b";
  fs::create_directories(wdA, ec);
  fs::create_directories(wdB, ec);
  piet::SessionState sessA(wdA);  // runs the `in`-qualified command directly
  piet::SessionState sessB(wdB);  // runs `keep in a/b` then the plain command

  auto freshA = [&]() { (void)piet::dispatch("sysuse fatalities, clear", sessA); };
  auto freshBReduced = [&](const std::string& range) {
    (void)piet::dispatch("sysuse fatalities, clear", sessB);
    (void)piet::dispatch("keep in " + range, sessB);
  };
  auto findBlockOfType = [](const nlohmann::ordered_json& blocks,
                            const std::string& type) -> nlohmann::ordered_json {
    for (const auto& b : blocks) {
      if (b.is_object() && b.value("type", std::string()) == type) return b;
    }
    return nlohmann::ordered_json();
  };
  auto hasError = [](const nlohmann::ordered_json& blocks) {
    for (const auto& b : blocks) {
      if (b.is_object() && b.value("type", std::string()) == "error") return true;
    }
    return false;
  };

  // (a) summarize ... in a/b
  freshA();
  freshBReduced("1/5");
  {
    auto blocksA = piet::dispatch("summarize beertax in 1/5", sessA);
    auto blocksB = piet::dispatch("summarize beertax", sessB);
    check(!hasError(blocksA), "BS-090(a): `summarize beertax in 1/5` does not error");
    auto sumA = findBlockOfType(blocksA, "summarize");
    auto sumB = findBlockOfType(blocksB, "summarize");
    bool ok = !sumA.is_null() && !sumB.is_null() && sumA.contains("stats") &&
              sumA["stats"].contains("beertax") && sumB.contains("stats") &&
              sumB["stats"].contains("beertax");
    check(ok, "BS-090(a): both `summarize beertax in 1/5` and the keep-in-1/5-reduced copy "
              "return beertax stats");
    if (ok) {
      const auto& sa = sumA["stats"]["beertax"];
      const auto& sb = sumB["stats"]["beertax"];
      check(sa.value("N", -1.0) == 5.0, "BS-090(a): `in 1/5` restricts to exactly 5 observations");
      check(sa.value("N", -1.0) == sb.value("N", -2.0),
            "BS-090(a): N matches the independently keep-in-1/5-reduced copy");
      check(std::abs(sa.value("mean", 0.0) - sb.value("mean", 1.0)) < 1e-9,
            "BS-090(a): mean matches the independently keep-in-1/5-reduced copy");
    }
  }

  // (b) count ... in a/b (value-independent: `in 1/5` is always exactly 5
  // rows regardless of the composition mechanism).
  freshA();
  {
    auto blocksA = piet::dispatch("count in 1/5", sessA);
    check(!hasError(blocksA), "BS-090(b): `count in 1/5` does not error");
    auto dispBlock = findBlockOfType(blocksA, "display");
    check(!dispBlock.is_null() && dispBlock.value("text", std::string()) == "5",
          "BS-090(b): `count in 1/5` == 5");
  }

  // (c) drop/keep in a/b: `keep in 1/5` -> 5 rows left; `drop in 1/5` on a
  // FRESH copy -> 336-5=331 rows left (drop's `in` is the COMPLEMENT of the
  // range, matching runDropIf's pre-existing complement-of-if idiom).
  freshA();
  {
    auto blocksKeep = piet::dispatch("keep in 1/5", sessA);
    auto mutKeep = findBlockOfType(blocksKeep, "data_mutation");
    check(!mutKeep.is_null() && mutKeep.value("n_rows_after", -1) == 5,
          "BS-090(c): `keep in 1/5` leaves exactly 5 rows");
  }
  freshA();
  {
    auto blocksDrop = piet::dispatch("drop in 1/5", sessA);
    auto mutDrop = findBlockOfType(blocksDrop, "data_mutation");
    check(!mutDrop.is_null() && mutDrop.value("n_rows_after", -1) == 331,
          "BS-090(c): `drop in 1/5` leaves 336-5=331 rows (complement of the range)");
  }

  // (d) egen ... in a/b: computed ONLY over the in-sample, missing outside
  // it (same contract egen's pre-existing `if` support already has).
  freshA();
  {
    auto blocksEgen = piet::dispatch("egen gm5 = mean(beertax) in 1/5", sessA);
    check(!hasError(blocksEgen), "BS-090(d): `egen gm5 = mean(beertax) in 1/5` does not error");
    auto sumBlocks = piet::dispatch("summarize gm5", sessA);
    auto sumGm = findBlockOfType(sumBlocks, "summarize");
    bool ok = !sumGm.is_null() && sumGm.contains("stats") && sumGm["stats"].contains("gm5");
    check(ok && sumGm["stats"]["gm5"].value("N", -1.0) == 5.0,
          "BS-090(d): `egen gm5 = mean(beertax) in 1/5` has exactly 5 non-missing rows (the "
          "other 331 are missing, matching the if-merge-back contract)");
    if (ok) {
      double gmMean = sumGm["stats"]["gm5"].value("mean", 0.0);
      // Every in-sample row carries the SAME broadcast group value, so
      // gm5's own mean == mean(beertax) over the in-sample — cross-check
      // against the keep-in-1/5-reduced copy's plain summarize.
      freshBReduced("1/5");
      auto plainBlocks = piet::dispatch("summarize beertax", sessB);
      auto sumB = findBlockOfType(plainBlocks, "summarize");
      if (sumB.contains("stats") && sumB["stats"].contains("beertax")) {
        double refMean = sumB["stats"]["beertax"].value("mean", 1.0);
        check(std::abs(gmMean - refMean) < 1e-6,
              "BS-090(d): egen's in-sample mean matches the independently keep-in-1/5-reduced "
              "copy's plain summarize mean");
      }
    }
  }

  // (e) corr ... in a/b
  freshA();
  freshBReduced("1/10");
  {
    auto blocksA = piet::dispatch("corr beertax income in 1/10", sessA);
    auto blocksB = piet::dispatch("corr beertax income", sessB);
    check(!hasError(blocksA), "BS-090(e): `corr beertax income in 1/10` does not error");
    auto estA = findBlockOfType(blocksA, "estimation");
    auto estB = findBlockOfType(blocksB, "estimation");
    check(!estA.is_null() && !estB.is_null() && estA.value("n_obs", -1) == 10 &&
              estA.value("n_obs", -1) == estB.value("n_obs", -2),
          "BS-090(e): n_obs==10, matching the independently keep-in-1/10-reduced copy");
  }

  // (f) ttest ... in a/b
  freshA();
  freshBReduced("1/10");
  {
    auto blocksA = piet::dispatch("ttest beertax in 1/10", sessA);
    auto blocksB = piet::dispatch("ttest beertax", sessB);
    check(!hasError(blocksA), "BS-090(f): `ttest beertax in 1/10` does not error");
    auto estA = findBlockOfType(blocksA, "estimation");
    auto estB = findBlockOfType(blocksB, "estimation");
    check(!estA.is_null() && !estB.is_null() && estA.value("n_obs", -1) == 10 &&
              estA.value("n_obs", -1) == estB.value("n_obs", -2),
          "BS-090(f): n_obs==10, matching the independently keep-in-1/10-reduced copy");
  }

  // (g) regress/feols ... in a/b
  freshA();
  freshBReduced("1/20");
  {
    auto blocksA = piet::dispatch("regress income beertax in 1/20", sessA);
    auto blocksB = piet::dispatch("regress income beertax", sessB);
    check(!hasError(blocksA), "BS-090(g): `regress income beertax in 1/20` does not error");
    auto estA = findBlockOfType(blocksA, "estimation");
    auto estB = findBlockOfType(blocksB, "estimation");
    check(!estA.is_null() && !estB.is_null() && estA.value("n_obs", -1) == 20 &&
              estA.value("n_obs", -1) == estB.value("n_obs", -2),
          "BS-090(g): n_obs==20, matching the independently keep-in-1/20-reduced copy");
    if (!estA.is_null() && !estB.is_null()) {
      double bA = -1.0, bB = -2.0;
      bool foundA = false, foundB = false;
      for (const auto& row : estA.value("coeftable", nlohmann::ordered_json::array())) {
        if (row.value("name", std::string()) == "beertax") { bA = row.value("b", -1.0); foundA = true; }
      }
      for (const auto& row : estB.value("coeftable", nlohmann::ordered_json::array())) {
        if (row.value("name", std::string()) == "beertax") { bB = row.value("b", -2.0); foundB = true; }
      }
      check(foundA && foundB && std::abs(bA - bB) < 1e-6,
            "BS-090(g): the `beertax` coeftable row's `b` matches the independently "
            "keep-in-1/20-reduced copy");
    }
  }

  // (h) tabulate ... in a/b (2 full states' worth of the state-blocked
  // fixture — 14 rows, 2 distinct `state` values).
  freshA();
  freshBReduced("1/14");
  {
    auto blocksA = piet::dispatch("tabulate state in 1/14", sessA);
    auto blocksB = piet::dispatch("tabulate state", sessB);
    check(!hasError(blocksA), "BS-090(h): `tabulate state in 1/14` does not error");
    auto tabA = findBlockOfType(blocksA, "tabulate");
    auto tabB = findBlockOfType(blocksB, "tabulate");
    check(!tabA.is_null() && !tabB.is_null() && tabA == tabB,
          "BS-090(h): `tabulate state in 1/14` byte-matches the independently "
          "keep-in-1/14-reduced copy's plain `tabulate state`");
  }

  // (i) duplicates report ... in a/b (same 14-row, 2-state slice: `year`
  // has each of 7 distinct values appearing exactly twice -> 7 duplicate
  // groups).
  freshA();
  freshBReduced("1/14");
  {
    auto blocksA = piet::dispatch("duplicates report year in 1/14", sessA);
    auto blocksB = piet::dispatch("duplicates report year", sessB);
    check(!hasError(blocksA), "BS-090(i): `duplicates report year in 1/14` does not error");
    auto dA = findBlockOfType(blocksA, "display");
    auto dB = findBlockOfType(blocksB, "display");
    check(!dA.is_null() && !dB.is_null() &&
              dA.value("text", std::string()) == dB.value("text", std::string()),
          "BS-090(i): `duplicates report year in 1/14` byte-matches the independently "
          "keep-in-1/14-reduced copy's plain `duplicates report year`");
  }

  // (j) duplicates drop ... in a/b — honest reject, same disclosed boundary
  // as its pre-existing `if` reject (dedup-then-splice-back needs more than
  // a simple filter). `force' is spelled: without it duplicates refuses a
  // varlist drop first (r(198); w2ah_data_verbs.log
  // ah_dup_drop_noforce), so the `in' refusal is only reachable with it.
  freshA();
  {
    auto blocksA = piet::dispatch("duplicates drop year in 1/14, force", sessA);
    auto errA = findBlockOfType(blocksA, "error");
    check(!errA.is_null(), "BS-090(j): `duplicates drop year in 1/14, force` still honestly rejects "
                           "(same disclosed boundary as its pre-existing `if` reject)");
    check(errA.value("message", std::string()).find("with `in`") != std::string::npos,
          "BS-090(j): reject message names the `in` qualifier specifically — got: " +
              errA.value("message", std::string()));
  }

  // (k) collapse ... in a/b, by(state) — 2-state slice collapses to
  // exactly 2 rows.
  freshA();
  freshBReduced("1/14");
  {
    auto blocksA = piet::dispatch("collapse (mean) beertax in 1/14, by(state)", sessA);
    auto blocksB = piet::dispatch("collapse (mean) beertax, by(state)", sessB);
    check(!hasError(blocksA), "BS-090(k): `collapse (mean) beertax in 1/14, by(state)` does not "
                              "error");
    auto mutA = findBlockOfType(blocksA, "data_mutation");
    auto mutB = findBlockOfType(blocksB, "data_mutation");
    check(!mutA.is_null() && mutA.value("n_rows_after", -1) == 2 &&
              mutA.value("n_rows_after", -1) == mutB.value("n_rows_after", -2),
          "BS-090(k): collapsing the in-1/14 sample by state gives exactly 2 rows, matching the "
          "independently keep-in-1/14-reduced copy");
  }

  fs::remove_all(base, ec);
}

// BETA campaign Phase G (BS-092): `by:`/`bysort: summarize` real per-group
// dispatch (dispatcher.cpp's by/bysort interception block) — the ONE OTHER
// subcommand besides gen/replace/egen with a genuine PIET-side by-group
// implementation this phase. Cross-checks each group's own stats against a
// bare `summarize X if G==val` for that SAME group value (the task brief's
// own suggested verification), on a small, deterministic 2-group fixture
// (the bundled fatalities panel's first 14 rows — exactly 2 states' worth,
// 7 years each, per the CSV's own state-blocked appearance order).
void testBS092BysortSummarize() {
  std::printf("[selftest] --- BS-092 `by:`/`bysort: summarize` grouped dispatch (BETA campaign "
              "Phase G) ---\n");
  namespace fs = std::filesystem;
  std::string workdir = (fs::temp_directory_path() / "piet_native_selftest_bs092").u8string();
  std::error_code ec;
  fs::remove_all(workdir, ec);
  fs::create_directories(workdir, ec);
  piet::SessionState session(workdir);

  (void)piet::dispatch("sysuse fatalities, clear", session);
  // Exactly 2 states' worth (BS-090(c)/(k) already cover `keep in`'s own
  // correctness — used here purely as fixture setup for a small, fast,
  // deterministic 2-group dataset).
  (void)piet::dispatch("keep in 1/14", session);

  piet::Datastore* ds = session.datastore();
  bool haveFixture = ds != nullptr && ds->nRows() == 14 && ds->has("state") && ds->has("beertax");
  check(haveFixture, "BS-092 setup: 14-row, 2-state fixture loaded");
  if (!haveFixture) {
    fs::remove_all(workdir, ec);
    return;
  }

  // The two distinct `state` levels actually present, read directly off the
  // factor column (rather than assumed) so this doesn't hardcode which
  // postal codes the bundled CSV happens to use.
  std::string state1, state2;
  {
    const auto& levels = ds->varinfo("state").levels;
    const int32_t* codes = ds->col("state").codes();
    check(levels.size() >= 2, "BS-092 setup: at least 2 distinct `state` levels present");
    if (levels.size() >= 2 && codes[0] >= 0 && codes[13] >= 0) {
      state1 = levels[static_cast<size_t>(codes[0])];
      state2 = levels[static_cast<size_t>(codes[13])];
      check(state1 != state2, "BS-092 setup: row 1 and row 14 are DIFFERENT states");
    }
  }

  auto blocks = piet::dispatch("bysort state: summarize beertax", session);
  bool sawError = false;
  for (const auto& b : blocks) {
    if (b.is_object() && b.value("type", std::string()) == "error") sawError = true;
  }
  check(!sawError, "BS-092: `bysort state: summarize beertax` does not error (was an honest "
                   "reject before this phase)");

  // Collect the (display header, summarize block) pairs in emission order.
  std::vector<std::pair<std::string, nlohmann::ordered_json>> groups;
  {
    std::string pendingHeader;
    for (const auto& b : blocks) {
      if (!b.is_object()) continue;
      if (b.value("type", std::string()) == "display") {
        pendingHeader = b.value("text", std::string());
      } else if (b.value("type", std::string()) == "summarize") {
        groups.emplace_back(pendingHeader, b);
      }
    }
  }
  check(groups.size() == 2,
        "BS-092: exactly 2 group blocks emitted (one per distinct `state` value) — got " +
            std::to_string(groups.size()));
  if (groups.size() == 2 && !state1.empty() && !state2.empty()) {
    check(groups[0].first == "-> state = " + state1,
          "BS-092: first group's header is `-> state = " + state1 + "` — got `" +
              groups[0].first + "`");
    check(groups[1].first == "-> state = " + state2,
          "BS-092: second group's header is `-> state = " + state2 + "` — got `" +
              groups[1].first + "`");

    for (size_t gi = 0; gi < 2; ++gi) {
      const std::string& sval = (gi == 0) ? state1 : state2;
      const auto& grpBlock = groups[gi].second;
      bool haveStats = grpBlock.contains("stats") && grpBlock["stats"].contains("beertax");
      check(haveStats,
            "BS-092: group " + std::to_string(gi) + "'s summarize block has beertax stats");
      if (!haveStats) continue;
      const auto& grpStats = grpBlock["stats"]["beertax"];

      // Cross-check against a bare `summarize beertax if state=="VAL"` for
      // this SAME group value.
      auto refBlocks = piet::dispatch("summarize beertax if state==\"" + sval + "\"", session);
      nlohmann::ordered_json refSum;
      for (const auto& b : refBlocks) {
        if (b.is_object() && b.value("type", std::string()) == "summarize") refSum = b;
      }
      bool refOk = refSum.is_object() && refSum.contains("stats") &&
                   refSum["stats"].contains("beertax");
      check(refOk, "BS-092: `summarize beertax if state==\"" + sval + "\"` cross-check succeeds");
      if (!refOk) continue;
      const auto& refStats = refSum["stats"]["beertax"];
      check(grpStats.value("N", -1.0) == refStats.value("N", -2.0),
            "BS-092: group " + std::to_string(gi) + "'s N matches `summarize ... if state==\"" +
                sval + "\"` (N=" + std::to_string(grpStats.value("N", -1.0)) + ")");
      check(std::abs(grpStats.value("mean", 0.0) - refStats.value("mean", 1.0)) < 1e-9,
            "BS-092: group " + std::to_string(gi) + "'s mean matches the if-restricted "
            "cross-check");
      check(std::abs(grpStats.value("sd", 0.0) - refStats.value("sd", 1.0)) < 1e-9,
            "BS-092: group " + std::to_string(gi) + "'s sd matches the if-restricted cross-check");
    }
  }

  // `count` graduated out of the BS-107 bucket (FU-163): under by it runs per group.
  {
    auto rejBlocks = piet::dispatch("bysort state: count", session);
    bool sawReject = false;
    for (const auto& b : rejBlocks)
      if (b.is_object() && b.value("type", std::string()) == "error") sawReject = true;
    check(!sawReject, "BS-092: `bysort: count` runs per group (FU-163, graduated out of BS-107)");
  }

  fs::remove_all(workdir, ec);
}

// BETA campaign Phase G, SCOPE.md regression-lock rows (test-only —
// verified-correct-today behavior, no functional code change): BS-060/
// BS-061/BS-062/BS-088/BS-094. Each row was independently re-verified
// against this session's actual source (not assumed from SCOPE.md's own
// "already shipped" claim) before writing its lock leg — see the task's own
